    // ---- My Grinds: reusable setup metadata, never financial truth --------------------------
    /** Reusable My Grind definitions; setup and default targets only. */
    List<SavedGrind> savedGrinds = new ArrayList<>();

    /** All My Grinds; archived ones only when asked for. */
    synchronized List<SavedGrind> getSavedGrinds(boolean includeArchived) {
        var result = new ArrayList<SavedGrind>();
        for (SavedGrind grind : savedGrinds) {
            if (!grind.archived || includeArchived) result.add(grind);
        }
        return result;
    }

    /** Saved-Grind lookup by stable id; null when unknown. */
    synchronized SavedGrind savedGrind(String grindId) {
        for (SavedGrind grind : savedGrinds) {
            if (grind.getGrindId().equals(grindId)) return grind;
        }
        return null;
    }

    /** Creates a reusable My Grind from reusable setup only; runs link to it as they start. */
    synchronized SavedGrind saveGrind(String name, Long netTargetGp, Long activeTimeMillis, boolean favorite) {
        String cleanName = nonBlank(name, "");
        if (cleanName.isEmpty()) return null;
        var grind = new SavedGrind(UUID.randomUUID().toString(), cleanName, netTargetGp, activeTimeMillis, favorite);
        savedGrinds.add(grind);
        return grind;
    }

    /**
     * Edits a My Grind. Finished runs keep the targets they ran with; a running run of this Grind
     * takes the new name and any changed target at once (owner 1.5.0: one Grind, one setup).
     */
    synchronized boolean updateSavedGrind(String grindId, String name, Long netTargetGp, Long activeTimeMillis,
            boolean favorite) {
        SavedGrind grind = savedGrind(grindId);
        if (grind == null) return false;
        String cleanName = nonBlank(name, "");
        // Only a changed target reaches the run: a rename or a favourite never re-arms its aim.
        boolean retarget = !Objects.equals(netTargetGp, grind.netTargetGp)
                        || !Objects.equals(activeTimeMillis, grind.activeTimeTargetMillis);
        if (!cleanName.isEmpty()) grind.setName(cleanName);
        grind.setNetTargetGp(netTargetGp);
        grind.setActiveTimeTargetMillis(activeTimeMillis);
        grind.setFavorite(favorite);
        Session run = customSession;
        if (run != null && grindId.equals(run.getGrindId())) {
            if (!cleanName.isEmpty()) renameActive(cleanName);
            if (retarget) setTargets(netTargetGp, activeTimeMillis, SafeMath.now());
        }
        return true;
    }

    /** The My Grind with this name, ignoring case; null when there is none. */
    synchronized SavedGrind grindNamed(String name) {
        for (SavedGrind grind : savedGrinds) {
            if (grind.getName().equalsIgnoreCase(nonBlank(name, "").trim())) return grind;
        }
        return null;
    }

    synchronized boolean archiveGrind(String grindId, boolean archived) {
        SavedGrind grind = savedGrind(grindId);
        if (grind == null) return false;
        grind.setArchived(archived);
        return true;
    }

    /** Removes the reusable definition only; canonical history and lineage links survive. */
    synchronized boolean deleteSavedGrind(String grindId) {
        SavedGrind grind = savedGrind(grindId);
        if (grind == null) return false;
        savedGrinds.remove(grind);
        return true;
    }

    /** Stable-id lineage members, newest first. Never display-name matching. */
    synchronized List<Session> linkedSessions(String grindId) {
        var result = new ArrayList<Session>();
        if (empty(grindId)) return result;
        Session active = activeSession;
        if (active != null && grindId.equals(active.getGrindId())) result.add(active);
        for (Session session : history) {
            if (session != null && grindId.equals(session.getGrindId())) result.add(session);
        }
        return result;
    }

    /** Stable-id lineage members among completed instances only, newest first. */
    synchronized List<Session> completedLinked(String grindId) {
        var result = new ArrayList<Session>();
        for (Session session : linkedSessions(grindId)) {
            if (session != null && session.isClosed()) result.add(session);
        }
        return result;
    }

    /**
     * Starts one fresh canonical Grind. Every Grind is remembered (owner 1.5.0): the run links to
     * its My Grind, found by id, else by name, else created, and the targets it starts with become
     * that Grind's targets. No financial state, loot, active time or correction state is copied.
     */
    synchronized boolean startGrind(
            String name, String grindId, Long netTargetGp, Long activeTimeTargetMillis, long now) {
        String cleanName = nonBlank(name, "");
        if (cleanName.isEmpty() || customSession != null) return false;
        SavedGrind grind = savedGrind(grindId);
        if (grind == null) grind = grindNamed(cleanName);
        if (grind == null) grind = saveGrind(cleanName, null, null, false);
        grind.setArchived(false);
        grind.setNetTargetGp(netTargetGp);
        grind.setActiveTimeTargetMillis(activeTimeTargetMillis);
        startCustom(grind.getName(), now);
        Session active = activeSession;
        if (active == null) return false;
        active.setGrindId(grind.getGrindId());
        active.setProfitTargetGp(netTargetGp);
        active.setActiveTimeTargetMillis(activeTimeTargetMillis, now);
        return true;
    }

    /**
     * Renames the running Grind; a change like any other, so the revision advances and it is saved.
     */
    synchronized void renameActive(String name) {
        if (activeSession != null) {
            activeSession.rename(name);
            bumpRevision();
        }
    }

    /** Mid-Grind aim edit: changes the current target snapshot only, never financial truth. */
    synchronized boolean setTargets(Long netTargetGp, Long activeTimeTargetMillis, long now) {
        if (activeSession == null) return false;
        boolean net = activeSession.setProfitTargetGp(netTargetGp == null || netTargetGp <= 0L ? null : netTargetGp,
                        getMetrics(now).net, activeSession.getElapsedMillis(now));
        boolean time = activeSession.setActiveTimeTargetMillis(
                        activeTimeTargetMillis == null || activeTimeTargetMillis <= 0L ? null : activeTimeTargetMillis,
                        now);
        // A new or changed target starts a session; re-saving one keeps its count, and Done or
        // Clear leaves the session counting (owner 1.5.2).
        if ((net || time) && (activeSession.getProfitTargetGp() != null
                        || activeSession.getActiveTimeTargetMillis() != null)) newLiveSession(now);
        return true;
    }

    /**
     * The Targets sheet's save: the run's targets change and, during a Grind, so do that Grind's,
     * so the next run starts with them (owner 1.5.0). Done clears the run's aim only.
     */
    synchronized boolean saveTargets(Long netTargetGp, Long activeTimeTargetMillis, long now) {
        if (!setTargets(netTargetGp, activeTimeTargetMillis, now)) return false;
        SavedGrind grind = customSession == null ? null : savedGrind(customSession.getGrindId());
        if (grind != null) {
            grind.setNetTargetGp(activeSession.getProfitTargetGp());
            grind.setActiveTimeTargetMillis(activeSession.getActiveTimeTargetMillis());
        }
        return true;
    }

    /** Again: a new session with the same target, in the same run (owner 1.5.2). */
    synchronized boolean restartTarget(long now) {
        if (activeSession == null || activeSession.getProfitTargetGp() == null
                        && activeSession.getActiveTimeTargetMillis() == null) return false;
        newLiveSession(now);
        return true;
    }

    /** Toggles the timer's own pause; the run keeps tracking (owner live 2026-10-14). */
    synchronized boolean toggleTimeTargetPause(long now) {
        if (activeSession == null || activeSession.getActiveTimeTargetMillis() == null) return false;
        return activeSession.pauseTimeTarget(now) || activeSession.resumeTimeTarget(now);
    }

    /** Every session the engine opens follows the detected activity (AUTO). */
    Session newSession(String name, long now, boolean grind) {
        var session = new Session(name, now, SessionMode.AUTO);
        session.grind = grind;
        attachListeners(session);
        bumpRevision();
        return session;
    }

    void attachListeners(Session session) {
        if (session != null) {
            session.setChangeListener(this::bumpRevision);
            session.ownedValueObserver = trackedBasis;
        }
    }

    void bumpRevision() {
        revision = revision == Long.MAX_VALUE ? 1L : revision + 1L;
    }

    static boolean validZone(String value) {
        if (blank(value)) return false;
        try {
            ZoneId.of(value);
            return true;
        } catch (RuntimeException ex) {
            return false;
        }
    }

    /**
     * Per-source evidence: a confirmed Eat/Drink/Bury/Cast action. Decays on its own TTL via {@link
     * Inbox} — independent of bank-open/close evidence, so a stale or active bank signal can never
     * suppress a confirmed consume. See {@code com.gpmanager.engine.evidence} for why evidence
     * lifetimes are tracked per-source rather than with one shared flag.
     */
    /**
     * One context claim on the next inventory change: what it is, why, which loot, which encounter.
     */
    static class Clue {
        Context context = GENERIC;
        String note = "";
        Map<Integer, Long> expectedLoot = emptyMap();
        String encounterId;

        /**
         * Bank/deposit evidence during this change; {@code hard} is a real container/menu movement.
         */
        boolean transfer;

        boolean hard;

        /** Soft evidence: the bank UI was open, but no deposit or withdrawal was confirmed. */
        boolean soft() {
            return transfer && !hard;
        }

        /** The claim gives way to ordinary classification; transfer evidence is kept. */
        void generic() {
            context = GENERIC;
            note = "";
            expectedLoot = emptyMap();
            encounterId = null;
        }

        void clear() {
            generic();
            transfer = false;
            hard = false;
        }

        /**
         * A higher-priority (or forced) claim replaces this one; the same context merges its
         * details.
         */
        void offer(Context claim, String claimNote, Map<Integer, Long> loot, String encounter, boolean replace) {
            if (replace || claim.priority > context.priority) {
                context = claim;
                note = orEmpty(claimNote);
                expectedLoot = positiveEntries(loot);
                encounterId = encounter;
            } else if (claim == context) {
                note = empty(claimNote) ? note : claimNote;
                if (claim == LOOT || claim == PK_LOOT) {
                    Map<Integer, Long> merged = positiveEntries(loot);
                    expectedLoot.forEach((itemId, quantity) -> merged.merge(itemId, quantity, SafeMath::safeAdd));
                    expectedLoot = merged;
                }
                encounterId = empty(encounter) ? encounterId : encounter;
            }
        }
    }
}

/** Source-backed quantities and their distinct source/encounter owners, in observation order. */
@AllArgsConstructor
class LootMatch {
    static final LootMatch NONE = new LootMatch(false, "", "General", Context.GENERIC, null,
                    Collections.<Integer, Long>emptyMap(), Collections.emptyList());
    boolean matched;
    String note;
    String activityName;
    Context context;
    String encounterId;
    Map<Integer, Long> matchedQuantities;
    List<LootMatch> sources;
}

@Singleton
class TransactionClassifier {
    TransactionType classify(Context context, List<Flow> flows) {
        if (context == Context.TRANSFER) return TransactionType.TRANSFER;
        boolean hasGain = false;
        boolean hasCost = false;
        for (Flow flow : flows) {
            // Direction comes from quantity. An unavailable unit price produces a
            // zero value, but it is still a real gain or cost that belongs in Review.
            hasGain |= flow.isGain();
            hasCost |= flow.isCost();
        }
        if (context == MARKET) return TRADE;
        if (context == Context.PK_LOOT && hasGain) return TransactionType.PK_LOOT;
        if (context == PK_DEATH && hasCost) return PK_DEATH_LOSS;
        if (context == Context.LOOT && hasGain) return TransactionType.LOOT;
        if (hasGain && hasCost) {
            return context == PRODUCTION ? PROCESSING : UNCERTAIN;
        }
        if (hasGain) return GAIN;
        if (hasCost) return CONSUMPTION;
        return ADJUSTMENT;
    }
}

/** Pending evidence inbox. FE fee, CH chest, TK ground click, BG bag gain, KT kit snapshot. */
/** DI dismantle click, GE collect interaction, TA fired-ammo pickup intent. */
/** DO drop click, DROPPED an own drop still on the ground, FA recoverable fired-ammo loss. */
/** CN a consume command, including its named inventory baseline and presentation hints. */
/** SC an earlier consume whose item already left the pack, displaced by a newer click. */
/** LT private loot (at bounds attribution); LP/RD quantities reserved by an own-pile despawn. */
/**
 * CL load target, CK exact Check link, RV uncharge return; command quantities never prove money.
 */
/** CX/CP live/stabilizing claims, CT attribution clock, SF/HF soft/hard transfer, BO bank UI. */
class Inbox {
    static final int FEE = 1, CHEST = 2, GROUND_CLICK = 3, BAG_GAIN = 4, KIT_SNAPSHOT = 5, DISMANTLE_CLICK = 6,
            GE_COLLECT = 7, DROP_CLICK = 9, DROPPED = 10, CONSUME = 12, PRIVATE_LOOT = 13, LOOT_RESERVE = 14,
            LOAD_TARGET = 16, CHECK_LINK = 17, UNCHARGE = 18, LIVE_CLAIM = 19, PENDING_CLAIM = 20, CLOCK = 21,
            SOFT_TRANSFER = 22, HARD_TRANSFER = 23, BANK_UI = 24, SERVANT = 25, SAWMILL = 26, DIALOGUE = 27,
            PIPE_PICKUP = 28, CANNON = 29, SPENT_CONSUME = 30;
    volatile long owner;

    /** Legacy lifecycle ephemera clear here; their durable state keeps its tested lifecycle. */
    Runnable reset = () -> {};

    int now;

    /** Proved context stays latched while its measured snapshot stabilizes, as in 1.2. */
    boolean hold;

    List<Observation> open = new ArrayList<>();

    synchronized Observation add(int kind, int item, long qty, int ticks, String note) {
        var e = new Observation();
        e.kind = kind;
        e.owner = owner;
        e.item = item;
        e.qty = qty;
        e.until = (int) Math.min(Integer.MAX_VALUE, (long) now + ticks);
        e.note = note;
        open.add(e);
        return e;
    }

    /** Replace a single observation, such as the latest click or chat confirmation. */
    synchronized Observation put(int kind, int item, long qty, int ticks, String note) {
        drop(kind);
        return add(kind, item, qty, ticks, note);
    }

    int item(int kind) {
        Observation e = peek(kind);
        return e == null ? -1 : e.item;
    }

    long at(int kind) {
        Observation e = peek(kind);
        return e == null ? 0L : e.at;
    }

    boolean has(int kind, int item) {
        return peek(kind, e -> e.item == item) != null;
    }

    Engine.Clue clue(int kind) {
        Observation e = peek(kind);
        if (e == null) {
            e = add(kind, -1, 1L, Integer.MAX_VALUE, null);
            e.data = new Engine.Clue();
        }
        return (Engine.Clue) e.data;
    }

    int left(int kind) {
        Observation e = peek(kind);
        return e == null ? 0 : e.until - now + 1;
    }

    void ttl(int kind, int ticks) {
        if (ticks <= 0) drop(kind);
        else put(kind, -1, 1L, ticks - 1, null);
    }

    synchronized Observation peek(int kind, Predicate<Observation> match) {
        for (Observation e : open) if (e.kind == kind && live(e) && match.test(e)) return e;
        return null;
    }

    Observation peek(int kind) {
        return peek(kind, e -> true);
    }

    /** Consume no more than the still-open proof, even when a caller retains a stale record. */
    synchronized long take(int kind, int item, long qty, Predicate<Observation> match) {
        long left = Math.max(0L, qty);
        for (Observation e : open) {
            if (e.kind != kind || e.item != item || !live(e) || !match.test(e)) continue;
            long used = Math.min(left, e.qty);
            e.qty -= used;
            left -= used;
            if (left == 0L) break;
        }
        open.removeIf(e -> !live(e));
        return Math.max(0L, qty) - left;
    }

    boolean live(Observation e) {
        return e.owner == owner && e.qty > 0L && now <= e.until;
    }

    /**
     * Reserve proven private quantity for the bag, retaining its original source for settlement.
     */
    synchronized long reserve(int kind, int item, long qty, int into) {
        long left = Math.max(0L, qty);
        for (Observation e : all(kind)) {
            if (e.item != item) continue;
            int index = open.indexOf(e);
            long used = take(kind, item, left, v -> v == e);
            if (used > 0L) {
                Observation part = add(into, item, used, e.until - now, e.note);
                part.data = e;
                open.remove(part);
                open.add(Math.min(index, open.size()), part);
            }
            left -= used;
            if (left == 0L) break;
        }
        return Math.max(0L, qty) - left;
    }

    synchronized List<Observation> all(int kind) {
        var found = new ArrayList<Observation>();
        for (Observation e : open) if (e.kind == kind && live(e)) found.add(e);
        return found;
    }

    void refresh(int kind, int ticks) {
        Observation e = peek(kind);
        if (e != null) e.until = Math.max(e.until, now + Math.max(1, ticks) - 1);
    }

    synchronized void drop(int... kinds) {
        for (int kind : kinds) open.removeIf(e -> e.kind == kind);
    }

    synchronized void tick(int tick) {
        if (hold)
            for (Observation e : open)
                if (e.kind >= CLOCK && e.kind <= HARD_TRANSFER && e.until < Integer.MAX_VALUE)
                    e.until += tick - now;
        now = tick;
        open.removeIf(e -> !live(e));
    }

    /**
     * Sole account boundary; called with Persistence's existing request generation, including A ->
     * B -> A.
     */
    void owner(long token) {
        synchronized (this) {
            owner = token;
            open.clear();
        }
        // Never take the engine monitor while holding the inbox monitor.
        reset.run();
    }
}

/** One owner-scoped observation. Quantity is spent once; until is an inclusive inbox tick. */
class Observation {
    int kind, item, x, y, until;
    long owner, qty;

    /** Source tick/time and inventory quantity at the observation. */
    long at, held;

    /** Receipt or physical target identity, independent of the human source label. */
    String id;

    String note;

    /** Typed source snapshot (kit contents); never persisted. */
    Object data;

    /** Consume command metadata: Destroy, verb, trusted spell label. */
    boolean flag;

    ActionKind action;
    ActionLabel label;

    /** Loot source context and activity; id is its encounter. */
    ChargeCheck.ChargedItem variant;

    Context context;
    String name;

    Observation source() {
        return data instanceof Observation ? ((Observation) data).source() : this;
    }
}

/** Null-tolerant, allocation-light predicates and projections over settled item flows. */
class FlowFilters {
    static final IntPredicate ANY = itemId -> true;

    /** Positive flows whose item matches. */
    static List<Flow> gains(List<Flow> flows, IntPredicate item) {
        var out = new ArrayList<Flow>();
        if (flows != null) {
            for (Flow flow : flows) {
                if (flow.quantityDelta > 0L && item.test(flow.itemId))
                    out.add(flow);
            }
        }
        return out;
    }

    /** Flows minus those whose item matches (positive-only when {@code gainsOnly}). */
    static List<Flow> without(List<Flow> flows, IntPredicate item, boolean gainsOnly) {
        if (flows == null) return Collections.emptyList();
        var out = new ArrayList<Flow>(flows.size());
        for (Flow flow : flows) {
            if (!item.test(flow.itemId) || (gainsOnly && flow.quantityDelta <= 0L))
                out.add(flow);
        }
        return out;
    }

    /** Positive entries of {@code quantities} whose item does not match. */
    static Map<Integer, Long> withoutItems(Map<Integer, Long> quantities, IntPredicate item) {
        var out = new HashMap<Integer, Long>();
        if (quantities != null) {
            for (Entry<Integer, Long> e : quantities.entrySet()) {
                if (e.getKey() != null && e.getValue() != null && e.getValue() > 0L && !item.test(e.getKey())) {
                    out.put(e.getKey(), e.getValue());
                }
            }
        }
        return out.isEmpty() ? Collections.emptyMap() : out;
    }

    /** Positive entries only (fresh mutable map; merges duplicates). */
    static Map<Integer, Long> positiveEntries(Map<Integer, Long> quantities) {
        var out = new HashMap<Integer, Long>();
        if (quantities != null) {
            for (Entry<Integer, Long> e : quantities.entrySet()) {
                if (e.getKey() != null && e.getValue() != null && e.getValue() > 0L) {
                    out.merge(e.getKey(), e.getValue(), SafeMath::safeAdd);
                }
            }
        }
        return out;
    }

    /**
     * The shared settle-later claim: offers each matching flow's magnitude to {@code claimer},
     * which returns how much its lifecycle takes, leaves only the unclaimed rest in {@code flows}
     * and returns the claimed parts.
     */
    static List<Flow> claim(List<Flow> flows, Predicate<Flow> which, ToLongBiFunction<Flow, Long> claimer) {
        var parts = new ArrayList<Flow>();
        for (int index = 0; index < flows.size(); index++) {
            Flow flow = flows.get(index);
            if (flow.quantityDelta == Long.MIN_VALUE || !which.test(flow)) continue;
            long taken = claimer.applyAsLong(flow, SafeMath.abs(flow.quantityDelta));
            if (taken > 0L) parts.add(flow.part(taken));
            Flow rest = flow.rest(taken);
            if (rest == null) flows.remove(index--);
            else flows.set(index, rest);
        }
        return parts;
    }

    /** Positive remainders of {@code a} minus {@code b}: what left between two observations. */
    static Map<Integer, Long> minus(Map<Integer, Long> base, Map<Integer, Long> subtract) {
        var out = new LinkedHashMap<Integer, Long>();
        if (base != null) {
            for (Entry<Integer, Long> e : base.entrySet()) {
                Long less = subtract == null ? null : subtract.get(e.getKey());
                long left = (e.getValue() == null ? 0L : e.getValue()) - (less == null ? 0L : nonNeg(less));
                if (e.getKey() != null && left > 0L) out.put(e.getKey(), left);
            }
        }
        return out;
    }

    /** True when every wanted quantity fits inside {@code available}. */
    static boolean covers(Map<Integer, Long> available, Map<Integer, Long> wanted) {
        if (empty(wanted) || empty(available)) return false;
        for (Entry<Integer, Long> e : wanted.entrySet()) {
            if (e.getKey() == null || e.getValue() == null || e.getValue() <= 0L
                    || available.getOrDefault(e.getKey(), 0L) < e.getValue()) {
                return false;
            }
        }
        return true;
    }

    /** Removes up to {@code max} of one item and returns the quantity taken. */
    static long take(Map<Integer, Long> quantities, int itemId, long max) {
        if (quantities == null || max <= 0L) return 0L;
        long held = quantities.getOrDefault(itemId, 0L);
        long taken = min(nonNeg(held), max);
        if (held - taken <= 0L) quantities.remove(itemId);
        else quantities.put(itemId, held - taken);
        return taken;
    }

    /** Summed positive quantities per matching item. */
    static Map<Integer, Long> gainQuantities(List<Flow> flows, IntPredicate item) {
        return quantities(flows, item, true);
    }

    /** Summed magnitudes of negative deltas per matching item. */
    static Map<Integer, Long> lossQuantities(List<Flow> flows, IntPredicate item) {
        return quantities(flows, item, false);
    }

    static Map<Integer, Long> quantities(List<Flow> flows, IntPredicate item, boolean gains) {
        var out = new HashMap<Integer, Long>();
        if (flows != null) {
            for (Flow flow : flows) {
                if (!item.test(flow.itemId)) continue;
                long delta = flow.quantityDelta;
                if (gains ? delta > 0L : delta < 0L) {
                    long magnitude = SafeMath.abs(delta);
                    out.merge(flow.itemId, magnitude, SafeMath::safeAdd);
                }
            }
        }
        return out;
    }

    /**
     * Removes same-variant charge-state swaps (full -> partial -> uncharged): one physical weapon
     * changing item id is neither a gain nor a loss. A 1:1 proxy pair (X and X(i)/(ei)/(ri)) is the
     * same item changing state too, so an imbue never books a loss and a gain (owner 2026-10-12).
     * Leftover flows keep their own rows.
     */
    static List<Flow> withoutSwaps(List<Flow> flows) {
        boolean[] dropped = new boolean[flows.size()];
        for (int i = 0; i < flows.size(); i++) {
            Flow cost = flows.get(i);
            if (cost == null || cost.quantityDelta >= 0L) continue;
            ChargeCheck.ChargedItem variant = ChargeCheck.supportedForId(cost.itemId);
            for (int j = 0; j < flows.size(); j++) {
                Flow gain = flows.get(j);
                if (dropped[j] || gain == null || gain.quantityDelta <= 0L || gain.itemId == cost.itemId
                        || abs(gain.quantityDelta) != abs(cost.quantityDelta)) {
                    continue;
                }
                if (variant != null && ChargeCheck.supportedForId(gain.itemId) == variant
                        || reducedBase(cost.itemId) == reducedBase(gain.itemId)) {
                    dropped[i] = true;
                    dropped[j] = true;
                    break;
                }
            }
        }
        var result = new ArrayList<Flow>();
        for (int i = 0; i < flows.size(); i++) {
            if (!dropped[i]) result.add(flows.get(i));
        }
        return result;
    }

    /** The item's 1:1 proxy base (an imbued variant reduces to its plain item), else itself. */
    static int reducedBase(int itemId) {
        int[] proxy = CurrencyProxyCatalogue.proxyOf(itemId);
        return proxy != null && proxy[1] == 1 ? proxy[0] : itemId;
    }

    static boolean hasLoss(List<Flow> flows) {
        return hasLoss(flows, ANY);
    }

    static boolean hasLoss(List<Flow> flows, IntPredicate item) {
        if (flows != null) {
            for (Flow flow : flows) {
                if (flow.quantityDelta < 0L && item.test(flow.itemId)) return true;
            }
        }
        return false;
    }

    /** True when every non-null flow is on one side and at least one is non-zero. */
    static boolean onlyGains(List<Flow> flows) {
        return oneSided(flows, true);
    }

    static boolean onlyCosts(List<Flow> flows) {
        return oneSided(flows, false);
    }

    static boolean oneSided(List<Flow> flows, boolean gains) {
        if (empty(flows)) return false;
        boolean saw = false;
        for (Flow flow : flows) {
            long delta = flow.quantityDelta;
            if (gains ? delta < 0L : delta > 0L) return false;
            saw |= delta != 0L;
        }
        return saw;
    }
}

/**
 * PvM death → reclaim lifecycle. A separate held-stack snapshot is intersected with measured
 * negative inventory flows to establish which items actually left the player. Those exact
 * quantities remain ownership-neutral until reclaimed or the gravestone timer expires.
 *
 * <p>Fees are never inferred here; the engine can book only an observed carried-coin loss. A timer
 * expiry records an informational audit event and never creates an item loss.
 *
 * <p>Pure tick-counted state; the engine owns the single instance.
 */
class DeathReclaimLifecycle {
    /** Ticks a gravestone retains items. */
    static final int AWAIT_TICKS = 1_500; // 15 minutes

    /** Keep a grave interaction armed through the usual open/confirm/claim sequence. */
    static final int MIN_RECLAIM_ARM_TICKS = 200; // 2 minutes

    /** Bound delayed death-wipe reconciliation so later ordinary losses cannot match it. */
    static final int DEATH_WIPE_WINDOW_TICKS = 100; // 1 minute

    @Getter(AccessLevel.PACKAGE)
    boolean awaitingReclaim;

    int deathWipeTicks;
    int ageTicks;
    int reclaimTicks;
    BossRetrievalCatalogue.Service reclaimService;

    /** Stacks held at death not yet matched to a measured loss; null when no wipe is pending. */
    Map<Integer, Long> carriedAtDeath;

    /** Measured grave contents still outstanding, with the names used by the expiry note. */
    Map<Integer, Long> deathItems = new HashMap<>();

    Map<Integer, String> names = new HashMap<>();

    /** Local unsafe PvM death: the snapshot is ownership evidence, not presentation evidence. */
    void onPvmDeath(Map<Integer, Long> heldItems) {
        // A second death moves outstanding items to the new gravestone. Keep their
        // quantities and restart the single gravestone timer with the new grave.
        if (!awaitingReclaim) deathItems.clear();
        awaitingReclaim = true;
        // Missing canonical evidence is not permission to neutralize arbitrary losses.
        Map<Integer, Long> held = positiveEntries(heldItems);
        carriedAtDeath = held.isEmpty() ? null : held;
        deathWipeTicks = carriedAtDeath == null ? 0 : DEATH_WIPE_WINDOW_TICKS;
        ageTicks = 0;
        reclaimTicks = 0;
        reclaimService = null;
        completeIfEmpty();
    }

    /** True while waiting for the measured death inventory/equipment removal. */
    boolean wipePending() {
        return awaitingReclaim && carriedAtDeath != null;
    }

    /** Stop the short death-wipe whitelist when stronger later evidence owns the loss. */
    void cancelDeathWipe() {
        carriedAtDeath = null;
        deathWipeTicks = 0;
        completeIfEmpty();
    }

    /** Consume death-time candidates whose later loss is explicitly action-attributed. */
    void excludeActionLosses(Map<Integer, Long> actionLosses) {
        if (carriedAtDeath == null || Phrases.empty(actionLosses)) return;
        positiveEntries(actionLosses).forEach((itemId, lost) -> take(carriedAtDeath, itemId, lost));
        endWipeIfSpent();
    }

    /**
     * Intersect a settled negative-flow batch with the stacks held at death. The returned
     * quantities identify the exact negative flow portions that may be labelled as the
     * ownership-neutral death transfer.
     */
    Map<Integer, Long> onDeathItemsRemoved(List<Flow> flows) {
        if (!wipePending()) return emptyMap();
        var removed = new HashMap<Integer, Long>();
        for (Flow flow : flows == null ? Collections.<Flow>emptyList() : flows) {
            if (flow.quantityDelta >= 0L || flow.quantityDelta == Long.MIN_VALUE
                    // A live retrieval interaction makes measured coin loss a possible
                    // fee; do not consume it as a delayed death wipe.
                    || flow.itemId == ItemID.COINS && isReclaimArmed()) {
                continue;
            }
            long matched = take(carriedAtDeath, flow.itemId, -flow.quantityDelta);
            if (matched <= 0L) continue;
            removed.put(flow.itemId, matched);
            // Coins can be part of the measured death wipe transfer, but they are
            // never reclaim whitelist items: a later coin loss may be the observed fee.
            if (flow.itemId != ItemID.COINS) {
                deathItems.merge(flow.itemId, matched, SafeMath::safeAdd);
                if (flow.itemName != null && !flow.itemName.trim().isEmpty())
                    names.put(flow.itemId, flow.itemName.trim());
            }
        }
        endWipeIfSpent();
        return removed.isEmpty() ? emptyMap() : unmodifiableMap(removed);
    }

    /**
     * Match a positive return against the still-outstanding measured death quantity. Returns zero
     * when the item was not part of the actual settled death wipe.
     */
    long matchReturnedItem(int itemId, long quantity) {
        long matched = take(deathItems, itemId, quantity);
        if (matched > 0L && deathItems.isEmpty()) {
            // All measured grave contents have returned. Remaining stacks from the
            // death-time snapshot were kept and can no longer be a delayed wipe.
            cancelDeathWipe();
        }
        return matched;
    }

    long outstandingItemCount() {
        long count = 0L;
        for (long quantity : deathItems.values()) count = SafeMath.safeAdd(count, quantity);
        return count;
    }

    int ageTicks() {
        return ageTicks;
    }

    /**
     * Player interacted with a retrieval service. A fresh Grave / Gravestone click can always
     * re-arm while this local death remains active.
     *
     * @return true only when a local PvM death is awaiting reclaim
     */
    boolean noteReclaimIntent(BossRetrievalCatalogue.Service service, int ticks) {
        if (service == null || !awaitingReclaim && deathItems.isEmpty()) return false;
        reclaimService = service;
        reclaimTicks = Math.max(MIN_RECLAIM_ARM_TICKS, ticks);
        return true;
    }

    boolean isReclaimArmed() {
        return reclaimTicks > 0 && reclaimService != null;
    }

    /** One inventory/game tick; defers gravestone expiry while a snapshot is unsettled. */
    String tick(boolean deferGravestoneExpiry) {
        if (awaitingReclaim && ageTicks < Integer.MAX_VALUE) ageTicks++;
        if (reclaimTicks > 0 && --reclaimTicks == 0) reclaimService = null;
        if (deathWipeTicks > 0 && --deathWipeTicks == 0) cancelDeathWipe();
        if (deferGravestoneExpiry || !awaitingReclaim || ageTicks < AWAIT_TICKS) return null;
        String expired = deathItems.isEmpty() ? null : expiredItems();
        // Expired grave items wait at Death's Office for good: still yours, so they stay
        // outstanding
        // and match only while a retrieval is armed (review 2026-10-09).
        awaitingReclaim = false;
        cancelDeathWipe();
        return expired;
    }

    /** The expiry audit explanation: the outstanding items, sorted by name. */
    String expiredItems() {
        var labels = new ArrayList<String>();
        deathItems.forEach((itemId, quantity) -> {
                    String name = names.getOrDefault(itemId, "item #" + itemId);
                    labels.add(quantity == 1L ? name : name + " ×" + String.format(Locale.ROOT, "%,d", quantity));
                });
        labels.sort(String.CASE_INSENSITIVE_ORDER);
        return msg("gravestone-timer") + outstandingItemCount() + msg("item-s") + String.join(", ", labels)
                + msg("item-loss");
    }

    void reset() {
        awaitingReclaim = false;
        deathWipeTicks = 0;
        ageTicks = 0;
        reclaimTicks = 0;
        reclaimService = null;
        carriedAtDeath = null;
        deathItems.clear();
        names.clear();
    }

    /**
     * Persistable physical continuity for restart, or null when no death awaits reclaim. Item
     * identity and quantity only; the live reclaim interaction and presentation labels are
     * deliberately not persisted.
     */
    PendingDeath snapshot() {
        List<DeathItem> outstanding = items(deathItems);
        List<DeathItem> held = items(carriedAtDeath);
        return outstanding.isEmpty() && held.isEmpty() ? null
                : new PendingDeath(outstanding, held, deathWipeTicks, ageTicks);
    }

    static List<DeathItem> items(Map<Integer, Long> quantities) {
        var items = new ArrayList<DeathItem>();
        positiveEntries(quantities).forEach((itemId, quantity) -> items.add(new DeathItem(itemId, quantity)));
        return items;
    }

    /**
     * Restore persisted physical continuity after a restart. The reclaimed quantities are matched
     * exactly as before; the delayed-wipe window resumes its remaining bounded ticks and the
     * gravestone timer keeps its age. A live reclaim interaction is never restored.
     */
    void restore(PendingDeath pending) {
        reset();
        if (pending == null || pending.isEmpty()) return;
        for (DeathItem item : pending.getOutstandingItems()) {
            if (item.getQuantity() > 0L)
                deathItems.merge(item.itemId, item.getQuantity(), SafeMath::safeAdd);
        }
        var held = new HashMap<Integer, Long>();
        for (DeathItem item : pending.getHeldAtDeath()) {
            held.merge(item.itemId, item.getQuantity(), SafeMath::safeAdd);
        }
        deathWipeTicks = Math.min(DEATH_WIPE_WINDOW_TICKS, pending.getWipeTicksRemaining());
        carriedAtDeath = deathWipeTicks > 0 && !held.isEmpty() ? held : null;
        deathWipeTicks = carriedAtDeath == null ? 0 : deathWipeTicks;
        ageTicks = pending.getGravestoneAgeTicks();
        awaitingReclaim = carriedAtDeath != null || !deathItems.isEmpty() && ageTicks < AWAIT_TICKS;
    }

    /** Adopt the physical continuity of a staged engine during an owner install. */
    void adoptFrom(DeathReclaimLifecycle other) {
        reset();
        if (other == null) return;
        awaitingReclaim = other.awaitingReclaim;
        deathWipeTicks = other.deathWipeTicks;
        ageTicks = other.ageTicks;
        reclaimTicks = other.reclaimTicks;
        reclaimService = other.reclaimService;
        carriedAtDeath = other.carriedAtDeath == null ? null : new HashMap<>(other.carriedAtDeath);
        deathItems.putAll(other.deathItems);
        names.putAll(other.names);
    }

    void endWipeIfSpent() {
        if (carriedAtDeath != null && carriedAtDeath.isEmpty()) cancelDeathWipe();
        completeIfEmpty();
    }

    void completeIfEmpty() {
        if (awaitingReclaim && carriedAtDeath == null && deathItems.isEmpty()) reset();
    }
}

/**
 * Read-only state for the local PvM death-reclaim indicator. The item count is the sum of measured
 * outstanding stack quantities, and age is measured in active engine game ticks.
 */
class DeathReclaimStatus {
    boolean awaiting;
    boolean armed;
    long outstandingItemCount;
    long ageTicks;

    DeathReclaimStatus(boolean awaiting, boolean armed, long outstandingItemCount, long ageTicks) {
        this.awaiting = awaiting;
        this.armed = awaiting && armed;
        this.outstandingItemCount = nonNeg(outstandingItemCount);
        this.ageTicks = nonNeg(ageTicks);
    }
}

/**
 * Item Retrieval Services and their published flat fees. Source: OSRS Wiki "Item Retrieval Service"
 * (checked 2026-10-11). The fee here is an <em>expectation used for labelling</em>; the booked cost
 * is always the coins actually observed leaving the inventory in the reclaim window. Fees paid from
 * the bank or Death's Coffer are not observable and are never invented.
 */
class BossRetrievalCatalogue {
    /** Marker for services whose fee depends on the run (ToA scales with raid level). */
    static final long VARIABLE_FEE = -1L;

    /** Marker for tiered / percentage fees (gravestone, Death's Office) — see DeathReclaimFees. */
    static final long TIERED_FEE = -2L;

    @AllArgsConstructor
    static class Service {
        String key;
        String activity;
        String interactable;
        long expectedFee;
        String note;

        /**
         * Target name shared with unrelated scenery (a bare "Chest", a gravestone): only evidence
         * when a local PvM death is still awaiting reclaim.
         */
        boolean ambiguousTarget;

        /** Ledger explanation for an observed coin payment at this service. */
        String why(long observedCoins) {
            var why = new StringBuilder(msg("item-retrieval")).append(activity).append(" (").append(interactable)
                            .append(")");
            if (expectedFee > 0L) {
                why.append(", published ").append(String.format(ROOT, "%,d", expectedFee));
                if (observedCoins > 0L && observedCoins != expectedFee) {
                    why.append(", observed ").append(String.format(ROOT, "%,d", observedCoins));
                }
            } else if (expectedFee == VARIABLE_FEE) {
                why.append(", fee varies");
            }
            if (!note.isEmpty()) why.append(". ").append(note);
            return why.toString();
        }
    }

    static final Map<String, Service> BY_INTERACTABLE = new LinkedHashMap<>();

    static {
        for (String[] row : GameData.rows("retrieval_services")) {
            BY_INTERACTABLE.put(row[2].toLowerCase(ROOT), new Service(row[0], row[1], row[2], Long.parseLong(row[3]),
                            row[4], Boolean.parseBoolean(row[5])));
        }
    }

    /**
     * Service for a menu target (NPC or object name) when the option is a retrieval verb (see
     * {@link #isRetrievalOption}). Ambiguous targets ("Chest", "Gravestone", "Death") are returned
     * too; the engine only acts on them while a local PvM death awaits reclaim.
     */

    /** Menu verbs that open or complete a reclaim. */
    /** Existing reclaim vocabulary and grave prefix compiled once from d18. */
    static final java.util.regex.Pattern RECLAIM = GameData.pattern("reclaim");

    static final java.util.regex.Pattern GRAVE = GameData.pattern("grave");

    static Service serviceFor(String option, String target) {
        if (target == null || option == null || !RECLAIM.matcher(Phrases.lower(option)).matches()) {
            return null;
        }
        String lower = Phrases.lower(target);
        if (lower.isEmpty()) return null;
        Service exact = BY_INTERACTABLE.get(lower);
        if (exact != null) return exact;
        for (Map.Entry<String, Service> entry : BY_INTERACTABLE.entrySet()) {
            if (!entry.getValue().ambiguousTarget && lower.contains(entry.getKey()))
                return entry.getValue();
        }
        if (GRAVE.matcher(lower).matches()) return BY_INTERACTABLE.get("gravestone");
        return null;
    }
}

/**
 * Derives the observed {@link ActionKind} for a settled inventory change from positive evidence
 * only: a matched menu verb plus the settled flow shape. Never upgrades weak evidence into a
 * confident verb — a dose leftover without a matched Drink click is {@link ActionKind#SUPPLIES},
 * not {@link ActionKind#DRINK}.
 *
 * <p>Presentation evidence only. Accounting type, valuation and counted state are decided elsewhere
 * and never read this class.
 */
class ActionReader {
    static final Set<String> HERBLORE_INGREDIENTS = new HashSet<>(GameData.names("empty_vessels"));
    static final Pattern HERBLORE_INGREDIENT_SUFFIX = GameData.pattern("herblore-ingredient");
    static final Pattern DOSE_SUFFIX = GameData.pattern("dose-suffix");

    /** Ammunition names; tips, heads and shafts are fletching supplies, not ammunition. */
    static final Pattern AMMUNITION = GameData.pattern("ammunition");

    static final Pattern FLETCHING_PART = GameData.pattern("fletching-part");

    /** Menu verb prefixes (a leading "~" means "contains") and the action each evidences. */
    static final Object[] VERBS = GameData.rows("action_rules").stream().filter(a -> !a[2].isEmpty())
                    .flatMap(a -> java.util.stream.Stream.of(a[0], ActionKind.valueOf(a[2]))).toArray();

    /**
     * Final stamp for a booked change.
     *
     * @param matchedIntent the menu verb whose intent matched these flows, or null when the intent
     *     was absent, stale or matched nothing
     * @param flows settled flows of the transaction
     * @param type booked accounting type (unchanged by this call)
     * @param activityName booked activity name, used only to recognise Herblore production
     */
    static ActionKind resolve(ActionKind matchedIntent, List<Flow> flows, TransactionType type, String activityName) {
        if (Phrases.empty(flows)) return null;
        // A decant shape can also appear in a bank transfer or trade. Only the
        // otherwise-unclassified mixed inventory row is evidence of a player action.
        if (type == UNCERTAIN && isDecant(flows)) return DECANT;
        String activity = Phrases.lower(activityName);
        if (type == PROCESSING && activity.equals("herblore") && all(flows, -1, ActionReader::isIngredient)
                && all(flows, 1, name -> trailingDose(name) > 0)) {
            return MIX;
        }
        if (type == PROCESSING && activity.equals("cooking") && isCooking(flows)) {
            // Use the actual outcome: every output burnt → Burnt, otherwise Cooked.
            return all(flows, 1, name -> name.startsWith("burnt")) ? BURN : COOK;
        }
        // Rune/ammo spends are only recognised on cost-shaped rows: a bank deposit or
        // death loss of runes is a transfer/death, not casting.
        boolean spendShaped = type == CONSUMPTION || type == PK_SUPPLY_COST;
        boolean hasLoss = hasLoss(flows);
        boolean hasGain = !gains(flows, ANY).isEmpty();
        boolean lossOnly = hasLoss && !hasGain;
        if (spendShaped && lossOnly && all(flows, 0, ActionReader::isRune)) return ActionKind.CAST;
        if (spendShaped && lossOnly && all(flows, 0, ActionReader::isAmmo)) return FIRE;
        boolean doseStep = isDoseStep(flows);
        // Every loss must be one potion's doses (Drink) or one item (Eat/Bury/...): a coalesced
        // shark or bones under the same click is not "Drank", so it falls back to Supplies.
        boolean onePotion = oneLossFamily(flows, name -> trailingDose(name) > 0 ? doseBaseName(name) : null);
        boolean oneItem = oneLossFamily(flows, name -> name.isEmpty() ? null : name)
                        && all(flows, -1, name -> trailingDose(name) <= 0);
        if (matchedIntent != null && hasLoss) {
            switch (matchedIntent) {
                case DRINK:
                    return onePotion ? ActionKind.DRINK : ActionKind.SUPPLIES;
                case EAT:
                case BURY:
                case SCATTER:
                case OFFER:
                    return oneItem ? matchedIntent : ActionKind.SUPPLIES;
                case CAST:
                    // A Cast proves its spell by what it spent: runes, or a broken tablet (the
                    // spell in item form). An alch's coins or Bones to Peaches' fruit may come
                    // back with them (owner live 2026-10-16); a bank or trade move never casts.
                    return type != TransactionType.TRANSFER && type != TRADE && !all(flows, -1,
                                            name -> !isRune(name) && Spells.named(name) == null) ? ActionKind.CAST
                            : doseStep ? ActionKind.SUPPLIES : null;
                case SUPPLIES:
                    // This explicit intent currently comes from Light/Tend-to and the
                    // Tinderbox→fuel pair. Require the matching loss to be actual fuel.
                    return lossOnly && all(flows, 0, name -> name.matches(msg("logs-kindling"))) ? ActionKind.SUPPLIES
                            : null;
                default:
                    return matchedIntent;
            }
        }
        // Consumption is known from the leftover shape; the verb is not.
        return type == CONSUMPTION && doseStep ? ActionKind.SUPPLIES : null;
    }

    /**
     * Doses of one potion redistributed with no dose lost: e.g. −(3) −(1) +(4), or −(4) +(2) +(2).
     * Requires every flow to be a dosed form of the same base name.
     */
    static boolean isDecant(List<Flow> flows) {
        if (flows == null || flows.size() < 2) return false;
        String base = null;
        long doseBalance = 0L;
        boolean anyLoss = false;
        boolean anyGain = false;
        for (Flow flow : flows) {
            if (flow.quantityDelta == 0L) continue;
            String name = Phrases.lower(flow.itemName);
            int dose = trailingDose(name);
            // Combining doses frees a vessel; an emptied vial/jug gain is part of the shape.
            if (dose <= 0 && flow.quantityDelta > 0L && isVessel(name)) continue;
            String stem = doseBaseName(name);
            if (dose <= 0 || stem.isEmpty() || base != null && !base.equals(stem)) return false;
            base = stem;
            doseBalance += (long) dose * flow.quantityDelta;
            anyLoss |= flow.quantityDelta < 0L;
            anyGain |= flow.quantityDelta > 0L;
        }
        return anyLoss && anyGain && doseBalance == 0L;
    }

    /** A dose/food step confirms a consume even when its menu intent has expired. */
    static boolean isDoseStep(List<Flow> flows) {
        return !partialUses(flows).isEmpty();
    }

    /** Exact matched loss/remainder pairs for a recognized dose or partial-food consume. */
    static List<PartialUse> partialUses(List<Flow> flows) {
        if (flows == null || flows.size() < 2) return Collections.emptyList();
        var pairs = new ArrayList<PartialUse>();
        for (int lossIndex = 0; lossIndex < flows.size(); lossIndex++) {
            // A loss pairs only with the one remainder it could have become, and that remainder
            // only with this loss.
            List<Integer> gains = stepPartners(flows, flows.get(lossIndex), true);
            if (gains.size() == 1 && stepPartners(flows, flows.get(gains.get(0)), false).size() == 1) {
                pairs.add(new PartialUse(lossIndex, gains.get(0)));
            }
        }
        return Collections.unmodifiableList(pairs);
    }

    /**
     * Indexes of the flows a loss could step to ({@code toGains}), or the losses a gain could come
     * from.
     */
    static List<Integer> stepPartners(List<Flow> flows, Flow flow, boolean toGains) {
        var partners = new ArrayList<Integer>();
        Flow loss = toGains ? flow : null;
        Flow gain = toGains ? null : flow;
        if (flow == null || (toGains ? flow.quantityDelta >= 0L || flow.quantityDelta == Long.MIN_VALUE
                        : flow.quantityDelta <= 0L)) {
            return partners;
        }
        for (int index = 0; index < flows.size(); index++) {
            Flow other = flows.get(index);
            Flow lost = toGains ? loss : other;
            Flow gained = toGains ? other : gain;
            if (lost != null && gained != null && lost.quantityDelta < 0L && lost.quantityDelta != Long.MIN_VALUE
                    && gained.quantityDelta > 0L && -lost.quantityDelta == gained.quantityDelta
                    && isConsumeStep(lost.itemName, gained.itemName)) {
                partners.add(index);
            }
        }
        return partners;
    }

    @AllArgsConstructor
    static class PartialUse {
        int lossIndex;
        int remainderIndex;
    }

    static boolean addDoseLosses(Map<Integer, Long> target, List<Flow> flows) {
        boolean matched = false;
        for (Flow loss : flows) {
            if (!stepPartners(flows, loss, true).isEmpty()) {
                target.put(loss.itemId, -loss.quantityDelta);
                matched = true;
            }
        }
        return matched;
    }

    /**
     * Potion base name without its dose suffix, for receipts: "Prayer potion(4)" → "Prayer potion".
     */
    static String doseBaseName(String itemName) {
        return itemName == null ? "" : DOSE_SUFFIX.matcher(itemName.trim()).replaceFirst("").trim();
    }

    /** Dose count parsed from a trailing "(N)" suffix, or −1 when absent. */
    static int trailingDose(String itemName) {
        Matcher matcher = DOSE_SUFFIX.matcher(itemName == null ? "" : itemName.trim());
        return matcher.find() ? Integer.parseInt(matcher.group(1)) : -1;
    }

    static boolean isAmmo(String itemName) {
        String lower = Phrases.lower(itemName);
        return AMMUNITION.matcher(lower).matches() && !FLETCHING_PART.matcher(lower).matches();
    }

    /**
     * True when every loss has the same non-null family key (a matched click cannot name mixed
     * costs); false when there is no loss.
     */
    static boolean oneLossFamily(List<Flow> flows, Function<String, String> family) {
        String first = null;
        for (Flow flow : flows) {
            if (flow.quantityDelta >= 0L) continue;
            String key = family.apply(Phrases.lower(flow.itemName));
            if (key == null || first != null && !first.equals(key)) return false;
            first = key;
        }
        return first != null;
    }

    /** A cooking row must pair raw food inputs with only their cooked/burnt products. */
    static boolean isCooking(List<Flow> flows) {
        var rawBases = new ArrayList<String>();
        for (Flow flow : flows) {
            if (flow.quantityDelta < 0L) {
                String name = Phrases.lower(flow.itemName);
                rawBases.add(name.startsWith("raw ") && name.length() > 4 ? name.substring(4).trim()
                                : name.startsWith("uncooked ") && name.length() > 9 ? name.substring(9).trim() : null);
            }
        }
        return !rawBases.isEmpty() && !rawBases.contains(null) && all(flows, 1, output -> rawBases.stream().anyMatch(
                                                raw -> output.equals(raw) || output.equals("cooked " + raw)
                                                                || output.equals("burnt " + raw)));
    }

    /** True when every gained item is a burnt product ("Burnt shark", "Burnt pie"). */
    /**
     * True when at least one flow on the chosen side (1 gains, -1 losses, 0 both) exists and every
     * such flow's lower-case name satisfies {@code predicate}.
     */
    static boolean all(List<Flow> flows, int side, Predicate<String> predicate) {
        boolean any = false;
        for (Flow flow : flows) {
            long delta = flow.quantityDelta;
            if (delta == 0L || side != 0 && Long.signum(delta) != side) continue;
            if (!predicate.test(Phrases.lower(flow.itemName))) return false;
            any = true;
        }
        return any;
    }

    /** Ordered intent and item-name rules, compiled beside the old implementation for parity. */
    static final Map<String, Phrases.Clause[][]> RULES = GameData.rules("action_rules");

    static boolean rule(String group, String text) {
        return Phrases.has(text, RULES.get(group));
    }

    /** First matching verb wins, before the explicit fuel fallback. */
    static ActionKind verbOf(String raw) {
        String name = Phrases.lower(raw);
        for (int index = 0; index < VERBS.length; index += 2) {
            if (rule((String) VERBS[index], name)) return (ActionKind) VERBS[index + 1];
        }
        return rule("supplies", name) ? ActionKind.SUPPLIES : null;
    }

    /** Empty vessels use the already-normalized name, exactly as before. */
    static boolean isVessel(String name) {
        return rule("vessel", name);
    }

    /** Rune and unopened-claim names use the shared trimmed normalization. */
    static boolean isRune(String name) {
        return rule("rune", Phrases.lower(name));
    }

    static boolean isClaim(String name) {
        return rule("claim", Phrases.lower(name));
    }

    /** Ingredient names retain their existing non-null precondition and named ingredient set. */
    static boolean isIngredient(String name) {
        return !name.isEmpty() && rule("ingredient", name) && (HERBLORE_INGREDIENTS.contains(name)
                        || HERBLORE_INGREDIENT_SUFFIX.matcher(name).matches());
    }

    /** Dose arithmetic is unchanged; only food/vessel vocabulary is table-driven. */
    static boolean isConsumeStep(String lostName, String gainedName) {
        String lost = Phrases.lower(lostName);
        String gained = Phrases.lower(gainedName);
        if (lost.isEmpty() || gained.isEmpty()) return false;
        if (isVessel(gained)) return true;
        int lostDose = trailingDose(lost);
        int gainedDose = trailingDose(gained);
        if (lostDose > 0) {
            String lostBase = doseBaseName(lost);
            if (!lostBase.isEmpty() && lostBase.equals(doseBaseName(gained))) {
                // A suffix-less gain of the same base is the uncharged item: the last glory
                // charge leaves the plain amulet, so the pair is still one dose step (owner
                // 1.3.4). Any other suffix-less gain keeps failing closed.
                return lostDose == (gainedDose < 0 ? 0 : gainedDose) + 1;
            }
        }
        return rule("food", lost) && rule("partial", gained);
    }
}

/**
 * Menu / chat vocabulary that turns a click into an accounting intent: explicit spend actions (eat,
 * drink, bury, offer, light), transform/production options that arm PRODUCTION context, gather
 * verbs that only name the activity, and the chat lines that confirm a spend after the click.
 * Anything not listed here stays ambiguous and settles through Review, never a guess.
 */
class ActionSignals {
    static final Map<String, String> TRANSFORM = GameData.byName("transform_skills");
    static final Map<String, String> GATHER = GameData.byName("gather_skills");

    /** Compiled menu/chat predicates; d7/d10 already contain transform and gather data. */
    static final Map<String, Phrases.Clause[][]> RULES = GameData.rules("menu_rules");

    /** Apply one compiled predicate group. */
    static boolean rule(String group, String text) {
        return Phrases.has(text, RULES.get(group));
    }

    /** Widget actions eligible for selected spell evidence. */
    static boolean isWidgetAction(MenuAction action) {
        return rule("widget", action == null ? null : action.name());
    }

    /** Raw consume verbs plus normalized explicit spends. */
    static boolean isSpend(String option) {
        return rule("spend.raw", option) || isSpendName(option);
    }

    /** Normalized light/offer/pray and burial/scatter verbs. */
    static boolean isSpendName(String option) {
        return rule("spend.norm", Phrases.lower(option));
    }

    /** Use tinderbox with fuel; target normalization preserves whitespace. */
    static boolean lightsFire(String option, String target) {
        return rule("use", Phrases.lower(option)) && rule("fuel", Phrases.lower(target, false))
                && rule("fire", Phrases.lower(target, false));
    }

    /** Use bones/ashes on an altar. */
    static boolean offersBones(String option, String target) {
        return rule("use", Phrases.lower(option)) && rule("altar", Phrases.lower(target, false))
                && rule("bones", Phrases.lower(target, false));
    }

    /** Positive Sinister Offering cast evidence. */
    static boolean isOffering(String option, String target) {
        return rule("cast", Phrases.lower(option)) && rule("offering", Phrases.lower(target, false));
    }

    /** Chaos Altar saved a bone; this cannot confirm spend. */
    static boolean isSpared(String message) {
        return rule("spared", Phrases.lower(message, false));
    }

    /** Inventory-spend chat, excluding a saved bone. */
    static boolean isChatSpend(String message) {
        return !isSpared(message) && rule("spend.chat", Phrases.lower(message, false));
    }

    /**
     * Transform/production options (station or inventory) mapped to the skill whose XP confirms
     * them.
     */
    static String transformSkill(String option) {
        return TRANSFORM.getOrDefault(Phrases.lower(option), "");
    }

    /** Activity hint for object gather verbs; "General" when the verb is not a gather. */
    static String gatherActivity(String option) {
        return GATHER.getOrDefault(Phrases.orEmpty(option), "General");
    }

    /** Rake and plant still name the activity, but do not arm gather ownership evidence. */
    static boolean namesActivityOnly(String option) {
        return option != null && !"General".equals(gatherActivity(option)) && !rule("gather.exclude", option);
    }
}

/**
 * Schema-106 pooled known-basis coverage memory.
 *
 * <p>Tracked basis is a double-count-prevention memory, never a second financial ledger: canonical
 * counted transactions stay the only financial authority and this ledger never books, reprices or
 * exports GP. It records only <em>known coverage</em>: quantity whose prior GP Manager accounting
 * is proven, with the exact GP value GP Manager counted (which may legitimately be zero). Absence
 * of coverage means UNKNOWN basis, never zero basis; unknown quantity is derived per realization
 * and never persisted as a global unknown-owned ledger.
 *
 * <p>Allocation is tracked-first pooled weighted average (never FIFO/LIFO). Acquisitions add known
 * coverage. Proven SELL placements reserve their share; cancellations release the unused
 * reservation exactly; settlements consume the realized share; permanent ownership sinks deplete
 * with the same rule. A per-item realization fence blocks retroactive acquisition corrections once
 * known coverage has been realized or depleted, so canonical Net and tracked basis can never
 * disagree about what was previously counted.
 */
class TrackedBasisLedger {
    /** Exact known-coverage share a proven SELL placement captured from the available pool. */
    @AllArgsConstructor
    static class Reservation {
        long trackedQty;
        long basisGp;
    }

    Map<Integer, BasisPool> pools = new LinkedHashMap<>();
    long basisEpochMillis;
    java.util.function.IntFunction<Long> openReservationLookup = id -> 0L;

    // ---------------------------------------------------------------------------------------
    // Acquisition / removal / change
    // ---------------------------------------------------------------------------------------
    /**
     * Book a newly added canonical transaction: add its exact known coverage, and deplete known
     * coverage for proven permanent non-custody ownership sinks. Custody-owned settlements already
     * consumed their reservation, so their item legs never deplete again.
     */
    synchronized void onAdded(Transaction transaction, boolean custodyOwned) {
        if (transaction == null || transaction.timestampEpochMillis < basisEpochMillis) {
            // Pre-epoch stock is UNKNOWN coverage by migration law; nothing is inferred here.
            return;
        }
        if (basisEpochMillis <= 0L && transaction.timestampEpochMillis > 0L)
            basisEpochMillis = transaction.timestampEpochMillis;
        applyContribution(contribution(transaction), transaction.timestampEpochMillis);
        if (!custodyOwned) depleteSinks(transaction);
    }

    /** Validate restoring a previously removed transaction; false blocks the restore. */
    synchronized boolean canAdd(Transaction transaction) {
        if (transaction == null) return false;
        if (transaction.timestampEpochMillis >= basisEpochMillis && !sinkQuantities(transaction).isEmpty()) {
            return false;
        }
        return canApplyAll(contribution(transaction), 1L, transaction.timestampEpochMillis);
    }

    /** Validate removing a retained transaction (undo); false blocks the canonical removal. */
    synchronized boolean canRemove(Transaction transaction) {
        if (transaction == null || transaction.timestampEpochMillis < basisEpochMillis) return true;
        if (!sinkQuantities(transaction).isEmpty()) {
            return false;
        }
        return canApplyAll(contribution(transaction), -1L, transaction.timestampEpochMillis);
    }

    boolean canApplyAll(Map<Integer, long[]> deltas, long sign, long timestamp) {
        for (Entry<Integer, long[]> entry : deltas.entrySet()) {
            if (!canApply(entry.getKey(), sign * entry.getValue()[0], sign * entry.getValue()[1], timestamp)) {
                return false;
            }
        }
        return true;
    }

    synchronized void onUsedUp(Transaction transaction) {
        depleteSinks(transaction);
    }

    /** Reverse a previously removed transaction's exact known coverage. */
    synchronized void onRemoved(Transaction transaction) {
        if (transaction == null || transaction.timestampEpochMillis < basisEpochMillis) return;
        contribution(transaction).forEach((itemId, delta) -> applyDelta(itemId, -delta[0], -delta[1]));
    }

    /**
     * Validate a pending correction/split/undo before any canonical mutation. False means the
     * mutation must be rejected as-is: the item's known coverage is reserved or already realized.
     */
    synchronized boolean canChange(Transaction transaction, Correction previousCorrection, List<Flow> previousFlows,
            Correction nextCorrection, List<Flow> nextFlows) {
        if (transaction == null) return false;
        Map<Integer, long[]> before = contribution(transaction, previousCorrection, previousFlows);
        // A null next-flow set means the caller can only promise the positive contribution
        // shrinks; validating against the empty worst case is the strictest safe check.
        Map<Integer, long[]> after = contribution(transaction, nextCorrection, nextFlows);
        Map<Integer, Long> beforeSinks = sinkQuantities(transaction, previousCorrection, previousFlows);
        Map<Integer, Long> afterSinks = sinkQuantities(transaction, nextCorrection, nextFlows);
        if (transaction.timestampEpochMillis >= basisEpochMillis && !beforeSinks.equals(afterSinks)
                && !canIntroduceSink(beforeSinks, afterSinks, transaction.timestampEpochMillis)) {
            return false;
        }
        return canApplyAll(deltas(before, after), 1L, transaction.timestampEpochMillis);
    }

    /** Apply the exact effective delta after a permitted correction/split/undo. */
    synchronized void onChanged(Transaction transaction, Correction previousCorrection, List<Flow> previousFlows) {
        if (transaction == null) return;
        Map<Integer, Long> beforeSinks = sinkQuantities(transaction, previousCorrection, previousFlows);
        Map<Integer, Long> afterSinks = sinkQuantities(transaction);
        applyContribution(deltas(contribution(transaction, previousCorrection, previousFlows),
                        contribution(transaction)), transaction.timestampEpochMillis);
        if (!beforeSinks.equals(afterSinks) && beforeSinks.isEmpty()) depleteSinks(transaction);
    }

    // ---------------------------------------------------------------------------------------
    // Reservation / realization / depletion
    // ---------------------------------------------------------------------------------------
    /**
     * Reserve the tracked-first known-coverage share for a quantity entering proven SELL custody.
     */
    synchronized Reservation reserve(int itemId, long quantity, long now) {
        long requested = nonNeg(quantity);
        BasisPool pool = pools.get(itemId);
        long availableQty = pool == null ? 0L : pool.availableQty;
        long availableBasis = pool == null ? 0L : pool.availableBasisGp;
        long consumeQty = min(requested, availableQty);
        long basis = BasisMath.shareOf(availableQty, availableBasis, consumeQty);
        if (consumeQty <= 0L && basis <= 0L) return new Reservation(0L, 0L);
        pool = pool(itemId);
        pool.availableQty = nonNeg(availableQty - consumeQty);
        pool.availableBasisGp = nonNeg(availableBasis - basis);
        return new Reservation(consumeQty, basis);
    }

    /** A sale realized units of this item: fence retroactive corrections before {@code now}. */
    synchronized void fenceRealized(int itemId, long now) {
        BasisPool pool = pool(itemId);
        pool.realizationFenceEpochMillis = max(pool.realizationFenceEpochMillis, now);
    }

    /** Return an unconsumed reservation share to the available pool (cancel/return). */
    synchronized void release(int itemId, long quantity, long basisGp) {
        long releaseQty = nonNeg(quantity);
        long releaseBasis = nonNeg(basisGp);
        if (releaseQty <= 0L && releaseBasis <= 0L) return;
        BasisPool pool = pool(itemId);
        pool.availableQty = nonNeg(pool.availableQty + releaseQty);
        pool.availableBasisGp = nonNeg(pool.availableBasisGp + releaseBasis);
    }

    /** Deplete known coverage for a proven permanent ownership sink; returns basis consumed. */
    synchronized long deplete(int itemId, long quantity, long now) {
        long requested = nonNeg(quantity);
        BasisPool pool = pools.get(itemId);
        if (requested <= 0L) return 0L;
        if (pool == null) {
            // Even a sink with no known coverage leaves a realization fence: units left ownership,
            // so later retroactive coverage for them can never be re-added.
            pool(itemId).realizationFenceEpochMillis = nonNeg(now);
            return 0L;
        }
        long consumeQty = min(requested, pool.availableQty);
        long basis = BasisMath.shareOf(pool.availableQty, pool.availableBasisGp, consumeQty);
        pool.availableQty = nonNeg(pool.availableQty - consumeQty);
        pool.availableBasisGp = nonNeg(pool.availableBasisGp - basis);
        pool.realizationFenceEpochMillis = max(pool.realizationFenceEpochMillis, now);
        return basis;
    }

    /** Currency is money, never tracked owned-item value. */
    static boolean isCurrency(int itemId) {
        return itemId == ItemID.COINS || itemId == ItemID.PLATINUM;
    }

    // ---------------------------------------------------------------------------------------
    // Persistence / lifecycle
    // ---------------------------------------------------------------------------------------
    synchronized void writeTo(SavedState state) {
        if (state == null) return;
        var out = new TrackedBasisState();
        // Epoch 0 only happens for an engine that never restored or tracked anything; a positive
        // sentinel keeps a saved pool loadable as "tracked since the beginning".
        out.basisEpochMillis = nonNeg(basisEpochMillis > 0L ? basisEpochMillis : 1L);
        var list = new ArrayList<BasisPool>();
        for (BasisPool pool : pools.values()) {
            if (pool.availableQty <= 0L && pool.availableBasisGp <= 0L && pool.realizationFenceEpochMillis <= 0L
                    && pool.latestAcquisitionEpochMillis <= 0L) {
                continue;
            }
            var copy = new BasisPool(pool.itemId);
            copy.availableQty = pool.availableQty;
            copy.availableBasisGp = pool.availableBasisGp;
            copy.realizationFenceEpochMillis = pool.realizationFenceEpochMillis;
            copy.latestAcquisitionEpochMillis = pool.latestAcquisitionEpochMillis;
            list.add(copy);
        }
        list.removeIf(value -> value == null || value.itemId <= 0);
        out.pools = new ArrayList<>(list);
        state.setTrackedBasis(out);
    }

    /**
     * Restore persisted continuity. A pre-106 (or absent) state starts with no known coverage at
     * the migration boundary: existing holdings are UNKNOWN coverage, no bank value seeds basis and
     * no history is reconstructed. Reserved shares live on the durable custody records.
     */
    synchronized void restore(SavedState state, long now) {
        pools.clear();
        TrackedBasisState saved = state == null ? null : state.getTrackedBasis();
        if (saved != null && saved.getBasisEpochMillis() > 0L) {
            basisEpochMillis = saved.getBasisEpochMillis();
            for (BasisPool pool : saved.pools()) {
                if (pool == null || pool.itemId <= 0) continue;
                // A save is clamped once here, so the pool's fields are read directly.
                pool.availableQty = nonNeg(pool.availableQty);
                pool.availableBasisGp = nonNeg(pool.availableBasisGp);
                pool.realizationFenceEpochMillis = nonNeg(pool.realizationFenceEpochMillis);
                pool.latestAcquisitionEpochMillis = nonNeg(pool.latestAcquisitionEpochMillis);
                pools.put(pool.itemId, pool);
            }
        } else {
            basisEpochMillis = now;
        }
    }

    /** Destructive reset: tracked basis is continuity state and clears with the rest. */
    synchronized void reset() {
        pools.clear();
        basisEpochMillis = 0L;
    }

    /** Adopt another ledger's durable state during a staged profile swap. */
    synchronized void adoptFrom(TrackedBasisLedger other) {
        reset();
        if (other != null) {
            basisEpochMillis = other.basisEpochMillis;
            other.pools.forEach((itemId, pool) -> {
                        if (pool != null) pools.put(itemId, pool);
                    });
        }
    }

    // ---------------------------------------------------------------------------------------
    // Internals
    // ---------------------------------------------------------------------------------------
    BasisPool pool(int itemId) {
        return pools.computeIfAbsent(itemId, BasisPool::new);
    }

    void applyContribution(Map<Integer, long[]> contribution, long timestamp) {
        for (Entry<Integer, long[]> entry : contribution.entrySet()) {
            applyDelta(entry.getKey(), entry.getValue()[0], entry.getValue()[1]);
            if (entry.getValue()[0] > 0L) {
                BasisPool pool = pool(entry.getKey());
                pool.latestAcquisitionEpochMillis = max(pool.latestAcquisitionEpochMillis, timestamp);
            }
        }
    }

    /** Deplete known coverage for each proven permanent non-custody ownership sink in the row. */
    void depleteSinks(Transaction transaction) {
        Map<Integer, Long> quantities = sinkQuantities(transaction);
        for (Entry<Integer, Long> entry : quantities.entrySet())
            deplete(entry.getKey(), entry.getValue(), transaction.timestampEpochMillis);
    }

    /** An owner may first count a Review removal while no later use has frozen its pool. */
    boolean canIntroduceSink(Map<Integer, Long> before, Map<Integer, Long> after, long transactionTimestamp) {
        if (!before.isEmpty() || after.isEmpty()) return false;
        for (Integer itemId : after.keySet()) {
            if (!canApply(itemId, 0L, 0L, transactionTimestamp)) return false;
            BasisPool pool = pools.get(itemId);
            if (pool != null && pool.availableQty > 0L && (pool.latestAcquisitionEpochMillis <= 0L
                            || pool.latestAcquisitionEpochMillis > transactionTimestamp)) {
                return false;
            }
        }
        return true;
    }

    /** Physical counted removals that would require exact reversal of pooled sink depletion. */
    Map<Integer, Long> sinkQuantities(TransactionType type, boolean counted, Correction correction, List<Flow> flows) {
        var quantities = new LinkedHashMap<Integer, Long>();
        if (!counted || type == TransactionType.TRANSFER || type == TransactionType.TRADE || correction == Correction.TRANSFER
                || flows == null) {
            // Custody-owned trade settlements consume their reservation separately. Their financial
            // Result corrections must remain available without touching physical basis.
            return quantities;
        }
        for (Flow flow : flows) {
            if (flow.quantityDelta >= 0L || isCurrency(flow.itemId)) continue;
            long quantity = flow.quantityDelta == Long.MIN_VALUE ? Long.MAX_VALUE : -flow.quantityDelta;
            int itemId = flow.itemId;
            quantities.put(itemId, safeAdd(quantities.getOrDefault(itemId, 0L), quantity));
        }
        return quantities;
    }

    void applyDelta(int itemId, long deltaQty, long deltaBasisGp) {
        if (deltaQty == 0L && deltaBasisGp == 0L) return;
        BasisPool pool = pool(itemId);
        pool.availableQty = nonNeg(pool.availableQty + deltaQty);
        pool.availableBasisGp = nonNeg(pool.availableBasisGp + deltaBasisGp);
    }

    boolean canApply(int itemId, long deltaQty, long deltaBasisGp, long transactionTimestamp) {
        if (transactionTimestamp < basisEpochMillis) return false;
        Long reservationTime = openReservationLookup.apply(itemId);
        if (reservationTime != null && reservationTime > 0L && reservationTime >= transactionTimestamp) return false;
        BasisPool pool = pools.get(itemId);
        long fence = pool == null ? 0L : pool.realizationFenceEpochMillis;
        if (fence > 0L && fence >= transactionTimestamp) return false;
        long availableQty = pool == null ? 0L : pool.availableQty;
        long availableBasis = pool == null ? 0L : pool.availableBasisGp;
        if (availableQty + deltaQty < 0L || availableBasis + deltaBasisGp < 0L) return false;
        return true;
    }

    Map<Integer, long[]> deltas(Map<Integer, long[]> before, Map<Integer, long[]> after) {
        var out = new LinkedHashMap<Integer, long[]>();
        for (Entry<Integer, long[]> entry : before.entrySet()) {
            long[] target = after.get(entry.getKey());
            long deltaQty = (target == null ? 0L : target[0]) - entry.getValue()[0];
            long deltaBasis = (target == null ? 0L : target[1]) - entry.getValue()[1];
            if (deltaQty != 0L || deltaBasis != 0L) {
                out.put(entry.getKey(), new long[] {deltaQty, deltaBasis});
            }
        }
        for (Entry<Integer, long[]> entry : after.entrySet()) {
            if (!before.containsKey(entry.getKey())) {
                out.put(entry.getKey(), new long[] {entry.getValue()[0], entry.getValue()[1]});
            }
        }
        return out;
    }

    Map<Integer, long[]> contribution(Transaction transaction) {
        return contribution(transaction, transaction.getCorrection(), transaction.getFlows());
    }

    /** The contribution the transaction would have under {@code correction} with {@code flows}. */
    Map<Integer, long[]> contribution(Transaction transaction, Correction correction, List<Flow> flows) {
        return flows == null ? new LinkedHashMap<>() : contribution(transaction.autoType(),
                        effectiveCounted(transaction.autoCounted(), correction), correction, flows);
    }

    /** The row's sinks as it is booked now. */
    Map<Integer, Long> sinkQuantities(Transaction transaction) {
        return sinkQuantities(transaction, transaction.getCorrection(), transaction.getFlows());
    }

    Map<Integer, Long> sinkQuantities(Transaction transaction, Correction correction, List<Flow> flows) {
        // A drop or a shot still on the ground is not a use yet: picking it up shrinks the row. It
        // depletes the pool when its pickup window closes (Engine#settleGround).
        if (transaction.isOnGround()) return new LinkedHashMap<>();
        return sinkQuantities(transaction.autoType(), effectiveCounted(transaction.autoCounted(), correction),
                correction, flows);
    }

    /** Effective counted state for an explicit correction (REVENUE/COST always count). */
    static boolean effectiveCounted(boolean automaticallyCounted, Correction correction) {
        Correction effective = correction == null ? AUTO : correction;
        return effective == REVENUE || effective == COST || (effective == AUTO && automaticallyCounted);
    }

    /**
     * Exact known coverage a counted transaction introduces, mirroring {@code Accounting.flow} for
     * positive quantities: AUTO counts the observed positive value, REVENUE counts the gross
     * magnitude, COST/IGNORE/TRANSFER count nothing. Quantity is tracked even when the booked value
     * is legitimately zero; unpriced/unknown/deferred sources create no coverage at all.
     */
    static Map<Integer, long[]> contribution(
            TransactionType type, boolean counted, Correction correction, List<Flow> flows) {
        var out = new LinkedHashMap<Integer, long[]>();
        Correction effective = correction == null ? AUTO : correction;
        if (type == TransactionType.TRANSFER || effective == Correction.TRANSFER || !counted || effective == IGNORE
                || flows == null) {
            return out;
        }
        for (Flow flow : flows) {
            if (flow.quantityDelta <= 0L || isCurrency(flow.itemId)) continue;
            PriceSource source = flow.getPriceSource();
            if (source == null || source == UNPRICED || source == UNKNOWN || source == PriceSource.DEFERRED_CLAIM) continue;
            long revenue = effective == REVENUE ? SafeMath.abs(flow.valueDelta)
                            : effective == COST ? 0L : nonNeg(flow.valueDelta);
            long[] total = out.computeIfAbsent(flow.itemId, itemId -> new long[2]);
            total[0] = safeAdd(total[0], flow.quantityDelta);
            total[1] = safeAdd(total[1], revenue);
        }
        return out;
    }
}

/**
 * Persisted schema-106 tracked-basis continuity: the minimum state a pooled weighted-average
 * double-count-prevention memory needs across restart.
 *
 * <p>{@code basisEpochMillis} is the migration boundary: acquisitions booked before it are
 * untracked by law (no backfill, no bank-price inference), and basis-affecting corrections of those
 * rows are fenced. Open SELL reservation shares live on their durable custody records; the ledger
 * rebinds the pooled reserved totals from them on restore.
 */
class TrackedBasisState {
    long basisEpochMillis;
    List<BasisPool> pools = new ArrayList<>();

    long getBasisEpochMillis() {
        return nonNeg(basisEpochMillis);
    }

    /** Never null: a pre-106 file upgrades with an empty pool. */
    List<BasisPool> pools() {
        if (pools == null) pools = new ArrayList<>();
        return pools;
    }
}

/**
 * One canonical item's pooled tracked-basis state (schema 106).
 *
 * <p>It is supporting ownership state, never a financial authority: canonical counted transactions
 * stay the only financial truth. {@code available*} is the free pooled quantity/value that a new
 * SELL reservation or permanent sink may consume (a reserved share is held by its open SELL custody
 * record, not here); {@code realizationFenceEpochMillis} records the latest time pooled basis was
 * realized or permanently depleted, which fences retroactive acquisition corrections for this item.
 * No FIFO lots, no portfolio history, no mark-to-market.
 */
class BasisPool {
    int itemId;
    long availableQty;
    long availableBasisGp;
    long realizationFenceEpochMillis;

    /** Latest proven known-coverage acquisition; fences retroactive counted removals. */
    long latestAcquisitionEpochMillis;

    BasisPool() {}

    BasisPool(int itemId) {
        this.itemId = itemId;
    }
}

/**
 * Integer-only pooled basis math shared by the known-basis ledger and the read model.
 *
 * <p>Every allocation is floor-based and the remainder stays with the other side, so parts always
 * sum to the whole: no invented GP, no decimals, no drift. All multiplication is long-safe.
 */
class BasisMath {
    /**
     * Floor-share of a pooled quantity/basis pair; consuming everything takes the exact remainder.
     */
    static long shareOf(long totalQty, long totalBasisGp, long consumeQty) {
        long qty = nonNeg(totalQty);
        long basis = nonNeg(totalBasisGp);
        long consume = nonNeg(consumeQty);
        if (qty <= 0L || basis <= 0L || consume <= 0L) return 0L;
        if (consume >= qty) return basis;
        return multiplyDivide(basis, consume, qty);
    }

    /**
     * Known-coverage share of an observed settlement: the known portion takes the floor share and
     * the unknown remainder receives the integer difference, so both always sum to the settlement.
     */
    static long knownProceedsOf(long totalSettlementGp, long realizedQty, long knownQty) {
        long total = nonNeg(totalSettlementGp);
        long realized = nonNeg(realizedQty);
        long known = nonNeg(min(knownQty, realized));
        if (realized <= 0L || known <= 0L) return 0L;
        if (known >= realized) return total;
        return multiplyDivide(total, known, realized);
    }

    /** Long-safe floor(value × numerator / denominator) for non-negative inputs. */
    static long multiplyDivide(long value, long numerator, long denominator) {
        if (denominator <= 0L || numerator <= 0L || value <= 0L) return 0L;
        if (numerator >= denominator) return value;
        BigInteger product = BigInteger.valueOf(value).multiply(BigInteger.valueOf(numerator));
        BigInteger share = product.divide(BigInteger.valueOf(denominator));
        // b < c, so the share is below a and fits a long.
        return share.longValue();
    }
}

package com.gpmanager;

import static com.gpmanager.Context.*;
import static com.gpmanager.FlowFilters.*;
import static com.gpmanager.GameData.msg;
import static com.gpmanager.GeOffer.Side.*;
import static com.gpmanager.GeOffer.Stage.*;
import static com.gpmanager.PriceSource.*;
import static com.gpmanager.SafeMath.*;
import static com.gpmanager.TransactionType.*;
import static java.lang.Math.*;
import static java.util.Collections.*;

import com.gpmanager.GeOffer.*;
import com.gpmanager.OfferSlots.Snapshot;
import java.util.*;
import java.util.function.*;
import javax.inject.Singleton;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.gameval.ItemID;
import static com.gpmanager.Phrases.*;

/**
 * Durable schema-104 GE custody ledger.
 *
 * <p>Physical placement principal, cancellation returns and refunds are ownership-neutral
 * transfers. A safely realized settlement books one canonical counted Market result exactly once,
 * guarded by the persisted cumulative-execution counters. Unattributable or unbased lifecycles fail
 * closed through the existing Review domain instead of guessing.
 *
 * <p>An observed collect coin movement (a live Collect interaction with its coin gain) is
 * attributed to exactly the sold offers it proves: the offers whose slot cleared within the SLOT
 * WINDOW, or the one subset of observed after-tax nets that sums to it exactly. A
 * unique-but-unconfirmed match is held for that short window and settles only without contradicting
 * slot evidence; a tie, a contradiction or exhausted evidence fails closed, quarantining only
 * slot-evidenced candidates and leaving the rest pending. Collect cash that arrives before the
 * matching sell execution evidence keeps its longer transient hold. Both holds are transient: a
 * restart leaves the durable records to their own unobserved-settlement handoff, never a double
 * booking. A coin gain with no Collect interaction keeps the previous booking path unchanged.
 *
 * <p>The ledger never mutates booked transactions, never re-prices history, and never scans the
 * whole session history: claims are quantity-bounded against the bounded open-record set.
 */
class GeCustodyLedger {
    /** How long a placement still explains the coins or items it took from the inventory. */
    static final long PLACEMENT_WINDOW_MILLIS = 90_000L;

    /** How long a terminal lifecycle may await an unobserved settlement before Review handoff. */
    static final long UNOBSERVED_GRACE_MILLIS = 10L * 60L * 1000L;

    /** A cleared slot whose cash or items never reached the inventory went to the bank by now. */
    static final long BANK_COLLECT_MILLIS = 30_000L;

    /**
     * Slot-clear evidence window: at most 3 game ticks either side of the coin gain. A slot that
     * cleared in this window proves its offer's coins were the ones collected.
     */
    static final long SLOT_WINDOW_MILLIS = 1_800L;

    /** One open record per GE slot; more candidates than this can never be enumerated. */
    static final int MAX_SETTLEMENT_CANDIDATES = 8;

    /** How long a fill or cancellation still explains a collected movement. */
    static final long COLLECTION_WINDOW_MILLIS = 2L * 60L * 60L * 1000L;

    /** Bounded retention of reconciled lifecycles so recent Market context survives. */
    static final int MAX_CLOSED_RECORDS = 64;

    /**
     * Per-slot baseline of each observed offer; exact fill deltas come from its cumulative
     * counters.
     */
    Map<Integer, Snapshot> baselines = new HashMap<>();

    List<GeOffer> records = new ArrayList<>();

    /** Slots whose identity was replaced mid-life; the next placement is quarantined. */
    Set<Integer> replacedSlots = new HashSet<>();

    /**
     * Aggregate GE cash observed with a live Collect interaction but not yet exactly attributable
     * to every sell lifecycle it may settle. Retained internally (never a visible receipt) until
     * the missing offer evidence arrives and the batch reconciles exactly, or the bounded lifecycle
     * expires and the cash fails closed to Review. Transient by design: a restart without the
     * evidence leaves the records to their own unobserved-settlement handoff, never a double
     * booking.
     */
    long pendingSettlementCashGp;

    long pendingSettlementAtEpochMillis;

    /** Earliest observation of the still-unattributed cash; the SLOT WINDOW anchor. */
    long pendingSettlementHeldSinceEpochMillis;

    /**
     * True while the held cash is waiting for sell execution/terminal evidence (the existing long
     * hold). Its evidence completion books the exact attribution immediately, as before; a short
     * SLOT WINDOW hold instead waits for slot confirmation.
     */
    boolean pendingSettlementAwaitingEvidence;

    /**
     * Transient slot-clear evidence (offer id to CLEARED observation time). It only proves which
     * sold offers a nearby collect movement belongs to; like held cash it is never persisted and
     * clears on restore/reset/adopt.
     */
    Map<String, Long> slotClearedAtEpochMillis = new HashMap<>();

    /**
     * Transient: live lifecycles the login seed saw as an EMPTY slot. RuneLite reports every slot
     * EMPTY at login before the server restores the offers, so the same offer arriving shortly
     * after is a late replay of it, never a new offer reusing the slot.
     */
    Map<String, Long> loginClearedAtEpochMillis = new HashMap<>();

    static final long LOGIN_REPLAY_MILLIS = 2L * 60L * 1000L;

    /**
     * Transient: when each offer last explained a movement (its offer id, with a "$" suffix for the
     * coin side). A placement explains one loss; a fill or cancellation explains nothing more until
     * the offer is seen again.
     */
    Map<String, Long> explainedAt = new HashMap<>();

    /** Schema-106 pooled known-basis ledger; null keeps custody purely observational. */
    TrackedBasisLedger basisLedger;

    // The operation in progress: each synchronized entry point sets these before it works.
    /** The operation's time. */
    long now;

    /** The session the operation books into. */
    String sessionId = "";

    /** What the operation books: settlements and Review handoffs. */
    List<Transaction> bookings = new ArrayList<>();

    /** One settle's flows not yet claimed, the parts claimed so far, and the items it may claim. */
    List<Flow> residual = new ArrayList<>();

    List<Flow> claimed = new ArrayList<>();
    IntPredicate allowed = itemId -> true;

    /** Starts an operation at {@code now}; it books into a fresh list. */
    void begin(long now, String sessionId) {
        this.now = now;
        this.sessionId = sessionId;
        bookings = new ArrayList<>();
    }

    /** Wire the pooled known-basis ledger that owns SELL reservations and BUY coverage. */
    synchronized void setBasisLedger(TrackedBasisLedger ledger) {
        basisLedger = ledger;
    }

    /** Latest capture time of an open SELL reservation for the item; 0 when none is open. */
    synchronized long latestReservationTime(int itemId) {
        long latest = 0L;
        for (GeOffer record : records) {
            if (record.side != SELL || record.itemId != itemId) continue;
            if (record.reservedQty() <= 0L && record.reservedBasis() <= 0L) continue;
            long capturedAt = record.basisCapturedAtEpochMillis > 0L ? record.basisCapturedAtEpochMillis
                            : record.placedAtEpochMillis;
            latest = max(latest, capturedAt);
        }
        return latest;
    }

    /** Immutable result of one settle: residual flows still needing normal classification. */
    @AllArgsConstructor
    static class Partition {
        List<Flow> residualFlows;
        List<Transaction> countedBookings;
        List<Transaction> transferBookings;

        /** Physical flows consumed by custody claims; used to spend matching offer evidence. */
        List<Flow> claimedFlows;

        Transaction lastBooking() {
            List<Transaction> bookings = countedBookings.isEmpty() ? transferBookings : countedBookings;
            return bookings.isEmpty() ? null : bookings.get(bookings.size() - 1);
        }
    }

    // ---------------------------------------------------------------------------------------
    // Lifecycle observation
    // ---------------------------------------------------------------------------------------
    /** Apply one offer-ledger transition; returns any Review handoff or settled rows it forced. */
    synchronized List<Transaction> observeTransition(
            OfferSlots.Transition transition, String itemName, long now, String sessionId) {
        begin(now, sessionId);
        observe(transition.previous, transition.current, itemName);
        // New execution/lifecycle evidence may complete a settlement whose cash was observed
        // first; the held batch settles as soon as it is exactly attributable.
        reconcilePendingSettlement();
        return bookings;
    }

    /**
     * Applies one slot snapshot against the slot's baseline: exact incremental fills from the
     * cumulative counters, Modify Offer, slot reuse and identity replacement. Backwards counters,
     * value moved without quantity, or a missed placement are a desync, never a fill.
     */
    void observe(Snapshot previous, Snapshot current, String itemName) {
        int slot = current.slot;
        Side side = OfferSlots.sideOf(current.state);
        Snapshot base = baselines.remove(slot);
        if (side == null) {
            GeOffer record = touch(slot, base != null ? base : previous);
            if (record != null) {
                record.cleared = true;
                // Transient slot evidence: proves which offer a nearby collect belongs to.
                slotClearedAtEpochMillis.put(record.offerId, now);
            }
            return;
        }
        GeOffer replay = base == null ? lateLoginReplay(slot, side, current) : null;
        if (replay != null) {
            loginClearedAtEpochMillis.remove(replay.offerId);
            slotClearedAtEpochMillis.remove(replay.offerId);
            replay.cleared = false;
            resume(replay, current);
            baselines.put(slot, current);
            return;
        }
        boolean active = OfferSlots.isActive(current.state);
        if (base == null || active && (OfferSlots.sideOf(base.state) != side || base.itemId != current.itemId)) {
            if (base != null) {
                // Item/side changed mid-life without Modify evidence: retire the old lifecycle and
                // quarantine the next; never inherit prior basis or progress.
                GeOffer old = touch(slot, base);
                if (old != null) {
                    old.confidence = CustodyConfidence.AMBIGUOUS;
                    handoffAndRemove(old, msg("offer-identity"));
                }
                replacedSlots.add(slot);
            }
            baselines.put(slot, current);
            if (base == null && previous != null && previous.state != GrandExchangeOfferState.EMPTY) {
                // A missed placement cannot be dated: quarantine the lifecycle, emit no fill.
                desync(slot, current, current, itemName);
                return;
            }
            place(slot, side, current, itemName);
            advance(slot, current, current, current.quantityTraded, current.spent);
            return;
        }
        if (active && (base.totalQuantity != current.totalQuantity || base.price != current.price)) {
            // A price-only Modify keeps the lifecycle and its basis; a quantity change has no exact
            // per-slice basis allocation, so realization fails closed to Review.
            boolean priceOnly = base.totalQuantity == current.totalQuantity;
            baselines.put(slot, new Snapshot(slot, base.state, base.itemId, current.totalQuantity, base.quantityTraded,
                            priceOnly ? current.price : base.price, base.spent));
            GeOffer record = touch(slot, base);
            if (record != null && priceOnly) {
                record.listedPrice = nonNeg(current.price);
            } else if (record != null) {
                record.offeredQty = nonNeg(current.totalQuantity);
                record.quantityModified = true;
            }
            return;
        }
        long quantity = current.quantityTraded - base.quantityTraded;
        long spent = current.spent - base.spent;
        baselines.put(slot, new Snapshot(slot, base.state, base.itemId, base.totalQuantity, current.quantityTraded,
                        base.price, current.spent));
        if (quantity < 0L || spent < 0L || quantity == 0L && spent > 0L) {
            desync(slot, base, current, itemName);
            return;
        }
        advance(slot, base, current, quantity, spent);
    }

    /** A new offer in the slot: a duplicate replay of the live lifecycle changes nothing. */
    void place(int slot, Side side, Snapshot offer, String itemName) {
        GeOffer previous = forSlot(slot);
        if (previous != null && isSameIdentity(previous, side, offer.itemId, offer.totalQuantity, offer.price)
                && !previous.cleared && !previous.isTerminal()) {
            previous.lastSeenAtEpochMillis = now;
            return;
        }
        if (previous != null && previous.stage == OPEN && previous.isReconciled()) {
            // Settled but not yet sealed (a settlement completed by an offer transition):
            // seal it exactly as the next settle would, so it stays as history.
            previous.stage = CLOSED;
            previous = null;
        }
        if (previous != null && previous.cleared && previous.isTerminal() && trusted(previous, previous.side)) {
            // Owner 1.2: a finished offer collected moments before its slot is reused still waits
            // for
            // its items or coins to settle; it gives up the slot instead of going to Review.
            previous.slot = -1;
            previous = null;
        }
        if (previous != null) {
            // Slot reuse: a new offer never inherits prior basis or progress.
            handoffAndRemove(previous, msg("slot-reused"));
        }
        // A settled (CLOSED) lifecycle in this slot stays as bounded market history for its
        // booked sale; only its unrealized reservation leaves with the slot.
        releaseRemaining(latestClosed(slot));
        GeOffer record = newRecord(offer, itemName, offer.state);
        if (replacedSlots.remove(slot)) record.confidence = CustodyConfidence.AMBIGUOUS;
        // Per-fill tax is exact only for a placement observed live from an empty slot.
        record.fillTaxExact = side == SELL && record.confidence == CustodyConfidence.CONFIRMED;
        records.add(record);
    }

    /** Exact fill progress, then the terminal state (a final fill lands before a cancellation). */
    void advance(int slot, Snapshot offer, Snapshot current, long quantity, long spent) {
        boolean fill = quantity > 0L && spent >= 0L;
        boolean terminal = OfferSlots.isTerminal(current.state);
        GeOffer record = fill || terminal ? touch(slot, offer) : null;
        if (record != null && fill) recordFill(record, quantity, spent);
        if (record != null && terminal) record.offerState = current.state.name();
    }

    /** Counters with no exact lineage: quarantine the lifecycle, or start an unbased one. */
    void desync(int slot, Snapshot offer, Snapshot current, String itemName) {
        GeOffer record = touch(slot, offer);
        if (record != null) {
            record.confidence = CustodyConfidence.AMBIGUOUS;
            record.fillTaxExact = false;
        } else if (offer.itemId > 0) {
            record = newRecord(offer, itemName, current.state);
            record.confidence = CustodyConfidence.LEGACY_UNBASED;
            records.add(record);
        }
    }

    /**
     * The live lifecycle the login seed cleared in this slot, when this snapshot is that same
     * offer.
     */
    GeOffer lateLoginReplay(int slot, Side side, Snapshot current) {
        GeOffer record = forSlot(slot);
        Long clearedAt = record == null ? null : loginClearedAtEpochMillis.get(record.offerId);
        return clearedAt != null && now - clearedAt <= LOGIN_REPLAY_MILLIS && isSameIdentity(
                                record, side, current.itemId, current.totalQuantity, current.price) ? record : null;
    }

    /**
     * Resume a persisted lifecycle; progress made while away is adopted once, never as a fill. Its
     * confidence stays as it was: a relog never makes a quarantined or unbased offer trusted.
     */
    void resume(GeOffer existing, Snapshot snapshot) {
        existing.lastSeenAtEpochMillis = now;
        existing.offerState = snapshot.state.name();
        if (snapshot.quantityTraded != existing.filledQty) {
            // Fills while logged out were never observed at their own prices.
            existing.fillTaxExact = false;
        }
        existing.filledQty = snapshot.quantityTraded;
        existing.spentGp = nonNeg(snapshot.spent);
    }

    /** A new lifecycle for the offer in this snapshot's slot, last seen in {@code state}. */
    GeOffer newRecord(Snapshot offer, String itemName, GrandExchangeOfferState state) {
        var record = new GeOffer(UUID.randomUUID().toString(), offer.slot, OfferSlots.sideOf(offer.state), offer.itemId,
                        itemName, offer.totalQuantity, offer.price, now, Phrases.orEmpty(sessionId));
        record.lastSeenAtEpochMillis = now;
        record.offerState = state.name();
        return record;
    }

    /**
     * Record the login slot baseline: resume a persisted matching lifecycle, quarantine active
     * offers first seen now as legacy/unbased, and hand off records whose slot changed identity.
     */
    synchronized List<Transaction> seedSlots(Map<Integer, Snapshot> snapshots, long now, String sessionId) {
        begin(now, sessionId);
        baselines.clear();
        loginClearedAtEpochMillis.clear();
        for (Snapshot snapshot : snapshots.values()) {
            GeOffer existing = forSlot(snapshot.slot);
            if (snapshot.state == GrandExchangeOfferState.EMPTY) {
                if (existing != null) loginClearedAtEpochMillis.put(existing.offerId, now);
                else existing = latestClosed(snapshot.slot);
                if (existing != null) {
                    existing.cleared = true;
                    existing.lastSeenAtEpochMillis = now;
                    slotClearedAtEpochMillis.put(existing.offerId, now);
                }
                continue;
            }
            Side side = OfferSlots.sideOf(snapshot.state);
            if (side == null) continue;
            // Pre-existing progress is only a baseline, never replayed as a fill.
            baselines.put(snapshot.slot, snapshot);
            if (existing != null && isSameIdentity(existing, side, snapshot.itemId, snapshot.totalQuantity,
                            snapshot.price)) {
                resume(existing, snapshot);
                continue;
            }
            if (existing != null) {
                handoffAndRemove(existing, msg("offer-changed"));
            }
            GeOffer record = newRecord(snapshot, "", snapshot.state);
            record.confidence = CustodyConfidence.LEGACY_UNBASED;
            record.filledQty = snapshot.quantityTraded;
            record.spentGp = nonNeg(snapshot.spent);
            records.add(record);
        }
        return bookings;
    }

    /**
     * True when every moved flow is explained by a recent offer: an item or coins lost shortly
     * after a sell or buy was placed, an item or coins gained after a buy or sell filled, or the
     * other side's cancellation. Custody is authoritative for GE economics, so a movement it could
     * not claim but an offer explains is Grand Exchange activity for Review, never counted.
     */
    synchronized boolean explains(List<Flow> flows, long now) {
        this.now = now;
        boolean moved = false;
        for (Flow flow : flows) {
            if (flow.quantityDelta != 0L) {
                moved = true;
                if (explaining(flow) == null) return false;
            }
        }
        return moved;
    }

    /** Spends the offer evidence behind these movements: one offer side explains one movement. */
    synchronized void spend(List<Flow> flows, long now) {
        this.now = now;
        for (Flow flow : flows) {
            String key = flow.quantityDelta == 0L ? null : explaining(flow);
            if (key != null) explainedAt.put(key, now);
        }
    }

    String explaining(Flow flow) {
        boolean coins = flow.itemId == ItemID.COINS;
        for (GeOffer record : records) {
            boolean buy = record.side == BUY;
            String key = record.offerId + (coins ? "$" : "");
            Long spent = explainedAt.get(key);
            long seen = record.lastSeenAtEpochMillis;
            // Only a live placement moves coins (buy) or items (sell) out of the inventory; a
            // finished
            // fill of the same side or a cancellation of the other brings them back. Passive
            // progress on an open offer explains nothing.
            boolean fits = flow.isCost() ? buy == coins && spent == null && !record.isUnbased() && !record.isCancelled()
                                    && now - record.placedAtEpochMillis <= PLACEMENT_WINDOW_MILLIS
                            : (spent == null || spent < seen) && now - seen <= COLLECTION_WINDOW_MILLIS && (buy != coins
                                            ? record.filledQty > 0L && record.isTerminal() : record.isCancelled());
            if (fits && (coins || record.itemId == flow.itemId)) return key;
        }
        return null;
    }

    // ---------------------------------------------------------------------------------------
    // Flow-level custody claims and canonical realization
    // ---------------------------------------------------------------------------------------
    /**
     * Claim custody flows from one stabilized settle. {@code itemAllowed} excludes items already
     * owned by a stronger per-item evidence source (consume/drop/loot) without weakening the
     * whole-transaction safety gates. {@code collectionEvidence} is a bounded player Collect
     * interaction; without it, collection claims need an observed terminal offer state.
     */
    synchronized Partition partition(List<Flow> incoming, long now, String sessionId, IntPredicate itemAllowed,
            boolean collectionEvidence) {
        begin(now, sessionId);
        var transfers = new ArrayList<Transaction>();
        residual = new ArrayList<>(incoming);
        claimed = new ArrayList<>();
        allowed = itemAllowed;
        // A settlement held from an earlier collect may now be exactly attributable.
        reconcilePendingSettlement();
        claimSellPlacements();
        claimBuyReserves();
        claimBuyRefunds();
        claimSellReturns();
        claimBuyCollections(collectionEvidence);
        claimSellSettlements(collectionEvidence);
        if (!claimed.isEmpty()) {
            transfers.add(new Transaction(now, TransactionType.TRANSFER, Context.TRANSFER,
                            msg("grand-exchange-custody"), "Market", false, new ArrayList<>(claimed),
                            Confidence.CONFIRMED, msg("ownership-neutral-grand"), null));
        }
        // A hold created by this settle retries immediately: a batch whose evidence is complete
        // fails closed at once instead of waiting invisibly for a later event.
        reconcilePendingSettlement();
        for (GeOffer open : records) {
            if (open.stage == OPEN && open.isReconciled()) open.stage = CLOSED;
        }
        return new Partition(residual, bookings, transfers, claimed);
    }

    /** Prune reconciled lifecycles, expire terminal-unobserved ones and cap stale records. */
    synchronized List<Transaction> maintenance(long now, String sessionId) {
        begin(now, sessionId);
        prune();
        // A held settlement retries and, once its evidence is exhausted or its bounded
        // lifecycle expires, fails closed to Review with the observed cash preserved.
        reconcilePendingSettlement();
        return bookings;
    }

    void prune() {
        int closed = 0;
        for (GeOffer record : records) {
            if (record.stage == CLOSED) closed++;
        }
        // Settled history is bounded: the oldest closed lifecycles leave first.
        for (; closed > MAX_CLOSED_RECORDS; closed--) {
            GeOffer oldest = oldestClosed();
            releaseRemaining(oldest);
            records.remove(oldest);
        }
        for (int index = records.size() - 1; index >= 0; index--) {
            GeOffer record = records.get(index);
            if (record.stage == CLOSED) continue;
            if (record.isReconciled()) {
                record.stage = CLOSED;
                continue;
            }
            // Expire by grace only a slot that is CLEARED and whose cash was never seen (a
            // collect-to-bank and similar). A SELL whose slot still shows the terminal state is
            // still in GE custody: its coins may be collected much later, so it must not expire by
            // time. BUY keeps its existing pattern (reported, not changed).
            boolean cleared = record.cleared;
            // Owner 2026-10-09: Collect to bank (or a collect while GP Manager was away) settles
            // from
            // the offer itself instead of waiting for Review; held collect cash may still be its
            // own.
            if (cleared && now - record.lastSeenAtEpochMillis > BANK_COLLECT_MILLIS && pendingSettlementCashGp <= 0L
                    && banked(record)) {
                continue;
            }
            boolean buyTerminal = record.side != SELL && record.isTerminal();
            if ((cleared || buyTerminal) && now - record.lastSeenAtEpochMillis > UNOBSERVED_GRACE_MILLIS) {
                handoffAndRemove(record, msg("settlement-observed"));
            }
        }
        slotClearedAtEpochMillis.values().removeIf(at -> now - at > UNOBSERVED_GRACE_MILLIS);
        // Spent offer evidence goes with its offer.
        var live = new HashSet<String>();
        for (GeOffer record : records) live.add(record.offerId);
        explainedAt.keySet().removeIf(key -> !live.contains(key.replace("$", "")));
    }

    // -- Custody claims: each settle offers its flows to the lifecycles, oldest placement first --
    /** One lifecycle's claim on a flow: the magnitude it takes, or 0 to pass. */
    interface ClaimStep {
        long claim(GeOffer record, Flow flow, long remaining);
    }

    /** Offers one side's trusted lifecycles a gain or loss of coins or items, oldest first. */
    void claimFlows(Side side, boolean gain, boolean coins, ClaimStep step) {
        FlowFilters.claim(residual, flow -> (gain ? flow.isGain() : flow.isCost())
                                && (flow.itemId == ItemID.COINS) == coins && (coins || allowed.test(flow.itemId)),
                (flow, magnitude) -> {
                    long remaining = magnitude;
                    for (GeOffer record : byPlacement()) {
                        if (remaining > 0L && trusted(record, side) && (coins || record.itemId == flow.itemId))
                            remaining -= nonNeg(step.claim(record, flow, remaining));
                    }
                    return magnitude - remaining;
                });
    }

    /** A lifecycle observed from its placement with no identity desync. */
    static boolean trusted(GeOffer record, Side side) {
        return record.side == side && !record.isUnbased() && record.confidence != CustodyConfidence.AMBIGUOUS;
    }

    /** SELL placement principal (item loss). */
    void claimSellPlacements() {
        claimFlows(SELL, false, false, (record, flow, remaining) -> {
                    long claim = min(remaining, record.offeredQty);
                    if (record.isCancelled() || record.cleared || record.capturedQty > 0L
                            || now - record.placedAtEpochMillis > PLACEMENT_WINDOW_MILLIS || claim <= 0L) {
                        return 0L;
                    }
                    captureBasis(record, flow);
                    if (basisLedger != null) {
                        TrackedBasisLedger.Reservation reservation = basisLedger.reserve(record.itemId, claim, now);
                        record.reservedTrackedQty = nonNeg(safeAdd(record.reservedTrackedQty, reservation.trackedQty));
                        record.reservedTrackedBasisGp =
                                nonNeg(safeAdd(record.reservedTrackedBasisGp, reservation.basisGp));
                    }
                    record.capturedQty = claim;
                    record.lastSeenAtEpochMillis = now;
                    claimed.add(flow.part(claim));
                    return claim;
                });
    }

    /** BUY observed reserve (coin loss). */
    void claimBuyReserves() {
        Set<Integer> gainItems = gainQuantities(residual, ANY).keySet();
        claimFlows(BUY, false, true, (record, flow, remaining) -> {
                    long reserve = nonNeg(record.offeredQty * record.listedPrice);
                    // Owner 1.2: an offer placed, bought and collected inside one settle shows only
                    // its exact spend, the reserve with its change already back; the purchase books
                    // it, never Review.
                    boolean instant = gainItems.contains(record.itemId) && record.isTerminal()
                                    && remaining == record.spentGp;
                    long claim = instant ? remaining : min(remaining, reserve);
                    // A same-item acquisition alongside the coin loss is a purchase, not a reserve:
                    // leave the mixed movement to the normal classification path. An offer that
                    // filled at once still took these coins; only a cancelled one kept none.
                    if (record.isCancelled() || record.cleared && !instant || record.reserveGp > 0L
                            || now - record.placedAtEpochMillis > PLACEMENT_WINDOW_MILLIS
                            || !instant && gainItems.contains(record.itemId) || claim <= 0L) {
                        return 0L;
                    }
                    record.reserveGp = instant ? reserve : nonNeg(claim);
                    if (instant) record.refundedGp = nonNeg(reserve - claim);
                    record.lastSeenAtEpochMillis = now;
                    claimed.add(flow.part(claim, 1, FACE_VALUE));
                    return claim;
                });
    }

    /** BUY refund (coin gain). */
    void claimBuyRefunds() {
        claimFlows(BUY, true, true, (record, flow, remaining) -> {
                    long refundRoom = nonNeg(record.offeredQty * record.listedPrice - record.spentGp)
                                    - record.refundedGp;
                    // An offer paid from the bank (the GE draws there once the pack runs out) never
                    // showed its reserve, yet its change still lands in the pack: as the slot
                    // clears, up to the exact change owed is the player's own coins coming back
                    // (owner live 2026-10-16: two bank-paid buys sent their change to Review).
                    Long clearedAt = slotClearedAtEpochMillis.get(record.offerId);
                    boolean bankPaid = record.reserveGp == 0L && clearedAt != null
                                    && Math.abs(now - clearedAt) <= 2 * SLOT_WINDOW_MILLIS;
                    long claim = min(remaining, min(nonNeg(refundRoom),
                                            bankPaid ? refundRoom : record.reserveOutstanding()));
                    // Change is owed once the offer is finished (bought or cancelled) or its slot
                    // cleared.
                    if (!(record.isTerminal() || record.cleared) || claim <= 0L) return 0L;
                    record.refundedGp = nonNeg(safeAdd(record.refundedGp, claim));
                    claimed.add(flow.part(claim, 1, FACE_VALUE));
                    return claim;
                });
    }

    /**
     * An old Review row for coins a bank-paid buy gave back (before 1.5.1 that change went to
     * Review): the latest such buy placed before it that still owes at least that change takes it
     * (owner live 2026-10-16).
     */
    synchronized boolean claimOldChange(long gp, long at) {
        GeOffer match = null;
        for (GeOffer record : records) {
            if (record.side == BUY && record.reserveGp == 0L && (record.isTerminal() || record.cleared)
                    && record.placedAtEpochMillis <= at && at - record.placedAtEpochMillis <= COLLECTION_WINDOW_MILLIS
                    && nonNeg(record.offeredQty * record.listedPrice - record.spentGp) - record.refundedGp
                            >= gp && (match == null || record.placedAtEpochMillis > match.placedAtEpochMillis))
                match = record;
        }
        if (match == null) return false;
        match.refundedGp = safeAdd(match.refundedGp, gp);
        return true;
    }

    /** SELL cancellation return (item gain). */
    void claimSellReturns() {
        claimFlows(SELL, true, false, (record, flow, remaining) -> {
                    long claim = min(remaining, record.heldQty());
                    if (!(record.isCancelled() || record.cleared) || claim <= 0L) return 0L;
                    releaseShare(record, claim);
                    record.returnedQty = safeAdd(record.returnedQty, claim);
                    // The returned principal is neutral at its frozen custody basis, never the
                    // current live quote; with no frozen basis it stays the observed movement.
                    claimed.add(record.basisUnitPrice > 0L ? flow.part(
                                            claim, record.basisUnitPrice, record.getBasisSource()) : flow.part(claim));
                    return claim;
                });
    }

    /** BUY collection (item gain). */
    void claimBuyCollections(boolean collectionEvidence) {
        claimFlows(BUY, true, false, (record, flow, remaining) -> {
                    long claim = min(remaining, record.pendingQty());
                    // Passive progress alone never turns a same-item delta into a collection.
                    if (record.quantityModified || claim <= 0L
                            || !(collectionEvidence || record.isTerminal() || record.cleared)) {
                        return 0L;
                    }
                    if (record.basisSource == null) captureBasis(record, flow);
                    record.collectedQty = nonNeg(safeAdd(record.collectedQty, claim));
                    record.collectedValueGp = safeAdd(record.collectedValueGp,
                                    SafeMath.safeMultiply(claim, flow.unitPrice));
                    record.lastSeenAtEpochMillis = now;
                    claimed.add(flow.part(claim));
                    if (record.collectedQty < record.filledQty) {
                        // Partial collection: execution chunks are not attributable; fail closed.
                        record.collectionAmbiguous = true;
                    } else {
                        bookBuySettlement(record);
                    }
                    return claim;
                });
    }

    void bookBuySettlement(GeOffer record) {
        long settleQty = record.collectedQty - record.settledQty;
        long execution = record.pendingExecution();
        if (settleQty <= 0L) return;
        boolean clean = isCleanRealization(record);
        var flows = new ArrayList<Flow>(2);
        // Exact NEW-model BUY: the asset value equals the actual settled spend, so acquisition is
        // Net-neutral and the acquired quantity becomes known coverage at that exact spend.
        flows.add(itemFlow(record, settleQty, execution / settleQty, execution));
        flows.add(coins(-execution));
        settled(record, buildMarket(flows, clean, clean, msg("grand-exchange-purchase")), settleQty, execution,
                execution);
        record.collectedQty = nonNeg(record.settledQty);
        record.collectedValueGp = 0L;
    }

    Flow coins(long amount) {
        return new Flow(ItemID.COINS, "Coins", amount, 1, amount, FACE_VALUE, now);
    }

    /** One flow of the offer's item, carrying its frozen basis source and capture time. */
    static Flow itemFlow(GeOffer record, long quantity, long unitPrice, long value) {
        return new Flow(record.itemId, record.itemName, quantity, toInt(unitPrice), value, record.getBasisSource(),
                record.basisCapturedAtEpochMillis);
    }

    /** An uncounted Market row left for Review: the observed movement, never a guess. */
    Transaction reviewRow(List<Flow> flows, String explanation) {
        return new Transaction(now, UNCERTAIN, MARKET, "Grand Exchange", "Market", false, flows, Confidence.UNCERTAIN,
                explanation, null);
    }

    /** Claims a whole coin gain as held or settled GE cash. */
    long claimWhole(Flow flow) {
        claimed.add(flow.part(flow.valueDelta, 1, FACE_VALUE));
        return flow.valueDelta;
    }

    // -- SELL collection (coin gain) ----------------------------------------------------------
    /**
     * Attribute one observed collect coin movement to exactly the sold offers it proves.
     *
     * <p>Exact integer equality only: a movement settles a subset when the subset's observed
     * after-tax nets sum to it exactly. The slot-clear set is the primary proof; otherwise the
     * unique matching subset is confirmed by slot evidence within the SLOT WINDOW or, with no
     * contradicting evidence, at the window end. Ties and unprovable evidence fail closed: only
     * slot-evidenced candidates may be quarantined, and every other candidate stays pending for a
     * later exact collect.
     */
    void claimSellSettlements(boolean collectionEvidence) {
        if (!collectionEvidence) {
            // A coin gain with no Collect interaction settles a waiting sale only when it is
            // that whole sale, less at most its tax.
            claimSellsWithoutCollect();
            return;
        }
        FlowFilters.claim(residual, flow -> flow.isGain() && flow.itemId == ItemID.COINS, (flow, magnitude) -> {
                    long cashGp = flow.valueDelta;
                    List<GeOffer> candidates = settlementCandidates(true);
                    // Coins may arrive before the offer's execution/terminal evidence. A live
                    // Collect interaction with a captured sell lifecycle still pending is that
                    // settlement's cash; with no candidate yet it is held below (an empty set
                    // attributes to NONE) instead of letting an unresolved Coins row reach Review.
                    // The bounded hold retries as offer evidence arrives.
                    if (candidates.isEmpty() && (cashGp <= 0L || !hasPendingSellEvidence()))
                        return 0L;
                    Attribution attribution = attribute(candidates, cashGp, now);
                    if (attribution.kind == AttributionKind.SETTLE) {
                        settleAttributed(attribution.records, cashGp);
                        return claimWhole(flow);
                    }
                    if (!attribution.contradicted) {
                        // Exact-but-unconfirmed, tied, or unmatched evidence: retain the observed
                        // cash
                        // transiently. The SLOT WINDOW gathers the slot evidence a fail-closed
                        // decision
                        // needs; while a sell can still receive execution evidence, the existing
                        // long hold
                        // keeps waiting for it.
                        holdCash(cashGp);
                        pendingSettlementAwaitingEvidence |= attribution.kind == AttributionKind.NONE
                                        && hasPendingSellEvidence();
                        return claimWhole(flow);
                    }
                    // No exact attribution: only candidates with slot evidence in this interaction
                    // may be
                    // quarantined. The unattributed movement follows the ordinary path to one
                    // uncounted
                    // Review Coins row; every other candidate stays pending for a later exact
                    // collect.
                    quarantineAmbiguous(attribution.quarantinable);
                    return 0L;
                });
    }

    /**
     * Booking for a coin gain with no Collect interaction (the click fell outside its window): only
     * a gain between the whole waiting sale and that sale less its largest possible tax settles it.
     */
    void claimSellsWithoutCollect() {
        FlowFilters.claim(residual, flow -> flow.isGain() && flow.itemId == ItemID.COINS, (flow, magnitude) -> {
                    List<GeOffer> candidates = settlementCandidates(false);
                    long totalExecution = 0L;
                    for (GeOffer record : candidates)
                        totalExecution = safeAdd(totalExecution, record.pendingExecution());
                    long original = flow.valueDelta;
                    // Without a Collect click only the whole waiting sale, less at most its GE
                    // tax (2%), can explain the coins: an alch or a shop sale never claims it.
                    if (original > totalExecution || original < totalExecution - totalExecution / 50) return 0L;
                    long claimCash = min(original, totalExecution);
                    if (claimCash <= 0L) return 0L;
                    if (candidates.size() > 1) {
                        boolean allClean = true;
                        boolean allKnownCoverage = true;
                        long expectedTax = 0L;
                        for (GeOffer record : candidates) {
                            allClean &= isCleanRealization(record);
                            allKnownCoverage &= record.reservedQty() >= record.pendingQty();
                            // Candidate fee only: the aggregate observed cash must confirm the
                            // exact combined gap.
                            expectedTax = safeAdd(expectedTax, nonNeg(pendingSellTax(record)));
                        }
                        boolean taxAttributed = expectedTax > 0L && totalExecution - claimCash == expectedTax;
                        if (!taxAttributed && (expectedTax > 0L || claimCash != totalExecution) && !allKnownCoverage) {
                            allClean = false;
                            for (GeOffer record : candidates) record.collectionAmbiguous = true;
                        }
                        // An exact batch books each offer's after-tax share of the observed cash;
                        // any
                        // other batch books gross execution and an adjustment row for the
                        // difference.
                        long allocated = 0L;
                        for (GeOffer record : candidates) {
                            long settleQty = record.pendingQty();
                            long execution = record.pendingExecution();
                            if (settleQty > 0L && execution > 0L) {
                                long cash = taxAttributed ? execution - nonNeg(pendingSellTax(record)) : execution;
                                bookSellSettlement(record, settleQty, cash, execution, allClean);
                                allocated = safeAdd(allocated, cash);
                            }
                        }
                        if (claimCash != allocated) {
                            // Legacy (non-collect) batch adjustment row; collect interactions never
                            // produce one.
                            bookings.add(new Transaction(now, allClean ? TRADE : UNCERTAIN, MARKET,
                                            msg("grand-exchange-settlement"), "Market", allClean,
                                            singletonList(coins(claimCash - allocated)),
                                            allClean ? Confidence.CONFIRMED : Confidence.UNCERTAIN,
                                            msg("grand-exchange-batch"), null));
                        }
                    } else {
                        GeOffer record = candidates.get(0);
                        long execution = record.pendingExecution();
                        boolean over = original > execution;
                        record.collectionAmbiguous = record.collectionAmbiguous || over;
                        bookSellSettlement(record, record.pendingQty(), over ? execution : claimCash, execution,
                                !over && isCleanRealization(record));
                    }
                    claimed.add(flow.part(claimCash, 1, FACE_VALUE));
                    return claimCash;
                });
    }

    /**
     * Book one exactly attributed subset at each offer's own observed after-tax cash. A sale that
     * filled at several prices in one observed chunk has a tax range, not one tax: the observed
     * cash proves the subset's total, so each such offer pays its lowest possible tax plus, in
     * order, the rest up to its highest (owner 2026-10-08: a big mixed-price sale is no Review).
     */
    void settleAttributed(List<GeOffer> records, long cash) {
        boolean allClean = true;
        for (GeOffer record : records) {
            allClean &= isCleanRealization(record);
            long[] net = net(record);
            if (net != null) cash -= net[1];
        }
        // The tax beyond every offer's lowest possible tax.
        cash = -cash;
        for (GeOffer record : records) {
            long[] net = net(record);
            // An offer with no execution is never part of a match; the attribution excluded it.
            if (net == null) continue;
            long execution = record.pendingExecution();
            long extra = max(0L, min(net[1] - net[0], cash));
            cash -= extra;
            long tax = execution - net[1] + extra;
            if (pendingSellTax(record) < 0L) {
                // The cash proved it: later reads (the receipt, a restart) see this exact tax.
                record.fillTaxExact = true;
                record.fillTaxGp = safeAdd(record.settledTaxGp, tax);
            }
            bookSellSettlement(record, record.pendingQty(), execution - tax, execution, allClean);
        }
    }

    /**
     * The pending execution's possible after-tax cash {lowest, highest}, or null with no execution.
     * Exact when its tax is proven; otherwise each item paid price/50 rounded down, so the stack
     * paid at most gross/50 and at least (gross - 49 per item)/50 (below the 5M per-item cap).
     */
    static long[] net(GeOffer record) {
        long execution = record.pendingExecution();
        long quantity = record.pendingQty();
        long tax = pendingSellTax(record);
        if (execution <= 0L || quantity <= 0L) return null;
        if (tax >= 0L) return new long[] {execution - tax, execution - tax};
        long least = execution >= 250_000_000L ? 0L : max(0L, (execution - 49L * quantity + 49L) / 50L);
        return new long[] {execution - execution / 50L, execution - least};
    }

    /**
     * Fail closed on the slot-evidenced candidates only. The quarantine booking keeps today's shape
     * (uncounted, collectionAmbiguous, the booked allocation recorded) while the observed cash
     * itself is never assigned to a lifecycle it was not proven part of.
     */
    void quarantineAmbiguous(List<GeOffer> quarantinable) {
        for (GeOffer record : quarantinable) {
            long settleQty = record.pendingQty();
            long execution = record.pendingExecution();
            if (settleQty > 0L && execution > 0L) {
                record.collectionAmbiguous = true;
                bookSellSettlement(record, settleQty, execution, execution, false);
            }
        }
    }

    /** Candidate sell lifecycles for one coin gain; the retry needs durable terminal evidence. */
    List<GeOffer> settlementCandidates(boolean collectionEvidence) {
        var candidates = new ArrayList<GeOffer>();
        for (GeOffer record : byPlacement()) {
            if (record.side == SELL && record.pendingQty() > 0L && record.capturedQty > 0L
                    && record.settleableQty() >= record.pendingQty() && !record.isUnbased()
                    && (collectionEvidence || record.isTerminal() || record.cleared)) {
                candidates.add(record);
            }
        }
        return candidates;
    }

    /** Retain observed collect cash transiently; the SLOT WINDOW anchors on the first hold. */
    void holdCash(long cashGp) {
        if (cashGp <= 0L) return;
        if (pendingSettlementCashGp <= 0L) pendingSettlementHeldSinceEpochMillis = now;
        pendingSettlementCashGp = safeAdd(pendingSettlementCashGp, cashGp);
        pendingSettlementAtEpochMillis = max(pendingSettlementAtEpochMillis, now);
    }

    /** Exact attribution of one collect coin movement over the current candidate set. */
    Attribution attribute(List<GeOffer> candidates, long cashGp, long coinAt) {
        int size = candidates.size();
        var quarantinable = new ArrayList<GeOffer>();
        if (size <= 0 || size > MAX_SETTLEMENT_CANDIDATES) {
            return new Attribution(AttributionKind.NONE, quarantinable, quarantinable, false);
        }
        // Each candidate's possible after-tax cash: one value, or a range for a mixed-price fill.
        long[][] nets = new long[size][];
        var cleared = new ArrayList<Integer>();
        for (int index = 0; index < size; index++) {
            GeOffer record = candidates.get(index);
            nets[index] = net(record);
            Long clearedAt = slotClearedAtEpochMillis.get(record.offerId);
            // The candidate's slot cleared within the SLOT WINDOW of the coin gain.
            if (clearedAt != null && Math.abs(clearedAt - coinAt) <= SLOT_WINDOW_MILLIS) {
                cleared.add(index);
                quarantinable.add(record);
            }
        }
        // Apply slot evidence only after enumerating every subset within the eight-offer bound.
        List<List<Integer>> matches = matchingSubsets(nets, cashGp, 1 << size);
        List<Integer> match = null;
        AttributionKind kind = AttributionKind.NONE;
        boolean contradicted = false;
        if (matches.contains(cleared)) {
            // §2.1: the slot-clear set is the primary proof; a single candidate has no competing
            // explanation either, so neither needs slot confirmation (an amount it cannot have
            // received, or an execution with no known price, still fails closed below).
            kind = AttributionKind.SETTLE;
            match = cleared;
        } else if (size == 1 && !matches.isEmpty()) {
            kind = AttributionKind.SETTLE;
            match = matches.get(0);
        } else if (matches.size() > 1) {
            // §2.3: slot evidence may still select exactly one matching subset.
            matches.removeIf(subset -> !subset.containsAll(cleared));
            contradicted = !cleared.isEmpty() && matches.isEmpty();
            kind = contradicted ? AttributionKind.NONE
                            : matches.size() == 1 ? AttributionKind.SETTLE : AttributionKind.TIE;
            match = matches.size() == 1 ? matches.get(0) : null;
        } else if (matches.size() == 1) {
            // A unique match settles when the slot-clear set is exactly it, needs confirmation
            // while
            // no slot outside it cleared, and §2.2: a slot cleared outside it contradicts it.
            match = matches.get(0);
            contradicted = !match.containsAll(cleared);
            kind = match.equals(cleared) ? AttributionKind.SETTLE
                            : contradicted ? AttributionKind.NONE : AttributionKind.CONFIRM;
        }
        var records = new ArrayList<GeOffer>();
        for (int index : match == null || contradicted ? Collections.<Integer>emptyList() : match) {
            records.add(candidates.get(index));
        }
        return new Attribution(kind, records, quarantinable, contradicted);
    }

    /**
     * Subset enumeration over candidates with a known execution: a subset matches when the cash
     * lies within its summed {lowest, highest} after-tax cash. Saturating sums, deterministic index
     * order, at most {@code limit} matches. Returns empty when the candidate bound is exceeded, so
     * an over-full interaction can never be enumerated.
     */
    static List<List<Integer>> matchingSubsets(long[][] nets, long cashGp, int limit) {
        int size = nets == null ? 0 : nets.length;
        var matches = new ArrayList<List<Integer>>();
        if (size <= 0 || size > MAX_SETTLEMENT_CANDIDATES) {
            return matches;
        }
        for (int mask = 1; mask < 1 << size && matches.size() < limit; mask++) {
            long least = 0L;
            long most = 0L;
            var subset = new ArrayList<Integer>();
            for (int index = 0; index < size && least >= 0L; index++) {
                if ((mask & (1 << index)) != 0) {
                    subset.add(index);
                    least = nets[index] == null ? -1L : safeAdd(least, nets[index][0]);
                    most = nets[index] == null ? most : safeAdd(most, nets[index][1]);
                }
            }
            if (least >= 0L && least <= cashGp && cashGp <= most) matches.add(subset);
        }
        return matches;
    }

    /** Attribution outcome kinds; names are conceptual, not persisted. */
    enum AttributionKind {
        /** An exact subset is proven and may be settled now. */
        SETTLE,
        /** The unique exact subset needs slot confirmation (or the window end). */
        CONFIRM,
        /** More than one exact subset matches; slot evidence must select one. */
        TIE,
        /** No exact attribution exists. */
        NONE
    }

    @AllArgsConstructor
    static class Attribution {
        AttributionKind kind;
        List<GeOffer> records;
        List<GeOffer> quarantinable;
        boolean contradicted;
    }

    /** True while an observed sell lifecycle can still receive execution/terminal evidence. */
    boolean hasPendingSellEvidence() {
        for (GeOffer record : records) {
            if (record.side == SELL && record.capturedQty > 0L && !record.isUnbased() && !record.isTerminal()
                    && !record.cleared) {
                return true;
            }
        }
        return false;
    }

    /**
     * Retry a held collect under the one attribution law. An exact subset settles as soon as the
     * evidence (or the SLOT WINDOW) confirms it; a tie, a contradiction, or exhausted evidence
     * fails closed to Review, never distributed by guesswork.
     */
    void reconcilePendingSettlement() {
        if (pendingSettlementCashGp <= 0L) return;
        // The held cash IS a collect interaction, so the retry sees the same candidate set that
        // interaction saw (still-active sells whose fills may still be collected included).
        Attribution attribution = attribute(settlementCandidates(true), pendingSettlementCashGp,
                        pendingSettlementHeldSinceEpochMillis);
        boolean windowClosed = now - pendingSettlementHeldSinceEpochMillis > SLOT_WINDOW_MILLIS;
        // §2.2b: a unique match settles at the window end with no contradicting slot evidence; the
        // existing long hold also books as soon as its missing execution evidence completes.
        if (attribution.kind == AttributionKind.SETTLE || attribution.kind == AttributionKind.CONFIRM
                        && (windowClosed || pendingSettlementAwaitingEvidence)) {
            settleAttributed(attribution.records, pendingSettlementCashGp);
            clearPendingSettlement();
            return;
        }
        // §2.2 contradiction, §2.3 an unresolved tie, and §2.4/§3 exhausted evidence fail closed:
        // only slot-evidenced candidates are quarantined and the held cash goes to Review.
        if (attribution.contradicted || now - pendingSettlementAtEpochMillis > UNOBSERVED_GRACE_MILLIS
                || attribution.kind == AttributionKind.TIE && windowClosed || attribution.kind == AttributionKind.NONE
                        && (pendingSettlementAwaitingEvidence ? !hasPendingSellEvidence() : windowClosed)) {
            quarantineAmbiguous(attribution.quarantinable);
            releasePendingSettlement();
        }
    }

    /** Releases a held collect to Review at the time it was held; returns that row. */
    synchronized List<Transaction> releaseHeldCollect() {
        begin(pendingSettlementAtEpochMillis, sessionId);
        releasePendingSettlement();
        return bookings;
    }

    /** Fail closed: the observed cash stays visible as an uncounted Review row, never guessed. */
    void releasePendingSettlement() {
        long held = pendingSettlementCashGp;
        clearPendingSettlement();
        if (held <= 0L) return;
        bookings.add(reviewRow(singletonList(coins(held)), msg("grand-exchange-collection")));
    }

    void bookSellSettlement(GeOffer record, long settleQty, long cashValue, long execution, boolean clean) {
        long remainingQty = record.reservedQty();
        long remainingBasis = record.reservedBasis();
        long knownQty = min(settleQty, remainingQty);
        long knownBasis = BasisMath.shareOf(remainingQty, remainingBasis, knownQty);
        long knownProceeds = BasisMath.knownProceedsOf(cashValue, settleQty, knownQty);
        boolean fullyUnknown = knownQty <= 0L;
        record.consumedTrackedQty = safeAdd(record.consumedTrackedQty, knownQty);
        record.consumedTrackedBasisGp = safeAdd(record.consumedTrackedBasisGp, knownBasis);
        if (basisLedger != null) {
            // The realized quantity left ownership even when it carried no known coverage; the
            // per-item realization fence always advances.
            basisLedger.fenceRealized(record.itemId, now);
        }
        // The one shared accepted-tax predicate: this settlement's observed gross execution against
        // its actual Received cash. Only an exact per-item match counts; the tax is never inferred
        // from a reference, a guide price or a difference.
        long provenTax = pendingSellTax(record);
        long acceptedTax = fullyUnknown && clean && provenTax > 0L && execution - cashValue == provenTax ? provenTax
                        : 0L;
        boolean knownCostOnly = acceptedTax > 0L;
        var flows = new ArrayList<Flow>(2);
        if (knownCostOnly) {
            // Fully unknown prior value with a PROVEN tax: the departing item flow is valued at
            // the observed gross execution (not at the frozen reference) against the observed
            // Received cash, so the counted automatic Net is exactly -accepted tax — a market
            // trade cost. Result stays unknown: the accumulator below receives no result here, and
            // a later correction replaces this contribution instead of stacking on it.
            long unit = execution / settleQty;
            flows.add(itemFlow(record, -settleQty, unit, -execution));
            flows.add(coins(cashValue));
        } else if (fullyUnknown) {
            // Unknown coverage without a proven tax: the full observed movement stays as
            // liquidation evidence and is Net-neutral. It is never a fake cost and never
            // automatic profit.
            flows.add(itemFlow(record, -settleQty, record.basisUnitPrice, -record.basisFor(settleQty)));
            flows.add(coins(cashValue));
        } else {
            if (knownBasis > 0L) {
                long unit = knownQty > 0L ? knownBasis / knownQty : 0L;
                flows.add(itemFlow(record, -settleQty, unit, -knownBasis));
            }
            flows.add(coins(knownProceeds));
        }
        String explanation = knownCostOnly ? msg("grand-exchange-sale-settled-proven") : fullyUnknown
                                ? msg("grand-exchange-sale-settled") : knownQty < settleQty
                                        ? msg("grand-exchange-sale-settled-quantity") : msg("grand-exchange-sale");
        // Counted when the lifecycle is exact AND either the realized quantity carries known
        // coverage
        // or the actual GE tax is proven. An unknown sale without a proven tax stays an exact,
        // uncounted evidence row (liquidation cash retained, Net-neutral, never a Review nag).
        if (provenTax >= 0L) record.settledTaxGp = nonNeg(safeAdd(record.settledTaxGp, provenTax));
        record.realizedResultGp = safeAdd(record.realizedResultGp, knownProceeds - knownBasis);
        settled(record, buildMarket(flows, clean, clean && (!fullyUnknown || knownCostOnly), explanation), settleQty,
                execution, cashValue);
    }

    /** Books one settlement row and advances the offer's settled counters by what it booked. */
    void settled(GeOffer record, Transaction row, long quantity, long execution, long cash) {
        bookings.add(row);
        record.settledQty = safeAdd(record.settledQty, quantity);
        record.settledExecutionGp = safeAdd(record.settledExecutionGp, execution);
        record.settledCashGp = safeAdd(record.settledCashGp, cash);
        record.setSettlementId(row.getId());
    }

    /** Return an unconsumed reservation share when custody returns or retires a lifecycle. */
    void releaseShare(GeOffer record, long returnedQty) {
        if (returnedQty <= 0L) return;
        long remainingQty = record.reservedQty();
        long remainingBasis = record.reservedBasis();
        if (remainingQty <= 0L && remainingBasis <= 0L) return;
        long releaseQty = min(returnedQty, remainingQty);
        long releaseBasis = BasisMath.shareOf(remainingQty, remainingBasis, releaseQty);
        if (basisLedger != null && (releaseQty > 0L || releaseBasis > 0L)) {
            basisLedger.release(record.itemId, releaseQty, releaseBasis);
        }
        record.reservedTrackedQty = nonNeg(max(record.consumedTrackedQty, record.reservedTrackedQty - releaseQty));
        record.reservedTrackedBasisGp = nonNeg(max(record.consumedTrackedBasisGp,
                                record.reservedTrackedBasisGp - releaseBasis));
    }

    /** Release every still-unrealized reserved share when a lifecycle leaves custody state. */
    void releaseRemaining(GeOffer record) {
        if (record == null) return;
        releaseShare(record, max(record.reservedQty(), record.reservedBasis()));
    }

    // ---------------------------------------------------------------------------------------
    // Builders
    // ---------------------------------------------------------------------------------------
    /**
     * One Market row: exact lifecycles book as trades, anything else stays uncounted for review.
     */
    Transaction buildMarket(List<Flow> flows, boolean exact, boolean countsInNet, String explanation) {
        return new Transaction(now, exact ? TRADE : UNCERTAIN, MARKET, "Grand Exchange", "Market", countsInNet, flows,
                exact ? Confidence.CONFIRMED : Confidence.UNCERTAIN, exact ? explanation : explanation
                                + msg("lifecycle-could-settled-exactly") + msg("stays-uncounted"), null);
    }

    boolean isCleanRealization(GeOffer record) {
        if (record.isUnbased() || record.confidence == CustodyConfidence.AMBIGUOUS || record.quantityModified
                || record.collectionAmbiguous || !record.hasFrozenBasis()) {
            return false;
        }
        if (record.originSessionId.isEmpty() && sessionId != null && !sessionId.isEmpty()) {
            record.originSessionId = Phrases.orEmpty(sessionId);
        }
        // Owner policy (2026-09-24, replaces PRE-R5B 11.19): a settlement books in the session
        // where it is collected; the listing session is kept for the "Listed during" label only
        // and is never rewritten.
        return true;
    }

    /**
     * Accumulate one observed fill. A SELL chunk's tax is exact only when its own per-item price is
     * proven (spent divisible by quantity, or an exempt item); otherwise per-fill tax is lost for
     * this lifecycle and the uniform rule over the total remains the only proof.
     */
    static void recordFill(GeOffer record, long quantity, long spent) {
        record.filledQty = safeAdd(record.filledQty, quantity);
        record.spentGp = safeAdd(record.spentGp, spent);
        if (record.side != SELL || !record.fillTaxExact || quantity <= 0L) return;
        long chunkTax = GeTaxRule.provableTax(record.itemId, spent, quantity);
        if (chunkTax < 0L) {
            record.fillTaxExact = false;
            return;
        }
        record.fillTaxGp = nonNeg(safeAdd(record.fillTaxGp, chunkTax));
    }

    /**
     * The exact GE tax of a SELL's pending (filled, unsettled) execution, or {@link
     * GeTaxRule#UNPROVABLE_TAX}. Per-fill tax wins when every fill was observed at a provable
     * price, since fills at different prices pay different per-item tax; otherwise the uniform rule
     * over the pending total applies.
     */
    static long pendingSellTax(GeOffer record) {
        long execution = record.pendingExecution();
        long quantity = record.pendingQty();
        if (record.fillTaxExact && execution > 0L && quantity > 0L) {
            long tax = record.fillTaxGp - record.settledTaxGp;
            return tax >= 0L && tax <= execution ? tax : GeTaxRule.UNPROVABLE_TAX;
        }
        return GeTaxRule.provableTax(record.itemId, execution, quantity);
    }

    // ---------------------------------------------------------------------------------------
    // Persistence / lifecycle
    // ---------------------------------------------------------------------------------------
    synchronized void writeTo(SavedState state) {
        if (state != null) state.setGeCustody(new ArrayList<>(records));
    }

    synchronized void restore(SavedState state, long now) {
        reset();
        if (state == null) return;
        // One live lifecycle per slot (its newest record); settled CLOSED history is kept as well.
        var newestBySlot = new HashMap<Integer, GeOffer>();
        var closedByOffer = new LinkedHashMap<String, GeOffer>();
        for (GeOffer record : state.getGeCustody()) {
            if (record == null || record.offerId.isEmpty()) continue;
            if (record.stage == CLOSED) closedByOffer.put(record.offerId, record);
            GeOffer existing = newestBySlot.get(record.slot);
            if (existing == null || record.placedAtEpochMillis >= existing.placedAtEpochMillis) {
                newestBySlot.put(record.slot, record);
            }
        }
        for (GeOffer record : newestBySlot.values()) closedByOffer.remove(record.offerId);
        records.addAll(newestBySlot.values());
        records.addAll(closedByOffer.values());
        records.sort((left, right) -> Long.compare(left.placedAtEpochMillis, right.placedAtEpochMillis));
    }

    /** Destructive reset: custody state is financial continuity state and clears with it. */
    synchronized void reset() {
        records.clear();
        baselines.clear();
        replacedSlots.clear();
        explainedAt.clear();
        loginClearedAtEpochMillis.clear();
        clearPendingSettlement();
    }

    /** Adopt another ledger's durable records during a staged profile swap. */
    synchronized void adoptFrom(GeCustodyLedger other) {
        reset();
        if (other != null) records.addAll(other.records);
    }

    synchronized List<GeOffer> records() {
        return unmodifiableList(new ArrayList<>(records));
    }

    /**
     * Drop any transient held collect and slot-clear evidence; durable lifecycles are untouched.
     */
    synchronized void clearPendingSettlement() {
        pendingSettlementCashGp = 0L;
        pendingSettlementAtEpochMillis = 0L;
        pendingSettlementHeldSinceEpochMillis = 0L;
        pendingSettlementAwaitingEvidence = false;
        slotClearedAtEpochMillis.clear();
    }

    // ---------------------------------------------------------------------------------------
    // Internals
    // ---------------------------------------------------------------------------------------
    List<GeOffer> byPlacement() {
        var sorted = new ArrayList<GeOffer>(records);
        sorted.sort((left, right) -> {
                    int byTime = Long.compare(left.placedAtEpochMillis, right.placedAtEpochMillis);
                    return byTime != 0 ? byTime : Integer.compare(left.slot, right.slot);
                });
        return sorted;
    }

    /** The slot's live lifecycle; settled (CLOSED) history never owns a slot. */
    GeOffer forSlot(int slot) {
        for (GeOffer record : records) {
            if (record.slot == slot && record.stage != CLOSED) return record;
        }
        return null;
    }

    GeOffer latestClosed(int slot) {
        GeOffer latest = null;
        for (GeOffer record : records) {
            if (record.slot == slot && record.stage == CLOSED && (latest == null
                            || record.placedAtEpochMillis >= latest.placedAtEpochMillis)) {
                latest = record;
            }
        }
        return latest;
    }

    GeOffer oldestClosed() {
        GeOffer oldest = null;
        for (GeOffer record : records) {
            if (record.stage == CLOSED && (oldest == null || record.placedAtEpochMillis < oldest.placedAtEpochMillis)) {
                oldest = record;
            }
        }
        return oldest;
    }

    /**
     * The slot's live lifecycle for an offer (any side or item when unknown), falling back to its
     * latest settled history; marks it seen.
     */
    GeOffer touch(int slot, Snapshot offer) {
        Side side = offer == null ? null : OfferSlots.sideOf(offer.state);
        int itemId = offer == null ? 0 : offer.itemId;
        GeOffer match = null;
        for (GeOffer record : records) {
            if (record.slot != slot || side != null && side != record.side || itemId > 0 && record.itemId != itemId) {
                continue;
            }
            if (record.stage != CLOSED) {
                match = record;
                break;
            }
            if (match == null || record.placedAtEpochMillis >= match.placedAtEpochMillis)
                match = record;
        }
        if (match != null) match.lastSeenAtEpochMillis = now;
        return match;
    }

    boolean isSameIdentity(GeOffer record, Side side, int itemId, long totalQty, long price) {
        return record.side == side && record.itemId == itemId && record.offeredQty == totalQty
                && record.listedPrice == price;
    }

    /**
     * The slot cleared but its cash or items never reached the inventory: they went to the bank.
     * The offer itself proves what filled and what it cost, so it settles as if collected. A buy is
     * exact; a sale pays its proven tax or, filled at several prices, the highest tax it could have
     * paid, so its result is never overstated. What never sold, or was never spent, went too. False
     * leaves an untrusted or unobserved lifecycle to the Review handoff.
     */
    boolean banked(GeOffer record) {
        boolean sell = record.side == SELL;
        if (!sell && record.basisSource == null && record.pendingQty() > 0L) {
            // A bought item never seen has no market quote: its own execution is its basis.
            record.basisUnitPrice = record.pendingExecution() / record.pendingQty();
            record.basisSource = PriceSource.GRAND_EXCHANGE;
            record.basisCapturedAtEpochMillis = now;
        }
        if (sell && record.capturedQty <= 0L || !isCleanRealization(record)) return false;
        if (sell) {
            long[] net = net(record);
            if (net != null) {
                // The lowest after-tax cash it could have received, as an exact one-offer collect.
                boolean estimated = pendingSellTax(record) < 0L;
                settleAttributed(singletonList(record), net[0]);
                if (estimated) bookings.get(bookings.size() - 1).explanation += msg("gbank");
            }
            long unsold = record.heldQty();
            releaseShare(record, unsold);
            record.returnedQty = safeAdd(record.returnedQty, unsold);
        } else {
            record.collectedQty = nonNeg(record.filledQty);
            bookBuySettlement(record);
            record.refundedGp = nonNeg(safeAdd(record.refundedGp, record.reserveOutstanding()));
        }
        if (record.isReconciled()) record.stage = CLOSED;
        return true;
    }

    void handoffAndRemove(GeOffer record, String reason) {
        releaseRemaining(record);
        Transaction review = reviewHandoff(record, reason);
        if (review != null) bookings.add(review);
        records.remove(record);
    }

    Transaction reviewHandoff(GeOffer record, String reason) {
        if (record.isUnbased()) return null;
        boolean buy = record.side == BUY;
        if (!buy && record.capturedQty <= 0L) {
            // The principal was never observed entering custody; its movements follow the
            // ordinary classification path and must not be surfaced twice.
            return null;
        }
        long unsettledQty = buy ? record.pendingQty() : record.settleableQty();
        long execution = record.pendingExecution();
        if (unsettledQty <= 0L && execution <= 0L) return null;
        var flows = new ArrayList<Flow>(2);
        long unit = record.basisUnitPrice;
        if (unsettledQty > 0L) {
            long value = buy && record.collectedValueGp != 0L ? SafeMath.abs(record.collectedValueGp)
                            : record.basisFor(unsettledQty);
            flows.add(itemFlow(record, buy ? unsettledQty : -unsettledQty, unit, buy ? value : -value));
        }
        if (execution > 0L) flows.add(coins(buy ? -execution : execution));
        return reviewRow(flows, msg("grand-exchange-lifecycle") + reason + msg("known-facts"));
    }

    void captureBasis(GeOffer record, Flow flow) {
        PriceSource source = flow.getPriceSource();
        record.basisUnitPrice = nonNeg(flow.unitPrice);
        record.basisSource = source == null ? UNKNOWN : source;
        record.basisCapturedAtEpochMillis = now;
    }

    /** Presentation/audit source name; never used for matching. */
}

/**
 * Slot-keyed, observation-only record of the Grand Exchange offer state exposed by RuneLite. It
 * screens duplicate snapshots and hands each real change to custody as a previous/current pair; it
 * assigns no financial meaning to any field and never books anything.
 *
 * <p>Call {@link #beginSeed()} before processing RuneLite's login slot replay. Snapshots received
 * until {@link #finishSeed()} establish baselines and produce no transitions. On relog, starting
 * another seed clears old slot state so the replay cannot look like new activity.
 */
@Singleton
class OfferSlots {
    Map<Integer, Snapshot> bySlot = new LinkedHashMap<>();
    boolean loginSeed;

    /**
     * Begin a login/relogin baseline pass; all observations are suppressed until it is finished.
     */
    synchronized void beginSeed() {
        bySlot.clear();
        loginSeed = true;
    }

    /** Finish the baseline pass after the caller has received the initial offer-slot replay. */
    synchronized void finishSeed() {
        loginSeed = false;
    }

    /**
     * Observe one immutable slot snapshot. Repeated identical snapshots, a first empty slot and all
     * login-seed observations return an empty Optional.
     */
    synchronized Optional<Transition> observe(Snapshot current) {
        Objects.requireNonNull(current, "current");
        Snapshot previous = bySlot.put(current.slot, current);
        if (loginSeed || current.equals(previous) || current.state == GrandExchangeOfferState.EMPTY
                        && (previous == null || previous.state == GrandExchangeOfferState.EMPTY)) {
            return Optional.empty();
        }
        return Optional.of(new Transition(previous, current));
    }

    /**
     * Take an immutable point-in-time copy of the latest per-slot observations. The returned map
     * cannot be used to mutate this ledger.
     */
    synchronized Map<Integer, Snapshot> snapshots() {
        return Collections.unmodifiableMap(new LinkedHashMap<>(bySlot));
    }

    /** The offer side a state belongs to; null for an empty slot. */
    static GeOffer.Side sideOf(GrandExchangeOfferState state) {
        return state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.BOUGHT
                        || state == GrandExchangeOfferState.CANCELLED_BUY ? GeOffer.Side.BUY
                : state == GrandExchangeOfferState.SELLING || state == GrandExchangeOfferState.SOLD
                                || state == GrandExchangeOfferState.CANCELLED_SELL ? GeOffer.Side.SELL : null;
    }

    static boolean isActive(GrandExchangeOfferState state) {
        return state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.SELLING;
    }

    static boolean isTerminal(GrandExchangeOfferState state) {
        return sideOf(state) != null && !isActive(state);
    }

    /** Immutable copy of the API fields used by the offer ledger. */
    @EqualsAndHashCode
    @AllArgsConstructor
    static class Snapshot {
        int slot;
        GrandExchangeOfferState state;
        int itemId;
        int totalQuantity;

        /** RuneLite's quantity bought or sold so far, copied from getQuantitySold(). */
        int quantityTraded;

        long price;

        /** Raw getSpent() observation; the model does not assign sell-side or tax semantics. */
        long spent;

        static Snapshot fromOffer(int slot, GrandExchangeOffer offer) {
            return new Snapshot(slot, offer.getState(), offer.getItemId(), offer.getTotalQuantity(),
                    offer.getQuantitySold(), offer.getPrice(), offer.getSpent());
        }
    }

    /**
     * One observed slot change: the previous snapshot (null when first seen) and the current one.
     */
    @AllArgsConstructor
    static class Transition {
        Snapshot previous;
        Snapshot current;
    }
}

/**
 * One bounded schema-104 Grand Exchange custody lifecycle: the durable minimum needed to keep exact
 * economics across restart for an offer whose placement was observed under schema 104.
 *
 * <p>Physical custody movements (placement principal, cancellation return/refund) are
 * ownership-neutral. A safely realized settlement books one counted canonical Market result,
 * exactly once, using the persisted cumulative-execution counters as the idempotency guard.
 *
 * <p>Fields are side-specific on purpose: SELL freezes item basis at placement; BUY captures item
 * basis only when the purchased quantity enters tracked ownership. No field is a second financial
 * journal.
 */
@EqualsAndHashCode(of = "offerId")
@Getter
@Setter
class GeOffer {
    /** Durable offer side. */
    enum Side {
        BUY, SELL
    }

    /** Durable lifecycle stage. Behavioural projection states are derived from these facts. */
    enum Stage {
        /** Placement observed; principal may still be arriving; execution may advance. */
        OPEN,
        /** Terminal and reconciled; eligible for safe retirement. */
        CLOSED
    }

    /** Confidence in the placement/basis lineage. */
    enum CustodyConfidence {
        /** Placement and any basis were observed live under schema 104. */
        CONFIRMED,
        /**
         * Offer was already open when schema 104 first observed it; never receives invented basis.
         */
        LEGACY_UNBASED,
        /** Identity or quantity desync; no exact basis lineage. */
        AMBIGUOUS
    }

    String offerId = "";
    int slot;
    Side side = Side.SELL;
    int itemId;
    String itemName = "";
    long offeredQty;
    long listedPrice;
    long placedAtEpochMillis;
    long lastSeenAtEpochMillis;
    String originSessionId = "";
    String offerState = "";
    Stage stage = Stage.OPEN;
    CustodyConfidence confidence = CustodyConfidence.CONFIRMED;

    /** Latest cumulative filled quantity observed from the offer counters. */
    long filledQty;

    /** Latest cumulative spent observed from the offer counters (exact execution evidence). */
    long spentGp;

    /** Filled quantity already booked into a canonical settlement. */
    long settledQty;

    /** Gross execution value already booked into a canonical settlement. */
    long settledExecutionGp;

    /** Observed settlement value already applied to this offer's settlements (0 when batch). */
    long settledCashGp;

    /**
     * Cumulative realized Market result booked for this lifecycle (derived, not a second truth).
     */
    long realizedResultGp;

    /** SELL: quantity whose basis is frozen. Never increased after the placement capture. */
    long capturedQty;

    /** SELL: quantity returned from custody on cancellation. */
    long returnedQty;

    /** BUY: observed inventory coin principal currently held by the exchange. */
    long reserveGp;

    /** BUY: observed coin principal already refunded to the inventory. */
    long refundedGp;

    /** SELL frozen basis unit price; 0 when unbased. */
    long basisUnitPrice;

    /** SELL frozen basis price source; null until a basis is captured. */
    PriceSource basisSource;

    /** SELL frozen basis capture time; 0 when unbased. */
    long basisCapturedAtEpochMillis;

    /** BUY: quantity collected into tracked ownership (basis captured at collection). */
    long collectedQty;

    /** BUY: exact value of the collected quantity (sum of observed collection valuations). */
    long collectedValueGp;

    /** Last canonical settlement transaction id linked to this offer lifecycle. */
    String settlementId = "";

    /**
     * The earlier settlement ids, space-separated: an offer collected in parts books one settlement
     * per collect, and Live and the Ledger fold all of them into its one market row (owner
     * 2026-10-09).
     */
    String earlierSettlements = "";

    /** Schema-106 pooled tracked-basis reservation captured with the SELL placement principal. */
    long reservedTrackedQty;

    long reservedTrackedBasisGp;

    /** Schema-106 realized share of the reservation consumed by collected settlements. */
    long consumedTrackedQty;

    long consumedTrackedBasisGp;

    /** True when quantity was modified without an exact per-slice basis allocation. */
    boolean quantityModified;

    /** True once the offer slot was observed EMPTY; the terminal/cancelled state is retained. */
    boolean cleared;

    /** True when a collection could not be attributed exactly to the filled quantity. */
    boolean collectionAmbiguous;

    /**
     * Schema-107 SELL: exact GE tax of every observed fill, each at its own proven unit price.
     * Meaningful only while {@link #fillTaxExact}; absent (false) on pre-107 records.
     */
    long fillTaxGp;

    /** Schema-107 SELL: true while every fill was observed at a provable per-item price. */
    boolean fillTaxExact;

    /** Schema-107 SELL: the part of {@link #fillTaxGp} already booked into settlements. */
    long settledTaxGp;

    GeOffer() {
        // Gson
    }

    GeOffer(String offerId, int slot, Side side, int itemId, String itemName, long offeredQty, long listedPrice,
            long placedAtEpochMillis, String originSessionId) {
        this.offerId = offerId;
        this.slot = slot;
        this.side = side;
        this.itemId = itemId;
        this.itemName = orEmpty(itemName);
        this.offeredQty = nonNeg(offeredQty);
        this.listedPrice = nonNeg(listedPrice);
        this.placedAtEpochMillis = nonNeg(placedAtEpochMillis);
        this.originSessionId = orEmpty(originSessionId);
    }

    /** The frozen basis price source; UNKNOWN until one is captured. */
    PriceSource getBasisSource() {
        return basisSource == null ? PriceSource.UNKNOWN : basisSource;
    }

    /** SELL: tracked reservation quantity still held by this lifecycle. */
    long reservedQty() {
        return nonNeg(reservedTrackedQty - consumedTrackedQty);
    }

    /** SELL: tracked reservation basis still held by this lifecycle. */
    long reservedBasis() {
        return nonNeg(reservedTrackedBasisGp - consumedTrackedBasisGp);
    }

    void setSettlementId(String value) {
        earlierSettlements = earlierSettlements + " " + settlementId;
        settlementId = orEmpty(value);
    }

    /**
     * Clamps a record read from a save once, so the accessors can read fields directly: blank text
     * and missing enums take their defaults, and no counter is negative.
     */
    void sanitize() {
        offerId = orEmpty(offerId);
        itemName = orEmpty(itemName);
        originSessionId = orEmpty(originSessionId);
        offerState = orEmpty(offerState);
        settlementId = orEmpty(settlementId);
        earlierSettlements = orEmpty(earlierSettlements);
        if (side == null) side = Side.BUY;
        if (stage == null) stage = Stage.OPEN;
        if (confidence == null) confidence = CustodyConfidence.CONFIRMED;
        offeredQty = nonNeg(offeredQty);
        listedPrice = nonNeg(listedPrice);
        placedAtEpochMillis = nonNeg(placedAtEpochMillis);
        lastSeenAtEpochMillis = nonNeg(lastSeenAtEpochMillis);
        filledQty = nonNeg(filledQty);
        spentGp = nonNeg(spentGp);
        settledQty = nonNeg(settledQty);
        settledExecutionGp = nonNeg(settledExecutionGp);
        capturedQty = nonNeg(capturedQty);
        returnedQty = nonNeg(returnedQty);
        reserveGp = nonNeg(reserveGp);
        refundedGp = nonNeg(refundedGp);
        basisUnitPrice = nonNeg(basisUnitPrice);
        basisCapturedAtEpochMillis = nonNeg(basisCapturedAtEpochMillis);
        collectedQty = nonNeg(collectedQty);
        reservedTrackedQty = nonNeg(reservedTrackedQty);
        reservedTrackedBasisGp = nonNeg(reservedTrackedBasisGp);
        consumedTrackedQty = nonNeg(consumedTrackedQty);
        consumedTrackedBasisGp = nonNeg(consumedTrackedBasisGp);
        fillTaxGp = nonNeg(fillTaxGp);
        settledTaxGp = nonNeg(settledTaxGp);
    }

    /** A fresh basis can still be frozen at the first matched owned movement. */
    boolean hasFrozenBasis() {
        return basisSource != null && basisSource != PriceSource.UNPRICED && basisSource != PriceSource.UNKNOWN
                && basisUnitPrice > 0L;
    }

    /** Filled quantity not yet booked into a canonical settlement. */
    long pendingQty() {
        return nonNeg(filledQty - settledQty);
    }

    /** Exact gross execution value of the quantity not yet booked. */
    long pendingExecution() {
        return nonNeg(spentGp - settledExecutionGp);
    }

    /** SELL: quantity still held by the exchange (captured, not returned, not filled). */
    long heldQty() {
        return nonNeg(capturedQty - returnedQty - filledQty);
    }

    /** SELL: basis value for a quantity at the frozen unit price; 0 when unbased. */
    long basisFor(long quantity) {
        long left = basisUnitPrice;
        long right = nonNeg(quantity);
        try {
            return multiplyExact(left, right);
        } catch (ArithmeticException ex) {
            return left >= 0L ? Long.MAX_VALUE : Long.MIN_VALUE;
        }
    }

    /** SELL: quantity that can be settled with an exact frozen basis. */
    long settleableQty() {
        return min(pendingQty(), nonNeg(capturedQty - settledQty));
    }

    /** BUY: reserve not yet spent on fills or returned as change; zero once the offer is done. */
    long reserveOutstanding() {
        return nonNeg(reserveGp - spentGp - refundedGp);
    }

    /** True when the offer's last observed state is a terminal fill/cancellation. */
    boolean isTerminal() {
        return "SOLD".equals(offerState) || "BOUGHT".equals(offerState) || isCancelled();
    }

    /** True when the last observed state is an explicit cancellation. */
    boolean isCancelled() {
        return "CANCELLED_SELL".equals(offerState) || "CANCELLED_BUY".equals(offerState);
    }

    /** True when custody is fully reconciled and the record may be retired after a durable save. */
    boolean isReconciled() {
        if (side == Side.SELL) {
            return pendingQty() == 0L && heldQty() == 0L && (isTerminal() || cleared);
        }
        return pendingQty() == 0L && nonNeg(filledQty - collectedQty) == 0L && reserveOutstanding() == 0L
                && (isTerminal() || cleared);
    }

    /** True when no durable basis can ever be attached (legacy-open or desync). */
    boolean isUnbased() {
        return confidence == CustodyConfidence.LEGACY_UNBASED;
    }
}

/**
 * The one authoritative GE sell-tax rule shared by custody settlement and the read model.
 *
 * <p>Ordinary taxed items pay 2% of the sale price rounded DOWN per item (so sub-50 gp items pay
 * nothing), capped at 5,000,000 gp per item. The wiki's Grand Exchange tax exemption list (checked
 * 2026-09-13, ids resolved against the pinned RuneLite gameval {@code ItemID} constants) pays
 * nothing regardless of price; a real client Collect All of the owner's seven-sale batch proved the
 * exempt low-level food case (cooked chicken sold at 69 gp paid no tax). Tax is never approximated
 * as a stack-wide 2%: it rounds per ITEM. Everything is integer-only and long-safe; there is no
 * floating point here and no second exemption list anywhere else in the codebase.
 */
class GeTaxRule {
    /**
     * Items exempt from the GE convenience fee, per the wiki's Grand Exchange tax exemption list.
     * Items under 50 gp pay nothing through rounding anyway, so most tools here matter only when
     * their price spikes.
     */
    static final Set<Integer> EXEMPT_IDS = GameData.byId("tax_exempt").keySet();

    /** Sentinel: no proven per-item price exists, so no tax can be asserted for an execution. */
    static final long UNPROVABLE_TAX = -1L;

    /**
     * The uniform per-item tax of one execution: {@link #UNPROVABLE_TAX} when the per-item price
     * cannot be proven (a non-exempt gross that is not divisible by the quantity), otherwise the
     * exact tax, which may legitimately be 0 (an exempt item, or a unit price below 50 gp). Each
     * item pays its price / 50 rounded down, at most 5,000,000 gp. The tax never exceeds gross /
     * 50, so it always fits a long.
     */
    static long provableTax(int itemId, long grossGp, long quantity) {
        if (grossGp <= 0L || quantity <= 0L) return UNPROVABLE_TAX;
        if (EXEMPT_IDS.contains(itemId)) return 0L;
        if (grossGp % quantity != 0L) return UNPROVABLE_TAX;
        return Math.min(5_000_000L, grossGp / quantity / 50L) * quantity;
    }

    /**
     * The proven sell tax of one settled execution: the exact positive gap between the observed
     * gross execution and the observed Received cash, accepted only when it equals the uniform
     * per-item rule for that execution. Zero means nothing is proven — a genuinely tax-free stack,
     * an exempt item, a non-uniform execution, or a gap that does not match the rule.
     *
     * <p>Booking and the read model share this one predicate, so a booked tax can never disagree
     * with the receipt that explains it. It is a tax proof, not a result: it never implies the
     * prior tracked value of the sold units.
     */
    static long acceptedTax(int itemId, long grossGp, long quantity, long receivedGp) {
        long tax = provableTax(itemId, grossGp, quantity);
        return tax > 0L && grossGp - receivedGp == tax ? tax : 0L;
    }
}

package com.gpmanager;

import static java.lang.Math.*;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.Pattern;
import static com.gpmanager.PriceSource.*;
import java.util.function.*;
import javax.inject.*;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.*;
import net.runelite.http.api.item.ItemPrice;

/**
 * Game-knowledge tables (item ids, region ids, names) bundled under /com/gpmanager/model as
 * tab-separated resources: one row per line, {@code #} lines are comments. GameDataTablesTest
 * checks every table against RuneLite's named constants.
 */
class GameData {
    /** Rule tables alone are cached: callers of legacy rows still receive independent arrays. */
    static final Map<String, List<String[]>> ROWS = new HashMap<>();

    static final Map<String, Map<String, Phrases.Clause[][]>> RULES = new HashMap<>();

    static synchronized List<String[]> cachedRows(String name) {
        return ROWS.computeIfAbsent(name, GameData::rows);
    }

    /** Whole-column text aliases may contain the existing alternative/conjunction grammar. */
    static String text(String value) {
        return value.matches("@[\\w.-]+") ? msg(value.substring(1)) : value;
    }

    /** The rows of {@code name}.tsv; a missing table is a packaging bug, so it fails loudly. */
    static List<String[]> rows(String name) {
        InputStream stream = GameData.class.getResourceAsStream("/com/gpmanager/model/" + name + ".tsv");
        if (stream == null) throw new IllegalStateException("Missing game data table " + name);
        var rows = new ArrayList<String[]>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8))) {
            for (String line = reader.readLine(); line != null; line = reader.readLine()) {
                if (!line.isEmpty() && !line.startsWith("#")) rows.add(line.split("\t", -1));
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return rows;
    }

    /** {@code name}.tsv keyed by its first-column id, valued by its second column. */
    static Map<Integer, String> byId(String name) {
        var map = new HashMap<Integer, String>();
        for (String[] row : rows(name)) map.put(Integer.parseInt(row[0]), row[1]);
        return map;
    }

    /** Ordered first-column names; useful for catalogues whose first match wins. */
    static List<String> names(String name) {
        var names = new ArrayList<String>();
        for (String[] row : rows(name)) names.add(row[0]);
        return names;
    }

    /** Exact first-column names mapped to their second-column labels. */
    static Map<String, String> byName(String name) {
        var map = new HashMap<String, String>();
        for (String[] row : rows(name)) map.put(row[0], row[1]);
        return map;
    }

    /** Ordered boolean rules: | alternatives, + conjunctions, compiled once by each catalogue. */
    static synchronized Map<String, Phrases.Clause[][]> rules(String name) {
        if (RULES.containsKey(name)) return RULES.get(name);
        var compiled = new LinkedHashMap<String, Phrases.Clause[][]>();
        for (String[] row : cachedRows(name)) {
            compiled.put(row[0], Arrays.stream(text(row[1]).split("\\|", -1)).filter(d -> !d.isEmpty()).map(d ->
                                            Arrays.stream(d.split("\\+", -1)).map(Phrases.Clause::new)
                                                    .toArray(Phrases.Clause[]::new)).toArray(Phrases.Clause[][]::new));
        }
        RULES.put(name, compiled);
        return compiled;
    }

    static final Map<String, String> TEXT = byName("text");
    static final Map<String, Pattern> PATTERNS = new HashMap<>();

    static {
        for (String[] row : rows("patterns"))
            PATTERNS.put(row[0], Pattern.compile(row[1].startsWith("@") ? msg(row[1].substring(1)) : row[1],
                            Integer.parseInt(row[2])));
    }

    static Pattern pattern(String key) {
        return Objects.requireNonNull(PATTERNS.get(key), "Missing pattern " + key);
    }

    /**
     * Text keyed by a prefix and an enum constant ("verb.TRADE"), or the fallback when it has no
     * row.
     */
    static String msg(String key, String fallback) {
        return TEXT.getOrDefault(key, fallback);
    }

    /** Long user-facing text from text.tsv; a test checks every key the code uses. */
    static String msg(String key) {
        String text = TEXT.get(key);
        if (text == null) throw new IllegalStateException("Missing text " + key);
        return text;
    }
}

/**
 * Saturating long/int arithmetic shared by the accounting model; overflow clamps toward the sign of
 * the addend.
 */
class SafeMath {
    /** The wall clock every accounting read uses; the rework's replay sets it to recorded time. */
    static volatile java.util.function.LongSupplier clock = System::currentTimeMillis;

    static long now() {
        return clock.getAsLong();
    }

    /** Absolute value that saturates instead of overflowing on {@code Long.MIN_VALUE}. */
    /** The value, or zero when it is negative. */
    static long nonNeg(long value) {
        return max(0L, value);
    }

    static long abs(long value) {
        return value == Long.MIN_VALUE ? Long.MAX_VALUE : Math.abs(value);
    }

    static long safeAdd(long left, long right) {
        try {
            return addExact(left, right);
        } catch (ArithmeticException ex) {
            return right >= 0L ? Long.MAX_VALUE : Long.MIN_VALUE;
        }
    }

    static long safeSubtract(long left, long right) {
        try {
            return subtractExact(left, right);
        } catch (ArithmeticException ex) {
            return right < 0L ? Long.MAX_VALUE : Long.MIN_VALUE;
        }
    }

    static long safeMultiply(long left, long right) {
        try {
            return multiplyExact(left, right);
        } catch (ArithmeticException ex) {
            return (left >= 0L) == (right >= 0L) ? Long.MAX_VALUE : Long.MIN_VALUE;
        }
    }

    /** A long clamped into the int range (unit prices). */
    static int toInt(long value) {
        return (int) max(Integer.MIN_VALUE, min(Integer.MAX_VALUE, value));
    }

    /** Non-negative count sum saturating at {@link Integer#MAX_VALUE}. */
    static int safeAddCount(int left, int right) {
        long sum = (long) max(0, left) + max(0, right);
        return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
    }
}

/** Display-name defaults and phrase matching shared by the model and the classifiers. */
class Phrases {
    /** Blank activity names fall back to the General bucket. */
    static String normalizeActivity(String value) {
        return nonBlank(value, "General");
    }

    static String orEmpty(String text) {
        return text == null ? "" : text;
    }

    /** Trimmed lower-case text; null reads as empty. */
    static String lower(String value) {
        return lower(value, true);
    }

    /** Some chat/target rules intentionally distinguish leading spaces. */
    static String lower(String value, boolean trim) {
        return value == null ? "" : (trim ? value.trim() : value).toLowerCase(Locale.ROOT);
    }

    static boolean empty(String text) {
        return text == null || text.isEmpty();
    }

    static boolean empty(java.util.Collection<?> values) {
        return values == null || values.isEmpty();
    }

    static boolean empty(java.util.Map<?, ?> values) {
        return values == null || values.isEmpty();
    }

    static boolean blank(String text) {
        return text == null || text.trim().isEmpty();
    }

    /** The trimmed text, or the fallback when it is blank. */
    static String nonBlank(String text, String fallback) {
        return blank(text) ? fallback : text.trim();
    }

    /** Trimmed lower-case text, or null when blank. */
    static String norm(String value) {
        String key = lower(value);
        return key.isEmpty() ? null : key;
    }

    /** True when the text contains any of the words. */
    static boolean has(String text, String... words) {
        for (String word : words) {
            if (text.contains(word)) return true;
        }
        return false;
    }

    /** True when any non-null term contains the already lower-case needle. */
    static boolean containsFolded(String lowerNeedle, String... terms) {
        for (String term : terms) {
            if (term != null && term.toLowerCase(Locale.ROOT).contains(lowerNeedle)) return true;
        }
        return false;
    }

    /**
     * A compiled table clause: contains, =exact, ^prefix, $suffix, %pattern, ~case-insensitive
     * exact (Unicode equalsIgnoreCase), with optional !.
     */
    static class Clause {
        String text;
        int kind;
        boolean negated;
        java.util.regex.Pattern pattern;

        Clause(String spec) {
            if (spec.startsWith("@")) spec = GameData.msg(spec.substring(1));
            negated = spec.startsWith("!");
            if (negated) spec = spec.substring(1);
            kind = spec.isEmpty() ? -1 : "=^$%~".indexOf(spec.charAt(0));
            text = kind < 0 ? spec : spec.substring(1);
            pattern = kind == 3 ? GameData.pattern(text) : null;
        }
    }

    /** Alternatives of conjunctions; all parsing and regex compilation happens at table load. */
    static boolean has(String text, Clause[][] rules) {
        if (text == null) return false;
        for (Clause[] clauses : rules) if (containsAll(text, clauses)) return true;
        return false;
    }

    static boolean containsAll(String text, Clause[] clauses) {
        for (Clause clause : clauses) {
            boolean hit = clause.kind == 0 ? text.equals(clause.text) : clause.kind == 1 ? text.startsWith(clause.text)
                                    : clause.kind == 2 ? text.endsWith(clause.text) : clause.kind == 3
                                                    ? clause.pattern.matcher(text).matches() : clause.kind == 4
                                                            ? text.equalsIgnoreCase(clause.text)
                                                            : text.contains(clause.text);
            if (hit == clause.negated) return false;
        }
        return true;
    }
}

@Singleton
class Valuation implements FlowValuator {
    /** Whether the current world/economy permits ordinary automatic RuneLite market quotes. */
    enum Economy {
        NORMAL, UNSUPPORTED_SPECIAL, UNKNOWN
    }

    /**
     * Explicit RuneLite quote route. The boolean is GP Manager's own policy choice, never the
     * user's global RuneLite display-price preference, so identical observations book the same
     * amount. Production binds this to {@code ItemManager::getItemPriceWithSource}.
     */
    @FunctionalInterface
    interface MarketQuote {
        int priceOf(int itemId, boolean active);
    }

    static final Map<String, String> PARTS = GameData.byName("partial_food");

    IntFunction<ItemComposition> compositions;
    MarketQuote marketQuotes;
    IntPredicate unsupportedMapping;
    GpManagerConfig config;
    @Getter volatile Economy economyState;

    /** Karamja gloves 1-4 worn: sampled by the plugin, read when a proxy rate is chosen. */
    volatile boolean karamjaGlovesWorn;

    /** A market quote floored at zero; an unavailable quote reads 0 (the flow stays unpriced). */
    int quoteOrZero(int itemId) {
        try {
            return max(0, marketQuotes.priceOf(itemId, true));
        } catch (RuntimeException ignored) {
            return 0;
        }
    }

    @Inject
    Valuation(ItemManager itemManager, GpManagerConfig config) {
        // Accounting explicitly requests GP Manager's chosen RuneLite active market route (the
        // boolean is always true at the call site). It must not delegate to getItemPrice(),
        // whose implementation follows the user's global useWikiItemPrices display preference
        // and would make identical observations book different amounts. RuneLite may itself
        // fall back to guide/Jagex pricing; the selected quote is captured and frozen at
        // booking time, and history is never repriced. The economy gate starts UNKNOWN until
        // the plugin observes a logged-in world, so automatic quotes fail closed meanwhile.
        this(config, itemManager::getItemComposition,
                (id, active) -> unitPriceOf(itemManager.getItemPriceWithSource(id, active)),
                id -> hasUnsupportedMapping(itemManager, id), Economy.UNKNOWN);
    }

    /**
     * Unit-price boundary for a RuneLite quote. RuneLite 1.13.1 widened the quote to long for
     * beyond-max-cash trades; the unit-price model is int, so a value that does not fit (or is not
     * positive) stays unpriced for Review instead of booking a clamped, fabricated amount.
     */
    static int unitPriceOf(long quote) {
        return quote <= 0L || quote > Integer.MAX_VALUE ? 0 : SafeMath.toInt(quote);
    }

    /** Test seam: deterministic NORMAL economy and no mapping guard; the boolean stays explicit. */
    Valuation(GpManagerConfig config, IntFunction<ItemComposition> compositions, MarketQuote marketQuotes) {
        this(config, compositions, marketQuotes, id -> false, Economy.NORMAL);
    }

    Valuation(GpManagerConfig config, IntFunction<ItemComposition> compositions, MarketQuote marketQuotes,
            IntPredicate unsupportedMapping, Economy economyState) {
        this.config = config;
        this.compositions = compositions;
        this.marketQuotes = marketQuotes;
        this.unsupportedMapping = unsupportedMapping == null ? id -> false : unsupportedMapping;
        this.economyState = economyState == null ? Economy.UNKNOWN : economyState;
    }

    @Override
    public List<Flow> value(Map<Integer, Long> quantityDeltas) {
        return value(quantityDeltas, 0L);
    }

    @Override
    public List<Flow> value(Map<Integer, Long> quantityDeltas, long priceCapturedAtEpochMillis) {
        var flows = new ArrayList<Flow>();
        Map<Integer, Integer> priceOverrides = priceOverrides();
        for (Map.Entry<Integer, Long> entry : quantityDeltas.entrySet()) {
            Flow flow = valueOne(entry.getKey(), entry.getValue(), priceOverrides, priceCapturedAtEpochMillis);
            if (flow != null) flows.add(flow);
        }
        flows.sort(Comparator.comparingLong((Flow flow) -> SafeMath.abs(flow.valueDelta)).reversed());
        return flows;
    }

    /**
     * Revalues only a confirmed Drink action. Ordinary valuation remains a quote of each observed
     * item variant; this hook is deliberately separate so a decant, transfer or production shape
     * cannot be mistaken for consumption before action settlement.
     */
    @Override
    public List<Flow> normalizeConsumedFlows(List<Flow> flows, ActionKind actionKind, long priceCapturedAtEpochMillis) {
        if (flows == null || flows.isEmpty() || actionKind != ActionKind.DRINK || ActionReader.isDecant(flows)) {
            return flows;
        }
        Map<Integer, Integer> priceOverrides = priceOverrides();
        List<ActionReader.PartialUse> pairs = ActionReader.partialUses(flows);
        if (pairs.isEmpty()) return flows;
        // Each exact pair is an atomic accounting unit. Compute both replacement flows before
        // assigning either one; an unsupported basis returns null and leaves the caller's
        // original captured list untouched for Review.
        var normalized = new ArrayList<>(flows);
        for (ActionReader.PartialUse pair : pairs) {
            if (!normalizePotionPair(normalized, pair.lossIndex, pair.remainderIndex, priceOverrides,
                    priceCapturedAtEpochMillis)) {
                return null;
            }
        }
        return normalized;
    }

    Flow doseAuthority(Flow flow, Map<Integer, Integer> priceOverrides, long now) {
        if (flow == null) return null;
        String one = (ActionReader.doseBaseName(flow.itemName) + "(1)").trim().toLowerCase(Locale.ROOT);
        Flow geCandidate = null;
        try {
            for (int id : ItemVariationMapping.getVariations(ItemVariationMapping.map(flow.itemId))) {
                Flow unit = valueOne(id, 1L, priceOverrides, now, false);
                String unitName = unit == null ? "" : unit.itemName;
                if (unitName == null || !one.equals(Phrases.lower(unitName))) continue;
                if (unit.getPriceSource() == MANUAL_OVERRIDE) return unit;
                if (unit.getPriceSource() == GRAND_EXCHANGE && geCandidate == null)
                    geCandidate = unit;
            }
        } catch (RuntimeException ignored) {
            return null;
        }
        return geCandidate;
    }

    /**
     * The per-dose price for a dose variant with no quote of its own (owner 1.3.4): the family's
     * highest-dose quote scaled by this variant's dose, so a Burning amulet(4) is four fifths of
     * the (5) and one teleport costs a fifth. A manual override anywhere in the family is
     * authoritative; RuneLite's variation mapping names the family and anything malformed fails
     * closed to null.
     */
    Flow doseFamilyQuote(int itemId, String itemName, Map<Integer, Integer> priceOverrides) {
        int dose = ActionReader.trailingDose(itemName);
        String base = ActionReader.doseBaseName(itemName);
        if (dose <= 0 || base.isEmpty()) return null;
        int anchorDose = 0;
        int anchorPrice = 0;
        boolean manual = false;
        try {
            for (int id : ItemVariationMapping.getVariations(ItemVariationMapping.map(itemId))) {
                if (id == itemId) continue;
                String otherName = compositionName(id);
                int otherDose = ActionReader.trailingDose(otherName);
                if (otherDose <= 0 || !base.equalsIgnoreCase(ActionReader.doseBaseName(otherName))) {
                    continue;
                }
                Integer override = priceOverrides.get(id);
                if (override != null && override > 0) {
                    if (!manual || otherDose > anchorDose) {
                        manual = true;
                        anchorDose = otherDose;
                        anchorPrice = override;
                    }
                    continue;
                }
                if (manual || otherDose <= anchorDose) continue;
                int quote = quoteOrZero(id);
                if (quote > 0) {
                    anchorDose = otherDose;
                    anchorPrice = quote;
                }
            }
        } catch (RuntimeException ignored) {
            return null;
        }
        if (anchorDose <= 0 || anchorPrice <= 0) return null;
        long scaled = (long) anchorPrice * dose / anchorDose;
        if (scaled <= 0L || scaled > Integer.MAX_VALUE) return null;
        return new Flow(itemId, itemName, 1L, (int) scaled, scaled, manual ? MANUAL_OVERRIDE : GRAND_EXCHANGE, 0L);
    }

    /** One variation family member's display name, "" when the definition is unavailable. */
    String compositionName(int id) {
        try {
            ItemComposition composition = compositions.apply(id);
            return composition == null || composition.getName() == null ? "" : composition.getName();
        } catch (RuntimeException ignored) {
            return "";
        }
    }

    private boolean normalizePotionPair(List<Flow> normalized, int lossIndex, int remainderIndex,
            Map<Integer, Integer> priceOverrides, long now) {
        Flow loss = normalized.get(lossIndex);
        Flow remainder = normalized.get(remainderIndex);
        int lostDose = ActionReader.trailingDose(loss.itemName);
        int gainedDose = ActionReader.trailingDose(remainder.itemName);
        if (lostDose <= 0 || gainedDose <= 0 || lostDose != gainedDose + 1 || !ActionReader.doseBaseName(loss.itemName)
                        .equals(ActionReader.doseBaseName(remainder.itemName))) {
            return false;
        }
        Flow authority = doseAuthority(loss, priceOverrides, now);
        if (!compatibleWithAuthority(loss, authority) || !compatibleWithAuthority(remainder, authority)) return false;
        try {
            long lossUnit = multiplyExact(lostDose, (long) authority.unitPrice);
            long remainderUnit = multiplyExact(gainedDose, (long) authority.unitPrice);
            Flow normalizedLoss = new Flow(loss.itemId, loss.itemName, loss.quantityDelta, toIntExact(lossUnit),
                            multiplyExact(loss.quantityDelta, lossUnit), authority.getPriceSource(),
                            authority.getPriceCapturedAtEpochMillis());
            Flow normalizedRemainder = new Flow(remainder.itemId, remainder.itemName, remainder.quantityDelta,
                            toIntExact(remainderUnit), multiplyExact(remainder.quantityDelta, remainderUnit),
                            authority.getPriceSource(), authority.getPriceCapturedAtEpochMillis());
            normalized.set(lossIndex, normalizedLoss);
            normalized.set(remainderIndex, normalizedRemainder);
            return true;
        } catch (ArithmeticException ex) {
            return false;
        }
    }

    private static boolean compatibleWithAuthority(Flow flow, Flow authority) {
        if (flow == null || authority == null) return false;
        if (authority.getPriceSource() == GRAND_EXCHANGE) {
            return flow.getPriceSource() == GRAND_EXCHANGE && flow.unitPrice > 0;
        }
        return authority.getPriceSource() == MANUAL_OVERRIDE
                && (flow.getPriceSource() == GRAND_EXCHANGE && flow.unitPrice > 0
                        || flow.getPriceSource() == MANUAL_OVERRIDE);
    }

    /**
     * One measured charge component valued through the same policy as ordinary observations:
     * deferred claim, face value, explicit manual override, the mapping guard, the world/economy
     * gate, the explicit active RuneLite market route and UNPRICED otherwise.
     */
    Flow valueComponent(int itemId, long quantityDelta, long now) {
        return valueOne(itemId, quantityDelta, priceOverrides(), now);
    }

    @Override
    public boolean automaticMarketQuotesAvailable() {
        return economyState == Economy.NORMAL;
    }

    /**
     * Client-thread world/economy refresh. UNKNOWN and special economies fail automatic market
     * quotes closed; manual override and face-value policy still apply.
     */
    void setEconomyState(Economy state) {
        economyState = state == null ? Economy.UNKNOWN : state;
    }

    /** Client-thread Karamja-gloves snapshot; picks the improved proxy rate while worn. */
    void setKaramjaGlovesWorn(boolean worn) {
        karamjaGlovesWorn = worn;
    }

    /**
     * Every main-game world (members, PvP, high risk, LMS, PvP Arena, skill total...) shares the
     * Grand Exchange and keeps automatic quotes. Only the separate economies (Deadman, Leagues,
     * speedrunning, beta, tournament and no-save worlds) and an absent world observation fail
     * closed.
     */
    static Economy economyFor(Collection<WorldType> worldTypes) {
        if (worldTypes == null) return Economy.UNKNOWN;
        for (WorldType type : worldTypes) {
            if (type == null) return Economy.UNKNOWN;
            switch (type) {
                case DEADMAN:
                case SEASONAL:
                case QUEST_SPEEDRUNNING:
                case BETA_WORLD:
                case TOURNAMENT_WORLD:
                case NOSAVE_MODE:
                    return Economy.UNSUPPORTED_SPECIAL;
                default:
                    break;
            }
        }
        return Economy.NORMAL;
    }

    /**
     * Owner 2026-10-09 (1.3.0): an ironman who chose high alch values items at their alchemy price;
     * ironmen cannot sell on the Grand Exchange. The plugin sets it each tick from the account
     * type.
     */
    volatile boolean alch;

    Flow valueOne(int itemId, long quantityDelta, Map<Integer, Integer> priceOverrides,
            long priceCapturedAtEpochMillis) {
        return valueOne(itemId, quantityDelta, priceOverrides, priceCapturedAtEpochMillis, true);
    }

    Flow valueOne(int itemId, long quantityDelta, Map<Integer, Integer> priceOverrides, long priceCapturedAtEpochMillis,
            boolean doseFallback) {
        boolean deferredClaim = DeferredClaims.of(itemId);
        try {
            ItemComposition composition = null;
            try {
                composition = compositions.apply(itemId);
            } catch (RuntimeException ignored) {
                // No definition yet: the flow keeps a placeholder name.
            }
            String name = composition == null || composition.getName() == null ? "Item " + itemId
                            : composition.getName();
            // A clue scroll, scroll box or reward casket is worth nothing until its casket opens
            // (owner 2026-10-08).
            deferredClaim |= GameData.pattern("clue").matcher(name).matches();
            // An empty vial is a physical neutral; filled variants remain ordinary items.
            if (itemId == ItemID.VIAL_EMPTY) return null;
            boolean manualOverride = priceOverrides.containsKey(itemId);
            int faceValue = faceValueOf(itemId);
            // For ordinary items, a user override is authoritative even before RuneLite prices
            // load; fixed currencies below retain their face value by policy.
            int marketPrice = 0;
            // RuneLite's ItemManager price helper is intentionally convenient: when an item has
            // no direct quote it can recurse through ItemMapping and price an untradeable variant
            // from another item (for example unidentified minerals or golden nuggets via coal).
            // Those catalogue entries are non-GP currencies in GP Manager, so their physical
            // identity must not inherit a monetary identity from the platform mapping. An
            // explicit owner override remains authoritative.
            if (!manualOverride && !deferredClaim && faceValue == 0 && !CurrencyProxyCatalogue.isMapped(itemId)
                    && economyState == Economy.NORMAL && !unsupportedMapping.test(itemId)) {
                // GP Manager's single automatic market policy: the explicit active route,
                // gated by the current world/economy and the mapping guard above.
                marketPrice = quoteOrZero(itemId);
            }
            // A proxy row values the component from a market item and its fixed exchange rate.
            // The proxy's market item is priced only where market quotes are, never on unknown or
            // special worlds (Codex review 1.2).
            int[] proxy = marketPrice == 0 && economyState == Economy.NORMAL ? CurrencyProxyCatalogue.proxyOf(itemId)
                            : null;
            if (proxy != null) {
                // Some exchanges improve while Karamja gloves are worn; the proxy row may
                // carry the improved units after a slash (tokkul: 300,000 or 260,000 per onyx).
                int units = proxy[1];
                if (karamjaGlovesWorn) {
                    int glovesUnits = CurrencyProxyCatalogue.glovesUnitsOf(itemId);
                    if (glovesUnits > 0) units = glovesUnits;
                }
                // No proxy quote: the flow stays unpriced for Review.
                marketPrice = quoteOrZero(proxy[0]) / units;
            }
            // RuneLite's ItemMapping carries no bracelet of ethereum entry (upstream omission,
            // verified 2026-10-12): the charged bracelet prices from its uncharged form's live
            // quote, the same relationship the revenant weapons already have.
            if (marketPrice == 0 && itemId == ItemID.WILD_CAVE_BRACELET_CHARGED && !manualOverride
                    && economyState == Economy.NORMAL && !unsupportedMapping.test(itemId)) {
                // No quote: the flow stays unpriced for Review.
                marketPrice = quoteOrZero(ItemID.WILD_CAVE_BRACELET_UNCHARGED);
            }
            // A partial dose RuneLite cannot quote (Burning amulet(4)) is priced from its family's
            // highest-dose quote at the same rate per dose (owner 1.3.4, GP-Per-Hour's fractional
            // model); a manual override anywhere in the family is authoritative.
            Flow doseQuote = null;
            if (marketPrice == 0 && doseFallback && !manualOverride && !deferredClaim && faceValue == 0
                    && economyState == Economy.NORMAL && !CurrencyProxyCatalogue.isMapped(itemId)
                    && !unsupportedMapping.test(itemId)) {
                doseQuote = doseFamilyQuote(itemId, name, priceOverrides);
            }
            // Half a pie, a pizza half or a cake slice is its share of the whole one's quote
            // (owner live 2026-10-16: Half a summer pie read "?").
            String part = PARTS.get(String.valueOf(itemId));
            if (marketPrice == 0 && part != null && !manualOverride && economyState == Economy.NORMAL) {
                String[] share = part.split(" ");
                marketPrice = (int)
                                ((long) quoteOrZero(Integer.parseInt(share[0]))
                                        * Integer.parseInt(share[1])
                                        / Integer.parseInt(share[2]));
            }
            int unitPrice;
            PriceSource priceSource;
            if (deferredClaim) {
                // A non-tradeable key is an unopened claim, not held wealth. Its
                // contents become ordinary valued inventory gains only on receipt.
                unitPrice = 0;
                priceSource = DEFERRED_CLAIM;
            } else if (faceValue > 0) {
                unitPrice = faceValue;
                priceSource = FACE_VALUE;
            } else if (manualOverride) {
                unitPrice = priceOverrides.get(itemId);
                priceSource = MANUAL_OVERRIDE;
            } else if (alch && composition != null && composition.getHaPrice() > 0) {
                unitPrice = composition.getHaPrice();
                priceSource = HIGH_ALCHEMY;
            } else if (marketPrice > 0) {
                // The item's own market quote is a supported observation. Non-GP currencies
                // without a quote stay unpriced; an exchange relationship is never converted into
                // booked GP.
                unitPrice = marketPrice;
                priceSource = proxy == null ? GRAND_EXCHANGE : CURRENCY_PROXY;
            } else if (doseQuote != null) {
                // The derived price follows its family anchor's source so provenance stays honest.
                unitPrice = doseQuote.unitPrice;
                priceSource = doseQuote.getPriceSource();
            } else if (composition != null && !CurrencyProxyCatalogue.isMapped(itemId)
                    && !unsupportedMapping.test(itemId) && (!composition.isTradeable() || economyState == Economy.NORMAL
                                    && quoteOrZero(ItemID.NATURERUNE) > 0)) {
                // No market quote (untradeable, or tradeable once prices have loaded): its alch
                // value for every account (a crystal shard), else worth nothing (a Progress hat),
                // a known zero rather than a missing price (owner 2026-10-16). With both, the GE
                // price above wins unless an ironman chose alch values.
                unitPrice = max(0, composition.getHaPrice());
                priceSource = unitPrice > 0 ? HIGH_ALCHEMY : NO_VALUE;
            } else {
                unitPrice = 0;
                priceSource = UNPRICED;
            }
            long valueDelta = safeMultiply(quantityDelta, unitPrice);
            // Only a non-zero selected price is a captured price. Unpriced/deferred flows
            // deliberately retain zero so consumers cannot present a fabricated capture time.
            long capturedAt = unitPrice > 0 && priceSource != PriceSource.UNKNOWN && priceSource != FACE_VALUE
                            ? SafeMath.nonNeg(priceCapturedAtEpochMillis) : 0L;
            return new Flow(itemId, name, quantityDelta, unitPrice, valueDelta, priceSource, capturedAt);
        } catch (RuntimeException ignored) {
            return new Flow(itemId, "Item " + itemId, quantityDelta, 0, 0L, deferredClaim ? DEFERRED_CLAIM : UNPRICED);
        }
    }

    static int faceValueOf(int itemId) {
        if (itemId == ItemID.COINS) return 1;
        if (itemId == ItemID.PLATINUM) return 1_000;
        return 0;
    }

    /**
     * ItemManager's convenience quote recursively applies ItemMapping. Only a quantity-one,
     * non-coin mapping can represent a state/base identity; quantity/rate mappings and coin targets
     * would silently manufacture monetary identity for a physically distinct item.
     */
    static boolean hasUnsupportedMapping(ItemManager itemManager, int itemId) {
        try {
            int canonicalId = itemManager.canonicalize(itemId);
            return hasUnsupportedMapping(ItemMapping.map(canonicalId));
        } catch (RuntimeException ignored) {
            return true;
        }
    }

    static boolean hasUnsupportedMapping(Collection<ItemMapping> mappings) {
        if (mappings == null) return false;
        for (ItemMapping mapping : mappings) {
            if (mapping.getQuantity() != 1L || mapping.getTradeableItem() == ItemID.COINS)
                return true;
        }
        return false;
    }

    static long safeMultiply(long quantity, int price) {
        try {
            return multiplyExact(quantity, (long) price);
        } catch (ArithmeticException ex) {
            return quantity >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
        }
    }

    /** The owner's manual price overrides by item id. */
    Map<Integer, Integer> priceOverrides() {
        return ItemRuleParser.parsePriceOverrides(config.manualPriceOverrides());
    }
}

class ItemRuleParser {
    static Map<Integer, Integer> parsePriceOverrides(String value) {
        if (Phrases.blank(value)) return Collections.emptyMap();
        var result = new HashMap<Integer, Integer>();
        for (String token : value.split(",")) {
            String[] parts = token.trim().split("=", 2);
            if (parts.length != 2) continue;
            try {
                int itemId = Integer.parseInt(parts[0].trim());
                int price = Integer.parseInt(parts[1].trim());
                if (itemId >= 0 && price >= 0) result.put(itemId, price);
            } catch (NumberFormatException ignored) {
                // Invalid entries are ignored so a typo cannot break tracking.
            }
        }
        return result;
    }
}

@FunctionalInterface
interface FlowValuator {
    List<Flow> value(Map<Integer, Long> quantityDeltas);

    /**
     * Values flows using the caller's evidence-capture time. Existing valuators remain
     * source-compatible and may ignore the timestamp until they support price provenance.
     */
    default List<Flow> value(Map<Integer, Long> quantityDeltas, long priceCapturedAtEpochMillis) {
        return value(quantityDeltas);
    }

    /**
     * Applies an action-aware normalization after the engine has confirmed a consumption. Synthetic
     * valuators keep their observed flows unchanged; the canonical valuator may normalize only the
     * explicitly evidenced action and must preserve all source provenance.
     *
     * <p>Callers must invoke this after action settlement and before custody or booking. The
     * timestamp is the same observation timestamp used to value the committed inventory delta. A
     * {@code null} result means the confirmed action had an unsupported or conflicting price basis;
     * callers must keep the original captured flows and route the receipt to Review.
     */
    default List<Flow> normalizeConsumedFlows(
            List<Flow> flows, ActionKind actionKind, long priceCapturedAtEpochMillis) {
        return flows;
    }

    /**
     * Whether the current world/economy permits ordinary automatic market quotes. Synthetic test
     * valuators default to the deterministic NORMAL fixture; the canonical {@link Valuation}
     * overrides this with its observed economy snapshot.
     */
    default boolean automaticMarketQuotesAvailable() {
        return true;
    }
}

/**
 * The item lookups accounting needs, in one place: the canonical id, the composition, the active
 * market quote and a name search. Production answers from RuneLite's ItemManager; the rework's
 * replay answers from a recording (docs/REWORK_PLAN.md), so a session books the same both ways.
 */
@Singleton
class ItemLookup {
    ItemManager manager;

    @Inject
    ItemLookup(ItemManager manager) {
        this.manager = manager;
    }

    int canon(int id) {
        return manager == null ? id : manager.canonicalize(id);
    }

    ItemComposition composition(int id) {
        return manager == null ? null : manager.getItemComposition(id);
    }

    List<ItemPrice> find(String name) {
        return manager == null ? Collections.emptyList() : manager.search(name);
    }
}

/**
 * Untradeable non-GP currencies. They are unpriced unless a manual override supplies a price or a
 * proxy row prices them from a market item and its fixed exchange rate: RuneLite's price helper
 * would otherwise value some of them through an item mapping. A proxy's units cell may read
 * base/with-gloves when Karamja gloves improve that exchange.
 */
class CurrencyProxyCatalogue {
    static final Set<Integer> CURRENCIES = GameData.byId("currencies").keySet();

    /** Proxy rows: item id to {market item id, units per proxy item}. */
    static final Map<Integer, int[]> PROXIES = new HashMap<>();

    /** Proxy rows whose exchange improves with Karamja gloves worn: item id to gloves units. */
    static final Map<Integer, Integer> GLOVES_UNITS = new HashMap<>();

    static {
        for (String[] row : GameData.rows("currencies")) {
            if (row.length > 2) {
                String[] units = row[2].split("/");
                PROXIES.put(Integer.parseInt(row[0]), new int[] {Integer.parseInt(row[1]), Integer.parseInt(units[0])});
                if (units.length > 1) {
                    GLOVES_UNITS.put(Integer.parseInt(row[0]), Integer.parseInt(units[1]));
                }
            }
        }
    }

    static boolean isMapped(int itemId) {
        return CURRENCIES.contains(itemId);
    }

    /** The proxy price source for this item, or null. */
    static int[] proxyOf(int itemId) {
        return PROXIES.get(itemId);
    }

    /** The gloves-worn units for this proxy row, or 0 when its rate does not change. */
    static int glovesUnitsOf(int itemId) {
        return GLOVES_UNITS.getOrDefault(itemId, 0);
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import static com.gpmanager.Accounting.*;
import static com.gpmanager.Correction.*;
import static com.gpmanager.GameData.msg;
import static com.gpmanager.PauseReason.*;
import static com.gpmanager.Phrases.*;
import static com.gpmanager.SafeMath.*;
import static java.lang.Math.*;
import static java.util.Collections.*;

import com.gpmanager.Accounting.Amounts;
import com.gpmanager.CorrectionRecord.Change;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.function.Predicate;
import lombok.*;

class Session {
    /** The always-on General tracker is shown as "Overall". */
    static final String DURABLE_OWNER_NAME = "Overall";

    static final int MAX_UNDO_HISTORY = 32;
    String id;
    String name;
    String activityHint;
    SessionMode mode;

    /** True for a named Grind; false for the Overall (free play) session. */
    boolean grind;

    /** Runtime-only signal/revision for profile totals derived from session-day summaries. */
    transient Runnable changeListener;

    /** Runtime-only change count; a quick save reuses a closed session's JSON while it holds. */
    transient long saveStamp;

    /** Runtime-only pooled known-basis observer; the engine wires the tracked-basis ledger. */
    transient TrackedBasisLedger ownedValueObserver;

    /** A drop or shot nobody picked up is used up, off the ground and off the paid-price record. */
    void usedUp(Transaction row) {
        row.setOnGround(false);
        if (ownedValueObserver != null) ownedValueObserver.onUsedUp(row);
        notifyChanged();
    }

    void notifyOwnedValue(Transaction transaction, boolean custodyOwned) {
        if (ownedValueObserver != null) ownedValueObserver.onAdded(transaction, custodyOwned);
    }

    boolean canChangeOwnedValue(Transaction transaction, Correction previousCorrection, List<Flow> previousFlows,
            Correction nextCorrection, List<Flow> nextFlows) {
        return ownedValueObserver == null || ownedValueObserver.canChange(
                        transaction, previousCorrection, previousFlows, nextCorrection, nextFlows);
    }

    /** Announces a changed row: totals, PvP and the owned-value observer follow it. */
    void changed(Transaction transaction, Correction previousCorrection, List<Flow> previousFlows) {
        transactionChanged(transaction);
        if (ownedValueObserver != null)
            ownedValueObserver.onChanged(transaction, previousCorrection, previousFlows);
    }

    void log(long now, String reason, Change... changes) {
        correctionHistory.add(new CorrectionRecord(reason, Arrays.asList(changes)));
    }

    long startedAtEpochMillis;
    long endedAtEpochMillis;

    boolean paused;
    PauseReason pauseReason = NONE;
    long pausedAtEpochMillis;
    long totalPausedMillis;
    List<Transaction> transactions = new ArrayList<>();
    PkTally pk = new PkTally();

    List<CorrectionRecord> correctionHistory = new ArrayList<>();
    List<UndoRecord> undoHistory = new ArrayList<>();
    int transactionLimit;
    long retainedRevenue;
    long retainedCosts;
    long retainedSuppliesCosts;
    boolean retainedCostSplitComplete;
    long compactedTransactionCount;
    // Nullable by design: a target is owner-local presentation metadata, never
    // an accounting input or generated transaction.
    Long profitTargetGp;
    // The session's Net when the target above was last set: the aim counts what has been earned
    // since (owner live 2026-10-14). Null on older saves counts from the run's start.
    Long profitTargetSetNet;

    /** The run's Active Time when the Net aim was set; its pace counts from there (owner 2026-10-16). */
    Long profitTargetSetActiveMillis;

    /**
     * When Live's current session began (New session, or a target set), and the run's Active Time
     * then: Live counts from here while the run keeps everything (owner 1.5.2). Null shows the
     * whole run (a fresh Grind, older saves).
     */
    Long sessionStartAt;

    long sessionStartMillis;

    /** Free play's Net milestone: it counts Free play's whole Net (owner 1.5.2); null with none. */
    Long milestoneGp;
    // Signature targets: the actual Active-Time aim this Grind instance ran with, and the stable
    // My Grind lineage link it was started from. Both are metadata; neither books anything.
    Long activeTimeTargetMillis;
    // The session's own Active Time when the target above was last set; null on older saves and
    // fresh sessions, which keep counting from the run's start (owner live 2026-10-13).
    Long activeTimeTargetSetMillis;
    // The timer's own pause: the Active Time it was frozen at; null while it runs (owner live
    // 2026-10-14). Distinct from a session pause — the run keeps tracking.
    Long activeTimeTargetPauseMillis;
    String grindId;

    Session() {
        // Gson
    }

    Session(String name, long startedAtEpochMillis, SessionMode mode) {
        id = UUID.randomUUID().toString();
        this.name = normalizeName(name);
        this.mode = mode == null ? SessionMode.GENERAL : mode;
        activityHint = "General";
        this.startedAtEpochMillis = startedAtEpochMillis;
        transactionLimit = 2_000;
        retainedCostSplitComplete = true;
    }

    /**
     * @param custodyOwned true for transactions already realized by a custody lifecycle; their item
     *     legs consumed their reservation and must never deplete again
     */
    void addTransaction(Transaction transaction, int maxTransactions, boolean custodyOwned) {
        if (transaction == null) return;
        transactionLimit = max(1, maxTransactions);
        transactions.add(transaction);
        transactionChanged(transaction);
        notifyOwnedValue(transaction, custodyOwned);
        evict(transactions.size() - transactionLimit);
    }

    /** Drops the oldest rows over the limit, each summarized exactly into the retained totals. */
    void evict(int overflow) {
        if (overflow <= 0) return;
        var removed = new ArrayList<Transaction>(transactions.subList(0, overflow));
        transactions.subList(0, overflow).clear();
        for (Transaction transactionToRemove : removed) compactTransaction(transactionToRemove);
    }

    void recordAction(String hint, long now) {
        setActivityHint(normalizeActivity(hint), now);
    }

    void setActivityHint(String hint, long now) {
        if (blank(hint)) return;
        String next = normalizeActivity(hint);
        String current = getActivityHint();
        if (next.equalsIgnoreCase(current)) return;
        activityHint = next;
    }

    void rename(String value) {
        name = normalizeName(value);
    }

    boolean setProfitTargetGp(Long value) {
        return setProfitTargetGp(value, 0L, 0L);
    }

    /**
     * Sets the Net aim and the run's Net at the set moment (owner live 2026-10-14): a changed value
     * counts from now, as does the same value once the aim is already reached; an unchanged,
     * unreached value keeps its count.
     */
    boolean setProfitTargetGp(Long value, long sessionNet, long activeMillis) {
        Long next = value == null || value <= 0L ? null : value;
        if (Objects.equals(next, profitTargetGp)) {
            return next != null && profitTargetProgress(sessionNet) >= next
                    && rebaseProfitTarget(sessionNet, activeMillis);
        }
        profitTargetGp = next;
        rebaseProfitTarget(sessionNet, activeMillis);
        return true;
    }

    /** The run's Net when the aim was set; 0 with none and on older saves. */
    long getProfitTargetSetNet() {
        return profitTargetSetNet == null || profitTargetSetNet < 0L ? 0L : profitTargetSetNet;
    }

    /** What the Net aim has counted so far; sessionNet is the run's total. */
    long profitTargetProgress(long sessionNet) {
        return sessionStartAt != null ? metrics(rowsSince(sessionStartAt), 0L).net
                : sessionNet - getProfitTargetSetNet();
    }

    /**
     * Re-bases the set Net aim's count on the given net, keeping its value (owner live 2026-10-14):
     * Reset counts the aim from now whether or not it was reached.
     */
    boolean rebaseProfitTarget(long sessionNet, long activeMillis) {
        profitTargetSetNet = profitTargetGp == null ? null : sessionNet;
        profitTargetSetActiveMillis = profitTargetGp == null ? null : activeMillis;
        return profitTargetGp != null;
    }

    /** Active Time the Net aim has run for; the whole run on older saves. */
    long profitTargetActiveMillis(long elapsedMillis) {
        return nonNeg(elapsedMillis - (profitTargetSetActiveMillis == null ? 0L : profitTargetSetActiveMillis));
    }

    /** The actual Active-Time target this instance ran with; null when none was set. */
    Long getActiveTimeTargetMillis() {
        return activeTimeTargetMillis != null && activeTimeTargetMillis > 0L ? activeTimeTargetMillis : null;
    }

    /**
     * Sets the actual Active-Time target and restarts its count when the value changes (owner live
     * 2026-10-13): a target counts from the moment it was set, not from the run's start. An
     * unchanged value keeps the running count; a cleared one forgets it.
     */
    boolean setActiveTimeTargetMillis(Long value, long now) {
        Long next = value == null || value <= 0L ? null : value;
        if (Objects.equals(next, activeTimeTargetMillis)) {
            // Re-saving the same aim keeps a running window; a completed one starts over
            // (owner live 2026-10-13: Edit > Save after completion must begin again).
            if (next != null && getElapsedMillis(now) - getActiveTimeTargetSetMillis() >= next) {
                activeTimeTargetSetMillis = getElapsedMillis(now);
                activeTimeTargetPauseMillis = null;
                return true;
            }
            return false;
        }
        activeTimeTargetMillis = next;
        activeTimeTargetSetMillis = next == null ? null : getElapsedMillis(now);
        activeTimeTargetPauseMillis = null;
        return true;
    }

    /** The Active Time a set target counts from; 0 with none and on older saves. */
    long getActiveTimeTargetSetMillis() {
        return activeTimeTargetSetMillis == null || activeTimeTargetSetMillis < 0L ? 0L : activeTimeTargetSetMillis;
    }

    /** The window a set target has counted so far; frozen while the timer is paused. */
    long getActiveTimeTargetWindowMillis(long elapsedMillis) {
        long at = activeTimeTargetPauseMillis != null ? activeTimeTargetPauseMillis : max(0L, elapsedMillis);
        return max(0L, at - getActiveTimeTargetSetMillis());
    }

    /** True while the timer's own pause holds; the run keeps tracking (owner live 2026-10-14). */
    boolean isTimeTargetPaused() {
        return activeTimeTargetPauseMillis != null;
    }

    /** Freezes the timer's window where it stands; an ended window has nothing to stop. */
    boolean pauseTimeTarget(long now) {
        if (activeTimeTargetMillis == null || activeTimeTargetPauseMillis != null) return false;
        if (getActiveTimeTargetWindowMillis(getElapsedMillis(now)) >= activeTimeTargetMillis) {
            return false;
        }
        activeTimeTargetPauseMillis = getElapsedMillis(now);
        return true;
    }

    /** Resumes a paused timer, keeping the window it had already counted. */
    boolean resumeTimeTarget(long now) {
        if (activeTimeTargetMillis == null || activeTimeTargetPauseMillis == null) return false;
        activeTimeTargetSetMillis = getActiveTimeTargetSetMillis()
                        + max(0L, getElapsedMillis(now) - activeTimeTargetPauseMillis);
        activeTimeTargetPauseMillis = null;
        return true;
    }

    /**
     * Restarts the set target's count from now without changing its value (owner live 2026-10-13).
     */
    void rearmTimeTarget(long now) {
        if (activeTimeTargetMillis != null) {
            activeTimeTargetSetMillis = getElapsedMillis(now);
            activeTimeTargetPauseMillis = null;
        }
    }

    /** Stable My Grind lineage link; empty when this instance was never saved as a Grind. */
    String getGrindId() {
        return orEmpty(grindId);
    }

    void setGrindId(String value) {
        grindId = nonBlank(value, null);
    }

    boolean isLinked() {
        return !getGrindId().isEmpty();
    }

    void pause(long now, PauseReason reason) {
        if (!paused && endedAtEpochMillis == 0L) {
            paused = true;
            pausedAtEpochMillis = now;
            pauseReason = reason == null ? MANUAL : reason;
        }
    }

    void resume(long now) {
        if (paused && endedAtEpochMillis == 0L) {
            totalPausedMillis = safeAdd(totalPausedMillis, nonNeg(now - pausedAtEpochMillis));
            pausedAtEpochMillis = 0L;
            paused = false;
        }
        pauseReason = NONE;
    }

    PauseReason getPauseReason() {
        if (!paused) return NONE;
        return pauseReason == null || pauseReason == NONE ? MANUAL : pauseReason;
    }

    /** A closed run carries on: the time it was closed counts as paused (owner 1.5.2, Restore). */
    void reopen(long now) {
        if (paused) totalPausedMillis = safeAdd(totalPausedMillis, nonNeg(endedAtEpochMillis - pausedAtEpochMillis));
        totalPausedMillis = safeAdd(totalPausedMillis, nonNeg(now - endedAtEpochMillis));
        paused = false;
        pausedAtEpochMillis = 0L;
        pauseReason = NONE;
        endedAtEpochMillis = 0L;
        saveStamp++;
    }

    void close(long now) {
        if (endedAtEpochMillis != 0L) return;
        saveStamp++;
        endedAtEpochMillis = max(now, startedAtEpochMillis);
    }

    boolean correctTransaction(String transactionId, Correction correction, long now, String reason) {
        Transaction transaction = findTransaction(transactionId);
        return transaction != null && correct(singletonList(transaction), correction == null ? AUTO : correction, now,
                        reason);
    }

    /**
     * Automatic reconciliation of an automatic estimate against a measured Check: shrink it by
     * {@code quantity} of one item, voiding the row once it spends nothing. Automatic evidence, not
     * an owner correction, so nothing is logged; the change is announced like every other change.
     */
    void settleEstimate(Transaction estimate, int itemId, long quantity, String explanation) {
        if (estimate == null || itemId <= 0 || quantity <= 0L) return;
        Correction previous = estimate.getCorrection();
        List<Flow> previousFlows = estimate.getFlows();
        estimate.takeQuantity(itemId, false, quantity);
        estimate.confidence = Confidence.CONFIRMED;
        if (!estimate.spends()) estimate.applyCorrection(IGNORE, SafeMath.now(), explanation);
        estimate.setExplanation(explanation);
        changed(estimate, previous, previousFlows);
    }

    /**
     * Applies one decision to the still-unresolved transactions and stores one correction record,
     * so a single undo restores the complete operation.
     */
    int correctAll(List<String> transactionIds, Correction correction, long now, String reason) {
        Correction next = correction == null ? AUTO : correction;
        if (empty(transactionIds) || next == AUTO) return 0;
        var targets = new ArrayList<Transaction>();
        for (String transactionId : new LinkedHashSet<>(transactionIds)) {
            Transaction transaction = findTransaction(transactionId);
            if (ReviewRules.needsOwnerDecision(transaction)) targets.add(transaction);
        }
        return correct(targets, next, now, nonBlank(reason, msg("bulk-review"))) ? targets.size() : 0;
    }

    /**
     * One owner decision over rows: every row is checked with the owned-value observer before any
     * changes (one blocked row rejects the whole decision), then one undoable record is logged.
     */
    boolean correct(List<Transaction> targets, Correction next, long now, String reason) {
        var changes = new ArrayList<Change>();
        for (Transaction transaction : targets) {
            if (!canChangeOwnedValue(transaction, transaction.getCorrection(), transaction.getFlows(), next,
                    transaction.getFlows())) {
                // The item's known coverage is reserved or already realized; leave the rows
                // untouched.
                return false;
            }
            changes.add(new Change(transaction.getId(), transaction.getCorrection(), next, null, null));
        }
        for (Transaction transaction : targets) {
            Correction previous = transaction.getCorrection();
            transaction.applyCorrection(next, now, reason);
            changed(transaction, previous, transaction.getFlows());
        }
        if (!changes.isEmpty()) correctionHistory.add(new CorrectionRecord(reason, changes));
        return !changes.isEmpty();
    }

    /**
     * Personal item split: Net keeps only {@code keepQuantity} of {@code itemId}. Given-away qty is
     * removed from counted gain (not Used). Full give-away on a single-item row IGNORE-corrects.
     * Shares the correction undo stack.
     */
    boolean splitItem(String transactionId, int itemId, long keepQuantity, long now, String optionalNote) {
        Transaction transaction = findTransaction(transactionId);
        if (transaction == null || itemId <= 0) return false;
        long totalGain = transaction.quantity(itemId, true);
        if (totalGain <= 0L) return false;
        long keep = nonNeg(min(keepQuantity, totalGain));
        if (keep == totalGain) return false;
        String reason = ItemSplits.reason(keep, totalGain, optionalNote);
        Correction previous = transaction.getCorrection();
        var flowSnapshot = new ArrayList<Flow>(transaction.getFlows());
        String explanationSnapshot = transaction.getExplanation();
        boolean ignore = keep <= 0L && onlyGainItem(transaction, itemId);
        if (!canChangeOwnedValue(transaction, previous, flowSnapshot, ignore ? IGNORE : previous, null)) {
            // The known coverage this split would shrink is reserved or already realized.
            return false;
        }
        if (ignore) transaction.applyCorrection(IGNORE, now, reason);
        else transaction.takeQuantity(itemId, true, totalGain - keep);
        transaction.stampSplit(reason, now);
        changed(transaction, previous, flowSnapshot);
        log(now, reason, new Change(transactionId, previous, transaction.getCorrection(), flowSnapshot,
                        explanationSnapshot));
        return true;
    }

    /**
     * Reverts the most recent correction/split when a flow snapshot is present, or restores the
     * previous correction enum otherwise.
     */
    boolean undoCorrection(long now) {
        if (correctionHistory.isEmpty()) return false;
        CorrectionRecord last = null;
        for (int index = correctionHistory.size() - 1; index >= 0; index--) {
            CorrectionRecord candidate = correctionHistory.get(index);
            if (candidate != null && !candidate.isUndone()) {
                last = candidate;
                break;
            }
        }
        if (last == null) return false;
        List<Change> changes = last.getChanges();
        if (changes.isEmpty()) return false;
        var targets = new ArrayList<Transaction>(changes.size());
        for (Change change : changes) {
            Transaction transaction = findTransaction(change.getTransactionId());
            if (transaction == null) {
                // Fail closed: never partially undo a batch after retention or deletion.
                return false;
            }
            targets.add(transaction);
        }
        // Validate the whole restore before any canonical mutation.
        for (int index = 0; index < changes.size(); index++) {
            Change change = changes.get(index);
            Transaction transaction = targets.get(index);
            List<Flow> nextFlows = change.hasFlowSnapshot() ? change.getFlowSnapshot() : transaction.getFlows();
            if (!canChangeOwnedValue(transaction, transaction.getCorrection(), transaction.getFlows(),
                    change.getPreviousCorrection(), nextFlows)) {
                return false;
            }
        }
        for (int index = changes.size() - 1; index >= 0; index--) {
            Change change = changes.get(index);
            Transaction transaction = targets.get(index);
            Correction previous = transaction.getCorrection();
            List<Flow> previousFlows = transaction.getFlows();
            if (change.hasFlowSnapshot()) transaction.replaceFlows(change.getFlowSnapshot());
            if (change.explanationSnapshot != null)
                transaction.setExplanation(change.explanationSnapshot);
            transaction.applyCorrection(change.getPreviousCorrection(), now);
            transaction.correctionReason = previousReason(transaction.getId(), last);
            changed(transaction, previous, previousFlows);
        }
        last.undone = true;
        return true;
    }

    /** Restore metadata from the retained decision timeline without adding save fields. */
    String previousReason(String transactionId, CorrectionRecord undone) {
        for (int index = correctionHistory.indexOf(undone) - 1; index >= 0; index--) {
            CorrectionRecord record = correctionHistory.get(index);
            if (record == null || record.isUndone()) continue;
            for (Change change : record.getChanges()) {
                if (transactionId.equals(change.getTransactionId()) && (!change.hasFlowSnapshot()
                                || change.getPreviousCorrection() != change.newCorrection
                                || ItemSplits.isSplitReason(record.getReason())))
                    return record.getReason();
            }
        }
        return "";
    }

    static boolean onlyGainItem(Transaction transaction, int itemId) {
        if (transaction == null) return false;
        boolean sawTarget = false;
        for (Flow flow : transaction.getFlows()) {
            if (flow.quantityDelta == 0L) continue;
            if (flow.itemId != itemId) return false;
            if (flow.quantityDelta > 0L) sawTarget = true;
        }
        return sawTarget;
    }

    /**
     * A dropped item picked back up: the Dropped row loses that quantity, and is excluded once it
     * spends nothing, so the drop and its pickup never show as a loss and a gain. Returns how many
     * the row still held to give back.
     */
    long pickUp(String dropId, int itemId, long quantity, long now) {
        Transaction drop = findTransaction(dropId);
        if (drop == null || !drop.isCounted() || drop.getCorrection() != AUTO) return 0L;
        long taken = min(quantity, drop.quantity(itemId, false));
        if (taken <= 0L) return 0L;
        var flowSnapshot = new ArrayList<Flow>(drop.getFlows());
        drop.takeQuantity(itemId, false, taken);
        if (!drop.spends()) drop.applyCorrection(IGNORE, now, "Picked back up");
        changed(drop, AUTO, flowSnapshot);
        return taken;
    }

    /** Drops a neutral row the engine no longer keeps (old bank-paid GE change, owner 1.5.1). */
    void drop(Transaction transaction) {
        if (!transactions.remove(transaction)) return;
        saveStamp++;
        notifyChanged();
        if (ownedValueObserver != null) ownedValueObserver.onRemoved(transaction);
    }

    Transaction undoTransaction() {
        if (transactions.isEmpty()) return null;
        Transaction removed = transactions.get(transactions.size() - 1);
        if (ownedValueObserver != null && !ownedValueObserver.canRemove(removed)) {
            // Known coverage was already reserved/realized downstream; leave it untouched.
            return null;
        }
        transactions.remove(transactions.size() - 1);
        notifyChanged();
        if (ownedValueObserver != null) ownedValueObserver.onRemoved(removed);
        undoHistory.add(new UndoRecord(removed));
        int overflow = undoHistory.size() - MAX_UNDO_HISTORY;
        if (overflow > 0) undoHistory.subList(0, overflow).clear();
        return removed;
    }

    Transaction restoreUndo() {
        for (int index = undoHistory.size() - 1; index >= 0; index--) {
            UndoRecord record = undoHistory.get(index);
            if (record == null || record.restored || record.transaction == null) continue;
            Transaction restored = record.transaction;
            if (ownedValueObserver != null && !ownedValueObserver.canAdd(restored)) {
                // Restoring would re-add known coverage after a later realization; refuse it.
                return null;
            }
            int effectiveLimit = transactionLimit <= 0 ? 2_000 : transactionLimit;
            // Restoring an undo is also a bounded-ledger insertion: the displaced row is summarized
            // exactly.
            evict(transactions.size() + 1 - effectiveLimit);
            transactions.add(restored);
            transactionChanged(restored);
            notifyOwnedValue(restored, false);
            record.restored = true;
            return restored;
        }
        return null;
    }

    Transaction findTransaction(String transactionId) {
        if (empty(transactionId)) return null;
        for (Transaction transaction : transactions) {
            if (transactionId.equals(transaction.getId())) return transaction;
        }
        return null;
    }

    /** Counts one kill or death on this Grind and returns the id its receipts carry. */
    String addEncounter(boolean kill, long now) {
        String id = pk().record(kill);
        notifyChanged();
        recordAction("PKing", now);
        return id;
    }

    void attachToEncounter(String transactionId, String encounterId, boolean asPkSupplyCost) {
        Transaction transaction = findTransaction(transactionId);
        if (transaction == null || empty(encounterId) || !PkTally.isEncounter(encounterId)) return;
        saveStamp++;
        transaction.assignEncounter(encounterId, asPkSupplyCost);
        notifyChanged();
    }

    void attachRecentCosts(String encounterId, long now, long lookbackMillis) {
        long cutoff = nonNeg(now - max(0L, lookbackMillis));
        for (int index = transactions.size() - 1; index >= 0; index--) {
            Transaction transaction = transactions.get(index);
            if (transaction.timestampEpochMillis < cutoff) break;
            if (!transaction.getEncounterId().isEmpty()) continue;
            if (transaction.revenue == 0L && transaction.costs > 0L
                    && transaction.autoType() == TransactionType.CONSUMPTION) {
                attachToEncounter(transaction.getId(), encounterId, true);
            }
        }
    }

    void compactTransaction(Transaction transaction) {
        if (transaction == null) return;
        compactedTransactionCount++;
        if (transaction.isOnGround()) usedUp(transaction);
        pk().compact(transaction, transactions);
        if (transaction.getType() == TransactionType.TRANSFER) return;
        if (transaction.isCounted()) {
            Amounts amounts = transaction(transaction);
            retainedRevenue = safeAdd(retainedRevenue, amounts.revenue);
            retainedCosts = safeAdd(retainedCosts, amounts.costs);
            Accounting.CostSplit split = costSplit(transaction);
            if (!split.available) retainedCostSplitComplete = false;
            else retainedSuppliesCosts = safeAdd(retainedSuppliesCosts, split.supplies);
        }
    }

    /** A counted row changed: advance the revision. */
    void transactionChanged(Transaction transaction) {
        if (transaction != null) notifyChanged();
    }

    PkTally pk() {
        if (pk == null) pk = new PkTally();
        return pk;
    }

    long bestKill() {
        return pk().bestKill(transactions);
    }

    @AllArgsConstructor
    static class MoneyFold {
        long revenue;
        long costs;
        long supplies;
        boolean costSplitAvailable = true;

        Amounts add(Transaction transaction) {
            Amounts amounts = transaction(transaction);
            if (!amounts.available || !amounts.included) return amounts;
            revenue = safeAdd(revenue, amounts.revenue);
            costs = safeAdd(costs, amounts.costs);
            Accounting.CostSplit split = costSplit(transaction);
            if (!split.available) costSplitAvailable = false;
            else supplies = safeAdd(supplies, split.supplies);
            return amounts;
        }
    }

    Metrics metrics(long now) {
        return metrics(new MoneyFold(retainedRevenue, retainedCosts, retainedSuppliesCosts,
                        compactedTransactionCount == 0L || retainedCostSplitComplete), transactions,
                getElapsedMillis(now));
    }

    /**
     * Rows booked at or after {@code at}: a target run's own (owner 1.5.2). A correction keeps its
     * row's time, so fixes to older rows stay out; rows compacted past the row limit drop out.
     */
    List<Transaction> rowsSince(long at) {
        var rows = new ArrayList<Transaction>();
        for (Transaction row : transactions)
            if (row != null && row.timestampEpochMillis >= at) rows.add(row);
        return rows;
    }

    /** The money in these rows alone, over the given Active Time. */
    Metrics metrics(List<Transaction> rows, long elapsed) {
        return metrics(new MoneyFold(0L, 0L, 0L, true), rows, elapsed);
    }

    Metrics metrics(MoneyFold money, List<Transaction> rows, long elapsed) {
        for (Transaction transaction : rows) {
            if (transaction == null) continue;
            money.add(transaction);
        }
        if (money.supplies > money.costs) money.costSplitAvailable = false;
        long net = safeSubtract(money.revenue, money.costs);
        return new Metrics(getActivityHint(), paused, elapsed, money.revenue, money.costs, net, hourly(net, elapsed),
                money.costSplitAvailable ? money.supplies : 0L,
                money.costSplitAvailable ? safeSubtract(money.costs, money.supplies) : 0L, money.costSplitAvailable);
    }

    /**
     * The correction-aware money folded out of individually inspectable rows by compaction.
     * Retained rows plus this contribution reconcile exactly to {@link #metrics}.
     */
    @AllArgsConstructor
    static class CompactedContribution {
        long rows;
        long revenue;
        long costs;
        long suppliesCosts;
        boolean costSplitAvailable;

        long getNet() {
            return safeSubtract(revenue, costs);
        }
    }

    CompactedContribution compactedContribution() {
        return new CompactedContribution(compactedTransactionCount, retainedRevenue, retainedCosts,
                retainedSuppliesCosts, compactedTransactionCount == 0L || retainedCostSplitComplete);
    }

    long compactedRevenue() {
        return retainedRevenue;
    }

    long compactedCosts() {
        return retainedCosts;
    }

    static long hourly(long value, long elapsedMillis) {
        if (elapsedMillis <= 0L) return 0L;
        // Math.round saturates at the long range by itself.
        return round(value * (3_600_000.0d / elapsedMillis));
    }

    long getElapsedMillis(long now) {
        long endpoint = endedAtEpochMillis == 0L ? now : endedAtEpochMillis;
        long activePaused = paused ? nonNeg(endpoint - pausedAtEpochMillis) : 0L;
        return nonNeg(endpoint - startedAtEpochMillis - totalPausedMillis - activePaused);
    }

    static String normalizeName(String value) {
        if (blank(value)) return DURABLE_OWNER_NAME;
        return value.trim();
    }

    String getId() {
        if (empty(id)) id = UUID.randomUUID().toString();
        return id;
    }

    String getName() {
        return normalizeName(name);
    }

    void setChangeListener(Runnable listener) {
        changeListener = listener;
    }

    void notifyChanged() {
        saveStamp++;
        Runnable listener = changeListener;
        if (listener != null) listener.run();
    }

    String getActivityHint() {
        return normalizeActivity(activityHint);
    }

    SessionMode getMode() {
        return mode == null ? SessionMode.GENERAL : mode;
    }

    boolean isClosed() {
        return endedAtEpochMillis != 0L;
    }

    Long getProfitTargetGp() {
        return profitTargetGp != null && profitTargetGp > 0L ? profitTargetGp : null;
    }

    /** A loaded session is cleaned once: no null rows or flows reach any reader. */
    void sanitize() {
        if (transactions == null) transactions = new ArrayList<>();
        transactions.removeIf(java.util.Objects::isNull);
        for (Transaction transaction : transactions) transaction.sanitize();
    }

    List<Transaction> getTransactions() {
        return unmodifiableList(transactions);
    }

    /** Timestamp of the oldest retained row, or {@code Long.MIN_VALUE} when none is retained. */

    /**
     * Receipt retention (section L): folds retained rows dated before {@code cutoffEpochMillis}
     * into this session's correction-aware archive totals, oldest first, skipping rows the caller
     * still needs individually (an unresolved claim's audit row or its settlement). Undo/correction
     * entries that reference a folded row are pruned at the same boundary. Compacted rows are no
     * longer individually correctable; totals stay exact.
     */
    int compactBefore(long cutoffEpochMillis, Predicate<Transaction> keep) {
        if (transactions.isEmpty()) return 0;
        var folded = new ArrayList<Transaction>();
        for (Transaction transaction : transactions) {
            if (transaction == null) continue;
            if (transaction.timestampEpochMillis >= cutoffEpochMillis) continue;
            if (keep != null && keep.test(transaction)) continue;
            folded.add(transaction);
        }
        if (folded.isEmpty()) return 0;
        saveStamp++;
        var foldedIds = new HashSet<String>();
        for (Transaction transaction : folded) {
            foldedIds.add(transaction.getId());
            transactions.remove(transaction);
            compactTransaction(transaction);
        }
        undoHistory.removeIf(record -> record != null && record.transaction != null
                                && foldedIds.contains(record.transaction.getId()));
        correctionHistory.removeIf(record -> record != null && record.touchesAny(foldedIds));
        return folded.size();
    }
}

/**
 * AUTO sessions follow the detected activity; every session the engine opens (Overall and each
 * Grind) is AUTO. GENERAL is the plain default of a bare {@code new Session}.
 */
enum SessionMode {
    AUTO, GENERAL
}

/** Persisted ownership of a paused session. NONE means the session is running. */
enum PauseReason {
    NONE, MANUAL, IDLE, LIFECYCLE, RECOVERY, CUSTOM_SESSION, WORLD
}

/** A transaction removed through the undo action, kept so the latest one can be restored. */
class UndoRecord {
    Transaction transaction;
    boolean restored;

    UndoRecord() {
        // Gson
    }

    UndoRecord(Transaction transaction) {
        this.transaction = transaction;
    }
}

/** Only the canonical money, active clock and rate facts consumed by presentation and export. */
class Metrics {
    String activityHint;
    boolean paused;
    long elapsedMillis;
    long revenue;
    long costs;
    long net;
    long profitPerHour;
    long suppliesCosts;
    long otherCosts;
    boolean costSplitAvailable;

    static Metrics none() {
        return new Metrics("General", false, 0L, 0L, 0L, 0L, 0L);
    }

    Metrics(String activityHint, boolean paused, long elapsedMillis, long revenue, long costs, long net,
            long profitPerHour) {
        this(activityHint, paused, elapsedMillis, revenue, costs, net, profitPerHour, 0L, 0L, false);
    }

    Metrics(String activityHint, boolean paused, long elapsedMillis, long revenue, long costs, long net,
            long profitPerHour, long suppliesCosts, long otherCosts, boolean costSplitAvailable) {
        this.activityHint = activityHint;
        this.paused = paused;
        this.elapsedMillis = elapsedMillis;
        this.revenue = revenue;
        this.costs = costs;
        this.net = net;
        this.profitPerHour = profitPerHour;
        this.suppliesCosts = suppliesCosts;
        this.otherCosts = otherCosts;
        this.costSplitAvailable = costSplitAvailable && safeAdd(suppliesCosts, otherCosts) == costs;
    }
}

/**
 * Closed-session history management and receipt retention: UTC-day compaction sweeps, retention
 * status, profile size/data-health facts and the history session reads/edits. The history list
 * itself stays on the engine because owner lifecycle appends to it. Invoked only under the {@link
 * Engine} monitor.
 */
@RequiredArgsConstructor
class SessionArchive {
    /** UTC day of the last receipt-retention sweep; null before the first one this run. */
    LocalDate lastSweepDay;

    final Engine engine;

    void clear() {
        lastSweepDay = null;
    }

    /** Post-restore compaction with the configured window; it counts as today's sweep. */
    void compactAfterRestore(long now) {
        compactOlderThan(retentionDays(), now);
        lastSweepDay = utcDay(now);
    }

    void adoptFrom(SessionArchive staged) {
        lastSweepDay = staged.lastSweepDay;
    }

    /** The configured receipt retention in days; 0 keeps receipts forever. */
    int retentionDays() {
        Retention period = engine.config.receiptRetentionDays();
        return period == null ? Retention.DAYS_90.days : period.days;
    }

    static LocalDate utcDay(long now) {
        return Instant.ofEpochMilli(now).atZone(ZoneOffset.UTC).toLocalDate();
    }

    void trimHistory() {
        int maxHistory = Math.max(1, engine.config.maxHistorySessions());
        if (engine.history.size() > maxHistory) {
            engine.history.subList(maxHistory, engine.history.size()).clear();
            engine.bumpRevision();
        }
    }

    /**
     * Compacts closed sessions strictly older than {@code days}; a zero window means forever and
     * performs no compaction. The session metadata and all retained accounting aggregates remain
     * available.
     *
     * @return receipt rows compacted
     */
    int compactOlderThan(int days, long now) {
        if (days <= 0) return 0;
        long cutoff;
        try {
            cutoff = Instant.ofEpochMilli(now).minus(days, ChronoUnit.DAYS).toEpochMilli();
        } catch (RuntimeException ex) {
            cutoff = Long.MIN_VALUE;
        }
        // Rows still needed individually: an unresolved claim's audit row and the settlement that
        // carries a claim id keep their detail until the claim resolves (section L).
        Set<String> pendingClaimIds = engine.pendingClaimIds();
        Predicate<Transaction> keep = transaction -> isPendingClaimRow(transaction, pendingClaimIds)
                                || (!transaction.sourceClaimId().isEmpty()
                                        && pendingClaimIds.contains(transaction.sourceClaimId()));
        int compactedReceipts = 0;
        for (Session session : engine.uniqueSessions()) {
            if (session == null || session.getTransactions().isEmpty()) continue;
            compactedReceipts = SafeMath.safeAddCount(compactedReceipts, session.compactBefore(cutoff, keep));
        }
        if (compactedReceipts > 0) engine.bumpRevision();
        return compactedReceipts;
    }

    /**
     * A multi-key audit row owns claims named {@code auditId#n}; retain its base row while any
     * derived claim remains unresolved so provenance survives receipt compaction.
     */
    static boolean isPendingClaimRow(Transaction transaction, Set<String> pendingClaimIds) {
        if (transaction == null || empty(pendingClaimIds)) return false;
        String transactionId = transaction.getId();
        if (pendingClaimIds.contains(transactionId)) return true;
        String derivedPrefix = transactionId + "#";
        for (String claimId : pendingClaimIds) {
            if (claimId != null && claimId.startsWith(derivedPrefix)) return true;
        }
        return false;
    }

    /**
     * The game tick's daily sweep: the first tick of each later UTC day compacts once. The first
     * tick of a run only marks the day, since a restore already swept.
     */
    int maintainRetention(long now) {
        LocalDate today = utcDay(now);
        if (lastSweepDay != null && !today.isAfter(lastSweepDay)) return 0;
        boolean first = lastSweepDay == null;
        lastSweepDay = today;
        return first ? 0 : compactOlderThan(retentionDays(), now);
    }

    Session historySession(String sessionId) {
        if (empty(sessionId)) return null;
        for (Session session : engine.history) {
            if (sessionId.equals(session.getId())) return session;
        }
        return null;
    }

    Metrics historyMetrics(String sessionId, long now) {
        Session session = historySession(sessionId);
        return session == null ? null : session.metrics(now);
    }

    boolean deleteHistory(String sessionId) {
        Session session = historySession(sessionId);
        if (session == null) return false;
        engine.history.remove(session);
        engine.bumpRevision();
        return true;
    }
}

package com.gpmanager;

import static com.gpmanager.ActionKind.*;
import static com.gpmanager.Correction.*;
import static com.gpmanager.GameData.msg;
import static com.gpmanager.Phrases.*;
import static com.gpmanager.PriceSource.*;
import static com.gpmanager.SafeMath.*;
import static com.gpmanager.TransactionType.*;
import static java.lang.Math.min;
import static java.util.Collections.*;

import java.util.*;
import lombok.*;
import com.gpmanager.ActionReader.PartialUse;

/**
 * Canonical durable financial fact: stable id, timestamp, type/context, booked item flows, the
 * automatic counted state, confidence, correction and split state, and optional links to a PvP
 * encounter or the pending claim it settled. Booked values are never repriced.
 */
class Transaction {
    String id;
    long timestampEpochMillis;
    TransactionType type;
    Context context;
    String note;
    String activityName;
    boolean counted;
    List<Flow> flows;
    long revenue;
    long costs;
    Confidence confidence;
    String explanation;
    Correction correction;
    String correctionReason;
    String encounterId;

    /**
     * Dropped or fired, its pickup window still open: picking it up shrinks this row, so it leaves
     * the paid-price record only once the window closes. Saved only while true.
     */
    Boolean onGround;

    boolean isOnGround() {
        return Boolean.TRUE.equals(onGround);
    }

    void setOnGround(boolean value) {
        onGround = value ? Boolean.TRUE : null;
    }

    /** The pending claim this settlement resolved, when any; idempotency key on load. */
    String sourceClaimId;

    /** Observed action wire name (B10 presentation evidence); null when unsupported/legacy. */
    String actionKind;

    /**
     * Durable bounded exact action label (schema 105), e.g. "Ice Burst". Presentation-only metadata
     * attached to an already-booked canonical transaction: it never feeds classification,
     * valuation, counted state, ownership, Review or correction. Revalidated on load; invalid text
     * degrades to null and generic presentation.
     */
    String observedActionLabel;

    /** Transient icon hint for an estimated charge cast: the weapon's item id; never saved. */
    transient int castItemId;

    Transaction() {
        // Gson
    }

    Transaction(long timestampEpochMillis, TransactionType type, Context context, String note, String activityName,
            boolean counted, List<Flow> flows, Confidence confidence, String explanation, String encounterId) {
        id = UUID.randomUUID().toString();
        this.timestampEpochMillis = timestampEpochMillis;
        this.type = type;
        this.context = context;
        this.note = orEmpty(note);
        this.activityName = normalizeActivity(activityName);
        this.counted = counted;
        this.flows = flows == null ? new ArrayList<>() : new ArrayList<>(flows);
        this.confidence = confidence == null ? Confidence.UNCERTAIN : confidence;
        this.explanation = orEmpty(explanation);
        correction = Correction.AUTO;
        correctionReason = "";
        this.encounterId = encounterId;
        recalculate();
    }

    void recalculate() {
        revenue = 0L;
        costs = 0L;
        for (Flow flow : flows) {
            if (flow.valueDelta > 0) revenue = safeAdd(revenue, flow.valueDelta);
            else if (flow.valueDelta < 0) costs = safeAdd(costs, abs(flow.valueDelta));
        }
    }

    void applyCorrection(Correction newCorrection, long now) {
        applyCorrection(newCorrection, now, "Manual correction");
    }

    void applyCorrection(Correction newCorrection, long now, String reason) {
        correction = newCorrection == null ? Correction.AUTO : newCorrection;
        correctionReason = normalizeReason(reason);
    }

    /**
     * Takes {@code amount} of one item's gains (newest flow first) or costs (oldest first) out of
     * the flows, each remainder keeping its own unit value, and returns the quantity left.
     */
    long takeQuantity(int itemId, boolean gains, long amount) {
        var ordered = new ArrayList<Flow>(getFlows());
        if (gains) reverse(ordered);
        var next = new ArrayList<Flow>();
        for (Flow flow : ordered) {
            long magnitude = abs(flow.quantityDelta);
            long take = flow.itemId == itemId && (gains ? flow.isGain() : flow.isCost())
                            ? Math.min(nonNeg(amount), magnitude) : 0L;
            amount -= take;
            long left = magnitude - take;
            if (take <= 0L) {
                next.add(flow);
            } else if (left > 0L) {
                long unit = flow.unitPrice;
                long signed = gains ? left : -left;
                next.add(new Flow(itemId, flow.itemName, signed, flow.unitPrice,
                                unit == 0L ? flow.valueDelta / magnitude * left : signed * unit, flow.getPriceSource(),
                                flow.getPriceCapturedAtEpochMillis()));
            }
        }
        if (gains) reverse(next);
        replaceFlows(next);
        return quantity(itemId, gains);
    }

    /** True while any flow still spends an item; a blowpipe shot keeps its scales after a dart. */
    boolean spends() {
        for (Flow flow : getFlows()) {
            if (flow.isCost()) return true;
        }
        return false;
    }

    void replaceFlows(List<Flow> nextFlows) {
        flows = nextFlows == null ? new ArrayList<>() : new ArrayList<>(nextFlows);
        recalculate();
    }

    /**
     * Resolve an automatic charge-load Review row as a neutral transfer after a same-target
     * measured Check confirms its component quantities.
     */

    /**
     * Stamps split provenance on explanation/reason without changing the correction enum (partial
     * keep stays counted).
     */
    void stampSplit(String reason, long now) {
        String mark = reason == null ? ItemSplits.SPLIT_SHARE_MARK : reason.trim();
        if (mark.isEmpty()) mark = ItemSplits.SPLIT_SHARE_MARK;
        correctionReason = normalizeReason(mark);
        String current = getExplanation();
        if (!ItemSplits.isSplitReason(current)) {
            explanation = current.isEmpty() ? mark : current + " — " + mark;
        } else if (!current.contains(mark)) {
            explanation = current + " — " + mark;
        }
    }

    void setExplanation(String next) {
        explanation = orEmpty(next);
    }

    /** Total gained ({@code gains}) or lost quantity of one item across the remaining flows. */
    long quantity(int itemId, boolean gains) {
        long total = 0L;
        for (Flow flow : flows) {
            if (flow.itemId == itemId && (gains ? flow.isGain() : flow.isCost())) {
                total = safeAdd(total, abs(flow.quantityDelta));
            }
        }
        return total;
    }

    void assignEncounter(String newEncounterId, boolean asPkSupplyCost) {
        encounterId = newEncounterId;
        if (asPkSupplyCost && autoType() == CONSUMPTION) {
            type = PK_SUPPLY_COST;
            activityName = "PKing";
            confidence = Confidence.LIKELY;
            explanation = msg("supply-loss-occurred");
        }
    }

    long gross() {
        return safeAdd(revenue, costs);
    }

    String getId() {
        if (empty(id)) id = UUID.randomUUID().toString();
        return id;
    }

    TransactionType autoType() {
        return type == null ? ADJUSTMENT : type;
    }

    TransactionType getType() {
        switch (getCorrection()) {
            case REVENUE:
                return GAIN;
            case COST:
                return CONSUMPTION;
            case TRANSFER:
                return TransactionType.TRANSFER;
            case IGNORE:
                return ADJUSTMENT;
            case AUTO:
            default:
                return autoType();
        }
    }

    Context getContext() {
        return context == null ? Context.GENERIC : context;
    }

    String getNote() {
        return orEmpty(note);
    }

    /** Presentation-only audit-row note update; accounting fields are untouched. */
    String getActivityName() {
        if (!blank(activityName)) return activityName.trim();
        String safeNote = getNote();
        String prefix = "Loot from ";
        return safeNote.startsWith(prefix) && safeNote.length() > prefix.length()
                ? safeNote.substring(prefix.length()).trim() : "General";
    }

    boolean isCounted() {
        Correction safeCorrection = getCorrection();
        return safeCorrection == Correction.REVENUE || safeCorrection == Correction.COST
                || (safeCorrection == Correction.AUTO && counted);
    }

    /** Raw automatic counted flag, before any correction makes the row count. */
    boolean autoCounted() {
        return counted;
    }

    List<Flow> getFlows() {
        return unmodifiableList(flows);
    }

    /** A loaded row is cleaned once (no missing or null flows), so readers never re-check. */
    void sanitize() {
        if (flows == null) flows = new ArrayList<>();
        flows.removeIf(java.util.Objects::isNull);
    }

    long autoNet() {
        return safeSubtract(revenue, costs);
    }

    long getRevenue() {
        switch (getCorrection()) {
            case REVENUE:
                return gross();
            case COST:
            case TRANSFER:
            case IGNORE:
                return 0L;
            case AUTO:
            default:
                return revenue;
        }
    }

    long getCosts() {
        switch (getCorrection()) {
            case COST:
                return gross();
            case REVENUE:
            case TRANSFER:
            case IGNORE:
                return 0L;
            case AUTO:
            default:
                return costs;
        }
    }

    long getNet() {
        return safeSubtract(getRevenue(), getCosts());
    }

    /**
     * Personal-Net contribution this row would have under {@code hypothetical} (0 when it would not
     * count).
     */
    long netUnder(Correction hypothetical) {
        switch (hypothetical == null ? Correction.AUTO : hypothetical) {
            case REVENUE:
                return gross();
            case COST:
                return safeSubtract(0L, gross());
            case TRANSFER:
            case IGNORE:
                return 0L;
            case AUTO:
            default:
                return counted ? safeSubtract(revenue, costs) : 0L;
        }
    }

    Confidence getConfidence() {
        return confidence == null ? Confidence.UNCERTAIN : confidence;
    }

    String getExplanation() {
        return orEmpty(explanation);
    }

    Correction getCorrection() {
        return correction == null ? Correction.AUTO : correction;
    }

    String correctionReason() {
        return nonBlank(correctionReason, "");
    }

    String getEncounterId() {
        return orEmpty(encounterId);
    }

    String sourceClaimId() {
        return orEmpty(sourceClaimId);
    }

    /**
     * Links this settlement to the claim it resolved; set once, in the same revision the claim is
     * removed.
     */
    void setSourceClaimId(String claimId) {
        sourceClaimId = nonBlank(claimId, null);
    }

    /** Observed action behind this change, or null when no honest verb was evidenced. */
    ActionKind getActionKind() {
        return fromWireName(actionKind);
    }

    /** Presentation-only stamp; never alters type, valuation, counted state or ownership. */
    void setActionKind(ActionKind kind) {
        actionKind = kind == null ? null : kind.wireName();
    }

    /** Exact action text captured from a trusted client widget, or null for generic/legacy rows. */
    ActionLabel actionLabel() {
        return ActionLabel.of(labelWire());
    }

    /**
     * A Cast's name for presentation: the captured spell, else (autocast never clicks one) the
     * spell its exact runes pay for; "" otherwise. Never stored.
     */
    String spellName() {
        return memo(7, () -> {
                    // Runes that identify a spell win over a click queued behind an autocast (owner
                    // 2026-09-28);
                    // otherwise the clicked name stands (a staff-covered or non-combat spell).
                    String spell = getActionKind() == CAST ? Spells.spellFor(getFlows()) : null;
                    ActionLabel label = actionLabel();
                    return spell != null ? spell : label == null ? "" : label.value();
                });
    }

    /** Derived-value memo (release pass): every refresh reads each receipt; never stored. */
    transient Object[] memo;

    /**
     * Slots 6+ hold derived values; the array is replaced as soon as flows, correction, type,
     * counted, action or label change (each is replaced, never edited in place).
     */
    @SuppressWarnings("unchecked")
    <T> T memo(int slot, java.util.function.Supplier<T> build) {
        Object[] cache = memo;
        if (cache == null || cache[0] != flows || cache[1] != correction || cache[2] != type
                || cache[3] != (Boolean) counted || cache[4] != actionKind || cache[5] != observedActionLabel) {
            cache = new Object[] {
                        flows, correction, type, counted, actionKind, observedActionLabel, null, null, null, null, null
                    };
            memo = cache;
        }
        if (cache[slot] == null) cache[slot] = build.get();
        return (T) cache[slot];
    }

    /** Presentation only. Stores only the normalized bounded label text. */
    void setActionLabel(ActionLabel label) {
        observedActionLabel = label == null ? null : label.value();
    }

    /**
     * The only accepted label value, revalidated on every read: bounded, sanitized, non-generic and
     * attached to a CAST or DRINK transaction. Oversized, markup, control-character or generic
     * saved text reads as no label, so a damaged save degrades to generic wording instead of
     * failing.
     */
    String labelWire() {
        if (empty(observedActionLabel)) return null;
        if (getActionKind() != CAST && getActionKind() != ActionKind.DRINK) return null;
        ActionLabel normalized = ActionLabel.of(observedActionLabel);
        return normalized == null ? null : normalized.value();
    }

    static String normalizeReason(String value) {
        if (blank(value)) return "Manual correction";
        String trimmed = value.trim();
        return trimmed.length() > 200 ? trimmed.substring(0, 200) : trimmed;
    }
}

@AllArgsConstructor
enum Context {
    GENERIC(0), PRODUCTION(1), LOOT(2), PK_LOOT(3), MARKET(4), PK_DEATH(5), TRANSFER(6);
    @Getter int priority;
}

enum TransactionType {
    LOOT, CONSUMPTION, PROCESSING, TRADE, TRANSFER, GAIN, ADJUSTMENT, UNCERTAIN, PK_LOOT, PK_SUPPLY_COST, PK_DEATH_LOSS
}

/**
 * Personal item-split provenance helpers. Splits adjust personal Net share via the correction
 * timeline — never Party settlement, never fake Used eats.
 */
class ItemSplits {
    static final String SPLIT_SHARE_MARK = "Split share";
    static final String SPLIT_KEEP_PREFIX = "Split keep ";

    static String reason(long keepQuantity, long totalQuantity, String optionalNote) {
        long total = nonNeg(totalQuantity);
        long keep = nonNeg(min(keepQuantity, total));
        var sb = new StringBuilder(SPLIT_KEEP_PREFIX).append(keep).append('/').append(total).append(" · ")
                        .append(SPLIT_SHARE_MARK);
        if (optionalNote != null) {
            String trimmed = optionalNote.trim();
            if (!trimmed.isEmpty())
                sb.append(" · ").append(trimmed.length() > 80 ? trimmed.substring(0, 80) : trimmed);
        }
        String value = sb.toString();
        return value.length() > 200 ? value.substring(0, 200) : value;
    }

    static final java.util.Map<String, Boolean> SPLIT_TEXT = new java.util.concurrent.ConcurrentHashMap<>();

    static boolean isSplitReason(String reasonOrExplanation) {
        if (Phrases.empty(reasonOrExplanation)) return false;
        // Receipt texts are shared strings read on every tick: decide each distinct text once.
        if (SPLIT_TEXT.size() > 10_000) SPLIT_TEXT.clear();
        return SPLIT_TEXT.computeIfAbsent(reasonOrExplanation, text -> Phrases.has(
                                text.toLowerCase(java.util.Locale.ROOT), "split keep", "split share"));
    }
}

enum Correction {
    AUTO, REVENUE, COST, TRANSFER, IGNORE
}

enum Confidence {
    CONFIRMED, LIKELY, UNCERTAIN
}

/** A deliberate correction choice for an unresolved transaction. */
@AllArgsConstructor
enum Decision {
    GAIN(REVENUE), COST(Correction.COST), TRANSFER(Correction.TRANSFER), IGNORE(Correction.IGNORE);
    Correction correction;

    Correction toCorrection() {
        return correction;
    }
}

/** Shared accounting predicate for receipts that still need an owner decision. */
class ReviewRules {
    /**
     * Only unresolved automatic classifier decisions belong in the decision inbox. Ledger may
     * separately surface unknown pricing or provenance as review hints.
     */
    static boolean needsOwnerDecision(Transaction transaction) {
        return transaction != null && transaction.getCorrection() == Correction.AUTO
                && transaction.getConfidence() == Confidence.UNCERTAIN;
    }
}

/** One undoable owner decision: the before/after state of every row it changed. */
class CorrectionRecord {
    String reason;
    List<Change> changes;

    /** Set once the decision has been undone; an undone record is skipped by later undos. */
    boolean undone;

    CorrectionRecord() {
        // Gson
    }

    CorrectionRecord(String reason, List<Change> changes) {
        this.reason = Transaction.normalizeReason(reason);
        this.changes = new ArrayList<>(changes);
    }

    String getReason() {
        return Transaction.normalizeReason(reason);
    }

    boolean isUndone() {
        return undone;
    }

    /** The rows this decision changed. */
    List<Change> getChanges() {
        return changes == null ? emptyList() : unmodifiableList(changes);
    }

    /** True when any change in this record targets one of the given transaction ids. */
    boolean touchesAny(Set<String> transactionIds) {
        for (Change change : getChanges()) {
            if (transactionIds.contains(change.getTransactionId())) return true;
        }
        return false;
    }

    /**
     * One row's before/after state. The flow and explanation snapshots are set when the decision
     * changed the row's flows (split, own-drop recovery); flows are immutable, so they are shared.
     */
    @NoArgsConstructor
    @AllArgsConstructor
    static class Change {
        String transactionId;
        Correction previousCorrection;
        Correction newCorrection;
        List<Flow> flowSnapshot;
        String explanationSnapshot;

        String getTransactionId() {
            return orEmpty(transactionId);
        }

        Correction getPreviousCorrection() {
            return previousCorrection == null ? Correction.AUTO : previousCorrection;
        }

        List<Flow> getFlowSnapshot() {
            return flowSnapshot == null ? Collections.<Flow>emptyList() : unmodifiableList(flowSnapshot);
        }

        boolean hasFlowSnapshot() {
            return flowSnapshot != null;
        }
    }
}

@EqualsAndHashCode(exclude = "priceCapturedAtEpochMillis")
class Flow {
    int itemId;
    String itemName;
    long quantityDelta;
    int unitPrice;
    long valueDelta;
    PriceSource priceSource;

    /** Epoch-millis when the selected non-zero unit price was observed; zero when unavailable. */
    long priceCapturedAtEpochMillis;

    Flow() {
        // Gson
    }

    Flow(int itemId, String itemName, long quantityDelta, int unitPrice, long valueDelta) {
        this(itemId, itemName, quantityDelta, unitPrice, valueDelta, UNKNOWN);
    }

    Flow(int itemId, String itemName, long quantityDelta, int unitPrice, long valueDelta, PriceSource priceSource) {
        this(itemId, itemName, quantityDelta, unitPrice, valueDelta, priceSource, 0L);
    }

    Flow(int itemId, String itemName, long quantityDelta, int unitPrice, long valueDelta, PriceSource priceSource,
            long priceCapturedAtEpochMillis) {
        this.itemId = itemId;
        this.itemName = itemName;
        this.quantityDelta = quantityDelta;
        this.unitPrice = unitPrice;
        this.valueDelta = valueDelta;
        this.priceSource = priceSource == null ? UNKNOWN : priceSource;
        this.priceCapturedAtEpochMillis = priceCapturedAtEpochMillis;
    }

    PriceSource getPriceSource() {
        return priceSource == null ? UNKNOWN : priceSource;
    }

    long getPriceCapturedAtEpochMillis() {
        return SafeMath.nonNeg(priceCapturedAtEpochMillis);
    }

    /** {@code magnitude} units of this flow, signed like it, valued at {@code unit} each. */
    Flow part(long magnitude, long unit, PriceSource source) {
        long sign = quantityDelta < 0L ? -1L : 1L;
        return new Flow(itemId, itemName, sign * magnitude, SafeMath.toInt(unit),
                sign * SafeMath.safeMultiply(magnitude, unit), source, getPriceCapturedAtEpochMillis());
    }

    Flow part(long magnitude) {
        return part(magnitude, unitPrice, getPriceSource());
    }

    /**
     * What remains once {@code claimed} units leave at the unit price; null when nothing remains.
     */
    Flow rest(long claimed) {
        long left = SafeMath.abs(quantityDelta) - claimed;
        return claimed <= 0L ? this : left <= 0L ? null : new Flow(itemId, itemName, quantityDelta < 0L ? -left : left,
                                unitPrice, valueDelta - part(claimed).valueDelta, priceSource,
                                priceCapturedAtEpochMillis);
    }

    boolean isGain() {
        return quantityDelta > 0;
    }

    boolean isCost() {
        return quantityDelta < 0;
    }
}

/** Provenance of the unit price used for an item flow. */
@AllArgsConstructor
enum PriceSource {
    MANUAL_OVERRIDE("manual"),
    /** A catalogue proxy price: a market item's quote divided by its fixed exchange rate. */
    CURRENCY_PROXY("currency proxy"), GRAND_EXCHANGE("RuneLite market"), FACE_VALUE("face value"),
    /** High-alchemy value, for an ironman who chose to value items at their alch price. */
    HIGH_ALCHEMY("high alchemy"), DEFERRED_CLAIM("Claim on open"),
    /** Untradeable with no alch value: a known zero, never shown as an unknown price. */
    NO_VALUE("no value"), UNPRICED("unpriced"), UNKNOWN("unknown");
    String label;

    public String toString() {
        return label;
    }
}

/**
 * Bounded client-observed action text: durable presentation metadata since schema 105, never
 * financial.
 */
@AllArgsConstructor
class ActionLabel {
    static final int MAX_LENGTH = 64;
    String value;

    /**
     * Accept a name only from a Cast interaction whose associated widget belongs to the spellbook.
     * The menu target is deliberately absent from this API: NPC/player/item names cannot become
     * spell labels.
     *
     * <p>Used for both the direct spellbook click and the selected spell widget that RuneLite still
     * exposes during the following widget-target interaction.
     */
    static ActionLabel fromSpellMenu(String menuOption, int widgetId, int spellbookGroupId, String widgetText,
            String widgetName) {
        String option = clean(menuOption);
        if (!option.toLowerCase(java.util.Locale.ROOT).startsWith("cast")
                || ((widgetId >>> 16) & 0xffff) != (spellbookGroupId & 0xffff)) {
            return null;
        }
        String text = useful(clean(widgetText));
        if (text != null) return new ActionLabel(text);
        String name = useful(clean(widgetName));
        if (name != null) return new ActionLabel(name);
        // Some menu entries expose the exact action text directly, e.g. "Cast Ice Burst".
        // Do not inspect menuTarget: it names the affected actor or item.
        if (option.length() > 4 && option.regionMatches(true, 0, "Cast ", 0, 5)) {
            String direct = useful(clean(option.substring(5)));
            if (direct != null) return new ActionLabel(direct);
        }
        return null;
    }

    /** True when the widget id's interface group is the spellbook group. */
    static ActionLabel of(String text) {
        String normalized = useful(clean(text));
        return normalized == null ? null : new ActionLabel(normalized);
    }

    String value() {
        return value;
    }

    static String clean(String text) {
        if (text == null) return "";
        String withoutMarkup = text.replaceAll("<[^>]*>", " ").replaceAll("@[a-zA-Z0-9]{3,6}@", " ")
                        .replace("&nbsp;", " ").replace("&#160;", " ");
        return withoutMarkup.replaceAll("\\s+", " ").trim();
    }

    static String useful(String text) {
        if (text.isEmpty() || text.length() > MAX_LENGTH) return null;
        if ("cast".equalsIgnoreCase(text) || "autocast".equalsIgnoreCase(text)
                || "cancel".equalsIgnoreCase(text)) return null;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (!Character.isLetterOrDigit(c) && c != ' ' && c != '\'' && c != '-' && c != ',')
                return null;
        }
        return text;
    }

    public String toString() {
        return value;
    }
}

/**
 * Observed player action behind a settled inventory change. Presentation-only evidence: it names
 * what the player did (drank, ate, decanted, cast) so HUD/receipts/Live/Ledger can use honest
 * wording. It never changes {@link TransactionType}, valuation, counted state or session ownership.
 *
 * <p>Persisted on {@link Transaction} by wire name; absent on rows saved before B10 and on rows
 * whose evidence never supported a specific verb. Unsupported evidence must not acquire a more
 * confident verb — callers fall back to {@link #SUPPLIES} or a generic label rather than guessing.
 */
enum ActionKind {
    /** Drink intent plus a settled dose/vial decrease. */
    DRINK,
    /** Eat intent plus settled food loss (partial foods use the observed portion). */
    EAT,
    /** Herblore production: ingredients in, potion out. Not every paired transform. */
    MIX,
    /** Dose-conserving redistribution (3+1 → 4). Never implies doses were drunk. */
    DECANT, BURY, OFFER, SCATTER,
    /** Supported rune consumption. Spell name only when evidenced. Ledger detail only. */
    CAST,
    /** Supported ammunition consumption. Ledger detail only. */
    FIRE,
    /** Untradeable key audit rows are inspectable in Ledger only. */
    DEFERRED_CLAIM,
    /** Ambiguous charge-load settlements are explanatory Ledger notes only. */
    CHARGE_LOAD_AMBIGUOUS, COOK, BURN,
    /** Settled supply loss whose specific action is not evidenced. */
    SUPPLIES,
    /** A bank-paid fee row (the retired boat recovery): one action row named by its own note. */
    FEE;

    /** The constant's name, lowercased with hyphens: the wire name saved on every row. */
    String wireName = name().toLowerCase(Locale.ROOT).replace('_', '-');

    /** Stable persisted identifier. */
    String wireName() {
        return wireName;
    }

    static ActionKind fromWireName(String value) {
        return Phrases.blank(value) ? null : BY_WIRE.get(Phrases.lower(value));
    }

    /** Wire and constant names, lowercased, read on every getActionKind() (a hot path). */
    static final Map<String, ActionKind> BY_WIRE = new HashMap<>();

    static {
        for (ActionKind kind : values()) {
            BY_WIRE.put(kind.wireName, kind);
            BY_WIRE.put(kind.name().toLowerCase(Locale.ROOT), kind);
        }
    }
}

/**
 * Combat spells by exact rune cost (spells.tsv). Autocasting never clicks a spell, so a Cast with
 * no captured name reads as the one spell its runes pay for (owner 2026-09-28). A staff, tome or
 * combination rune may cover elementals; when two spells could fit, it stays a plain Cast.
 */
class Spells {
    /** Icons and recipes retain their original joined row shape for existing readers. */
    static final Map<String, String> ICONS = GameData.byName("spells");

    static final List<String[]> TABLE = GameData.cachedRows("spell_recipes").stream()
                    .map(a -> new String[] {a[0], ICONS.get(a[0]), a[1]}).collect(java.util.stream.Collectors.toList());
    static final Map<String, String> COMBINATIONS = new HashMap<>();
    static final String ELEMENTS = " air water earth fire ";

    static {
        for (String[] row : GameData.rows("combination_runes")) COMBINATIONS.put(row[0], row[1]);
    }

    /**
     * The spell these rune costs pay for (a whole number of casts), or null. When staff-covered
     * elementals let several fit, the one paid in full wins; if none or several are, it stays a
     * Cast.
     */

    /**
     * The spell's spellbook icon as a negated sprite id (the sidebar's sprite lookup reads it),
     * else -1.
     */
    static final Map<String, String> BY_LOWER = new HashMap<>();

    static {
        for (String name : ICONS.keySet()) BY_LOWER.put(name.toLowerCase(Locale.ROOT), name);
    }

    /** The item ids a spell makes (an alch's coins, Bones to Peaches' fruit); empty for others. */
    static Set<Integer> product(String name) {
        for (String[] row : GameData.cachedRows("spells")) {
            if (row[0].equals(name) && row.length > 2) {
                var ids = new HashSet<Integer>();
                for (String id : row[2].split(",")) ids.add(Integer.parseInt(id));
                return ids;
            }
        }
        return Collections.emptySet();
    }

    /** The spell a name spells out, ignoring case (a "Bones to peaches" tablet), else null. */
    static String named(String name) {
        return name == null ? null : BY_LOWER.get(name.toLowerCase(Locale.ROOT).trim());
    }

    static int icon(String name) {
        // d19 holds a spell's sprite, or minus an item id for a row named by its item (the barrel).
        String icon = ICONS.get(name);
        return icon == null ? -1 : -Integer.parseInt(icon);
    }

    /** 0 when these costs cannot be this spell, 1 when they fit it, 2 when they pay it in full. */

    /** Rune recipes are parsed once; fitting arithmetic and HashMap iteration stay unchanged. */
    static final Map<String, Map<String, Long>> RECIPES = new LinkedHashMap<>();

    static {
        for (String[] row : GameData.cachedRows("spell_recipes")) {
            var recipe = new HashMap<String, Long>();
            for (String part : row[1].split(" ")) {
                int colon = part.indexOf(':');
                recipe.put(part.substring(colon + 1), Long.parseLong(part.substring(0, colon)));
            }
            RECIPES.put(row[0], Collections.unmodifiableMap(recipe));
        }
    }

    static String spellFor(List<Flow> flows) {
        String fitting = null;
        String full = null;
        int fits = 0;
        int fulls = 0;
        for (String[] spell : TABLE) {
            int fit = fit(RECIPES.get(spell[0]), flows);
            if (fit > 0) {
                fits++;
                fitting = spell[0];
            }
            if (fit > 1) {
                fulls++;
                full = spell[0];
            }
        }
        return fits == 1 ? fitting : fulls == 1 ? full : null;
    }

    static int fit(Map<String, Long> recipe, List<Flow> flows) {
        var paid = new HashMap<String, Long>();
        for (Flow flow : flows) {
            String name = flow.itemName.toLowerCase(Locale.ROOT);
            if (!name.endsWith(" rune") || flow.quantityDelta >= 0L) return 0;
            String rune = name.substring(0, name.length() - 5);
            boolean used = false;
            for (String element : COMBINATIONS.getOrDefault(rune, rune).split(" ")) {
                // A combination rune pays only the elements this spell uses (steam is water for Ice
                // Barrage).
                if (recipe.containsKey(element) || !COMBINATIONS.containsKey(rune)) {
                    paid.merge(element, -flow.quantityDelta, Long::sum);
                    used = true;
                }
            }
            if (!used) return 0;
        }
        long casts = 0L;
        for (Map.Entry<String, Long> rune : recipe.entrySet()) {
            if (!ELEMENTS.contains(" " + rune.getKey() + " ")) {
                long got = paid.getOrDefault(rune.getKey(), 0L);
                if (got == 0L || got % rune.getValue() != 0L || casts != 0L && got / rune.getValue() != casts) return 0;
                casts = got / rune.getValue();
            }
        }
        boolean full = true;
        for (Map.Entry<String, Long> rune : recipe.entrySet()) {
            long got = paid.getOrDefault(rune.getKey(), 0L);
            // A rune the spell never uses, or more of an elemental than its casts need, is another
            // spell.
            if (got > casts * rune.getValue()) return 0;
            full &= got == casts * rune.getValue();
        }
        return paid.keySet().stream().allMatch(recipe::containsKey) ? full ? 2 : 1 : 0;
    }
}

/** Shared correction-aware projection for accounting read models and exports. */
class Accounting {
    static Amounts transaction(Transaction transaction) {
        if (transaction == null) return Amounts.unavailable();
        return transaction.memo(8, () -> amounts(transaction));
    }

    static Amounts amounts(Transaction transaction) {
        if (transaction.getType() == TransactionType.TRANSFER || transaction.getCorrection() == Correction.TRANSFER) {
            return Amounts.transfer();
        }
        if (!transaction.isCounted()) return Amounts.excluded();
        List<Flow> flows = transaction.getFlows();
        if (Phrases.empty(flows)) {
            return Amounts.included(transaction.getRevenue(), transaction.getCosts());
        }
        long gross = 0L;
        boolean included = false;
        for (Flow flow : flows) {
            if (flow == null) continue;
            included = true;
            gross = safeAdd(gross, abs(flow.valueDelta));
        }
        if (!included) return Amounts.excluded();
        switch (transaction.getCorrection()) {
            case REVENUE:
                return Amounts.included(gross, 0L);
            case COST:
                return Amounts.included(0L, gross);
            case IGNORE:
                return Amounts.excluded();
            case TRANSFER:
                return Amounts.transfer();
            case AUTO:
            default:
                long[] steps = cachedSteps(transaction);
                long step = 0L;
                for (int i = 0; i < flows.size(); i++) {
                    if (flows.get(i) != null && flows.get(i).valueDelta > 0L)
                        step = safeAdd(step, steps[i]);
                }
                step = Math.min(step, Math.min(transaction.getRevenue(), transaction.getCosts()));
                return Amounts.included(safeSubtract(transaction.getRevenue(), step),
                        safeSubtract(transaction.getCosts(), step));
        }
    }

    /**
     * Owner 2026-09-28: a sip or bite steps an item down ((4) to (3), pie to half pie). The part
     * left is no gain and the whole potion no cost; only the step is, as the Ledger pairs it. Per
     * flow, the value both legs of each such pair give up (0 elsewhere, and always 0 under a
     * correction).
     */
    static long[] cachedSteps(Transaction transaction) {
        return transaction.memo(6, () -> steps(transaction));
    }

    static long[] steps(Transaction transaction) {
        List<Flow> flows = transaction.getFlows();
        long[] steps = new long[flows.size()];
        for (PartialUse pair : consumePairs(transaction)) {
            long left = flows.get(pair.remainderIndex).valueDelta;
            if (left > 0L && safeAdd(flows.get(pair.lossIndex).valueDelta, left) <= 0L) {
                steps[pair.lossIndex] = left;
                steps[pair.remainderIndex] = left;
            }
        }
        return steps;
    }

    /** One consume gate for accounting and item presentation; transfers/decants keep raw quotes. */
    static List<PartialUse> consumePairs(Transaction transaction) {
        List<Flow> flows = transaction.getFlows();
        ActionKind action = transaction.getActionKind();
        // Cheapest facts first: this runs for every flow of every receipt on each refresh (release
        // pass).
        if (!transaction.isCounted() || transaction.getCorrection() != Correction.AUTO
                || transaction.getType() != TransactionType.CONSUMPTION
                        && transaction.getType() != TransactionType.PK_SUPPLY_COST || action != null
                        && action != ActionKind.DRINK && action != ActionKind.EAT && action != ActionKind.SUPPLIES
                || ActionReader.isDecant(flows)) return java.util.Collections.emptyList();
        var pairs = new java.util.ArrayList<PartialUse>();
        for (PartialUse pair : ActionReader.partialUses(flows)) {
            if (flows.get(pair.lossIndex).getPriceSource()
                    == flows.get(pair.remainderIndex).getPriceSource()) pairs.add(pair);
        }
        return pairs;
    }

    /** Returns the additive accounting contribution of a single item-flow row. */
    static Amounts flow(Transaction transaction, Flow flow) {
        if (transaction == null || flow == null) return Amounts.unavailable();
        if (transaction.getType() == TransactionType.TRANSFER || transaction.getCorrection() == Correction.TRANSFER) {
            return Amounts.transfer();
        }
        if (!transaction.isCounted() || transaction.getCorrection() == Correction.IGNORE) {
            return Amounts.excluded();
        }
        long value = flow.valueDelta;
        long autoRevenue = value > 0L ? value : 0L;
        long autoCosts = value < 0L ? abs(value) : 0L;
        switch (transaction.getCorrection()) {
            case REVENUE:
                return Amounts.included(abs(value), 0L);
            case COST:
                return Amounts.included(0L, abs(value));
            case IGNORE:
                return Amounts.excluded();
            case TRANSFER:
                return Amounts.transfer();
            case AUTO:
            default:
                List<Flow> flows = transaction.getFlows();
                long step = 0L;
                for (int i = 0; i < flows.size(); i++) {
                    if (flows.get(i) == flow) step = cachedSteps(transaction)[i];
                }
                return Amounts.included(safeSubtract(autoRevenue, value > 0L ? step : 0L),
                        safeSubtract(autoCosts, value < 0L ? step : 0L));
        }
    }

    /** Correction-aware supplies/other split shared by every retained money fold. */
    static CostSplit costSplit(Transaction transaction) {
        return transaction.memo(9, () -> split(transaction));
    }

    static CostSplit split(Transaction transaction) {
        Amounts total = transaction(transaction);
        if (!total.available) return new CostSplit(0L, 0L, false);
        if (!total.included || total.costs <= 0L) return new CostSplit(0L, 0L, true);
        if (transaction.getFlows().isEmpty()) return new CostSplit(0L, 0L, false);
        long supplies = 0L;
        long other = 0L;
        for (Flow flow : transaction.getFlows()) {
            if (flow == null) continue;
            Amounts amounts = flow(transaction, flow);
            if (!amounts.available) return new CostSplit(0L, 0L, false);
            if (!amounts.included || amounts.costs <= 0L) continue;
            switch (CostKind.of(transaction, flow)) {
                case SUPPLIES:
                    supplies = safeAdd(supplies, amounts.costs);
                    break;
                case LOSS:
                case MARKET:
                    other = safeAdd(other, amounts.costs);
                    break;
                default:
                    return new CostSplit(0L, 0L, false);
            }
        }
        return new CostSplit(supplies, other, safeAdd(supplies, other) == total.costs);
    }

    /**
     * The correction-aware fold of the counted Market-context population. Market membership is the
     * authoritative typed predicate {@code automaticType == TRADE}; corrections change effective
     * amounts but never membership. Whole transactions are folded here so callers can remove their
     * gross legs from ordinary categories without re-deriving economics.
     */
    static MarketFold marketFold(List<Transaction> transactions) {
        long revenue = 0L;
        long costs = 0L;
        long supplies = 0L;
        long other = 0L;
        boolean splitAvailable = true;
        int counted = 0;
        if (transactions == null) return new MarketFold(0L, 0L, 0L, 0L, true, 0);
        for (Transaction transaction : transactions) {
            if (transaction == null || transaction.autoType() != TransactionType.TRADE) continue;
            Amounts amounts = transaction(transaction);
            if (!amounts.included) continue;
            counted++;
            revenue = safeAdd(revenue, amounts.revenue);
            costs = safeAdd(costs, amounts.costs);
            CostSplit split = costSplit(transaction);
            if (!split.available) {
                splitAvailable = false;
                continue;
            }
            supplies = safeAdd(supplies, split.supplies);
            other = safeAdd(other, split.other);
        }
        return new MarketFold(revenue, costs, splitAvailable ? supplies : 0L, splitAvailable ? other : 0L,
                splitAvailable, counted);
    }

    @AllArgsConstructor
    static class MarketFold {
        long revenue;
        long costs;
        long supplies;
        long other;
        boolean splitAvailable;

        /** Counted Market-context transactions behind this fold. */
        int transactions;

        long getNet() {
            return safeSubtract(revenue, costs);
        }
    }

    @AllArgsConstructor
    static class Amounts {
        boolean available;
        boolean included;
        boolean transfer;
        long revenue;
        long costs;

        static Amounts included(long revenue, long costs) {
            return new Amounts(true, true, false, revenue, costs);
        }

        static Amounts excluded() {
            return new Amounts(true, false, false, 0L, 0L);
        }

        static Amounts transfer() {
            return new Amounts(true, false, true, 0L, 0L);
        }

        static Amounts unavailable() {
            return new Amounts(false, false, false, 0L, 0L);
        }

        long getNet() {
            return safeSubtract(revenue, costs);
        }
    }

    @AllArgsConstructor
    static class CostSplit {
        long supplies;
        long other;
        boolean available;
    }
}

/**
 * Model-layer classification for one effective counted item cost.
 *
 * <p>The inputs intentionally match the Ledger's item contribution boundary: a transaction plus one
 * flow. This keeps classification independent of Swing and allows every read model to apply the
 * same rule after compaction.
 *
 * <p>The category is selected by typed canonical data only: the synthetic tax flow id, the
 * transaction type and the observed action kind. Item names, activity labels, notes, explanations
 * and owner correction reasons are presentation; renaming any of them can never change the booked
 * category.
 */
enum CostKind {
    NONE, SUPPLIES, LOSS,
    /** Trade costs are market movement and remain inside the non-supplies total. */
    MARKET;

    /**
     * Historical synthetic GE sell-tax flow id. New booking stopped in Band 3 C2; the constant
     * stays so saved history keeps its typed loss category and the Ledger tax filter still reads.
     */
    static final int GE_TAX_ITEM_ID = -99502;

    /**
     * Classifies only an effective cost after counted/correction semantics. Non-cost, ignored,
     * transfer, uncounted and deferred claim flows return {@link #NONE}.
     */
    static CostKind of(Transaction transaction, Flow flow) {
        if (transaction == null || flow == null || transaction.getActionKind() == ActionKind.DEFERRED_CLAIM) {
            return NONE;
        }
        Accounting.Amounts effective = Accounting.flow(transaction, flow);
        if (!effective.available || !effective.included || effective.costs <= 0L) return NONE;
        if (flow.itemId == GE_TAX_ITEM_ID || transaction.autoType() == PK_DEATH_LOSS) {
            return LOSS;
        }
        if (transaction.autoType() == TRADE) return MARKET;
        TransactionType type = transaction.autoType();
        // Supplies are consumables the player used (eat / drink / cast / fire / charges /
        // processing
        // inputs), which the engine evidences with an action kind or a supply-shaped type. A plain
        // "value decreased" consumption with no evidence is an item gone, i.e. a loss.
        // A production run's input is a supply even when that action made nothing (a failed smelt).
        if (type == PK_SUPPLY_COST || type == PROCESSING || transaction.getActionKind() != null
                || transaction.getContext() == Context.PRODUCTION) {
            return SUPPLIES;
        }
        return LOSS;
    }
}

package com.gpmanager;

import static com.gpmanager.GameData.msg;
import static java.lang.Math.*;

import com.google.gson.Gson;
import com.gpmanager.SessionRepository.ReplaceOutcome;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.time.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Filepath;
import org.slf4j.*;
import static com.gpmanager.Phrases.*;
import static com.gpmanager.SafeMath.nonNeg;
import static java.util.Collections.*;
import java.util.*;
import com.google.gson.*;
import com.gpmanager.SaveStatus.State;
