package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Generic fallbacks are not activities: they never become the session's activity label. */
public class ActivityDetectorTest
{
    @Test
    public void npcLootFallbackNeverBecomesTheActivity()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        };
        Engine engine = new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        ActivityDetector detector = new ActivityDetector(config, engine);

        detector.observe("Woodcutting", true);
        assertEquals("Woodcutting", engine.getMetrics(1_100L).activityHint);

        detector.observe("NPC loot", true);
        assertEquals("a fallback is not an activity", "Woodcutting", engine.getMetrics(1_200L).activityHint);
    }

    @Test
    public void aGatherClickNamesNothingUntilItsSkillsFirstXp()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        };
        Engine engine = new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        ActivityDetector detector = new ActivityDetector(config, engine);

        // Clicking a tree with no axe, or before reaching it.
        detector.gatherSkill = ActionSignals.gatherActivity("chop down");
        assertEquals("General", engine.getMetrics(1_100L).activityHint);
        // Other XP still needs its second drop.
        detector.observeXp("Mining", null, false, 1_200L);
        assertEquals("General", engine.getMetrics(1_300L).activityHint);
        // The first log's XP names the run at once.
        detector.observeXp("Woodcutting", null, false, 1_400L);
        assertEquals("Woodcutting", engine.getMetrics(1_500L).activityHint);
    }

    /**
     * Owner report 2026-09-28: iron smelting fails about half the time with no XP, so the six-tick
     * window lapsed between successes and the next ore-to-bar change became a Review row. A
     * production skill's XP keeps the run in PRODUCTION for 30 s after the last one.
     */
    @Test
    public void aSmeltingRunSurvivesFailedSmeltsWithoutXp()
    {
        GpManagerConfig config = new GpManagerConfig() {};
        Engine engine = new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        ActivityDetector detector = new ActivityDetector(config, engine);
        long now = 1_000_000L;

        detector.armProduction("Smelting", now);
        engine.inbox.drop(Inbox.CLOCK); // two failed smelts: the six-tick window has lapsed
        detector.observeXp("Smithing", null, false, now + 12_000L);
        assertEquals(Context.PRODUCTION, engine.liveClue().context);
        assertTrue("Smithing XP re-arms the run", engine.clockLeft() > 0);

        engine.inbox.drop(Inbox.CLOCK);
        detector.observeXp("Attack", null, false, now + 17_000L);
        assertEquals("combat XP never opens production", 0, engine.clockLeft());

        detector.observeXp("Smithing", null, false, now + 12_000L + 31_000L);
        assertEquals("past the run window XP no longer re-arms", 0, engine.clockLeft());
    }
}

package com.gpmanager;

import org.junit.Test;

import static com.gpmanager.ReviewFixesTest.T0;
import static com.gpmanager.ReviewFixesTest.engine;
import static com.gpmanager.ReviewFixesTest.plugin;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** AFK pause (owner 1.5.0): off by default, pauses from the moment it fires, any play lifts it. */
public class AfkPauseTest
{
    @Test
    public void afkPausePausesFromNowAndPlayLiftsIt()
    {
        Engine engine = engine();
        engine.pauseIdle(T0 + 120_000L);
        Session session = engine.getActiveSession();
        assertTrue(session.paused);
        assertEquals(PauseReason.IDLE, session.getPauseReason());
        assertEquals("the timeout window still counts as active", T0 + 120_000L, session.pausedAtEpochMillis);
        assertTrue(engine.isIdlePaused());
        assertTrue("movement or play resumes it", engine.resume(T0 + 180_000L, PauseReason.IDLE));
        assertFalse(session.paused);
    }

    @Test
    public void afkPauseNeverReplacesAnotherPause()
    {
        for (PauseReason held : new PauseReason[] {PauseReason.MANUAL, PauseReason.WORLD, PauseReason.LIFECYCLE})
        {
            Engine engine = engine();
            engine.getActiveSession().pause(T0 + 1_000L, held);
            engine.pauseIdle(T0 + 2_000L);
            assertEquals(held, engine.getActiveSession().getPauseReason());
            assertEquals(T0 + 1_000L, engine.getActiveSession().pausedAtEpochMillis);
        }
    }

    @Test
    public void anyActivityRestartsTheIdleCount()
    {
        ReviewFixesTest.Plugin p = plugin(engine(), new int[] {11});
        p.idleTicks = 150;
        p.markActivity();
        assertEquals(0, p.idleTicks);
        p.idleTicks = 150;
        p.markGameplayActivity();
        assertEquals(0, p.idleTicks);
    }

    /** Owner 1.5.0: clicking the status dot lifts AWAY for good, not until the next tick. */
    @Test
    public void theStatusDotResumeRestartsTheAfkClock()
    {
        Engine engine = engine();
        ReviewFixesTest.Plugin p = plugin(engine, new int[] {11});
        p.idleTicks = 99;
        p.idleTick(100);
        assertTrue(engine.isIdlePaused());
        p.idleTick(100);
        assertTrue("still away while nothing happens", engine.isIdlePaused());
        engine.togglePause(T0 + 300_000L);
        assertFalse(engine.getActiveSession().paused);
        p.idleTick(100);
        assertFalse("the next still tick does not pause again", engine.getActiveSession().paused);
        assertEquals(0, p.idleTicks);
        for (int i = 0; i < 100; i++) p.idleTick(100);
        assertTrue("a full AFK window later it pauses again", engine.isIdlePaused());
    }

    @Test
    public void afkPauseIsThreeMinutesByDefault()
    {
        assertEquals(3, new GpManagerConfig() {}.afkPauseMinutes());
    }
}

