    private static void set(Object target, String name, Object value) throws Exception
    {
        Field field = GpManagerPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static final class Harness
    {
        final Engine engine;
        final ChargeIntake intake;

        Harness(ItemContainer worn, ItemContainer inventory)
        {
            Valuation valuation = ModelProbe.valuation(CONFIG, AtesTeleportInterfaceTest::compositionOf,
                id -> id == TEAR ? 1_000 : 0);
            engine = new Engine(valuation, new TransactionClassifier(), CONFIG);
            engine.startCustom("Ates", T0);
            engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
            intake = new ChargeIntake(client(worn, inventory), lookup(), CONFIG, engine, valuation);
        }
    }

    private static ItemLookup lookup()
    {
        return new ItemLookup(null)
        {
            @Override
            ItemComposition composition(int id)
            {
                return compositionOf(id);
            }
        };
    }

    private static ItemComposition compositionOf(int id)
    {
        String name = id == TEAR ? "Frozen tear" : "Item " + id;
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) ->
            {
                if ("getName".equals(method.getName())) return name;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }

    private static Client client(ItemContainer worn, ItemContainer inventory)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) ->
            {
                if ("getItemContainer".equals(method.getName()))
                {
                    int containerId = (int) args[0];
                    if (containerId == InventoryID.WORN) return worn;
                    if (containerId == InventoryID.INV) return inventory;
                    return null;
                }
                if ("getTickCount".equals(method.getName())) return 10;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }

    private static ItemContainer container(int slot, int itemId)
    {
        return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[] {ItemContainer.class}, (proxy, method, args) ->
            {
                if ("getItem".equals(method.getName()))
                    return (int) args[0] == slot ? new Item(itemId, 1) : null;
                if ("size".equals(method.getName())) return 28;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }

    private static ItemContainer emptyContainer()
    {
        return container(-1, 0);
    }

    private static MenuOptionClicked clickWithParam1(int component)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                if ("getOption".equals(method.getName())) return "kastori";
                if ("getTarget".equals(method.getName())) return "";
                if ("getType".equals(method.getName())) return MenuAction.CC_OP;
                if ("getParam1".equals(method.getName())) return component;
                if ("getWidget".equals(method.getName())) return null;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
        return new MenuOptionClicked(entry);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;

/** Retained bank contents are not proof that the bank interface is still open. */
public class BankVisibilityRegressionTest
{
    @Test public void cachedBankAfterCloseDoesNotSuppressHarvestOrSupplies() throws Exception
    {
        for (int itemId : new int[] {1942, 1947, 1511, 1519, 385})
        {
            boolean consuming = itemId == 385;
            GpManagerConfig config = new GpManagerConfig() {
                public int stabilizationTicks() { return 0; }
            };
            Engine engine = new Engine(deltas -> {
                java.util.List<Flow> flows = new java.util.ArrayList<>();
                deltas.forEach((id, qty) -> flows.add(new Flow(id, "Item " + id, qty, 50, qty * 50)));
                return flows;
            }, new TransactionClassifier(), config);
            engine.ensureSession(1000);
            ContainerSnapshot held = new ContainerSnapshot(Collections.singletonMap(itemId, 1L));
            engine.setBaseline(consuming ? held : ContainerSnapshot.empty());
            // The same bank visibility decision used by the production tick adapter.
            if (bankOpen(false)) engine.bankOpened(6);
            else engine.bankClosed();
            engine.markDirty();
            ContainerSnapshot next = consuming ? ContainerSnapshot.empty() : held;
            engine.processIfDirty(next, 1600, null);
            assertEquals(consuming ? TransactionType.CONSUMPTION : TransactionType.GAIN,
                engine.processIfDirty(next, 2200, null).getType());
            assertEquals(consuming ? -50 : 50, engine.getMetrics(2200).net);
        }
    }

    @Test public void visibleBankStillSuppressesTransfers() throws Exception
    {
        assertTrue(bankOpen(true));
    }

    @Test public void toolLeprechaunStoreIsStorageOnlyWhileItsWindowShows()
    {
        Widget shown = proxy(Widget.class, name -> "isHidden".equals(name) ? false : null);
        Client open = proxy(Client.class, name -> "getWidget".equals(name) ? shown : null);
        Client closed = proxy(Client.class, name -> null);
        assertTrue(Widgets.isToolStoreOpen(open));
        assertFalse(Widgets.isToolStoreOpen(closed));
    }

    /**
     * Owner 2026-10-08: storing in or taking from a store with its own window (Elnock, the seed
     * vault, a cargo hold, Death's coffer, item sets...) is no loot. Every d29 row names a real
     * RuneLite component, and only that store's window gives its note.
     */
    @Test public void storeWindowsAreStorageWhileEitherPanelShows() throws Exception
    {
        Widget shown = proxy(Widget.class, name -> "isHidden".equals(name) ? false : null);
        assertTrue(Widgets.STORES.size() >= 16);
        for (String[] row : Widgets.STORES)
        {
            String[] name = row[1].split("\\.");
            int component = Class.forName("net.runelite.api.gameval.InterfaceID$" + name[0])
                .getField(name[1]).getInt(null);
            assertEquals(row[1], component, Integer.parseInt(row[0]));
            Client open = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
                (obj, method, args) -> "getWidget".equals(method.getName()) && args.length == 1
                    && Integer.valueOf(component).equals(args[0]) ? shown : null);
            assertEquals(row[1], row[2], Widgets.store(open));
            assertFalse("not the tool store", Widgets.isToolStoreOpen(open));
            assertFalse("not the Grand Exchange", Widgets.isGeOpen(open));
        }
        assertNull(Widgets.store(proxy(Client.class, name -> null)));
    }

    /** A banker's collection box collects Grand Exchange offers: a Collect there is GE evidence. */
    @Test public void collectionBoxCountsAsTheGrandExchange()
    {
        Widget shown = proxy(Widget.class, name -> "isHidden".equals(name) ? false : null);
        int box = net.runelite.api.gameval.InterfaceID.GeCollect.UNIVERSE;
        Client open = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (obj, method, args) -> "getWidget".equals(method.getName()) && args.length == 1
                && Integer.valueOf(box).equals(args[0]) ? shown : null);
        assertTrue(Widgets.isGeOpen(open));
        assertFalse(Widgets.isGeOpen(proxy(Client.class, name -> null)));
    }

    private boolean bankOpen(boolean visible) throws Exception
    {
        ItemContainer cachedBank = proxy(ItemContainer.class, (name) -> null);
        Widget widget = proxy(Widget.class, name -> "isHidden".equals(name) ? !visible : null);
        Client client = proxy(Client.class, name -> {
            if ("getItemContainer".equals(name)) return cachedBank;
            if ("getWidget".equals(name)) return widget;
            return null;
        });
        return Widgets.isBankOpen(client);
    }

    private static <T> T proxy(Class<T> type, java.util.function.Function<String, Object> values)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, (obj, method, args) -> {
            Object value = values.apply(method.getName());
            if (value != null || !method.getReturnType().isPrimitive()) return value;
            if (method.getReturnType() == boolean.class) return false;
            if (method.getReturnType() == long.class) return 0L;
            return 0;
        }));
    }
}

package com.gpmanager;

import java.io.InputStream;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Properties;
import javax.annotation.Nullable;

/**
 * Immutable build-time identity for development builds (dev launcher and panel preview only; the
 * plugin itself has no build-identity code). Build metadata only: never financial,
 * never owner-scoped and never persisted. The Gradle build writes the bundled resource; runtime
 * reads ordinary immutable data (no process execution, no networking, no reflection).
 *
 * <p>Missing or corrupt metadata degrades to a bare {@code DEV BUILD} marker instead of failing
 * plugin startup.</p>
 */
public final class BuildInfo
{
    /** Build-generated resource, written by Gradle into the plugin resources. */
    static final String RESOURCE = "/gp-manager-build.properties";

    private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm'Z'")
        .withZone(ZoneOffset.UTC);
    private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss 'UTC'")
        .withZone(ZoneOffset.UTC);
    private static final int MAX_FIELD = 48;

    private final String version;
    private final String developmentVersion;
    private final String schemaVersion;
    private final String builtAtUtc;
    private final String revision;
    private final String runeliteDependency;
    private final boolean development;

    private BuildInfo(String version, String developmentVersion, String schemaVersion,
        String builtAtUtc, String revision, String runeliteDependency, boolean development)
    {
        this.version = safe(version);
        this.developmentVersion = safe(developmentVersion);
        this.schemaVersion = safe(schemaVersion);
        this.builtAtUtc = safe(builtAtUtc);
        this.revision = safe(revision);
        this.runeliteDependency = safe(runeliteDependency);
        this.development = development;
    }

    /** Reads the bundled build metadata; any failure yields the harmless fallback. */
    public static BuildInfo load()
    {
        return load(BuildInfo.class.getResourceAsStream(RESOURCE));
    }

    /** Explicit-stream load for tests and previews; the stream is closed here. */
    public static BuildInfo load(@Nullable InputStream stream)
    {
        if (stream == null)
        {
            return fallback();
        }
        Properties properties = new Properties();
        try (InputStream in = stream)
        {
            properties.load(in);
        }
        catch (Exception ex)
        {
            return fallback();
        }
        String version = properties.getProperty("version");
        String developmentVersion = properties.getProperty("developmentVersion");
        if (safe(version).isEmpty() && safe(developmentVersion).isEmpty())
        {
            return fallback();
        }
        return new BuildInfo(
            version,
            developmentVersion,
            properties.getProperty("schema"),
            properties.getProperty("builtAt"),
            properties.getProperty("revision"),
            properties.getProperty("runeliteDependency"),
            "true".equalsIgnoreCase(safe(properties.getProperty("development"))));
    }

    /** Injection seam for previews/tests: an explicit, fixed identity. */
    public static BuildInfo of(@Nullable String version, @Nullable String developmentVersion,
        @Nullable String schemaVersion, @Nullable String builtAtUtc, @Nullable String revision,
        @Nullable String runeliteDependency, boolean development)
    {
        return new BuildInfo(version, developmentVersion, schemaVersion, builtAtUtc, revision,
            runeliteDependency, development);
    }

    /** Safe fallback when optional metadata is missing or unreadable. */
    public static BuildInfo fallback()
    {
        return new BuildInfo("", "", "", "", "", "", true);
    }

    public boolean development()
    {
        return development;
    }

    public String version()
    {
        return version;
    }

    public String developmentVersion()
    {
        return developmentVersion;
    }

    public String schemaVersion()
    {
        return schemaVersion;
    }

    public String revision()
    {
        return revision;
    }

    /**
     * The tiny footer marker: {@code DEV · 1.2.0 · 01:24Z}. Release builds return an empty
     * string, so the footer collapses instead of showing a stale development marker.
     */
    public String badgeText()
    {
        if (!development)
        {
            return "";
        }
        if (version.isEmpty())
        {
            return "DEV BUILD";
        }
        String clock = clockUtc();
        return clock.isEmpty() ? "DEV \u00b7 " + version : "DEV \u00b7 " + version + " \u00b7 " + clock;
    }

    /** Full identity for the footer tooltip and accessibility description. */
    public String tooltipText()
    {
        StringBuilder text = new StringBuilder(development
            ? "GP Manager Development Build" : "GP Manager Release Build");
        String shownVersion = developmentVersion.isEmpty() ? version : developmentVersion;
        if (!shownVersion.isEmpty())
        {
            text.append("\nVersion: ").append(shownVersion);
        }
        if (!schemaVersion.isEmpty())
        {
            text.append("\nSchema: ").append(schemaVersion);
        }
        String stamp = stampUtc();
        if (!stamp.isEmpty())
        {
            text.append("\nBuilt: ").append(stamp);
        }
        if (!runeliteDependency.isEmpty())
        {
            text.append("\nRuneLite: ").append(runeliteDependency);
        }
        if (!revision.isEmpty())
        {
            text.append("\nRevision: ").append(revision);
        }
        return text.toString();
    }

    /** Compact UTC clock of the build, or empty when no usable timestamp is bundled. */
    public String clockUtc()
    {
        Instant instant = parsedBuiltAt();
        return instant == null ? "" : CLOCK.format(instant);
    }

    /** Full UTC timestamp of the build, or the raw bundled text when unparseable. */
    public String stampUtc()
    {
        Instant instant = parsedBuiltAt();
        return instant == null ? builtAtUtc : STAMP.format(instant);
    }

    @Nullable
    private Instant parsedBuiltAt()
    {
        if (builtAtUtc.isEmpty())
        {
            return null;
        }
        try
        {
            return Instant.parse(builtAtUtc);
        }
        catch (RuntimeException ex)
        {
            return null;
        }
    }

    private static String safe(@Nullable String value)
    {
        if (value == null)
        {
            return "";
        }
        StringBuilder clean = new StringBuilder(Math.min(value.length(), MAX_FIELD));
        for (int i = 0; i < value.length() && clean.length() < MAX_FIELD; i++)
        {
            char c = value.charAt(i);
            if (!Character.isISOControl(c))
            {
                clean.append(c);
            }
        }
        return clean.toString().trim();
    }
}

package com.gpmanager;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Build identity is ordinary immutable metadata: parsed, displayed and fail-safe. */
public class BuildInfoTest
{
    @Test
    public void developmentMetadataParsesIntoTheTinyFooterMarker()
    {
        BuildInfo info = BuildInfo.load(stream("version=1.2.0\n"
            + "developmentVersion=1.2.0-dev\n"
            + "development=true\n"
            + "schema=105\n"
            + "builtAt=2026-09-23T01:24:37Z\n"
            + "revision=2929696\n"
            + "runeliteDependency=1.12.39\n"));

        assertTrue(info.development());
        assertEquals("1.2.0", info.version());
        assertEquals("1.2.0-dev", info.developmentVersion());
        assertEquals("105", info.schemaVersion());
        assertEquals("2929696", info.revision());
        assertEquals("DEV \u00b7 1.2.0 \u00b7 01:24Z", info.badgeText());
        assertTrue(info.tooltipText().contains("GP Manager Development Build"));
        assertTrue(info.tooltipText().contains("Version: 1.2.0-dev"));
        assertTrue(info.tooltipText().contains("Schema: 105"));
        assertTrue(info.tooltipText().contains("Built: 2026-09-23 01:24:37 UTC"));
        assertTrue(info.tooltipText().contains("RuneLite: 1.12.39"));
        assertTrue(info.tooltipText().contains("Revision: 2929696"));
    }

    @Test
    public void releaseMetadataOmitsTheDevelopmentMarker()
    {
        BuildInfo info = BuildInfo.load(stream("version=1.0.0\n"
            + "developmentVersion=1.0.0\n"
            + "development=false\n"
            + "schema=105\n"
            + "builtAt=2026-09-23T01:24:37Z\n"));

        assertFalse(info.development());
        assertEquals("", info.badgeText());
    }

    @Test
    public void missingMetadataFallsBackWithoutFailing()
    {
        BuildInfo info = BuildInfo.load((java.io.InputStream) null);

        assertTrue("a missing resource still identifies the running build", info.development());
        assertEquals("DEV BUILD", info.badgeText());
        assertTrue(info.tooltipText().contains("GP Manager Development Build"));
    }

    @Test
    public void corruptMetadataFailsSafelyAndNeverLeaksControlCharacters()
    {
        BuildInfo info = BuildInfo.load(stream("not=properties\n\u0000\u0001version=\u0007garbage\u0000\n"));

        // No usable version survives, so the marker degrades to the bare development form.
        assertEquals("DEV BUILD", info.badgeText());
        for (int i = 0; i < info.badgeText().length(); i++)
        {
            assertFalse(Character.isISOControl(info.badgeText().charAt(i)));
        }
    }

    @Test
    public void unparseableTimestampKeepsTheVersionAndDropsOnlyTheClock()
    {
        BuildInfo info = BuildInfo.load(stream("version=1.2.0\n"
            + "developmentVersion=1.2.0-dev\n"
            + "development=true\n"
            + "builtAt=not-a-timestamp\n"));

        assertEquals("DEV \u00b7 1.2.0", info.badgeText());
        assertTrue(info.tooltipText().contains("Built: not-a-timestamp"));
    }

    @Test
    public void injectedFixedIdentityDoesNotDependOnTheWallClock()
    {
        BuildInfo info = BuildInfo.of("1.2.0", "1.2.0-dev", "105",
            "2026-09-23T11:42:05Z", "abcdef1", "1.12.39", true);

        assertEquals("DEV \u00b7 1.2.0 \u00b7 11:42Z", info.badgeText());
    }

    private static ByteArrayInputStream stream(String text)
    {
        return new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));
    }
}

