package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Owner 1.2: charging any charged item moves its components into charges; it never books a loss. */
public class ChargeLoadAnyItemTest
{
    private static final long T0 = 1_000_000L;

    @Test
    public void everyItemsOwnChargeMaterialIsALoad()
    {
        assertTrue(ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.CRYSTAL_BOW, ItemID.PRIF_CRYSTAL_SHARD, "Crystal shard"));
        assertTrue(ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.SANGUINESTI, ItemID.BLOODRUNE, "Blood rune"));
        assertTrue(ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.SHADOW, ItemID.SOULRUNE, "Soul rune"));
        assertTrue(ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.ATES, ItemID.FROZEN_TEAR, "Frozen tear"));
        assertTrue(ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.VENATOR, ItemID.ANCIENT_ESSENCE, "Ancient essence"));
        assertTrue(ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.CRAW, ItemID.WILD_CAVE_SHARD, "Revenant ether"));
        assertTrue("the scythe's vials too", ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.SCYTHE, ItemID.VIAL_BLOOD, "Vial of blood"));
        assertFalse("another item is not its charge", ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.SANGUINESTI, ItemID.FIRERUNE, "Fire rune"));
    }

    @Test
    public void chargingACrystalBowBooksNothing()
    {
        Engine engine = settle(true);
        assertEquals(0L, engine.getMetrics(T0 + 10_000L).net);
        assertTrue(engine.getActiveSession().getTransactions().stream().noneMatch(Transaction::isCounted));
    }

    @Test
    public void chargingBryophytasStaffBooksNothing()
    {
        // Owner 2026-10-09 (recorded): 1,000 nature runes into the staff turned the uncharged staff into the
        // charged one and went to Review; the runes are now its charges.
        assertTrue(ChargeCheck.isLoadComponent(ChargeCheck.ChargedItem.BRYOPHYTA, ItemID.NATURERUNE, "Nature rune"));
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.NATURERUNE, 6_766L, ItemID.NATURE_STAFF_UNCHARGED, 1L))));
        engine.markChargeLoad(ChargeCheck.ChargedItem.BRYOPHYTA, ItemID.NATURERUNE, "Nature rune", "149:1:22368:BRYOPHYTA", ChargeIntake.LOAD_TICKS);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.NATURERUNE, 5_766L, ItemID.NATURE_STAFF_CHARGED, 1L))), T0 + tick * 600L, null);
        }
        assertEquals("charging the staff is not a cost", 0L, engine.getMetrics(T0 + 10_000L).net);
        assertTrue("nor Review", engine.getActiveSession().getTransactions().stream().noneMatch(ReviewRules::needsOwnerDecision));
    }

    @Test
    public void withoutTheLoadTheSameShardsWouldBeALoss()
    {
        assertTrue(settle(false).getMetrics(T0 + 10_000L).net < 0L);
    }

    @Test
    public void theScytheOnTheVyreWellLoadsItsRunesAndVialsThroughThePrompt()
    {
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.BLOODRUNE, 1_000L, ItemID.VIAL_BLOOD, 5L))));
        Widget scythe = widget(ItemID.SCYTHE_OF_VITUR, 149 << 16, 3);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, args) -> "getSelectedWidget".equals(method.getName()) ? scythe
                : "getTickCount".equals(method.getName()) ? 10 : null);
        ChargeIntake intake = new ChargeIntake(client, null, HudBuilderTest.config(true, 4), engine, null);
        intake.armLoad(click(MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, "Use", null), "use");
        intake.armLoad(click(MenuAction.WIDGET_CONTINUE, "Continue", null), "continue");
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.BLOODRUNE, 800L, ItemID.VIAL_BLOOD, 4L))), T0 + tick * 600L, null);
        }
        assertEquals("charging the scythe is not a cost", 0L, engine.getMetrics(T0 + 10_000L).net);
    }

    private static Engine settle(boolean loaded)
    {
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.PRIF_CRYSTAL_SHARD, 500L))));
        if (loaded)
        {
            engine.markChargeLoad(ChargeCheck.ChargedItem.CRYSTAL_BOW, ItemID.PRIF_CRYSTAL_SHARD, "Crystal shard", "149:0:23983:CRYSTAL_BOW",
                ChargeIntake.LOAD_TICKS);
        }
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.PRIF_CRYSTAL_SHARD, 400L))), T0 + tick * 600L, null);
        }
        return engine;
    }

    static Widget widget(int itemId, int id, int index)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[]{Widget.class},
            (proxy, method, args) -> "getItemId".equals(method.getName()) ? itemId
                : "getId".equals(method.getName()) ? id : "getIndex".equals(method.getName()) ? index
                : method.getReturnType() == int.class ? 0 : method.getReturnType() == boolean.class ? false : null);
    }

    static MenuOptionClicked click(MenuAction type, String option, Widget widget)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[]{MenuEntry.class}, (proxy, method, args) ->
            {
                if ("getOption".equals(method.getName())) return option;
                if ("getTarget".equals(method.getName())) return "";
                if ("getType".equals(method.getName())) return type;
                if ("getWidget".equals(method.getName())) return widget;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
        return new MenuOptionClicked(entry);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.*;

/** Typed outcomes retain exact component quantities and physical-target isolation. */
public class ChargeOutcomeTest
{
    /** A Check that books nothing; SAME and SPEND never pass. */
    static void none(ChargeDelta delta)
    {
        none("no booking", delta);
    }

    static void none(String message, ChargeDelta delta)
    {
        assertNotNull(message, delta);
        assertTrue(message, delta.result == ChargeDelta.CheckResult.SEED
            || delta.result == ChargeDelta.CheckResult.LOAD
            || delta.result == ChargeDelta.CheckResult.MISMATCH);
        assertTrue(message, delta.componentDeltas.isEmpty());
    }

    static ChargeDelta outcome(ChargeDelta.CheckResult expected, ChargeDelta delta)
    {
        assertNotNull(delta);
        assertEquals(expected, delta.result);
        return delta;
    }

    static ChargeCheck seasCheck(long charges)
    {
        return ChargeCheck.parse("Your Trident of the seas has " + charges + " charges.");
    }

    @Test
    public void firstAndUnchangedReadsNameDifferentOutcomes()
    {
        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        outcome(ChargeDelta.CheckResult.SEED, tracker.observe(seasCheck(10), "a", 1));
        ChargeDelta same = outcome(ChargeDelta.CheckResult.SAME, tracker.observe(seasCheck(10), "a", 2));
        assertTrue(same.componentDeltas.isEmpty());
        assertEquals(2L, tracker.baselines.get("a").atEpochMillis);
    }

    @Test
    public void loadSeedsTheNextExactSpendWithoutAComponentLoss()
    {
        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        outcome(ChargeDelta.CheckResult.SEED, tracker.observe(seasCheck(10), "a", 1));
        ChargeDelta load = outcome(ChargeDelta.CheckResult.LOAD, tracker.observe(seasCheck(20), "a", 2));
        assertTrue(load.componentDeltas.isEmpty());
        ChargeDelta spend = outcome(ChargeDelta.CheckResult.SPEND, tracker.observe(seasCheck(19), "a", 3));
        assertEquals(4, spend.componentDeltas.size());
        assertEquals(-1L, spend.componentDeltas.stream()
            .filter(component -> component.itemId == ItemID.DEATHRUNE).findFirst().get().quantityDelta);
    }

    @Test
    public void aMixedBlowpipeLoadKeepsIndependentMeasuredScaleSpend()
    {
        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        tracker.observe(ChargeCheck.parse("Darts: Adamant dart x 10. Scales: 100 (1.0%)."), "a", 1);
        ChargeDelta spend = outcome(ChargeDelta.CheckResult.SPEND,
            tracker.observe(ChargeCheck.parse("Darts: Adamant dart x 12. Scales: 98 (1.0%)."), "a", 2));
        assertEquals(1, spend.componentDeltas.size());
        assertEquals(ItemID.SNAKEBOSS_SCALE, spend.componentDeltas.get(0).itemId);
        assertEquals(-2L, spend.componentDeltas.get(0).quantityDelta);
    }

    @Test
    public void anUnsupportedReadMismatchesAndClearsThePriorBaseline()
    {
        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        tracker.observe(seasCheck(10), "a", 1);
        outcome(ChargeDelta.CheckResult.MISMATCH,
            tracker.observe(ChargeCheck.parse("Darts: Exotic dart x 100. Scales: 90 (1.0%)."), "a", 2));
        assertNull(tracker.baselines.get("a"));
        outcome(ChargeDelta.CheckResult.SEED, tracker.observe(seasCheck(9), "a", 3));
    }

    @Test
    public void aMissingReadKeepsTheLastExactBaselineAsBefore()
    {
        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        tracker.observe(seasCheck(10), "a", 1);
        outcome(ChargeDelta.CheckResult.MISMATCH, tracker.observe(null, "a", 2));
        assertNotNull(tracker.baselines.get("a"));
        outcome(ChargeDelta.CheckResult.SPEND, tracker.observe(seasCheck(9), "a", 3));
    }

    @Test
    public void aVariantMismatchAndTwoPhysicalTargetsRemainIsolated()
    {
        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        outcome(ChargeDelta.CheckResult.SEED, tracker.observe(seasCheck(10), "a", 1));
        outcome(ChargeDelta.CheckResult.SEED, tracker.observe(seasCheck(2), "b", 2));
        outcome(ChargeDelta.CheckResult.SPEND, tracker.observe(seasCheck(9), "a", 3));
        outcome(ChargeDelta.CheckResult.SAME, tracker.observe(seasCheck(2), "b", 4));
        outcome(ChargeDelta.CheckResult.MISMATCH,
            tracker.observe(ChargeCheck.parse("Your Trident of the swamp has 8 charges."), "a", 5));
        outcome(ChargeDelta.CheckResult.SPEND,
            tracker.observe(ChargeCheck.parse("Your Trident of the swamp has 7 charges."), "a", 6));
    }

    @Test
    public void aMeasuredLoadArmsTransferWithoutRequiringChargeWordingOrPrices()
    {
        GpManagerConfig config = new GpManagerConfig() {};
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[]{Client.class}, (proxy, method, args) ->
            {
                if (method.getName().equals("getTickCount")) return 10;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
        ChargeIntake intake = new ChargeIntake(client, null, config, engine, null);
        assertTrue(intake.startCheck(ChargeCheck.ChargedItem.TRIDENT_SEAS, "a", 10, 2));
        assertTrue(intake.observeCheck("Your Trident of the seas has 10 charges.", 1_001L));
        assertNull(engine.inbox.peek(Inbox.SOFT_TRANSFER));
        assertTrue(intake.startCheck(ChargeCheck.ChargedItem.TRIDENT_SEAS, "a", 10, 2));
        assertTrue(intake.observeCheck("Your Trident of the seas has 20 charges.", 1_002L));
        assertNotNull(engine.inbox.peek(Inbox.SOFT_TRANSFER));
        assertTrue(engine.getActiveSession().getTransactions().isEmpty());
    }

    @Test
    public void aFreshStartLeavesEarlierEstimatesBookedButOutOfTheNextCheck()
    {
        GpManagerConfig config = new GpManagerConfig() {};
        Engine engine = new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[]{Client.class}, (proxy, method, args) ->
            {
                if (method.getName().equals("getTickCount")) return 10;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
        ChargeIntake intake = new ChargeIntake(client, null, config, engine, null);
        assertTrue(intake.startCheck(ChargeCheck.ChargedItem.TRIDENT_SEAS, "a", 10, 2));
        assertTrue(intake.observeCheck("Your Trident of the seas has 100 charges.", 1_001L));
        Transaction cast = engine.bookEstimatedCharge("a", "Trident of the seas", ActionKind.CAST,
            Collections.singletonList(new Flow(ItemID.DEATHRUNE, "Death rune", -1, 100, -100,
                PriceSource.GRAND_EXCHANGE)), 1_002L);
        String session = engine.getActiveSession().getId();
        assertEquals(1L, ChargeProbes.adp(engine.chargeEstimateJournal, session, "a", "seas", ItemID.DEATHRUNE));

        // A recharge read ("charged with") arrives before its load books: a fresh start.
        assertTrue(intake.startCheck(ChargeCheck.ChargedItem.TRIDENT_SEAS, "a", 10, 2));
        assertTrue(intake.observeCheck("Your Trident of the seas has 150 charges.", 1_003L));
        assertEquals("the next Check never reconciles it", 0L,
            ChargeProbes.adp(engine.chargeEstimateJournal, session, "a", "seas", ItemID.DEATHRUNE));
        assertTrue("the cast stays booked", cast.isCounted());
        assertEquals(100L, engine.getMetrics(2_000L).costs);
    }

    @Test
    public void nonSpendOutcomesCannotAuthorizeValuedLosses()
    {
        ChargeDelta load = new ChargeDelta(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Collections.singletonList(new ChargeDelta.ComponentDelta(ItemID.DEATHRUNE, -1)),
            ChargeDelta.CheckResult.LOAD);
        assertEquals(0L, load.exactCost(Collections.singletonList(
            new Flow(ItemID.DEATHRUNE, "Death rune", -1, 100, -100, PriceSource.GRAND_EXCHANGE))));
    }
}

package com.gpmanager;

import java.util.List;

/** Read-only charge lookups the tests assert on; the plugin itself never needs them. */
final class ChargeProbes
{
    private ChargeProbes()
    {
    }

    /** The family's first pinned local cast graphic (d20); 0 means no automatic estimate. */
    static int nx(ChargeCheck.ChargedItem variant)
    {
        return variant.graphics.length == 0 ? 0 : variant.graphics[0];
    }

    /** The journal's still-open estimated quantity of one component for one weapon. */
    static long adp(ChargeEstimateJournal journal, String sessionId, String targetIdentity, String family, int itemId)
    {
        long total = 0L;
        for (ChargeEstimateJournal.Receipt receipt : journal.receipts(sessionId, targetIdentity, itemId))
        {
            total = SafeMath.safeAdd(total, Math.max(0L, receipt.remainingQuantity));
        }
        return total;
    }
}

package com.gpmanager;

import java.util.Collections;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.*;

/** Window closure, leftover removal, and the bounded journal's overlap memory. */
public class ChargeReconciliationWindowTest
{
    private static final long T0 = 10_000L;

    @Test
    public void clearingATargetKeepsTheReceiptBoundHonest()
    {
        ChargeEstimateJournal journal = new ChargeEstimateJournal();
        for (int i = 0; i < ChargeEstimateJournal.MAX_RECEIPTS; i++)
        {
            journal.record("s1", "slot", "tx" + i, 1, 1L);
        }
        journal.clearTarget("s1", "slot");
        for (int i = 0; i < ChargeEstimateJournal.MAX_RECEIPTS; i++)
        {
            journal.record("s1", "slot", "ty" + i, 1, 1L);
        }
        assertEquals("a cleared target must not evict its replacements early",
            ChargeEstimateJournal.MAX_RECEIPTS, journal.receipts("s1", "slot", 1).size());
    }

    @Test
    public void evictedReceiptsKeepTheirWindowOverlapUntilCleared()
    {
        ChargeEstimateJournal journal = new ChargeEstimateJournal();
        for (int i = 0; i < ChargeEstimateJournal.MAX_RECEIPTS + 3; i++)
        {
            journal.record("s1", "slot", "tx" + i, 1, 2L);
        }
        assertEquals("evicted quantities stay visible to reconciliation", 6L,
            journal.evictedOverlap("s1", "slot", 1));
        journal.clearTarget("s1", "slot");
        assertEquals(0L, journal.evictedOverlap("s1", "slot", 1));
    }

    @Test
    public void leftoverEstimatesAreRemovedWhenACheckClosesTheWindow()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Transaction first = estimate(engine, T0 + 1L);
        Transaction second = estimate(engine, T0 + 2L);
        Transaction third = estimate(engine, T0 + 3L);

        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Collections.singletonList(new ChargeDelta.ComponentDelta(ItemID.DEATHRUNE, -1L)), ChargeDelta.CheckResult.SPEND);
        Transaction measured = engine.bookChargeSpend(delta, "Trident of the seas",
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -1L, 100)), T0 + 4L, "slot-a");

        assertNull("the surviving estimate already booked the measured unit", measured);
        assertEquals(1L, first.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, second.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, third.quantity(ItemID.DEATHRUNE, false));
        assertEquals(Correction.IGNORE, second.getCorrection());
        assertEquals(Correction.IGNORE, third.getCorrection());
        assertEquals(0L, ChargeProbes.adp(engine.chargeEstimateJournal, 
            engine.getActiveSession().getId(), "slot-a", "seas", ItemID.DEATHRUNE));
    }

    @Test
    public void aCompatibleCheckThatMovedNothingClosesTheWindow()
    {
        Engine engine = engine();
        engine.ensureSession(T0);
        Transaction first = estimate(engine, T0 + 1L);
        Transaction second = estimate(engine, T0 + 2L);

        engine.closeChargeWindow("slot-a");

        assertEquals(0L, first.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, second.quantity(ItemID.DEATHRUNE, false));
        assertEquals(Correction.IGNORE, first.getCorrection());
        assertEquals(Correction.IGNORE, second.getCorrection());
        assertEquals(0L, ChargeProbes.adp(engine.chargeEstimateJournal, 
            engine.getActiveSession().getId(), "slot-a", "seas", ItemID.DEATHRUNE));
    }

    private static Transaction estimate(Engine engine, long at)
    {
        return engine.bookEstimatedCharge("slot-a", "seas", ActionKind.CAST,
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -1L, 100)), at);
    }

    private static Flow flow(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), new GpManagerConfig() {});
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.http.api.item.ItemPrice;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-09 (1.3.0, tested in game): a chug from the chugging barrel drinks one dose of every
 * potion in it without touching the inventory. The game names each one ("You have 3 doses of
 * Saradomin brew(1) left in your barrel."), so the doses book as one Drank row titled by the barrel,
 * at each one-dose potion's price, and filling it through its window is a move.
 */
public class ChugBarrelTest
{
    private static final int BREW = 6691;
    private static final int RESTORE = 3030;
    private static final Map<Integer, String> NAMES = Map.of(BREW, "Saradomin brew(1)", RESTORE, "Super restore(1)");
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    };

    @Test
    public void aChugIsOneDrankRowOfOneDoseOfEachPotion()
    {
        Valuation valuation = ModelProbe.valuation(CONFIG, ChugBarrelTest::composition, id -> id == BREW ? 2_400 : id == RESTORE ? 3_600 : 0);
        Engine engine = new Engine(valuation, new TransactionClassifier(), CONFIG);
        engine.startCustom("Chug", 1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        ChargeIntake intake = new ChargeIntake(null, new ItemLookup(null)
        {
            @Override
            List<ItemPrice> find(String name)
            {
                List<ItemPrice> found = new ArrayList<>();
                NAMES.forEach((id, item) ->
                {
                    if (item.toLowerCase().contains(name.toLowerCase()))
                    {
                        ItemPrice price = new ItemPrice();
                        price.setId(id);
                        price.setName(item);
                        found.add(price);
                    }
                });
                return found;
            }
        }, CONFIG, engine, valuation);

        java.util.regex.Pattern chug = GameData.pattern("chug");
        for (String line : new String[] {"You have 3 doses of Saradomin brew(1) left in your barrel.",
            "You have finished all doses of Super restore(1) in your barrel."})
        {
            java.util.regex.Matcher match = chug.matcher(line);
            assertTrue(line, match.matches());
            intake.chug(match.group(1), 1_001_000L);
        }
        intake.drank(1_001_600L);
        intake.drank(1_002_200L);

        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals("one row per chug", 1, rows.size());
        Transaction row = rows.get(0);
        assertEquals("Chugging barrel", row.spellName());
        assertEquals(ActionKind.DRINK, row.getActionKind());
        assertEquals("one dose of each", -2_400L - 3_600L, engine.getMetrics(1_100_000L).net);
        assertEquals("one Recent row", 1, LiveProbe.recent(rows, LiveContext.NONE).size());
        assertEquals("the row shows the barrel itself", 30000, LiveProbe.recent(rows, LiveContext.NONE).get(0).itemId);
        assertEquals("a spell keeps its sprite", -15, Spells.icon("Wind Strike"));
        assertEquals("no label, no icon", -1, Spells.icon("Drank"));
        assertTrue("filling it through its window is a move",
            GameData.cachedRows("store_windows").stream().anyMatch(store -> "PrepotDevice.FRAME".equals(store[1])));
    }

    @Test
    public void uncharingBryophytasStaffSpendsTheRunesItDestroys()
    {
        // Owner recording 2026-10-09: the runes used to charge the staff are not returned.
        Valuation valuation = ModelProbe.valuation(CONFIG, ChugBarrelTest::composition, id -> id == 561 ? 138 : 0);
        Engine engine = new Engine(valuation, new TransactionClassifier(), CONFIG);
        engine.startCustom("Alching", 1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        java.util.regex.Matcher line = GameData.pattern("bru").matcher("You remove 1000 charges from your staff, leaving it empty.");
        assertTrue(line.matches());
        new ChargeIntake(null, null, CONFIG, engine, valuation).emptied(ChargeCheck.parseCount(line.group(1)), 1_001_000L);
        assertEquals(-138_000L, engine.getMetrics(1_100_000L).net);
        Transaction row = engine.getActiveSession().getTransactions().get(0);
        assertEquals("an exact count, not an estimate", "Measured charge spend · Bryophyta's staff", row.getNote());
        assertEquals(Confidence.CONFIRMED, row.getConfidence());
    }

    private static ItemComposition composition(int id)
    {
        String name = NAMES.getOrDefault(id, "Item " + id);
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) -> {
                if ("getName".equals(method.getName())) return name;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return false;
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }
}

package com.gpmanager;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static com.gpmanager.ReviewFixesTest.BONES;
import static com.gpmanager.ReviewFixesTest.T0;
import static com.gpmanager.ReviewFixesTest.engine;
import static com.gpmanager.ReviewFixesTest.plugin;
import static com.gpmanager.ReviewFixesTest.proxy;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The Codex research findings on 1.2 (2026-10-06), kept as regression tests without reflection. */
public class CodexResearchFixesTest
{
    /** Finding 1: another player's or a public pile vanishing is never our bag pickup. */
    @Test
    public void onlyOurOwnPileCanHaveGoneIntoOurBag()
    {
        assertEquals("a public pile", 0L, despawn(TileItem.OWNERSHIP_NONE));
        assertEquals("another player's pile", 0L, despawn(TileItem.OWNERSHIP_OTHER));
        assertEquals("our own pile is bounded by the two proven bones", 2L, despawn(TileItem.OWNERSHIP_SELF));
    }

    static long despawn(int ownership)
    {
        Engine engine = engine();
        engine.markLoot(Map.of(BONES, 2L), 50, "Loot from Guard", "Guard");
        ReviewFixesTest.Plugin p = plugin(engine, new int[]{11});
        ReviewFixesTest.take(p).item = BONES;
        ReviewFixesTest.take(p).at = 10;
        ReviewFixesTest.take(p).x = 10;
        ReviewFixesTest.take(p).y = 10;
        Map<String, Object> tileValues = new HashMap<>();
        tileValues.put("getSceneLocation", new Point(10, 10));
        tileValues.put("getWorldLocation", new WorldPoint(100, 100, 0));
        Map<String, Object> itemValues = new HashMap<>();
        itemValues.put("getId", BONES);
        itemValues.put("getQuantity", 3);
        itemValues.put("getOwnership", ownership);
        p.onItemDespawned(new ItemDespawned(proxy(Tile.class, tileValues), proxy(TileItem.class, itemValues)));
        return ReviewFixesTest.qty(p, Inbox.BAG_GAIN);
    }

    /** Finding 4: a reclaim fee still waiting its two ticks never reaches the next account. */
    @Test
    public void aWaitingBankFeeIsDroppedAtTheAccountFence()
    {
        ReviewFixesTest.Plugin p = plugin(engine(), new int[]{11});
        p.engine.inbox.put(Inbox.FEE, -1, 5_964L, 10, null);
        p.ready = false;
        p.onGameTick(new GameTick());
        assertEquals(0L, ReviewFixesTest.qty(p, Inbox.FEE));
    }

    /** Finding 5: a Check that reads the same as the last one is a compatible "nothing used". */
    @Test
    public void anUnchangedCheckRemovesTheOverestimate()
    {
        Engine e = engine();
        String target = "same-staff";
        e.observeCheck(ChargeCheck.parse("Your Trident of the seas has 100 charges."), target, T0);
        e.bookEstimatedCharge(target, ChargeCheck.ChargedItem.TRIDENT_SEAS.getDisplayName(), ActionKind.CAST,
            List.of(new Flow(ItemID.DEATHRUNE, "Death rune", -1, 100, -100, PriceSource.GRAND_EXCHANGE)), T0 + 1_000L);
        assertTrue(e.getMetrics(T0 + 1_500L).costs > 0L);
        ReviewFixesTest.Plugin p = plugin(e, new int[]{100});
        p.charges.startCheck(ChargeCheck.ChargedItem.TRIDENT_SEAS, target, 100, 2);
        assertTrue(p.charges.observeCheck("Your Trident of the seas has 100 charges.", T0 + 2_000L));
        assertEquals("the matching Check proves no charge was used", 0L, e.getMetrics(T0 + 5_000L).costs);
    }

    /** Finding 6: checking one staff keeps another same-kind staff's estimate credit. */
    @Test
    public void checkingOneStaffKeepsTheOtherStaffsEstimates()
    {
        Engine e = engine();
        String family = ChargeCheck.ChargedItem.TRIDENT_SEAS.getDisplayName();
        List<Flow> use = List.of(new Flow(ItemID.DEATHRUNE, "Death rune", -1, 100, -100, PriceSource.GRAND_EXCHANGE));
        e.bookEstimatedCharge("staff-a", family, ActionKind.CAST, use, T0 + 1_000L);
        e.bookEstimatedCharge("staff-b", family, ActionKind.CAST, use, T0 + 1_001L);
        e.clearPendingEstimates("staff-a", java.util.Collections.emptySet());
        String session = e.getActiveSession().getId();
        assertTrue(e.chargeEstimateJournal.receiptsFor(session, "staff-a").isEmpty());
        assertFalse("staff B keeps its own credit", e.chargeEstimateJournal.receiptsFor(session, "staff-b").isEmpty());
    }

    /** Conditional trace: a split catch books only the fish missing from the inventory. */
    @Test
    public void aSplitCatchBooksOnlyWhatIsMissingFromTheInventory()
    {
        Engine e = engine();
        ReviewFixesTest.Plugin p = plugin(e, new int[]{11});
        p.snapshotFactory = new ContainerSnapshotFactory(p.client, null)
        {
            @Override
            ContainerSnapshot capture(boolean equipment, boolean pouch)
            {
                return new ContainerSnapshot(Map.of(335, 1L));
            }
        };
        ReviewFixesTest.take(p).item = 335;
        ReviewFixesTest.take(p).held = 0;
        ReviewFixesTest.bag(p).at = 10;
        ReviewFixesTest.bag(p).qty = 2;
        p.bagSettle();
        assertEquals("one in the pack, one in the barrel", -1L, e.baseline.quantityOf(335));
    }
}

