/** An internal injected tracker must still publish client evidence through its callback. */
public class InjectedInteractionTrackerTest
{
    @Test
    public void guiceBuildsAndReusesTheTrackerThatPublishesCombatTargets()
    {
        GpManagerConfig config = new GpManagerConfig() {};
        Engine engine = new Engine(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        engine.ensureSession(1L);
        Player local = proxy(Player.class, method -> null);
        Client client = proxy(Client.class, method -> "getLocalPlayer".equals(method) ? local : null);
        NPC target = proxy(NPC.class, method -> "getName".equals(method) ? "Goblin"
            : "getCombatLevel".equals(method) ? 2 : null);
        Injector injector = Guice.createInjector(new AbstractModule()
        {
            @Override
            protected void configure()
            {
                bind(Client.class).toInstance(client);
                bind(Engine.class).toProvider(() -> engine);
                bind(GpManagerConfig.class).toInstance(config);
            }
        });
        InteractionContextTracker tracker = injector.getInstance(InteractionContextTracker.class);
        assertSame(tracker, injector.getInstance(InteractionContextTracker.class));
        String[] published = {""};
        tracker.bindPresentation(() -> true, (name, combat) -> published[0] = name);
        tracker.onInteractingChanged(new InteractingChanged(local, target));
        assertEquals("Goblin", published[0]);
        assertTrue(tracker.hasPvmContext());
    }

    private static <T> T proxy(Class<T> type, Function<String, Object> values)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type},
            (object, method, args) ->
            {
                Object value = values.apply(method.getName());
                if (value != null || !method.getReturnType().isPrimitive()) return value;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == long.class) return 0L;
                return 0;
            }));
    }
}

package com.gpmanager;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * A private boss instance is paid coffer first, then the bank for the rest, in the same tick
 * (Death Cost Tracker's in-game capture). Every instance line arrives as SPAM: both parts
 * count, and a lone SPAM bank line with an empty coffer books the bank-paid fee. A GAMEMESSAGE
 * bank line is reclaim evidence and never an instance fee here.
 */
public class InstanceFeeTest
{
    private final GpManagerConfig config = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    };

    private int tick = 100;

    @Test
    public void theBankShareOfAnInstanceFeeCountsWithTheCofferShare() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your coffer: 15,325 Coins."));
        plugin.onChatMessage(spam("Payment has been taken from your bank: 9,675 x Coins"));
        assertEquals(25_000L, engine.getMetrics(2_000L).costs);
        assertEquals(2, engine.getActiveSession().getTransactions().size());
    }

    @Test
    public void aLaterBankPaymentIsNotAnInstanceFee() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your coffer: 15,325 Coins."));
        tick++;
        plugin.onChatMessage(spam("Payment has been taken from your bank: 9,675 x Coins"));
        assertEquals(15_325L, engine.getMetrics(2_000L).costs);
    }

    @Test
    public void aCofferOnlyInstanceFeeBooksTheCapturedLiveLine() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your coffer: 12,500 Coins."));
        assertEquals(12_500L, engine.getMetrics(2_000L).costs);
        assertEquals(1, engine.getActiveSession().getTransactions().size());
    }

    @Test
    public void aSpamBankLineWithNoCofferBooksTheBankPaidFee() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(spam("Payment has been taken from your bank: 12,500 Coins."));
        assertEquals(12_500L, engine.getMetrics(2_000L).costs);
        assertEquals(1, engine.getActiveSession().getTransactions().size());
        assertEquals("Instance fee (bank)",
            engine.getActiveSession().getTransactions().get(0).getNote());
    }

    @Test
    public void aGameMessageBankLineIsNotAnInstanceFee() throws Exception
    {
        Engine engine = engine();
        GpManagerPlugin plugin = plugin(engine);
        plugin.onChatMessage(gameMessage("Payment has been taken from your bank: 12,500 Coins."));
        assertEquals(0L, engine.getMetrics(2_000L).costs);
        assertEquals(0, engine.getActiveSession().getTransactions().size());
    }

    private Engine engine()
    {
        Engine engine = new Engine(deltas -> {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, qty) -> flows.add(new Flow(id, "Item " + id, qty, 1, qty)));
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        engine.setBaseline(ContainerSnapshot.empty());
        return engine;
    }

    private GpManagerPlugin plugin(Engine engine) throws Exception
    {
        GpManagerPlugin plugin = new GpManagerPluginProbe();
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[] {Client.class},
            (proxy, method, args) -> "getTickCount".equals(method.getName()) ? tick : null);
        set(plugin, "config", config);
        set(plugin, "engine", engine);
        set(plugin, "client", client);
        set(plugin, "charges", new ChargeIntake(null, null, config, engine, null));
        return plugin;
    }

    private static ChatMessage spam(String text)
    {
        ChatMessage message = new ChatMessage();
        message.setType(ChatMessageType.SPAM);
        message.setMessage(text);
        return message;
    }

    private static ChatMessage gameMessage(String text)
    {
        ChatMessage message = new ChatMessage();
        message.setType(ChatMessageType.GAMEMESSAGE);
        message.setMessage(text);
        return message;
    }

    private static void set(Object target, String name, Object value) throws Exception
    {
        Field field = GpManagerPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/** The interaction tracker titles NPCs only: scenery and opponent names never publish. */
public class InteractionContextTrackerTest
{
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void sceneryClicksNeverTitle()
    {
        Harness harness = new Harness();
        harness.clickObject("Bank", 100);
        assertEquals("a bank booth is not an activity", "", harness.last());
        harness.clickObject("Chop down", 200);
        assertEquals("a tree is not an activity either", "", harness.last());
    }

    @Test
    public void npcTargetsTitleButPlayerNamesDoNot()
    {
        Harness harness = new Harness();
        harness.interact(harness.npc("Goblin", 2));
        assertEquals("Goblin", harness.last());
        harness.interact(harness.player("Rival"));
        assertEquals("opponent names never display", "", harness.last());
    }

    @Test
    public void aCombatTargetSurvivesSceneryClicks()
    {
        Harness harness = new Harness();
        harness.interact(harness.npc("Vorkath", 732));
        harness.clickObject("Open", 300);
        assertEquals("Vorkath", harness.last());
    }

    private static final class Harness
    {
        private final Engine engine;
        private final Client client;
        private final Player local;
        private final InteractionContextTracker tracker;
        private String published = "";

        Harness()
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public int stabilizationTicks()
                {
                    return 0;
                }
            };
            engine = new Engine(deltas ->
            {
                List<Flow> flows = new ArrayList<>();
                deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Item " + id, quantity, 50, quantity * 50)));
                return flows;
            }, new TransactionClassifier(), config);
            engine.ensureSession(T0);
            local = player("Local");
            client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
                (proxy, method, args) ->
                {
                    switch (method.getName())
                    {
                        case "getLocalPlayer": return local;
                        case "getObjectDefinition": return object(args == null || args.length == 0 ? "" : "Scenery");
                        default:
                            if (method.getReturnType() == boolean.class) return false;
                            if (method.getReturnType() == int.class) return 0;
                            if (method.getReturnType() == long.class) return 0L;
                            return null;
                    }
                });
            tracker = new InteractionContextTracker(client, engine, config);
            tracker.bindPresentation(() -> true, (name, combat) -> published = name == null ? "" : name);
        }

        String last()
        {
            return published;
        }

        void interact(Actor target)
        {
            tracker.onInteractingChanged(new InteractingChanged(local, target));
        }

        void clickObject(String option, int id)
        {
            tracker.onMenuOptionClicked(new MenuOptionClicked(menu(option, id, MenuAction.GAME_OBJECT_FIRST_OPTION)));
        }

        Player player(String name)
        {
            return (Player) Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[] {Player.class},
                (proxy, method, args) ->
                {
                    if ("getName".equals(method.getName())) return name;
                    if ("isDead".equals(method.getName())) return false;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }

        NPC npc(String name, int combatLevel)
        {
            return (NPC) Proxy.newProxyInstance(NPC.class.getClassLoader(), new Class<?>[] {NPC.class},
                (proxy, method, args) ->
                {
                    if ("getName".equals(method.getName())) return name;
                    if ("getCombatLevel".equals(method.getName())) return combatLevel;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }

        private static ObjectComposition object(String name)
        {
            return (ObjectComposition) Proxy.newProxyInstance(ObjectComposition.class.getClassLoader(),
                new Class<?>[] {ObjectComposition.class}, (proxy, method, args) ->
                {
                    if ("getName".equals(method.getName())) return name;
                    if ("getImpostorIds".equals(method.getName())) return null;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }

        private static MenuEntry menu(String option, int id, MenuAction action)
        {
            return (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
                new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
                {
                    if ("getOption".equals(method.getName())) return option;
                    if ("getId".equals(method.getName())) return id;
                    if ("getType".equals(method.getName())) return action;
                    if ("getIdentifier".equals(method.getName())) return id;
                    if ("getItemOp".equals(method.getName())) return 0;
                    if ("isItemOp".equals(method.getName())) return false;
                    if ("getWidget".equals(method.getName())) return null;
                    if (method.getReturnType() == boolean.class) return false;
                    if (method.getReturnType() == int.class) return 0;
                    if (method.getReturnType() == long.class) return 0L;
                    return null;
                });
        }
    }
}

package com.gpmanager;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Menu/chat vocabulary that becomes an accounting intent; anything else stays ambiguous. */
public class InventoryConsumptionOptionTest
{
    @Test
    public void recognisesSupportedInventoryConsumeOptions()
    {
        for (String option : new String[] {"bury", "scatter", "eat", "drink", "empty", "break", "cast", "release", "eat 1", "drink 1", "light", "offer", "tend-to"})
        {
            assertTrue(option, ActionSignals.isSpend(option));
        }
        assertFalse(ActionSignals.isSpend("cook"));
        assertTrue(ActionSignals.isSpendName("light"));
        assertFalse(ActionSignals.isSpendName("cook"));
    }

    @Test
    public void ignoresDropUseAndBankishOptions()
    {
        for (String option : new String[] {"drop", "use", "wear", "wield", "deposit", ""})
        {
            assertFalse(option, ActionSignals.isSpend(option));
        }
        assertFalse(ActionSignals.isSpend(null));
    }

    @Test
    public void transformOptionsArmProductionBySkill()
    {
        assertEquals("Cooking", ActionSignals.transformSkill("cook"));
        assertEquals("Smelting", ActionSignals.transformSkill("smelt"));
        assertEquals("Herblore", ActionSignals.transformSkill("clean"));
        assertEquals("Fletching", ActionSignals.transformSkill("fletch"));
        assertEquals("", ActionSignals.transformSkill("eat"));
        assertTrue(ActionSignals.lightsFire("use", "Tinderbox -> Willow logs"));
        assertFalse(ActionSignals.lightsFire("use", "Willow logs"));
        assertTrue(ActionSignals.offersBones("use", "Dragon bones -> Altar"));
        assertTrue(ActionSignals.isOffering("cast", "Sinister Offering"));
    }

    @Test
    public void recognisesHarvestGatherOptionsForActivityHints()
    {
        assertTrue(ActionSignals.namesActivityOnly("pick"));
        assertTrue(ActionSignals.namesActivityOnly("harvest"));
        assertTrue(ActionSignals.namesActivityOnly("chop down"));
        assertTrue(ActionSignals.namesActivityOnly("mine"));
        assertFalse(ActionSignals.namesActivityOnly("rake"));
        assertEquals("Farming", ActionSignals.gatherActivity("pick"));
        assertEquals("Woodcutting", ActionSignals.gatherActivity("chop"));
        assertEquals("Mining", ActionSignals.gatherActivity("mine"));
        assertEquals("Fishing", ActionSignals.gatherActivity("fish"));
        assertEquals("General", ActionSignals.gatherActivity("open"));
    }

    @Test
    public void recognisesLiveConsumptionChatMessages()
    {
        assertTrue(ActionSignals.isChatSpend("you drink some of your prayer potion."));
        assertTrue(ActionSignals.isChatSpend("you dig a hole and bury the bones."));
        assertTrue(ActionSignals.isChatSpend("you eat the lobster."));
        assertTrue(ActionSignals.isChatSpend("you scatter the ashes."));
        assertTrue(ActionSignals.isChatSpend("the gods are very pleased with your offering."));
        assertFalse("bone-save keeps the bone: never a spend", ActionSignals.isChatSpend("the dark lord spares your sacrifice but still rewards you."));
        assertTrue(ActionSignals.isSpared("The Dark Lord spares your sacrifice."));
        assertFalse(ActionSignals.isChatSpend("you pick a potato."));
        assertFalse(ActionSignals.isChatSpend(""));
        assertFalse(ActionSignals.isChatSpend(null));
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
