import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Owner 1.2: the costs of Kharedst's memoirs (runes per teleport) and the blood essence. */
public class MemoirsAndEssenceTest
{
    private static final long T0 = 1_000_000L;
    private static final Map<Integer, Long> RUNES = Map.of(ItemID.LAWRUNE, 100L, ItemID.BODYRUNE, 100L,
        ItemID.MINDRUNE, 100L, ItemID.SOULRUNE, 100L);

    @Test
    public void theMemoirsCheckReadsItsRunes()
    {
        ChargeCheck read = ChargeCheck.parse("On the inside of the cover a message is displayed in dark ink. It reads: 87 memories remain.");
        assertEquals(ChargeCheck.ChargedItem.MEMOIRS, read.variant);
        assertEquals(Long.valueOf(87L), read.componentCounts.get(ItemID.SOULRUNE));
        assertEquals(Long.valueOf(87L), read.componentCounts.get(ItemID.LAWRUNE));
        assertEquals(ChargeCheck.ChargedItem.MEMOIRS, ChargeCheck.supportedForName("Book of the dead"));
    }

    @Test
    public void theBooksTeleportsAreLocations()
    {
        assertTrue(ChargeIntake.isAtesLocation("the fisher's flute"));
        assertTrue(ChargeIntake.isAtesLocation("lunch by the lancalliums"));
        assertTrue(ChargeIntake.isAtesLocation("a dark disposition"));
    }

    @Test
    public void chargingAtTheOldMemorialBooksNothing()
    {
        assertEquals(0L, memorial(true).getMetrics(T0 + 10_000L).net);
        assertTrue("without the memorial click the runes would be a loss", memorial(false).getMetrics(T0 + 10_000L).net < 0L);
    }

    @Test
    public void activatingABloodEssenceIsUsedNotReview()
    {
        assertTrue(ActionSignals.isSpend("activate"));
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.BLOOD_ESSENCE_INACTIVE, 2L))));
        engine.noteConsume(ItemID.BLOOD_ESSENCE_INACTIVE, 6, false);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(ItemID.BLOOD_ESSENCE_INACTIVE, 1L, ItemID.BLOOD_ESSENCE_ACTIVE, 1L))),
                T0 + tick * 600L, null);
        }
        assertTrue(engine.getActiveSession().getTransactions().toString(),
            engine.getActiveSession().getTransactions().stream().allMatch(row -> row.autoType() == TransactionType.CONSUMPTION));
        assertEquals(1, engine.getActiveSession().getTransactions().size());
    }

    private static Engine memorial(boolean inspected)
    {
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(RUNES)));
        if (inspected)
        {
            Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
                (proxy, method, args) -> "getTickCount".equals(method.getName()) ? 10 : null);
            ChargeIntake intake = new ChargeIntake(client, null, HudBuilderTest.config(true, 4), engine, null);
            intake.onMenuOptionClicked(ChargeLoadAnyItemTest.click(MenuAction.GAME_OBJECT_FIRST_OPTION, "Inspect", null),
                "inspect", "old memorial");
        }
        engine.markDirty();
        var after = new HashMap<Integer, Long>();
        RUNES.forEach((id, quantity) -> after.put(id, quantity - 20L));
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), T0 + tick * 600L, null);
        }
        return engine;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * A pending loot key's chest is valued exactly from its observed contents only (owner 2026-10-14):
 * the game's own display rounds to the nearest million, while the Ledger and the Live tooltip show
 * the exact manifest sum; a part without a quote shows nothing.
 */
public class PendingKeyValueTest
{
    private static final long T0 = 1_000_000L;
    private static final int KEY = ItemID.WILDY_LOOT_KEY0;
    private static final int KEY1 = ItemID.WILDY_LOOT_KEY1;
    private static final int FANG = 26219;
    private static final int RING = 6737;
    private static final long FANG_PRICE = 400_000L;
    private static final long RING_PRICE = 15_000L;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }

        @Override
        public boolean keepTransferAuditRows()
        {
            return true;
        }
    };

    @Test
    public void theObservedChestPricesExactly()
    {
        Engine engine = engine();
        engine.setChestVisible(true);
        engine.observeKeyContainer(KEY, mapOf(FANG, 1L, RING, 1L));
        assertEquals(
                "the exact manifest sum, never rounded to a million",
                FANG_PRICE + RING_PRICE,
                engine.pendingKeyValue(KEY, T0));
    }

    @Test
    public void anUnseenChestShowsNothing()
    {
        Engine engine = engine();
        assertEquals(0L, engine.pendingKeyValue(KEY, T0));
        engine.setChestVisible(true);
        assertEquals(0L, engine.pendingKeyValue(KEY, T0));
    }

    @Test
    public void aClosedOrEmptiedChestShowsNothing()
    {
        Engine engine = engine();
        engine.setChestVisible(true);
        engine.observeKeyContainer(KEY, mapOf(FANG, 1L, RING, 1L));
        assertEquals(FANG_PRICE + RING_PRICE, engine.pendingKeyValue(KEY, T0));

        // The loot taken: the emptied container is the last thing seen.
        engine.observeKeyContainer(KEY, Collections.emptyMap());
        assertEquals(0L, engine.pendingKeyValue(KEY, T0));

        // A closed chest keeps no stale worth either (reopening starts fresh).
        engine.observeKeyContainer(KEY, mapOf(FANG, 1L, RING, 1L));
        engine.setChestVisible(false);
        assertEquals(0L, engine.pendingKeyValue(KEY, T0));
    }

    @Test
    public void twoObservedKeyTypesSumTheirChests()
    {
        Engine engine = engine();
        engine.markPkLoot(mapOf(KEY, 1L, KEY1, 1L), 50, T0);
        assertNotNull(settle(engine, mapOf(KEY, 1L, KEY1, 1L), T0 + 600L));
        engine.setChestVisible(true);
        engine.observeKeyContainer(KEY, mapOf(FANG, 1L));
        engine.observeKeyContainer(KEY1, mapOf(RING, 3L));
        assertEquals(FANG_PRICE + 3L * RING_PRICE, engine.pendingKeysValue(T0 + 10_000L));
    }

    @Test
    public void theLedgerNamesTheWorthOncePerKeyType()
    {
        Engine engine = engine();
        engine.markPkLoot(mapOf(KEY, 1L), 50, T0);
        assertNotNull(settle(engine, mapOf(KEY, 1L), T0 + 600L));
        engine.markPkLoot(mapOf(KEY, 1L), 50, T0 + 5_000L);
        assertNotNull(settle(engine, mapOf(KEY, 2L), T0 + 5_600L));
        engine.setChestVisible(true);
        engine.observeKeyContainer(KEY, mapOf(FANG, 1L, RING, 1L));

        List<LedgerData.PendingItem> items =
                LedgerData.pendingItems(engine, LedgerData.Entry.current(), T0 + 10_000L);
        int rows = 0;
        int valued = 0;
        for (LedgerData.PendingItem item : items)
        {
            if (item.itemId != KEY) continue;
            rows++;
            if (item.value > 0L) valued++;
        }
        assertTrue("every stacked claim of the key lists", rows >= 2);
        assertEquals("but one chest names its worth once", 1, valued);
        assertEquals(FANG_PRICE + RING_PRICE, engine.pendingKeysValue(T0 + 10_000L));
    }

    @Test
    public void anUnpricedPartShowsNothing()
    {
        Engine engine = engine();
        engine.setChestVisible(true);
        engine.observeKeyContainer(KEY, mapOf(FANG, 1L, 123456, 1L));
        assertEquals(
                "one part without a quote fails the whole manifest closed",
                0L,
                engine.pendingKeyValue(KEY, T0));
    }

    @Test
    public void everyPendingKeyTypeCountsItsObservedChestOnce()
    {
        Engine engine = engine();
        engine.markPkLoot(Collections.singletonMap(KEY, 2L), 50, T0);
        assertNotNull("the key pickup books its audit row", settle(engine, KEY, 2L, T0 + 600L));
        assertFalse("and opens a pending claim", engine.getPendingClaims().isEmpty());
        assertEquals(2L, engine.getPendingClaims().get(0).getQuantity());

        engine.setChestVisible(true);
        engine.observeKeyContainer(KEY, mapOf(FANG, 1L, RING, 1L));
        assertEquals(
                "two keys of one type take one chest's contents once",
                FANG_PRICE + RING_PRICE,
                engine.pendingKeysValue(T0 + 10_000L));
        assertEquals(FANG_PRICE + RING_PRICE, engine.pendingKeyValue(KEY, T0 + 10_000L));
    }

    private static Transaction settle(Engine engine, int id, long qty, long now)
    {
        return settle(engine, Collections.singletonMap(id, qty), now);
    }

    private static Transaction settle(Engine engine, Map<Integer, Long> quantities, long now)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(quantities);
        Transaction result = engine.processIfDirty(snapshot, now, null);
        return result != null ? result : engine.processIfDirty(snapshot, now + 1L, null);
    }

    private static Engine engine()
    {
        Engine engine = new Engine(PendingKeyValueTest::flows, new TransactionClassifier(), CONFIG);
        engine.ensureSession(T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        return engine;
    }

    private static List<Flow> flows(Map<Integer, Long> deltas)
    {
        List<Flow> flows = new ArrayList<>();
        for (Map.Entry<Integer, Long> entry : deltas.entrySet())
        {
            long price =
                    entry.getKey() == FANG ? FANG_PRICE : entry.getKey() == RING ? RING_PRICE : 0L;
            flows.add(
                    new Flow(
                            entry.getKey(),
                            "Item " + entry.getKey(),
                            entry.getValue(),
                            (int) price,
                            entry.getValue() * price));
        }
        return flows;
    }

    private static Map<Integer, Long> mapOf(Object... values)
    {
        Map<Integer, Long> result = new HashMap<>();
        for (int index = 0; index + 1 < values.length; index += 2)
        {
            result.put((Integer) values[index], (Long) values[index + 1]);
        }
        return result;
    }
}

package com.gpmanager;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.events.ItemDespawned;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * The game's ammo-picking setting puts picked-up darts straight into the blowpipe (OSRS Wiki): the
 * pack never gains them, yet the shot they came from is recovered, once.
 */
public class PipePickupTest
{
    private static final int DART = 807;
    private static final String PIPE = "pipe";

    private static Flow dartsSpent(long quantity)
    {
        return new Flow(DART, "Iron dart", -quantity, 10, -quantity * 10, PriceSource.GRAND_EXCHANGE);
    }

    /** A Checked pipe, twelve shots on the ground, and a Take on eight of them. */
    private static ReviewFixesTest.Plugin firedThenTake(long packAfterPickup, int[] tick)
    {
        Engine engine = ReviewFixesTest.engine();
        engine.observeCheck(ChargeCheck.parse("Darts: Iron dart x 100. Scales: 100 (1.0%)."), PIPE,
            ReviewFixesTest.T0);
        for (int shot = 0; shot < 12; shot++)
        {
            engine.bookEstimatedCharge(PIPE, "Toxic blowpipe", ActionKind.CAST,
                Collections.singletonList(dartsSpent(1)), ReviewFixesTest.T0 + 100L + shot);
        }
        ReviewFixesTest.Plugin p = ReviewFixesTest.plugin(engine, tick);
        p.snapshotFactory = new ContainerSnapshotFactory(p.client, null)
        {
            @Override
            ContainerSnapshot capture(boolean equipment, boolean pouch)
            {
                return new ContainerSnapshot(Collections.singletonMap(DART, packAfterPickup));
            }

            @Override
            boolean bagOpen()
            {
                return false;
            }
        };
        p.charges.blowpipeDart = DART;
        Observation take = ReviewFixesTest.take(p);
        take.item = DART;
        take.at = 10;
        take.x = 10;
        take.y = 10;
        take.held = 0L;
        Map<String, Object> pile = new HashMap<>();
        pile.put("getId", DART);
        pile.put("getQuantity", 8);
        pile.put("getOwnership", TileItem.OWNERSHIP_SELF);
        p.onItemDespawned(new ItemDespawned(ReviewFollowupTest.tile(10, 10),
            ReviewFixesTest.proxy(TileItem.class, pile)));
        return p;
    }

    @Test
    public void dartsTakenStraightIntoThePipeRecoverTheShot()
    {
        int[] tick = {11};
        ReviewFixesTest.Plugin p = firedThenTake(0L, tick);
        p.pipePickups();
        assertEquals("the decision waits for the pack", 120L, p.engine.getMetrics(ReviewFixesTest.T0 + 1_000L).costs);
        tick[0] = 13;
        p.pipePickups();
        assertEquals("8 of the 12 darts went back into the pipe", 40L,
            p.engine.getMetrics(ReviewFixesTest.T0 + 1_000L).costs);
        p.pipePickups();
        assertEquals("one pickup recovers once", 40L, p.engine.getMetrics(ReviewFixesTest.T0 + 1_000L).costs);
    }

    @Test
    public void dartsThePackGainedAreLeftToTheOrdinaryPickup()
    {
        int[] tick = {11};
        ReviewFixesTest.Plugin p = firedThenTake(8L, tick);
        tick[0] = 13;
        p.pipePickups();
        assertEquals("the pack's own settle books this pickup, not the pipe path", 120L,
            p.engine.getMetrics(ReviewFixesTest.T0 + 1_000L).costs);
    }
}

package com.gpmanager;

import java.lang.reflect.Field;
import java.util.*;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import org.junit.Test;
import static org.junit.Assert.*;

/** Real settlement/callback boundaries missed by the isolated accounting helpers. */
/**
 * Partial PK pickups, pending loot chests, reclaim fees and coinless GE Collect settle
 * through inventory evidence only. Review regressions (September 2026) kept under the
 * subject they test.
 */
public class PkChestAndReclaimSettlementTest
{
    private final GpManagerConfig config = new GpManagerConfig() {
        public int stabilizationTicks() { return 0; }
        public boolean keepTransferAuditRows() { return true; }
    };

    private Engine engine()
    {
        Engine engine = new Engine(deltas -> {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, qty) -> flows.add(new Flow(id, "Item " + id, qty,
                id == 995 ? 1 : 100, qty * (id == 995 ? 1 : 100))));
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        engine.setBaseline(ContainerSnapshot.empty());
        return engine;
    }

    private Engine orderedKeyEngine(boolean reverse)
    {
        Engine engine = new Engine(deltas -> {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, qty) -> flows.add(new Flow(id, "Item " + id, qty, 100,
                qty * 100)));
            flows.sort(Comparator.comparingInt((itemData -> itemData.itemId)));
            if (reverse)
            {
                Collections.reverse(flows);
            }
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        engine.setBaseline(ContainerSnapshot.empty());
        return engine;
    }

    private Transaction settle(Engine engine, int id, long qty, long now)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(Collections.singletonMap(id, qty));
        Transaction result = engine.processIfDirty(snapshot, now, null);
        return result != null ? result : engine.processIfDirty(snapshot, now + 1L, null);
    }

    private Transaction settleSnapshot(Engine engine, Map<Integer, Long> quantities, long now)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(quantities);
        Transaction result = engine.processIfDirty(snapshot, now, null);
        return result != null ? result : engine.processIfDirty(snapshot, now + 1L, null);
    }

    @Test
    public void npcAndPlayerLootInOneSnapshotKeepTheirSeparateOwners()
    {
        for (boolean pkFirst : new boolean[] {false, true})
        {
            Engine engine = engine();
            if (pkFirst) engine.markPkLoot(Collections.singletonMap(4151, 1L), 50, 1_100L);
            engine.markLoot(Collections.singletonMap(526, 1L), 50, "Loot from Goblin", "Goblin");
            if (!pkFirst) engine.markPkLoot(Collections.singletonMap(4151, 1L), 50, 1_100L);
            assertNotNull(settleSnapshot(engine, Map.of(526, 1L, 4151, 1L), 1_600L));
            assertEquals("both measured pickups count once", 200L, engine.getMetrics(2_000L).revenue);
            assertEquals("only the player-owned pickup contributes to PK", 100L, pkRevenue(engine));
            List<Transaction> rows = engine.getActiveSession().getTransactions();
            assertEquals(2, rows.size());
            Transaction npc = rows.stream().filter(t -> t.getContext() == Context.LOOT).findFirst().get();
            Transaction pk = rows.stream().filter(t -> t.getContext() == Context.PK_LOOT).findFirst().get();
            assertEquals(Map.of(526, 1L), quantities(npc.getFlows()));
            assertEquals(Map.of(4151, 1L), quantities(pk.getFlows()));
            assertEquals("Goblin", npc.getActivityName());
            assertNotNull(pk.getEncounterId());
            assertNull("the same measured snapshot cannot book again",
                settleSnapshot(engine, Map.of(526, 1L, 4151, 1L), 2_200L));
        }
    }

    @Test
    public void sharedItemQuantitiesAndExtraGainsAreSplitWithoutDoubleCounting()
    {
        Engine engine = engine();
        engine.markLoot(Map.of(526, 2L), 50, "Loot from Goblin", "Goblin");
        engine.markPkLoot(Map.of(526, 3L), 50, 1_100L);
        List<Transaction> published = new ArrayList<>();
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(Map.of(526, 8L));
        engine.processIfDirty(snapshot, 1_600L, published::add);
        Transaction remaining = engine.processIfDirty(snapshot, 1_601L, published::add);
        assertNotNull(remaining);
        assertEquals(Context.GENERIC, remaining.getContext());
        assertEquals(Map.of(526, 3L), quantities(remaining.getFlows()));
        assertEquals("both source receipts reach presentation", 2, published.size());
        assertEquals(Map.of(526, 2L), quantities(published.get(0).getFlows()));
        assertEquals(Map.of(526, 3L), quantities(published.get(1).getFlows()));
        assertEquals(800L, engine.getMetrics(2_000L).revenue);
        assertEquals(300L, pkRevenue(engine));
        assertEquals(3, engine.getActiveSession().getTransactions().size());
    }

    @Test
    public void twoPlayerPickupsKeepTheirOwnEncountersAndPublishAfterBooking()
    {
        Engine engine = engine();
        engine.markPkLoot(Map.of(4151, 1L), 50, 1_100L);
        engine.markPkLoot(Map.of(4151, 1L), 50, 1_200L);
        List<Transaction> published = new ArrayList<>();
        java.util.function.Consumer<Transaction> listener = row ->
        {
            assertEquals("canonical booking is complete before publishing", 200L,
                engine.getMetrics(2_000L).revenue);
            published.add(row);
        };
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(Map.of(4151, 2L));
        engine.processIfDirty(snapshot, 1_600L, listener);
        Transaction last = engine.processIfDirty(snapshot, 1_601L, listener);
        assertNotNull(last);
        assertEquals(1, published.size());
        assertNotEquals(last.getEncounterId(), published.get(0).getEncounterId());
        assertEquals(100L, last.autoNet());
        assertEquals(100L, published.get(0).autoNet());
        assertEquals(200L, pkRevenue(engine));
        assertEquals(2, engine.getActiveSession().pk().kills);
    }

    private Transaction createPendingKeyManifest(Engine engine, long now)
    {
        int keyId = net.runelite.api.gameval.ItemID.WILDY_LOOT_KEY0;
        engine.markPkLoot(Collections.singletonMap(keyId, 1L), 50, now);
        assertNotNull(settleSnapshot(engine, Collections.singletonMap(keyId, 1L), now + 500L));

        engine.setChestVisible(true);
        engine.observeKeyContainer(keyId, Collections.singletonMap(526, 1L));
        engine.observeKeyContainer(keyId, Collections.<Integer, Long>emptyMap());
        return engine.getActiveSession().getTransactions().get(0);
    }

    private static Map<Integer, Long> heldKeyAndManifestItem(int keyId)
    {
        return heldKeyAndManifestItems(keyId, 1L);
    }

