package com.gpmanager;

import com.google.gson.Gson;
import java.lang.reflect.Proxy;
import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.http.api.item.ItemPrice;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * The eight findings of the Codex review of GP Manager 1.2 (2026-10-05), kept as regression tests.
 * Adapted from Codex's probes; the catch lookup is tested through its helper, without reflection.
 */
public class ReviewFixesTest {
    static final long T0 = 1_700_000_000_000L;
    static final int BONES = 526;
    static final GpManagerConfig CONFIG = new GpManagerConfig() {
        @Override public int stabilizationTicks() { return 0; }
        @Override public boolean autoStartSession() { return false; }
    };

    static Engine engine() {
        JsonCodec.bind(new Gson());
        Engine e = new Engine(deltas -> {
            List<Flow> result = new ArrayList<>();
            deltas.forEach((id, q) -> result.add(new Flow(id, "Item " + id, q, 100, q * 100)));
            return result;
        }, new TransactionClassifier(), CONFIG);
        e.ensureSession(T0);
        e.setBaseline(ContainerSnapshot.empty());
        return e;
    }

    static final class Plugin extends GpManagerPlugin {
        boolean ready = true;
        @Override boolean canIngest() { return ready; }
        @Override void pulse() { }
    }

    static Plugin plugin(Engine engine, int[] tick) {
        Plugin p = new Plugin();
        p.engine = engine;
        p.config = CONFIG;
        p.client = proxy(Client.class, new HashMap<String, Object>() {{
            put("getTickCount", (java.util.function.IntSupplier) () -> tick[0]);
            put("getGameState", GameState.LOGIN_SCREEN);
            put("getLocalPlayer", proxy(Player.class, Collections.singletonMap("getWorldLocation", new WorldPoint(100, 100, 0))));
        }});
        p.snapshotFactory = new ContainerSnapshotFactory(p.client, null) {
            @Override ContainerSnapshot capture(boolean equipment, boolean pouch) { return ContainerSnapshot.empty(); }
            @Override boolean bagOpen() { return true; }
        };
        p.persistence = new Persistence(p.client, null, null, null, engine);
        p.charges = new ChargeIntake(p.client, null, CONFIG, engine, null);
        return p;
    }

    static Observation take(Plugin p) {
        Observation e = p.engine.inbox.peek(Inbox.GROUND_CLICK);
        return e == null ? p.engine.inbox.add(Inbox.GROUND_CLICK, -1, 1, 5, null) : e;
    }

    static Observation bag(Plugin p) {
        Observation e = p.engine.inbox.open.stream().filter(v -> v.kind == Inbox.BAG_GAIN).findFirst().orElse(null);
        if (e == null) {
            Observation click = take(p);
            e = p.engine.inbox.add(Inbox.BAG_GAIN, click.item, 0, 5, null);
            e.held = click.held;
        }
        return e;
    }

    static long qty(Plugin p, int kind) {
        Observation e = p.engine.inbox.peek(kind);
        return e == null ? 0L : e.qty;
    }

    @Test public void pendingBagGainMustRespectTheAccountReadinessFence() {
        Engine e = engine();
        Plugin p = plugin(e, new int[] { 11 });
        ReviewFixesTest.take(p).item = BONES;
        ReviewFixesTest.take(p).held = 0;
        ReviewFixesTest.bag(p).at = 10;
        ReviewFixesTest.bag(p).qty = 3;
        p.ready = false; // An account switch, restore or logout has fenced ingestion.
        p.onGameTick(new GameTick());
        assertEquals("a held account must not acquire a synthetic inventory delta", 0L, e.baseline.quantityOf(BONES));
    }

    @Test public void fencedBagSettlementMustNotWaitForTheEngineMonitor() throws Exception {
        Engine e = engine();
        Plugin p = plugin(e, new int[] { 11 });
        ReviewFixesTest.take(p).item = BONES;
        ReviewFixesTest.bag(p).at = 10;
        ReviewFixesTest.bag(p).qty = 3;
        p.ready = false;
        CountDownLatch tickReturned = new CountDownLatch(1);
        AtomicReference<Throwable> error = new AtomicReference<>();
        Thread tick = new Thread(() -> {
            try { p.onGameTick(new GameTick()); }
            catch (Throwable ex) { error.set(ex); }
            finally { tickReturned.countDown(); }
        });
        try {
            synchronized (e) { // A maintenance snapshot/restore owns this monitor.
                tick.start();
                assertTrue("fenced gameplay must return without waiting for maintenance", tickReturned.await(250, TimeUnit.MILLISECONDS));
            }
        } finally {
            tick.join(2_000);
            assertNull(error.get());
        }
    }

    @Test public void aNearbyDespawnIsNotProofThatTheClickedItemEnteredOurBag() {
        Plugin p = plugin(engine(), new int[] { 11 });
        ReviewFixesTest.take(p).item = BONES;
        ReviewFixesTest.take(p).at = 10;
        // The clicked pile was on (100,100); another player's pile on (101,100) expires.
        Tile tile = proxy(Tile.class, Collections.singletonMap("getWorldLocation", new WorldPoint(101, 100, 0)));
        TileItem item = proxy(TileItem.class, new HashMap<String, Object>() {{ put("getId", BONES); put("getQuantity", 3); }});
        p.onItemDespawned(new ItemDespawned(tile, item));
        assertEquals("an unrelated tile's despawn must not be promoted to counted loot", 0L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
    }

    @Test public void aCatchMustResolveToRawFishEvenWhenCookedFishComesFirst() {
        assertEquals("cooked first", 335, GpManagerPlugin.caughtItem("trout", List.of(price(333, "Trout"), price(335, "Raw trout"))));
        assertEquals("raw first", 335, GpManagerPlugin.caughtItem("trout", List.of(price(335, "Raw trout"), price(333, "Trout"))));
        assertEquals("logs have no raw form", 1515, GpManagerPlugin.caughtItem("yew logs", List.of(price(1515, "Yew logs"))));
        assertEquals("no match", -1, GpManagerPlugin.caughtItem("trout", List.of(price(5, "Trout pie"))));
    }

    static ItemPrice price(int id, String name) {
        ItemPrice price = new ItemPrice();
        price.setId(id);
        price.setName(name);
        return price;
    }

    @Test public void normalWorldStillPricesCrystalShardProxy() {
        Valuation values = proxyValuation(Valuation.Economy.NORMAL);
        Flow shard = values.value(Collections.singletonMap(23962, 1L), T0).get(0);
        assertEquals(100, shard.unitPrice);
        assertEquals(PriceSource.CURRENCY_PROXY, shard.getPriceSource());
    }

    @Test public void specialWorldMustNotPriceCrystalShardsFromTheMainGameMarket() {
        Flow shard = proxyValuation(Valuation.Economy.UNSUPPORTED_SPECIAL).value(Collections.singletonMap(23962, 1L), T0).get(0);
        assertEquals(PriceSource.UNPRICED, shard.getPriceSource());
        assertEquals(0, shard.unitPrice);
    }

    @Test public void unknownWorldMustNotPriceCrystalShardsBeforeLogin() {
        Flow shard = proxyValuation(Valuation.Economy.UNKNOWN).value(Collections.singletonMap(23962, 1L), T0).get(0);
        assertEquals(PriceSource.UNPRICED, shard.getPriceSource());
    }

    @Test public void aHigherShardQuoteMustOnlyPriceTheNewCharge() {
        ChargeIntake intake = new ChargeIntake(null, null, CONFIG, engine(), null);
        assertEquals(10_000L, intake.carriedValue(ChargeCheck.ChargedItem.CRYSTAL_BOW, 23962, 100L, 10_000, 100));
        assertEquals("one new charge must not revalue the 100 already consumed", 200L,
            intake.carriedValue(ChargeCheck.ChargedItem.CRYSTAL_BOW, 23962, 1L, 20_000, 100));
    }

    @Test public void aLowerShardQuoteMustOnlyPriceTheNewCharge() {
        ChargeIntake intake = new ChargeIntake(null, null, CONFIG, engine(), null);
        assertEquals(10_000L, intake.carriedValue(ChargeCheck.ChargedItem.CRYSTAL_BOW, 23962, 100L, 10_000, 100));
        assertEquals("a cheaper quote must not subtract value booked at the previous quote", 90L,
            intake.carriedValue(ChargeCheck.ChargedItem.CRYSTAL_BOW, 23962, 1L, 9_000, 100));
    }

    @Test public void aSlowFactoryResetMustLeaveTheRuneLiteSwingThreadResponsive() throws Exception {
        CountDownLatch diskEntered = new CountDownLatch(1);
        CountDownLatch diskCanFinish = new CountDownLatch(1);
        CountDownLatch uiHeartbeat = new CountDownLatch(1);
        Persistence disk = new Persistence(null, null, null, null, null) {
            @Override synchronized ResetOutcome factoryReset(long now) {
                diskEntered.countDown();
                try { diskCanFinish.await(2, TimeUnit.SECONDS); }
                catch (InterruptedException ex) { throw new AssertionError(ex); }
                return new ResetOutcome(false, "test reset refused");
            }
        };
        AtomicReference<GrindsController> controller = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> controller.set(new GrindsController(new SidebarPanel(engine(), CONFIG, null, null, disk))));
        SwingUtilities.invokeLater(() -> controller.get().resetNow(true));
        try {
            assertTrue("the reset was dispatched", diskEntered.await(2, TimeUnit.SECONDS));
            SwingUtilities.invokeLater(uiHeartbeat::countDown);
            assertTrue("disk work must not hold the entire RuneLite Swing thread", uiHeartbeat.await(250, TimeUnit.MILLISECONDS));
        } finally {
            diskCanFinish.countDown();
            SwingUtilities.invokeAndWait(() -> { });
        }
    }

    static Valuation proxyValuation(Valuation.Economy economy) {
        return new Valuation(CONFIG, id -> null, (id, active) -> 15_000, id -> false, economy);
    }

    @SuppressWarnings("unchecked")
    static <T> T proxy(Class<T> type, Map<String, Object> values) {
        return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, (p, method, args) -> {
            Object value = values.get(method.getName());
            if (value instanceof java.util.function.IntSupplier) return ((java.util.function.IntSupplier) value).getAsInt();
            if (value != null) return value;
            Class<?> r = method.getReturnType();
            if (r == boolean.class) return false;
            if (r == int.class) return 0;
            if (r == long.class) return 0L;
            if (r == byte.class) return (byte) 0;
            if (r == short.class) return (short) 0;
            if (r == float.class) return 0F;
            if (r == double.class) return 0D;
            if (r == char.class) return '\0';
            return null;
        });
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.events.ItemDespawned;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

/**
 * The Codex follow-up review of GP Manager 1.2 (2026-10-05), kept as regression tests, plus the
 * positive control: your own loot vanishing on your Take still counts as a bag pickup.
 */
public class ReviewFollowupTest {
    @Rule public final TemporaryFolder temporary = new TemporaryFolder();

    static Tile tile(int sceneX, int sceneY) {
        Map<String, Object> values = new HashMap<>();
        values.put("getWorldLocation", new WorldPoint(100, 100, 0));
        values.put("getSceneLocation", new Point(sceneX, sceneY));
        return ReviewFixesTest.proxy(Tile.class, values);
    }

    static TileItem bones() {
        Map<String, Object> values = new HashMap<>();
        values.put("getId", ReviewFixesTest.BONES);
        values.put("getQuantity", 3);
        // The game marks a pile dropped for you as yours (Codex research 1.2).
        values.put("getOwnership", TileItem.OWNERSHIP_SELF);
        return ReviewFixesTest.proxy(TileItem.class, values);
    }

    static ReviewFixesTest.Plugin take() {
        ReviewFixesTest.Plugin p = ReviewFixesTest.plugin(ReviewFixesTest.engine(), new int[] {11});
        ReviewFixesTest.take(p).item = ReviewFixesTest.BONES;
        ReviewFixesTest.take(p).at = 10;
        ReviewFixesTest.take(p).x = 10;
        ReviewFixesTest.take(p).y = 10;
        return p;
    }

    @Test public void aDifferentSceneTileIsRejectedWithValidTileMetadata() {
        ReviewFixesTest.Plugin p = take();
        p.onItemDespawned(new ItemDespawned(tile(11, 10), bones()));
        assertEquals(0L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
    }

    @Test public void anotherPlayerTakingTheClickedPileMustNotBecomeOurBagLoot() {
        ReviewFixesTest.Plugin p = take();
        // Our Take has not succeeded. Another player removes the clicked pile first.
        // There is no increase in our inventory or confirmation of a bag insertion.
        p.onItemDespawned(new ItemDespawned(tile(10, 10), bones()));
        assertEquals("the matching tile is intent, not proof of our successful pickup", 0L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
    }

    @Test public void yourOwnLootVanishingOnYourTakeIsStillABagPickup() {
        ReviewFixesTest.Plugin p = take();
        p.engine.markLoot(Collections.singletonMap(ReviewFixesTest.BONES, 3L), 100, "Loot from Guard", "Guard");
        p.onItemDespawned(new ItemDespawned(tile(10, 10), bones()));
        assertEquals("loot from your own kill is yours to pick up", 3L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
    }

    @Test public void anIdentityBoundaryMustClearPendingBagEvidenceImmediately() {
        Engine e = ReviewFixesTest.engine();
        ReviewFixesTest.Plugin p = ReviewFixesTest.plugin(e, new int[] {11});
        p.geOfferLedger = new OfferSlots();
        p.interactionContextTracker = new InteractionContextTracker(p.client, e, ReviewFixesTest.CONFIG);
        ReviewFixesTest.take(p).item = ReviewFixesTest.BONES;
        ReviewFixesTest.take(p).at = 10;
        ReviewFixesTest.bag(p).at = 10;
        ReviewFixesTest.bag(p).qty = 3;
        p.engine.inbox.put(Inbox.FEE, -1, 5_964L, 10, null);
        p.engine.inbox.add(Inbox.CHEST, -1, 1, 10, null).x = InventoryID.RAIDS_REWARDS;
        p.engine.inbox.add(Inbox.KIT_SNAPSHOT, InventoryID.TACKLE_BOX, 1, Integer.MAX_VALUE, null).data = new Item[0];
        p.beginOwnerSwitch(); // The async bind may finish before the next GameTick sees !nh().
        assertEquals("old-account bag evidence must be cleared at the boundary, not a later tick", 0L, ReviewFixesTest.qty(p, Inbox.BAG_GAIN));
        assertEquals("a waiting reclaim fee never reaches the next account (Codex research 1.2)", 0L, ReviewFixesTest.qty(p, Inbox.FEE));
        assertEquals("nor a chest Bank-all window", null, p.engine.inbox.peek(Inbox.CHEST));
        assertTrue("nor the last account's kit contents", p.engine.inbox.peek(Inbox.KIT_SNAPSHOT) == null);
    }

    @Test public void resetAndItsSafetyCopyMustStayWithTheAccountThatWasConfirmed() throws Exception {
        JsonCodec.bind(new Gson());
        Engine e = ReviewFixesTest.engine();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(temporary.newFolder().toPath()), false);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        TrackingIdentity alice = new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID);
        TrackingIdentity bob = new TrackingIdentity("rsprofile.bob", TrackingIdentity.ACCOUNT_HASH_INVALID);
        AtomicReference<TrackingIdentity> current = new AtomicReference<>(alice);
        AtomicReference<String> backedUpOwner = new AtomicReference<>();
        AtomicReference<String> resetOwner = new AtomicReference<>();
        CountDownLatch backupFinished = new CountDownLatch(1);
        Persistence c = new Persistence(null, null, repository, writer, e) {
            @Override TrackingIdentity resolveCurrentIdentity() { return current.get(); }
            @Override Filepath writeBackup(long now) throws java.io.IOException {
                backedUpOwner.set(account());
                Filepath result = super.writeBackup(now);
                backupFinished.countDown();
                return result;
            }
            @Override synchronized ResetOutcome factoryReset(long now) {
                resetOwner.set(account());
                return super.factoryReset(now);
            }
        };
        c.start();
        try {
            assertTrue(c.switchIdentity(alice, true, true));
            e.ensureSession(System.currentTimeMillis());
            SwingUtilities.invokeAndWait(() -> {
                SidebarPanel p = new SidebarPanel(e, ReviewFixesTest.CONFIG, null, repository, c);
                new GrindsController(p).factoryReset();
                ShellProbe.pressSheet(p.shell, "Back up & delete");
                try {
                    assertTrue("Alice's backup completed", backupFinished.await(5, TimeUnit.SECONDS));
                    // A profile switch finishes while the backup's EDT callback is queued.
                    current.set(bob);
                    assertTrue(c.switchIdentity(bob, false, true));
                    long now = System.currentTimeMillis();
                    e.ensureSession(now);
                    e.getActiveSession().addTransaction(new Transaction(now, TransactionType.GAIN, Context.GENERIC, "", "", true,
                        Collections.singletonList(new Flow(526, "Bones", 2L, 100, 200L)),
                        Confidence.CONFIRMED, "fixture", null), 2_000, false);
                    assertEquals("Bob has unrelated history before the callback", 200L, e.getMetrics(now).net);
                } catch (InterruptedException ex) {
                    throw new AssertionError(ex);
                }
            });
            PersistenceProbe.drain(c, 2);
            assertEquals("the safety backup was Alice's", alice.rsProfileKey, backedUpOwner.get());
            assertEquals("Alice's confirmation must not erase Bob; reset target was " + resetOwner.get(),
                200L, e.getMetrics(System.currentTimeMillis()).net);
        } finally {
            c.shutdown(false);
        }
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/** "Bank-all" on a reward chest books its loot, which never passes the inventory (research 1.2). */
public class RewardChestBankAllTest
{
    @Test
    public void theChestTableMatchesRuneLiteConstants()
    {
        Map<Integer, Integer> expected = new HashMap<>();
        expected.put(InterfaceID.RAIDS_REWARDS, InventoryID.RAIDS_REWARDS);
        expected.put(InterfaceID.TOB_CHESTS, InventoryID.TOB_CHESTS);
        expected.put(InterfaceID.TOA_CHESTS, InventoryID.TOA_CHESTS);
        expected.put(InterfaceID.COLOSSEUM_REWARD_CHEST_2, InventoryID.COLOSSEUM_REWARDS);
        expected.put(InterfaceID.PMOON_REWARD, InventoryID.PMOON_REWARDINV);
        expected.put(InterfaceID.WILDY_LOOT_CHEST, InventoryID.LOOT_INV_ACCESS);
        expected.put(InterfaceID.DOM_END_LEVEL_UI, InventoryID.DOM_LOOTPILE);
        expected.put(InterfaceID.TRAWLER_REWARD, InventoryID.TRAWLER_REWARDINV);
        expected.put(InterfaceID.FOSSIL_DRIFTNET, InventoryID.MACRO_CERTER);
        assertEquals(expected, GpManagerPlugin.CHESTS);
    }

    /** Codex research 1.2: only what really leaves the chest after a Bank-all is booked, once. */
    @Test
    public void bankAllBooksWhatLeavesTheChestOnceAndIgnoresOtherContainers()
    {
        Engine engine = ReviewFixesTest.engine();
        int[] tick = {100};
        Item[][] chest = {{new Item(ItemID.TWISTED_BOW, 1), new Item(ItemID.DRAGON_ARROW, 50), null}};
        ItemContainer rewards = (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[]{ItemContainer.class}, (proxy, method, args) -> "getItems".equals(method.getName()) ? chest[0] : null);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, args) -> {
                if ("getTickCount".equals(method.getName()))
                {
                    return tick[0];
                }
                if ("getItemContainer".equals(method.getName()))
                {
                    return (int) args[0] == InventoryID.RAIDS_REWARDS ? rewards : null;
                }
                return null;
            });
        GpManagerPlugin plugin = new GpManagerPlugin();
        plugin.engine = engine;
        plugin.client = client;
        plugin.snapshotFactory = new ContainerSnapshotFactory(client, null);

        plugin.bankAll(InterfaceID.RAIDS_REWARDS);
        assertEquals("the click alone books nothing", 0L, engine.baseline.quantityOf(ItemID.TWISTED_BOW));
        plugin.chestChanged(InventoryID.RAIDS_REWARDS, rewards);
        assertEquals("a refused Bank-all moves nothing", 0L, engine.baseline.quantityOf(ItemID.TWISTED_BOW));

        chest[0] = new Item[]{new Item(ItemID.DRAGON_ARROW, 20)};
        tick[0]++;
        plugin.chestChanged(InventoryID.RAIDS_REWARDS, rewards);
        assertEquals("the bow reads as picked up", -1L, engine.baseline.quantityOf(ItemID.TWISTED_BOW));
        assertEquals("only the arrows that left", -30L, engine.baseline.quantityOf(ItemID.DRAGON_ARROW));

        tick[0] += 6;
        plugin.bankAll(InterfaceID.RAIDS_REWARDS);
        plugin.chestChanged(InventoryID.RAIDS_REWARDS, rewards);
        assertEquals("a repeated click books nothing again", -1L, engine.baseline.quantityOf(ItemID.TWISTED_BOW));
        assertEquals(-30L, engine.baseline.quantityOf(ItemID.DRAGON_ARROW));

        chest[0] = new Item[0];
        plugin.chestChanged(InventoryID.BANK, rewards);
        assertEquals("another container is not the chest", -30L, engine.baseline.quantityOf(ItemID.DRAGON_ARROW));
    }
}

