    public void spendIsAttributedToTheActivityBeingPlayed()
    {
        Engine engine = engine();
        long start = 75_000L;
        engine.ensureSession(start);
        engine.getActiveSession().setActivityHint("Zulrah", start);
        ChargeOutcomeTest.none(engine.observeCheck(blowpipe(100, 10), TARGET, start));
        ChargeDelta use = engine.observeCheck(blowpipe(98, 10), TARGET, start + 1_000L);
        Transaction spend = engine.bookChargeSpend(use, "Toxic blowpipe",
            Collections.singletonList(new Flow(12934, "Zulrah's scales", -2L, 100, -200L, PriceSource.GRAND_EXCHANGE)), start + 1_000L, null);
        assertTrue(spend != null);
        assertEquals("Zulrah", spend.getActivityName());
        engine.getActiveSession().setActivityHint("Vorkath", start + 2_000L);
        ChargeDelta later = engine.observeCheck(blowpipe(97, 10), TARGET, start + 3_000L);
        Transaction laterSpend = engine.bookChargeSpend(later, "Toxic blowpipe",
            Collections.singletonList(new Flow(12934, "Zulrah's scales", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE)), start + 3_000L, null);
        assertEquals("Vorkath", laterSpend.getActivityName());
    }


    /** A refundless crystal load books its shards as Supplies the moment they arrive. */
    @Test
    public void committedCrystalLoadsBookTheirShardsAsSupplies()
    {
        for (ChargeCheck.ChargedItem piece : new ChargeCheck.ChargedItem[] {
            ChargeCheck.ChargedItem.CRYSTAL_HELM, ChargeCheck.ChargedItem.CRYSTAL_BODY,
            ChargeCheck.ChargedItem.CRYSTAL_LEGS, ChargeCheck.ChargedItem.CRYSTAL_SHIELD})
        {
            Engine engine = engine();
            long start = 100_000L;
            engine.ensureSession(start);
            engine.setBaseline(snapshot(ItemID.PRIF_CRYSTAL_SHARD, 42L));

            engine.markChargeLoad(piece, ItemID.PRIF_CRYSTAL_SHARD, "Crystal shard", TARGET, 8);
            engine.markDirty();
            Transaction load = settle(engine, snapshot(ItemID.PRIF_CRYSTAL_SHARD, 38L), start + 600L);

            assertEquals(piece.name(), TransactionType.CONSUMPTION, load.autoType());
            assertTrue(piece.name(), load.isCounted());
            assertEquals(piece.name(), GameData.msg("committed-load") + piece.getDisplayName(),
                load.getNote());
            assertEquals(piece.name(), ActionKind.SUPPLIES, load.getActionKind());
            assertEquals(piece.name(), -2_000L, load.getNet());
            assertEquals(piece.name(), 2_000L, engine.getMetrics(start + 2_400L).costs);
            assertEquals(piece.name(), -2_000L, engine.getMetrics(start + 2_400L).net);
        }
    }

    private static int countTransactions(Session session, TransactionType type)
    {
        int count = 0;
        for (Transaction transaction : session.getTransactions())
        {
            if (transaction.getType() == type)
            {
                count++;
            }
        }
        return count;
    }

    private static Engine engine()
    {
        return new Engine(ChargeLoadReviewLifecycleTest::flowsForTest,
            new TransactionClassifier(), CONFIG);
    }

    private static Engine engineWithSplitScaleFlow()
    {
        return new Engine(deltas -> {
            Long scaleDelta = deltas.get(12934);
            if (scaleDelta == null || scaleDelta >= 0L || scaleDelta != -50L)
            {
                return flowsForTest(deltas);
            }
            return Arrays.asList(
                new Flow(12934, "Zulrah's scales", -20L, 100, -2_000L,
                    PriceSource.GRAND_EXCHANGE),
                new Flow(12934, "Zulrah's scales", -30L, 100, -3_000L,
                    PriceSource.GRAND_EXCHANGE));
        }, new TransactionClassifier(), CONFIG);
    }

    private static List<Flow> flowsForTest(Map<Integer, Long> deltas)
    {
        List<Flow> flows = new ArrayList<>();
        for (Map.Entry<Integer, Long> entry : deltas.entrySet())
        {
            int id = entry.getKey();
            String name = itemName(id);
            int price = id == 12934 ? 100 : id == 995 ? 1 : 500;
            flows.add(new Flow(id, name, entry.getValue(), price, entry.getValue() * price,
                PriceSource.GRAND_EXCHANGE));
        }
        return flows;
    }

    private static String itemName(int id)
    {
        if (id == 12934) return "Zulrah's scales";
        if (id == 560) return "Death rune";
        if (id == 562) return "Chaos rune";
        if (id == 554) return "Fire rune";
        if (id == 995) return "Coins";
        return "Rune dart";
    }

    private static Transaction only(List<Transaction> rows, TransactionType type)
    {
        Transaction match = null;
        for (Transaction row : rows)
        {
            if (row.autoType() == type)
            {
                assertTrue("expected a single row of type " + type, match == null);
                match = row;
            }
        }
        assertNotNull("missing row of type " + type, match);
        return match;
    }

    private static ChargeCheck blowpipe(long scales, long darts)
    {
        return ChargeCheck.parse(
            "Darts: Rune dart x " + darts + ". Scales: " + scales + " (1.0%).");
    }

    private static ContainerSnapshot snapshot(int id, long quantity)
    {
        return snapshot(mapOf(id, quantity));
    }

    private static ContainerSnapshot snapshot(Map<Integer, Long> quantities)
    {
        return new ContainerSnapshot(quantities);
    }

    private static Map<Integer, Long> mapOf(Object... values)
    {
        Map<Integer, Long> result = new HashMap<>();
        for (int index = 0; index + 1 < values.length; index += 2)
        {
            result.put((Integer) values[index], (Long) values[index + 1]);
        }
        return result;
    }

    private static Transaction settle(Engine engine, ContainerSnapshot next, long firstTick)
    {
        Transaction result = engine.processIfDirty(next, firstTick, null);
        assertNull(result);
        result = engine.processIfDirty(next, firstTick + 600L, null);
        assertNull(result);
        return engine.processIfDirty(next, firstTick + 1_200L, null);
    }

}

package com.gpmanager;

import java.util.*;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * A Check counts darts loaded since the last Check as loaded, not unused: picked-up darts reloaded
 * before a Check are not subtracted twice, and an exact top-up still books what was fired.
 */
public class ChargeReloadTest
{
    private static final int DART = 807;
    private static final int SCALES = 12934;
    private static final String PIPE = "pipe";

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, id == DART ? "Iron dart" : "Zulrah's scales",
            quantity, 10, quantity * 10, PriceSource.GRAND_EXCHANGE)));
        return flows;
    };

    private static Flow dartsSpent(long quantity)
    {
        return new Flow(DART, "Iron dart", -quantity, 10, -quantity * 10, PriceSource.GRAND_EXCHANGE);
    }

    private static ChargeCheck read(long darts)
    {
        return ChargeCheck.parse("Darts: Iron dart x " + darts + ". Scales: 100 (1.0%).");
    }

    /** A Checked pipe holding 100 darts, then {@code shots} shots of one dart each. */
    private Engine fired(int shots)
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(ContainerSnapshot.empty());
        engine.observeCheck(read(100), PIPE, 1_000L);
        for (int shot = 0; shot < shots; shot++)
        {
            engine.bookEstimatedCharge(PIPE, "Toxic blowpipe", ActionKind.CAST,
                Collections.singletonList(dartsSpent(1)), 1_100L + shot);
        }
        return engine;
    }

    private static void settle(Engine engine, long darts, long firstTick)
    {
        ContainerSnapshot snapshot = new ContainerSnapshot(Collections.singletonMap(DART, darts));
        engine.markDirty();
        for (long tick = firstTick; tick <= firstTick + 1_800L; tick += 600L)
        {
            engine.processIfDirty(snapshot, tick, null);
        }
    }

    /** Runs a measured Check the way ChargeIntake does: book the spend, then close the window. */
    private static void check(Engine engine, long darts, long now)
    {
        ChargeDelta delta = engine.observeCheck(read(darts), PIPE, now);
        assertEquals(ChargeDelta.CheckResult.SPEND, delta.result);
        var losses = new ArrayList<Flow>();
        for (ChargeDelta.ComponentDelta component : delta.componentDeltas)
        {
            losses.add(component.itemId == DART ? dartsSpent(-component.quantityDelta)
                : new Flow(SCALES, "Zulrah's scales", component.quantityDelta, 10,
                    component.quantityDelta * 10, PriceSource.GRAND_EXCHANGE));
        }
        engine.bookChargeSpend(delta, "Toxic blowpipe", losses, now, PIPE);
        engine.clearPendingEstimates(PIPE, delta.unchanged);
    }

    @Test
    public void pickedUpDartsReloadedBeforeACheckStaySpentOnce()
    {
        Engine engine = fired(10);
        settle(engine, 5L, 2_000L);
        assertEquals("5 picked back up", 50L, engine.getMetrics(5_000L).costs);

        assertTrue(engine.markChargeLoad(ChargeCheck.ChargedItem.BLOWPIPE, DART, "Iron dart", PIPE, 20));
        settle(engine, 0L, 6_000L);
        assertEquals("the reload is a transfer", 50L, engine.getMetrics(9_000L).costs);

        check(engine, 95L, 10_000L);
        assertEquals("10 fired, 5 recovered: 5 darts lost", 50L, engine.getMetrics(11_000L).costs);
    }

    @Test
    public void anExactTopUpStillBooksWhatWasFired()
    {
        Engine engine = fired(5);
        // Five fresh darts already in the pack (not the fired ones) top the pipe back up.
        engine.setBaseline(new ContainerSnapshot(Collections.singletonMap(DART, 5L)));
        assertTrue(engine.markChargeLoad(ChargeCheck.ChargedItem.BLOWPIPE, DART, "Iron dart", PIPE, 20));
        settle(engine, 0L, 6_000L);

        check(engine, 100L, 10_000L);
        assertEquals("5 fired, count unchanged after a 5-dart top-up", 50L, engine.getMetrics(11_000L).costs);
    }

    @Test
    public void dartsPickedUpStraightIntoThePipeAreNotLost()
    {
        // Twelve shots; eight of the fired darts are picked up and go straight back into the pipe,
        // so the pack never changes and the next Check reads only four fewer.
        Engine engine = fired(12);
        assertEquals("before a Check every shot is an estimate", 120L, engine.getMetrics(2_000L).costs);
        check(engine, 96L, 10_000L);
        assertEquals("the Check measures 4 darts lost", 40L, engine.getMetrics(11_000L).costs);
    }

    @Test
    public void dartsPickedUpIntoThePipeShrinkTheShotAndTheCheckAgrees()
    {
        Engine engine = fired(12);
        engine.pickUpIntoPipe(DART, 8L, 5_000L);
        assertEquals("8 of the 12 fired darts went back into the pipe", 40L,
            engine.getMetrics(6_000L).costs);
        check(engine, 96L, 10_000L);
        assertEquals("the Check agrees: 4 darts lost, never 0", 40L, engine.getMetrics(11_000L).costs);
    }

    @Test
    public void aPipePickupWithNoFiredDartsLeftChangesNothing()
    {
        Engine engine = fired(2);
        engine.pickUpIntoPipe(DART, 8L, 5_000L);
        assertEquals("only the 2 fired darts can come back", 0L, engine.getMetrics(6_000L).costs);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.*;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Owner 2026-09-29: uncharging returns the loaded components. The refund is the player's own
 * charge investment coming back, so it books as an ownership-neutral transfer, never income,
 * however long the confirm takes.
 */
public class ChargeUnloadTest
{
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void anUnchargeClickMakesTheReturnedComponentsNeutral()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        Engine engine = engine(config);
        ChargeIntake intake = new ChargeIntake(null, null, config, engine, null);

        engine.startCustom("Nechryael", T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(ItemID.TOTS_CHARGED, 1L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));
        held.remove(ItemID.TOTS_CHARGED);
        held.put(ItemID.TOTS_UNCHARGED, 1L);
        held.put(ItemID.DEATHRUNE, 100L);
        engine.markDirty();
        // A right-click Uncharge on the worn trident; the plugin passes the lowercased option.
        intake.armCheck(click(ItemID.TOTS_CHARGED), "uncharge", "Trident of the seas");
        Transaction result = null;
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)), T0 + 600L + i * 600L, null);
            if (settled != null)
            {
                result = settled;
            }
        }
        assertNotNull(result);
        assertEquals("the refund is a transfer, not income", TransactionType.TRANSFER, result.getType());
        assertFalse(result.isCounted());
        assertEquals("nothing books to the session", 0L, engine.getMetrics(T0 + 2_400L).net);
        assertEquals(0L, engine.getMetrics(T0 + 2_400L).costs);
    }

    @Test
    public void aConfirmThatTakesLongerThanTheClickStillBooksNeutral()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        Engine engine = engine(config);
        int[] tick = {100};
        Map<Integer, Long> held = new HashMap<>();
        held.put(ItemID.TOTS_CHARGED, 1L);
        ChargeIntake intake = new ChargeIntake(client(tick, held), null, config, engine, null)
        {
            @Override
            String itemName(int itemId)
            {
                return itemId == ItemID.DEATHRUNE ? "Death rune" : null;
            }
        };
        engine.startCustom("Nechryael", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));
        intake.armCheck(click(ItemID.TOTS_CHARGED), "uncharge", "Trident of the seas");
        long now = T0;
        // The "Really uncharge?" prompt sits open for twelve ticks: the click's own context lapses.
        for (int i = 0; i < 12; i++)
        {
            tick[0]++;
            intake.watchReturn();
            assertNull(engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)), now += 600L, null));
        }
        held.remove(ItemID.TOTS_CHARGED);
        held.put(ItemID.TOTS_UNCHARGED, 1L);
        held.put(ItemID.DEATHRUNE, 100L);
        engine.markDirty();
        Transaction result = null;
        for (int i = 0; i < 3; i++)
        {
            tick[0]++;
            intake.watchReturn();
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)), now += 600L, null);
            if (settled != null)
            {
                result = settled;
            }
        }
        assertNotNull(result);
        assertEquals("a slow confirm is still a transfer, not income", TransactionType.TRANSFER, result.getType());
        assertEquals(0L, engine.getMetrics(now).net);
    }

    @Test
    public void onlyTheWeaponsOwnComponentsCountAsTheReturn()
    {
        assertTrue("blowpipe scales coming back are the return", ChargeIntake.returnLanded(ChargeCheck.ChargedItem.BLOWPIPE,
            counts(ItemID.SNAKEBOSS_SCALE, 10L), counts(ItemID.SNAKEBOSS_SCALE, 2_010L), ChargeUnloadTest::name));
        assertTrue("trident runes coming back are the return", ChargeIntake.returnLanded(ChargeCheck.ChargedItem.TRIDENT_SEAS,
            Collections.emptyMap(), counts(ItemID.DEATHRUNE, 500L), ChargeUnloadTest::name));
        assertFalse("loot that is not a load component never counts", ChargeIntake.returnLanded(ChargeCheck.ChargedItem.BLOWPIPE,
            Collections.emptyMap(), counts(ItemID.BIG_BONES, 1L), ChargeUnloadTest::name));
        assertFalse("an unchanged stack is not a return", ChargeIntake.returnLanded(ChargeCheck.ChargedItem.BLOWPIPE,
            counts(ItemID.SNAKEBOSS_SCALE, 10L), counts(ItemID.SNAKEBOSS_SCALE, 10L), ChargeUnloadTest::name));
    }

    private static String name(int itemId)
    {
        switch (itemId)
        {
            case ItemID.SNAKEBOSS_SCALE: return "Zulrah's scales";
            case ItemID.DEATHRUNE: return "Death rune";
            case ItemID.BIG_BONES: return "Big bones";
            default: return null;
        }
    }

    private static Map<Integer, Long> counts(int itemId, long quantity)
    {
        return Collections.singletonMap(itemId, quantity);
    }

    /** A client whose tick and inventory the test drives. */
    private static net.runelite.api.Client client(int[] tick, Map<Integer, Long> held)
    {
        net.runelite.api.ItemContainer inventory = (net.runelite.api.ItemContainer) Proxy.newProxyInstance(
            net.runelite.api.ItemContainer.class.getClassLoader(), new Class<?>[] {net.runelite.api.ItemContainer.class},
            (proxy, method, args) ->
            {
                if ("getItems".equals(method.getName()))
                {
                    return held.entrySet().stream()
                        .map(e -> new net.runelite.api.Item(e.getKey(), e.getValue().intValue()))
                        .toArray(net.runelite.api.Item[]::new);
                }
                return method.getReturnType() == int.class ? 0 : null;
            });
        return (net.runelite.api.Client) Proxy.newProxyInstance(net.runelite.api.Client.class.getClassLoader(),
            new Class<?>[] {net.runelite.api.Client.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getTickCount": return tick[0];
                    case "getItemContainer": return inventory;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
    }

    private static Engine engine(GpManagerConfig config)
    {
        Map<Integer, String> names = new HashMap<>();
        names.put(ItemID.TOTS_CHARGED, "Trident of the seas (full)");
        names.put(ItemID.TOTS_UNCHARGED, "Trident of the seas");
        names.put(ItemID.DEATHRUNE, "Death rune");
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int unit = delta.getKey() == ItemID.DEATHRUNE ? 200 : 1_000_000;
                flows.add(new Flow(delta.getKey(), names.get(delta.getKey()), delta.getValue(), unit,
                    delta.getValue() * unit, PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }

    private static MenuOptionClicked click(int itemId)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return "Uncharge";
                    case "getTarget": return "Trident of the seas";
                    case "getType": return MenuAction.CC_OP;
                    case "getItemId": return itemId;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-08: clue scrolls, scroll boxes and impling jars went to Review. A treasure trail's scrolls,
 * boxes and caskets are claims on the casket's loot, held at zero like a coin pouch, so only the
 * casket's contents count, once it is opened.
 */
public class ClueClaimTest
{
    private static final int CLUE = 2722;
    private static final int NEXT_STEP = 2723;
    private static final int BOX = 24364;
    private static final int CASKET = 20544;
    private static final int PLATEBODY = 1127;
    private static final int COINS = 995;
    private static final int MYSTERY = 30000;
    private static final int EMPTY_JAR = 11260;
    private static final int ECLECTIC = 11248;
    private static final int POUCH = 26908;
    private static final int WATER_RUNE = 555;
    private static final Map<Integer, String> NAMES = new HashMap<>();

    static
    {
        NAMES.put(CLUE, "Clue scroll (hard)");
        NAMES.put(NEXT_STEP, "Clue scroll (hard)");
        NAMES.put(BOX, "Scroll box (hard)");
        NAMES.put(CASKET, "Reward casket (hard)");
        NAMES.put(PLATEBODY, "Rune platebody");
        NAMES.put(COINS, "Coins");
        NAMES.put(MYSTERY, "Mystery scroll");
        NAMES.put(EMPTY_JAR, "Impling jar");
        NAMES.put(ECLECTIC, "Eclectic impling jar");
        NAMES.put(POUCH, "Intricate pouch");
        NAMES.put(WATER_RUNE, "Water rune");
    }

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    };

    private final Map<Integer, Long> inventory = new HashMap<>();
    private final Engine engine = new Engine(ModelProbe.valuation(CONFIG, ClueClaimTest::composition,
        id -> id == PLATEBODY ? 38_000
            : id == ECLECTIC ? 20_000
            : id == EMPTY_JAR ? 290
            : id == WATER_RUNE ? 5
            : 0), new TransactionClassifier(), CONFIG);
    private long now = 1_000_000L;

    @Test
    public void namesMatchEveryTierAndNothingElse()
    {
        for (String name : new String[] {"Clue scroll (beginner)", "Clue scroll (master)", "Scroll box (elite)",
            "Reward casket (medium)", "Clue bottle (easy)", "Clue nest (hard)", "Clue geode (elite)",
            "Challenge scroll (hard)", "Puzzle box", "Light box",
            // Renamed with their tier in 2014 (OSRS Wiki); trail step items, worth nothing (owner 2026-10-16).
            "Puzzle box (hard)", "Puzzle box (master)", "Key (medium)", "Key (elite)"})
        {
            assertTrue(name, GameData.pattern("clue").matcher(name).matches());
        }
        for (String name : new String[] {"Casket", "Clue scroll", "Scroll box (hard) extra", "Bird nest",
            "Clue hunter garb", "Mystery box", "Key", "Puzzle box (easy)", "Loop half of key"})
        {
            assertFalse(name, GameData.pattern("clue").matcher(name).matches());
        }
    }

    @Test
    public void aWholeTrailBooksOnlyTheCasketsLoot()
    {
        engine.startCustom("Clues", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));

        change(BOX, 1L);
        change(BOX, -1L, CLUE, 1L);
        change(CLUE, -1L, NEXT_STEP, 1L);
        change(NEXT_STEP, -1L, CASKET, 1L);
        assertEquals("a scroll, a box or a casket is worth nothing yet", 0L, net());
        assertEquals(0, reviews());

        change(CASKET, -1L, PLATEBODY, 1L, COINS, 5_000L);
        assertEquals("the casket's loot counts once it is opened", 43_000L, net());
        assertEquals(0, reviews());
    }

    /** In game the reward window reports the casket first (Loot Tracker), which opens the clue path. */
    @Test
    public void aCasketOpenedThroughItsRewardWindowCountsItsLoot()
    {
        inventory.put(CASKET, 1L);
        engine.startCustom("Clues", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
        engine.beginCluePath("loot:Clue Scroll (Hard)", "Clue Scroll (Hard)");

        change(CASKET, -1L, PLATEBODY, 1L, COINS, 5_000L);
        assertEquals(43_000L, net());
        assertEquals(0, reviews());
    }

    /** Owner 2026-10-08: every impling jar, caught or looted, books without Review. */
    @Test
    public void catchingAndLootingAnImplingCountsWithoutReview()
    {
        inventory.put(EMPTY_JAR, 2L);
        engine.startCustom("Hunter", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));

        change(EMPTY_JAR, -1L, ECLECTIC, 1L);
        assertEquals("the caught impling is worth its jar less the empty one", 19_710L, net());

        change(ECLECTIC, -1L, PLATEBODY, 1L, EMPTY_JAR, 1L);
        assertEquals("its loot and the empty jar replace the full jar", 19_710L + 38_290L - 20_000L, net());

        // One jar in ten breaks: the loot alone replaces it.
        change(EMPTY_JAR, -1L, ECLECTIC, 1L);
        change(ECLECTIC, -1L, PLATEBODY, 1L);
        assertEquals(19_710L + 18_290L + 19_710L + 18_000L, net());
        assertEquals(0, reviews());
    }

    /** An untradeable that is no clue is worth its alch value (owner 2026-10-16), never a claim. */
    @Test
    public void anUntradeableThatIsNoClueIsWorthItsAlchPrice()
    {
        engine.startCustom("Clues", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
        change(MYSTERY, 1L);
        Flow flow = engine.getActiveSession().getTransactions().get(0).getFlows().get(0);
        assertEquals(PriceSource.HIGH_ALCHEMY, flow.getPriceSource());
    }

    /** The GOTR reward pouch: held at zero until opened, then its contents book once. */
    @Test
    public void theIntricatePouchIsAClaimUntilOpened()
    {
        engine.startCustom("GotR", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));

        change(POUCH, 1L);
        assertEquals("the pouch is worth nothing yet", 0L, net());
        assertEquals(0, reviews());

        change(POUCH, -1L, WATER_RUNE, 106L);
        assertEquals("opening it counts the runes once", 530L, net());
        assertEquals(0, reviews());
    }

    private void change(Object... idsAndDeltas)
    {
        for (int index = 0; index < idsAndDeltas.length; index += 2)
        {
            inventory.merge((Integer) idsAndDeltas[index], (Long) idsAndDeltas[index + 1], Long::sum);
        }
        inventory.values().removeIf(quantity -> quantity == 0L);
        now += 3_000L;
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 600L, null);
    }

    private long net()
    {
        return engine.getMetrics(now + 60_000L).net;
    }

    private int reviews()
    {
        int count = 0;
        for (Transaction transaction : engine.getActiveSession().getTransactions())
        {
            if (ReviewRules.needsOwnerDecision(transaction))
            {
                count++;
            }
        }
        return count;
    }

    private static ItemComposition composition(int id)
    {
        String name = NAMES.getOrDefault(id, "Item " + id);
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) -> {
                if ("getName".equals(method.getName())) return name;
                if ("getHaPrice".equals(method.getName())) return id == MYSTERY ? 50 : 0;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return false;
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }
}

