    @Test
    public void observedReclaimFeeAfterRestartBooksOnce()
    {
        Engine first = started(gear(1L, 0L, 150_000L, 0L));
        first.markPvmDeath(20, gear(1L, 0L, 150_000L, 0L).quantities);
        first.markDirty();
        assertNotNull(settle(first, ContainerSnapshot.empty(), 1_600L));

        Engine restarted = new Engine(valuator, new TransactionClassifier(), CONFIG);
        restarted.restore(roundTrip(first.savedState()), 10_000L);
        restarted.resume(11_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        restarted.setBaseline(gear(0L, 0L, 150_000L, 0L));
        assertTrue(restarted.noteReclaimIntent(
            BossRetrievalCatalogue.serviceFor("Talk-to", "Priestess Zul-Gwenwynig"), 40));
        restarted.markDirty();
        Transaction fee = settle(restarted, gear(1L, 0L, 50_000L, 0L), 12_000L);

        assertNotNull(fee);
        assertEquals(TransactionType.CONSUMPTION, fee.getType());
        assertTrue(fee.isCounted());
        assertEquals(-100_000L, fee.getNet());
        assertEquals(100_000L, restarted.getMetrics(20_000L).costs);
        assertEquals(0L, restarted.getMetrics(20_000L).revenue);

        // Replaying the same settled state cannot book a second fee.
        restarted.markDirty();
        assertNull(settle(restarted, gear(1L, 0L, 50_000L, 0L), 20_000L));
        assertEquals(100_000L, restarted.getMetrics(30_000L).costs);
    }

    private static SavedState roundTrip(SavedState state)
    {
        com.google.gson.Gson gson = new com.google.gson.Gson();
        return gson.fromJson(gson.toJson(state), SavedState.class);
    }

    private Engine started(ContainerSnapshot baseline)
    {
        return started(baseline, CONFIG);
    }

    private Engine started(ContainerSnapshot baseline, GpManagerConfig config)
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        engine.setBaseline(baseline);
        return engine;
    }

    private static ContainerSnapshot gear(long whip, long torture, long coins, long sharks)
    {
        Map<Integer, Long> values = new HashMap<>();
        if (whip > 0L)
        {
            values.put(WHIP, whip);
        }
        if (torture > 0L)
        {
            values.put(TORTURE, torture);
        }
        if (coins > 0L)
        {
            values.put(COINS, coins);
        }
        if (sharks > 0L)
        {
            values.put(SHARK, sharks);
        }
        return new ContainerSnapshot(values);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        return engine.processIfDirty(snapshot, firstTick + 1_200L, null);
    }

    private static Transaction sw(Engine engine, String note)
    {
        for (Transaction transaction : engine.getActiveSession().getTransactions())
        {
            if (note.equals(transaction.getNote()))
            {
                return transaction;
            }
        }
        return null;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Combining or decanting potions keeps every dose: neutral, never a Review row (owner 1.2). */
public class DecantNeutralTest
{
    private static final int PRAYER_4 = 2434;
    private static final int PRAYER_3 = 139;
    private static final int PRAYER_2 = 141;
    private static final int PRAYER_1 = 143;
    private static final int VIAL = 229;
    private static final Map<Integer, String> NAMES = Map.of(PRAYER_4, "Prayer potion(4)", PRAYER_3, "Prayer potion(3)",
        PRAYER_2, "Prayer potion(2)", PRAYER_1, "Prayer potion(1)", VIAL, "Vial");
    private static final Map<Integer, Integer> PRICES = Map.of(PRAYER_4, 9_800, PRAYER_3, 7_400, PRAYER_2, 4_900,
        PRAYER_1, 2_500, VIAL, 3);

    private static Engine engine(boolean auditRows)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 2;
            }

            @Override
            public boolean keepTransferAuditRows()
            {
                return auditRows;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, NAMES.get(id), quantity, PRICES.get(id),
                quantity * PRICES.get(id))));
            return flows;
        }, new TransactionClassifier(), config);
    }

    private static Engine settle(boolean auditRows, Map<Integer, Long> before, Map<Integer, Long> after)
    {
        Engine engine = engine(auditRows);
        engine.ensureSession(1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    @Test
    public void combiningByHandBooksNothingAndNeedsNoReview()
    {
        Engine engine = settle(false, Map.of(PRAYER_3, 1L, PRAYER_1, 1L), Map.of(PRAYER_4, 1L, VIAL, 1L));
        assertEquals("no money moved", 0L, engine.getMetrics(1_010_000L).net);
        assertTrue("no Review row: " + engine.getActiveSession().getTransactions(),
            engine.getActiveSession().getTransactions().isEmpty());
    }

    @Test
    public void aDecantIsANeutralTransferInTheAudit()
    {
        Engine engine = settle(true, Map.of(PRAYER_2, 2L), Map.of(PRAYER_4, 1L));
        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        Transaction decant = rows.get(0);
        assertEquals(TransactionType.TRANSFER, decant.autoType());
        assertEquals("Decanted", decant.getNote());
        assertEquals(false, decant.isCounted());
        assertEquals(0L, engine.getMetrics(1_010_000L).net);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Taking an item apart is neutral; a crystal tool's 120 shards are the only cost (owner 1.2). */
public class DismantleNeutralTest
{
    private static final Map<Integer, String> NAMES = Map.of(ItemID.CRYSTAL_HARPOON, "Crystal harpoon",
        ItemID.DRAGON_HARPOON, "Dragon harpoon", ItemID.PRIF_TOOL_SEED, "Crystal tool seed",
        ItemID.PRIF_CRYSTAL_SHARD, "Crystal shard", ItemID.AGS, "Armadyl godsword",
        ItemID.GODWARS_GODSWORD_BLADE1_2_3, "Godsword blade", ItemID.GODWARS_GODSWORD_HILT_ARMADYL, "Armadyl hilt",
        ItemID.WILD_CAVE_BRACELET_UNCHARGED, "Bracelet of ethereum (uncharged)",
        ItemID.WILD_CAVE_SHARD, "Revenant ether");
    private static final Map<Integer, Integer> PRICES = Map.of(ItemID.CRYSTAL_HARPOON, 0,
        ItemID.DRAGON_HARPOON, 3_000_000, ItemID.PRIF_TOOL_SEED, 1_000_000, ItemID.PRIF_CRYSTAL_SHARD, 2_000,
        ItemID.AGS, 12_000_000, ItemID.GODWARS_GODSWORD_BLADE1_2_3, 1_000_000, ItemID.GODWARS_GODSWORD_HILT_ARMADYL, 10_500_000,
        ItemID.WILD_CAVE_BRACELET_UNCHARGED, 40_000, ItemID.WILD_CAVE_SHARD, 250);

    private static Engine settle(int clicked, Map<Integer, Long> before, Map<Integer, Long> after)
    {
        return settle(clicked, before, after, new GpManagerConfig()
        {
        });
    }

    private static Engine settle(int clicked, Map<Integer, Long> before, Map<Integer, Long> after, GpManagerConfig config)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, NAMES.get(id), quantity, PRICES.get(id),
                quantity * PRICES.get(id))));
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        engine.markDirty();
        if (clicked > 0)
        {
            engine.dismantle(clicked);
        }
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    private static final Map<Integer, Long> HARPOON = Map.of(ItemID.CRYSTAL_HARPOON, 1L);
    private static final Map<Integer, Long> PARTS = Map.of(ItemID.DRAGON_HARPOON, 1L, ItemID.PRIF_TOOL_SEED, 1L);

    @Test
    public void revertingACrystalToolCostsOnlyItsShards()
    {
        Engine engine = settle(ItemID.CRYSTAL_HARPOON, HARPOON, PARTS);
        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        Transaction shards = rows.get(0);
        assertEquals(TransactionType.CONSUMPTION, shards.autoType());
        assertEquals("Dismantled Crystal harpoon", shards.getNote());
        assertEquals(ItemID.PRIF_CRYSTAL_SHARD, shards.getFlows().get(0).itemId);
        assertEquals(-120L, shards.getFlows().get(0).quantityDelta);
        assertEquals(-240_000L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void withoutTheClickTheSameChangeStillNeedsReview()
    {
        Engine engine = settle(-1, HARPOON, PARTS);
        assertTrue(engine.getActiveSession().getTransactions().stream().anyMatch(row -> row.autoType() == TransactionType.UNCERTAIN));
    }

    @Test
    public void dismantlingAGodswordBooksNothing()
    {
        Engine engine = settle(ItemID.AGS, Map.of(ItemID.AGS, 1L), Map.of(ItemID.GODWARS_GODSWORD_BLADE1_2_3, 1L, ItemID.GODWARS_GODSWORD_HILT_ARMADYL, 1L));
        assertTrue(engine.getActiveSession().getTransactions().toString(),
            engine.getActiveSession().getTransactions().isEmpty());
        assertEquals(0L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void dismantlingABraceletOfEthereumIsNotNeutral()
    {
        // The parts (250 ether) are worth more than the item: the neutral parts rule would bury
        // the gain, so it settles like the same change without the click (Muse review 2026-10-12).
        Engine engine = settle(ItemID.WILD_CAVE_BRACELET_UNCHARGED,
            Map.of(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L), Map.of(ItemID.WILD_CAVE_SHARD, 250L));
        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertEquals(TransactionType.UNCERTAIN, rows.get(0).autoType());
        assertFalse(rows.get(0).isCounted());
        assertTrue(ReviewRules.needsOwnerDecision(rows.get(0)));
        assertEquals(0L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void aCountedUncertainSettingBooksTheBraceletConversion()
    {
        Engine engine = settle(ItemID.WILD_CAVE_BRACELET_UNCHARGED,
            Map.of(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L), Map.of(ItemID.WILD_CAVE_SHARD, 250L),
            new GpManagerConfig()
            {
                @Override public boolean countUncertainMixedChanges()
                {
                    return true;
                }
            });
        assertEquals(250L * 250L - 40_000L, engine.getMetrics(1_010_000L).net);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
