import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Owner 1.3.4: a dose variant RuneLite cannot quote is priced from its family's full quote at the
 * same rate per dose (the GP-Per-Hour fractional model), so a burning-amulet teleport books a
 * fifth of the amulet instead of the full price or an unknown row.
 */
public class DoseFamilyValueTest
{
    private static final int BURNING_5 = 21166;
    private static final int BURNING_4 = 21169;
    private static final int BURNING_3 = 21171;
    private static final int BURNING_2 = 21173;
    private static final int BURNING_1 = 21175;

    private static final Map<Integer, String> NAMES = Map.of(
        BURNING_5, "Burning amulet(5)",
        BURNING_4, "Burning amulet(4)",
        BURNING_3, "Burning amulet(3)",
        BURNING_2, "Burning amulet(2)",
        BURNING_1, "Burning amulet(1)");

    @Test
    public void aPartialDoseIsPricedFromItsFamilyFullQuote()
    {
        Valuation service = service(new GpManagerConfig() { }, Map.of(BURNING_5, 2_231));

        assertEquals("the full amulet keeps its own quote", 2_231, one(service, BURNING_5).unitPrice);
        assertEquals(1_784, one(service, BURNING_4).unitPrice);
        assertEquals(1_338, one(service, BURNING_3).unitPrice);
        assertEquals(892, one(service, BURNING_2).unitPrice);
        assertEquals(446, one(service, BURNING_1).unitPrice);
        assertEquals(PriceSource.GRAND_EXCHANGE, one(service, BURNING_4).getPriceSource());

        Map<Integer, Long> swap = new HashMap<>();
        swap.put(BURNING_3, -1L);
        swap.put(BURNING_2, 1L);
        long net = 0L;
        for (Flow flow : service.value(swap, 1_000L)) net += flow.valueDelta;
        assertEquals("one teleport is a fifth of the amulet", -446L, net);
    }

    @Test
    public void aManualOverrideAnywhereInTheFamilyIsAuthoritative()
    {
        GpManagerConfig full = new GpManagerConfig()
        {
            @Override
            public String manualPriceOverrides()
            {
                return "21166=2500";
            }
        };
        Valuation fromFull = service(full, Map.of());
        assertEquals(2_000, one(fromFull, BURNING_4).unitPrice);
        assertEquals(PriceSource.MANUAL_OVERRIDE, one(fromFull, BURNING_4).getPriceSource());

        GpManagerConfig oneDose = new GpManagerConfig()
        {
            @Override
            public String manualPriceOverrides()
            {
                return "21175=500";
            }
        };
        Valuation fromOne = service(oneDose, Map.of(BURNING_5, 2_231));
        assertEquals("an override outranks the family quote", 2_000,
            one(fromOne, BURNING_4).unitPrice);
        assertEquals(PriceSource.MANUAL_OVERRIDE, one(fromOne, BURNING_4).getPriceSource());
    }

    @Test
    public void withoutAnyFamilyQuoteNothingIsInvented()
    {
        Valuation service = service(new GpManagerConfig() { }, Map.of());
        assertEquals(0, one(service, BURNING_4).unitPrice);
        assertEquals(PriceSource.UNPRICED, one(service, BURNING_4).getPriceSource());
        assertEquals(PriceSource.UNPRICED, one(service, 999_999).getPriceSource());
    }

    static Valuation service(GpManagerConfig config, Map<Integer, Integer> prices)
    {
        return ModelProbe.valuation(config,
            id -> composition(NAMES.getOrDefault(id, "Item " + id)),
            id -> prices.getOrDefault(id, 0));
    }

    private static ItemComposition composition(String name)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) ->
            {
                if ("getName".equals(method.getName())) return name;
                // Potions and amulets trade on the Grand Exchange.
                if (method.getReturnType() == boolean.class) return "isTradeable".equals(method.getName());
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
    }

    private static Flow one(Valuation service, int itemId)
    {
        List<Flow> flows = service.value(Map.of(itemId, 1L), 1_000L);
        assertNotNull(flows);
        return flows.stream().filter(flow -> flow.itemId == itemId).findFirst().orElseThrow();
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.4: a confirmed drop owns its item when a harvest lands in the same change (the live
 * calquat shape: Empty plant pot x-11 with a Calquat fruit gain). The drop books as its own
 * Dropped row and the sibling gain separately, with no Review; guard shapes cancel the split.
 */
public class DropMixedSettleTest
{
    private static final int CALQUAT_FRUIT = 5980;
    private static final int EMPTY_PLANT_POT = 5350;
    private static final int SHARK = 385;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) ->
            flows.add(new Flow(id, name(id), quantity, unit(id), quantity * unit(id))));
        return flows;
    };

    private static String name(int id)
    {
        switch (id)
        {
            case CALQUAT_FRUIT: return "Calquat fruit";
            case EMPTY_PLANT_POT: return "Empty plant pot";
            case SHARK: return "Shark";
            default: return "Item " + id;
        }
    }

    private static int unit(int id)
    {
        switch (id)
        {
            case CALQUAT_FRUIT: return 600;
            case SHARK: return 1_000;
            default: return 1;
        }
    }

    @Test
    public void aDropKeepsItsOwnItemWhenAHarvestLands()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L)), 1_600L);

        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 2, rows.size());
        Transaction drop = rows.get(0);
        assertEquals(TransactionType.CONSUMPTION, drop.getType());
        assertEquals("Dropped", drop.getNote());
        assertTrue(drop.isCounted());
        assertEquals(11L, drop.quantity(EMPTY_PLANT_POT, false));
        Transaction harvest = rows.get(1);
        assertEquals(TransactionType.GAIN, harvest.getType());
        assertEquals(1L, harvest.quantity(CALQUAT_FRUIT, true));
        assertEquals("no Review", 0, engine.getReviewRows(10_000L).size());
        Metrics metrics = engine.getMetrics(10_000L);
        assertEquals(11L, metrics.costs);
        assertEquals(600L, metrics.revenue);
    }

    @Test
    public void pickingPartOfTheSplitDropBackUpShrinksIt()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L)), 1_600L);

        engine.markDirty();
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L, EMPTY_PLANT_POT, 5L)), 4_000L);

        assertEquals("the pickup books no new row", 2, engine.getActiveSession().getTransactions().size());
        Metrics metrics = engine.getMetrics(10_000L);
        assertEquals("6 pots stay on the ground", 6L, metrics.costs);
        assertEquals(600L, metrics.revenue);
    }

    @Test
    public void aSecondLossCancelsTheSplit()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L, SHARK, 2L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L, SHARK, 1L)), 1_600L);

        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertFalse("Dropped", "Dropped".equals(rows.get(0).getNote()));
        assertEquals(TransactionType.UNCERTAIN, rows.get(0).getType());
        assertEquals(1, engine.getReviewRows(10_000L).size());
    }

    @Test
    public void aConsumeIntentCancelsTheSplit()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L, SHARK, 2L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        engine.noteConsume(SHARK, 6, false);
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L, SHARK, 1L)), 1_600L);

        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertFalse("Dropped", "Dropped".equals(rows.get(0).getNote()));
        assertEquals(TransactionType.CONSUMPTION, rows.get(0).getType());
    }

    @Test
    public void aPkLootContextCancelsTheSplit()
    {
        Engine engine = engine(Map.of(EMPTY_PLANT_POT, 11L));
        engine.noteDrop(EMPTY_PLANT_POT, 6);
        engine.markContext(Context.PK_LOOT, 6, "PKing");
        settle(engine, held(Map.of(CALQUAT_FRUIT, 1L)), 1_600L);

        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertFalse("Dropped", "Dropped".equals(rows.get(0).getNote()));
    }

    private Engine engine(Map<Integer, Long> baseline)
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(baseline)));
        return engine;
    }

    private static ContainerSnapshot held(Map<Integer, Long> quantities)
    {
        return new ContainerSnapshot(new HashMap<>(quantities));
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        Transaction tx = engine.processIfDirty(snapshot, firstTick + 1_200L, null);
        assertNotNull(tx);
        return tx;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Owner 1.3.3: a drop picked back up shrinks the Dropped row instead of adding a matching gain. */
public class DropPickupTest
{
    private static final int BOLTS = 9140;
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Iron bolts", quantity, 10, quantity * 10)));
        return flows;
    };

    private Engine dropped(long bolts)
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(Collections.singletonMap(BOLTS, 3L)));
        engine.noteDrop(BOLTS, 6);
        Transaction drop = settle(engine, snapshot(3L - bolts), 1_600L);
        assertEquals("Dropped", drop.getNote());
        return engine;
    }

    @Test
    public void pickingAllOfADropBackUpLeavesNeitherRow()
    {
        Engine engine = dropped(3L);
        assertEquals(-30L, engine.getMetrics(3_000L).net);
        settle(engine, snapshot(3L), 4_000L);
        assertEquals("Net is back where it started", 0L, engine.getMetrics(6_000L).net);
        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals("only the Dropped row is kept, excluded", 1, rows.size());
        assertEquals(Correction.IGNORE, rows.get(0).getCorrection());
        assertFalse(rows.get(0).isCounted());
    }

    @Test
    public void pickingPartOfADropBackUpShrinksIt()
    {
        Engine engine = dropped(3L);
        settle(engine, snapshot(1L), 4_000L);
        Transaction drop = engine.getActiveSession().getTransactions().get(0);
        assertTrue(drop.isCounted());
        assertEquals("2 bolts stay on the ground", -20L, engine.getMetrics(6_000L).net);
        assertEquals(1, engine.getActiveSession().getTransactions().size());
    }

    @Test
    public void pickingUpMoreThanWasDroppedBooksOnlyTheExtra()
    {
        Engine engine = dropped(1L);
        Transaction extra = settle(engine, snapshot(5L), 4_000L);
        assertEquals(TransactionType.GAIN, extra.getType());
        assertEquals("1 cancels the drop, 2 are new", 20L, extra.getRevenue());
        assertEquals(20L, engine.getMetrics(6_000L).net);
    }

    @Test
    public void pickingUpFiredBoltsShrinksTheShot()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(100L));
        Transaction fired = settle(engine, snapshot(60L), 1_600L);
        assertEquals(ActionKind.FIRE, fired.getActionKind());
        assertEquals(400L, engine.getMetrics(3_000L).costs);
        engine.markDirty();
        settle(engine, snapshot(90L), 4_000L);
        Metrics metrics = engine.getMetrics(6_000L);
        assertEquals("never income", 0L, metrics.revenue);
        assertEquals("10 bolts stayed on the ground", 100L, metrics.costs);
    }

    private static final int DART = 807;
    private static final int SCALES = 12934;

    /** A blowpipe shot estimated at one dart and one scale, 10 gp each. */
    private Engine blowpipeShot()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(ContainerSnapshot.empty());
        Transaction shot = engine.bookEstimatedCharge("pipe", "Toxic blowpipe", ActionKind.CAST,
            Arrays.asList(new Flow(DART, "Iron dart", -1L, 10, -10L),
                new Flow(SCALES, "Zulrah's scales", -1L, 10, -10L)), 1_100L);
        assertEquals(20L, shot.getCosts());
        return engine;
    }

    @Test
    public void pickingUpABlowpipeDartKeepsTheShotsScaleCost()
    {
        Engine engine = blowpipeShot();
        engine.markDirty();
        settle(engine, new ContainerSnapshot(Collections.singletonMap(DART, 1L)), 2_000L);
        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals("no gain row for the dart", 1, rows.size());
        assertTrue(rows.get(0).isCounted());
        assertEquals(0L, rows.get(0).quantity(DART, false));
        Metrics metrics = engine.getMetrics(4_000L);
        assertEquals(0L, metrics.revenue);
        assertEquals("the scale is still spent", 10L, metrics.costs);
    }

    @Test
    public void aCheckAfterADartPickupNeverCountsTheDartAgain()
    {
        Engine engine = blowpipeShot();
        engine.markDirty();
        settle(engine, new ContainerSnapshot(Collections.singletonMap(DART, 1L)), 2_000L);
        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.BLOWPIPE,
            Arrays.asList(new ChargeDelta.ComponentDelta(DART, -1L),
                new ChargeDelta.ComponentDelta(SCALES, -1L)), ChargeDelta.CheckResult.SPEND);
        engine.bookChargeSpend(delta, "Toxic blowpipe",
            Arrays.asList(new Flow(DART, "Iron dart", -1L, 10, -10L),
                new Flow(SCALES, "Zulrah's scales", -1L, 10, -10L)), 5_000L, "pipe");
        assertEquals("measured 20 less the 10 picked up", 10L, engine.getMetrics(6_000L).costs);
    }

    @Test
    public void aDartTheCheckAlreadyTookBackIsAnOrdinaryGain()
    {
        Engine engine = blowpipeShot();
        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.BLOWPIPE,
            Collections.singletonList(new ChargeDelta.ComponentDelta(SCALES, -1L)), ChargeDelta.CheckResult.SPEND);
        engine.bookChargeSpend(delta, "Toxic blowpipe",
            Collections.singletonList(new Flow(SCALES, "Zulrah's scales", -1L, 10, -10L)), 1_500L, "pipe");
        engine.clearPendingEstimates("pipe", Collections.singleton(DART));
        Transaction shot = engine.getActiveSession().getTransactions().get(0);
        assertEquals("the Check found no dart used", 0L, shot.quantity(DART, false));

        engine.markDirty();
        Transaction gain = settle(engine, new ContainerSnapshot(Collections.singletonMap(DART, 1L)), 2_000L);
        assertEquals(TransactionType.GAIN, gain.getType());
        assertEquals(10L, gain.getRevenue());
        assertEquals(10L, engine.getMetrics(4_000L).costs);
    }

    @Test
    public void scalesPickedUpAreAnOrdinaryGain()
    {
        Engine engine = blowpipeShot();
        engine.markDirty();
        Transaction gain = settle(engine, new ContainerSnapshot(Collections.singletonMap(SCALES, 1L)), 2_000L);
        assertEquals(TransactionType.GAIN, gain.getType());
        assertEquals(20L, engine.getMetrics(4_000L).costs);
    }

    private static ContainerSnapshot snapshot(long bolts)
    {
        return new ContainerSnapshot(Collections.singletonMap(BOLTS, bolts));
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        assertNull(engine.processIfDirty(snapshot, firstTick, null));
        assertNull(engine.processIfDirty(snapshot, firstTick + 600L, null));
        Transaction tx = engine.processIfDirty(snapshot, firstTick + 1_200L, null);
        assertNotNull(tx);
        return tx;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.3: setting up and picking up a dwarf multicannon is neutral; only the cannonballs it
 * fired count. Balls it did not fire come back on pick-up and shrink the load. Owner 1.3.4: the
 * balls it takes are Supplies on the ledger, and a change mixing a ball loss with a gain stays
 * Review rather than being stamped.
 */
public class DwarfCannonTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }

        @Override
        public boolean keepTransferAuditRows()
        {
            return true;
        }
    };

    private static final Map<Integer, String> NAMES = Map.of(
        ItemID.TWPART1, "Cannon base", ItemID.TWPART2, "Cannon stand",
        ItemID.TWPART3, "Cannon barrels", ItemID.TWPART4, "Cannon furnace",
        ItemID.MCANNONBALL, "Cannonball", ItemID.GRANITE_CANNONBALL, "Granite cannonball",
        ItemID.BRONZE_CANNONBALL, "Bronze cannonball",
        ItemID.DRAGON_CHAINSHOT_CANNONBALL, "Dragon chainshot cannonball",
        ItemID.COINS, "Coins");

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> {
            int unit = id == ItemID.MCANNONBALL ? 200
                : id == ItemID.GRANITE_CANNONBALL ? 350
                : id == ItemID.BRONZE_CANNONBALL ? 30
                : id == ItemID.DRAGON_CHAINSHOT_CANNONBALL ? 300
                : id == ItemID.COINS ? 1 : 150_000;
            flows.add(new Flow(id, NAMES.get(id), quantity, unit, quantity * unit));
        });
        return flows;
    };

    @Test
    public void onlyTheFiredBallsCount()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 100L));

        engine.moveCannon();
        settle(engine, snapshot(false, 100L), 1_600L);
        assertEquals("setting it up is neutral", 0L, engine.getMetrics(5_000L).net);

        engine.loadCannon(6);
        Transaction load = settle(engine, snapshot(false, 70L), 6_000L);
        assertEquals("Loaded into the cannon", load.getNote());
        assertEquals(-6_000L, engine.getMetrics(10_000L).net);
        assertEquals("the balls are a supply, not an item loss", ActionKind.SUPPLIES,
            load.getActionKind());
        assertEquals(CostKind.SUPPLIES, CostKind.of(load, load.getFlows().get(0)));

        engine.moveCannon();
        settle(engine, snapshot(true, 80L), 12_000L);
        assertEquals("20 balls were fired; parts and 10 balls came back", -4_000L, engine.getMetrics(20_000L).net);
        assertEquals(0, engine.getReviewRows(20_000L).size());
    }

    @Test
    public void aBareCannonballLossIsSuppliesToo()
    {
        // The live shape: the load settled with no drop intent attached, so it booked as a plain
        // consumption; it is still the cannon's balls (owner 1.3.4).
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 100L));

        Transaction loss = settle(engine, snapshot(true, 55L), 2_000L);
        assertEquals("", loss.getNote());
        assertEquals(ActionKind.SUPPLIES, loss.getActionKind());
        assertEquals(CostKind.SUPPLIES, CostKind.of(loss, loss.getFlows().get(0)));
    }

    @Test
    public void graniteCannonballsAreSupplies()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(held(ItemID.GRANITE_CANNONBALL, 30L));

        Transaction loss = settle(engine, held(ItemID.GRANITE_CANNONBALL, 10L), 2_000L);
        assertEquals(ActionKind.SUPPLIES, loss.getActionKind());
        assertEquals(CostKind.SUPPLIES, CostKind.of(loss, loss.getFlows().get(0)));
    }

    @Test
    public void aChangeMixingBallsWithAnotherGainIsNotStamped()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(held(ItemID.MCANNONBALL, 100L, ItemID.COINS, 10L));

        Transaction mixed = settle(
            engine, held(ItemID.MCANNONBALL, 95L, ItemID.COINS, 20L), 2_000L);
        assertEquals(TransactionType.UNCERTAIN, mixed.getType());
        assertNull(mixed.getActionKind());
        assertEquals(1, engine.getReviewRows(9_000L).size());
    }

    @Test
    public void aSetUpAutoLoadAndUseLoadAreArmedAndOnlyFiredBallsBook()
    {
        // The live shape (owner 2026-10-13): Set-up auto-loads the balls it finds with the parts
        // and using a ball on the cannon loads too. Both must book on ground, so an Empty return
        // shrinks them instead of booking a gain, and only what never comes back books.
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(ContainerSnapshot.empty());
        settle(engine, held(ItemID.MCANNONBALL, 90L), 2_000L);
        assertEquals(18_000L, engine.getMetrics(10_000L).net);

        engine.moveCannon();
        engine.loadCannon(6);
        Transaction setup = settle(engine, held(ItemID.MCANNONBALL, 45L), 20_000L);
        assertEquals("Loaded into the cannon", setup.getNote());
        assertTrue(setup.isOnGround());
        assertEquals("the 45 it took book and can come back", 18_000L - 9_000L,
            engine.getMetrics(50_000L).net);

        engine.loadCannon(6);
        settle(engine, held(ItemID.MCANNONBALL, 25L), 60_000L);
        assertEquals(9_000L - 4_000L, engine.getMetrics(90_000L).net);

        settle(engine, held(ItemID.MCANNONBALL, 60L), 100_000L);
        assertEquals("the 35 returned shrink the loads; no gain books", 1L,
            engine.getActiveSession().getTransactions().stream()
                .filter(row -> row.isCounted() && row.getType() == TransactionType.GAIN)
                .count());
        assertEquals("30 balls stayed out: 65 loaded, 35 back", 18_000L - 30L * 200L,
            engine.getMetrics(150_000L).net);
        assertEquals(0, engine.getReviewRows(150_000L).size());

        wait(engine, held(ItemID.MCANNONBALL, 60L), 2_150L, 200_000L);
        assertEquals("nothing more books after the windows", 18_000L - 30L * 200L,
            engine.getMetrics(10_000_000L).net);
        assertEquals(1L,
            engine.getActiveSession().getTransactions().stream()
                .filter(row -> row.isCounted() && row.getType() == TransactionType.GAIN)
                .count());
    }

    @Test
    public void aSlowSetUpKeepsTheFurnaceNeutralAndArmsItsAutoLoad()
    {
        // The live shape (owner 2026-10-13, second session): the last part settles about 15
        // ticks after the click together with the auto-load, right at the old 15-tick custody
        // edge. The furnace must stay neutral and the 45 balls must still be a load.
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 90L));

        engine.moveCannon();
        engine.loadCannon(40);
        wait(engine, snapshot(true, 90L), 20L, 2_000L);
        Transaction load = settle(engine, snapshot(false, 45L), 20_000L);
        assertEquals("Loaded into the cannon", load.getNote());
        assertTrue(load.isOnGround());
        assertEquals("parts are neutral; only the loaded 45 book", -(45L * 200L),
            engine.getMetrics(90_000L).net);

        settle(engine, snapshot(false, 80L), 100_000L);
        assertEquals("the return shrinks the load", -(10L * 200L), engine.getMetrics(150_000L).net);
        assertEquals(0, engine.getReviewRows(150_000L).size());
    }

    @Test
    public void aLoadRightAfterALoginPrimeStillBooksAsALoad()
    {
        // The login priming clears the click intent; the parts custody must carry the load
        // evidence through it (owner live 2026-10-13, second session: the first set-up's
        // auto-load booked a full loss because the prime wiped its intent).
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(true, 90L));

        engine.moveCannon();
        engine.loadCannon(40);
        engine.resetTracking(true);
        engine.setBaseline(snapshot(true, 90L));
        engine.markDirty();

        Transaction load = settle(engine, snapshot(false, 45L), 20_000L);
        assertEquals("Loaded into the cannon", load.getNote());
        assertEquals(-(45L * 200L), engine.getMetrics(50_000L).net);

        settle(engine, snapshot(false, 80L), 60_000L);
        assertEquals("the return shrinks the load, never a gain", -(10L * 200L),
            engine.getMetrics(90_000L).net);
        assertEquals(0L, engine.getActiveSession().getTransactions().stream()
            .filter(row -> row.isCounted() && row.getType() == TransactionType.GAIN).count());
    }

    @Test
    public void shipCannonballTiersAreSuppliesToo()
    {
        // Sailing's plain tiers, chainshot and incendiary are the same cannon economy: the balls
        // leaving the pack for a ship cannon read as Supplies like the dwarf load (owner 1.3.4
        // ship sweep).
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(held(ItemID.BRONZE_CANNONBALL, 40L, ItemID.DRAGON_CHAINSHOT_CANNONBALL, 5L));

        Transaction loss = settle(engine,
            held(ItemID.BRONZE_CANNONBALL, 25L, ItemID.DRAGON_CHAINSHOT_CANNONBALL, 2L), 2_000L);
        assertEquals(ActionKind.SUPPLIES, loss.getActionKind());
        assertEquals(CostKind.SUPPLIES, CostKind.of(loss, loss.getFlows().get(0)));
        assertEquals(-(15L * 30L) - (3L * 300L), engine.getMetrics(5_000L).net);
    }

    private static ContainerSnapshot snapshot(boolean parts, long balls)
    {
        Map<Integer, Long> held = new HashMap<>();
        if (parts)
        {
            held.put(ItemID.TWPART1, 1L);
            held.put(ItemID.TWPART2, 1L);
            held.put(ItemID.TWPART3, 1L);
            held.put(ItemID.TWPART4, 1L);
        }
        held.put(ItemID.MCANNONBALL, balls);
        return new ContainerSnapshot(held);
    }

    private static ContainerSnapshot held(Object... idsAndQuantities)
    {
        Map<Integer, Long> held = new HashMap<>();
        for (int index = 0; index < idsAndQuantities.length; index += 2)
        {
            held.merge((Integer) idsAndQuantities[index], (Long) idsAndQuantities[index + 1],
                Long::sum);
        }
        return new ContainerSnapshot(held);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        Transaction row = null;
        for (long t = firstTick; row == null && t < firstTick + 6_000L; t += 600L) row = engine.processIfDirty(snapshot, t, null);
        assertNotNull(row);
        return row;
    }

    private static void wait(Engine engine, ContainerSnapshot snapshot, long ticks, long firstTick)
    {
        long now = firstTick;
        for (long tick = 0; tick < ticks; tick++) engine.processIfDirty(snapshot, now += 600L, null);
    }
}

package com.gpmanager;


/** Test-side reads of engine state; moved out of production to keep the plugin small. */
public final class EngineProbe
{
    private EngineProbe()
    {
    }

    private static BasisPool pool(Engine engine, int itemId) {
        synchronized (engine.trackedBasis) {
            return engine.trackedBasis.pools.get(itemId);
        }
    }

    public static long availableQty(Engine engine, int itemId) {
        BasisPool pool = pool(engine, itemId);
        return pool == null ? 0L : pool.availableQty;
    }

    public static long availableBasisGp(Engine engine, int itemId) {
        BasisPool pool = pool(engine, itemId);
        return pool == null ? 0L : pool.availableBasisGp;
    }

    /** Known coverage held out by the item's open SELL custody records. */
    public static long reservedQty(Engine engine, int itemId) {
        long total = 0L;
        for (GeOffer record : engine.geCustody.records()) {
            if (record.itemId == itemId && record.getSide() == GeOffer.Side.SELL) total += record.reservedQty();
        }
        return total;
    }

    public static long reservedBasisGp(Engine engine, int itemId) {
        long total = 0L;
        for (GeOffer record : engine.geCustody.records()) {
            if (record.itemId == itemId && record.getSide() == GeOffer.Side.SELL) total += record.reservedBasis();
        }
        return total;
    }

    /** Exact known coverage for one canonical item. */
    public static long knownCoverageQty(Engine engine, int itemId) {
        return availableQty(engine, itemId) + reservedQty(engine, itemId);
    }

    /** Exact known coverage basis for one canonical item. */
    public static long knownCoverageBasisGp(Engine engine, int itemId) {
        return availableBasisGp(engine, itemId) + reservedBasisGp(engine, itemId);
    }

    public static boolean isBaselinePriming(Engine engine) {
        synchronized (engine) {
            return engine.baselinePriming;
        }
    }

    public static boolean isAwaitingDeathReclaim(Engine engine)
    {
        synchronized (engine)
        {
            return engine.deathReclaim.isAwaitingReclaim();
        }
    }

    /** The cash retained internally pending exact attribution. */
    public static long pendingSettlementCash(GeCustodyLedger ledger)
    {
        synchronized (ledger)
        {
            return ledger.pendingSettlementCashGp;
        }
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
