import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The bracelet of ethereum: revenant ether loads as a committed Supplies spend (an uncharge
 * destroys the stored ether), the charged bracelet prices from its uncharged form, and its
 * dismantle is not the neutral parts rule (the ether is worth more than the item) (OSRS Wiki,
 * Muse review, owner 2026-10-12).
 */
public class EthereumChargeTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final String BRACELET = "149:0:9764864:21816:ETHEREUM";
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override public int stabilizationTicks() { return 2; }
        @Override public boolean keepTransferAuditRows() { return true; }
    };

    @Test
    public void theChargedBraceletPricesFromItsUnchargedQuote()
    {
        // RuneLite's ItemMapping carries no bracelet entry; the charged form prices from the
        // uncharged form's live quote (Muse review 2026-10-12).
        Valuation valuation = ModelProbe.valuation(new GpManagerConfig() { }, EthereumChargeTest::composition,
            id -> id == ItemID.WILD_CAVE_BRACELET_UNCHARGED ? 40_000 : 0);
        Flow bracelet = valuation.valueComponent(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L, 0L);
        assertEquals(40_000, bracelet.unitPrice);
        assertSame(PriceSource.GRAND_EXCHANGE, bracelet.getPriceSource());
        assertEquals("the uncharged keeps its own quote",
            40_000, valuation.valueComponent(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L, 0L).unitPrice);
    }

    @Test
    public void committedEtherLoadsBookTheirEtherAsSupplies()
    {
        Engine engine = engine();
        long start = 100_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_SHARD, 30L));

        assertTrue(engine.markChargeLoad(ChargeCheck.ChargedItem.ETHEREUM, ItemID.WILD_CAVE_SHARD,
            "Revenant ether", BRACELET, 8));
        engine.markDirty();
        Transaction load = settle(engine, snapshot(ItemID.WILD_CAVE_SHARD, 25L), start + 600L);

        assertEquals(TransactionType.CONSUMPTION, load.autoType());
        assertTrue(load.isCounted());
        assertEquals(GameData.msg("committed-load") + "Bracelet of ethereum", load.getNote());
        assertEquals(ActionKind.SUPPLIES, load.getActionKind());
        assertEquals(-1_250L, load.getNet());
        assertEquals(1_250L, engine.getMetrics(start + 2_400L).costs);
    }

    @Test
    public void anUnchargeBooksNothing()
    {
        Engine engine = engine();
        long start = 120_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Uncharge", item(ItemID.WILD_CAVE_BRACELET_CHARGED, 0)),
            "uncharge", "Bracelet of ethereum");
        assertNotNull("the uncharge watch arms", engine.inbox.peek(Inbox.UNCHARGE));
        engine.markDirty();
        settle(engine, snapshot(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L), start + 600L);

        assertTrue("the ether was booked at load; the uncharge adds nothing",
            engine.getActiveSession().getTransactions().stream().noneMatch(Transaction::isCounted));
        assertEquals(0L, engine.getMetrics(start + 2_400L).net);
    }

    @Test
    public void theBankConfigureChargesRouteNeverPhantomBooks()
    {
        Engine engine = engine();
        long start = 140_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_SHARD, 30L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Configure-Charges", item(ItemID.WILD_CAVE_BRACELET_CHARGED, 0)),
            "configure-charges", "Bracelet of ethereum");
        assertNull("no load arms without a use-on click", engine.inbox.peek(Inbox.LOAD_TARGET));

        engine.markDirty();
        settle(engine, snapshot(ItemID.WILD_CAVE_SHARD, 25L), start + 600L);
        for (Transaction row : engine.getActiveSession().getTransactions())
        {
            assertFalse("a bank load cannot phantom-book as a charge load",
                row.getNote() != null && row.getNote().startsWith(GameData.msg("committed-load")));
        }
    }

    @Test
    public void alchemyBooksTheBraceletAtItsBaseQuoteOnce()
    {
        // The observed cast: the charged bracelet leaves and the coins arrive under consume
        // intent (the ConsumptionBurialEngineTest alchemy pattern).
        Engine engine = engine();
        long start = 160_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L));
        engine.noteConsume(ItemID.WILD_CAVE_BRACELET_CHARGED, 8, false);
        engine.markDirty();

        Transaction alchemy = settle(engine, snapshot(995, 45_000L), start + 600L);

        assertNotNull(alchemy);
        assertTrue(alchemy.isCounted());
        long braceletLeg = alchemy.getFlows().stream()
            .filter(flow -> flow.itemId == ItemID.WILD_CAVE_BRACELET_CHARGED)
            .mapToLong(flow -> flow.valueDelta).sum();
        assertEquals("the bracelet leaves at its uncharged form's quote", -40_000L, braceletLeg);
        assertEquals(5_000L, alchemy.getNet());
    }

    @Test
    public void theChargeToAlchFlowNetsTheGuideMargin()
    {
        Engine engine = engine();
        long start = 200_000L;
        engine.ensureSession(start);

        // Buy the bracelet and one ether (both net-neutral), charge (the committed load), then
        // alch: the counted lifetime net is the guide's margin.
        engine.setBaseline(snapshot(995, 100_000L));
        engine.markDirty();
        settle(engine, snapshot(mapOf(995, 60_000L, ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L)), start + 600L);

        engine.markDirty();
        settle(engine, snapshot(mapOf(995, 59_750L, ItemID.WILD_CAVE_BRACELET_UNCHARGED, 1L,
            ItemID.WILD_CAVE_SHARD, 1L)), start + 1_400L);

        engine.markChargeLoad(ChargeCheck.ChargedItem.ETHEREUM, ItemID.WILD_CAVE_SHARD,
            "Revenant ether", BRACELET, 8);
        engine.markDirty();
        settle(engine, snapshot(mapOf(995, 59_750L, ItemID.WILD_CAVE_BRACELET_CHARGED, 1L)), start + 2_200L);

        engine.noteConsume(ItemID.WILD_CAVE_BRACELET_CHARGED, 8, false);
        engine.markDirty();
        settle(engine, snapshot(995, 104_750L), start + 3_000L);

        assertEquals("45,000 - 40,000 - 250", 4_750L, engine.getMetrics(start + 5_000L).net);
    }

    @Test
    public void aDeathWipeAddsNoEtherDoubleCount()
    {
        Engine engine = engine();
        long start = 240_000L;
        engine.ensureSession(start);
        ContainerSnapshot carried = snapshot(ItemID.WILD_CAVE_BRACELET_CHARGED, 1L);
        engine.setBaseline(carried);
        engine.markDirty();
        for (int tick = 1; tick <= 3; tick++)
        {
            engine.processIfDirty(carried, start + tick * 600L, null);
        }

        engine.markPvmDeath(1, carried.quantities);
        engine.markDirty();
        Transaction wipe = settle(engine, ContainerSnapshot.empty(), start + 3_000L);

        assertNotNull(wipe);
        assertEquals(TransactionType.TRANSFER, wipe.getType());
        assertFalse(wipe.isCounted());
        assertEquals(0L, engine.getMetrics(start + 6_000L).net);
        for (Transaction row : engine.getActiveSession().getTransactions())
        {
            assertFalse(row.getNote() != null && row.getNote().startsWith(GameData.msg("committed-load")));
        }
    }

    private static ItemComposition composition(int id)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) ->
            {
                if ("getName".equals(method.getName())) return "Bracelet of ethereum";
                if ("getHaPrice".equals(method.getName())) return 45_000;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return false;
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }

    private static Engine engine()
    {
        return new Engine(EthereumChargeTest::flows, new TransactionClassifier(), CONFIG);
    }

    private static List<Flow> flows(Map<Integer, Long> deltas)
    {
        List<Flow> flows = new ArrayList<>();
        for (Map.Entry<Integer, Long> entry : deltas.entrySet())
        {
            int price = priceOf(entry.getKey());
            flows.add(new Flow(entry.getKey(), nameOf(entry.getKey()), entry.getValue(), price,
                entry.getValue() * price));
        }
        return flows;
    }

    private static int priceOf(int itemId)
    {
        if (itemId == ItemID.COINS) return 1;
        if (itemId == ItemID.WILD_CAVE_SHARD) return 250;
        if (itemId == ItemID.WILD_CAVE_BRACELET_UNCHARGED
                || itemId == ItemID.WILD_CAVE_BRACELET_CHARGED) return 40_000;
        return 0;
    }

    private static String nameOf(int itemId)
    {
        if (itemId == ItemID.COINS) return "Coins";
        if (itemId == ItemID.WILD_CAVE_SHARD) return "Revenant ether";
        return "Bracelet of ethereum";
    }

    private static ContainerSnapshot snapshot(int id, long quantity)
    {
        return snapshot(mapOf(id, quantity));
    }

    private static ContainerSnapshot snapshot(Map<Integer, Long> quantities)
    {
        return new ContainerSnapshot(quantities);
    }

    private static Map<Integer, Long> mapOf(Object... values)
    {
        Map<Integer, Long> result = new HashMap<>();
        for (int index = 0; index + 1 < values.length; index += 2)
        {
            result.put((Integer) values[index], (Long) values[index + 1]);
        }
        return result;
    }

    private static Transaction settle(Engine engine, ContainerSnapshot next, long firstTick)
    {
        assertNull(engine.processIfDirty(next, firstTick, null));
        assertNull(engine.processIfDirty(next, firstTick + 600L, null));
        return engine.processIfDirty(next, firstTick + 1_200L, null);
    }

    private static Widget item(int itemId, int slot)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[] {Widget.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getItemId": return itemId;
                    case "getIndex": return slot;
                    case "getId": return InterfaceID.Inventory.ITEMS;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        return null;
                }
            });
    }

    private static net.runelite.api.Client selecting(Widget selected)
    {
        return (net.runelite.api.Client) Proxy.newProxyInstance(
            net.runelite.api.Client.class.getClassLoader(), new Class<?>[] {net.runelite.api.Client.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getSelectedWidget": return selected;
                    case "getTickCount": return 101;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
    }

    private static MenuOptionClicked click(MenuAction action, String option, Widget clicked)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return option;
                    case "getTarget": return "";
                    case "getType": return action;
                    case "getWidget": return clicked;
                    case "getItemId": return clicked == null ? -1 : clicked.getItemId();
                    case "getParam0": return clicked == null ? -1 : clicked.getIndex();
                    case "getParam1": return clicked == null ? -1 : clicked.getId();
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class FiremakingSupplyEvidenceTest
{
    @Test
    public void explicitLightAndTendToFuelLossesAreTypedSupplies()
    {
        assertFuelAction("Light", "Willow logs");
        assertFuelAction("Tend-to", "Blisterwood logs");
        assertFuelAction("Tend to", "Juniper logs");
        assertTrue("existing Use Tinderbox evidence remains supported",
            ActionSignals.lightsFire("Use", "Tinderbox -> Willow logs"));
    }

    @Test
    public void unexplainedLossAndArbitraryUseRemainLosses()
    {
        Transaction unexplained = transaction("Logs");
        assertNull(ActionReader.resolve(null, unexplained.getFlows(), unexplained.getType(), "Firemaking"));
        assertEquals(CostKind.LOSS, CostKind.of(unexplained, unexplained.getFlows().get(0)));

        ActionKind arbitraryUse = ActionReader.verbOf("Use");
        assertNull(arbitraryUse);
        assertNull(ActionReader.resolve(arbitraryUse, unexplained.getFlows(),
            unexplained.getType(), "Firemaking"));
        assertEquals(CostKind.LOSS, CostKind.of(unexplained, unexplained.getFlows().get(0)));

        ActionKind mismatchedFuelIntent = ActionReader.resolve(ActionReader.verbOf("Light"),
            Collections.singletonList(new Flow(946, "Knife", -1L, 1, -1L)),
            TransactionType.CONSUMPTION, "Firemaking");
        assertNull("Light does not turn a non-fuel loss into Supplies", mismatchedFuelIntent);
    }

    private static void assertFuelAction(String menuOption, String name)
    {
        Transaction transaction = transaction(name);
        ActionKind resolved = ActionReader.resolve(ActionReader.verbOf(menuOption),
            transaction.getFlows(), transaction.getType(), "Firemaking");
        assertEquals(ActionKind.SUPPLIES, resolved);
        transaction.setActionKind(resolved);
        assertEquals(CostKind.SUPPLIES, CostKind.of(transaction, transaction.getFlows().get(0)));
    }

    private static Transaction transaction(String name)
    {
        return new Transaction(1_000L, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Firemaking", true,
            Collections.singletonList(new Flow(1519, name, -1L, 100, -100L)),
            Confidence.CONFIRMED, "explicit evidence test", null);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static com.gpmanager.GameData.msg;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner live 2026-10-16: coins picked up at Commander Zilyana went to Review as "Grand Exchange
 * movement not claimable by a custody lifecycle", because a sale had finished in the last two
 * hours. The GE-collect gate stops new ones; the load-time recheck rebooks the old ones.
 */
public class GeCollectRecheckTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int COINS = 995, BONES = 526;

    @Test
    public void aPreGateCoinPickupBooksAsTodaysPickup()
    {
        Engine engine = engine();
        engine.startCustom("Zilyana", T0);
        Session session = engine.getActiveSession();
        Transaction old = geReview(Context.GENERIC, coins(19_911L));
        String id = old.getId();
        session.addTransaction(old, 2_000, false);
        assertTrue("it starts in Review", ReviewRules.needsOwnerDecision(old));
        long revision = engine.getRevision();

        engine.recheck(item -> 0);

        Transaction today = pickup(19_911L);
        assertNotNull("today's code books the same coins", today);
        assertSame(today.getType(), old.getType());
        assertSame(TransactionType.GAIN, old.getType());
        assertEquals(today.isCounted(), old.isCounted());
        assertTrue(old.isCounted());
        assertSame(today.getConfidence(), old.getConfidence());
        assertEquals(today.getExplanation(), old.getExplanation());
        assertEquals(today.getNote(), old.getNote());
        assertFalse("it leaves Review", ReviewRules.needsOwnerDecision(old));
        assertEquals("same row", id, old.getId());
        assertEquals("same time", T0, old.timestampEpochMillis);
        assertEquals("same activity", "Growler", old.getActivityName());
        assertSame(Correction.AUTO, old.getCorrection());
        assertEquals("the session's Net counts it", 19_911L, session.metrics(T0).net);
        assertNotEquals("the HUD and totals hear of it", revision, engine.getRevision());

        revision = engine.getRevision();
        engine.recheck(item -> 0);
        assertEquals("a second pass changes nothing", revision, engine.getRevision());
    }

    @Test
    public void aMarketRowALossOrAnOwnerDecisionIsNeverRebooked()
    {
        Engine engine = engine();
        engine.startCustom("Zilyana", T0);
        Session session = engine.getActiveSession();
        Transaction market = geReview(Context.MARKET, coins(5_000L));
        Transaction withLoss = geReview(Context.GENERIC, coins(5_000L),
            new Flow(BONES, "Bones", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE));
        Transaction withItem = geReview(Context.GENERIC, coins(5_000L),
            new Flow(BONES, "Bones", 1L, 100, 100L, PriceSource.GRAND_EXCHANGE));
        Transaction counted = geReview(Context.GENERIC, coins(5_000L));
        counted.applyCorrection(Correction.REVENUE, T0);
        for (Transaction row : List.of(market, withLoss, withItem, counted)) session.addTransaction(row, 2_000, false);
        long revision = engine.getRevision();

        engine.recheck(item -> 0);

        for (Transaction row : List.of(market, withLoss, withItem, counted))
        {
            assertSame(TransactionType.UNCERTAIN, row.autoType());
            assertEquals("Grand Exchange", row.getNote());
            assertEquals(msg("grand-exchange-movement"), row.getExplanation());
            assertFalse(row.autoCounted());
        }
        assertSame("the owner's Count stays theirs", Correction.REVENUE, counted.getCorrection());
        assertEquals("nothing changed", revision, engine.getRevision());
    }

    private static Flow coins(long quantity)
    {
        return new Flow(COINS, "Coins", quantity, 1, quantity, PriceSource.FACE_VALUE);
    }

    /** A row as the pre-gate rule booked it. */
    private static Transaction geReview(Context context, Flow... flows)
    {
        return new Transaction(T0, TransactionType.UNCERTAIN, context, "Grand Exchange", "Growler", false,
            List.of(flows), Confidence.UNCERTAIN, msg("grand-exchange-movement"), null);
    }

    /** The same coins landing in the pack today, with no Collect click. */
    private static Transaction pickup(long quantity)
    {
        Engine engine = engine();
        engine.startCustom("Zilyana", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(Map.of(COINS, 0L))));
        engine.markDirty();
        List<Transaction> booked = new ArrayList<>();
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(Map.of(COINS, quantity))),
                T0 + 600L + i * 600L, booked::add);
            if (settled != null) booked.add(settled);
        }
        return booked.isEmpty() ? null : booked.get(0);
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                flows.add(id == COINS ? coins(delta.getValue())
                    : new Flow(id, "Bones", delta.getValue(), 100, delta.getValue() * 100, PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-09: an offer collected to the bank never shows its cash or items in the
 * inventory, so it used to wait ten minutes and land in Review uncounted. The offer itself proves
 * what filled and what it cost, so it now settles: a buy exactly, a sale at its proven tax or, at
 * mixed prices, the highest tax it could have paid.
 */
public class GeCollectToBankTest
{
    private static final int COINS = ItemID.COINS;
    private static final int RUNE = ItemID.NATURERUNE;
    private static final long T0 = 1_000_000_000_000L;
    private static final long LATER = 31_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 1_000_000L, RUNE, 100L));
    private final OfferSlots ledger = new OfferSlots();
    private final Engine engine = engine(inventory);

    @Test
    public void aBuyCollectedToTheBankIsAPurchase()
    {
        long t = T0 + 10_000L;
        offer(0, BUYING, 1_000, 180, 0, 0, t);
        inventory.put(COINS, 1_000_000L - 180_000L);
        settle(t + 100L);
        offer(0, BOUGHT, 1_000, 180, 1_000, 176_000, t + 1_000L);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("no Review", 0, reviewRows());
        assertTrue("one purchase", trades() == 1);
        assertEquals("buying is Net-neutral", 0L, net());
        engine.tickGe(t + 2_000L + 11L * 60_000L);
        assertEquals("still nothing in Review ten minutes later", 0, reviewRows());
    }

    @Test
    public void aSaleAtOnePriceCollectedToTheBankCountsItsTax()
    {
        long t = T0 + 10_000L;
        sell(40L, 5_600L, SOLD, t);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + 10_000L);
        assertEquals("not before the bank wait", 0, trades());
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("140 each pays 2 each", -80L, net());
        assertEquals(0, reviewRows());
        assertEquals(1, trades());
    }

    @Test
    public void aSaleAtSeveralPricesCountsTheHighestTaxItCouldHavePaid()
    {
        long t = T0 + 10_000L;
        sell(25L, 3_513L, SOLD, t);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("3,513 / 50 = 70 at most, never less than the truth", -70L, net());
        assertEquals(0, reviewRows());
        assertTrue(lastTrade().getExplanation().contains("highest tax"));
    }

    @Test
    public void aCancelledSaleSendsWhatDidNotSellToTheBankToo()
    {
        long t = T0 + 10_000L;
        sell(40L, 0L, SELLING, t);
        offer(0, SELLING, 40, 140, 10, 1_400, t + 1_000L);
        offer(0, CANCELLED_SELL, 40, 140, 10, 1_400, t + 1_500L);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals("only the 10 sold pay tax", -20L, net());
        assertEquals("the 30 unsold went back neutrally", 0, reviewRows());
        engine.tickGe(t + 2_000L + 11L * 60_000L);
        assertEquals(0, reviewRows());
    }

    @Test
    public void coinsCollectedToTheInventoryStillSettleOnceFromThem()
    {
        long t = T0 + 10_000L;
        sell(40L, 5_600L, SOLD, t);
        offer(0, EMPTY, 0, 0, 0, 0, t + 2_000L);
        engine.noteGeCollect(t + 2_100L);
        inventory.put(COINS, inventory.get(COINS) + 5_600L - 80L);
        settle(t + 2_200L);
        engine.tickGe(t + 2_000L + LATER);

        assertEquals(-80L, net());
        assertEquals("settled once, from the coins", 1, trades());
        assertEquals(0, reviewRows());
    }

    private void sell(long quantity, long spent, GrandExchangeOfferState state, long t)
    {
        offer(0, SELLING, (int) quantity, 140, 0, 0, t);
        inventory.put(RUNE, inventory.get(RUNE) - quantity);
        settle(t + 100L);
        if (state == SOLD) offer(0, SOLD, (int) quantity, 140, (int) quantity, (int) spent, t + 1_000L);
    }

    private long net()
    {
        return engine.getMetrics(T0 + 60L * 60_000L).net;
    }

    private int reviewRows()
    {
        int count = 0;
        for (Transaction transaction : engine.getActiveSession().getTransactions())
        {
            if (ReviewRules.needsOwnerDecision(transaction)) count++;
        }
        return count;
    }

    private int trades()
    {
        int count = 0;
        for (Transaction transaction : engine.getActiveSession().getTransactions())
        {
            if (transaction.autoType() == TransactionType.TRADE) count++;
        }
        return count;
    }

    private Transaction lastTrade()
    {
        Transaction last = null;
        for (Transaction transaction : engine.getActiveSession().getTransactions())
        {
            if (transaction.autoType() == TransactionType.TRADE) last = transaction;
        }
        return last;
    }

    private void offer(int slot, GrandExchangeOfferState state, int total, int price, int traded, int spent, long at)
    {
        int item = state == EMPTY ? 0 : state == BUYING || state == BOUGHT ? ItemID.WILD_CAVE_SHARD : RUNE;
        ledger.observe(new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent))
            .ifPresent(transition -> engine.noteGeOffer(transition, "Item " + item, at));
    }

    private void settle(long at)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(new HashMap<>(inventory));
        engine.processIfDirty(snapshot, at, null);
        engine.processIfDirty(snapshot, at + 1L, null);
    }

    private static Engine engine(Map<Integer, Long> inventory)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                long unit = id == COINS ? 1L : 137L;
                flows.add(new Flow(id, id == COINS ? "Coins" : "Item " + id, delta.getValue(), (int) unit,
                    delta.getValue() * unit, id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        });
        engine.startCustom("Trading", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
        return engine;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_BUY;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Schema-104 Option 2 custody contract: pending placement/reserve is ownership-neutral, a
 * cancellation return is neutral at its frozen basis, and a safely realized settlement books one
 * canonical Market result exactly once.
 */
public class GeCustodyEngineTest
{
    private static final int RUNE = ItemID.NATURERUNE;
    private static final int LOGS = ItemID.LOGS;
    private static final int COINS = ItemID.COINS;
    private static final long T0 = 1_000_000_000_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final class Harness
    {
        final int[] quote;
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        long now = T0;
        Map<Integer, Long> inventory = new HashMap<>();

        Harness(int initialQuote)
        {
            quote = new int[]{initialQuote};
            engine = engine(quote);
            engine.startCustom("Trading", now);
            inventory.put(COINS, 100_000L);
            engine.setBaseline(new ContainerSnapshot(inventory));
        }

        OfferSlots.Transition offer(int slot, GrandExchangeOfferState state, int item, int total,
            int traded, int price, int spent)
        {
            now += 600L;
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent)).orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition, name(transition.current.itemId), now);
            }
            return transition;
        }

        Transaction settle(Map<Integer, Long> next)
        {
            now += 600L;
            inventory = new HashMap<>(next);
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            Transaction result = null;
            for (int i = 0; i < 3; i++)
            {
                Transaction settled = engine.processIfDirty(snapshot, now, null);
                if (settled != null)
                {
                    result = settled;
                }
                now += 600L;
            }
            return result;
        }

        /** Establish exact known coverage for an item (schema-106 tracked basis). */
        void gain(int item, long quantity, long value, long at)
        {
            engine.getActiveSession().addTransaction(new Transaction(at,
                TransactionType.GAIN, Context.GENERIC, "", "Loot", true,
                Collections.singletonList(new Flow(item, name(item), quantity,
                    (int) (quantity > 0L ? value / quantity : 0L), value,
                    PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED, "", null), 500, false);
        }

        long net()
        {
            return engine.getMetrics(now).net;
        }

        List<Transaction> transactions()
        {
            List<Transaction> out = new ArrayList<>();
            for (Transaction transaction : engine.getActiveSession().getTransactions())
            {
                if (transaction != null)
                {
                    out.add(transaction);
                }
            }
            return out;
        }

        List<Transaction> counted()
        {
            List<Transaction> out = new ArrayList<>();
            for (Transaction transaction : transactions())
            {
                if (transaction.isCounted())
                {
                    out.add(transaction);
                }
            }
            return out;
        }

        List<Transaction> reviews()
        {
            List<Transaction> out = new ArrayList<>();
            for (Transaction transaction : transactions())
            {
                if (!transaction.isCounted()
                    && transaction.autoType() == TransactionType.UNCERTAIN)
                {
                    out.add(transaction);
                }
            }
            return out;
        }
    }

    private static String name(int id)
    {
        if (id == COINS)
        {
            return "Coins";
        }
        if (id == RUNE)
        {
            return "Nature rune";
        }
        if (id == ItemID.LAWRUNE) return "Law rune";
        if (id == LOGS)
        {
            return "Logs";
        }
        return "Item " + id;
    }

    private static Map<Integer, Long> with(Map<Integer, Long> base, Object... pairs)
    {
        Map<Integer, Long> map = new HashMap<>(base);
        for (int i = 0; i < pairs.length; i += 2)
        {
            long quantity = (Long) pairs[i + 1];
            if (quantity <= 0L)
            {
                map.remove((Integer) pairs[i]);
            }
            else
            {
                map.put((Integer) pairs[i], quantity);
            }
        }
        return map;
    }

    private static long flow(Transaction transaction, int itemId)
    {
        for (Flow itemFlow : transaction.getFlows())
        {
            if (itemFlow.itemId == itemId)
            {
                return itemFlow.valueDelta;
            }
        }
        return 0L;
    }

    // ---- proven starting defects ---------------------------------------------------------

    @Test
    public void bankedRuneSalesUseEarlierKnownBasisButNeverInventItFromAWithdrawal()
    {
        for (boolean earlierAcquisition : new boolean[] {true, false})
        {
            Harness h = new Harness(122);
            if (earlierAcquisition)
            {
                h.gain(ItemID.LAWRUNE, 200L, 24_400L, h.now);
                h.inventory = with(h.inventory, ItemID.LAWRUNE, 200L);
                h.engine.setBaseline(new ContainerSnapshot(h.inventory));
                h.engine.markTransfer("Bank deposit", 6);
                h.settle(with(h.inventory, ItemID.LAWRUNE, 0L));
            }
            assertTrue(h.engine.finishCustom(h.now));
            h.engine.startCustom("Trading", h.now);
            h.engine.setBaseline(new ContainerSnapshot(h.inventory));
            h.engine.markTransfer("Bank withdrawal", 6);
            h.settle(with(h.inventory, ItemID.LAWRUNE, 200L));
            assertEquals("withdrawing owned stock adds no revenue", 0L, h.net());

            h.offer(0, SELLING, ItemID.LAWRUNE, 200, 0, 120, 0);
            h.settle(with(h.inventory, ItemID.LAWRUNE, 0L));
            h.offer(0, SOLD, ItemID.LAWRUNE, 200, 200, 120, 24_000);
            Transaction law = h.settle(with(h.inventory, COINS, 123_600L));
            assertNotNull(law);
            assertEquals("known basis gives -800; unknown basis counts only the proven -400 tax",
                earlierAcquisition ? -800L : -400L, law.getNet());

            h.quote[0] = 136;
            h.engine.markTransfer("Bank withdrawal", 6);
            h.settle(with(h.inventory, RUNE, 200L));
            h.offer(1, SELLING, RUNE, 200, 0, 137, 0);
            h.settle(with(h.inventory, RUNE, 0L));
            h.offer(1, SOLD, RUNE, 200, 200, 137, 27_400);
            Transaction nature = h.settle(with(h.inventory, COINS, 150_600L));
            assertNotNull(nature);
            assertEquals(-400L, nature.getNet());
            assertEquals("only genuine earlier law basis supports the owner's -1.2k total",
                earlierAcquisition ? -1_200L : -800L, h.net());
            assertEquals("sale proceeds never become ordinary Gains", 0L,
                LiveSnapshot.capture(h.engine, h.now, null).gains);
        }
    }

    @Test
    public void pendingSellCustodyIsNeutral()
    {
        Harness h = new Harness(6);
        h.inventory = with(h.inventory, RUNE, 100L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));

        h.offer(0, SELLING, RUNE, 100, 0, 7, 0);
        Transaction placement = h.settle(with(h.inventory, RUNE, 0L));
        assertNotNull(placement);
        assertEquals("placement principal is a custody transfer",
            TransactionType.TRANSFER, placement.getType());
        assertFalse(placement.isCounted());
        assertEquals("pending SELL must not change canonical Net", 0L, h.net());
        assertEquals(1, h.engine.geCustody.records().size());
    }

    @Test
    public void pendingBuyObservedReserveIsNeutral()
    {
        Harness h = new Harness(6);
        h.offer(1, BUYING, LOGS, 100, 0, 7, 0);
        Transaction reserve = h.settle(with(h.inventory, COINS, 100_000L - 700L));
        assertNotNull(reserve);
        assertEquals(TransactionType.TRANSFER, reserve.getType());
        assertFalse(reserve.isCounted());
        assertEquals("pending BUY reserve must not change canonical Net", 0L, h.net());
    }

    @Test
    public void zeroFillCancelAfterQuoteMovementIsNeutral()
    {
        Harness h = new Harness(6);
        h.inventory = with(h.inventory, RUNE, 100L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));

        h.offer(2, SELLING, RUNE, 100, 0, 7, 0);
        h.settle(with(h.inventory, RUNE, 0L));
        assertEquals(0L, h.net());

        h.quote[0] = 7;
        h.offer(2, CANCELLED_SELL, RUNE, 100, 0, 7, 0);
        h.settle(with(h.inventory, RUNE, 100L));
        assertEquals("cancelled unfilled principal is neutral at its frozen basis", 0L, h.net());
    }

    @Test
    public void cancelledSellNeverClaimsAnotherItemsGainAsItsReturn()
    {
        Harness h = new Harness(6);
        h.inventory = with(h.inventory, RUNE, 100L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));
        h.offer(2, SELLING, RUNE, 100, 0, 7, 0);
        h.settle(with(h.inventory, RUNE, 0L));
        h.offer(2, CANCELLED_SELL, RUNE, 100, 0, 7, 0);

        Transaction pickup = h.settle(with(h.inventory, LOGS, 5L));

        assertNotNull(pickup);
        assertFalse("another item's gain is not this offer's cancellation return",
            pickup.getType() == TransactionType.TRANSFER);
    }

    // ---- SELL realization ----------------------------------------------------------------

    @Test
    public void sellAboveBasisRealizesPositiveEdgeOnce()
    {
        Harness h = new Harness(6);
        h.inventory = with(h.inventory, RUNE, 10L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));
        h.gain(RUNE, 10L, 60L, h.now - 60_000L);

        h.offer(0, SELLING, RUNE, 10, 0, 7, 0);
        h.settle(with(h.inventory, RUNE, 0L));
        h.offer(0, SOLD, RUNE, 10, 10, 7, 70);
        Transaction settlement = h.settle(with(h.inventory, COINS, 100_070L));

        assertNotNull(settlement);
        assertEquals(TransactionType.TRADE, settlement.getType());
        assertTrue(settlement.isCounted());
        assertEquals("known basis consumed at the pooled value", -60L, flow(settlement, RUNE));
        assertEquals("observed cash settlement", 70L, flow(settlement, COINS));
        assertEquals("the sale realizes +10 on top of the counted 60", 70L, h.net());
        assertEquals(2, h.counted().size());

        // A duplicate terminal replay and a restart must not book again.
        assertTrue(h.engine.geCustody.records().isEmpty()
            || h.engine.geCustody.records().get(0).getSettledQty() == 10L);
        assertEquals(2, h.counted().size());
    }

    @Test
    public void sellBelowBasisRealizesNegativeEdgeOnce()
    {
        Harness h = new Harness(6);
        h.inventory = with(h.inventory, RUNE, 10L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));
        h.gain(RUNE, 10L, 70L, h.now - 60_000L);

        h.offer(0, SELLING, RUNE, 10, 0, 7, 0);
        h.settle(with(h.inventory, RUNE, 0L));
        h.offer(0, SOLD, RUNE, 10, 10, 7, 50);
        Transaction settlement = h.settle(with(h.inventory, COINS, 100_050L));
        assertEquals("the sale realizes -20 against the counted 70", -20L, settlement.getNet());
        assertEquals("end to end the received 50 is the tracked realization", 50L, h.net());
    }

    @Test
