    @Test
    public void multiPriceFillsPreserveExactTotal()
    {
        Harness h = new Harness(6);
        h.inventory = with(h.inventory, RUNE, 10L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));
        h.gain(RUNE, 10L, 60L, h.now - 60_000L);

