 * Owner smoke (G2 re-test): a collect held for exact attribution must resolve on game ticks, not
 * only when a later inventory change happens to settle. The hold is transient, so waiting for an
 * unrelated movement left the cash invisible and lost it on logout.
 */
public class GeCustodyTickTest
{
    private static final int COINS = ItemID.COINS;
    private static final int SHARK = ItemID.SHARK;
    private static final long T0 = 1_000_000_000_000L;
    private static final long RECEIVED = 29_280L - 570L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void heldCollectResolvesOnTheTickAfterItsWindowWithoutAnotherInventoryChange()
    {
        Map<Integer, Long> inventory = new HashMap<>();
        Engine engine = engine();
        engine.startCustom("Trading", T0);
        inventory.put(COINS, 1_000_000L);
        inventory.put(SHARK, 60L);
        engine.setBaseline(new ContainerSnapshot(inventory));
        OfferSlots ledger = new OfferSlots();
        long t = T0 + 10_000L;
        // Two identical sold offers: one collect's cash matches either, so it is a tie.
        offer(engine, ledger, 0, SELLING, 0, 0, t);
        offer(engine, ledger, 1, SELLING, 0, 0, t + 50L);
        inventory.put(SHARK, 0L);
        settle(engine, inventory, t + 100L);
        offer(engine, ledger, 0, SOLD, 30, 29_280, t + 200L);
        offer(engine, ledger, 1, SOLD, 30, 29_280, t + 250L);

        engine.noteGeCollect(t + 10_000L);
        inventory.put(COINS, 1_000_000L + RECEIVED);
        settle(engine, inventory, t + 10_000L);
        assertEquals("the tied cash is held for slot evidence", RECEIVED,
            EngineProbe.pendingSettlementCash(engine.geCustody));
        assertEquals(0, reviewRows(engine));

        assertFalse("inside the window nothing is decided", engine.tickGe(t + 10_600L));
        assertTrue("the first tick after the window resolves it", engine.tickGe(t + 12_400L));
        assertEquals(0L, EngineProbe.pendingSettlementCash(engine.geCustody));
        assertTrue("a tie with no slot evidence fails closed visibly", reviewRows(engine) > 0);
        assertEquals("nothing is counted from an unproven tie", 0L, engine.getMetrics(t + 13_000L).net);
    }

    @Test
    public void pausedTrackingNeverBooksFromTheTick()
    {
        Engine engine = engine();
        engine.startCustom("Trading", T0);
        engine.togglePause(T0 + 1_000L);
        assertFalse(engine.tickGe(T0 + 2_000L));
    }

    private static int reviewRows(Engine engine)
    {
        int count = 0;
        for (Transaction transaction : engine.getActiveSession().getTransactions())
        {
            if (ReviewRules.needsOwnerDecision(transaction))
            {
                count++;
            }
        }
        return count;
    }

    private static void offer(Engine engine, OfferSlots ledger, int slot,
        GrandExchangeOfferState state, int traded, int spent, long at)
    {
        ledger.observe(new OfferSlots.Snapshot(slot, state, SHARK, 30, traded, 978, spent))
            .ifPresent(transition -> engine.noteGeOffer(transition, "Shark", at));
    }

    private static void settle(Engine engine, Map<Integer, Long> inventory, long at)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
        engine.processIfDirty(snapshot, at, null);
        engine.processIfDirty(snapshot, at + 1L, null);
    }

    private static Engine engine()
    {
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                long unit = id == COINS ? 1L : 978L;
                flows.add(new Flow(id, id == COINS ? "Coins" : "Shark", delta.getValue(), (int) unit,
                    delta.getValue() * unit,
                    id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
            @Override
            public Retention receiptRetentionDays()
            {
                return Retention.DAYS_365;
            }

            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        });
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_BUY;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * C3a GE evidence ownership: the offer ledger is item/direction-scoped settlement evidence, never a
 * blanket MARKET hint. Stronger source evidence keeps its delta, terminal/cancel offer states never
 * explain a later movement, and account/profile plus destructive-reset boundaries clear the evidence.
 */
public class GeEvidenceOwnershipTest
{
    private static final int LOGS = 1519;
    private static final int SHARK = 385;
    private static final int COINS = 995;
    private static final long T0 = 1_000_000_000_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void realLootKeepsItsDeltaWhenARecentBuyForTheSameItemExists()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BOUGHT, SHARK, 5, 5, 800, 4_000, now + 600L);

        engine.markLoot(quantities(SHARK, 1L), 100, "Loot from Goblin", "Goblin");
        Transaction loot = settle(engine, inventory(COINS, 100_000L, SHARK, 1L), now + 1_200L);

        assertNotNull(loot);
        assertEquals("real loot owns its delta over a recent GE buy of the same item",
            TransactionType.LOOT, loot.getType());
        assertEquals("Loot from Goblin", loot.getNote());
    }

    @Test
    public void passiveProgressCannotClaimAnUnrelatedItemDelta()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 2, 800, 1_600, now + 600L);

        Transaction gain = settle(engine, inventory(COINS, 100_000L, LOGS, 1L), now + 1_200L);

        assertNotNull(gain);
        assertEquals(TransactionType.GAIN, gain.getType());
    }

    @Test
    public void passiveProgressAloneCannotClaimTheSameItemDelta()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 2, 800, 1_600, now + 600L);

        Transaction gain = settle(engine, inventory(COINS, 100_000L, SHARK, 1L), now + 1_200L);

        assertNotNull(gain);
        assertEquals("unsettled progress cannot make a same-item gain look like a collection",
            TransactionType.GAIN, gain.getType());
    }

    @Test
    public void shopLikeMovementAfterPassiveProgressIsNotStolenAsMarket()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 2, 800, 1_600, now + 600L);

        // A shop purchase pays coins for an item; it is not an offer settlement.
        Transaction purchase = settle(engine, inventory(COINS, 99_200L, SHARK, 1L), now + 1_200L);

        assertNotNull(purchase);
        assertEquals(TransactionType.UNCERTAIN, purchase.getType());
    }

    @Test
    public void cancelledSellRefundCannotExplainALaterItemLoss()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L, SHARK, 5L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 1, CANCELLED_SELL, SHARK, 5, 0, 800, 0, now);

        Transaction loss = settle(engine, inventory(COINS, 100_000L, SHARK, 4L), now + 600L);

        assertNotNull(loss);
        assertEquals("a cancelled sell returns items; it cannot explain a later loss",
            TransactionType.CONSUMPTION, loss.getType());
    }

    @Test
    public void cancelledBuyRefundCannotExplainALaterCoinLoss()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 2, CANCELLED_BUY, SHARK, 5, 0, 800, 0, now);

        Transaction loss = settle(engine, inventory(COINS, 99_000L), now + 600L);

        assertNotNull(loss);
        assertEquals("a cancelled buy refunds coins; it cannot explain a later coin loss",
            TransactionType.CONSUMPTION, loss.getType());
    }

    @Test
    public void profileSwitchClearsRecentGeEvidence()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BOUGHT, SHARK, 5, 5, 800, 4_000, now + 600L);

        engine.restoreProfile("rsprofile.ge-audit-b", new SavedState(), now + 600L);
        engine.startCustom("Trading", now + 700L);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        Transaction gain = settle(engine, inventory(COINS, 100_000L, SHARK, 1L), now + 1_200L);

        assertNotNull(gain);
        assertEquals("the previous owner's GE evidence must not classify the new owner's delta",
            TransactionType.GAIN, gain.getType());
        assertTrue("the previous owner's custody lifecycles never leak across profiles",
            engine.geCustody.records().isEmpty());
    }

    @Test
    public void destructiveResetClearsRecentGeEvidence()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BOUGHT, SHARK, 5, 5, 800, 4_000, now + 600L);

        engine.resetData(now + 600L);
        engine.togglePause(now + 700L);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        Transaction gain = settle(engine, inventory(COINS, 100_000L, SHARK, 1L), now + 1_200L);

        assertNotNull(gain);
        assertEquals("cleared GE evidence must not reappear after a destructive reset",
            TransactionType.GAIN, gain.getType());
        assertTrue("destructive reset clears schema-104 custody state",
            engine.geCustody.records().isEmpty());
    }

    @Test
    public void recentSellPlacementClaimsTheItemLossAsOwnershipNeutralCustody()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L, SHARK, 5L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 3, SELLING, SHARK, 5, 0, 800, 0, now);

        Transaction trade = settle(engine, inventory(COINS, 100_000L, SHARK, 4L), now + 600L);

        assertNotNull(trade);
        assertEquals("a proven placement principal is custody, not finalized economics",
            TransactionType.TRANSFER, trade.getType());
        assertEquals(Context.TRANSFER, trade.getContext());
        assertEquals("pending SELL custody never changes canonical Net",
            0L, engine.getMetrics(now + 1_200L).net);
        assertEquals(1, engine.geCustody.records().size());
    }

    @Test
    public void recentBuyPlacementClaimsTheCoinLossAsOwnershipNeutralCustody()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 4, BUYING, SHARK, 5, 0, 800, 0, now);

        Transaction trade = settle(engine, inventory(COINS, 96_000L), now + 600L);

        assertNotNull(trade);
        assertEquals("an observed buy reserve is custody, not finalized economics",
            TransactionType.TRANSFER, trade.getType());
        assertEquals(Context.TRANSFER, trade.getContext());
        assertEquals("pending BUY reserve never changes canonical Net",
            0L, engine.getMetrics(now + 1_200L).net);
    }

    @Test
    public void observationsAloneNeverBookWithoutAnInventoryMovement()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(inventory(COINS, 100_000L)));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BOUGHT, SHARK, 5, 5, 800, 4_000, now + 600L);

        assertEquals(0, engine.getActiveSession().getTransactions().size());
        assertEquals(0L, engine.getMetrics(now + 1_200L).net);
    }

    private static void noteGe(
        Engine engine,
        OfferSlots ledger,
        int slot,
        GrandExchangeOfferState state,
        int itemId,
        int totalQuantity,
        int quantityTraded,
        int price,
        int spent,
        long at)
    {
        OfferSlots.Transition transition = ledger.observe(
            new OfferSlots.Snapshot(slot, state, itemId, totalQuantity, quantityTraded, price, spent))
            .orElse(null);
        if (transition != null)
        {
            engine.noteGeOffer(transition, name(itemId), at);
        }
    }

    private static Transaction settle(Engine engine, Map<Integer, Long> next, long now)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(next);
        Transaction first = engine.processIfDirty(snapshot, now, null);
        Transaction settled = engine.processIfDirty(snapshot, now + 600L, null);
        return settled == null ? first : settled;
    }

    private static Map<Integer, Long> inventory(Object... pairs)
    {
        Map<Integer, Long> map = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2)
        {
            map.put((Integer) pairs[i], (Long) pairs[i + 1]);
        }
        return map;
    }

    private static Map<Integer, Long> quantities(int itemId, long quantity)
    {
        Map<Integer, Long> map = new HashMap<>();
        map.put(itemId, quantity);
        return map;
    }

    private static String name(int id)
    {
        return id == LOGS ? "Willow logs" : id == SHARK ? "Shark" : id == COINS ? "Coins" : "Item " + id;
    }

    private static int price(int id)
    {
        return id == LOGS ? 48 : id == SHARK ? 800 : id == COINS ? 1 : 0;
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                flows.add(new Flow(id, name(id), delta.getValue(), price(id), delta.getValue() * price(id),
                    id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.2 (revenant ether and bracelet buys after the Craw's bow): fast buys never leave a coin
 * row in Review. One instantly filled and collected offer settles as a single net spend, and a
 * finished offer collected just before its slot is reused still settles as a purchase.
 */
public class GeFastBuyTest
{
    private static final int COINS = ItemID.COINS;
    private static final long T0 = 1_000_000_000_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void anOfferPlacedBoughtAndCollectedInOneSettleIsOnePurchase()
    {
        Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 1_000_000L));
        Engine engine = engine(inventory);
        OfferSlots ledger = new OfferSlots();
        long t = T0 + 10_000L;
        offer(engine, ledger, 3, BUYING, ItemID.WILD_CAVE_SHARD, 1200, 344, 0, 0, t);
        offer(engine, ledger, 3, BOUGHT, ItemID.WILD_CAVE_SHARD, 1200, 344, 1200, 211_200, t + 50L);
        offer(engine, ledger, 3, EMPTY, 0, 0, 0, 0, 0, t + 100L);
        engine.noteGeCollect(t + 120L);
        inventory.put(COINS, 1_000_000L - 211_200L);
        inventory.put(ItemID.WILD_CAVE_SHARD, 1200L);
        settle(engine, inventory, t + 200L);

        assertEquals("no coin row in Review", 0, reviewRows(engine));
        assertTrue(engine.getActiveSession().getTransactions().stream().anyMatch(row -> row.autoType() == TransactionType.TRADE));
        assertEquals("buying is Net-neutral", 0L, engine.getMetrics(t + 1_000L).net);
    }

    @Test
    public void aFinishedOfferCollectedJustBeforeItsSlotIsReusedStillSettles()
    {
        Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 1_000_000L));
        Engine engine = engine(inventory);
        OfferSlots ledger = new OfferSlots();
        long t = T0 + 10_000L;
        offer(engine, ledger, 3, BUYING, ItemID.WILD_CAVE_BRACELET_UNCHARGED, 2, 45_000, 0, 0, t);
        inventory.put(COINS, 1_000_000L - 90_000L);
        settle(engine, inventory, t + 20L);
        offer(engine, ledger, 3, BOUGHT, ItemID.WILD_CAVE_BRACELET_UNCHARGED, 2, 45_000, 2, 85_058, t + 50L);
        offer(engine, ledger, 3, EMPTY, 0, 0, 0, 0, 0, t + 100L);
        offer(engine, ledger, 3, BUYING, ItemID.WILD_CAVE_SHARD, 300, 181, 0, 0, t + 150L);
        engine.noteGeCollect(t + 160L);
        inventory.put(COINS, 1_000_000L - 85_058L);
        inventory.put(ItemID.WILD_CAVE_BRACELET_UNCHARGED, 2L);
        settle(engine, inventory, t + 200L);

        assertEquals("no Review for the reused slot", 0, reviewRows(engine));
        assertTrue(engine.getActiveSession().getTransactions().stream().anyMatch(row -> row.autoType() == TransactionType.TRADE));
    }

    private static int reviewRows(Engine engine)
    {
        int count = 0;
        for (Transaction transaction : engine.getActiveSession().getTransactions())
        {
            if (ReviewRules.needsOwnerDecision(transaction))
            {
                count++;
            }
        }
        return count;
    }

    private static void offer(Engine engine, OfferSlots ledger, int slot, GrandExchangeOfferState state, int itemId,
        int total, int price, int traded, int spent, long at)
    {
        ledger.observe(new OfferSlots.Snapshot(slot, state, itemId, total, traded, price, spent))
            .ifPresent(transition -> engine.noteGeOffer(transition, "Item " + itemId, at));
    }

    private static void settle(Engine engine, Map<Integer, Long> inventory, long at)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(new HashMap<>(inventory));
        engine.processIfDirty(snapshot, at, null);
        engine.processIfDirty(snapshot, at + 1L, null);
    }

    private static Engine engine(Map<Integer, Long> inventory)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                long unit = id == COINS ? 1L : 176L;
                flows.add(new Flow(id, id == COINS ? "Coins" : "Item " + id, delta.getValue(), (int) unit,
                    delta.getValue() * unit, id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        });
        engine.startCustom("Trading", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
        return engine;
    }
}

package com.gpmanager;

import java.util.Collections;
import java.util.List;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * Per-slot offer baseline contract of the custody ledger: exact cumulative deltas, duplicate and
 * no-progress screening, desync rejection, Modify Offer, Repeat Offer identity and login seeding.
 */
public class GeOfferBaselineTest
{
    private final OfferSlots offers = new OfferSlots();
    private final GeCustodyLedger custody = new GeCustodyLedger();
    private long now = 1_000L;

    private static OfferSlots.Snapshot snap(int slot, GrandExchangeOfferState state, int item,
        int total, int traded, int price, int spent)
    {
        return new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent);
    }

    /** Feed one snapshot through the offer ledger into custody; returns any Review handoffs. */
    private List<Transaction> step(OfferSlots.Snapshot snapshot)
    {
        now += 600L;
        OfferSlots.Transition transition = offers.observe(snapshot).orElse(null);
        return transition == null ? Collections.emptyList()
            : custody.observeTransition(transition, "Item", now, "s1");
    }

    /** The slot's newest lifecycle. */
    private GeOffer record(int slot)
    {
        GeOffer newest = null;
        for (GeOffer record : custody.records())
        {
            if (record.slot == slot && (newest == null
                || record.getPlacedAtEpochMillis() >= newest.getPlacedAtEpochMillis()))
            {
                newest = record;
            }
        }
        return newest;
    }

    @Test
    public void exactPartialFillDeltasAreDerivedFromCumulativeSnapshots()
    {
        step(snap(0, BUYING, 10, 100, 0, 7, 0));

        step(snap(0, BUYING, 10, 100, 4, 7, 27));
        assertEquals(4L, record(0).getFilledQty());
        assertEquals(27L, record(0).getSpentGp());

        step(snap(0, BOUGHT, 10, 100, 10, 7, 69));
        assertEquals(10L, record(0).getFilledQty());
        assertEquals(69L, record(0).getSpentGp());
        assertEquals("BOUGHT", record(0).getOfferState());
    }

    @Test
    public void duplicateAndNoProgressSnapshotsAreIdempotent()
    {
        step(snap(0, SELLING, 10, 10, 0, 7, 0));
        step(snap(0, SELLING, 10, 10, 3, 7, 21));

        // The identical replay is suppressed and changes nothing.
        step(snap(0, SELLING, 10, 10, 3, 7, 21));
        assertEquals(3L, record(0).getFilledQty());
        assertEquals(21L, record(0).getSpentGp());
        assertEquals(1, custody.records().size());
    }

    @Test
    public void backwardsCountersAreDesyncNotFill()
    {
        step(snap(0, BUYING, 10, 10, 0, 7, 0));
        step(snap(0, BUYING, 10, 10, 6, 7, 42));

        step(snap(0, BUYING, 10, 10, 2, 7, 14));
        assertEquals("backwards counters are never a fill", 6L, record(0).getFilledQty());
        assertEquals(GeOffer.CustodyConfidence.AMBIGUOUS, record(0).getConfidence());

        // Later progress counts from the desynced baseline, not the old one.
        step(snap(0, BUYING, 10, 10, 5, 7, 35));
        assertEquals(9L, record(0).getFilledQty());
    }

    @Test
    public void valueWithoutQuantityIsDesyncNotFill()
    {
        step(snap(0, SELLING, 10, 10, 0, 7, 0));
        step(snap(0, SELLING, 10, 10, 2, 7, 14));

        step(snap(0, SELLING, 10, 10, 2, 7, 20));
        assertEquals(14L, record(0).getSpentGp());
        assertEquals(GeOffer.CustodyConfidence.AMBIGUOUS, record(0).getConfidence());
        assertFalse(record(0).fillTaxExact);
    }

    @Test
    public void terminalTransitionProcessesFinalFillBeforeCancellation()
    {
        step(snap(0, SELLING, 10, 100, 0, 7, 0));
        step(snap(0, SELLING, 10, 100, 20, 7, 140));

        step(snap(0, CANCELLED_SELL, 10, 100, 30, 7, 210));
        assertEquals(30L, record(0).getFilledQty());
        assertEquals(210L, record(0).getSpentGp());
        assertEquals("CANCELLED_SELL", record(0).getOfferState());
    }

    @Test
    public void priceOnlyModifyKeepsTheLifecycleAndQuantityModifyFlags()
    {
        step(snap(0, SELLING, 10, 100, 0, 7, 0));
        String placed = record(0).getOfferId();

        step(snap(0, SELLING, 10, 100, 0, 8, 0));
        assertEquals("a price Modify keeps the lifecycle", placed, record(0).getOfferId());
        assertEquals(8L, record(0).getListedPrice());
        assertFalse(record(0).quantityModified);

        step(snap(0, SELLING, 10, 150, 0, 8, 0));
        assertEquals(placed, record(0).getOfferId());
        assertEquals(150L, record(0).getOfferedQty());
        assertTrue(record(0).quantityModified);

        // Fills after a Modify still count from the unchanged cumulative counters.
        step(snap(0, SELLING, 10, 150, 5, 8, 40));
        assertEquals(5L, record(0).getFilledQty());
    }

    @Test
    public void repeatOfferIsANewLifecycleAfterTerminalClear()
    {
        step(snap(0, SELLING, 10, 5, 0, 7, 0));
        step(snap(0, SOLD, 10, 5, 5, 7, 35));
        GeOffer first = record(0);
        step(snap(0, EMPTY, 0, 0, 0, 0, 0));
        assertTrue(first.cleared);

        step(snap(0, SELLING, 10, 5, 0, 7, 0));
        assertNotEquals(first.getOfferId(), record(0).getOfferId());
        assertEquals("a repeat offer starts from zero progress", 0L, record(0).getFilledQty());
    }

    @Test
    public void replacedIdentityNeverInheritsProgress()
    {
        step(snap(0, SELLING, 10, 5, 0, 7, 0));
        step(snap(0, SELLING, 10, 5, 3, 7, 21));
        GeOffer old = record(0);

        step(snap(0, SELLING, 11, 5, 3, 7, 21));
        assertFalse("the replaced lifecycle is handed off", custody.records().contains(old));
        GeOffer replacement = record(0);
        assertEquals(11, replacement.itemId);
        assertEquals("the replacement is quarantined", GeOffer.CustodyConfidence.AMBIGUOUS,
            replacement.getConfidence());
        assertEquals(3L, replacement.getFilledQty());
    }

    @Test
    public void seedBaselineNeverReplaysExistingProgress()
    {
        offers.beginSeed();
        offers.observe(snap(0, SELLING, 10, 100, 40, 7, 280));
        offers.finishSeed();
        custody.seedSlots(offers.snapshots(), now, "s1");
        assertEquals(40L, record(0).getFilledQty());

        step(snap(0, SELLING, 10, 100, 45, 7, 315));
        assertEquals(45L, record(0).getFilledQty());
        assertEquals(315L, record(0).getSpentGp());
    }

    @Test
    public void missedPlacementIsQuarantinedWithoutAFill()
    {
        // The offer ledger saw the slot, but custody never saw its placement.
        offers.observe(snap(0, SELLING, 10, 100, 40, 7, 280));

        step(snap(0, SELLING, 10, 100, 45, 7, 315));
        assertEquals(GeOffer.CustodyConfidence.LEGACY_UNBASED, record(0).getConfidence());
        assertEquals(0L, record(0).getFilledQty());
    }
}

package com.gpmanager;

import java.util.Map;
import java.util.Optional;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** The offer ledger only screens and pairs snapshots; fill arithmetic is custody's (GeOfferBaselineTest). */
public class GeOfferLedgerTest
{
    @Test
    public void loginReplaySeedsSlotsWithoutEmittingTransitions()
    {
        OfferSlots ledger = new OfferSlots();
        ledger.beginSeed();

        assertFalse(ledger.observe(snapshot(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0)).isPresent());
        assertFalse(ledger.observe(snapshot(1, GrandExchangeOfferState.BUYING, 4151, 10, 0, 2_000_000, 0)).isPresent());
        OfferSlots.Snapshot seeded = snapshot(1, GrandExchangeOfferState.BUYING, 4151, 10, 2, 2_000_000, 3_900_000);
        assertFalse(ledger.observe(seeded).isPresent());

        ledger.finishSeed();
        Optional<OfferSlots.Transition> transition = ledger.observe(
            snapshot(1, GrandExchangeOfferState.BUYING, 4151, 10, 3, 2_000_000, 5_850_000));
        assertTrue(transition.isPresent());
        assertSame("the seeded snapshot is the baseline", seeded, transition.get().previous);
    }

    @Test
    public void repeatedSnapshotsAreIdempotentAndFirstEmptySnapshotIsOnlyABaseline()
    {
        OfferSlots ledger = new OfferSlots();
        OfferSlots.Snapshot empty = snapshot(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
        assertFalse(ledger.observe(empty).isPresent());
        assertFalse(ledger.observe(empty).isPresent());
        assertFalse(ledger.observe(snapshot(0, GrandExchangeOfferState.EMPTY, 995, 1, 1, 1, 1)).isPresent());

        OfferSlots.Snapshot offer = snapshot(0, GrandExchangeOfferState.SELLING, 995, 100, 0, 100, 0);
        OfferSlots.Transition placed = ledger.observe(offer).get();
        assertEquals(GrandExchangeOfferState.EMPTY, placed.previous.state);
        assertSame(offer, placed.current);
        assertFalse(ledger.observe(offer).isPresent());

        OfferSlots.Transition cleared = ledger.observe(empty).get();
        assertSame("a cleared slot keeps the offer it cleared", offer, cleared.previous);
    }

    @Test
    public void firstObservationHasNoPrevious()
    {
        OfferSlots ledger = new OfferSlots();
        OfferSlots.Transition first = ledger.observe(
            snapshot(2, GrandExchangeOfferState.BUYING, 4151, 10, 3, 2_000_000, 5_970_000)).get();
        assertNull(first.previous);
    }

    @Test
    public void relogSeedReplacesOldBaselinesAndSuppressesTheOfferReplay()
    {
        OfferSlots ledger = new OfferSlots();
        ledger.observe(snapshot(3, GrandExchangeOfferState.BUYING, 4151, 10, 2, 2_000_000, 3_980_000));

        ledger.beginSeed();
        assertTrue(ledger.snapshots().isEmpty());
        assertFalse(ledger.observe(snapshot(3, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0)).isPresent());
        assertFalse(ledger.observe(snapshot(3, GrandExchangeOfferState.BUYING, 4151, 10, 2, 2_000_000, 3_980_000)).isPresent());
        ledger.finishSeed();

        OfferSlots.Transition progress = ledger.observe(
            snapshot(3, GrandExchangeOfferState.BUYING, 4151, 10, 5, 2_000_000, 9_950_000)).get();
        assertEquals(2, progress.previous.quantityTraded);
    }

    @Test
    public void snapshotsExposeAnImmutableSlotMapAndImmutableValues()
    {
        OfferSlots ledger = new OfferSlots();
        ledger.observe(snapshot(4, GrandExchangeOfferState.SELLING, 995, 100, 0, 120, 0));

        Map<Integer, OfferSlots.Snapshot> snapshots = ledger.snapshots();
        assertNotNull(snapshots.get(4));
        try
        {
            snapshots.clear();
            throw new AssertionError("snapshot map should be immutable");
        }
        catch (UnsupportedOperationException expected)
        {
            // Expected: callers cannot mutate ledger state through the returned map.
        }
        assertEquals(1, ledger.snapshots().size());
    }

    private static OfferSlots.Snapshot snapshot(
        int slot,
        GrandExchangeOfferState state,
        int itemId,
        int totalQuantity,
        int quantityTraded,
        int price,
        int spent)
    {
        return new OfferSlots.Snapshot(
            slot, state, itemId, totalQuantity, quantityTraded, price, spent);
    }
}

