    @Test
    public void twoOffersForTheSameItemSettleOnceFromTheInventory()
    {
        Harness h = new Harness();
        h.offer(0, BUYING, LOGS, 10, 0, 48, 0);
        h.offer(1, BUYING, LOGS, 10, 0, 48, 0);
        h.offer(0, BOUGHT, LOGS, 10, 10, 48, 480);
        h.offer(1, BOUGHT, LOGS, 10, 10, 48, 480);
        assertEquals(20L, h.filled());
        h.geInventory(with(h.inventory, LOGS, 20L));
        List<Transaction> counted = h.counted();
        assertEquals("each offer settles its own acquisition exactly once", 2, counted.size());
        long total = 0L;
        for (Transaction transaction : counted)
        {
            total += flow(transaction, LOGS);
        }
        assertEquals(960L, total);
        assertEquals(0L, h.net());
    }

    /**
     * Property: with or without offer observations, the canonical Net of every script stays exact.
     * Option 2 changes classification (custody is neutral), never the economic total, because this
     * harness values every movement at one fixed quote and books execution at the same price.
     */
    @Test
    public void observationsNeverChangeTheCanonicalNet()
    {
        for (int seed = 0; seed < 40; seed++)
        {
            Random random = new Random(seed);
            List<Object[]> script = new ArrayList<>();
            int steps = 3 + random.nextInt(8);
            for (int i = 0; i < steps; i++)
            {
                int kind = random.nextInt(3);
                int item = random.nextBoolean() ? LOGS : SHARK;
                int qty = 1 + random.nextInt(10);
                script.add(new Object[]{kind, item, qty});
            }
            long withObservations = runNet(script, true);
            long without = runNet(script, false);
            assertEquals("seed " + seed, without, withObservations);
        }
    }

    private static long runNet(List<Object[]> script, boolean observe)
    {
        Harness h = new Harness();
        int slot = 0;
        for (Object[] step : script)
        {
            int kind = (Integer) step[0];
            int item = (Integer) step[1];
            int qty = (Integer) step[2];
            int price = price(item);
            if (kind == 0)
            {
                if (observe) h.offer(slot, BUYING, item, qty, 0, price, 0);
                h.geInventory(with(h.inventory, COINS, h.inventory.get(COINS) - (long) qty * price));
                if (observe) h.offer(slot, BOUGHT, item, qty, qty, price, qty * price);
                h.geInventory(with(h.inventory, item, h.inventory.getOrDefault(item, 0L) + qty));
            }
            else if (kind == 1)
            {
                long have = h.inventory.getOrDefault(item, 0L);
                if (have <= 0L) continue;
                long selling = Math.min(have, qty);
                if (observe) h.offer(slot, SELLING, item, (int) selling, 0, price, 0);
                h.geInventory(with(h.inventory, item, have - selling));
                if (observe) h.offer(slot, SOLD, item, (int) selling, (int) selling, price, (int) (selling * price));
                h.geInventory(with(h.inventory, COINS, h.inventory.get(COINS) + selling * price));
            }
            else
            {
                if (observe) h.offer(slot, BUYING, item, qty, 0, price, 0);
                if (observe) h.offer(slot, CANCELLED_BUY, item, qty, 0, price, 0);
            }
            slot = (slot + 1) % 8;
        }
        return h.net();
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                flows.add(new Flow(id, name(id), delta.getValue(), price(id), delta.getValue() * price(id),
                    id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * PRE-R5C.2C.6A GE authority: custody is authoritative for GE economics. Ring-explained movements
 * are ancillary evidence; when no claimable custody lifecycle exists they fail closed to an
 * uncounted review row instead of booking a quote-valued cost or automatic proceeds.
 */
public class GeRingAuthorityTest
{
    private static final int LOGS = ItemID.LOGS;
    private static final int RUNE = ItemID.NATURERUNE;
    private static final int COINS = ItemID.COINS;
    private static final long T0 = 1_000_000_000_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void fastFillBuyReserveStaysCustodyNotReview()
    {
        Harness h = new Harness(140);
        // The offer fills before the reserve settle is processed. Owner report 2026-09-28: that coin
        // loss is still this offer's reserve, a neutral custody move, never a Review row.
        h.offer(0, BUYING, LOGS, 5, 0, 140, 0);
        h.offer(0, BOUGHT, LOGS, 5, 5, 140, 700);
        h.settle(with(h.inventory, COINS, 1_000_000L - 700L));

        assertEquals("the reserve never changes Net", 0L, h.net());
        for (Transaction transaction : h.transactions())
        {
            assertFalse("no Review row", ReviewRules.needsOwnerDecision(transaction));
            assertFalse("the reserve is uncounted", transaction.isCounted());
        }

        h.settle(with(h.inventory, COINS, 1_000_000L - 700L, LOGS, 5L));

        assertEquals("authoritative NEW BUY is Net-neutral", 0L, h.net());
        assertEquals("exact spend becomes known coverage", 5L, EngineProbe.knownCoverageQty(h.engine, LOGS));
        assertEquals(700L, EngineProbe.knownCoverageBasisGp(h.engine, LOGS));
        List<Transaction> counted = h.counted();
        assertEquals("only the authoritative settlement is counted", 1, counted.size());
        assertEquals(TransactionType.TRADE, counted.get(0).getType());
        assertEquals("no duplicate spend", 0L, counted.get(0).getNet());
    }

    @Test
    public void unclaimedSellCashFailsClosedToReview()
    {
        Harness h = new Harness(7);
        h.inventory = with(h.inventory, RUNE, 10L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));

        h.offer(0, SELLING, RUNE, 10, 0, 7, 0);
        h.settle(with(h.inventory, RUNE, 0L));
        // The player modifies the offer quantity: no exact realization is provable.
        h.offer(0, SELLING, RUNE, 20, 0, 7, 0);
        h.offer(0, SOLD, RUNE, 20, 10, 7, 70);
        h.settle(with(h.inventory, COINS, 1_000_070L));

        assertEquals("unclaimed cash is never automatic profit", 0L, h.net());
        assertFalse("no basis is mutated by the unclaimed movement", h.hasCountedCoinsOnlyRow());
        assertTrue("the movement is recorded for review", h.reviews() >= 1);
        assertEquals(0L, EngineProbe.knownCoverageQty(h.engine, RUNE));
    }

    @Test
    public void explicitGeBuyClickCannotCountUnclaimedCoinLoss()
    {
        Harness h = new Harness(7);
        h.engine.markContext(Context.MARKET, 10, "Grand Exchange buy");
        h.settle(with(h.inventory, COINS, 999_990L));

        assertEquals(0L, h.net());
        assertFalse(h.hasCountedCoinsOnlyRow());
        assertEquals(1, h.reviews());
        assertEquals(TransactionType.UNCERTAIN, h.transactions().get(0).getType());
    }

    @Test
    public void explicitGeCollectCannotCountUnclaimedCashOrItem()
    {
        Harness h = new Harness(7);
        h.engine.markContext(Context.MARKET, 10, "Grand Exchange collect");
        h.settle(with(h.inventory, COINS, 1_000_010L, RUNE, 5L));

        assertEquals(0L, h.net());
        assertEquals(1, h.reviews());
        assertEquals(0L, EngineProbe.knownCoverageQty(h.engine, RUNE));
        assertTrue(h.counted().isEmpty());
    }

    @Test
    public void shopMarketContextStillCountsItsObservedSpend()
    {
        Harness h = new Harness(7);
        h.engine.markContext(Context.MARKET, 10, "buy shop item");
        h.settle(with(h.inventory, COINS, 999_990L));

        assertEquals(-10L, h.net());
        assertEquals(TransactionType.TRADE, h.counted().get(0).getType());
    }

    @Test
    public void custodyBackedSellIsTheSoleRealization()
    {
        Harness h = new Harness(159);
        h.gain(LOGS, 5L, 775L, h.now - 60_000L);

        h.inventory = with(h.inventory, LOGS, 5L);
        h.engine.setBaseline(new ContainerSnapshot(h.inventory));
        h.offer(0, SELLING, LOGS, 5, 0, 159, 0);
        h.settle(with(h.inventory, LOGS, 0L));
        h.offer(0, SOLD, LOGS, 5, 5, 159, 790);
        h.settle(with(h.inventory, COINS, 1_000_790L));

        assertEquals("the earlier counted value plus the sale result", 790L, h.net());
        List<Transaction> counted = h.counted();
        assertEquals("the gain plus exactly one custody settlement", 2, counted.size());
        Transaction settlement = counted.get(1);
        assertEquals(TransactionType.TRADE, settlement.getType());
        assertEquals("custody books the sale exactly once", 15L, settlement.getNet());
        assertEquals("known coverage is consumed by the reservation", 0L,
            EngineProbe.knownCoverageQty(h.engine, LOGS));
        assertFalse(h.hasCountedCoinsOnlyRow());
    }

    // ---- harness ----------------------------------------------------------------------------

    private static final class Harness
    {
        final int[] quote;
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        long now = T0;
        Map<Integer, Long> inventory = new HashMap<>();

        Harness(int initialQuote)
        {
            quote = new int[] { initialQuote };
            engine = engine(quote);
            engine.startCustom("Trading", now);
            inventory.put(COINS, 1_000_000L);
            engine.setBaseline(new ContainerSnapshot(inventory));
        }

        void gain(int item, long qty, long value, long at)
        {
            engine.getActiveSession().addTransaction(new Transaction(at,
                TransactionType.GAIN, Context.GENERIC, "", "Loot", true,
                Collections.singletonList(new Flow(item, name(item), qty,
                    (int) (qty > 0L ? value / qty : 0L), value, PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED, "", null), 500, false);
        }

        void offer(int slot, GrandExchangeOfferState state, int item, int total, int traded,
            int price, int spent)
        {
            now += 600L;
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent)).orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition, name(transition.current.itemId), now);
            }
        }

        Transaction settle(Map<Integer, Long> next)
        {
            now += 600L;
            inventory = new HashMap<>(next);
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            Transaction result = null;
            for (int i = 0; i < 3; i++)
            {
                Transaction settled = engine.processIfDirty(snapshot, now, null);
                if (settled != null)
                {
                    result = settled;
                }
                now += 600L;
            }
            return result;
        }

        long net()
        {
            return engine.getMetrics(now).net;
        }

        List<Transaction> transactions()
        {
            List<Transaction> out = new ArrayList<>();
            for (Transaction transaction : engine.getActiveSession().getTransactions())
            {
                if (transaction != null)
                {
                    out.add(transaction);
                }
            }
            return out;
        }

        List<Transaction> counted()
        {
            List<Transaction> out = new ArrayList<>();
            for (Transaction transaction : transactions())
            {
                if (transaction.isCounted())
                {
                    out.add(transaction);
                }
            }
            return out;
        }

        int reviews()
        {
            int reviews = 0;
            for (Transaction transaction : transactions())
            {
                if (ReviewRules.needsOwnerDecision(transaction))
                {
                    reviews++;
                }
            }
            return reviews;
        }

        boolean hasCountedCoinsOnlyRow()
        {
            for (Transaction transaction : counted())
            {
                boolean coinsOnly = !transaction.getFlows().isEmpty();
                for (Flow flow : transaction.getFlows())
                {
                    coinsOnly &= flow.itemId == COINS;
                }
                if (coinsOnly)
                {
                    return true;
                }
            }
            return false;
        }
    }

    private static String name(int id)
    {
        return id == COINS ? "Coins" : id == LOGS ? "Logs" : id == RUNE ? "Nature rune" : "Item " + id;
    }

    private static Map<Integer, Long> with(Map<Integer, Long> base, Object... pairs)
    {
        Map<Integer, Long> map = new HashMap<>(base);
        for (int i = 0; i < pairs.length; i += 2)
        {
            long quantity = (Long) pairs[i + 1];
            if (quantity <= 0L)
            {
                map.remove((Integer) pairs[i]);
            }
            else
            {
                map.put((Integer) pairs[i], quantity);
            }
        }
        return map;
    }

    private static Engine engine(int[] quote)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                int unit = id == COINS ? 1 : quote[0];
                PriceSource source = id == COINS ? PriceSource.FACE_VALUE
                    : unit > 0 ? PriceSource.GRAND_EXCHANGE : PriceSource.UNPRICED;
                flows.add(new Flow(id, name(id), delta.getValue(), unit, delta.getValue() * unit,
                    source));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Pre-R5 GE sale classification: a genuine sell placement must own its settled rune loss as
 * TRADE/MARKET across the supported event orderings, while genuine casting stays
 * CONSUMPTION/CAST and a spent placement can never own a later unrelated loss.
 */
public class GeSellClassificationTest
{
    private static final int[] RUNES = {
        ItemID.AIRRUNE, ItemID.NATURERUNE, ItemID.FIRERUNE, ItemID.ASTRALRUNE, ItemID.LAVARUNE, ItemID.STEAMRUNE
    };
    private static final long T0 = 1_000_000_000_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void everySequentialRuneSaleSettlesAsNeutralCustodyNotCast()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L);
        for (int rune : RUNES)
        {
            inventory.put(rune, 5L);
        }
        engine.setBaseline(new ContainerSnapshot(inventory));

        OfferSlots ledger = new OfferSlots();
        for (int i = 0; i < RUNES.length; i++)
        {
            int rune = RUNES[i];
            noteGe(engine, ledger, i, SELLING, rune, 5, 0, 200, 0, now);
            inventory.put(rune, inventory.get(rune) - 1L);
            Transaction sale = settleStable(engine, inventory, now);
            assertNotNull("sale settles: " + name(rune), sale);
            assertEquals("a proven GE sale placement is ownership-neutral custody: " + name(rune),
                TransactionType.TRANSFER, sale.getType());
            assertEquals(Context.TRANSFER, sale.getContext());
            assertFalse("custody is never counted money", sale.isCounted());
            assertNotEquals("a sold rune is never stamped as a cast: " + name(rune),
                ActionKind.CAST, sale.getActionKind());
            assertEquals("the observed sold value is untouched: " + name(rune),
                -200L, sale.getFlows().get(0).valueDelta);
            now += 10_000L;
        }
        assertEquals("pending custody never changes the observed Net",
            0L, engine.getMetrics(now).net);
        assertEquals("no placement fell through to CAST", 0,
            engine.getActiveSession().getTransactions().stream()
                .filter(t -> t != null && ActionKind.CAST == t.getActionKind()).count());
    }

    @Test
    public void coalescedRuneLossesSettleOnceAsNeutralCustody()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L, ItemID.FIRERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, SELLING, ItemID.NATURERUNE, 5, 0, 200, 0, now);
        noteGe(engine, ledger, 1, SELLING, ItemID.FIRERUNE, 5, 0, 100, 0, now);
        inventory.put(ItemID.NATURERUNE, 4L);
        inventory.put(ItemID.FIRERUNE, 4L);

        Transaction sale = settleStable(engine, inventory, now);
        assertNotNull(sale);
        assertEquals(TransactionType.TRANSFER, sale.getType());
        assertFalse(sale.isCounted());
        assertEquals(1, engine.getActiveSession().getTransactions().size());
        assertTrue(sale.getFlows().size() >= 2);
        assertEquals(0L, engine.getMetrics(now).net);
    }

    @Test
    public void offerEvidenceDuringTheDirtyWindowOwnsTheLossAsCustody()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        // The inventory loss goes dirty first; the sell placement evidence arrives before the
        // stable settlement commits.
        inventory.put(ItemID.NATURERUNE, 4L);
        ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
        engine.markDirty();
        engine.processIfDirty(snapshot, now, null);

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, SELLING, ItemID.NATURERUNE, 5, 0, 200, 0, now + 100L);

        Transaction settled = engine.processIfDirty(snapshot, now + 600L, null);
        Transaction finalSettle = engine.processIfDirty(snapshot, now + 1_200L, null);
        Transaction sale = finalSettle == null ? settled : finalSettle;
        assertNotNull(sale);
        assertEquals(TransactionType.TRANSFER, sale.getType());
        assertEquals(Context.TRANSFER, sale.getContext());
        assertFalse(sale.isCounted());
    }

    @Test
    public void claimedSellPlacementCannotOwnALaterUnrelatedLoss()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, SELLING, ItemID.NATURERUNE, 5, 0, 200, 0, now);
        inventory.put(ItemID.NATURERUNE, 4L);
        Transaction sale = settleStable(engine, inventory, now);
        assertNotNull(sale);
        assertEquals("the placement principal is custody", TransactionType.TRANSFER, sale.getType());
        assertFalse(sale.isCounted());

        // A later unrelated same-item loss inside the placement window must not reuse the
        // already-captured placement evidence.
        inventory.put(ItemID.NATURERUNE, 3L);
        Transaction later = settleStable(engine, inventory, now + 5_000L);
        assertNotNull(later);
        assertEquals("a spent placement never owns a later unrelated loss",
            TransactionType.CONSUMPTION, later.getType());
    }

    @Test
    public void stalePlacementEvidenceNeverStealsAnExplicitCast()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, SELLING, ItemID.NATURERUNE, 5, 0, 200, 0, now);
        engine.noteConsume(ItemID.NATURERUNE, 18, false, ActionKind.CAST);
        inventory.put(ItemID.NATURERUNE, 4L);

        Transaction cast = settleStable(engine, inventory, now);
        assertNotNull(cast);
        assertEquals(TransactionType.CONSUMPTION, cast.getType());
        assertEquals("Cast", Semantics.verbOf(cast));
    }

    @Test
    public void soldRunePlacementIsNeutralCustodyAndCastCostIsSupplies()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, SELLING, ItemID.NATURERUNE, 5, 0, 200, 0, now);
        inventory.put(ItemID.NATURERUNE, 4L);
        Transaction sale = settleStable(engine, inventory, now);
        assertNotNull(sale);
        assertEquals("a sold rune placement is ownership-neutral custody, never a cost",
            CostKind.NONE, CostKind.of(sale, sale.getFlows().get(0)));

        engine.noteConsume(ItemID.NATURERUNE, 18, false, ActionKind.CAST);
        inventory.put(ItemID.NATURERUNE, 3L);
        Transaction cast = settleStable(engine, inventory, now + 10_000L);
        assertNotNull(cast);
        assertEquals(TransactionType.CONSUMPTION, cast.getType());
        assertEquals("a genuine cast stays a supply cost",
            CostKind.SUPPLIES, CostKind.of(cast, cast.getFlows().get(0)));
        assertEquals("only the cast remains counted", -200L, engine.getMetrics(now + 10_000L).net);
    }

    @Test
    public void lateOfferEvidenceNeverRewritesABookedSettle()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        // The loss settles before any evidence exists: book once, conservatively.
        inventory.put(ItemID.NATURERUNE, 4L);
        Transaction settled = settleStable(engine, inventory, now);
        assertNotNull(settled);
        assertEquals(TransactionType.CONSUMPTION, settled.getType());
        assertEquals(1, engine.getActiveSession().getTransactions().size());

        // Evidence arriving afterwards must not rewrite the booked row (no retroactive
        // reconciliation), and a later cast must still be a cast.
        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, SELLING, ItemID.NATURERUNE, 5, 0, 200, 0, now + 1_000L);
        assertEquals(1, engine.getActiveSession().getTransactions().size());
        assertEquals(TransactionType.CONSUMPTION, engine.getActiveSession().getTransactions().get(0).getType());

        engine.noteConsume(ItemID.NATURERUNE, 18, false, ActionKind.CAST);
        inventory.put(ItemID.NATURERUNE, 3L);
        Transaction cast = settleStable(engine, inventory, now + 10_000L);
        assertNotNull(cast);
        assertEquals(TransactionType.CONSUMPTION, cast.getType());
        assertEquals("Cast", Semantics.verbOf(cast));
    }

    @Test
    public void exactSpellNameAttachesOnlyToItsMatchedConsumptionIntent()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Vorkath", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        int spellbookGroup = net.runelite.api.gameval.InterfaceID.MAGIC_SPELLBOOK;
        ActionLabel iceBurst = ActionLabel.fromSpellMenu("Cast",
            spellbookGroup << 16 | 14, spellbookGroup, "<col=ff9040>Ice Burst</col>", "Cast");
        assertNotNull(iceBurst);
        engine.noteConsume(ItemID.NATURERUNE, 18, false, ActionKind.CAST, iceBurst);
        inventory.put(ItemID.NATURERUNE, 4L);
        Transaction cast = settleStable(engine, inventory, now);
        assertNotNull(cast);
        assertEquals("Ice Burst", cast.actionLabel().value());

        inventory.put(ItemID.NATURERUNE, 3L);
        Transaction laterLoss = settleStable(engine, inventory, now + 5_000L);
        assertNotNull(laterLoss);
        assertEquals("one matched intent cannot label later rune loss", null,
            laterLoss.actionLabel());
    }

    @Test
    public void unresolvedCastClickCannotRewriteAnArmedSupplyVerb()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Vorkath", now);
        int dragonBones = 536;
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, dragonBones, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        engine.noteConsume(dragonBones, 18, false, ActionKind.BURY, null);
        // A spellbook Cast click can resolve no item id. The open intent must keep the
        // resolved item's proven verb; the exact spell name is a hint, not a re-verb.
        engine.noteConsume(-1, 18, false, ActionKind.CAST,
            ActionLabel.of("Ice Burst"));
        inventory.put(dragonBones, 4L);
        Transaction buried = settleStable(engine, inventory, now);
        assertNotNull(buried);
        assertEquals("a later unresolved Cast click cannot rewrite the buried verb",
            "Buried", Semantics.verbOf(buried));
        assertEquals("buried bones stay a supply cost, not a loss",
            CostKind.SUPPLIES, CostKind.of(buried, buried.getFlows().get(0)));
        assertNull("a Cast click that did not cast cannot name the spell",
            buried.actionLabel());
    }

    @Test
    public void hardTransferEvidenceWinsOverStaleSellPlacement()
    {
        Engine engine = engine();
        long now = T0;
        engine.startCustom("Trading", now);
        Map<Integer, Long> inventory = inventory(ItemID.COINS, 100_000L, ItemID.NATURERUNE, 5L);
        engine.setBaseline(new ContainerSnapshot(inventory));

        OfferSlots ledger = new OfferSlots();
        noteGe(engine, ledger, 0, SELLING, ItemID.NATURERUNE, 5, 0, 200, 0, now);
        engine.markContext(Context.TRANSFER, 6, "Bank container transfer");
        inventory.put(ItemID.NATURERUNE, 4L);

        Transaction deposit = settleStable(engine, inventory, now);
        assertNotNull(deposit);
        assertEquals("hard transfer evidence keeps its own delta", TransactionType.TRANSFER, deposit.getType());
    }

    // ---- helpers ----------------------------------------------------------------------------

    private static void noteGe(
        Engine engine,
        OfferSlots ledger,
        int slot,
        GrandExchangeOfferState state,
        int itemId,
        int totalQuantity,
        int quantityTraded,
        int price,
        int spent,
        long at)
    {
        OfferSlots.Transition transition = ledger.observe(
            new OfferSlots.Snapshot(slot, state, itemId, totalQuantity, quantityTraded, price, spent))
            .orElse(null);
        if (transition != null)
        {
            engine.noteGeOffer(transition, name(itemId), at);
        }
    }

    /** Production stabilization: a dirty change commits only after the configured quiet ticks. */
    private static Transaction settleStable(Engine engine, Map<Integer, Long> next, long now)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(next);
        Transaction result = null;
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(snapshot, now + i * 600L, null);
            if (settled != null)
            {
                result = settled;
            }
        }
        return result;
    }

    private static Map<Integer, Long> inventory(Object... pairs)
    {
        Map<Integer, Long> map = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2)
        {
            map.put((Integer) pairs[i], (Long) pairs[i + 1]);
        }
        return map;
    }

    private static String name(int id)
    {
        if (id == ItemID.COINS)
        {
            return "Coins";
        }
        if (id == ItemID.AIRRUNE)
        {
            return "Air rune";
        }
        if (id == ItemID.NATURERUNE)
        {
            return "Nature rune";
        }
        if (id == ItemID.FIRERUNE)
        {
            return "Fire rune";
        }
        if (id == ItemID.ASTRALRUNE)
        {
            return "Astral rune";
        }
        if (id == ItemID.LAVARUNE)
        {
            return "Lava rune";
        }
        if (id == ItemID.STEAMRUNE)
        {
            return "Steam rune";
        }
        return "Item " + id;
    }

    private static int price(int id)
    {
        return id == ItemID.COINS ? 1 : 200;
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 2; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                flows.add(new Flow(id, name(id), delta.getValue(), price(id), delta.getValue() * price(id),
                    id == ItemID.COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * PR1-PRE-R5C.2C.6A.1A2 owner smoke (G1): a settled sale keeps its durable market record when its
 * slot is reused by a new offer. Reuse used to delete the closed record, so the booked sale lost
 * its market presentation and read as a generic trade of its full item value.
 */
public class GeSlotReuseSettledHistoryTest
{
    private static final int COINS = ItemID.COINS;
    private static final int SHARK = ItemID.SHARK;
    private static final int MITHRIL = ItemID.MITHRIL_BAR;
    private static final long T0 = 1_000_000_000_000L;
    private static final long SHARK_QTY = 30L;
    private static final long SHARK_GROSS = 29_280L;
    private static final long SHARK_TAX = 570L;
    private static final long SHARK_RECEIVED = SHARK_GROSS - SHARK_TAX;
    private static final long MITHRIL_QTY = 30L;
    private static final long MITHRIL_GROSS = 29_340L;
    private static final long MITHRIL_TAX = 570L;
    private static final long MITHRIL_RECEIVED = MITHRIL_GROSS - MITHRIL_TAX;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void settledSaleKeepsItsMarketRecordWhenTheSlotIsReused()
    {
        Fixture fixture = new Fixture();
        long t = T0 + 10_000L;
        String shark = fixture.sellAndCollectAlone(0, SHARK, SHARK_QTY, SHARK_GROSS, SHARK_RECEIVED, t);

        fixture.placeAndSell(0, MITHRIL, MITHRIL_QTY, MITHRIL_GROSS, t + 30_000L);

        MarketRows.Row retired = fixture.rowFor(shark);
        assertNotNull("the settled sale keeps its market record after slot reuse", retired);
        assertEquals(SHARK, retired.itemId);
        assertEquals(MarketRows.Lifecycle.REALIZED, retired.lifecycle);
        assertEquals("Received stays the observed cash", SHARK_RECEIVED, retired.observedSettlementGp);
        assertEquals("the proven tax stays visible", SHARK_TAX, retired.inferredGeTaxGp);
        assertEquals("the new offer is the slot's only live lifecycle", 1, fixture.openRecords(0));
        assertEquals(0, fixture.reviewCount());
    }

    @Test
    public void reusedSlotStillSettlesTheNewOfferExactly()
    {
        Fixture fixture = new Fixture();
        long t = T0 + 10_000L;
        String shark = fixture.sellAndCollectAlone(0, SHARK, SHARK_QTY, SHARK_GROSS, SHARK_RECEIVED, t);
        String mithril = fixture.sellAndCollectAlone(0, MITHRIL, MITHRIL_QTY, MITHRIL_GROSS, MITHRIL_RECEIVED,
            t + 30_000L);

        assertNotNull(fixture.rowFor(shark));
        MarketRows.Row second = fixture.rowFor(mithril);
        assertNotNull("the new offer in the reused slot settles through its own record", second);
        assertEquals(MITHRIL, second.itemId);
        assertEquals(MITHRIL_RECEIVED, second.observedSettlementGp);
        assertEquals(MITHRIL_TAX, second.inferredGeTaxGp);
        assertEquals("two booked sale settlements", 2, fixture.settlementTransactions());
        assertEquals(0, fixture.reviewCount());
        assertEquals("no unattributed Coins row", 0, fixture.unattributedCoinRows());
        assertEquals("Net is exactly the two taxes", -(SHARK_TAX + MITHRIL_TAX), fixture.net(t + 60_000L));
    }

    @Test
    public void settledHistorySurvivesRestartAlongsideTheLiveOffer()
    {
        Fixture fixture = new Fixture();
        long t = T0 + 10_000L;
        String shark = fixture.sellAndCollectAlone(0, SHARK, SHARK_QTY, SHARK_GROSS, SHARK_RECEIVED, t);
        fixture.placeAndSell(0, MITHRIL, MITHRIL_QTY, MITHRIL_GROSS, t + 30_000L);

        SavedState state = fixture.engine.savedState();
        Fixture restored = new Fixture();
        restored.engine.restore(state, t + 40_000L);

        assertNotNull("closed history is restored, not collapsed to one record per slot",
            restored.rowFor(shark));
        assertEquals(1, restored.openRecords(0));
        GeOffer live = restored.openRecord(0);
        assertEquals(MITHRIL, live.itemId);
        assertEquals(MITHRIL_QTY, live.getCapturedQty());
    }

    @Test
    public void closedHistoryIsBoundedByDroppingTheOldestFirst()
    {
        Fixture fixture = new Fixture();
        long t = T0 + 10_000L;
        List<String> settlements = new ArrayList<>();
        int total = GeCustodyLedger.MAX_CLOSED_RECORDS + 3;
        for (int index = 0; index < total; index++)
        {
            settlements.add(fixture.sellAndCollectAlone(0, SHARK, SHARK_QTY, SHARK_GROSS, SHARK_RECEIVED,
                t + index * 20_000L));
        }
        fixture.maintenance(t + total * 20_000L);

        int closed = 0;
        for (GeOffer record : fixture.engine.geCustody.records())
        {
            if (record.getStage() == GeOffer.Stage.CLOSED)
            {
                closed++;
            }
        }
        assertEquals(GeCustodyLedger.MAX_CLOSED_RECORDS, closed);
        assertNull("the oldest closed record is the one dropped", fixture.rowFor(settlements.get(0)));
        assertNotNull("the newest closed record is kept", fixture.rowFor(settlements.get(total - 1)));
        assertEquals("every sale stays booked", total, fixture.settlementTransactions());
    }

    // ── fixture ────────────────────────────────────────────────────────────────────────────────

    private static long reference(int itemId)
    {
        return itemId == SHARK ? 978L : itemId == MITHRIL ? 984L : 6L;
    }

    private static String name(int itemId)
    {
        return itemId == SHARK ? "Shark" : itemId == MITHRIL ? "Mithril bar" : "Item " + itemId;
    }

    private static final class Fixture
    {
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        final Map<Integer, Long> inventory = new HashMap<>();

        Fixture()
        {
            engine = new Engine(deltas ->
            {
                List<Flow> flows = new ArrayList<>();
                for (Map.Entry<Integer, Long> delta : deltas.entrySet())
                {
                    int id = delta.getKey();
                    long unit = id == COINS ? 1L : reference(id);
                    flows.add(new Flow(id, id == COINS ? "Coins" : name(id), delta.getValue(),
                        (int) unit, delta.getValue() * unit,
                        id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE));
                }
                return flows;
            }, new TransactionClassifier(), new GpManagerConfig()
            {
                @Override
                public Retention receiptRetentionDays()
                {
                    return Retention.DAYS_365;
                }

                @Override
                public int stabilizationTicks()
                {
                    return 0;
                }
            });
            engine.startCustom("Trading", T0);
            inventory.put(COINS, 1_000_000L);
            engine.setBaseline(new ContainerSnapshot(inventory));
        }

        void placeAndSell(int slot, int item, long qty, long gross, long at)
        {
            inventory.put(item, qty);
            engine.setBaseline(new ContainerSnapshot(inventory));
            offer(slot, SELLING, item, (int) qty, 0, (int) reference(item), 0, at);
            inventory.put(item, 0L);
            settleAt(at + 100L);
            offer(slot, SOLD, item, (int) qty, (int) qty, (int) reference(item), (int) gross, at + 200L);
        }

        /** List, sell and collect only this slot; returns the booked settlement transaction id. */
        String sellAndCollectAlone(int slot, int item, long qty, long gross, long received, long at)
        {
            placeAndSell(slot, item, qty, gross, at);
            long collectAt = at + 10_000L;
            offer(slot, EMPTY, item, 0, 0, 0, 0, collectAt - 600L);
            engine.noteGeCollect(collectAt);
            inventory.put(COINS, inventory.getOrDefault(COINS, 0L) + received);
            settleAt(collectAt);
            GeOffer record = openOrClosedRecord(slot, item);
            assertNotNull("the collected offer has a record", record);
            assertFalse("the single collect settled the offer", record.getSettlementId().isEmpty());
            return record.getSettlementId();
        }

        void maintenance(long at)
        {
            for (Transaction booking : engine.geCustody.maintenance(at,
                engine.getActiveSession().getId()))
            {
                engine.getActiveSession().addTransaction(booking, 500, true);
            }
        }

        private void offer(int slot, GrandExchangeOfferState state, int item, int total, int traded,
            int price, int spent, long at)
        {
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent)).orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition, name(item), at);
            }
        }

        private void settleAt(long at)
        {
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            engine.processIfDirty(snapshot, at, null);
            engine.processIfDirty(snapshot, at + 1L, null);
        }

        MarketRows.Row rowFor(String settlementId)
        {
            for (MarketRows.Row row : engine.marketRows())
            {
                if (settlementId.equals(row.settlementId))
                {
                    return row;
                }
            }
            return null;
        }

        GeOffer openOrClosedRecord(int slot, int item)
        {
            GeOffer found = null;
            for (GeOffer record : engine.geCustody.records())
            {
                if (record.slot == slot && record.itemId == item)
                {
                    found = record;
                }
            }
            return found;
        }

        GeOffer openRecord(int slot)
        {
            for (GeOffer record : engine.geCustody.records())
            {
                if (record.slot == slot && record.getStage() != GeOffer.Stage.CLOSED)
                {
                    return record;
                }
            }
            return null;
        }

        int openRecords(int slot)
        {
            int open = 0;
            for (GeOffer record : engine.geCustody.records())
            {
                if (record.slot == slot && record.getStage() != GeOffer.Stage.CLOSED)
                {
                    open++;
                }
            }
            return open;
        }

        int settlementTransactions()
        {
            int count = 0;
            for (Transaction transaction : engine.getActiveSession().getTransactions())
            {
                if (transaction.autoType() == TransactionType.TRADE && transaction.isCounted())
                {
                    count++;
                }
            }
            return count;
        }

        int reviewCount()
        {
            int reviews = 0;
            for (Transaction transaction : engine.getActiveSession().getTransactions())
            {
                if (ReviewRules.needsOwnerDecision(transaction))
                {
                    reviews++;
                }
            }
            return reviews;
        }

        int unattributedCoinRows()
        {
            int rows = 0;
            for (Transaction transaction : engine.getActiveSession().getTransactions())
            {
                if (transaction.autoType() == TransactionType.UNCERTAIN
                    && transaction.getFlows().size() == 1
                    && transaction.getFlows().get(0).itemId == COINS)
                {
                    rows++;
                }
            }
            return rows;
        }

        long net(long at)
        {
            return engine.getMetrics(at).net;
        }
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * PR1-PRE-R5C.2C.6A.1B: an unknown-basis GE sale whose ACTUAL tax is proven contributes exactly
 * that tax to Net (a Market cost) while its Result stays unknown. Exempt, unproven, pre-change and
 * corrected sales keep their existing automatic contribution, and every correction replaces the
 * tax instead of stacking on it.
 */
public class GeUnknownBasisTaxNetTest
{
    private static final int COINS = ItemID.COINS;
    private static final int VIAL = ItemID.VIAL_BLOOD;
    private static final int AMETHYST_ARROW = ItemID.AMETHYST_ARROW;
    private static final int CHICKEN = ItemID.COOKED_CHICKEN;
    private static final int RUNE = ItemID.NATURERUNE;
    private static final int CHAOS = ItemID.CHAOSRUNE;
    private static final long T0 = 1_000_000_000_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    // ── the fixtures ───────────────────────────────────────────────────────────────────────────

    @Test
    public void unknownBasisProvenTaxBooksExactlyTheTaxAndStaysUnknown()
    {
        Market market = new Market();
        market.prices.put(VIAL, 8_536L);
        market.sellUnknown(0, VIAL, 4L, 8_536, 33_804, 33_128);

        MarketRows.Row row = market.row(VIAL);
        assertEquals(4L, row.settledQty);
        assertEquals("Received is the actual after-tax cash", 33_128L, row.observedSettlementGp);
        assertEquals(33_804L, MarketFacts.realizedGrossGp(MarketFacts.record(market.engine, row)));
        assertEquals(-676L, row.settlementAdjustmentGp);
        assertEquals(676L, row.inferredGeTaxGp);
        assertEquals(8_282L, row.receivedEachGp);
        assertEquals(MarketRows.Coverage.FULLY_UNKNOWN, row.coverage);
        assertEquals("coverage is genuinely unknown", 0L, MarketFacts.trackedQtyConsumed(MarketFacts.record(market.engine, row)));
        assertTrue("the booked state is KNOWN_COST_ONLY", row.knownCostOnly);
        assertTrue(row.realizedResultCorrectionAware);
        assertEquals("the booked Net contribution is exactly -tax", -676L, row.realizedResultGp);

        Transaction settlement = market.transaction(row.settlementId);
        assertNotNull(settlement);
        assertTrue("one counted MARKET settlement", settlement.isCounted());
        assertEquals(TransactionType.TRADE, settlement.getType());
        assertEquals(Correction.AUTO, settlement.getCorrection());
        assertEquals("automatic Net is exactly -accepted tax", -676L, settlement.getNet());
        assertEquals(-33_804L, flow(settlement, VIAL));
        assertEquals(33_128L, flow(settlement, COINS));
        assertNoSyntheticTaxFlow(settlement);

        assertEquals("exactly one counted settlement exists", 1, market.counted());
        assertEquals("the tax lands in the Market result", -676L,
            Accounting.marketFold(market.transactions()).getNet());
        assertEquals("Live/grind Net reads the same booked transaction", -676L, market.net());
        assertEquals("the row shows the collected cash", 33_128L, row.observedSettlementGp);
    }

    @Test
    public void exemptUnknownSaleStaysNetZeroWithoutATax()
    {
        Market market = new Market();
        market.prices.put(CHICKEN, 66L);
        market.sellUnknown(0, CHICKEN, 5L, 69, 315, 315);

        MarketRows.Row row = market.row(CHICKEN);
        assertEquals(MarketRows.Coverage.FULLY_UNKNOWN, row.coverage);
        assertEquals("an exempt item never proves a tax", 0L, row.inferredGeTaxGp);
        assertFalse(row.knownCostOnly);
        assertEquals(0L, row.realizedResultGp);
        assertEquals(0L, market.net());
        assertEquals("an exempt sale stays uncounted", 0, market.counted());
    }

    @Test
    public void knownBasisSaleCountsTheResultWithoutASecondTax()
    {
        Market market = new Market();
        market.prices.put(RUNE, 420L);
        gain(market.engine, RUNE, 13L, 5_000L, market.now - 60_000L);
        market.sellUnknown(0, RUNE, 13L, 420, 5_460, 5_356);

        MarketRows.Row row = market.row(RUNE);
        assertEquals(MarketRows.Coverage.FULLY_KNOWN, row.coverage);
        assertEquals(104L, row.inferredGeTaxGp);
        assertEquals(5_000L, row.trackedBasisConsumedGp);
        assertEquals("Result = after-tax Received - proven basis", 356L, row.realizedResultGp);
        assertFalse("a full result is never KNOWN_COST_ONLY", row.knownCostOnly);
        assertEquals("Net = Result; no separate tax contribution", 356L,
            Accounting.marketFold(market.transactions()).getNet());
        assertEquals("the earlier counted gain plus the sale Result", 5_356L, market.net());
        assertNoSyntheticTaxFlow(market.transaction(row.settlementId));
    }

    @Test
    public void exemptAndKnownBasisFlowsAreUnchangedSoTheirPreviewsStayIdentical()
    {
        Market exempt = new Market();
        exempt.prices.put(CHICKEN, 66L);
        exempt.sellUnknown(0, CHICKEN, 5L, 69, 315, 315);
        Transaction exemptSettlement =
            exempt.transaction(exempt.row(CHICKEN).settlementId);
        assertEquals("the exempt booking keeps the frozen-reference flow exactly", -330L,
            flow(exemptSettlement, CHICKEN));
        assertEquals(315L, flow(exemptSettlement, COINS));
        assertFalse(exemptSettlement.isCounted());
        assertEquals(0L, exemptSettlement.netUnder(Correction.AUTO));

        Market known = new Market();
        known.prices.put(RUNE, 420L);
        gain(known.engine, RUNE, 13L, 5_000L, known.now - 60_000L);
        known.sellUnknown(0, RUNE, 13L, 420, 5_460, 5_356);
        Transaction knownSettlement = known.transaction(known.row(RUNE).settlementId);
        assertEquals("the known-basis booking keeps its consumed-basis flow exactly", -5_000L,
            flow(knownSettlement, RUNE));
        assertEquals(5_356L, flow(knownSettlement, COINS));
        assertTrue(knownSettlement.isCounted());
        assertEquals(356L, knownSettlement.netUnder(Correction.AUTO));
    }

    @Test
    public void amethystArrowFixtureCountsItsTaxOnce()
    {
        Market market = new Market();
        market.prices.put(AMETHYST_ARROW, 137L);
        market.sellUnknown(0, AMETHYST_ARROW, 110L, 137, 15_070, 14_850);

        MarketRows.Row row = market.row(AMETHYST_ARROW);
        assertEquals(220L, row.inferredGeTaxGp);
        assertEquals(135L, row.receivedEachGp);
        assertTrue(row.knownCostOnly);
        assertEquals(-220L, row.realizedResultGp);
        assertEquals(-220L, market.net());
        assertEquals(1, market.counted());
    }

    // ── corrections and undo ───────────────────────────────────────────────────────────────────

    @Test
    public void correctPreviewsKeepTheFormulaWithOnlyTheAllowedFlowDifference()
    {
        Market market = new Market();
        market.prices.put(VIAL, 8_536L);
        market.sellUnknown(0, VIAL, 4L, 8_536, 33_804, 33_128);
        Transaction settlement = market.transaction(market.row(VIAL).settlementId);

        // The 804fa72 shape: an uncounted unknown-basis sale with the item flow at the frozen
        // reference (4 x 8,536) and the same observed Received cash.
        Transaction before = new Transaction(market.now - 1_000L,
            TransactionType.TRADE, Context.MARKET, "Grand Exchange", "Market", false,
            java.util.Arrays.asList(
                new Flow(VIAL, name(VIAL), -4L, 8_536, -34_144L, PriceSource.GRAND_EXCHANGE),
                new Flow(COINS, "Coins", 33_128L, 1, 33_128L, PriceSource.FACE_VALUE)),
            Confidence.CONFIRMED, "", null);

        assertEquals("804fa72 REVENUE preview", 33_128L + 34_144L, before.netUnder(Correction.REVENUE));
        assertEquals("after REVENUE preview", 33_128L + 33_804L, settlement.netUnder(Correction.REVENUE));
        assertEquals("the difference is exactly the §4a flow valuation",
            -(34_144L - 33_804L),
            settlement.netUnder(Correction.REVENUE)
                - before.netUnder(Correction.REVENUE));
        assertEquals("COST", -(33_128L + 33_804L), settlement.netUnder(Correction.COST));
        assertEquals("TRANSFER is unchanged", 0L, settlement.netUnder(Correction.TRANSFER));
        assertEquals("IGNORE is unchanged", 0L, settlement.netUnder(Correction.IGNORE));
        assertEquals("the automatic contribution itself is -acknowledged tax",
            -676L, settlement.getNet());
    }

    @Test
    public void everyCorrectionReplacesTheTaxAndUndoRestoresItExactly()
    {
        for (Correction correction : new Correction[] {
            Correction.REVENUE, Correction.COST,
            Correction.TRANSFER, Correction.IGNORE})
        {
            Market market = new Market();
            market.prices.put(VIAL, 8_536L);
            market.sellUnknown(0, VIAL, 4L, 8_536, 33_804, 33_128);
            String settlementId = market.row(VIAL).settlementId;
            Transaction settlement = market.transaction(settlementId);
            long expectedAfter = settlement.netUnder(correction);

            assertEquals(-676L, market.net());
            assertTrue(market.engine.correctTransaction(settlementId, correction, market.now + 5_000L,
                "test " + correction));
            assertEquals("the correction REPLACES the automatic tax (never stacks)",
                expectedAfter, market.net());
            MarketRows.Row corrected = market.row(VIAL);
            assertNotEquals(Correction.AUTO,
                market.engine.transactionById(corrected.settlementId).getCorrection());
            assertFalse("a corrected sale is no longer KNOWN_COST_ONLY",
                corrected.knownCostOnly);
            assertEquals(expectedAfter, corrected.realizedResultGp);
            assertEquals("no second tax contribution appears",
                expectedAfter, Accounting.marketFold(market.transactions()).getNet());

            assertTrue(market.engine.undoCorrection(market.now + 6_000L));
            assertEquals("Undo restores exactly -accepted tax", -676L, market.net());
            MarketRows.Row undone = market.row(VIAL);
            assertTrue("the automatic booked state returns", undone.knownCostOnly);
            assertEquals(-676L, undone.realizedResultGp);
            assertEquals(Correction.AUTO, market.transaction(settlementId).getCorrection());
        }
    }

    @Test
    public void transferAndIgnoreCorrectionsZeroTheContribution()
    {
        Market market = new Market();
        market.prices.put(VIAL, 8_536L);
