    private static long flow(Transaction transaction, int itemId)
    {
        for (Flow itemFlow : transaction.getFlows())
        {
            if (itemFlow.itemId == itemId)
            {
                return itemFlow.valueDelta;
            }
        }
        return 0L;
    }

    private static void assertNoSyntheticTaxFlow(Transaction transaction)
    {
        assertNotNull(transaction);
        for (Flow flow : transaction.getFlows())
        {
            assertTrue("no synthetic GE tax flow may be booked",
                flow.itemId != CostKind.GE_TAX_ITEM_ID);
        }
    }

    private static void gain(Engine engine, int item, long quantity, long value, long at)
    {
        engine.getActiveSession().addTransaction(new Transaction(at,
            TransactionType.GAIN, Context.GENERIC, "", "Loot", true,
            Collections.singletonList(new Flow(item, name(item), quantity,
                (int) (quantity > 0L ? value / quantity : 0L), value,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "", null), 500, false);
    }

    private static String name(int itemId)
    {
        switch (itemId)
        {
            case VIAL: return "Vial of blood";
            case AMETHYST_ARROW: return "Amethyst arrow";
            case CHICKEN: return "Cooked chicken";
            case RUNE: return "Nature rune";
            default: return "Item " + itemId;
        }
    }

    /** A real engine with per-item frozen references and offline GE offer observations. */
    private static final class Market
    {
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        final Map<Integer, Long> prices = new HashMap<>();
        final Map<Integer, Long> inventory = new HashMap<>();
        long now = T0;

        Market()
        {
            engine = new Engine(deltas ->
            {
                List<Flow> flows = new ArrayList<>();
                for (Map.Entry<Integer, Long> delta : deltas.entrySet())
                {
                    int id = delta.getKey();
                    long unit = id == COINS ? 1L : prices.getOrDefault(id, 0L);
                    PriceSource source = id == COINS ? PriceSource.FACE_VALUE
                        : unit > 0L ? PriceSource.GRAND_EXCHANGE : PriceSource.UNPRICED;
                    flows.add(new Flow(id, id == COINS ? "Coins" : name(id), delta.getValue(),
                        (int) unit, delta.getValue() * unit, source));
                }
                return flows;
            }, new TransactionClassifier(), new GpManagerConfig()
            {
                @Override
                public Retention receiptRetentionDays()
                {
                    return Retention.DAYS_365;
                }
            });
            engine.startCustom("Trading", now);
            inventory.put(COINS, 1_000_000L);
        }

        /** Place a SELL offer for pre-existing (unknown-coverage) stock and collect its cash. */
        void sellUnknown(int slot, int item, long qty, long listedPrice, long gross, long received)
        {
            sellUnknown(slot, item, qty, listedPrice, gross, received, false);
        }

        /** {@code collect}: the coins arrive after a Collect click, as they do in the game. */
        void sellUnknown(int slot, int item, long qty, long listedPrice, long gross, long received,
            boolean collect)
        {
            inventory.put(item, qty);
            engine.setBaseline(new ContainerSnapshot(inventory));
            offer(slot, SELLING, item, (int) qty, 0, (int) listedPrice, 0);
            inventory.put(item, 0L);
            settle();
            offer(slot, SOLD, item, (int) qty, (int) qty, (int) listedPrice, (int) gross);
            if (collect) engine.noteGeCollect(now);
            inventory.put(COINS, inventory.getOrDefault(COINS, 0L) + received);
            settle();
        }

        void offer(int slot, GrandExchangeOfferState state, int item, int total, int traded,
            int price, int spent)
        {
            now += 5_000L;
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent))
                .orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition, name(item), now);
            }
        }

        void settle()
        {
            now += 5_000L;
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            for (int i = 0; i < 3; i++)
            {
                engine.processIfDirty(snapshot, now, null);
                now += 1_000L;
            }
        }

        MarketRows.Row row(int itemId)
        {
            for (MarketRows.Row row : engine.marketRows())
            {
                if (row.itemId == itemId)
                {
                    return row;
                }
            }
            throw new AssertionError("no market row for " + itemId);
        }

        Transaction transaction(String id)
        {
            Session session = engine.getActiveSession();
            return session == null ? null : session.findTransaction(id);
        }

        List<Transaction> transactions()
        {
            Session session = engine.getActiveSession();
            return session == null ? Collections.emptyList() : session.getTransactions();
        }

        int counted()
        {
            int counted = 0;
            for (Transaction transaction : transactions())
            {
                if (transaction != null && transaction.isCounted())
                {
                    counted++;
                }
            }
            return counted;
        }

        long net()
        {
            return engine.getMetrics(now + 1_000L).net;
        }
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
