package com.gpmanager;

import com.google.gson.Gson;
import java.util.*;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Dropped items and fired ammo stay on the paid-price record while they can still be picked up,
 * and leave it when the pickup window closes: only what nobody picked up is used up.
 */
public class GroundBasisTest
{
    private static final int BOLTS = 9140;
    private static final int DART = 807;
    private static final long WINDOW_TICKS = 300;

    static
    {
        JsonCodec.bind(new Gson());
    }

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, id == DART ? "Iron dart" : "Iron bolts",
            quantity, 10, quantity * 10, PriceSource.GRAND_EXCHANGE)));
        return flows;
    };

    private long now = 1_000L;

    private static ContainerSnapshot pack(int itemId, long quantity)
    {
        return new ContainerSnapshot(Collections.singletonMap(itemId, quantity));
    }

    private void settle(Engine engine, ContainerSnapshot snapshot)
    {
        engine.markDirty();
        for (int tick = 0; tick < 4; tick++) engine.processIfDirty(snapshot, now += 600L, null);
    }

    private void wait(Engine engine, ContainerSnapshot snapshot, long ticks)
    {
        for (long tick = 0; tick < ticks; tick++) engine.processIfDirty(snapshot, now += 600L, null);
    }

    /** Ten counted bolts (known coverage 10), then three dropped. */
    private Engine droppedThree()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(now);
        engine.setBaseline(ContainerSnapshot.empty());
        settle(engine, pack(BOLTS, 10L));
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, BOLTS));
        engine.noteDrop(BOLTS, 6);
        settle(engine, pack(BOLTS, 7L));
        Transaction drop = engine.getActiveSession().getTransactions().get(1);
        assertEquals("Dropped", drop.getNote());
        assertTrue(drop.isOnGround());
        return engine;
    }

    @Test
    public void aDropLeavesTheRecordOnlyWhenItsPickupWindowCloses()
    {
        Engine engine = droppedThree();
        assertEquals("still on the ground", 10L, EngineProbe.knownCoverageQty(engine, BOLTS));
        wait(engine, pack(BOLTS, 7L), WINDOW_TICKS);
        assertEquals("never picked up: used up", 7L, EngineProbe.knownCoverageQty(engine, BOLTS));
        assertFalse(engine.getActiveSession().getTransactions().get(1).isOnGround());
    }

    @Test
    public void aDropPickedBackUpNeverLeavesTheRecord()
    {
        Engine engine = droppedThree();
        settle(engine, pack(BOLTS, 10L));
        wait(engine, pack(BOLTS, 10L), WINDOW_TICKS);
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void aPartPickedUpLeavesOnlyTheRest()
    {
        Engine engine = droppedThree();
        settle(engine, pack(BOLTS, 9L));
        wait(engine, pack(BOLTS, 9L), WINDOW_TICKS);
        assertEquals("one bolt stayed on the ground", 9L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void aRestartSettlesWhatWasStillOnTheGround()
    {
        Engine engine = droppedThree();
        Gson gson = JsonCodec.gson();
        SavedState saved = gson.fromJson(gson.toJson(engine.savedState()), SavedState.class);
        Engine restarted = new Engine(valuator, new TransactionClassifier(), CONFIG);
        restarted.restore(saved, now);
        assertEquals(10L, EngineProbe.knownCoverageQty(restarted, BOLTS));
        restarted.processIfDirty(pack(BOLTS, 7L), now += 600L, null);
        assertEquals("its pickup memory did not survive", 7L, EngineProbe.knownCoverageQty(restarted, BOLTS));
    }

    @Test
    public void aDropCompactedWhileOnTheGroundStillLeavesTheRecord()
    {
        Engine engine = droppedThree();
        engine.getActiveSession().compactBefore(now + 1L, null);
        assertTrue(engine.getActiveSession().getTransactions().isEmpty());
        assertEquals(7L, EngineProbe.knownCoverageQty(engine, BOLTS));
        wait(engine, pack(BOLTS, 7L), WINDOW_TICKS);
        assertEquals("settled once", 7L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void anUndoneDropNeverLeavesTheRecord()
    {
        Engine engine = droppedThree();
        assertNotNull(engine.getActiveSession().undoTransaction());
        wait(engine, pack(BOLTS, 7L), WINDOW_TICKS);
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, BOLTS));
    }

    @Test
    public void dartsACheckMeasuredLeaveTheRecordAtOnce()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(now);
        engine.setBaseline(ContainerSnapshot.empty());
        settle(engine, pack(DART, 10L));
        assertEquals(10L, EngineProbe.knownCoverageQty(engine, DART));
        ChargeDelta delta = new ChargeDelta(ChargeCheck.ChargedItem.BLOWPIPE,
            Collections.singletonList(new ChargeDelta.ComponentDelta(DART, -4L)), ChargeDelta.CheckResult.SPEND);
        Transaction spent = engine.bookChargeSpend(delta, "Toxic blowpipe",
            Collections.singletonList(new Flow(DART, "Iron dart", -4L, 10, -40L, PriceSource.GRAND_EXCHANGE)),
            now, null);
        assertNotNull(spent);
        assertFalse("a measured spend is not on the ground", spent.isOnGround());
        assertEquals(6L, EngineProbe.knownCoverageQty(engine, DART));
    }

    @Test
    public void onlyRowsOnTheGroundCarryTheFlagInASave()
    {
        Engine engine = droppedThree();
        String json = JsonCodec.gson().toJson(engine.getActiveSession());
        assertEquals("one row on the ground", 1, json.split("\"onGround\"", -1).length - 1);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner live test 2026-10-12/13: emptying an essence pouch right before an altar craft made the
 * custody evidence neutralize the whole settle, hiding the crafted runes; depositing runes at
 * the rift's deposit pool booked a bogus Cast. The pouch owns only its essence; the craft's
 * runes classify normally, and the deposit pool is a bank move.
 */
public class GuardiansOfTheRiftBookingTest
{
    private static final int ESSENCE = ItemID.GOTR_GUARDIAN_ESSENCE;
    private static final int PURE_ESSENCE = ItemID.BLANKRUNE_HIGH;
    private static final int FIRE_RUNE = ItemID.FIRERUNE;
    private static final int STONE = ItemID.GOTR_GUARDIAN_STONE_ELEMENTAL;

    private static final Map<Integer, String> NAMES = Map.of(
        ESSENCE, "Guardian essence", PURE_ESSENCE, "Pure essence", FIRE_RUNE, "Fire rune",
        STONE, "Elemental guardian stone");
    private static final Map<Integer, Integer> PRICES = Map.of(
        ESSENCE, 30, PURE_ESSENCE, 5, FIRE_RUNE, 5, STONE, 30);

    private static final String POUCH_CUSTODY = "Container empty_to_inventory (essence_pouch)";
    private static final String DEPOSIT_POOL = "Deposit pool transfer";

    private static Engine engine()
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, NAMES.get(id), quantity, PRICES.get(id),
                quantity * PRICES.get(id))));
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
        });
        engine.ensureSession(1_000_000L);
        return engine;
    }

    private static Engine settle(
        Map<Integer, Long> before, Map<Integer, Long> after, String custodyNote)
    {
        Engine engine = engine();
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        if (custodyNote != null) engine.markContext(Context.TRANSFER, 6, custodyNote);
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    @Test
    public void aCraftInThePouchCustodyStillBooksItsRunes()
    {
        // The live shape: the pouch was emptied, then the craft consumed the essence and produced
        // runes plus a guardian stone. The strip removes the minigame items (essence, stone); the
        // custody must not swallow the runes with them.
        Engine engine = settle(Map.of(ESSENCE, 1L), Map.of(FIRE_RUNE, 132L, STONE, 40L), POUCH_CUSTODY);
        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertTrue(rows.get(0).isCounted());
        assertEquals(132L * 5L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void thePouchEmptyItselfStaysNeutral()
    {
        // Pure essence has no minigame strip: the custody removal itself keeps the move neutral.
        Engine engine = settle(Map.of(), Map.of(PURE_ESSENCE, 28L), POUCH_CUSTODY);
        assertTrue(engine.getActiveSession().getTransactions().toString(),
            engine.getActiveSession().getTransactions().isEmpty());
        assertEquals(0L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void aMergedEmptyAndCraftSplitsIntoTheRunesOnly()
    {
        // Empty (28 essence) and craft (24 essence used) inside one window: the net essence +4 is
        // the pouch's own leftover and stays neutral; the runes are the craft's real gain.
        Engine engine = settle(Map.of(), Map.of(PURE_ESSENCE, 4L, FIRE_RUNE, 96L), POUCH_CUSTODY);
        List<Transaction> rows = engine.getActiveSession().getTransactions();
        assertEquals(rows.toString(), 1, rows.size());
        assertTrue(rows.get(0).isCounted());
        assertEquals(96L * 5L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void aCraftWithoutCustodyStaysACountedGain()
    {
        // The control: with no pouch click in the window the runes were already the one gain.
        Engine engine = settle(Map.of(ESSENCE, 1L), Map.of(FIRE_RUNE, 132L, STONE, 40L), null);
        assertEquals(132L * 5L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void theDepositPoolDepositBooksNoCast()
    {
        // "Deposit-runes" on the deposit pool marks a custody transfer (neutral_transfers.tsv):
        // the runes leave for the bank and nothing counts, instead of a rune-only Cast.
        Engine engine = settle(Map.of(FIRE_RUNE, 253L), Map.of(), DEPOSIT_POOL);
        assertFalse(engine.getActiveSession().getTransactions().stream().anyMatch(Transaction::isCounted));
        assertEquals(0L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void theDepositPoolNoteComesFromItsTableRow()
    {
        // The plugin hands the joined menu text to NeutralTransfers; the row's note is this text.
        assertEquals(DEPOSIT_POOL, NeutralTransfers.storage("Deposit-runes Deposit Pool"));
    }
}

