/**
 * Owner 1.3.3 (in-game test): a herb box is worth nothing until opened, like a reward casket. Each
 * Take-one counts its herb; Bank-all only says how many went to the bank, so it counts nothing.
 */
public class HerbBoxTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(id == ItemID.NZONE_HERBBOX
            ? new Flow(id, "Herb box", quantity, 0, 0L, PriceSource.DEFERRED_CLAIM, 0L)
            : new Flow(id, "Grimy marrentill", quantity, 228, quantity * 228)));
        return flows;
    };

    @Test
    public void theBoxIsAClaimUntilOpened()
    {
        assertTrue(GameData.pattern("clue").matcher("herb box").matches());
        assertTrue(ActionReader.isClaim("Herb box"));
    }

    @Test
    public void everyTakeOneCountsItsHerbWithoutReview()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(1L, 0L));
        assertEquals(TransactionType.GAIN, settle(engine, snapshot(1L, 1L), 1_600L).getType());
        assertEquals("the last herb empties the box", TransactionType.GAIN, settle(engine, snapshot(0L, 2L), 6_000L).getType());
        assertEquals(456L, engine.getMetrics(20_000L).net);
        assertEquals(0, engine.getReviewRows(20_000L).size());
    }

    private static ContainerSnapshot snapshot(long boxes, long herbs)
    {
        Map<Integer, Long> held = new HashMap<>();
        if (boxes > 0) held.put(ItemID.NZONE_HERBBOX, boxes);
        if (herbs > 0) held.put(ItemID.UNIDENTIFIED_MARENTILL, herbs);
        return new ContainerSnapshot(held);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        Transaction row = null;
        for (long t = firstTick; row == null && t < firstTick + 4_000L; t += 600L) row = engine.processIfDirty(snapshot, t, null);
        return row;
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import net.runelite.api.ItemComposition;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Owner 2026-10-09 (1.3.0): imbuing keeps an item's worth, so an imbued black mask or slayer helmet
 * is worth the plain black mask and an NMZ imbue nets nothing. The Amulet of the damned degrades
 * like Barrows gear (a neutral swap) and is worth its full self until it turns to dust, when its
 * worth counts as used up (OSRS Wiki).
 */
public class ImbueAndDamnedTest
{
    private final Valuation valuation = ModelProbe.valuation(new GpManagerConfig() { }, ImbueAndDamnedTest::composition,
        id -> id == 8921 ? 1_000_000 : id == 12851 ? 29_000 : 0);

    @Test
    public void imbuedMasksAndHelmetsAreWorthThePlainMask()
    {
        for (int imbued : new int[] {11784, 11774, 25276, 26771, 11865, 25177, 26674})
        {
            assertEquals("item " + imbued, 1_000_000, valuation.valueComponent(imbued, 1L, 0L).unitPrice);
        }
    }

    @Test
    public void theAmuletOfTheDamnedWearsLikeBarrowsAndIsWorthItsFullSelf()
    {
        assertEquals(29_000, valuation.valueComponent(12853, 1L, 0L).unitPrice);
        String full = Engine.piece(new Flow(12851, "Amulet of the Damned (full)", -1L, 29_000, -29_000L));
        assertNotNull(full);
        assertEquals("the same piece degrading", full, Engine.piece(new Flow(12853, "Amulet of the Damned", 1L, 29_000, 29_000L)));
    }

    private static ItemComposition composition(int id)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) -> {
                if ("getName".equals(method.getName())) return "Item " + id;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return "isTradeable".equals(method.getName());
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Imbuing keeps an item's worth: X to X(i)/(ei)/(ri) swaps are neutral, the imbued leg prices
 * from its plain item where a quote exists, and lookalike pairs stay (Muse review, owner
 * 2026-10-12).
 */
public class ImbueSwapTest
{
    private static final int DAMNED = 12851;
    private static final int DAMNED_DUST = 12853;

    @Test
    public void everyImbuedFamilySwapIsNeutral()
    {
        assertSwapped(ItemID.NZONE_SALVE_AMULET, 4081);
