    @Test
    public void aPointsImbueDropsThePairButKeepsARealCost()
    {
        // The NMZ/Soul Wars imbues consume no items; a rune lost in the same settle still books.
        Engine engine = settle(mapOf(ItemID.RING_OF_WEALTH, 1L, ItemID.NATURERUNE, 1L),
            mapOf(ItemID.RING_OF_WEALTH_I, 1L));
        for (Transaction row : engine.getActiveSession().getTransactions())
        {
            for (Flow flow : row.getFlows())
            {
                assertTrue("the imbue pair never books: " + flow.itemId,
                    flow.itemId != ItemID.RING_OF_WEALTH && flow.itemId != ItemID.RING_OF_WEALTH_I);
            }
        }
        assertEquals(-300L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void theDamnedDegradeBooksNothing()
    {
        Engine engine = settle(mapOf(DAMNED, 1L), mapOf(DAMNED_DUST, 1L));
        assertTrue(engine.getActiveSession().getTransactions().toString(),
            engine.getActiveSession().getTransactions().isEmpty());
        assertEquals(0L, engine.getMetrics(1_010_000L).net);
    }

    @Test
    public void theSailorsAmuletStateSwapIsNeutral()
    {
        // Charging the sailors' amulet turns its inert state into the charged one; the pair is the
        // same worth. The armed use-on load books nothing (owner 2026-10-14: its charges measure
        // through the amulet's Check); this no-intent settle is the fail-safe where the runes
        // book rather than vanish.
        assertSwapped(ItemID.SAILORS_AMULET_EMPTY, ItemID.SAILORS_AMULET);

        Engine engine = settle(
            mapOf(ItemID.SAILORS_AMULET_EMPTY, 1L, ItemID.LAWRUNE, 1L, ItemID.WATERRUNE, 10L),
            mapOf(ItemID.SAILORS_AMULET, 1L));
        for (Transaction row : engine.getActiveSession().getTransactions())
        {
            for (Flow flow : row.getFlows())
            {
                assertTrue("the amulet's states never book: " + flow.itemId,
                    flow.itemId != ItemID.SAILORS_AMULET
                        && flow.itemId != ItemID.SAILORS_AMULET_EMPTY);
            }
        }
        assertEquals(-(300L + 10L * 5L), engine.getMetrics(1_010_000L).net);
    }

    private static void assertSwapped(int first, int second)
    {
        List<Flow> flows = new ArrayList<>();
        flows.add(flow(first, -1L));
        flows.add(flow(second, 1L));
        assertTrue(first + " -> " + second, FlowFilters.withoutSwaps(flows).isEmpty());
    }

    private static void assertKept(int first, int second)
    {
        List<Flow> flows = new ArrayList<>();
        flows.add(flow(first, -1L));
        flows.add(flow(second, 1L));
        assertEquals(first + " -> " + second, 2, FlowFilters.withoutSwaps(flows).size());
    }

    private static Flow flow(int itemId, long quantity)
    {
        return new Flow(itemId, "Item " + itemId, quantity, 100, quantity * 100);
    }

    private static Engine settle(Map<Integer, Long> before, Map<Integer, Long> after)
    {
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) ->
            {
                int price = id == ItemID.NATURERUNE ? 300
                    : id == ItemID.LAWRUNE ? 300
                    : id == ItemID.WATERRUNE ? 5 : 400_000;
                flows.add(new Flow(id, "Item " + id, quantity, price, quantity * price));
            });
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
        });
        engine.ensureSession(1_000_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        engine.markDirty();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)), 1_000_000L + tick * 600L, null);
        }
        return engine;
    }

    private static Map<Integer, Long> mapOf(Object... values)
    {
        Map<Integer, Long> result = new HashMap<>();
        for (int index = 0; index + 1 < values.length; index += 2)
        {
            result.put((Integer) values[index], (Long) values[index + 1]);
        }
        return result;
    }
}

package com.gpmanager;

import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import net.runelite.api.events.ItemDespawned;
import org.junit.Test;

import static com.gpmanager.ReviewFixesTest.*;
import static org.junit.Assert.*;

/** Real monetary paths retain their receipts while proof is reserved, exhausted or fenced. */
public class InboxMoneyTest
{
    @Test
    public void logoutDuringABindCompletesItsNewGeneration() throws Exception
    {
        Persistence persistence = new Persistence(null, null, null, null, engine());
        var entered = new CountDownLatch(1);
        var release = new CountDownLatch(1);
        try
        {
            persistence.runLifecycle(() -> false, false, "test bind", persist ->
            {
                entered.countDown();
                try
                {
                    release.await(3, TimeUnit.SECONDS);
                }
                catch (InterruptedException ex)
                {
                    throw new AssertionError(ex);
                }
                return true;
            });
            assertTrue(entered.await(3, TimeUnit.SECONDS));
            long generation = persistence.lifecycleRequest.get();
            persistence.onLogout(false);
            release.countDown();
            persistence.lifecycleExecutor.shutdown();
            assertTrue(persistence.lifecycleExecutor.awaitTermination(3, TimeUnit.SECONDS));
            assertEquals(generation + 1, persistence.lifecycleRequest.get());
            assertFalse(persistence.lifecyclePending);
            assertFalse(persistence.consumeReady());
        }
        finally
        {
            release.countDown();
            persistence.lifecycleExecutor.shutdownNow();
        }
    }

    @Test
    public void ownerFenceRetainsDurableGraveContinuityAndClearsTheInteraction()
    {
        Engine engine = engine();
        engine.deathReclaim.onPvmDeath(Map.of(BONES, 2L));
        engine.deathReclaim.reclaimTicks = 10;
        engine.neutralZoneStoredItems.put(BONES, 1L);
        engine.inbox.owner(1001L);
        assertTrue(engine.deathReclaim.isAwaitingReclaim());
        assertEquals(Long.valueOf(2L), engine.deathReclaim.carriedAtDeath.get(BONES));
        assertEquals(0, engine.deathReclaim.reclaimTicks);
        assertTrue(engine.neutralZoneStoredItems.isEmpty());
    }

    @Test
    public void existingCoordinatorGenerationFencesAnAccountCycle()
    {
        Engine engine = engine();
        Persistence persistence = new Persistence(null, null, null, null, engine);
        persistence.activeIdentity = new TrackingIdentity("A", 1);
        persistence.fence();
        Observation fee = engine.inbox.add(Inbox.FEE, -1, 500L, 10, "Reclaim fee (bank)");
        persistence.activeIdentity = new TrackingIdentity("B", 2);
        persistence.fence();
        persistence.activeIdentity = new TrackingIdentity("A", 1);
        persistence.fence();
        assertEquals(3L, persistence.lifecycleRequest.get());
        assertEquals(1003L, engine.inbox.owner);
        engine.inbox.open.add(fee);
        engine.fee(fee, T0);
        assertEquals(0L, engine.getMetrics(T0).costs);
    }

    @Test
    public void bagBooksOnlyThePrivateQuantityAndNeverTwice()
    {
        Engine engine = engine();
        engine.markLoot(Map.of(BONES, 2L), 50, "Loot from Guard", "Guard");
        int[] tick = {11};
        Plugin plugin = plugin(engine, tick);
        Observation click = take(plugin);
        click.item = BONES;
        click.at = 10;
        click.x = 10;
        click.y = 10;
        plugin.onItemDespawned(new ItemDespawned(ReviewFollowupTest.tile(10, 10), ReviewFollowupTest.bones()));
        assertEquals(2L, qty(plugin, Inbox.BAG_GAIN));
        assertFalse(engine.inbox.has(Inbox.PRIVATE_LOOT, BONES));
        plugin.onItemDespawned(new ItemDespawned(ReviewFollowupTest.tile(10, 10), ReviewFollowupTest.bones()));
        tick[0]++;
        plugin.bagSettle();
        engine.processIfDirty(ContainerSnapshot.empty(), T0 + 600, null);
        engine.processIfDirty(ContainerSnapshot.empty(), T0 + 1200, null);
        assertEquals(200L, engine.getMetrics(T0 + 1200).revenue);
        plugin.bagSettle();
        engine.processIfDirty(ContainerSnapshot.empty(), T0 + 1800, null);
        assertEquals(200L, engine.getMetrics(T0 + 1800).revenue);
    }

    @Test
    public void reservationKeepsTheFirstEncounterAheadOfTheSecond()
    {
        Engine engine = engine();
        engine.loot(Map.of(BONES, 1L), 50, "first", "Guard", Context.LOOT, "one");
        engine.loot(Map.of(BONES, 1L), 50, "second", "Goblin", Context.LOOT, "two");
        assertEquals(1L, engine.inbox.reserve(Inbox.PRIVATE_LOOT, BONES, 1L, Inbox.LOOT_RESERVE));
        LootMatch source = engine.consumeQueuedLoot(List.of(new Flow(BONES, "Bones", 1L, 100, 100L)));
        assertEquals("first", source.note);
        assertEquals("one", source.encounterId);
        assertEquals(1L, engine.inbox.peek(Inbox.PRIVATE_LOOT).qty);
    }

    @Test
    public void ordinaryPickupAlsoExhaustsPrivateProof()
    {
        Engine engine = engine();
        engine.markLoot(Map.of(BONES, 1L), 6, "Loot from Guard", "Guard");
        engine.consumeQueuedLoot(List.of(new Flow(BONES, "Bones", 1L, 100, 100L)));
        assertFalse(engine.inbox.has(Inbox.PRIVATE_LOOT, BONES));
        assertEquals(0L, engine.inbox.reserve(Inbox.PRIVATE_LOOT, BONES, 1L, Inbox.LOOT_RESERVE));
    }
}

package com.gpmanager;

import org.junit.Test;

import static org.junit.Assert.*;

/** Account ABA, quantity conservation, and inclusive expiry for every inbox kind. */
public class InboxTest
{
    private static final int BONES = 526;

    @Test
    public void ownerCycleRejectsEveryOldObservationEvenWhenReinserted()
    {
        Inbox inbox = new Inbox();
        for (int kind = Inbox.FEE; kind <= Inbox.BANK_UI; kind++)
        {
            inbox.owner(1001L);
            Observation old = inbox.add(kind, BONES, 3L, 5, "A");
            inbox.owner(2002L);
            assertTrue(inbox.open.isEmpty());
            inbox.owner(1003L);
            inbox.open.add(old);
            assertNull(inbox.peek(kind));
            assertEquals(0L, inbox.take(kind, BONES, 3L, observation -> true));
        }
    }

    @Test
    public void oversizedUseIsBoundedAndCannotRepeat()
    {
        for (int kind = Inbox.FEE; kind <= Inbox.BANK_UI; kind++)
        {
            Inbox inbox = new Inbox();
            inbox.add(kind, BONES, 3L, 5, "bag");
            assertEquals(2L, inbox.take(kind, BONES, 2L, observation -> true));
            assertEquals(1L, inbox.take(kind, BONES, 100L, observation -> true));
            assertEquals(0L, inbox.take(kind, BONES, 1L, observation -> true));
        }
    }

    @Test
    public void expiryIncludesTheBoundaryTick()
    {
        for (int kind = Inbox.FEE; kind <= Inbox.BANK_UI; kind++)
        {
            Inbox inbox = new Inbox();
            inbox.tick(10);
            inbox.add(kind, BONES, 3L, 5, null);
            inbox.tick(15);
            assertEquals(1L, inbox.take(kind, BONES, 1L, observation -> true));
            inbox.tick(16);
            assertEquals(0L, inbox.take(kind, BONES, 2L, observation -> true));
        }
    }

    @Test
    public void sourcePredicateAndItemMustBothMatch()
    {
        Inbox inbox = new Inbox();
        inbox.add(Inbox.CHEST, BONES, 3L, 5, "left");
        inbox.add(Inbox.CHEST, BONES, 4L, 5, "right");
        assertEquals(0L, inbox.take(Inbox.CHEST, 995, 100L, observation -> true));
        assertEquals(4L, inbox.take(Inbox.CHEST, BONES, 100L, observation -> "right".equals(observation.note)));
        assertEquals(3L, inbox.peek(Inbox.CHEST).qty);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.Map;
import net.runelite.api.ItemComposition;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

/**
 * Owner 2026-10-09 (1.3.0): an ironman who turns on "value at high alch" sees items at their
 * alchemy price, the coins they can actually make; everyone else, and coins and their own price
 * overrides, are unchanged.
 */
public class IronmanValueTest
{
    private static final int WHIP = 4151;
    private final Valuation valuation = ModelProbe.valuation(new GpManagerConfig() { }, IronmanValueTest::composition, id -> id == WHIP ? 1_500_000 : 0);

    @Test
    public void highAlchOnlyWhenChosen()
    {
        assertEquals("the GE price by default", 1_500_000, valuation.valueComponent(WHIP, 1L, 0L).unitPrice);
        valuation.alch = true;
        Flow whip = valuation.valueComponent(WHIP, 1L, 0L);
        assertEquals("its high alchemy price", 72_000, whip.unitPrice);
        assertSame(PriceSource.HIGH_ALCHEMY, whip.getPriceSource());
        assertEquals("coins stay coins", 1, valuation.valueComponent(995, 1L, 0L).unitPrice);
        assertEquals("your own override still wins", 2_000_000,
            valuation.valueOne(WHIP, 1L, Map.of(WHIP, 2_000_000), 0L).unitPrice);
    }

    private static ItemComposition composition(int id)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) -> {
                if ("getName".equals(method.getName())) return id == WHIP ? "Abyssal whip" : "Coins";
                if ("getHaPrice".equals(method.getName())) return id == WHIP ? 72_000 : 0;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return "isTradeable".equals(method.getName());
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }
}

