    @Test public void unsupportedDrinkKeepsBothQuotesDespiteTerminalGeCollection()
    {
        GpManagerConfig config = new GpManagerConfig() {
            @Override public String manualPriceOverrides() { return "139=5000"; }
            @Override public boolean countUncertainMixedChanges() { return true; }
        };
        Engine engine = new Engine(potionService(config), new TransactionClassifier(), config);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(Map.of(2434, 1L)));
        OfferSlots offers = new OfferSlots();
        for (net.runelite.api.GrandExchangeOfferState state : List.of(
            net.runelite.api.GrandExchangeOfferState.BUYING, net.runelite.api.GrandExchangeOfferState.BOUGHT))
        {
            boolean filled = state == net.runelite.api.GrandExchangeOfferState.BOUGHT;
            OfferSlots.Transition transition = offers.observe(new OfferSlots.Snapshot(
                0, state, 139, 1, filled ? 1 : 0, 5000, filled ? 5000 : 0)).orElse(null);
            engine.noteGeOffer(transition, "Prayer potion(3)", filled ? 1_600L : 1_300L);
        }
        engine.noteGeCollect(1_800L);
        engine.noteConsume(2434, 6, false, ActionKind.DRINK);
        Transaction sip = settleDrink(engine, Map.of(139, 1L), 2_000L);
        assertEquals(TransactionType.UNCERTAIN, sip.getType());
        assertFalse(sip.isCounted());
        assertEquals(2, sip.getFlows().size());
        assertEquals(-3600L, flow(sip.getFlows(), 2434).valueDelta);
        assertEquals(5000L, flow(sip.getFlows(), 139).valueDelta);
        assertEquals(0L, engine.getMetrics(5_000L).revenue);
        assertEquals(0L, engine.getMetrics(5_000L).costs);
    }

    private static Transaction settleDrink(Engine engine, Map<Integer, Long> inventory, long now)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
        assertNull(engine.processIfDirty(snapshot, now, null));
        assertNull(engine.processIfDirty(snapshot, now + 600L, null));
        Transaction sip = engine.processIfDirty(snapshot, now + 1_200L, null);
        assertNotNull(sip);
        return sip;
    }

    private static Valuation potionService(GpManagerConfig config)
    {
        return potionService(config, 1_000);
    }

    private static Valuation potionService(GpManagerConfig config, int oneDosePrice)
    {
        Map<Integer, String> names = new HashMap<>();
        names.put(2434, "Prayer potion(4)");
        names.put(139, "Prayer potion(3)");
        names.put(141, "Prayer potion(2)");
        names.put(143, "Prayer potion(1)");
        names.put(ItemID.VIAL_EMPTY, "Vial");
        names.put(ItemID.VIAL_WATER, "Vial of water");
        Map<Integer, Integer> prices = new HashMap<>();
        prices.put(2434, 3_600);
        prices.put(139, 2_600);
        prices.put(141, 1_900);
        prices.put(143, oneDosePrice);
        prices.put(ItemID.VIAL_EMPTY, 8);
        prices.put(ItemID.VIAL_WATER, 12);
        return ModelProbe.valuation(config,
            id -> composition(names.getOrDefault(id, "Item " + id), 0),
            id -> prices.getOrDefault(id, 0));
    }

    private static Flow flow(List<Flow> flows, int itemId)
    {
        Flow found = findFlow(flows, itemId);
        if (found != null) return found;
        fail("missing flow for " + itemId);
        return null;
    }

    private static Flow findFlow(List<Flow> flows, int itemId)
    {
        for (Flow flow : flows) {
            if (flow.itemId == itemId) return flow;
        }
        return null;
    }

    private static long net(List<Flow> flows)
    {
        long total = 0L;
        for (Flow flow : flows) {
            total = SafeMath.safeAdd(total, flow.valueDelta);
        }
        return total;
    }

    private static ItemComposition composition(String name, int highAlchemy)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) -> {
                if ("getName".equals(method.getName())) return name;
                if ("getHaPrice".equals(method.getName())) return highAlchemy;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return false;
                if (type == byte.class) return (byte) 0;
                if (type == short.class) return (short) 0;
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                if (type == float.class) return 0F;
                if (type == double.class) return 0D;
                if (type == char.class) return '\0';
                return null;
            });
    }
}

package com.gpmanager;

import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class KeyChestCatalogueTest
{
    /** Exact chest-name lookup, case-insensitive and whitespace-trimmed. */
    private static KeyChestCatalogue.Entry entryForChest(String chestName)
    {
        for (KeyChestCatalogue.Entry entry : KeyChestCatalogue.entries())
        {
            if (normalize(entry.getChestName()).equals(normalize(chestName)))
            {
                return entry;
            }
        }
        return null;
    }

    /** True when the key's first mapped chest keeps the GE opportunity cost. */
    private static boolean isTradeableKey(int keyItemId)
    {
        java.util.List<KeyChestCatalogue.Entry> entries = KeyChestCatalogue.entriesForKey(keyItemId);
        return !entries.isEmpty() && entries.get(0).isTradeable();
    }

    private static String normalize(String value)
    {
        return value.trim().replace('’', '\'').toLowerCase(java.util.Locale.ROOT);
    }

    @Test public void cataloguesAllRequestedTradeableAndDeferredKeys()
    {
        assertEquals(35, KeyChestCatalogue.entries().size());
        assertTradeable(ItemID.CRYSTAL_KEY, "Crystal chest");
        assertTradeable(ItemID.SLAYER_WILDERNESS_KEY, "Larran's small chest");
        assertNotNull(entryForChest("Larran's big chest"));
        assertTradeable(ItemID.ZOGRE_COFFINKEY, "Ogre coffin");
        assertTradeable(ItemID.MUDDY_KEY, "Muddy chest");
        assertTradeable(ItemID.SINISTER_KEY, "Sinister chest");
        assertTradeable(ItemID.HOSDUN_GRUBBY_KEY, "Grubby chest");

        assertDeferred(ItemID.KONAR_KEY, "Brimstone chest");
        assertDeferred(ItemID.PRIF_CRYSTAL_KEY, "Elven Crystal Chest");
        assertDeferred(ItemID.VARLAMORE_NICE_KEY, "Moon chest");
        assertDeferred(ItemID.SHADEKEY_BRONZE_BLOODRED, "Bronze Chest (red)");
        assertDeferred(ItemID.SHADEKEY_STEEL_BROWN, "Steel Chest (brown)");
        assertDeferred(ItemID.SHADEKEY_BLACK_CRIMSON, "Black Chest (crimson)");
        assertDeferred(ItemID.SHADEKEY_SILVER_BLACK, "Silver Chest (black)");
        assertDeferred(ItemID.SHADEKEY_GOLD_PURPLE, "Gold Chest (purple)");
    }

    @Test public void everyShadeMetalColorPairIsDeferred()
    {
        int[] shadeKeys = {
            ItemID.SHADEKEY_BRONZE_BLOODRED, ItemID.SHADEKEY_BRONZE_BROWN,
            ItemID.SHADEKEY_BRONZE_CRIMSON, ItemID.SHADEKEY_BRONZE_BLACK, ItemID.SHADEKEY_BRONZE_PURPLE,
            ItemID.SHADEKEY_STEEL_BLOODRED, ItemID.SHADEKEY_STEEL_BROWN,
            ItemID.SHADEKEY_STEEL_CRIMSON, ItemID.SHADEKEY_STEEL_BLACK, ItemID.SHADEKEY_STEEL_PURPLE,
            ItemID.SHADEKEY_BLACK_BLOODRED, ItemID.SHADEKEY_BLACK_BROWN,
            ItemID.SHADEKEY_BLACK_CRIMSON, ItemID.SHADEKEY_BLACK_BLACK, ItemID.SHADEKEY_BLACK_PURPLE,
            ItemID.SHADEKEY_SILVER_BLOODRED, ItemID.SHADEKEY_SILVER_BROWN,
            ItemID.SHADEKEY_SILVER_CRIMSON, ItemID.SHADEKEY_SILVER_BLACK, ItemID.SHADEKEY_SILVER_PURPLE,
            ItemID.SHADEKEY_GOLD_BLOODRED, ItemID.SHADEKEY_GOLD_BROWN,
            ItemID.SHADEKEY_GOLD_CRIMSON, ItemID.SHADEKEY_GOLD_BLACK, ItemID.SHADEKEY_GOLD_PURPLE
        };
        for (int keyId : shadeKeys)
        {
            assertTrue("Shade key " + keyId + " is deferred", KeyChestCatalogue.isDeferredKey(keyId));
            assertFalse("Shade key " + keyId + " is not tradeable", isTradeableKey(keyId));
            assertEquals(1, KeyChestCatalogue.entriesForKey(keyId).size());
        }
    }

    @Test public void unknownKeyAndTradeableKeysAreNeverDeferred()
    {
        assertFalse(KeyChestCatalogue.isDeferredKey(995));
        assertFalse(KeyChestCatalogue.isDeferredKey(ItemID.CRYSTAL_KEY));
        assertFalse(KeyChestCatalogue.isDeferredKey(ItemID.SLAYER_WILDERNESS_KEY));
        assertTrue(isTradeableKey(ItemID.CRYSTAL_KEY));
    }

    private static void assertTradeable(int keyId, String chestName)
    {
        KeyChestCatalogue.Entry entry = entryForChest(chestName);
        assertNotNull(chestName, entry);
        assertEquals(keyId, entry.getKeyItemId());
        assertTrue(chestName, entry.isTradeable());
            assertTrue(chestName, entry.isTradeable());
    }

    private static void assertDeferred(int keyId, String chestName)
    {
        KeyChestCatalogue.Entry entry = entryForChest(chestName);
        assertNotNull(chestName, entry);
        assertEquals(keyId, entry.getKeyItemId());
        assertFalse(chestName, entry.isTradeable());
            assertFalse(chestName, entry.isTradeable());
    }
}

