            map.put(pair[0], pair[1]);
        }
        return map;
    }

    @Test
    public void theTableMatchesRuneLiteConstants()
    {
        assertEquals(expected(), ContainerSnapshotFactory.ONE_ITEM);
    }

    @Test
    public void lightingALanternOrOpeningABagChangesNoSnapshot()
    {
        ContainerSnapshot before = snapshot(ItemID.BULLSEYE_LANTERN_UNLIT, ItemID.SLAYER_HERB_SACK, ItemID.SHARK);
        ContainerSnapshot after = snapshot(ItemID.BULLSEYE_LANTERN_LIT, ItemID.SLAYER_HERB_SACK_OPEN, ItemID.SHARK);
        assertEquals(before, after);
        assertEquals("the engine sees no change to book", Map.of(), after.diff(before));
        assertEquals("ordinary items keep their id", ItemID.SHARK,
            new ContainerSnapshotFactory(null, null).canonical(ItemID.SHARK));
    }

    private static ContainerSnapshot snapshot(int... ids)
    {
        Item[] items = new Item[ids.length];
        for (int i = 0; i < ids.length; i++)
        {
            items[i] = new Item(ids[i], 1);
        }
        ItemContainer inventory = (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[]{ItemContainer.class}, (proxy, method, args) -> "getItems".equals(method.getName()) ? items : null);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, args) -> "getItemContainer".equals(method.getName()) && (int) args[0] == InventoryID.INV
                ? inventory : null);
        return new ContainerSnapshotFactory(client, null).capture(false, false);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-09 (1.3.0): clue drops ride HUD+ again, opening caskets or impling jars is one
 * tray row per container, NPC dialogue purchases book like a shop's, a house servant's bank trips
 * are neutral, and the PvP tutorial arena is a lending zone.
 */
public class OwnerGapsTest
{
    private static final int COINS = 995;
    private static final int CLUE = 2722;
    private static final int CASKET = 20544;
    private static final int PLATEBODY = 1127;
    private static final int THIRD_AGE = 10348;
    private static final int TEAK_PLANK = 8780;
    private static final int TEAK_LOGS = 6333;
    private static final int JAR = 11260;
    private static final Map<Integer, String> NAMES = Map.of(COINS, "Coins", CLUE, "Clue scroll (hard)",
        CASKET, "Reward casket (hard)", PLATEBODY, "Rune platebody", THIRD_AGE, "3rd age platebody",
        TEAK_PLANK, "Teak plank", TEAK_LOGS, "Teak logs", JAR, "Impling jar");
    private static final Map<Integer, Integer> PRICES = Map.of(COINS, 1, PLATEBODY, 38_000,
        THIRD_AGE, 900_000_000, TEAK_PLANK, 600, TEAK_LOGS, 90, JAR, 290);

    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 100_000L));
    private final Engine engine = new Engine(deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) ->
        {
            String name = NAMES.getOrDefault(id, "Item " + id);
            boolean clue = GameData.pattern("clue").matcher(name).matches();
            int unit = clue ? 0 : PRICES.getOrDefault(id, 0);
            flows.add(new Flow(id, name, quantity, unit, quantity * unit,
                id == COINS ? PriceSource.FACE_VALUE : clue ? PriceSource.DEFERRED_CLAIM : PriceSource.GRAND_EXCHANGE));
        });
        return flows;
    }, new TransactionClassifier(), new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    });
    private long now = 1_000_000L;

    @Test
    public void aClueDropRidesTheTrayWithNoQuestionMark()
    {
        start();
        Transaction drop = change(CLUE, 1L);
        assertTrue("a clue drop books now", drop != null);
        HudTray tray = new HudTray();
        tray.booked(drop, now, false);
        HudTray.Entry entry = tray.entries().get(0);
        assertEquals("Clue scroll (hard)", entry.name);
        assertEquals("worth nothing yet, and no question mark", "", HudBuilder.value(entry));
        assertNull("opening it books nothing", change(CLUE, -1L, CASKET, 1L));
    }

    @Test
    public void openingCasketsIsOneRowPerCasketTypeWithItsTotal()
    {
        HudTray tray = new HudTray();
        tray.booked(opened(PLATEBODY, 38_000L), now, false);
        tray.booked(opened(PLATEBODY, 38_000L), now + 600L, false);
        assertEquals("one row, not one per reward", 1, tray.entries().size());
        HudTray.Entry casket = tray.entries().get(0);
        assertEquals("Reward casket (hard)", casket.name);
        assertEquals(2L, casket.quantity);
        assertEquals(76_000L, casket.value);
        assertEquals("Opened", tray.label());

        tray.booked(opened(THIRD_AGE, 900_000_000L), now + 1_200L, false);
        assertTrue("a big drop keeps its own gold row", tray.entries().stream()
            .anyMatch(entry -> entry.itemId == THIRD_AGE && entry.gold));

        Flow empty = new Flow(JAR, "Impling jar", -1L, 290, -290L);
        Flow full = new Flow(11248, "Eclectic impling jar", 1L, 20_000, 20_000L);
        assertNull("catching an impling is no opening", HudTray.opened(List.of(empty, full)));
        assertEquals("looting the jar is", 11248, HudTray.opened(List.of(new Flow(11248, "Eclectic impling jar", -1L, 20_000, -20_000L),
            new Flow(PLATEBODY, "Rune platebody", 1L, 38_000, 38_000L))).itemId);
    }

    @Test
    public void coinsForAnItemWhileTalkingToAnNpcIsAPurchase()
    {
        start();
        assertTrue("without a conversation it stays Review", ReviewRules.needsOwnerDecision(change(COINS, -2_000L, JAR, 1L)));
        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction bought = change(COINS, -2_000L, JAR, 1L);
        assertSame(TransactionType.TRADE, bought.getType());
        assertSame(Context.MARKET, bought.getContext());
        assertTrue(bought.isCounted());
        assertTrue("not Review", !ReviewRules.needsOwnerDecision(bought));
        assertEquals("paid 2,000 for a 290 jar; the first is still in Review", -1_710L, net());
    }

    @Test
    public void aServantsBankTripsAreNeutralButHisWageAndTheSawmillCount()
    {
        start();
        engine.inbox.put(Inbox.SERVANT, 0, 1L, 4, null);
        change(TEAK_PLANK, 26L);
        assertEquals("planks fetched from the bank", 0L, net());

        engine.inbox.put(Inbox.SERVANT, 0, 1L, 4, null);
        change(COINS, -10_000L, TEAK_PLANK, 26L);
        assertEquals("his wage counts; the planks he brought do not", -10_000L, net());

        engine.inbox.put(Inbox.SERVANT, 0, 1L, 4, null);
        engine.inbox.put(Inbox.SAWMILL, 0, 1L, 200, null);
        change(TEAK_LOGS, -26L, COINS, -13_000L);
        engine.inbox.put(Inbox.SERVANT, 0, 1L, 4, null);
        change(TEAK_PLANK, 26L);
        assertEquals("the sawmill: logs and fee spent, planks made", -10_000L - 26L * 90L - 13_000L + 26L * 600L, net());

        engine.inbox.put(Inbox.SERVANT, 0, 1L, 4, null);
        change(TEAK_PLANK, -26L);
        assertEquals("taking planks to the bank after the sawmill trip is neutral again",
            -10_000L - 26L * 90L - 13_000L + 26L * 600L, net());
    }

    @Test
    public void thePvpTutorialArenaIsALendingZone()
    {
        assertTrue(MinigameRegionHints.isPvpTutorial(10588));
        assertTrue("Ferox Enclave itself is not", !MinigameRegionHints.isPvpTutorial(12344));
        assertTrue("the Gauntlet keeps its own rule", MinigameRegionHints.isNeutralZoneRegion(7512) && !MinigameRegionHints.isPvpTutorial(7512));
    }

    private Transaction opened(int reward, long value)
    {
        return Tx.of(now, TransactionType.GAIN, Context.GENERIC, "", true, List.of(
            new Flow(CASKET, "Reward casket (hard)", -1L, 0, 0L, PriceSource.DEFERRED_CLAIM),
            new Flow(reward, NAMES.get(reward), 1L, (int) Math.min(Integer.MAX_VALUE, value), value)));
    }

    private void start()
    {
        engine.startCustom("Gaps", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
    }

    private Transaction change(Object... idsAndDeltas)
    {
        for (int index = 0; index < idsAndDeltas.length; index += 2)
        {
            inventory.merge((Integer) idsAndDeltas[index], (Long) idsAndDeltas[index + 1], Long::sum);
        }
        inventory.values().removeIf(quantity -> quantity == 0L);
        int before = engine.getActiveSession().getTransactions().size();
        now += 3_000L;
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 600L, null);
        List<Transaction> all = engine.getActiveSession().getTransactions();
        return all.size() > before ? all.get(all.size() - 1) : null;
    }

    private long net()
    {
        return engine.getMetrics(now + 60_000L).net;
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class PausePolicyTest
{
    private Engine engine(boolean autoStart)
    {
        GpManagerConfig config = new GpManagerConfig()
        {

            @Override
            public boolean autoStartSession()
            {
                return autoStart;
            }

            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        };
        return new Engine(
            deltas -> Collections.emptyList(),
            new TransactionClassifier(),
            config);
    }

    @Test
    public void manualPauseSurvivesGameplayActivityEvenWhenLegacyAutoResumeEnabled()
    {
        Engine engine = engine(true);
        engine.ensureSession(1_000L);
        engine.togglePause(2_000L);
        assertEquals(PauseReason.MANUAL, engine.getActiveSession().getPauseReason());
        engine.resume(3_000L, PauseReason.IDLE);
        engine.resume(4_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        engine.resume(5_000L, PauseReason.LIFECYCLE);
        assertTrue(engine.getActiveSession().paused);
        assertEquals(PauseReason.MANUAL, engine.getActiveSession().getPauseReason());
        assertEquals(1_000L, engine.getMetrics(5_000L).elapsedMillis);
    }

    @Test
    public void idlePauseResumesOnActivityButManualPauseDoesNot()
    {
        Engine engine = engine(true);
        engine.ensureSession(1_000L);
        engine.getActiveSession().pause(2_000L, PauseReason.IDLE);
        engine.resume(3_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        assertFalse(engine.getActiveSession().paused);

        engine.togglePause(4_000L);
        engine.resume(5_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        engine.resume(6_000L, PauseReason.IDLE);
        engine.resume(7_000L, PauseReason.LIFECYCLE);
        assertTrue(engine.getActiveSession().paused);
    }

    @Test
    public void recoveredPauseResumesOnActivityOrExplicitResume()
    {
        Engine engine = engine(true);
        engine.ensureSession(1_000L);
        engine.togglePause(2_000L);
        engine.restore(engine.savedState(), SafeMath.now());
        assertEquals(PauseReason.RECOVERY, engine.getActiveSession().getPauseReason());
        engine.resume(2_500L, PauseReason.LIFECYCLE);
        assertTrue("Login must not clear Recovery", engine.getActiveSession().paused);
        engine.resume(3_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        assertFalse(engine.getActiveSession().paused);

        engine = engine(true);
        engine.ensureSession(1_000L);
        engine.togglePause(2_000L);
        engine.restore(engine.savedState(), SafeMath.now());
        engine.togglePause(4_000L);
        assertFalse(engine.getActiveSession().paused);
    }

    @Test
    public void inventoryChangesDuringManualPauseDoNotBecomeCatchUpProfit()
    {
        Engine engine = new Engine(
            deltas -> Collections.singletonList(
                new Flow(1511, "Oak logs", deltas.getOrDefault(1511, 0L), 39,
                    deltas.getOrDefault(1511, 0L) * 39L)),
            new TransactionClassifier(),
            new GpManagerConfig()
            {
                @Override
                public int stabilizationTicks()
                {
                    return 0;
                }
            });
        engine.ensureSession(1_000L);
        Map<Integer, Long> empty = new HashMap<>();
        Map<Integer, Long> logs = new HashMap<>();
        logs.put(1511, 5L);
        engine.setBaseline(new ContainerSnapshot(empty));
        engine.togglePause(2_000L);
        assertNull(engine.processIfDirty(new ContainerSnapshot(logs), 3_000L, null));
        assertEquals(0L, engine.getMetrics(3_000L).net);
        engine.togglePause(4_000L);
        assertNull(engine.processIfDirty(new ContainerSnapshot(logs), 5_000L, null));
        assertEquals(0L, engine.getMetrics(5_000L).net);
    }

    @Test
    public void theActionThatResumesAnIdlePauseStillCounts()
    {
        Engine engine = new Engine(
            deltas -> Collections.singletonList(
                new Flow(1511, "Oak logs", deltas.getOrDefault(1511, 0L), 39,
                    deltas.getOrDefault(1511, 0L) * 39L)),
            new TransactionClassifier(),
            new GpManagerConfig()
            {
                @Override
                public int stabilizationTicks()
                {
                    return 0;
                }
            });
        engine.ensureSession(1_000L);
        Map<Integer, Long> empty = new HashMap<>();
        Map<Integer, Long> logs = new HashMap<>();
        logs.put(1511, 5L);
        engine.setBaseline(new ContainerSnapshot(empty));
        engine.getActiveSession().pause(2_000L, PauseReason.IDLE);
        assertTrue(engine.getActiveSession().paused);
        assertEquals(PauseReason.IDLE, engine.getActiveSession().getPauseReason());
        // The pause aligns its baseline on the next tick; then the action's gain settles
        // while still paused, and that gain is what wakes the session.
        engine.processIfDirty(new ContainerSnapshot(empty), 2_500L, null);
        engine.processIfDirty(new ContainerSnapshot(logs), 3_000L, null);
        assertFalse("the resuming gain wakes the session", engine.getActiveSession().paused);
        engine.processIfDirty(new ContainerSnapshot(logs), 4_000L, null);
        assertEquals("the action that resumed the session counts", 195L,
            engine.getMetrics(4_000L).net);
    }

    @Test
    public void automaticStartupCreatesGeneralOnlyWhenEnabledAndMissing()
    {
        Engine disabled = engine(false);
        assertFalse(disabled.autoStart(1_000L));
        assertNull(disabled.getActiveSession());
        assertNull(disabled.processIfDirty(new ContainerSnapshot(Collections.emptyMap()), 1_100L, null));

        Engine enabled = engine(true);
        assertTrue(enabled.autoStart(1_000L));
        assertNotNull(enabled.getActiveSession());
        assertFalse(enabled.autoStart(1_200L));
    }

    @Test
    public void lifecycleResumeDoesNotCancelManualPause()
    {
        Engine engine = engine(true);
        engine.ensureSession(1_000L);
        engine.pauseForLifecycle(2_000L);
        engine.togglePause(2_500L); // explicit manual while... actually if already paused lifecycle, toggle resumes then we'd pause manual
        // Start fresh: live -> manual
        engine = engine(true);
        engine.ensureSession(1_000L);
        engine.togglePause(2_000L);
        engine.resume(3_000L, PauseReason.LIFECYCLE);
        assertEquals(PauseReason.MANUAL, engine.getActiveSession().getPauseReason());
    }

    /**
     * Login init resumes LIFECYCLE pauses only (see GpManagerPlugin.ve).
     * Hop/relog clears LIFECYCLE; Idle and Recovery stay until activity; Stop stays sticky.
     */
    @Test
    public void loginResumePolicyClearsLifecycleOnly()
    {
        Engine lifecycle = engine(true);
        lifecycle.ensureSession(1_000L);
        lifecycle.pauseForLifecycle(2_000L);
        lifecycle.resume(3_000L, PauseReason.LIFECYCLE);
        assertFalse(lifecycle.getActiveSession().paused);

        Engine idle = engine(true);
        idle.ensureSession(1_000L);
        idle.getActiveSession().pause(2_000L, PauseReason.IDLE);
        idle.resume(3_000L, PauseReason.LIFECYCLE);
        assertTrue(idle.getActiveSession().paused);
        assertEquals(PauseReason.IDLE, idle.getActiveSession().getPauseReason());
        idle.resume(4_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        assertFalse(idle.getActiveSession().paused);
    }

    /** The boolean is the plugin's signal to install a trusted baseline right after a resume. */
    @Test
    public void resumeReportsWhetherItActuallyClearedAPause()
    {
        Engine engine = engine(true);
        engine.ensureSession(1_000L);
        assertFalse("a live session does not resume", engine.resume(2_000L, PauseReason.IDLE));
        engine.getActiveSession().pause(3_000L, PauseReason.IDLE);
        assertTrue("an idle pause clears", engine.resume(4_000L, PauseReason.IDLE));
        assertFalse("an already-live session reports false", engine.resume(5_000L, PauseReason.IDLE));
        engine.togglePause(6_000L);
        assertFalse("manual pause stays", engine.resume(7_000L, PauseReason.LIFECYCLE));
    }
}

