package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner report 2026-09-28: 50 Chaos runes picked up in the same settle as one thrown Steel dart went
 * to an uncounted Review. A pickup with only a routine rune/ammo spend is a counted gain net of it.
 */
public class PickupWithRoutineSpendTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int POUCH = 22538;
    private static final Map<Integer, String> NAMES = new HashMap<>();

    static
    {
        NAMES.put(562, "Chaos rune");
        NAMES.put(808, "Steel dart");
        NAMES.put(385, "Shark");
        NAMES.put(POUCH, "Coin pouch");
        NAMES.put(995, "Coins");
    }

    @Test
    public void openingCoinPouchesIsACountedGain()
    {
        Transaction settled = settleFrom(POUCH, 2L, 995, 60L, POUCH, 0L);
        assertNotNull(settled);
        assertEquals("the coins count as income, not an uncounted Review",
            TransactionType.GAIN, settled.getType());
        assertTrue(settled.isCounted());
    }

    @Test
    public void aPickupWithADartThrownIsACountedGain()
    {
        Transaction settled = settleFrom(808, 10L, 562, 50L, 808, 9L);
        assertNotNull(settled);
        assertEquals(TransactionType.GAIN, settled.getType());
        assertTrue("counted, never an uncounted Review", settled.isCounted());
        assertEquals("Net is the runes less the dart", 50L * 90L - 4L, settled.getNet());
    }

    @Test
    public void aPickupWithFoodEatenStaysReview()
    {
        Transaction settled = settleFrom(385, 3L, 562, 50L, 385, 2L);
        assertNotNull(settled);
        assertEquals("food is not a routine combat spend", TransactionType.UNCERTAIN, settled.getType());
    }

    /** Baseline {first: firstQty}, then {gainId: gainQty, first: firstAfter}. */
    private static Transaction settleFrom(int first, long firstQty, int gainId, long gainQty, int after, long afterQty)
    {
        Engine engine = engine();
        engine.startCustom("Nechryael", T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(first, firstQty);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));
        held.put(gainId, gainQty);
        held.put(after, afterQty);
        engine.markDirty();
        Transaction result = null;
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)), T0 + 600L + i * 600L, null);
            if (settled != null)
            {
                result = settled;
            }
        }
        return result;
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int unit = delta.getKey() == 562 ? 90 : delta.getKey() == 808 ? 4 : 900;
                flows.add(new Flow(delta.getKey(), NAMES.get(delta.getKey()), delta.getValue(), unit,
                    delta.getValue() * unit, PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.LootFilter;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Ground Items filtering is presentation only. A live presentation filter can never change
 * canonical money, rollups or corrections. Bank-close burial remains an observed supply cost.
 */
public class PresentationFilterAccountingIsolationEngineTest
{
    private Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig() {
            public int stabilizationTicks() { return 2; }
            public boolean keepTransferAuditRows() { return true; }
            public LootFilter lootPresentationFilter() { return LootFilter.HIGHLIGHTED_LIST_ONLY; }
        };
        Engine engine = new Engine(deltas -> {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Bones", quantity, 35, quantity * 35L)));
            return flows;
        }, new TransactionClassifier(), config);
        engine.ensureSession(1000L);
        return engine;
    }

    /** A Ground Items rule set that would show only feathers; bones are hidden from presentation. */
    private void onlyFeathers(Engine engine)
    {
        engine.setContributionEligibility(new LootPresentationFilterService(new GroundItemsPrefs(
            true, "Feather", "Bones", false)));
    }

    private Transaction gain(Flow... flows)
    {
        return Tx.of(1600L, TransactionType.GAIN, Context.GENERIC,
            "Pickup", true, Arrays.asList(flows));
    }

    @Test public void burialCallbackBeforeGameTickBankCloseMustNotLatchOldTransfer()
    {
        Engine engine = engine();
        ContainerSnapshot bones = new ContainerSnapshot(Collections.singletonMap(526, 1L));
        engine.setBaseline(bones);
        engine.bankOpened(6);
        engine.processIfDirty(bones, 1000L, null);
        engine.markDirty();
        engine.bankClosed();
        engine.processIfDirty(ContainerSnapshot.empty(), 1600L, null);
        engine.processIfDirty(ContainerSnapshot.empty(), 2200L, null);
        Transaction tx = engine.processIfDirty(ContainerSnapshot.empty(), 2800L, null);
        assertEquals(TransactionType.CONSUMPTION, tx.getType());
    }

    @Test public void hiddenItemsStillCountInNetAndInsights()
    {
        Engine engine = engine();
        onlyFeathers(engine);
        engine.getActiveSession().addTransaction(gain(new Flow(526, "Bones", 1L, 35, 35L)), 100, false);
        assertEquals(35L, engine.getMetrics(2800L).net);
    }

    @Test public void correctionsOperateOnTheWholeCanonicalRow()
    {
        Engine engine = engine();
        onlyFeathers(engine);
        Transaction tx = gain(new Flow(526, "Bones", 1L, 35, 35L),
            new Flow(314, "Feather", 1L, 10, 10L));
        engine.getActiveSession().addTransaction(tx, 100, false);
        assertEquals(45L, engine.getMetrics(2800L).revenue);
        engine.getActiveSession().correctTransaction(tx.getId(), Correction.REVENUE, 3000L, "Manual correction");
        assertEquals(45L, engine.getMetrics(3100L).revenue);
    }

    @Test public void compactionFoldsExactRawValues()
    {
        Engine engine = engine();
        onlyFeathers(engine);
        Session session = engine.getActiveSession();
        session.addTransaction(gain(new Flow(526, "Bones", 1L, 35, 35L)), 1, false);
        session.addTransaction(gain(new Flow(526, "Bones", 1L, 35, 35L)), 1, false);
        assertTrue(session.compactedTransactionCount > 0L);
        assertEquals(70L, engine.getMetrics(2800L).net);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
