import net.runelite.api.SkullIcon;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Charter E: NONE / SAFE_PVP_OR_MINIGAME / DANGEROUS_PVP precedence is fail-closed, context never
 * touches session identity, opponent names never persist by default, and best/worst/net follow
 * the correction-aware encounter summary. Offline only; live acceptance is owner-gated.
 */
public class PvpContextTest
{
    private static final int LMS_REGION = 13658;
    private static final int CASTLE_WARS_REGION = 9520;
    private static final int LUMBRIDGE_REGION = 12850;

    @Test
    public void knownDangerousContextsAreConfident()
    {
        assertEquals(PvpContext.DANGEROUS_PVP, PvpContext.classify(true, false, false, false, 0));
        assertEquals("attackable on a PvP world", PvpContext.DANGEROUS_PVP,
            PvpContext.classify(false, true, true, false, LUMBRIDGE_REGION));
        assertTrue(PvpContext.DANGEROUS_PVP.isDangerous());
    }

    @Test
    public void positivelyIdentifiedSafeArenasWinOverEverything()
    {
        assertEquals(PvpContext.SAFE_PVP_OR_MINIGAME, PvpContext.classify(false, true, false, false, LMS_REGION));
        assertEquals(PvpContext.SAFE_PVP_OR_MINIGAME, PvpContext.classify(false, false, false, false, CASTLE_WARS_REGION));
        assertEquals("PvP Arena worlds are safe PvP", PvpContext.SAFE_PVP_OR_MINIGAME,
            PvpContext.classify(false, true, true, true, LUMBRIDGE_REGION));
        assertEquals("a safe arena inside conflicting dangerous signals stays safe", PvpContext.SAFE_PVP_OR_MINIGAME,
            PvpContext.classify(true, true, true, false, LMS_REGION));
    }

    @Test
    public void noSignalsIsNone()
    {
        assertEquals(PvpContext.NONE, PvpContext.classify(false, false, false, false, LUMBRIDGE_REGION));
        assertEquals("unknown region with no signals", PvpContext.NONE, PvpContext.classify(false, false, false, false, 0));
    }

    @Test
    public void conflictingOrInsufficientSignalsNeverBecomeDangerous()
    {
        assertEquals("PvP world bank safe zone (no attackable orb)", PvpContext.NONE,
            PvpContext.classify(false, false, true, false, LUMBRIDGE_REGION));
        assertEquals("attackable orb without a world/Wilderness fact is ambiguous", PvpContext.NONE,
            PvpContext.classify(false, true, false, false, LUMBRIDGE_REGION));
        assertEquals("orb alone with an unknown region", PvpContext.NONE, PvpContext.classify(false, true, false, false, 0));
    }

    @Test
    public void manualPkTripSessionIsIndependentOfContextDetection()
    {
        Engine engine = engine();
        engine.ensureSession(1_000L);
        engine.startCustom("PK Trip", 2_000L);
        String tripId = engine.getActiveSession().getId();

        // Context is bookkeeping only: it never creates, renames or splits the manual session.
        engine.markPkLoot(Collections.singletonMap(4151, 1L), 10, 3_000L);
        engine.markPkDeath(4_000L);

        assertEquals(tripId, engine.getActiveSession().getId());
        assertEquals("PK Trip", engine.getActiveSession().getName());
        assertEquals(SessionMode.AUTO, engine.getActiveSession().getMode());
        assertEquals(2, engine.getActiveSession().pk().encounters());
        assertEquals("no automatic session was spawned", 0, engine.getHistory().size());
    }

    @Test
    public void opponentNamesNeverPersistByDefaultAndDeathsNeverCarryThem()
    {
        Engine engine = engine();
        engine.ensureSession(1_000L);
        engine.markPkLoot(Collections.emptyMap(), 10, 2_000L);
        engine.markPkDeath(3_000L);
        String json = new com.google.gson.Gson().toJson(engine.getActiveSession());
        assertFalse("no opponent label is stored", json.contains("Player kill"));
        assertEquals(1, engine.getActiveSession().pk().deaths);
    }

    @Test
    public void correctionsRecomputeBestKillWorstDeathAndNet()
    {
        Engine engine = engine();
        engine.ensureSession(1_000L);
        engine.setBaseline(ContainerSnapshot.empty());

        engine.markPkLoot(Collections.singletonMap(4151, 1L), 10, 2_000L);
        Transaction loot = settle(engine, Collections.singletonMap(4151, 1L), 2_600L);
        assertNotNull(loot);
        assertEquals(TransactionType.PK_LOOT, loot.getType());
        assertEquals(1_000_000L, engine.bestKill());

        assertTrue(engine.correctTransaction(loot.getId(), Correction.IGNORE, 3_000L, "not mine"));
        assertEquals("an excluded kill receipt leaves the encounter but not its value", 1,
            engine.getActiveSession().pk().kills);
        assertEquals(0L, engine.bestKill());

        assertTrue(engine.correctTransaction(loot.getId(), Correction.REVENUE, 3_500L, "counted again"));
        assertEquals(1_000_000L, engine.bestKill());

        engine.markPkDeath(4_000L);
        assertEquals(1, engine.getActiveSession().pk().deaths);
        assertEquals("a death never changes the best kill", 1_000_000L, engine.bestKill());
    }

    @Test
    public void relogKeepsEncountersOnTheSameOwner()
    {
        Engine engine = engine();
        engine.ensureSession(1_000L);
        engine.markPkLoot(Collections.emptyMap(), 10, 2_000L);
        engine.pauseForLifecycle(3_000L);
        engine.resume(4_000L, PauseReason.LIFECYCLE);
        engine.markPkDeath(5_000L);
        assertEquals(1, engine.getActiveSession().pk().kills);
        assertEquals(1, engine.getActiveSession().pk().deaths);
        assertEquals("relog never closes the owner", 0L, engine.getActiveSession().endedAtEpochMillis);
    }

    private static Transaction settle(Engine engine, Map<Integer, Long> quantities, long now)
    {
        engine.markDirty();
        ContainerSnapshot snapshot = new ContainerSnapshot(quantities);
        Transaction result = engine.processIfDirty(snapshot, now, null);
        return result != null ? result : engine.processIfDirty(snapshot, now + 1L, null);
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, qty) -> flows.add(new Flow(id, "Item " + id, qty, 1_000_000, qty * 1_000_000L)));
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Receipt retention compacts individually inspectable detail while preserving exact totals
 * and correction-aware metrics.
 */
public class ReceiptRetentionTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final long DAY = 86_400_000L;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int maxHistorySessions()
        {
            return 2_000;
        }

        @Override
        public Retention receiptRetentionDays()
        {
            return Retention.DAYS_90;
        }
    };

    @Test
    public void compactsRowsStrictlyOlderThanTheCutoffByTransactionTimeAcrossOwners()
    {
        // Section L: the cutoff is transaction time, whether the owner is closed or still active.
        long now = 100L * DAY + 12L * 60L * 60L * 1_000L;
        long cutoff = now - 30L * DAY;
        Session boundary = new Session("Boundary", cutoff - 10_000L, SessionMode.GENERAL);
        boundary.addTransaction(receipt(cutoff, 100L), 10, false);
        boundary.close(cutoff + 1_000L);
        Session old = new Session("Old", cutoff - 10_000L, SessionMode.GENERAL);
        old.addTransaction(receipt(cutoff - 1L, 200L), 10, false);
        old.close(cutoff + 2_000L);
        Session active = new Session("Active", cutoff - 2L * DAY, SessionMode.GENERAL);
        active.addTransaction(receipt(cutoff - DAY, 300L), 10, false);
        active.addTransaction(receipt(cutoff + DAY, 50L), 10, false);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Arrays.asList(boundary, old, old, active)), now);

        assertEquals(2, engine.compactOlderThan(30, now));
        assertEquals("a row exactly at the cutoff is retained", 1, boundary.getTransactions().size());
        assertTrue(old.getTransactions().isEmpty());
        assertEquals(1L, old.compactedTransactionCount);
        assertEquals(200L, old.metrics(now).revenue);
        assertEquals("only the active owner's overdue row folds", 1, active.getTransactions().size());
        assertEquals(350L, active.metrics(now).revenue);
        assertEquals(0, engine.compactOlderThan(30, now));
        assertEquals(0, engine.compactOlderThan(0, now));
    }

    @Test
    public void derivedPendingClaimIdKeepsItsOriginAuditRowRetained()
    {
        long now = 400L * DAY;
        Session session = new Session("Loot origin", now - 200L * DAY, SessionMode.GENERAL);
        Transaction audit = receipt(now - 200L * DAY + 1_000L, 0L);
        session.addTransaction(audit, 10, false);
        session.close(now - 200L * DAY + 2_000L);

        SavedState state = new SavedState(null, null, Collections.singletonList(session));
        state.setPendingClaims(Collections.singletonList(new SavedState.PendingClaim(
            audit.getId() + "#2", net.runelite.api.gameval.ItemID.WILDY_LOOT_KEY1, 1L,
            audit.timestampEpochMillis)));

        Engine engine = engine();
        engine.restore(state, now);

        assertEquals("a multi-key claim protects the shared origin audit row", 1,
            session.getTransactions().size());
        assertTrue(engine.getPendingClaims().get(0).getClaimId().endsWith("#2"));
        assertEquals(0, engine.compactOlderThan(90, now));
    }

    @Test
    public void compactionKeepsTheNameEncountersAndExactTotals()
    {
        long now = 400L * DAY;
        Session session = new Session("Favourite trip", now - 200L * DAY, SessionMode.AUTO);

        session.addTransaction(receipt(now - 200L * DAY + 1_000L, 100L), 10, false);
        session.addTransaction(receipt(now - 200L * DAY + 61_000L, 250L), 10, false);
        session.addTransaction(receipt(now - 200L * DAY + 62_500L, -40L), 10, false);
        String encounter = session.addEncounter(true, now - 200L * DAY + 62_000L);
        session.attachToEncounter(session.getTransactions().get(1).getId(), encounter, false);
        session.close(now - 200L * DAY + 120_000L);

        Metrics before = session.metrics(now);
        long bestKillBefore = session.bestKill();
        Engine engine = engine();
        engine.restore(new SavedState(null, null, Collections.singletonList(session)), now);

        assertEquals("current-schema restore already compacted the overdue rows", 0,
            engine.compactOlderThan(90, now));

        assertTrue(session.getTransactions().isEmpty());
        assertEquals(3L, session.compactedTransactionCount);
        assertEquals("Favourite trip", session.getName());
        assertEquals("compacted receipts keep the kill count", 1, session.pk().kills);

        Metrics after = session.metrics(now);
        assertEquals(before.revenue, after.revenue);
        assertEquals(before.costs, after.costs);
        assertEquals(before.net, after.net);
        assertEquals(350L, after.revenue);
        assertEquals(40L, after.costs);
        assertEquals(250L, bestKillBefore);
        assertEquals(bestKillBefore, session.bestKill());
    }

    @Test
    public void currentSchemaRestoreCompactsOverdueRowsWithoutWaitingForUtcRollover()
    {
        long now = 120L * DAY + 12L * 60L * 60L * 1_000L;
        Session overdue = closedWithReceipt("Overdue", now - 120L * DAY - 1L, 750L);
        SavedState current = new SavedState(null, null, Collections.singletonList(overdue));

        Engine engine = engine();
        engine.restore(current, now);

        assertTrue(overdue.getTransactions().isEmpty());
        assertEquals(1L, overdue.compactedTransactionCount);
        assertEquals(750L, overdue.metrics(now).revenue);
        assertEquals("the restore counts as today's sweep", 0, engine.maintainRetention(now + 1_000L));
    }

    @Test
    public void shippingRetentionWindowsAreBoundedAndUnknownReadsAs90Days()
    {
        assertEquals(Arrays.asList(30, 90, 180, 365), Arrays.asList(
            Retention.DAYS_30.getDays(), Retention.DAYS_90.getDays(),
            Retention.DAYS_180.getDays(), Retention.DAYS_365.getDays()));
        assertEquals(4, Retention.values().length);
        for (Retention period : Retention.values())
        {
            assertFalse("no shipping window means retain forever", period.getDays() <= 0);
        }
    }

    private static Session closedWithReceipt(String name, long endedAt, long value)
    {
        long start = Math.max(0L, endedAt - 10_000L);
        Session session = new Session(name, start, SessionMode.GENERAL);
        session.addTransaction(receipt(start + 1_000L, value), 10, false);
        session.close(endedAt);
        return session;
    }

    private static Transaction receipt(long timestamp, long value)
    {
        return Tx.of(timestamp, value < 0L ? TransactionType.CONSUMPTION : TransactionType.LOOT,
            Context.LOOT, "receipt", true, Collections.singletonList(new Flow(995, "Coins",
                value < 0L ? -1L : 1L, (int) Math.min(Integer.MAX_VALUE, Math.abs(value)), value)));
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(), CONFIG);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.function.LongSupplier;
import org.junit.Assume;
import org.junit.Test;
import org.junit.experimental.categories.Category;

/**
 * Release pass 2026-09-28: timing budget on a heavy profile (a running Grind at the 2,000 detailed
 * receipts the default keeps, 300 finished Grinds). Dev-only; runs when GP_PERF is set:
 * {@code GP_PERF=1 ./gradlew test --tests 'com.gpmanager.ReleasePerfTest'}. Prints median/p99.
 */
@Category(PerformanceBudget.class)
public class ReleasePerfTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final Random RANDOM = new Random(20260928L);

    @Test
    public void heavyProfileStaysInsideTheFrameBudget() throws Exception
    {
        Assume.assumeTrue("set GP_PERF to run", System.getenv("GP_PERF") != null);
        Engine engine = PresentationLifecycleTest.engine();
        for (int grind = 0; grind < 300; grind++)
        {
            Session done = new Session("Grind " + grind, T0 - (300 - grind) * 3_600_000L, SessionMode.GENERAL);
            for (int i = 0; i < 60; i++)
            {
                done.addTransaction(receipt(done.startedAtEpochMillis + i * 1_000L), 2_000, false);
            }
            done.close(done.startedAtEpochMillis + 3_000_000L);
            engine.history.add(0, done);
        }
        engine.startCustom("Greater Nechryael", T0);
        for (int i = 0; i < 2_000; i++)
        {
            engine.getActiveSession().addTransaction(receipt(T0 + i * 1_800L), 2_000, false);
        }
        long now = T0 + 4_000_000L;

        List<Transaction> all = engine.getActiveSession().getTransactions();
        report("Bp.transaction x2000", () -> all.stream().mapToLong(t -> Accounting.transaction(t).costs).sum());
        report("Bp.costSplit x2000", () -> all.stream().mapToLong(t -> Accounting.costSplit(t).supplies).sum());
        report("spellName x2000", () -> all.stream().mapToLong(t -> t.spellName().length()).sum());
        report("Ledger contributions x2000", () -> all.stream().mapToLong(t -> Contribution.project(t).size()).sum());
        report("session metrics", () -> engine.getActiveSession().metrics(now).net);
        int[] flip = {0};
        report("Live capture (cold)", () -> LiveSnapshot.capture(engine, now,
            new LiveContext(false, null, flip[0]++ % 2, PvpState.NONE, "", false, "", false)).net);
        report("Live capture (warm)", () -> LiveSnapshot.capture(engine, now, LiveContext.NONE).net);
        report("Ledger capture", () -> LedgerData.capture(engine, now, LedgerData.Entry.current()).net);
        report("Grinds capture", () -> GrindsData.capture(engine, now, false, null).myGrinds.size());
        GpManagerConfig config = HudBuilderTest.config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
        LiveSnapshot snapshot = LiveSnapshot.capture(engine, now, LiveContext.NONE);
        report("HUD+ update + render", () ->
        {
            builder.update(snapshot, f -> true, now);
            return overlay.render(g).width;
        });
        Gson gson = new Gson();
        String once = gson.toJson(engine.savedState());
        SavedState copy = gson.fromJson(once, SavedState.class);
        System.out.println("PERF save JSON bytes " + once.length()
            + ", identical to the old detached copy: " + once.equals(gson.toJson(copy)));
        report("save snapshot (engine lock)", () -> engine.savedState().schemaVersion);
        report("detach round trip", () -> gson.fromJson(gson.toJson(engine.savedState()), SavedState.class).schemaVersion);
        report("save snapshot + JSON", () -> gson.toJson(engine.savedState()).length());
        SessionRepository repository = new SessionRepository(gson,
            FilepathTestSupport.root(java.nio.file.Files.createTempDirectory("gp-perf")), false);
        Persistence coordinator = new Persistence(null, null, repository,
            new OrderedPersistenceWriter(repository, null), engine);
        report("save intent (client thread)", () -> coordinator.currentIntent().expectedBaseRevision);
        // 1.1: the periodic gameplay save reuses closed sessions' JSON; every 10th is full.
        report("quick save intent (client thread)", () -> coordinator.currentIntent(true).expectedBaseRevision);
        System.out.println("PERF quick save identical to one toJson: "
            + coordinator.snapshotJson(null, true).replaceFirst("\"savedAtEpochMillis\":\\d+", "")
                .equals(gson.toJson(engine.savedState()).replaceFirst("\"savedAtEpochMillis\":\\d+", "")));
    }

    private static Transaction receipt(long at)
    {
        List<Flow> flows;
        TransactionType type;
        ActionKind action = null;
        switch (RANDOM.nextInt(5))
        {
            case 0:
                type = TransactionType.LOOT;
                flows = Arrays.asList(new Flow(1_319, "Rune axe", 1L, 7_202, 7_202L),
                    new Flow(560, "Death rune", 46L, 187, 8_602L));
                break;
            case 1:
                type = TransactionType.CONSUMPTION;
                action = ActionKind.CAST;
                flows = Arrays.asList(new Flow(560, "Death rune", -4L, 187, -748L),
                    new Flow(565, "Blood rune", -2L, 341, -682L), new Flow(555, "Water rune", -6L, 5, -30L));
                break;
            case 2:
                type = TransactionType.CONSUMPTION;
                action = ActionKind.DRINK;
                flows = Arrays.asList(new Flow(2434, "Prayer potion(4)", -1L, 9_800, -9_800L),
                    new Flow(139, "Prayer potion(3)", 1L, 7_350, 7_350L));
                break;
            case 3:
                type = TransactionType.CONSUMPTION;
                action = ActionKind.FIRE;
                flows = Collections.singletonList(new Flow(808, "Steel dart", -2L, 4, -8L));
                break;
            default:
                type = TransactionType.GAIN;
                flows = Collections.singletonList(new Flow(526, "Bones", 1L, 37, 37L));
                break;
        }
        Transaction transaction = new Transaction(at, type,
            type == TransactionType.LOOT ? Context.LOOT : Context.GENERIC, "",
            "Greater Nechryael", true, flows, Confidence.CONFIRMED, "perf", null);
        transaction.setActionKind(action);
        return transaction;
    }

    private static void report(String name, LongSupplier work)
    {
        for (int i = 0; i < 20; i++)
        {
            work.getAsLong();
        }
        long[] times = new long[100];
        for (int i = 0; i < times.length; i++)
        {
            long start = System.nanoTime();
            work.getAsLong();
            times[i] = System.nanoTime() - start;
        }
        Arrays.sort(times);
        System.out.printf("PERF %-24s median %7.3f ms  p99 %7.3f ms%n", name, times[50] / 1e6, times[98] / 1e6);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A data / factory reset leaves the profile exactly as a new install: no session, nothing
 * accruing. Only Start or the plugin's genuine-activity start
 * ({@link Engine#autoStart}, when Automatic tracking is on)
 * begins tracking, each exactly once; the passive work around a reset (priming, ticks with
 * unchanged containers, saved-state snapshots, restore) never does.
 */
public class ResetStateLifecycleTest
{
    private static final int OAK_LOGS = 1521;

    private static Engine engine(AtomicBoolean autoStart)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public boolean autoStartSession() { return autoStart.get(); }
            @Override public int stabilizationTicks() { return 0; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> e : deltas.entrySet())
            {
                flows.add(new Flow(e.getKey(), "Oak logs", e.getValue(), 40, e.getValue() * 40L));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }

    private static Engine resetEngine(AtomicBoolean autoStart)
    {
        Engine engine = engine(autoStart);
        engine.ensureSession(1_000L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        engine.getActiveSession().addTransaction(Tx.of(1_500L, TransactionType.GAIN,
            Context.GENERIC, "Old", true,
            Collections.singletonList(new Flow(OAK_LOGS, "Oak logs", 5L, 40, 200L))), 100, false);
        engine.resetData(2_000L);
        return engine;
    }

    @Test
    public void resetLeavesANewInstall()
    {
        Engine engine = resetEngine(new AtomicBoolean(true));
        assertNull("no session until play or Start", engine.getActiveSession());
        assertNull(engine.getGeneralSession());
        assertEquals("no history survives", 0, engine.getHistory().size());
        assertEquals(0L, engine.getMetrics(2_000L).net);
        assertEquals(0L, engine.getMetrics(3_600_000L).elapsedMillis);
        assertFalse("no custom session starts because of reset", engine.isCustomActive());
    }

    @Test
    public void startAfterResetBeginsTrackingOnce()
    {
        Engine engine = resetEngine(new AtomicBoolean(false));
        engine.togglePause(3_000L);
        assertNotNull("Start creates Free play", engine.getActiveSession());
        assertFalse("and it runs, never born paused", engine.getActiveSession().paused);
        assertEquals("active time starts at Start", 60_000L, engine.getActiveSession().getElapsedMillis(63_000L));
        String id = engine.getActiveSession().getId();
        assertFalse("no second start from the activity path", engine.autoStart(3_100L));
        assertEquals(id, engine.getActiveSession().getId());
    }

    @Test
    public void genuineActivityStartsTrackingOnceAndThenBooks()
    {
        Engine engine = resetEngine(new AtomicBoolean(true));
        assertTrue(engine.autoStart(3_000L));
        assertFalse("already running: no duplicate start", engine.autoStart(3_100L));

        engine.setBaseline(new ContainerSnapshot(new HashMap<>()));
        engine.markDirty();
        Map<Integer, Long> logs = new HashMap<>();
        logs.put(OAK_LOGS, 1L);
        assertNull(engine.processIfDirty(new ContainerSnapshot(logs), 3_200L, null));
        Transaction gain = engine.processIfDirty(new ContainerSnapshot(logs), 3_800L, null);
        assertNotNull(gain);
        assertEquals(40L, gain.getNet());
        assertEquals(40L, engine.getMetrics(4_000L).net);
    }

    @Test
    public void passiveResetWorkNeverStartsTracking()
    {
        Engine engine = resetEngine(new AtomicBoolean(true));
        engine.beginPriming();
        ContainerSnapshot unchanged = new ContainerSnapshot(new HashMap<>());
        for (int tick = 0; tick < 20; tick++)
        {
            assertNull(engine.processIfDirty(unchanged, 2_200L + tick * 600L, null));
        }
        engine.resume(15_000L, PauseReason.LIFECYCLE);
        engine.resume(15_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        engine.resume(15_000L, PauseReason.IDLE);
        assertNull("resumes have nothing to resume", engine.getActiveSession());

        SavedState committed = engine.savedState();
        assertTrue(committed.getHistory().isEmpty());
        Engine reloaded = engine(new AtomicBoolean(true));
        reloaded.restore(new Gson().fromJson(new Gson().toJson(committed), SavedState.class), 16_000L);
        assertNull("a reload of the reset profile is still a new install", reloaded.getActiveSession());
        assertEquals(0L, reloaded.getMetrics(3_600_000L).net);
    }

    @Test
    public void activityStartHonoursAutomaticTracking()
    {
        AtomicBoolean autoStart = new AtomicBoolean(false);
        Engine engine = resetEngine(autoStart);
        assertFalse("Automatic tracking off: activity cannot start", engine.autoStart(3_000L));
        assertNull(engine.getActiveSession());
        autoStart.set(true);
        assertTrue(engine.autoStart(4_000L));
        assertFalse(engine.autoStart(4_100L));
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.Retention;

