import static org.junit.Assert.assertTrue;

/**
 * PRE-R5C.2B.3: schema-105 durable proven action labels are bounded presentation metadata that
 * survive restart, repository round trips and profile backup, while never touching money.
 */
public class Schema105ActionLabelPersistenceTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final String PROFILE = "profile-key-105";

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    @Test
    public void exactLabelIsDurableInSchema105StateAndReloads()
    {
        Session session = new Session("General", 1_000L, SessionMode.GENERAL);
        Transaction labelled = cast("Ice Burst", 2_000L);
        Transaction generic = genericCast(3_000L);
        session.addTransaction(labelled, 100, false);
        session.addTransaction(generic, 100, false);
        SavedState state = new SavedState(session, null, Collections.emptyList());
        assertEquals(110, state.schemaVersion);
        String json = new Gson().toJson(state);
        assertTrue("the bounded label is a stable JSON field",
            json.contains("\"observedActionLabel\":\"Ice Burst\""));

        SavedState loaded = new Gson().fromJson(json, SavedState.class);
        Transaction restored = loaded.getActiveSession().getTransactions().get(0);
        assertNotNull(restored.actionLabel());
        assertEquals("Ice Burst", restored.actionLabel().value());
        assertEquals("the reloaded receipt keeps its money", labelled.getNet(), restored.getNet());
        assertNull("an unlabelled receipt stays generic",
            loaded.getActiveSession().getTransactions().get(1).actionLabel());
    }

    @Test
    public void malformedOversizedControlAndGenericLabelsNormalizeToNull()
    {
        assertNull("invalid punctuation is rejected",
            normalizedWire("\"Ice Burst!!!\"", false).actionLabel());
        assertNull("oversized labels are rejected",
            normalizedWire("\"" + repeat("Ice Burst ", 7) + "\"", false).actionLabel());
        assertNull("control characters are rejected",
            normalizedWire("\"Ice\\u0000Burst\"", false).actionLabel());
        assertNull("generic Cast text never becomes an exact label",
            normalizedWire("\"Cast\"", false).actionLabel());
        assertNull("Autocast text never becomes an exact label",
            normalizedWire("\"Autocast\"", false).actionLabel());

        Transaction sanitized = normalizedWire("\"<col=ff9040>Ice Burst</col>\"", false);
        assertNotNull(sanitized.actionLabel());
        assertEquals("markup is stripped, never displayed", "Ice Burst",
            sanitized.actionLabel().value());
        assertFalse(sanitized.actionLabel().value().contains("<"));

        Transaction nonCast = normalizedWire("\"Ice Burst\"", true);
        assertNull("a non-CAST receipt cannot keep a stale spell label",
            nonCast.actionLabel());
    }

    @Test
    public void labelMutationsNeverDriftFinancialFingerprint()
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", T0);
        Transaction transaction = cast(null, T0 + 100L);
        engine.getActiveSession().addTransaction(transaction, 100, false);
        String before = fingerprint(transaction);
        long netBefore = engine.getMetrics(T0 + 200L).net;

        transaction.setActionLabel(ActionLabel.of("Ice Burst"));
        assertEquals("setting a label never changes money", before, fingerprint(transaction));
        transaction.setActionLabel(ActionLabel.of("Smoke Barrage"));
        assertEquals("changing a label never changes money", before, fingerprint(transaction));
        transaction.setActionLabel(null);
        assertEquals("clearing a label never changes money", before, fingerprint(transaction));
        assertEquals(netBefore, engine.getMetrics(T0 + 200L).net);

        Transaction trade = trade();
        String tradeBefore = fingerprint(trade);
        trade.setActionLabel(ActionLabel.of("Ice Burst"));
        assertNull("a non-CAST receipt never reads a spell label", trade.actionLabel());
        assertEquals("GE-shaped receipts stay financially identical", tradeBefore, fingerprint(trade));
    }

    @Test
    public void ownerFenceKeepsBookedLabelsAndClearsOnlyPendingEvidence()
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", T0);
        Transaction cast = cast("Ice Burst", T0 + 100L);
        engine.getActiveSession().addTransaction(cast, 100, false);
        long net = engine.getMetrics(T0 + 200L).net;

        engine.clearActionEvidence();

        assertNotNull("booked labels survive the presentation owner fence",
            cast.actionLabel());
        assertEquals("Ice Burst", cast.actionLabel().value());
        assertEquals("the fence never touches money", net, engine.getMetrics(T0 + 200L).net);
    }

    @Test
    public void onlyTheCurrentSchemaIsRead()
    {
        assertEquals(110, SavedState.CURRENT_SCHEMA_VERSION);
        SavedState old = new SavedState();
        old.setSchemaVersion(107);
        assertFalse("an older schema is never read", old.isSupportedSchema());
        assertFalse((old.schemaVersion > SavedState.CURRENT_SCHEMA_VERSION));
        SavedState future = new SavedState();
        future.setSchemaVersion(SavedState.CURRENT_SCHEMA_VERSION + 1);
        assertTrue((future.schemaVersion > SavedState.CURRENT_SCHEMA_VERSION));
        assertFalse("a newer schema is refused/read-only", future.isSupportedSchema());
        assertEquals("a restored profile saves as the current schema", 110,
            engine().savedState().schemaVersion);
    }

    @Test
    public void exactSpellGroupsSurviveRestartAndMergeLaterCasts()
    {
        long now = System.currentTimeMillis();
        Engine source = engine();
        source.startCustom("Vorkath", now);
        source.getActiveSession().addTransaction(cast("Ice Burst", now + 1_000L), 100, false);
        source.getActiveSession().addTransaction(cast("Ice Burst", now + 2_000L), 100, false);
        // Runes that name no spell (a staff covered them) keep the click; runes that do name one win.
        Transaction smoke = genericCast(now + 3_000L);
        smoke.setActionLabel(ActionLabel.of("Smoke Barrage"));
        source.getActiveSession().addTransaction(smoke, 100, false);
        source.getActiveSession().addTransaction(genericCast(now + 4_000L), 100, false);
        SavedState detached = source.savedState();
        assertEquals("detach keeps the bounded label", "Ice Burst",
            detached.getActiveSession().getTransactions().get(0).actionLabel().value());

        Engine restored = engine();
        restored.restore(detached, now + 5_000L);
        Session session = restored.getActiveSession();
        List<Transaction> restoredTransactions = session.getTransactions();
        assertEquals("Ice Burst", restoredTransactions.get(0).actionLabel().value());

        Semantics.Result before = Semantics.capture(
            restoredTransactions, null, session.getId(), null);
        Semantics.Group burst = groupNamed(before.groups, "Ice Burst");
        assertNotNull(burst);
        assertEquals(2, burst.receiptCount);
        String stableGroupId = burst.semanticGroupId;
        assertTrue("search terms survive restore", burst.searchTerms.contains("Ice Burst"));

        session.addTransaction(cast("Ice Burst", now + 6_000L), 100, false);
        Semantics.Result after = Semantics.capture(
            session.getTransactions(), null, session.getId(), null);
        Semantics.Group merged = groupNamed(after.groups, "Ice Burst");
        assertNotNull(merged);
        assertEquals("a later exact cast merges into the restored group", 3, merged.receiptCount);
        assertEquals("semantic identity stays stable for search and deep links",
            stableGroupId, merged.semanticGroupId);
        assertNotNull("Smoke Barrage stays separate",
            groupNamed(after.groups, "Smoke Barrage"));
        Semantics.Group generic = groupNamed(after.groups, "Cast");
        assertNotNull("the old generic Cast stays generic", generic);
        assertNotEquals(merged.semanticGroupId, generic.semanticGroupId);
    }

    @Test
    public void repositoryRoundTripAndBackupRotationPreserveTheLabel() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        Session session = new Session("General", 1_000L, SessionMode.GENERAL);
        Transaction labelled = cast("Ice Burst", 2_000L);
        session.addTransaction(labelled, 100, false);
        SavedState state = new SavedState(session, null, Collections.emptyList());
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        PersistenceProbe.save(repository, state);
        // Ordinary next save rotates the previous labelled generation into the backup file.
        session.addTransaction(cast("Smoke Barrage", 3_000L), 100, false);
        PersistenceProbe.save(repository, new SavedState(session, null, Collections.emptyList()));

        SavedState reloaded = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false).load();
        assertEquals(110, reloaded.schemaVersion);
        Transaction restored = reloaded.getActiveSession().getTransactions().get(0);
        assertEquals(labelled.getId(), restored.getId());
        assertEquals(labelled.getFlows().size(), restored.getFlows().size());
        assertEquals(labelled.getNet(), restored.getNet());
        assertEquals("Ice Burst", restored.actionLabel().value());
        assertTrue("backup rotation does not strip the field",
            Files.readString(directory.resolve("sessions.backup.json")).contains("Ice Burst"));
    }

    @Test
    public void compactionDoesNotArchiveOrInferActionNames()
    {
        long old = T0 - 400L * 24L * 60L * 60L * 1_000L;
        Engine engine = engine();
        engine.startCustom("Old Grind", old);
        engine.getActiveSession().addTransaction(cast("Ice Burst", old + 1_000L), 100, false);
        String sessionId = engine.getActiveSession().getId();
        engine.finishCustom(old + 2_000L);
        engine.compactOlderThan(1, T0);

        Session compacted = engine.historySession(sessionId);
        assertNotNull(compacted);
        assertTrue("the receipt detail is compacted away",
            compacted.getTransactions().isEmpty());
        assertTrue(compacted.compactedTransactionCount > 0);
        String json = new Gson().toJson(engine.savedState());
        assertFalse("a compacted receipt takes its action name with it",
            json.contains("Ice Burst"));
        assertFalse("no sidecar action-label archive exists",
            json.contains("actionLabelHistory"));
    }

    // ── fixtures ───────────────────────────────────────────────────────────────────────────────

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig()
            {
                @Override
                public Retention receiptRetentionDays()
                {
                    return Retention.DAYS_365;
                }
            });
    }

    private static SavedState stateWith(Transaction transaction)
    {
        Session session = new Session("General", 1_000L, SessionMode.GENERAL);
        session.addTransaction(transaction, 100, false);
        return new SavedState(session, null, Collections.emptyList());
    }

    /** Serialize, inject one raw wire value and reload; every read revalidates the label. */
    private static Transaction normalizedWire(String rawJsonValue, boolean nonCast)
    {
        Transaction source = nonCast ? eat("Ice Burst") : cast("Ice Burst", 2_000L);
        String json = new Gson().toJson(stateWith(source))
            .replace("\"observedActionLabel\":\"Ice Burst\"", "\"observedActionLabel\":" + rawJsonValue);
        SavedState loaded = new Gson().fromJson(json, SavedState.class);
        return loaded.getActiveSession().getTransactions().get(0);
    }

    private static Transaction cast(String label, long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                new Flow(560, "Death rune", -2L, 188, -376L, PriceSource.GRAND_EXCHANGE),
                new Flow(562, "Chaos rune", -4L, 106, -424L, PriceSource.GRAND_EXCHANGE),
                new Flow(555, "Water rune", -4L, 5, -20L, PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setActionKind(ActionKind.CAST);
        if (label != null)
        {
            transaction.setActionLabel(ActionLabel.of(label));
        }
        return transaction;
    }

    /** A Cast whose runes no spell pays (a Nature rune too), so it stays generic, never Ice Burst. */
    private static Transaction genericCast(long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                new Flow(560, "Death rune", -2L, 188, -376L, PriceSource.GRAND_EXCHANGE),
                new Flow(561, "Nature rune", -1L, 100, -100L, PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setActionKind(ActionKind.CAST);
        return transaction;
    }

    private static Transaction eat(String label)
    {
        Transaction transaction = new Transaction(T0 + 100L,
            TransactionType.CONSUMPTION, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(385, "Shark", -1L, 950, -950L,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Food", null);
        transaction.setActionKind(ActionKind.EAT);
        if (label != null)
        {
            transaction.setActionLabel(ActionLabel.of(label));
        }
        return transaction;
    }

    private static Transaction trade()
    {
        Transaction transaction = new Transaction(T0 + 100L, TransactionType.TRADE,
            Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(561, "Nature rune", -10L, 100, -1_000L,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "GE sale", null);
        return transaction;
    }

    private static String fingerprint(Transaction transaction)
    {
        return transaction.getNet() + "|" + transaction.getRevenue() + "|" + transaction.getCosts()
            + "|" + transaction.isCounted() + "|" + transaction.getType() + "|"
            + transaction.getContext() + "|" + transaction.getCorrection() + "|"
            + transaction.getActionKind() + "|"
            + new Gson().toJson(transaction.getFlows());
    }

    private static String repeat(String text, int times)
    {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < times; i++)
        {
            out.append(text);
        }
        return out.toString();
    }

    private static Semantics.Group groupNamed(
        List<Semantics.Group> groups, String name)
    {
        for (Semantics.Group group : groups)
        {
            if (name.equals(group.primaryName))
            {
                return group;
            }
        }
        return null;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-13 gap pass: a farming-contract seed pack and the Bounty Hunter supply crate are
 * claims like the herb box — worth nothing until taken from, and each Take counts its contents
 * without Review.
 */
public class SeedPackTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 2;
        }
    };

    private final FlowValuator valuator = deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(id == ItemID.SEEDBOX
            ? new Flow(id, "Seed pack", quantity, 0, 0L, PriceSource.DEFERRED_CLAIM, 0L)
            : new Flow(id, "Ranarr seed", quantity, 25_000, quantity * 25_000)));
        return flows;
    };

    @Test
    public void thePackIsAClaimUntilTakenFrom()
    {
        assertTrue(ActionReader.isClaim("Seed pack"));
        assertTrue("the Bounty supply crate is the same shape",
            ActionReader.isClaim("Bounty supply crate (anglerfish)"));
    }

    @Test
    public void everyTakeCountsItsSeedsWithoutReview()
    {
        Engine engine = new Engine(valuator, new TransactionClassifier(), CONFIG);
        engine.ensureSession(1_000L);
        engine.setBaseline(snapshot(1L, 0L));
        assertEquals(TransactionType.GAIN, settle(engine, snapshot(1L, 1L), 1_600L).getType());
        assertEquals("the last seed empties the pack", TransactionType.GAIN,
            settle(engine, snapshot(0L, 2L), 6_000L).getType());
        assertEquals(50_000L, engine.getMetrics(20_000L).net);
        assertEquals(0, engine.getReviewRows(20_000L).size());
    }

    private static ContainerSnapshot snapshot(long packs, long seeds)
    {
        Map<Integer, Long> held = new HashMap<>();
        if (packs > 0) held.put(ItemID.SEEDBOX, packs);
        if (seeds > 0) held.put(ItemID.RANARR_SEED, seeds);
        return new ContainerSnapshot(held);
    }

    private static Transaction settle(Engine engine, ContainerSnapshot snapshot, long firstTick)
    {
        Transaction row = null;
        for (long t = firstTick; row == null && t < firstTick + 4_000L; t += 600L)
            row = engine.processIfDirty(snapshot, t, null);
        return row;
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SessionHistoryEngineTest
{
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int maxHistorySessions()
        {
            return 100;
        }
    };

    @Test
    public void restoredActiveSessionWaitsPausedForRecovery()
    {
        Session interrupted = session("Interrupted", Context.LOOT, TransactionType.LOOT, 100L);
        Engine engine = engine();
        engine.restore(new SavedState(interrupted, null, Collections.emptyList()), SafeMath.now());

        assertNotNull(engine.getActiveSession());
        assertEquals(PauseReason.RECOVERY, engine.getActiveSession().getPauseReason());
    }

    @Test
    public void editsAndDeletesHistory()
    {
        Session pvm = session("Bossing", Context.LOOT, TransactionType.LOOT, 1_000L);
        pvm.close(3_600_000L);
        Session skilling = session("Fletching", Context.PRODUCTION, TransactionType.PROCESSING, 500L);
        skilling.close(3_600_000L);
        Session trading = session("Flipping", Context.MARKET, TransactionType.TRADE, -200L);
        trading.close(3_600_000L);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Arrays.asList(pvm, skilling, trading)), 3_600_000L);

        engine.historySession(pvm.getId()).rename("Vorkath");
        assertEquals("Vorkath", engine.historySession(pvm.getId()).getName());

        assertTrue(engine.deleteHistory(skilling.getId()));
        assertNull(engine.historySession(skilling.getId()));
        assertEquals(2, engine.getHistory().size());
    }

    @Test
    public void historicalCorrectionRecalculatesSummaryImmediately()
    {
        Session session = session("Review", Context.GENERIC, TransactionType.CONSUMPTION, -300L);
        session.close(60_000L);
        Transaction transaction = session.getTransactions().get(0);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Collections.singletonList(session)), 60_000L);
        Metrics before = engine.historyMetrics(session.getId(), 60_000L);
        assertEquals(-300L, before.net);

        assertTrue(engine.historySession(session.getId()).correctTransaction(
            transaction.getId(), Correction.REVENUE, 70_000L, "Manual correction"));
        Metrics after = engine.historyMetrics(session.getId(), 70_000L);
        assertEquals(300L, after.net);
    }

    @Test
    public void historySummaryCarriesStripMetadataWithoutLeakingSession()
    {
        Session session = session("Vorkath", Context.LOOT, TransactionType.LOOT, 1_000L);
        session.grind = true;
        session.close(60_000L);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Collections.singletonList(session)), 60_000L);

        Session retained = engine.historySession(session.getId());
        assertTrue(retained.grind);
        assertFalse(retained.getMode() == SessionMode.AUTO);
    }

    @Test
    public void historyIsNewestFirst()
    {
        long day = 24L * 60L * 60L * 1000L;
        long now = 100L * day;
        Session pvm = sessionAt("Vorkath", now - day, Context.LOOT, TransactionType.LOOT, 1_000L);
        Session skilling = sessionAt("Fletching", now - 10L * day, Context.PRODUCTION, TransactionType.PROCESSING, 500L);
        Session trading = sessionAt("Flipping", now - 40L * day, Context.MARKET, TransactionType.TRADE, -200L);

        Engine engine = engine();
        engine.restore(new SavedState(null, null, Arrays.asList(pvm, skilling, trading)), now);

        assertEquals("Vorkath", engine.getHistory().get(0).getName());
        assertEquals(3, engine.getHistory().size());

    }

    private static Engine engine()
    {
        return new Engine(
            deltas -> Collections.emptyList(),
            new TransactionClassifier(),
            CONFIG);
    }

    private static Session sessionAt(
        String name, long start, Context context, TransactionType type, long value)
    {
        Session session = new Session(name, start, SessionMode.GENERAL);
        long quantity = value < 0L ? -1L : 1L;
        session.addTransaction(Tx.of(
            start + 1_000L, 1_000L, type, context, name, name, true,
            Collections.singletonList(new Flow(1, "Item", quantity, (int) Math.abs(value), value))), 100, false);
        session.close(start + 3_600_000L);
        return session;
    }

    private static Session session(
        String name,
        Context context,
        TransactionType type,
        long value)
    {
        Session session = new Session(name, 0L, SessionMode.GENERAL);
        long quantity = value < 0L ? -1L : 1L;
        long absolute = Math.abs(value);
        session.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                type,
                context,
                name,
                name,
                true,
                Collections.singletonList(new Flow(1, "Item", quantity, (int) absolute, value))),
            100, false);
        return session;
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class SessionOwnershipTest
{
    private Engine engine(int historyLimit)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
            @Override public int maxHistorySessions() { return historyLimit; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Engine(deltas ->
            Collections.singletonList(new Flow(995, "Coins", deltas.get(995), 1, deltas.get(995))),
            new TransactionClassifier(), config);
    }

    @Test
    public void customSessionSuspendsGeneralAndOwnsEachObservedTransaction()
    {
        Engine engine = engine(10);
        engine.ensureSession(0L);
        Session general = engine.getGeneralSession();
        assertEquals("Overall", general.getName());
        engine.setBaseline(snapshot(0L));

        engine.startCustom("Vorkath", 100L);
        Session custom = engine.getActiveSession();
        assertNotEquals(general.getId(), custom.getId());
        assertTrue(general.paused);
        engine.setBaseline(snapshot(0L));
        engine.markDirty();
        engine.processIfDirty(snapshot(250L), 200L, null);
        Transaction transaction = engine.processIfDirty(snapshot(250L), 201L, null);

        assertEquals(250L, transaction.getNet());
        assertEquals(1, custom.getTransactions().size());
        assertEquals(0, general.getTransactions().size());
        assertTrue(engine.finishCustom(1_000L));
        assertEquals(general.getId(), engine.getActiveSession().getId());
        assertFalse(general.paused);
        assertEquals(1, engine.getHistory().size());
        assertEquals(custom.getId(), engine.getHistory().get(0).getId());
        assertEquals(1_100L, engine.getMetrics(2_000L).elapsedMillis);
    }

    @Test
    public void shutdownKeepsGeneralDurableAndRestoresItAsRecovery()
    {
        Engine engine = engine(10);
        engine.ensureSession(1_000L);
        String generalId = engine.getGeneralSession().getId();

        engine.pauseForLifecycle(2_000L);
        SavedState saved = engine.savedState();

        assertEquals(generalId, saved.generalSession.getId());
        assertEquals(0, saved.getHistory().size());
        Engine restored = engine(10);
        restored.restore(saved, SafeMath.now());
        assertEquals(generalId, restored.getActiveSession().getId());
        assertEquals(PauseReason.RECOVERY, restored.getActiveSession().getPauseReason());
    }

    @Test
    public void startCreatesARunningGeneralOwnerWhenAutoStartWasDisabled()
    {
        Engine engine = engine(10);

        engine.togglePause(1_000L);

        assertEquals("Overall", engine.getActiveSession().getName());
        assertEquals(engine.getGeneralSession().getId(), engine.getActiveSession().getId());
        assertFalse("Start begins tracking; it never creates a paused owner", engine.getActiveSession().paused);
    }

    @Test
    public void customTransitionPreservesEveryGeneralPauseOwner()
    {
        for (PauseReason reason : new PauseReason[] {PauseReason.IDLE, PauseReason.MANUAL, PauseReason.RECOVERY})
        {
            Engine engine = engine(10);
            engine.ensureSession(1_000L);
            Session general = engine.getGeneralSession();
            if (reason == PauseReason.IDLE) engine.getActiveSession().pause(1_100L, PauseReason.IDLE);
            if (reason == PauseReason.MANUAL) engine.togglePause(1_100L);
            if (reason == PauseReason.RECOVERY) general.pause(1_100L, PauseReason.RECOVERY);
            engine.startCustom("Custom", 1_200L);
            engine.finishCustom(1_300L);
            assertEquals(reason, general.getPauseReason());
            if (reason == PauseReason.IDLE || reason == PauseReason.RECOVERY)
            {
                engine.resume(1_400L, PauseReason.IDLE, PauseReason.RECOVERY);
                assertFalse(general.paused);
            }
            else
            {
                engine.resume(1_400L, PauseReason.IDLE, PauseReason.RECOVERY);
                assertTrue(general.paused);
            }
        }
    }

    @Test
    public void startingSecondCustomDoesNotArchiveTheFirst()
    {
        Engine engine = engine(10);
        engine.ensureSession(0L);
        engine.startCustom("First", 1L);
        String first = engine.getActiveSession().getId();
        engine.startCustom("Second", 2L);
        assertEquals(first, engine.getActiveSession().getId());
        assertEquals(0, engine.getHistory().size());
    }

    @Test
    public void idleGeneralPauseOwnerSurvivesCustomPersistenceAndFinish()
    {
        Engine engine = engine(10);
        engine.ensureSession(1_000L);
        engine.getActiveSession().pause(1_100L, PauseReason.IDLE);
        engine.startCustom("Raid", 1_200L);
        SavedState saved = new Gson().fromJson(new Gson().toJson(engine.savedState()), SavedState.class);

        Engine restored = engine(10);
        restored.restore(saved, SafeMath.now());
        restored.finishCustom(1_300L);

        assertEquals(PauseReason.IDLE, restored.getGeneralSession().getPauseReason());
        restored.resume(1_400L, PauseReason.IDLE, PauseReason.RECOVERY);
        assertFalse(restored.getGeneralSession().paused);
    }

    @Test
    public void explicitOwnersSurviveRestartAndCustomRecoveryWithoutMerging()
    {
        Engine engine = engine(10);
        engine.ensureSession(1_000L);
        String generalId = engine.getGeneralSession().getId();
        engine.startCustom("Raid", 2_000L);
        String customId = engine.getActiveSession().getId();

        SavedState saved = new Gson().fromJson(new Gson().toJson(engine.savedState()), SavedState.class);
        Engine restored = engine(10);
        restored.restore(saved, SafeMath.now());

        assertEquals(generalId, restored.getGeneralSession().getId());
        assertEquals(customId, restored.getActiveSession().getId());
        assertTrue(restored.isCustomActive());
        assertEquals(PauseReason.RECOVERY, restored.getActiveSession().getPauseReason());
        assertTrue(restored.getGeneralSession().paused);
    }

    @Test
    public void pauseLogoutAndRetentionDoNotCreateASecondOwner()
    {
        Engine engine = engine(2);
        engine.ensureSession(1_000L);
        String generalId = engine.getGeneralSession().getId();
        engine.togglePause(2_000L);
        engine.pauseForLifecycle(3_000L);
        engine.resume(4_000L, PauseReason.LIFECYCLE);
        assertTrue(engine.getActiveSession().paused);
        engine.resume(6_000L, PauseReason.IDLE, PauseReason.RECOVERY);
        assertTrue("a manual pause waits for Resume", engine.getActiveSession().paused);

        engine.startCustom("First", 7_000L);
        engine.finishCustom(8_000L);
        engine.startCustom("Second", 9_000L);
        engine.finishCustom(10_000L);
        engine.startCustom("Third", 11_000L);
        engine.finishCustom(12_000L);

        assertEquals(generalId, engine.getGeneralSession().getId());
        assertEquals(generalId, engine.getActiveSession().getId());
        assertEquals(2, engine.getHistory().size());
        assertEquals(PauseReason.MANUAL, engine.getGeneralSession().getPauseReason());
    }

    private static ContainerSnapshot snapshot(long coins)
    {
        return new ContainerSnapshot(Collections.singletonMap(995, coins));
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner 1.3.4: a shop window turns coins-for-items into a counted "Bought" and items-for-coins
 * into a counted "Sold" instead of a mixed Review row; the trade branches still fail closed when
 * the shapes are not exact.
 */
public class ShopPurchaseTest
{
    private static final int COINS = 995;
    private static final int JAR = 11260;
    private static final int PLATEBODY = 1127;
    private static final int TOKKUL = 6529;
    private static final int DEATH_RUNE = 560;
    private static final int BOOK = 9003; // Security book: untradeable, no market price
    private static final Map<Integer, String> NAMES = Map.of(COINS, "Coins", JAR, "Impling jar",
        PLATEBODY, "Rune platebody", TOKKUL, "Tokkul", DEATH_RUNE, "Death rune", BOOK, "Security book");
    private static final Map<Integer, Integer> PRICES = Map.of(COINS, 1, JAR, 290, PLATEBODY, 38_000, TOKKUL, 9);

    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 100_000L, PLATEBODY, 5L, TOKKUL, 100_000L));
    private final Engine engine = new Engine(deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) ->
        {
            int unit = PRICES.getOrDefault(id, 0);
            flows.add(new Flow(id, NAMES.getOrDefault(id, "Item " + id), quantity, unit,
                quantity * unit,
                id == COINS ? PriceSource.FACE_VALUE
                    : id == BOOK ? PriceSource.UNPRICED : PriceSource.GRAND_EXCHANGE));
        });
        return flows;
    }, new TransactionClassifier(), new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    });
    private long now = 1_000_000L;

    @Test
    public void buyingAnUntradeableIsAPurchaseNotReview()
    {
        // A shop/dialogue purchase of an item with no market (untradeable) spends coins that
        // can never be recovered: the purchase books the cost (Coinflow 1.7.1 calls this the
        // unrealizable case; owner probe 2026-10-13).
        start();
        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction bought = change(COINS, -2L, BOOK, 1L);
        assertSame(TransactionType.TRADE, bought.getType());
        assertEquals("Bought", bought.getNote());
        assertTrue(bought.isCounted());
        assertFalse("not Review", ReviewRules.needsOwnerDecision(bought));
        assertEquals(-2L, engine.getMetrics(now + 1_000L).net);
    }

    @Test
    public void coinsForAnItemWithAShopOpenIsAPurchase()
    {
        start();
        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction bought = change(COINS, -2_000L, JAR, 1L);
        assertSame(TransactionType.TRADE, bought.getType());
        assertEquals("Bought", bought.getNote());
        assertTrue(bought.isCounted());
        assertFalse("not Review", ReviewRules.needsOwnerDecision(bought));
    }

    @Test
    public void itemsForCoinsWithAShopOpenIsASale()
    {
        start();
        assertTrue("without the shop window it stays Review",
            ReviewRules.needsOwnerDecision(change(PLATEBODY, -1L, COINS, 38_000L)));

        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction sold = change(PLATEBODY, -1L, COINS, 38_000L);
        assertSame(TransactionType.TRADE, sold.getType());
        assertSame(Context.MARKET, sold.getContext());
        assertEquals("Sold", sold.getNote());
        assertTrue(sold.isCounted());
        assertFalse("not Review", ReviewRules.needsOwnerDecision(sold));
    }

    @Test
    public void aShopTradeEntryNamesWhatItBoughtOrSold()
    {
        start();
        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        engine.markContext(Context.MARKET, 4, "buy 1 Impling jar");
        Transaction bought = change(COINS, -290L, JAR, 1L);
        assertSame(TransactionType.TRADE, bought.getType());
        assertEquals("a coin shop keeps its own verb", "Traded", Semantics.verbOf(bought));
        assertEquals("Bought Impling jar",
            Semantics.tradedItems(bought, contributionOf(bought, COINS)));
        assertEquals("Paid Coins ×290",
            Semantics.tradedItems(bought, contributionOf(bought, JAR)));

        engine.markContext(Context.MARKET, 4, "buy 50 Death rune");
        Transaction exchanged = change(TOKKUL, -14_550L, DEATH_RUNE, 50L);
        assertSame(TransactionType.TRADE, exchanged.getType());
        assertEquals("a non-coin currency shop reads Exchanged", "Exchanged",
            Semantics.verbOf(exchanged));
        assertEquals("Bought Death rune ×50",
            Semantics.tradedItems(exchanged, contributionOf(exchanged, TOKKUL)));
        assertEquals("Paid Tokkul ×14,550",
            Semantics.tradedItems(exchanged, contributionOf(exchanged, DEATH_RUNE)));

        engine.markContext(Context.MARKET, 4, "sell 1 Rune platebody");
        Transaction sold = change(PLATEBODY, -1L, COINS, 380L);
        assertSame(TransactionType.TRADE, sold.getType());
        assertEquals("Traded", Semantics.verbOf(sold));
        assertEquals("Sold Rune platebody",
            Semantics.tradedItems(sold, contributionOf(sold, COINS)));
        assertEquals("Sold for Coins ×380",
            Semantics.tradedItems(sold, contributionOf(sold, PLATEBODY)));
    }

    @Test
    public void aTokkulSaleThroughItsSellClickIsAnExchangedTrade()
    {
        start();
        // The sell click arms the shop's MARKET context; outside it the same change fails closed.
        assertTrue("without the click context it stays Review",
            ReviewRules.needsOwnerDecision(change(PLATEBODY, -1L, TOKKUL, 380L)));

        engine.markContext(Context.MARKET, 4, "sell 1 Rune platebody");
        Transaction sold = change(PLATEBODY, -1L, TOKKUL, 380L);
        assertSame(TransactionType.TRADE, sold.getType());
        assertSame(Context.MARKET, sold.getContext());
        assertEquals("a non-coin currency shop reads Exchanged", "Exchanged", Semantics.verbOf(sold));
        assertTrue(sold.isCounted());
        assertFalse("not Review", ReviewRules.needsOwnerDecision(sold));
    }

    private static Contribution contributionOf(Transaction transaction, int itemId)
    {
        for (Contribution contribution : Contribution.project(transaction))
            if (contribution.itemId == itemId) return contribution;
        throw new AssertionError("no contribution for item " + itemId);
    }

    @Test
    public void aMixedCoinAndItemGainIsNotASale()
    {
        start();
        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction mixed = change(PLATEBODY, -1L, COINS, 1_000L, JAR, 1L);
        assertTrue("coins plus another item is not a sale",
            ReviewRules.needsOwnerDecision(mixed));
    }

    @Test
    public void aVisibleShopWindowIsShopEvidence()
    {
        assertTrue("InterfaceID.Shopmain.FRAME",
            Widgets.isShopOpen(clientWith(0x012c_0001)));
        assertTrue("InterfaceID.OmnishopMain.FRAME",
            Widgets.isShopOpen(clientWith(0x0333_0007)));
        assertFalse("a quantity button is not the shop window",
            Widgets.isShopOpen(clientWith(0x012c_0008)));
        assertFalse(Widgets.isShopOpen(clientWith(0)));
    }

    private static Client clientWith(int componentId)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[] {Client.class}, (proxy, method, args) ->
            {
                if ("getWidget".equals(method.getName()))
                    return componentId > 0 && (int) args[0] == componentId ? visibleWidget() : null;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                return null;
            });
    }

    private static Widget visibleWidget()
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
            new Class<?>[] {Widget.class}, (proxy, method, args) ->
            {
                if ("isHidden".equals(method.getName())) return false;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                return null;
            });
    }

    private void start()
    {
        engine.startCustom("Shops", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
    }

    private Transaction change(Object... idsAndDeltas)
    {
        for (int index = 0; index < idsAndDeltas.length; index += 2)
        {
            inventory.merge((Integer) idsAndDeltas[index], (Long) idsAndDeltas[index + 1],
                Long::sum);
        }
        inventory.values().removeIf(quantity -> quantity == 0L);
        int before = engine.getActiveSession().getTransactions().size();
        now += 3_000L;
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 600L, null);
        List<Transaction> all = engine.getActiveSession().getTransactions();
        return all.size() > before ? all.get(all.size() - 1) : null;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;

/** Owner report 2026-09-28: ore used up by a failed iron smelt is a supply, not a loss. */
public class SmeltingSupplyTest
{
    private static final int IRON_ORE = 440;
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void aFailedSmeltInsideTheRunIsASupplyAndNeverReview()
    {
        Engine engine = engine();
        engine.startCustom("Smithing", T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(IRON_ORE, 7L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));

        // The furnace's Smelt click (or a failed-smelt message) keeps the run in PRODUCTION.
        engine.markContext(Context.PRODUCTION, 6, "Smelting");
        held.put(IRON_ORE, 6L);
        Transaction failed = settle(engine, held, T0 + 600L);

        assertNotNull(failed);
        assertFalse("a failed smelt is not a Review decision", ReviewRules.needsOwnerDecision(failed));
        assertEquals("the ore it used is a supply", CostKind.SUPPLIES, CostKind.of(failed, failed.getFlows().get(0)));
        assertEquals("the run's first receipt names its skill before any XP", "Smithing", failed.getActivityName());
    }

    @Test
    public void takingOffWornEquipmentStartsNoProductionRun()
    {
        // "Remove" is the worn-equipment option; removing furniture returns nothing to book.
        assertEquals("", ActionSignals.transformSkill("Remove"));
        assertEquals("Construction", ActionSignals.transformSkill("Build"));
    }

    @Test
    public void anOreGoneWithoutAnyRunStaysALoss()
    {
        Engine engine = engine();
        engine.startCustom("Smithing", T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(IRON_ORE, 7L);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(held)));

        held.put(IRON_ORE, 6L);
        Transaction gone = settle(engine, held, T0 + 600L);
        assertNotNull(gone);
        assertEquals(CostKind.LOSS, CostKind.of(gone, gone.getFlows().get(0)));
    }

    private static Transaction settle(Engine engine, Map<Integer, Long> held, long now)
    {
        engine.markDirty();
        Transaction result = null;
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(held)), now + i * 600L, null);
            if (settled != null)
            {
                result = settled;
            }
        }
        return result;
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                flows.add(new Flow(delta.getKey(), "Iron ore", delta.getValue(), 71, delta.getValue() * 71L,
                    PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
