    @Test
    public void anUntradeableWithNoAlchValueIsWorthNothingNotUnpriced()
    {
        Valuation valuation = ModelProbe.valuation(new GpManagerConfig() { }, SpellShapesTest::composition, id -> 0);
        Flow hat = valuation.valueComponent(HAT, 1L, 0L);
        assertSame("a known zero", PriceSource.NO_VALUE, hat.getPriceSource());
        assertEquals(0, hat.unitPrice);
        assertSame("a tradeable item without a quote waits for prices, alch value or not",
            PriceSource.UNPRICED, valuation.valueComponent(BONES, 1L, 0L).getPriceSource());
        assertEquals("rows worth nothing read as a dash", "—", Fmt.worth(0L));
        assertEquals(Fmt.signed(1_200L), Fmt.worth(1_200L));

        Transaction received = settle(Map.of(HAT, 0L), Map.of(HAT, 1L), -1, null, null);
        assertNotNull("receiving it still books", received);
        assertTrue(received.getFlows().get(0).getPriceSource() == PriceSource.NO_VALUE);
    }

    private static Engine last;

    private static Transaction settle(Map<Integer, Long> before, Map<Integer, Long> after, int clicked,
        ActionKind verb, ActionLabel label)
    {
        Engine engine = last = engine();
        engine.startCustom("Magic", T0);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(before)));
        if (verb != null) engine.noteConsume(clicked, 10, false, verb, label);
        engine.markDirty();
        List<Transaction> booked = new ArrayList<>();
        for (int i = 0; i < 3; i++)
        {
            Transaction settled = engine.processIfDirty(new ContainerSnapshot(new HashMap<>(after)),
                T0 + 600L + i * 600L, booked::add);
            if (settled != null) booked.add(settled);
        }
        return booked.isEmpty() ? null : booked.get(0);
    }

    private static Engine engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                boolean worthless = id == PEACH || id == HAT;
                int unit = id == COINS ? 1 : worthless ? 0 : id == PLATESKIRT ? 37_000 : id == SHARD ? 6_000 : 100;
                flows.add(new Flow(id, NAMES.get(id), delta.getValue(), unit, delta.getValue() * unit,
                    worthless ? PriceSource.NO_VALUE : id == COINS ? PriceSource.FACE_VALUE
                        : id == SHARD ? PriceSource.HIGH_ALCHEMY : PriceSource.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }

    private static ItemComposition composition(int id)
    {
        return (ItemComposition) Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
            new Class<?>[] {ItemComposition.class}, (proxy, method, args) -> {
                if ("getName".equals(method.getName())) return NAMES.getOrDefault(id, "Item");
                if ("isTradeable".equals(method.getName())) return id != HAT;
                if ("getHaPrice".equals(method.getName())) return id == BONES ? 50 : 0;
                Class<?> type = method.getReturnType();
                if (type == boolean.class) return false;
                if (type == int.class) return 0;
                if (type == long.class) return 0L;
                return null;
            });
    }
}

package com.gpmanager;

import static com.gpmanager.TargetFreshStartTest.HOUR;
import static com.gpmanager.TargetFreshStartTest.coins;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Owner 1.5.2: the gear menu's Reset free-play moves the run so far to Grinds history, with
 * nothing deleted, and starts a new Free play at zero that keeps the milestone.
 */
public class StartFreePlayOverTest
{
    @Test
    public void theOldRunMovesToHistoryWithEveryRow()
    {
        Engine engine = TargetFreshStartTest.engine();
        Session before = engine.getGeneralSession();
        coins(engine, 5L, 1_000L);
        coins(engine, 10L, 500L);
        engine.setMilestone(1_000_000_000L);
        before.pause(HOUR - 1L, PauseReason.MANUAL);

        assertTrue(engine.startFreePlayOver(HOUR));
        Session kept = engine.getHistory().get(0);
        assertSame("the run is kept, not deleted", before, kept);
        assertEquals("Free play", kept.getName());
        assertTrue(kept.isClosed());
        assertEquals(2, kept.getTransactions().size());
        assertEquals(1_500L, kept.metrics(HOUR).net);

        Session fresh = engine.getGeneralSession();
        assertNotSame(before, fresh);
        assertSame(fresh, engine.getActiveSession());
        assertTrue("the new Free play starts at zero", fresh.getTransactions().isEmpty());
        assertEquals("the milestone counts the new run", Long.valueOf(1_000_000_000L), fresh.milestoneGp);
        assertSame("a manual pause holds", PauseReason.MANUAL, fresh.getPauseReason());
        assertEquals(0L, TargetFreshStartTest.live(engine, HOUR + 1L).runNet);
    }

    /** Owner 1.5.2: Restore swaps a past Free play back in; the current one moves to history. */
    @Test
    public void restoreSwapsAndSwapsBack()
    {
        Engine engine = TargetFreshStartTest.engine();
        Session first = engine.getGeneralSession();
        coins(engine, 5L, 1_000L);
        engine.setMilestone(1_000_000_000L);
        long firstActive = first.getElapsedMillis(HOUR);
        assertTrue(engine.startFreePlayOver(HOUR));
        Session second = engine.getGeneralSession();
        coins(engine, HOUR + 5L, 300L);

        assertTrue(engine.restoreFreePlay(first.getId(), 2 * HOUR));
        assertSame("the old run is Free play again", first, engine.getGeneralSession());
        assertSame(first, engine.getActiveSession());
        assertFalse(first.isClosed());
        assertEquals("every row came back", 1, first.getTransactions().size());
        assertEquals("its active time is unchanged", firstActive, first.getElapsedMillis(2 * HOUR));
        assertEquals(1_000L, TargetFreshStartTest.live(engine, 2 * HOUR).runNet);
        assertEquals(Long.valueOf(1_000_000_000L), first.milestoneGp);
        assertSame("the current run waits in history", second, engine.getHistory().get(0));
        assertTrue(second.isClosed());

        assertTrue("and swaps back", engine.restoreFreePlay(second.getId(), 3 * HOUR));
        assertSame(second, engine.getGeneralSession());
        assertEquals(300L, TargetFreshStartTest.live(engine, 3 * HOUR).runNet);
        assertSame(first, engine.getHistory().get(0));
    }

    @Test
    public void anEmptyCurrentRunIsDroppedAndGrindsCannotBeRestored()
    {
        Engine engine = TargetFreshStartTest.engine();
        Session first = engine.getGeneralSession();
        coins(engine, 5L, 1_000L);
        engine.startFreePlayOver(HOUR);
        assertTrue(engine.restoreFreePlay(first.getId(), 2 * HOUR));
        assertTrue("an empty Free play is not kept", engine.getHistory().isEmpty());

        engine.startCustom("Vorkath", 2 * HOUR);
        assertFalse("not during a Grind", engine.restoreFreePlay(first.getId(), 3 * HOUR));
        engine.finishCustom(3 * HOUR);
        Session grind = engine.getHistory().get(0);
        assertFalse("a Grind run is not Free play", engine.restoreFreePlay(grind.getId(), 4 * HOUR));
    }

    @Test
    public void grindsListsFreePlayApart()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 1_000L);
        engine.startFreePlayOver(HOUR);
        engine.startCustom("Vorkath", HOUR);
        engine.finishCustom(2 * HOUR);
        GrindsData data = GrindsData.capture(engine, 2 * HOUR, false, null);
        long free = data.recent.stream().filter(run -> run.freePlay).count();
        assertEquals("the reset run and the current Free play", 2, free);
        assertTrue(data.recent.stream().anyMatch(run -> !run.freePlay && "Vorkath".equals(run.name)));
    }

    /** Owner live 1.5.2: a past Free play's detail page offers Restore, never Start again. */
    @Test
    public void aPastFreePlayDetailOffersRestore() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.ensureSession(now - HOUR);
        Session old = engine.getGeneralSession();
        coins(engine, now - 60_000L, 1_000L);
        engine.startFreePlayOver(now - 30_000L);
        SidebarPanel panel = MilestoneTest.onEdt(() -> new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null));
        java.util.List<String> buttons = MilestoneTest.onEdt(() ->
        {
            panel.shell().show(Shell.GRINDS);
            new GrindsController(panel).openDetail(old.getId());
            SidebarPanelProbe.refresh(panel);
            java.util.List<String> texts = new java.util.ArrayList<>();
            collect(panel, texts);
            return texts;
        });
        assertTrue("Restore is offered: " + buttons, buttons.contains("Restore"));
        assertFalse("not Start again: " + buttons, buttons.contains("Start again"));
    }

    static void collect(java.awt.Component component, java.util.List<String> out)
    {
        if (component instanceof javax.swing.AbstractButton && component.isVisible())
            out.add(((javax.swing.AbstractButton) component).getText());
        if (component instanceof java.awt.Container)
            for (java.awt.Component child : ((java.awt.Container) component).getComponents())
                collect(child, out);
    }

    @Test
    public void notDuringAGrind() throws Exception
    {
        Engine engine = TargetFreshStartTest.engine();
        engine.startCustom("Vorkath", HOUR);
        assertFalse(engine.startFreePlayOver(HOUR + 1L));

        Engine panelEngine = PresentationLifecycleTest.engine();
        panelEngine.startCustom("Vorkath", System.currentTimeMillis());
        SidebarPanel panel = MilestoneTest.onEdt(() -> new SidebarPanel(panelEngine, PresentationLifecycleTest.config(), null, null, null));
        javax.swing.JPopupMenu menu = MilestoneTest.onEdt(() -> new GrindsController(panel).dataMenu());
        boolean enabled = true;
        for (java.awt.Component item : menu.getComponents())
            if (item instanceof javax.swing.JMenuItem && ((javax.swing.JMenuItem) item).getText().startsWith("Reset free-play"))
                enabled = item.isEnabled();
        assertFalse("the gear item is off during a Grind", enabled);
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The ring of suffering's recoils are committed: a discharge never refunds them, so a load books
 * one counted Supplies row at the recoil's price (owner 2026-10-12). The ring keeps no Check
 * comparison; the effect toggle, an uncharge and the bank's Configure-Charges book nothing.
 */
public class SufferingCommittedLoadTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final String RING = "149:0:9764864:20657:SUFFERING";
    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override public int stabilizationTicks() { return 2; }
        @Override public boolean keepTransferAuditRows() { return true; }
    };

    @Test
    public void committedRecoilLoadsBookTheirRecoilsAsSupplies()
    {
        Engine engine = engine();
        long start = 100_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.RING_OF_RECOIL, 30L));

        assertTrue(engine.markChargeLoad(ChargeCheck.ChargedItem.SUFFERING, ItemID.RING_OF_RECOIL,
            "Ring of recoil", RING, 8));
        engine.markDirty();
        Transaction load = settle(engine, snapshot(ItemID.RING_OF_RECOIL, 25L), start + 600L);

        assertEquals(TransactionType.CONSUMPTION, load.autoType());
        assertTrue(load.isCounted());
        assertEquals(GameData.msg("committed-load") + "Ring of suffering", load.getNote());
        assertEquals(ActionKind.SUPPLIES, load.getActionKind());
        assertEquals(-2_500L, load.getNet());
        assertEquals(2_500L, engine.getMetrics(start + 2_400L).costs);
    }

    @Test
    public void theRingsCheckLineBooksNothing()
    {
        Engine engine = engine();
        long start = 120_000L;
        engine.ensureSession(start);

        // The exact live Check line (owner recording 2026-10-12): a committed load has nothing
        // to compare, so the read never books.
        new ChargeIntake(null, null, CONFIG, engine, null).observeCheck(
            "Your ring currently has 5,097 recoil charges remaining. The recoil effect is currently disabled.",
            start);

        assertTrue(engine.getActiveSession().getTransactions().isEmpty());
        assertEquals(0L, engine.getMetrics(start).net);
    }

    @Test
    public void anUnchargeBooksNothing()
    {
        Engine engine = engine();
        long start = 140_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.NZONE_ZENYTE_RING_ENCHANTED_RECOIL, 1L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Uncharge", item(ItemID.NZONE_ZENYTE_RING_ENCHANTED_RECOIL, 0)),
            "uncharge", "Ring of suffering (ri)");
        assertNotNull("the uncharge watch arms", engine.inbox.peek(Inbox.UNCHARGE));
        engine.markDirty();
        settle(engine, snapshot(ItemID.ZENYTE_RING_ENCHANTED, 1L), start + 600L);

        assertTrue("the charge was booked at load; the uncharge adds nothing",
            engine.getActiveSession().getTransactions().stream().noneMatch(Transaction::isCounted));
        assertEquals(0L, engine.getMetrics(start + 2_400L).net);
    }

    @Test
    public void theBankConfigureChargesRouteNeverPhantomBooks()
    {
        Engine engine = engine();
        long start = 160_000L;
        engine.ensureSession(start);
        engine.setBaseline(snapshot(ItemID.RING_OF_RECOIL, 30L));

        ChargeIntake intent = new ChargeIntake(selecting(null), null, CONFIG, engine, null);
        intent.armCheck(click(MenuAction.CC_OP, "Configure-Charges", item(ItemID.NZONE_ZENYTE_RING_ENCHANTED_RECOIL, 0)),
            "configure-charges", "Ring of suffering (ri)");
        assertNull("no load arms without a use-on click", engine.inbox.peek(Inbox.LOAD_TARGET));

        // Bank-side charges are a documented blind spot: a recoil move without the use click is
        // never a charge load, and the recoils still book as the ordinary spend they are.
        engine.markDirty();
        settle(engine, snapshot(ItemID.RING_OF_RECOIL, 25L), start + 600L);
        for (Transaction row : engine.getActiveSession().getTransactions())
        {
            assertFalse("a bank load cannot phantom-book as a charge load",
                row.getNote() != null && row.getNote().startsWith(GameData.msg("committed-load")));
        }
        assertTrue("the recoils still book ordinarily",
            engine.getActiveSession().getTransactions().stream().anyMatch(Transaction::isCounted));
    }

    private static Engine engine()
    {
        return new Engine(SufferingCommittedLoadTest::flows, new TransactionClassifier(), CONFIG);
    }

    private static List<Flow> flows(Map<Integer, Long> deltas)
    {
        List<Flow> flows = new ArrayList<>();
        for (Map.Entry<Integer, Long> entry : deltas.entrySet())
        {
            flows.add(new Flow(entry.getKey(), "Ring of recoil", entry.getValue(), 500,
                entry.getValue() * 500));
        }
        return flows;
    }

    private static ContainerSnapshot snapshot(int id, long quantity)
    {
        return snapshot(mapOf(id, quantity));
    }

    private static ContainerSnapshot snapshot(Map<Integer, Long> quantities)
    {
        return new ContainerSnapshot(quantities);
    }

    private static Map<Integer, Long> mapOf(Object... values)
    {
        Map<Integer, Long> result = new HashMap<>();
        for (int index = 0; index + 1 < values.length; index += 2)
        {
            result.put((Integer) values[index], (Long) values[index + 1]);
        }
        return result;
    }

    private static Transaction settle(Engine engine, ContainerSnapshot next, long firstTick)
    {
        assertNull(engine.processIfDirty(next, firstTick, null));
        assertNull(engine.processIfDirty(next, firstTick + 600L, null));
        return engine.processIfDirty(next, firstTick + 1_200L, null);
    }

    private static Widget item(int itemId, int slot)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[] {Widget.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getItemId": return itemId;
                    case "getIndex": return slot;
                    case "getId": return InterfaceID.Inventory.ITEMS;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        return null;
                }
            });
    }

    private static Client selecting(Widget selected)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getSelectedWidget": return selected;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
