        restarted.getActiveSession().resume(h.now);
        restarted.seedGeSlots(Collections.singletonMap(0,
            new OfferSlots.Snapshot(0, SELLING, LOGS, 60, 0, 100, 0)), h.now + 500L);

        assertEquals("available coverage survives restart", 40L, EngineProbe.knownCoverageQty(restarted, LOGS)
            - EngineProbe.reservedQty(restarted, LOGS));
        assertEquals(4_000L, EngineProbe.availableBasisGp(restarted, LOGS));
        assertEquals("the open reservation survives restart", 60L,
            EngineProbe.reservedQty(restarted, LOGS));
        assertEquals(6_000L, EngineProbe.reservedBasisGp(restarted, LOGS));
        assertEquals(1, restarted.geCustody.records().size());

        OfferSlots ledger = new OfferSlots();
        OfferSlots.Transition cancel = ledger.observe(
            new OfferSlots.Snapshot(0, CANCELLED_SELL, LOGS, 60, 0, 100, 0)).orElse(null);
        assertNotNull(cancel);
        restarted.noteGeOffer(cancel, "Logs", h.now + 1_000L);
        restarted.markDirty();
        ContainerSnapshot back = new ContainerSnapshot(with(h.inventory, LOGS, 60L));
        for (int i = 0; i < 3; i++)
        {
            restarted.processIfDirty(back, h.now + 1_000L + i * 600L, null);
        }
        assertEquals("cancelling after restart releases the exact reservation", 100L,
            EngineProbe.knownCoverageQty(restarted, LOGS));
        assertEquals(10_000L, EngineProbe.availableBasisGp(restarted, LOGS));
        assertEquals(0L, EngineProbe.reservedQty(restarted, LOGS));
    }

    @Test
    public void schema105MigrationStartsUnknownWithoutBackfill()
    {
        Harness h = new Harness(159);
        h.gain(LOGS, 5L, 775L, h.now - 60_000L);
        long historicalNet = h.net();
        SavedState legacy = h.engine.savedState();
        legacy.setSchemaVersion(105);
        legacy.setTrackedBasis(null);

        Engine migrated = engine(new int[] {159});
        migrated.restore(legacy, h.now + 1_000L);

        assertEquals("no bank or history backfill", 0L, EngineProbe.knownCoverageQty(migrated, LOGS));
        assertEquals(0L, EngineProbe.knownCoverageBasisGp(migrated, LOGS));
        assertEquals("historical Net is unchanged by migration", historicalNet,
            migrated.getMetrics(h.now + 1_000L).net);

        // New post-migration acquisitions still create known coverage.
        Transaction gain = new Transaction(h.now + 2_000L, TransactionType.GAIN,
            Context.GENERIC, "", "Loot", true,
            Collections.singletonList(new Flow(LOGS, "Logs", 3L, 100, 300L,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "", null);
        migrated.getActiveSession().addTransaction(gain, 500, false);
        assertEquals(3L, EngineProbe.knownCoverageQty(migrated, LOGS));
        assertEquals(300L, EngineProbe.knownCoverageBasisGp(migrated, LOGS));
    }

    @Test
    public void bankValueEstimateNeverSeedsOrChangesBasis()
    {
        Harness h = new Harness(159);
        h.gain(LOGS, 5L, 775L, h.now - 60_000L);
        long qty = EngineProbe.knownCoverageQty(h.engine, LOGS);
        long basis = EngineProbe.knownCoverageBasisGp(h.engine, LOGS);

        h.quote[0] = 900;
        assertEquals("a price/estimate change never seeds basis", 0L,
            EngineProbe.knownCoverageQty(h.engine, COINS));
        assertEquals(qty, EngineProbe.knownCoverageQty(h.engine, LOGS));
        assertEquals("a price/estimate change never reprices basis", basis,
            EngineProbe.knownCoverageBasisGp(h.engine, LOGS));

        h.sell(0, LOGS, 5L, 900, 4_500L);
        assertEquals("basis stays the exact counted value", 775L + (4_500L - 775L), h.net());
    }

    // ---- harness ----------------------------------------------------------------------------

    private static final class Harness
    {
        final int[] quote;
        final Engine engine;
        final OfferSlots ledger = new OfferSlots();
        long now = T0;
        Map<Integer, Long> inventory = new HashMap<>();

        Harness(int initialQuote)
        {
            quote = new int[] { initialQuote };
            engine = engine(quote);
            engine.startCustom("Trading", now);
            inventory.put(COINS, 1_000_000L);
            engine.setBaseline(new ContainerSnapshot(inventory));
        }

        void gain(int item, long qty, long value, long at)
        {
            book(new Transaction(at, TransactionType.GAIN, Context.GENERIC, "",
                "Loot", true,
                Collections.singletonList(new Flow(item, name(item), qty,
                    (int) (qty > 0L ? value / qty : 0L), value, PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED, "", null));
        }

        void zeroGain(int item, long qty, long at)
        {
            book(new Transaction(at, TransactionType.GAIN, Context.GENERIC, "",
                "Loot", true,
                Collections.singletonList(new Flow(item, name(item), qty, 0, 0L,
                    PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED, "", null));
        }

        void unpricedGain(int item, long qty, long at)
        {
            book(new Transaction(at, TransactionType.GAIN, Context.GENERIC, "",
                "Loot", true,
                Collections.singletonList(new Flow(item, name(item), qty, 0, 0L,
                    PriceSource.UNPRICED)),
                Confidence.CONFIRMED, "", null));
        }

        void sink(int item, long qty, long at)
        {
            book(new Transaction(at, TransactionType.CONSUMPTION, Context.GENERIC,
                "", "Used", true,
                Collections.singletonList(new Flow(item, name(item), -qty, 100, -qty * 100L,
                    PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED, "", null));
        }

        void transfer(int item, long qty, long at)
        {
            book(new Transaction(at, TransactionType.TRANSFER, Context.TRANSFER,
                "Bank deposit", "Transfer", false,
                Collections.singletonList(new Flow(item, name(item), -qty, 100, -qty * 100L,
                    PriceSource.GRAND_EXCHANGE)),
                Confidence.CONFIRMED, "", null));
        }

        void book(Transaction transaction)
        {
            engine.getActiveSession().addTransaction(transaction, 500, false);
        }

        void sell(int slot, int item, long qty, int limit, long cash)
        {
            inventory = with(inventory, item, qty);
            engine.setBaseline(new ContainerSnapshot(inventory));
            offer(slot, SELLING, item, (int) qty, 0, limit, 0);
            inventory = with(inventory, item, 0L);
            settle(inventory);
            offer(slot, SOLD, item, (int) qty, (int) qty, limit, (int) cash);
            inventory = with(inventory, COINS, inventory.getOrDefault(COINS, 0L) + cash);
            settle(inventory);
        }

        void buy(int slot, int item, long qty, int limit, long spend)
        {
            offer(slot, BUYING, item, (int) qty, 0, limit, 0);
            inventory = with(inventory, COINS, inventory.getOrDefault(COINS, 0L) - spend);
            settle(inventory);
            offer(slot, BOUGHT, item, (int) qty, (int) qty, limit, (int) spend);
            inventory = with(inventory, item, qty);
            settle(inventory);
        }

        void offer(int slot, GrandExchangeOfferState state, int item, int total, int traded,
            int price, int spent)
        {
            now += 600L;
            OfferSlots.Transition transition = ledger.observe(
                new OfferSlots.Snapshot(slot, state, item, total, traded, price, spent)).orElse(null);
            if (transition != null)
            {
                engine.noteGeOffer(transition, name(transition.current.itemId), now);
            }
        }

        Transaction settle(Map<Integer, Long> next)
        {
            now += 600L;
            inventory = new HashMap<>(next);
            engine.markDirty();
            ContainerSnapshot snapshot = new ContainerSnapshot(inventory);
            Transaction result = null;
            for (int i = 0; i < 3; i++)
            {
                Transaction settled = engine.processIfDirty(snapshot, now, null);
                if (settled != null)
                {
                    result = settled;
                }
                now += 600L;
            }
            return result;
        }

        long net()
        {
            return engine.getMetrics(now).net;
        }

        List<MarketRows.Row> rows()
        {
            return engine.marketRows();
        }

        Transaction ajs(String id)
        {
            for (Transaction transaction : engine.getActiveSession().getTransactions())
            {
                if (transaction != null && transaction.getId().equals(id))
                {
                    return transaction;
                }
            }
            return null;
        }
    }

    private static String name(int id)
    {
        return id == COINS ? "Coins" : id == LOGS ? "Logs" : "Item " + id;
    }

    private static Map<Integer, Long> with(Map<Integer, Long> base, Object... pairs)
    {
        Map<Integer, Long> map = new HashMap<>(base);
        for (int i = 0; i < pairs.length; i += 2)
        {
            long quantity = (Long) pairs[i + 1];
            if (quantity <= 0L)
            {
                map.remove((Integer) pairs[i]);
            }
            else
            {
                map.put((Integer) pairs[i], quantity);
            }
        }
        return map;
    }

    private static Engine engine(int[] quote)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                int unit = id == COINS ? 1 : quote[0];
                PriceSource source = id == COINS ? PriceSource.FACE_VALUE
                    : unit > 0 ? PriceSource.GRAND_EXCHANGE : PriceSource.UNPRICED;
                flows.add(new Flow(id, name(id), delta.getValue(), unit, delta.getValue() * unit,
                    source));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TransactionClassifierTest
{
    private final TransactionClassifier classifier = new TransactionClassifier();

    @Test
    public void transferContextAlwaysWins()
    {
        assertEquals(
            TransactionType.TRANSFER,
            classifier.classify(
                Context.TRANSFER,
                Collections.singletonList(new Flow(1, "Item", 1, 100, 100))));
    }

    @Test
    public void genericMixedFlowsBecomeUncertain()
    {
        assertEquals(
            TransactionType.UNCERTAIN,
            classifier.classify(
                Context.GENERIC,
                Arrays.asList(
                    new Flow(1, "Input", -1, 100, -100),
                    new Flow(2, "Output", 1, 150, 150))));
    }

    @Test
    public void lootContextLabelsPositiveFlowAsLoot()
    {
        assertEquals(
            TransactionType.LOOT,
            classifier.classify(
                Context.LOOT,
                Collections.singletonList(new Flow(1, "Drop", 1, 100, 100))));
    }

    @Test
    public void productionContextLabelsMixedFlowsAsProcessing()
    {
        assertEquals(
            TransactionType.PROCESSING,
            classifier.classify(
                Context.PRODUCTION,
                Arrays.asList(
                    new Flow(1, "Input", -1, 100, -100),
                    new Flow(2, "Output", 1, 150, 150))));
    }

    @Test
    public void playerLootContextLabelsPositiveFlowAsPkLoot()
    {
        assertEquals(
            TransactionType.PK_LOOT,
            classifier.classify(
                Context.PK_LOOT,
                Collections.singletonList(new Flow(1, "Drop", 1, 100, 100))));
    }

    @Test
    public void unpricedQuantityStillHasItsRealDirection()
    {
        Flow gain = new Flow(1, "Unknown gain", 2, 0, 0, PriceSource.UNPRICED);
        Flow cost = new Flow(2, "Unknown cost", -1, 0, 0, PriceSource.UNPRICED);

        assertEquals(TransactionType.GAIN,
            classifier.classify(Context.GENERIC, Collections.singletonList(gain)));
        assertEquals(TransactionType.CONSUMPTION,
            classifier.classify(Context.GENERIC, Collections.singletonList(cost)));
        assertEquals(TransactionType.UNCERTAIN,
            classifier.classify(Context.GENERIC, Arrays.asList(gain, cost)));
    }

}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-09 (1.3.0): Barrows gear wearing down a stage or repaired is the same item, so
 * neutral, while the repair fee counts; an NPC paid in a skilling currency is a purchase; an
 * Imp-in-a-box sends items to the bank; a fishing key half is an ordinary gain.
 */
public class WearAndCurrencyTest
{
    private static final int COINS = 995;
    private static final int HELM = 4716;
    private static final int HELM_100 = 4880;
    private static final int HELM_75 = 4881;
    private static final int HELM_0 = 4884;
    private static final int KEY_HALF = 985;
    private static final int FLAKES = 25129;
    private static final int FISH_BARREL = 25582;
    private static final Map<Integer, String> NAMES = Map.of(COINS, "Coins", HELM, "Dharok's helm",
        HELM_100, "Dharok's helm 100", HELM_75, "Dharok's helm 75", HELM_0, "Dharok's helm 0",
        KEY_HALF, "Tooth half of key", FLAKES, "Spirit flakes", FISH_BARREL, "Fish barrel");
    private static final Map<Integer, Integer> PRICES = Map.of(COINS, 1, HELM, 1_200_000, HELM_100, 1_200_000,
        HELM_75, 1_200_000, HELM_0, 60_000, KEY_HALF, 9_543, FLAKES, 20, FISH_BARREL, 0);

    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 1_000_000L, HELM, 1L, FLAKES, 6_000L));
    private final Engine engine = new Engine(deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, NAMES.get(id), quantity, PRICES.get(id),
            quantity * PRICES.get(id), id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE)));
        return flows;
    }, new TransactionClassifier(), new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    });
    private long now = 1_000_000L;

    @Test
    public void barrowsWearIsNeutralAndOnlyTheRepairFeeCounts()
    {
        start();
        change(HELM, -1L, HELM_100, 1L);
        change(HELM_100, -1L, HELM_75, 1L);
        change(HELM_75, -1L, HELM_0, 1L);
        assertEquals("wearing down books nothing", 0L, net());
        assertTrue("and nothing waits in Review", engine.getActiveSession().getTransactions().stream().noneMatch(ReviewRules::needsOwnerDecision));

        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction repair = change(HELM_0, -1L, COINS, -100_000L, HELM, 1L);
        assertTrue(repair.isCounted());
        assertEquals("only the fee counts", -100_000L, net());

        assertNull("an ordinary Barrows buy is not wear", Engine.piece(new Flow(COINS, "Coins", 1L, 1, 1L)));
        assertEquals("dharok's helm", Engine.piece(new Flow(HELM_75, "Dharok's helm 75", 1L, 0, 0L)));
    }

    @Test
    public void anNpcPaidInSkillingCurrencyIsAPurchase()
    {
        start();
        engine.inbox.put(Inbox.DIALOGUE, 0, 1L, 4, null);
        Transaction bought = change(FLAKES, -6_000L, FISH_BARREL, 1L);
        assertSame(TransactionType.TRADE, bought.getType());
        assertSame(Context.MARKET, bought.getContext());
        assertTrue("not Review", !ReviewRules.needsOwnerDecision(bought));
    }

    @Test
    public void anImpInABoxBanksAndAKeyHalfIsAGain()
    {
        assertEquals("Sent to the bank by an imp-in-a-box", NeutralTransfers.storage("use dragon bones -> imp-in-a-box(2)"));
        assertEquals("Master scroll book", NeutralTransfers.storage("use teleport to house -> master scroll book"));
        assertTrue("a loot sack is held at zero until opened", ActionReader.isClaim("Hunters' loot sack (expert)"));
        for (String bag : new String[] {"Tiny port coin bag", "Port coin bag", "Large port reward bag", "Hallowed sack"})
        {
            assertTrue(bag + " is held at zero until opened", ActionReader.isClaim(bag));
        }
        assertTrue("an empty sack is no claim", !ActionReader.isClaim("Empty sack"));
        start();
        Transaction half = change(KEY_HALF, 1L);
        assertSame(TransactionType.GAIN, half.getType());
        assertEquals(9_543L, net());
    }

    private void start()
    {
        engine.startCustom("Barrows", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
    }

    private Transaction change(Object... idsAndDeltas)
    {
        for (int index = 0; index < idsAndDeltas.length; index += 2)
        {
            inventory.merge((Integer) idsAndDeltas[index], (Long) idsAndDeltas[index + 1], Long::sum);
        }
        inventory.values().removeIf(quantity -> quantity == 0L);
        int before = engine.getActiveSession().getTransactions().size();
        now += 3_000L;
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 600L, null);
        List<Transaction> all = engine.getActiveSession().getTransactions();
        return all.size() > before ? all.get(all.size() - 1) : null;
    }

    private long net()
    {
        return engine.getMetrics(now + 60_000L).net;
    }
}

