            ChargeCheck.ChargedItem.TRIDENT_SEAS, DEATH_RUNE, "Death runes"));
        assertTrue(ChargeCheck.isLoadComponent(
            ChargeCheck.ChargedItem.TRIDENT_SEAS, COINS, "Coins"));
        assertFalse(ChargeCheck.isLoadComponent(
            ChargeCheck.ChargedItem.TRIDENT_SEAS, ZULRAH_SCALES, "Zulrah's scales"));
        assertTrue(ChargeCheck.isLoadComponent(
            ChargeCheck.ChargedItem.TRIDENT_SWAMP_ENHANCED, ZULRAH_SCALES, "Zulrah's scales"));
        assertTrue(ChargeCheck.isLoadComponent(
            ChargeCheck.ChargedItem.BLOWPIPE, ItemID.ADAMANT_DART, "Adamant dart"));
        assertFalse(ChargeCheck.isLoadComponent(
            ChargeCheck.ChargedItem.BLOWPIPE, ItemID.ADAMANT_DART, "Rune dart"));
        assertFalse(ChargeCheck.isLoadComponent(
            ChargeCheck.ChargedItem.BLOWPIPE, ItemID.DRAGON_DART_P, "Dragon dart"));
    }

    @Test
    public void unrelatedAndMalformedMessagesCannotSpend()
    {
        assertNull(ChargeCheck.parse("You cast a spell."));
        ChargeCheck malformed = ChargeCheck.parse(
            "Darts: Adamant dart x many. Scales: 100 (1.0%).");
        assertNotNull(malformed);
        assertFalse(malformed.bookable);

        MeasuredChargeReadTracker tracker = new MeasuredChargeReadTracker();
        ChargeOutcomeTest.none(observe(tracker, trident("seas", "", 10)));
        ChargeOutcomeTest.none(observe(tracker, malformed));
        assertNull(tracker.baselines.get("single-target"));
    }

    private static ChargeDelta observe(
        MeasuredChargeReadTracker tracker,
        ChargeCheck read)
    {
        return tracker.observe(read, "single-target", System.currentTimeMillis());
    }

    private static ChargeCheck trident(String type, String enhanced, long charges)
    {
        String count = charges == 1L ? "one charge" : charges == 0L ? "no charges" : charges + " charges";
        return ChargeCheck.parse(
            "Your Trident of the " + type + enhanced + " has " + count + ".");
    }

    private static ChargeCheck blowpipe(String dart, long scales, long darts)
    {
        return ChargeCheck.parse(
            "Darts: " + dart + " dart x " + darts + ". Scales: " + scales + " (1.0%).");
    }

    private static ChargeCheck noDarts(long scales)
    {
        return ChargeCheck.parse(
            "Darts: None. Scales: " + scales + " (1.0%).");
    }

    private static MenuOptionClicked menuCheck(int itemId, int widgetId, int slot)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return "Check";
                    case "getTarget": return "Toxic blowpipe";
                    case "getIdentifier": return itemId;
                    case "getItemId": return itemId;
                    case "getType": return MenuAction.ITEM_FIRST_OPTION;
                    case "getParam0": return slot;
                    case "getParam1": return widgetId;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }

    /** A worn Check whose item and widget fields are omitted; the slot widget carries both. */
    private static MenuOptionClicked menuCheckViaWidget(int itemId, int widgetId, int slot)
    {
        Widget widget = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
            new Class<?>[] {Widget.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getId": return widgetId;
                    case "getItemId": return itemId;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return "Check";
                    case "getTarget": return "Toxic blowpipe";
                    case "getIdentifier": return -1;
                    case "getItemId": return -1;
                    case "getType": return MenuAction.ITEM_FIRST_OPTION;
                    case "getParam0": return slot;
                    case "getParam1": return 0;
                    case "getWidget": return widget;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }

    private static long quantityDelta(ChargeDelta delta, int itemId)
    {
        assertNotNull(delta);
        for (ChargeDelta.ComponentDelta component : delta.getComponentDeltas())
        {
            if (component.getItemId() == itemId)
            {
                return component.getQuantityDelta();
            }
        }
        throw new AssertionError("Missing component delta for item " + itemId);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class CostKindTest
{
    @Test
    public void classifiesSupplyLossAndMarketFromEffectiveCountedFlows()
    {
        assertEquals(CostKind.SUPPLIES, kind(TransactionType.CONSUMPTION, "Eating", 7, -100L));
        // A decrease nobody evidenced (no action kind) is an item gone: a loss, never a supply.
        assertEquals(CostKind.LOSS, kind(TransactionType.CONSUMPTION, "Unexplained", 7, -100L));
        assertEquals(CostKind.SUPPLIES, kind(TransactionType.PROCESSING, "Herblore", 7, -100L));
        assertEquals(CostKind.SUPPLIES, kind(TransactionType.PK_SUPPLY_COST, "PKing", 7, -100L));
        assertEquals(CostKind.LOSS, kind(TransactionType.PK_DEATH_LOSS, "PKing", 7, -100L));
        // The death-reclaim fee is a plain typed consumption; the label is not the authority.
        assertEquals(CostKind.LOSS, kind(TransactionType.CONSUMPTION, "Death reclaim", 7, -100L));
        assertEquals(CostKind.MARKET, kind(TransactionType.TRADE, "GE buy", 7, -100L));
    }

    /** Owner 1.1: burying, scattering and offering are Supplies, like eating; never a loss. */
    @Test
    public void buryScatterAndOfferAreSupplies()
    {
        for (ActionKind kind : new ActionKind[] {ActionKind.BURY, ActionKind.SCATTER, ActionKind.OFFER})
        {
            Transaction spend = transaction(TransactionType.CONSUMPTION, "Prayer", 526, -100L);
            spend.setActionKind(kind);
            assertEquals(kind.name(), CostKind.SUPPLIES, CostKind.of(spend, spend.getFlows().get(0)));
        }
    }

    @Test
    public void actionTaxAndCorrectionsUseEffectiveContribution()
    {
        Transaction action = transaction(TransactionType.GAIN, "General", 7, -100L);
        action.setActionKind(ActionKind.EAT);
        assertEquals(CostKind.SUPPLIES, CostKind.of(action, action.getFlows().get(0)));

        Transaction tax = transaction(TransactionType.ADJUSTMENT, "GE", CostKind.GE_TAX_ITEM_ID, -100L);
        assertEquals(CostKind.LOSS, CostKind.of(tax, tax.getFlows().get(0)));

        Transaction corrected = transaction(TransactionType.LOOT, "Loot", 7, 100L);
        corrected.applyCorrection(Correction.COST, 10L, "Owner correction");
        assertEquals(CostKind.LOSS, CostKind.of(corrected, corrected.getFlows().get(0)));
        corrected.applyCorrection(Correction.IGNORE, 11L, "Owner exclusion");
        assertEquals(CostKind.NONE, CostKind.of(corrected, corrected.getFlows().get(0)));
    }

    @Test
    public void presentationTextNeverSelectsTheCategory()
    {
        // A tax-looking explanation cannot reclassify a typed trade.
        Transaction annotated = transaction(TransactionType.TRADE, "GE buy", 7, -100L);
        annotated.setExplanation("Grand Exchange collect. GE tax 2% (capped).");
        assertEquals(CostKind.MARKET, CostKind.of(annotated, annotated.getFlows().get(0)));

        // A death-reclaim activity label cannot reclassify a typed trade either.
        assertEquals(CostKind.MARKET, kind(TransactionType.TRADE, "Death reclaim", 7, -100L));

        // A typed action kind, not a tax-looking label, selects Supplies.
        Transaction labelled = transaction(TransactionType.CONSUMPTION, "ge tax 2% (capped)", 7, -100L);
        labelled.setActionKind(ActionKind.EAT);
        assertEquals("a typed action kind, not the label, selects Supplies",
            CostKind.SUPPLIES, CostKind.of(labelled, labelled.getFlows().get(0)));

        // A free-form owner reason cannot manufacture a tax category on a market movement.
        Transaction reasonTax = transaction(TransactionType.TRADE, "GE", 7, -100L);
        reasonTax.applyCorrection(Correction.COST, 10L, "GE tax settlement");
        assertEquals(CostKind.MARKET, CostKind.of(reasonTax, reasonTax.getFlows().get(0)));

        // The synthetic tax flow id remains the typed tax authority whatever the label says.
        assertEquals(CostKind.LOSS, kind(TransactionType.ADJUSTMENT, "anything", CostKind.GE_TAX_ITEM_ID, -100L));
    }

    @Test
    public void uncountedTransfersAndDeferredClaimsAreNotCostKinds()
    {
        Transaction transfer = transaction(TransactionType.TRANSFER, "Bank", 7, -100L);
        assertEquals(CostKind.NONE, CostKind.of(transfer, transfer.getFlows().get(0)));

        Transaction uncounted = Tx.of(1L, TransactionType.CONSUMPTION,
            Context.GENERIC, "review", false,
            Collections.singletonList(new Flow(7, "Food", -1L, 100, -100L)));
        assertEquals(CostKind.NONE, CostKind.of(uncounted, uncounted.getFlows().get(0)));

        Transaction deferred = transaction(TransactionType.CONSUMPTION, "Chest", 7, -100L);
        deferred.setActionKind(ActionKind.DEFERRED_CLAIM);
        assertEquals(CostKind.NONE, CostKind.of(deferred, deferred.getFlows().get(0)));
    }

    @Test
    public void typedCategoryIsDeterministicAcrossSerialization()
    {
        com.google.gson.Gson gson = new com.google.gson.Gson();
        Transaction tax = transaction(TransactionType.ADJUSTMENT, "GE", CostKind.GE_TAX_ITEM_ID, -100L);
        Transaction trade = transaction(TransactionType.TRADE, "GE buy", 7, -100L);
        Transaction fee = transaction(TransactionType.CONSUMPTION, "Death reclaim", 7, -100L);

        Transaction restoredTax = gson.fromJson(gson.toJson(tax), Transaction.class);
        Transaction restoredTrade = gson.fromJson(gson.toJson(trade), Transaction.class);
        Transaction restoredFee = gson.fromJson(gson.toJson(fee), Transaction.class);

        assertEquals(CostKind.LOSS, CostKind.of(restoredTax, restoredTax.getFlows().get(0)));
        assertEquals(CostKind.MARKET, CostKind.of(restoredTrade, restoredTrade.getFlows().get(0)));
        assertEquals("a legacy reclaim fee row stays a typed loss after reload",
            CostKind.LOSS, CostKind.of(restoredFee, restoredFee.getFlows().get(0)));
    }

    private static CostKind kind(TransactionType type, String activity, int itemId, long value)
    {
        Transaction transaction = transaction(type, activity, itemId, value);
        return CostKind.of(transaction, transaction.getFlows().get(0));
    }

    private static Transaction transaction(TransactionType type, String activity,
        int itemId, long value)
    {
        Transaction transaction = Tx.of(1L, null, type, Context.GENERIC,
            activity, activity, true,
            Collections.singletonList(new Flow(itemId, "Item", value >= 0 ? 1L : -1L,
                (int) Math.min(Integer.MAX_VALUE, Math.abs(value)), value)));
        if ("Eating".equals(activity)) transaction.setActionKind(ActionKind.EAT);
        return transaction;
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Release pass 2026-09-28: the dose pairing (a sip books one dose, never a gain plus a whole potion)
 * must agree everywhere money is read. For generated sips, bites, decants, mixed loot and corrected
 * rows: the per-flow amounts add up to the transaction amounts, Net stays the raw flow sum, the cost
 * split covers the costs, and the Ledger contributions add up to the same Net.
 */
public class DosePairingInvariantTest
{
    private static final String[] POTIONS = {"Prayer potion", "Super defence", "Saradomin brew"};
    private static final ActionKind[] ACTIONS = {ActionKind.DRINK, ActionKind.EAT, ActionKind.SUPPLIES, null};
    private static final Correction[] CORRECTIONS = {Correction.AUTO, Correction.AUTO,
        Correction.AUTO, Correction.COST, Correction.REVENUE, Correction.IGNORE};

    @Test
    public void everyReaderAgreesOnGeneratedConsumption()
    {
        Random random = new Random(20260928L);
        int paired = 0;
        for (int i = 0; i < 2_000; i++)
        {
            Transaction transaction = generated(random, i);
            Accounting.Amounts total = Accounting.transaction(transaction);
            if (!total.included)
            {
                continue;
            }
            long revenue = 0L;
            long costs = 0L;
            long raw = 0L;
            for (Flow flow : transaction.getFlows())
            {
                Accounting.Amounts amounts = Accounting.flow(transaction, flow);
                revenue += amounts.revenue;
                costs += amounts.costs;
                raw += flow.valueDelta;
            }
            String where = "case " + i + " " + transaction.getFlows();
            assertEquals(where, total.revenue, revenue);
            assertEquals(where, total.costs, costs);
            if (transaction.getCorrection() == Correction.AUTO)
            {
                assertEquals("Net stays the raw flow sum: " + where, raw, total.getNet());
            }
            Accounting.CostSplit split = Accounting.costSplit(transaction);
            if (split.available)
            {
                assertEquals("the split covers the costs: " + where, total.costs, split.supplies + split.other);
            }
            long ledger = 0L;
            for (Contribution contribution : Contribution.project(transaction))
            {
                ledger += contribution.effectiveValue;
            }
            assertEquals("the Ledger adds up to Net: " + where, total.getNet(), ledger);
            if (!Accounting.consumePairs(transaction).isEmpty())
            {
                paired++;
            }
        }
        assertTrue("the generator exercises dose pairs (" + paired + ")", paired > 200);
    }

    private static Transaction generated(Random random, int i)
    {
        List<Flow> flows = new ArrayList<>();
        String potion = POTIONS[random.nextInt(POTIONS.length)];
        int dose = 1 + random.nextInt(4);
        int unit = 500 + random.nextInt(3_000);
        long sips = 1 + random.nextInt(3);
        switch (random.nextInt(5))
        {
            case 0:
                // A sip: (n) -> (n-1), or (1) -> vial or nothing.
                flows.add(new Flow(1_000 + dose, potion + "(" + dose + ")", -sips, unit * dose, -sips * unit * dose));
                if (dose > 1)
                {
                    flows.add(new Flow(1_000 + dose - 1, potion + "(" + (dose - 1) + ")", sips, unit * (dose - 1),
                        sips * unit * (dose - 1)));
                }
                else if (random.nextBoolean())
                {
                    flows.add(new Flow(229, "Vial", sips, 3, sips * 3));
                }
                break;
            case 1:
                // A bite of a pie.
                flows.add(new Flow(2327, "Meat pie", -1L, 40, -40L));
                flows.add(new Flow(2331, "Half a meat pie", 1L, 18, 18L));
                break;
            case 2:
                // A decant: two (2) become one (4); doses are conserved.
                flows.add(new Flow(1_002, potion + "(2)", -2L, unit * 2, -4L * unit));
                flows.add(new Flow(1_004, potion + "(4)", 1L, unit * 4, 4L * unit));
                flows.add(new Flow(229, "Vial", 1L, 3, 3L));
                break;
            case 3:
                // A sip settled together with a pickup.
                flows.add(new Flow(1_000 + dose, potion + "(" + dose + ")", -1L, unit * dose, -(long) unit * dose));
                if (dose > 1)
                {
                    flows.add(new Flow(1_000 + dose - 1, potion + "(" + (dose - 1) + ")", 1L, unit * (dose - 1),
                        (long) unit * (dose - 1)));
                }
                flows.add(new Flow(536, "Dragon bones", 1L + random.nextInt(3), 2_000, 2_000L * (1 + random.nextInt(3))));
                break;
            default:
                // A price that fell between the sip's two legs (the remainder worth more than the loss).
                flows.add(new Flow(1_002, potion + "(2)", -1L, unit, -unit));
                flows.add(new Flow(1_001, potion + "(1)", 1L, unit * 2, unit * 2L));
                break;
        }
        TransactionType type = random.nextInt(4) == 0 ? TransactionType.LOOT : TransactionType.CONSUMPTION;
        Transaction transaction = new Transaction(1_000L + i, type, Context.GENERIC, "",
            "Vorkath", true, flows, Confidence.LIKELY, "fixture", null);
        transaction.setActionKind(ACTIONS[random.nextInt(ACTIONS.length)]);
        Correction correction = CORRECTIONS[random.nextInt(CORRECTIONS.length)];
        if (correction != Correction.AUTO)
        {
            transaction.applyCorrection(correction, 2_000L + i);
        }
        return transaction;
    }
}

