package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Derived Market settlement projection contract: behavioural lifecycles, exact economics, pending
 * edge separated from realized result, and fail-closed unavailability. It books nothing.
 */
public class MarketSettlementProjectionTest
{
    private static GeOffer sell(long offered, long captured, long filled, long spent,
        long settled, long settledExecution, long settledCash, long realized)
    {
        GeOffer record = new GeOffer("offer-" + offered + "-" + filled, 0,
            GeOffer.Side.SELL, 561, "Nature rune", offered, 7L, 1_000L, "session-a");
        record.setCapturedQty(captured);
        record.setFilledQty(filled);
        record.setSpentGp(spent);
        record.setSettledQty(settled);
        record.setSettledExecutionGp(settledExecution);
        record.setSettledCashGp(settledCash);
        record.setRealizedResultGp(realized);
        record.setBasisUnitPrice(6L);
        record.setBasisSource(PriceSource.GRAND_EXCHANGE);
        record.setBasisCapturedAtEpochMillis(1_000L);
        return record;
    }

    @Test
    public void pendingExecutionEdgeIsNeverRealized()
    {
        GeOffer record = sell(10, 10, 10, 70, 0, 0, 0, 0);
        record.setOfferState("SOLD");
        MarketRows.Row row = MarketFacts.row(record);

        assertEquals(MarketRows.Lifecycle.EXECUTED_UNSETTLED, row.lifecycle);
        assertEquals(0L, row.realizedResultGp);
        assertFalse(row.isRealizedIncluded());
    }

    @Test
    public void settlementAdjustmentAndRealizedResultAreExact()
    {
        GeOffer record = sell(10, 10, 10, 70, 10, 70, 69, 9);
        record.setOfferState("SOLD");
        MarketRows.Row row = MarketFacts.row(record);

        assertEquals(MarketRows.Lifecycle.REALIZED, row.lifecycle);
        assertEquals(60L, MarketFacts.basisValueGp(record));
        assertEquals(69L, row.observedSettlementGp);
        assertEquals(-1L, row.settlementAdjustmentGp);
        assertEquals(9L, row.realizedResultGp);
        assertTrue(row.isRealizedIncluded());
    }

    @Test
    public void partiallyRealizedCountsOnlySettledQuantity()
    {
        GeOffer record = sell(100, 100, 100, 700, 40, 280, 280, 40);
        record.setOfferState("SELLING");
        MarketRows.Row row = MarketFacts.row(record);

        assertEquals(MarketRows.Lifecycle.PARTIALLY_REALIZED, row.lifecycle);
        assertEquals(40L, row.settledQty);
        assertEquals(40L, row.realizedResultGp);
    }

    @Test
    public void cancellingBeforeAnyFillIsCancelledReturned()
    {
        GeOffer record = sell(100, 100, 0, 0, 0, 0, 0, 0);
        record.setOfferState("CANCELLED_SELL");
        record.setReturnedQty(100L);
        MarketRows.Row row = MarketFacts.row(record);

        assertEquals(MarketRows.Lifecycle.CANCELLED_RETURNED, row.lifecycle);
    }

    @Test
    public void ambiguousAndLegacyFailClosed()
    {
        GeOffer ambiguous = sell(10, 10, 10, 70, 0, 0, 0, 0);
        ambiguous.setQuantityModified(true);
        assertEquals(MarketRows.Lifecycle.AMBIGUOUS,
            MarketRows.lifecycleOf(ambiguous));

        GeOffer legacy = sell(10, 0, 4, 28, 0, 0, 0, 0);
        legacy.setConfidence(GeOffer.CustodyConfidence.LEGACY_UNBASED);
        assertEquals(MarketRows.Lifecycle.UNAVAILABLE,
            MarketRows.lifecycleOf(legacy));
        assertEquals("unknown basis is never presented as a value", -1L,
            MarketFacts.basisValueGp(legacy));
    }

    @Test
    public void anOpenOfferAfterARelogIsStillPending()
    {
        GeOffer record = sell(10, 10, 0, 0, 0, 0, 0, 0);
        record.setOfferState("SELLING");
        assertEquals(MarketRows.Lifecycle.PENDING,
            MarketRows.lifecycleOf(record));
    }

    @Test
    public void rowsAreReadOnlyAndEmptyInputsAreSafe()
    {
        assertTrue(MarketRows.rows(Collections.emptyList(), null, null).isEmpty());
        assertTrue(MarketRows.rows(null, null, null).isEmpty());
    }

    @Test
    public void aSaleWhoseReceiptWasCompactedIsHistoryNotReview()
    {
        GeOffer record = sell(10, 10, 10, 70, 10, 70, 69, 9);
        record.setOfferState("SOLD");
        record.setSettlementId("compacted-receipt");
        MarketRows.Row row = MarketRows.rows(Collections.singletonList(record), id -> null, null).get(0);
        assertTrue(row.isRealizedIncluded());
        assertFalse("its money is already in the retained totals; nothing to decide",
            Semantics.marketUnit(row, Collections.emptyList()).reviewRequired);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.List;

/** Test-side reads of model state; moved out of production to keep the plugin small. */
public final class ModelProbe
{
    private ModelProbe()
    {
    }

    /** A valuation from a plain price per item id: NORMAL economy, no guard (moved out of the plugin). */
    public static Valuation valuation(GpManagerConfig config, java.util.function.IntFunction<net.runelite.api.ItemComposition> compositions,
        java.util.function.IntUnaryOperator prices)
    {
        return new Valuation(config, compositions, (id, active) -> prices.applyAsInt(id));
    }

    public static Valuation valuation(GpManagerConfig config, java.util.function.IntFunction<net.runelite.api.ItemComposition> compositions,
        Valuation.MarketQuote quotes)
    {
        return new Valuation(config, compositions, quotes);
    }

    /** The session's corrections that have not been undone, oldest first. */
    public static List<CorrectionRecord> activeCorrections(Session session)
    {
        List<CorrectionRecord> active = new ArrayList<>();
        for (CorrectionRecord record : session.correctionHistory)
        {
            if (record != null && !record.isUndone())
            {
                active.add(record);
            }
        }
        return active;
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Exact names come only from direct spellbook evidence and stay presentation-only metadata. */
public class ObservedActionLabelTest
{
    private static final int SPELLBOOK_GROUP = 412;

    @Test
    public void directSpellbookNamesAreSanitizedAndRetained()
    {
        int widgetId = SPELLBOOK_GROUP << 16 | 17;
        for (String spell : new String[] {"Ice Burst", "Ice Barrage", "Vengeance", "High Level Alchemy"})
        {
            ActionLabel label = ActionLabel.fromSpellMenu("Cast", widgetId,
                SPELLBOOK_GROUP, "<col=ff9040>  " + spell + "  </col>", "Cast");
            assertNotNull(spell, label);
            assertEquals(spell, label.value());
        }
    }

    @Test
    public void genericCastTargetsAndAutocastNeverBecomeExactSpellNames()
    {
        int spellWidget = SPELLBOOK_GROUP << 16 | 17;
        assertNull(ActionLabel.fromSpellMenu("Cast", spellWidget, SPELLBOOK_GROUP,
            "Cast", "Autocast"));
        assertNull("target text is not supplied to the spell-name extractor",
            ActionLabel.fromSpellMenu("Cast", spellWidget, SPELLBOOK_GROUP,
                "Cast", "Cast"));
        assertNull("NPC/player/item widgets are not spellbook evidence",
            ActionLabel.fromSpellMenu("Cast", 413 << 16 | 17, SPELLBOOK_GROUP,
                "Ice Burst", "Goblin"));
        assertNull("Autocast selection is not correlated to later rune loss",
            ActionLabel.fromSpellMenu("Autocast", spellWidget, SPELLBOOK_GROUP,
                "Ice Burst", "Ice Burst"));
        assertNull(ActionLabel.fromSpellMenu("Use", spellWidget, SPELLBOOK_GROUP,
            "Ice Burst", "Ice Burst"));
    }

    @Test
    public void exactActionLabelIsBackwardCompatibleAndFinanciallyNeutral()
    {
        Transaction transaction = new Transaction(10L,
            TransactionType.CONSUMPTION, Context.GENERIC, "", "Vorkath", true,
            Arrays.asList(new Flow(560, "Death rune", -1L, 100, -100L)),
            Confidence.CONFIRMED, "Exact rune cost", null);
        transaction.setActionKind(ActionKind.CAST);
        long netBefore = transaction.getNet();
        boolean countedBefore = transaction.isCounted();
        TransactionType typeBefore = transaction.getType();
        transaction.setActionLabel(ActionLabel.of("Ice Burst"));

        assertEquals(netBefore, transaction.getNet());
        assertEquals(countedBefore, transaction.isCounted());
        assertEquals(typeBefore, transaction.getType());
        assertEquals(110, SavedState.CURRENT_SCHEMA_VERSION);

        Gson gson = new Gson();
        String json = gson.toJson(transaction);
        assertTrue("the bounded exact label persists as schema-105 presentation metadata",
            json.contains("\"observedActionLabel\":\"Ice Burst\""));
        Transaction loaded = gson.fromJson(json, Transaction.class);
        assertNotNull("a schema-105 receipt keeps its exact label", loaded.actionLabel());
        assertEquals("Ice Burst", loaded.actionLabel().value());
        assertEquals(netBefore, loaded.getNet());
        assertEquals(countedBefore, loaded.isCounted());
        assertEquals(typeBefore, loaded.getType());
    }
}

