    @Test
    public void oldOwnerWriteFailureStaysFencedAfterSwitch() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        CountDownLatch entered = new CountDownLatch(1);
        CountDownLatch release = new CountDownLatch(1);
        FailingRepository repository = new FailingRepository(directory, entered, release);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        Engine engine = new Engine(
            deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        Persistence coordinator = new Persistence(
            null, null, repository, writer, engine);
        TrackingIdentity bob = new TrackingIdentity("rsprofile.bob", TrackingIdentity.ACCOUNT_HASH_INVALID);
        try
        {
            assertTrue(coordinator.switchIdentity(ALICE, true, true));
            engine.ensureSession(1_000L);
            engine.getGeneralSession().rename("Alice");
            assertTrue(coordinator.saveNow());
            long aliceGeneration = repository.scopeGeneration;
            engine.getGeneralSession().rename("failing old save");
            repository.failNextSaveForGeneration(aliceGeneration);
            coordinator.scheduleSave();
            assertTrue(entered.await(5, TimeUnit.SECONDS));

            coordinator.onHashInvalidated(false);
            assertTrue(coordinator.switchIdentity(bob, true, true));
            engine.ensureSession(2_000L);
            engine.getGeneralSession().rename("Bob");
            SaveStatus bobStatus = writer.getStatus();
            Path bobPrimary = FilepathTestSupport.path(repository.dataDir().joinSegment("sessions.json"));

            release.countDown();
            assertTrue(writer.flush(Duration.ofSeconds(10)));
            assertEquals(bobStatus.state, writer.getStatus().state);
            assertSame("the stale completion leaves Bob's status alone", bobStatus, writer.getStatus());
            assertEquals(bob, coordinator.getActiveIdentity());
            assertFalse("old-owner failure must not create Bob's file", Files.exists(bobPrimary));
            assertEquals("Bob", engine.getGeneralSession().getName());
        }
        finally
        {
            release.countDown();
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

    private static SavedState state(String name, long revision)
    {
        SavedState state = new SavedState(
            new Session(name, 1_000L, SessionMode.GENERAL), null, Collections.emptyList());
        state.setRevision(revision);
        return state;
    }
}

package com.gpmanager;

import javax.annotation.Nullable;
import net.runelite.client.util.Filepath;

/** Test-side reads of persistence state; moved out of production to keep the plugin small. */
public final class PersistenceProbe
{
    private PersistenceProbe()
    {
    }

    /** Saves {@code state} on the disk revision observed now, healing an unreadable primary first. */
    public static boolean save(SessionRepository repository, SavedState state)
    {
        synchronized (repository)
        {
            return repository.save(intentFromDisk(repository, state));
        }
    }

    /** A destructive replacement based on the disk revision observed now. */
    public static SessionRepository.ReplaceOutcome replaceStateDetailed(SessionRepository repository, SavedState state)
    {
        if (state == null)
        {
            return SessionRepository.ReplaceOutcome.failedUnchanged("state was null");
        }
        synchronized (repository)
        {
            return repository.replaceStateDetailed(intentFromDisk(repository, state));
        }
    }

    private static WriteIntent intentFromDisk(SessionRepository repository, SavedState state)
    {
        SessionRepository.ScopeFiles files = repository.bound;
        if (files.state.exists())
        {
            try
            {
                repository.readState(files.state);
            }
            catch (Exception ex)
            {
                repository.setAside(files);
                repository.lastKnownDiskRevision = repository.backupRevision(files.backup).orElse(0L);
            }
        }
        if (repository.lastKnownDiskRevision <= 0L)
        {
            repository.lastKnownDiskRevision = repository.peekRevision(files.state)
                .orElse(repository.backupRevision(files.backup).orElse(0L));
        }
        long base = repository.lastKnownDiskRevision;
        return repository.boundIdentity == null
            ? new WriteIntent(null, repository.scopeGeneration, base, state, null)
            : new WriteIntent(repository.boundIdentity, repository.scopeGeneration, base, state, null);
    }

    /**
     * Waits for maintenance the Grinds controller ran off Swing's thread (Codex review 1.2), then for
     * its result back on Swing's thread; {@code steps} covers a chain such as backup-then-reset.
     */
    public static void drain(Persistence persistence, int steps) throws Exception
    {
        for (int step = 0; step < steps; step++)
        {
            persistence.lifecycleExecutor().submit(() -> { }).get(5, java.util.concurrent.TimeUnit.SECONDS);
            javax.swing.SwingUtilities.invokeAndWait(() -> { });
        }
    }

    /** Number of existing rotated good-save copies (.1 through .3) in this scope. */
    public static int rotatedBackupCount(SessionRepository repository)
    {
        synchronized (repository)
        {
            repository.requireInit();
            int count = 0;
            for (int index = 1; index <= 3; index++)
            {
                Filepath candidate = repository.bound.dir.joinSegment(
                    repository.bound.backup.getFileName() + "." + index);
                if (candidate.exists())
                {
                    count++;
                }
            }
            return count;
        }
    }

    /** Why writes are held for the current identity, or null when the bound account may write. */
    @Nullable
    public static String identityBlockReason(Persistence coordinator)
    {
        synchronized (coordinator)
        {
            TrackingIdentity current = coordinator.resolveCurrentIdentity();
            if (current == null)
            {
                return coordinator.activeIdentity == null
                    ? "Waiting for RuneScape profile identity"
                    : "Client profile unavailable; previous account state held";
            }
            if (coordinator.activeIdentity == null)
            {
                return "Tracking identity not bound yet";
            }
            if (coordinator.readOnlyReason != null)
            {
                return coordinator.readOnlyReason;
            }
            if (!current.equals(coordinator.activeIdentity))
            {
                SaveStatus status = coordinator.writer.getStatus();
                String detail = status == null || status.detail == null || status.detail.isEmpty()
                    ? "previous account save did not finish"
                    : status.detail;
                return "Account switch held — " + detail + ". Retry after save succeeds.";
            }
            return null;
        }
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Collections;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class PersistenceSafetyTest
{
    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    private SavedState named(String name, long revision)
    {
        SavedState state = new SavedState(new Session(name, 1_000L, SessionMode.GENERAL), null, Collections.emptyList());
        state.setRevision(revision);
        return state;
    }

    @Test
    public void resetFailureAfterPrimaryStillCommitsAndInvalidatesObsoleteBackup() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository baseline = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        PersistenceProbe.save(baseline, named("Old history", 1L));
        PersistenceProbe.save(baseline, named("Older backup seed", 2L));

        AtomicInteger backupReplacements = new AtomicInteger();
        SessionRepository failing = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false)
        {
            @Override
            void replaceFile(Filepath source, Filepath target) throws IOException
            {
                if (target.getFileName().toString().equals("sessions.backup.json")
                    && backupReplacements.incrementAndGet() >= 1
                    && Files.exists(directory.resolve("sessions.json")))
                {
                    // Fail while aligning backup after primary reset commit.
                    String primary = Files.readString(directory.resolve("sessions.json"));
                    if (primary.contains("Fresh reset"))
                    {
                        throw new IOException("Simulated crash after primary reset");
                    }
                }
                super.replaceFile(source, target);
            }
        };

        SavedState reset = named("Fresh reset", 3L);
        SessionRepository.ReplaceOutcome outcome = PersistenceProbe.replaceStateDetailed(failing, reset);
        assertTrue(outcome.isCommitted());
        assertEquals("Fresh reset", failing.load().getActiveSession().getName());
        // Cleared data must not reappear via backup fallback.
        Files.deleteIfExists(directory.resolve("sessions.json"));
        // If backup still exists it must also be the reset payload, or be gone.
        if (Files.exists(directory.resolve("sessions.backup.json")))
        {
            assertEquals("Fresh reset",
                new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false).load().getActiveSession().getName());
        }
        else
        {
            assertEquals(null,
                new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false).load().getActiveSession());
        }
    }

    @Test
    public void staleRevisionCannotOverwriteNewerDiskState() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(PersistenceProbe.save(repository, named("First", 1L)));
        assertTrue(PersistenceProbe.save(repository, named("Second", 2L)));
        assertFalse(PersistenceProbe.save(repository, named("Stale", 1L)));
        assertEquals("Second", repository.load().getActiveSession().getName());
    }

    @Test
    public void staleDestructiveResetIsRefusedNotRebased() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(PersistenceProbe.save(repository, named("First", 1L)));
        assertTrue(PersistenceProbe.save(repository, named("Second", 2L)));
        String before = Files.readString(directory.resolve("sessions.json"));

        // Reset fenced on base 1 while disk is at 2: CONFLICT, disk untouched, revision not advanced.
        SessionRepository.ReplaceOutcome outcome = repository.replaceStateDetailed(
            new WriteIntent(null, repository.scopeGeneration, 1L, named("Reset", 2L), null));
        assertEquals(SessionRepository.ReplaceOutcome.Kind.CONFLICT, outcome.kind);
        assertFalse(outcome.isCommitted());
        assertEquals(before, Files.readString(directory.resolve("sessions.json")));
        assertEquals("Second", repository.load().getActiveSession().getName());
        assertEquals(2L, repository.lastKnownDiskRevision);
        assertFalse(Files.exists(directory.resolve("sessions.next.json")));
        assertFalse(Files.exists(directory.resolve("sessions.commit.stage")));

        // A non-advancing revision is refused even on the correct base.
        assertFalse(repository.replaceStateDetailed(new WriteIntent(null, repository.scopeGeneration, 2L, named("Reset", 2L), null)).isCommitted());
        assertEquals(before, Files.readString(directory.resolve("sessions.json")));

        // The same reset re-issued explicitly against the observed revision commits as 3.
        assertTrue(repository.replaceStateDetailed(new WriteIntent(null, repository.scopeGeneration, 2L, named("Reset", 3L), null)).isCommitted());
        assertEquals("Reset", repository.load().getActiveSession().getName());
        assertEquals(3L, repository.lastKnownDiskRevision);
    }

    @Test
    public void twoWritersFromSameBaseCannotBothCommit() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository first = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(PersistenceProbe.save(first, named("Shared", 10L)));
        long base = first.load().revision;
        assertEquals(10L, base);

        SessionRepository writerA = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        writerA.load();
        SessionRepository writerB = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        writerB.load();

        SavedState a = named("From A", 11L);
        SavedState b = named("From B", 11L);
        WriteIntent intentA = new WriteIntent(null, writerA.scopeGeneration, base, a, null);
        WriteIntent intentB = new WriteIntent(null, writerB.scopeGeneration, base, b, null);

        assertTrue(writerA.save(intentA));
        assertFalse("Second writer must lose the CAS race", writerB.save(intentB));
        assertEquals("From A", new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false).load().getActiveSession().getName());
    }

    @Test
    public void heldAccountLockRefusesSaveAndReplaceUntilReleased() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository store = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        TrackingIdentity alice = new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID);
        store.bindIdentity(alice);
        assertTrue(PersistenceProbe.save(store, named("Alice-1", 1L)));
        Path primary = FilepathTestSupport.path(store.dataDir().joinSegment("sessions.json"));
        String before = Files.readString(primary);

        Path lockPath = FilepathTestSupport.path(store.dataDir().joinSegment("sessions.write.lock"));
        try (java.nio.channels.FileChannel channel = java.nio.channels.FileChannel.open(lockPath,
            java.nio.file.StandardOpenOption.CREATE, java.nio.file.StandardOpenOption.WRITE);
            java.nio.channels.FileLock held = channel.tryLock())
        {
            assertTrue(held != null && held.isValid());
            assertFalse("ordinary save refused while another client holds the account lock",
                store.save(new WriteIntent(alice, store.scopeGeneration, 1L, named("Alice-2", 2L), null)));
            assertFalse("destructive replace refused too",
                store.replaceStateDetailed(new WriteIntent(alice, store.scopeGeneration, 1L, named("Reset", 2L), null)).isCommitted());
            assertEquals(before, Files.readString(primary));
        }
        assertTrue(store.save(new WriteIntent(alice, store.scopeGeneration, 1L, named("Alice-2", 2L), null)));
        assertEquals("Alice-2", store.load().getActiveSession().getName());
    }

    @Test
    public void queuedWriteKeepsImmutableAccountDestinationAfterSwitch() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository store = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        TrackingIdentity alice = new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID);
        TrackingIdentity bob = new TrackingIdentity("rsprofile.bob", TrackingIdentity.ACCOUNT_HASH_INVALID);

        store.bindIdentity(alice);
        assertTrue(PersistenceProbe.save(store, named("Alice-1", 1L)));
        long aliceBase = store.lastKnownDiskRevision;
        long aliceGeneration = store.scopeGeneration;

        SavedState pending = named("Alice-pending", aliceBase + 1L);
        WriteIntent aliceIntent = new WriteIntent(alice, aliceGeneration, aliceBase, pending, null);

        store.bindIdentity(bob);
        assertTrue(PersistenceProbe.save(store, named("Bob-1", 1L)));

        // Delayed Alice write must still land in Alice's folder, not Bob's.
        assertTrue(store.save(aliceIntent));
        store.bindIdentity(alice);
        assertEquals("Alice-pending", store.load().getActiveSession().getName());
        store.bindIdentity(bob);
        assertEquals("Bob-1", store.load().getActiveSession().getName());
    }

    @Test
    public void writerSurvivesShutdownThenRestart() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);

        writer.submit(new WriteIntent(null,
            repository.scopeGeneration,
            repository.lastKnownDiskRevision,
            named("Before disable", 1L), null));
        assertTrue(writer.flush(Duration.ofSeconds(5)));
        writer.shutdown(Duration.ofSeconds(5));

        writer.start();
        long base = repository.load().revision;
        writer.resetRevision(base);
        writer.submit(new WriteIntent(null,
            repository.scopeGeneration,
            base,
            named("After enable", base + 1L), null));
        assertTrue(writer.flush(Duration.ofSeconds(5)));
        assertEquals("After enable", repository.load().getActiveSession().getName());
        writer.shutdown(Duration.ofSeconds(5));
    }

    @Test
    public void orderedWriterCoalescesAndIgnoresStaleSnapshots() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        ExecutorService sameThread = Executors.newSingleThreadExecutor();
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository, sameThread);

        long generation = repository.scopeGeneration;
        writer.submit(new WriteIntent(null, generation, 0L, named("Old", 1L), null));
        writer.submit(new WriteIntent(null, generation, 0L, named("New", 2L), null));
        assertTrue(writer.flush(Duration.ofSeconds(5)));
        assertEquals("New", repository.load().getActiveSession().getName());
        assertEquals(2L, writer.appliedRevision());
        assertEquals(SaveStatus.State.OK, writer.getStatus().state);

        long base = repository.lastKnownDiskRevision;
        writer.submit(new WriteIntent(null, generation, base, named("Stale again", 1L), null));
        assertTrue(writer.flush(Duration.ofSeconds(5)));
        assertEquals("New", repository.load().getActiveSession().getName());
        sameThread.shutdown();
    }

    @Test
    public void shutdownPreservesPreviouslyQueuedDetachedSnapshot() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(
            repository,
            Executors.newSingleThreadExecutor());
        writer.submit(new WriteIntent(null,
            repository.scopeGeneration,
            0L,
            named("Shutdown save", 1L), null));
        assertTrue("test explicitly establishes the durable state before lifecycle fencing",
            writer.flush(Duration.ofSeconds(5)));
        writer.shutdown(Duration.ofSeconds(5));
        assertEquals("Shutdown save", repository.load().getActiveSession().getName());
        assertNotEquals(SaveStatus.State.NEVER_SAVED, writer.getStatus().state);
    }
}

