package com.gpmanager;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Measures caller-thread snapshot cost for a long synthetic session: the one serialization a
 * save runs under the engine lock before enqueue. Background disk writing alone is not enough.
 */
public class SnapshotDetachCostTest
{
    @Test
    public void detachLongSessionStaysUnderBudget()
    {
        Gson gson = new Gson();
        Session session = new Session("Cost probe", 1_000L, SessionMode.GENERAL);
        List<Transaction> txs = new ArrayList<>();
        for (int i = 0; i < 2_000; i++)
        {
            txs.add(Tx.of(
                1_000L + i,
                (long) i * 600L,
                TransactionType.LOOT,
                Context.LOOT,
                "",
                "Probe",
                true,
                Collections.emptyList()));
        }
        for (Transaction tx : txs)
        {
            session.addTransaction(tx, 100_000, false);
        }
        SavedState live = new SavedState(session, null, Collections.emptyList());
        live.setRevision(42L);

        long bestNanos = Long.MAX_VALUE;
        for (int i = 0; i < 8; i++)
        {
            long started = System.nanoTime();
            String json = gson.toJson(live);
            long elapsed = System.nanoTime() - started;
            assertTrue(json.contains("\"revision\":42"));
            bestNanos = Math.min(bestNanos, elapsed);
        }
        long bestMillis = TimeUnit.NANOSECONDS.toMillis(bestNanos);
        // Soft budget for a 2k-transaction detach on a developer workstation.
        // Recorded for the progress checkpoint; fail only on extreme stalls.
        assertTrue(
            "Detach took " + bestMillis + " ms (budget 250 ms)",
            bestMillis < 250L);
        System.out.println("SnapshotDetachCostTest best detach ms=" + bestMillis
            + " transactions=" + txs.size());
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.lang.reflect.Proxy;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Charter section 16: an asynchronous save for account generation A that completes only after the
 * coordinator moved to generation B (or to the unbound state) lands in A's folder and nothing else.
 * B's engine state, revision, generation, disk lineage and {@link SaveStatus} are untouched. Uses
 * latches on the repository, never sleeps.
 */
public class StaleGenerationCompletionTest
{
    private static final String ALICE = "rsprofile.alice";
    private static final String BOB = "rsprofile.bob";
    private static final long NOW = 1_800_000_000_000L;

    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    /** Blocks the first save whose intent carries {@code gate}'s generation until released. */
    private static final class GatedRepository extends SessionRepository
    {
        final CountDownLatch entered = new CountDownLatch(1);
        final CountDownLatch release = new CountDownLatch(1);
        volatile long gatedGeneration = -1L;

        GatedRepository(Path root)
        {
            super(new Gson(), FilepathTestSupport.root(root), true);
        }

        @Override
        public boolean save(WriteIntent intent)
        {
            if (intent.scopeGeneration == gatedGeneration)
            {
                gatedGeneration = -1L;
                entered.countDown();
                try
                {
                    if (!release.await(10, TimeUnit.SECONDS)) throw new AssertionError("gate never released");
                }
                catch (InterruptedException ex)
                {
                    throw new AssertionError(ex);
                }
            }
            return super.save(intent);
        }
    }

    private static final class Rig
    {
        final GatedRepository repository;
        final ExecutorService executor = Executors.newSingleThreadExecutor();
        final OrderedPersistenceWriter writer;
        final Engine engine;
        final Persistence coordinator;

        Rig(Path root)
        {
            repository = new GatedRepository(root);
            writer = new OrderedPersistenceWriter(repository, executor);
            engine = EngineTestFixtures.engine(new GpManagerConfig()
            {
                @Override public boolean autoStartSession() { return false; }
            });
            coordinator = new Persistence(client(), IsolatedConfigManager.create(ALICE),
                repository, writer, engine);
            coordinator.start();
        }

        private static Client client()
        {
            return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
                (proxy, method, args) -> {
                    if (method.getName().equals("getAccountHash")) return 77L;
                    Class<?> type = method.getReturnType();
                    if (type == boolean.class) return false;
                    if (type == int.class) return 0;
                    if (type == long.class) return 0L;
                    return null;
                });
        }

        /** Alice books a note, then a save for her generation is started and parked inside the repository. */
        long startParkedAliceSave() throws Exception
        {
            assertTrue(coordinator.switchIdentity(new TrackingIdentity(ALICE, TrackingIdentity.ACCOUNT_HASH_INVALID), true, true));
            engine.ensureSession(NOW - 10_000L);
            engine.getGeneralSession().rename("Alice general");
            assertTrue(coordinator.saveNow());
            long aliceGeneration = repository.scopeGeneration;
            engine.getGeneralSession().rename("in flight");
            repository.gatedGeneration = aliceGeneration;
            coordinator.scheduleSave();
            assertTrue("drain entered the repository", repository.entered.await(10, TimeUnit.SECONDS));
            return aliceGeneration;
        }

        void stop()
        {
            repository.release.countDown();
            writer.shutdown(Duration.ofSeconds(5));
            executor.shutdown();
        }
    }

    @Test
    public void lateSaveForPreviousAccountCannotTouchTheNewAccount() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        Rig rig = new Rig(root);
        try
        {
            long aliceGeneration = rig.startParkedAliceSave();
            Path alicePrimary = FilepathTestSupport.path(
                rig.repository.scopeDir(new TrackingIdentity(ALICE, TrackingIdentity.ACCOUNT_HASH_INVALID)).joinSegment("sessions.json"));
            String aliceBefore = Files.readString(alicePrimary);

            // Logout, then Bob logs in while Alice's write is still parked. No flush is possible
            // (the write is in flight), so the switch goes through the unbound state.
            rig.coordinator.onHashInvalidated(false);
            assertTrue(rig.coordinator.switchIdentity(new TrackingIdentity(BOB, TrackingIdentity.ACCOUNT_HASH_INVALID), true, true));
            rig.engine.ensureSession(NOW);
            rig.engine.getGeneralSession().rename("Bob general");
            long bobGeneration = rig.repository.scopeGeneration;
            assertNotEquals(aliceGeneration, bobGeneration);
            String bobGeneralId = rig.engine.getGeneralSession().getId();
            long bobApplied = rig.writer.appliedRevision();
            long bobDisk = rig.repository.lastKnownDiskRevision;
            SaveStatus bobStatus = rig.writer.getStatus();
            Path bobPrimary = FilepathTestSupport.path(rig.repository.dataDir().joinSegment("sessions.json"));
            assertFalse(Files.exists(bobPrimary));

            // Release Alice's completion and wait for the drain to finish.
            rig.repository.release.countDown();
            assertTrue(rig.writer.flush(Duration.ofSeconds(10)));

            // Alice's folder got her write; Bob's world is exactly as it was.
            assertNotEquals(aliceBefore, Files.readString(alicePrimary));
            assertTrue(Files.readString(alicePrimary).contains("in flight"));
            assertFalse("no durable state for Bob was created by Alice's completion", Files.exists(bobPrimary));
            assertEquals(bobGeneration, rig.repository.scopeGeneration);
            assertEquals(bobApplied, rig.writer.appliedRevision());
            assertEquals(bobDisk, rig.repository.lastKnownDiskRevision);
            assertEquals(bobStatus.state, rig.writer.getStatus().state);
            assertSame(bobStatus, rig.writer.getStatus());
            assertEquals(bobGeneralId, rig.engine.getGeneralSession().getId());
            assertEquals("Bob general", rig.engine.getGeneralSession().getName());
            assertEquals(BOB, rig.engine.exportState().ownerKey);

            // Bob's own first save then starts a fresh lineage at revision 1.
            assertTrue(rig.coordinator.saveNow());
            assertEquals(1L, rig.repository.load().revision);
            assertEquals("Bob general", rig.repository.load().getActiveSession().getName());
        }
        finally
        {
            rig.stop();
        }
    }

    @Test
    public void lateSaveAfterLogoutCannotRecreateStateOrReportForTheUnboundScope() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        Rig rig = new Rig(root);
        try
        {
            rig.startParkedAliceSave();
            rig.coordinator.onHashInvalidated(false);
            assertNull(rig.coordinator.getActiveIdentity());
            assertFalse(rig.repository.isBound());
            SaveStatus unboundStatus = rig.writer.getStatus();
            long unboundGeneration = rig.repository.scopeGeneration;

            rig.repository.release.countDown();
            assertTrue(rig.writer.flush(Duration.ofSeconds(10)));

            // Unbound: nothing is written to the root or the unassigned marker, status is not
            // rewritten for the abandoned generation, and a new save is refused outright.
            assertFalse(rig.repository.dataDir().joinSegment("sessions.json").exists());
            assertEquals(unboundGeneration, rig.repository.scopeGeneration);
            assertSame(unboundStatus, rig.writer.getStatus());
            assertEquals(0L, rig.writer.appliedRevision());
            assertFalse(rig.coordinator.saveNow());
            rig.coordinator.scheduleSave();
            assertTrue(rig.writer.flush(Duration.ofSeconds(5)));
            assertFalse(PersistenceProbe.replaceStateDetailed(rig.repository, new SavedState()).isCommitted());
            assertFalse(rig.repository.dataDir().joinSegment("sessions.json").exists());
        }
        finally
        {
            rig.stop();
        }
    }

}

package com.gpmanager;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.Locale;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertEquals;

/**
 * Synthetic long-session save harness. Measures wall time and file growth under a
 * TemporaryFolder — <strong>not</strong> a live RuneLite client soak.
 */
public class SyntheticLongSessionPerfTest
{
    @Rule
    public final TemporaryFolder folder = new TemporaryFolder();

    @Test
    public void syntheticSaveWorkloadRecordsDurationAndGrowth() throws Exception
    {
        Path root = folder.newFolder("profit-manager").toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(root), false);
        long t0 = 1_700_000_000_000L;
        final int transactions = 2_000;

        long beforeBytes = dirSize(root);
        long startNs = System.nanoTime();
        int committed = 0;
        for (int round = 0; round < 8; round++)
        {
            Session session = new Session("General-" + round, t0, SessionMode.AUTO);
            for (int i = 0; i < transactions; i++)
            {
                session.addTransaction(Tx.of(
                    t0 + i * 1_000L,
                    TransactionType.GAIN,
                    Context.GENERIC,
                    "Skilling",
                    true,
                    Collections.singletonList(new Flow(1511, "Logs", 1L, 39, 39L))), transactions, false);
            }
            assertEquals("Measure retained records, not only compacted totals", transactions, session.getTransactions().size());
            SavedState state = new SavedState(session, null, Collections.emptyList());
            state.setRevision(round + 1L);
            if (PersistenceProbe.save(repository, state) || PersistenceProbe.replaceStateDetailed(repository, state).isCommitted())
            {
                committed++;
            }
        }
        long elapsedMs = (System.nanoTime() - startNs) / 1_000_000L;
        long afterBytes = dirSize(root);
        long growth = Math.max(0L, afterBytes - beforeBytes);

        String report = String.format(Locale.ROOT,
            "synthetic_long_session_perf%n"
                + "label=SYNTHETIC_NOT_LIVE_CLIENT%n"
                + "transactions=%d%n"
                + "save_rounds=8%n"
                + "committed_saves=%d%n"
                + "elapsed_ms=%d%n"
                + "dir_bytes_before=%d%n"
                + "dir_bytes_after=%d%n"
                + "dir_growth_bytes=%d%n"
                + "note=CPU/UI-stall/live-log volume not measured here%n",
            transactions, committed, elapsedMs, beforeBytes, afterBytes, growth);

        Path outDir = Path.of("build", "reports", "perf");
        Files.createDirectories(outDir);
        Path out = outDir.resolve("synthetic-long-session.txt");
        Files.write(out, report.getBytes(StandardCharsets.UTF_8));

        assertEquals("Every measured save must commit: " + report, 8, committed);
        assertTrue("repository should write something", afterBytes > 0L);
        assertTrue(Files.exists(out));
    }

    private static long dirSize(Path root) throws IOException
    {
        if (!Files.exists(root))
        {
            return 0L;
        }
        final long[] total = {0L};
        try (java.util.stream.Stream<Path> paths = Files.walk(root))
        {
            paths.filter(Files::isRegularFile).forEach(path ->
            {
                try { total[0] += Files.size(path); }
                catch (IOException ex) { throw new java.io.UncheckedIOException(ex); }
            });
        }
        return total[0];
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Collections;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class WriterLineageAndIdentityTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    private SavedState named(String name, long revision)
    {
        SavedState state = new SavedState(new Session(name, 1_000L, SessionMode.GENERAL), null, Collections.emptyList());
        state.setRevision(revision);
        return state;
    }

    @Test
    public void laterSnapshotDuringOwnWriteMustPersist() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        CountDownLatch entered = new CountDownLatch(1);
        CountDownLatch release = new CountDownLatch(1);
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false)
        {
            @Override
            public boolean save(WriteIntent intent)
            {
                if (intent.state.revision == 1L)
                {
                    entered.countDown();
                    try
                    {
                        if (!release.await(5, TimeUnit.SECONDS))
                        {
                            return false;
                        }
                    }
                    catch (InterruptedException ex)
                    {
                        return false;
                    }
                }
                return super.save(intent);
            }
        };
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        try
        {
            SavedState first = named("First", 1L);
            writer.submit(new WriteIntent(null,
                repository.scopeGeneration,
                repository.lastKnownDiskRevision,
                first, null));
            assertTrue(entered.await(5, TimeUnit.SECONDS));

            SavedState latest = named("Latest", 2L);
            writer.submit(new WriteIntent(null,
                repository.scopeGeneration,
                repository.lastKnownDiskRevision,
                latest, null));
            release.countDown();
            assertTrue(writer.flush(Duration.ofSeconds(5)));
            assertEquals("Latest", repository.load().getActiveSession().getName());
        }
        finally
        {
            release.countDown();
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void intermediateSnapshotsCoalesceToNewest() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        try
        {
            long generation = repository.scopeGeneration;
            writer.submit(new WriteIntent(null, generation, 0L, named("A", 1L), null));
            writer.submit(new WriteIntent(null, generation, 0L, named("B", 2L), null));
            writer.submit(new WriteIntent(null, generation, 0L, named("C", 3L), null));
            assertTrue(writer.flush(Duration.ofSeconds(5)));
            assertEquals("C", repository.load().getActiveSession().getName());
            assertEquals(3L, repository.load().revision);
        }
        finally
        {
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void externalConflictIsNotSilentlyRebased() throws Exception
    {
        Path directory = temporary.newFolder().toPath();
        SessionRepository shared = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        assertTrue(PersistenceProbe.save(shared, named("Seed", 1L)));

        SessionRepository external = new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false);
        external.load();
        assertTrue(external.save(new WriteIntent(null,
            external.scopeGeneration,
            1L,
            named("External", 2L), null)));

        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(shared);
        try
        {
            writer.resetRevision(1L);
            // Stale base against external tip must conflict, not overwrite.
            writer.submit(new WriteIntent(null,
                shared.scopeGeneration,
                1L,
                named("Local stale", 2L), null));
            assertTrue(writer.flush(Duration.ofSeconds(5)));
            assertTrue(writer.getStatus().isFailure()
                || writer.getStatus().state == SaveStatus.State.CONFLICT);
            assertEquals("External", new SessionRepository(new Gson(), FilepathTestSupport.root(directory), false).load()
                .getActiveSession().getName());
        }
        finally
        {
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void refusedIdentitySwitchPreservesPreviousState() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository)
        {
            @Override
            public boolean flush(Duration timeout)
            {
                return false;
            }
        };
        Engine engine = new Engine(
            deltas -> Collections.emptyList(),
            new TransactionClassifier(),
            new GpManagerConfig() {});
        Persistence coordinator = new Persistence(
            null, null, repository, writer, engine);

        TrackingIdentity alice = new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID);
        TrackingIdentity bob = new TrackingIdentity("rsprofile.bob", TrackingIdentity.ACCOUNT_HASH_INVALID);
        assertTrue(coordinator.switchIdentity(alice, true, true));
        engine.ensureSession(1_000L);
        engine.getActiveSession().rename("Alice live");
        assertEquals("Alice live", engine.getActiveSession().getName());

        assertFalse(coordinator.switchIdentity(bob, true, true));
        assertEquals(alice, coordinator.getActiveIdentity());
        assertEquals("Alice live", engine.getActiveSession().getName());
        assertNotNull(PersistenceProbe.identityBlockReason(coordinator));
    }

    /**
     * A save serializes the engine's state while holding the engine's lock, so no live record is
     * read after it is released; the writer then commits that JSON without serializing again.
     */
    @Test
    public void saveSnapshotIsCopiedUnderTheEngineLock() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        Engine engine = new Engine(
            deltas -> Collections.emptyList(),
            new TransactionClassifier(),
            new GpManagerConfig() {});
        java.util.List<Boolean> locked = new java.util.ArrayList<>();
        Gson recording = new com.google.gson.GsonBuilder().registerTypeAdapterFactory(new com.google.gson.TypeAdapterFactory()
        {
            @Override
            @SuppressWarnings("unchecked")
            public <T> com.google.gson.TypeAdapter<T> create(Gson gson, com.google.gson.reflect.TypeToken<T> type)
            {
                if (type.getRawType() != SavedState.class)
                {
                    return null;
                }
                com.google.gson.TypeAdapter<T> delegate = gson.getDelegateAdapter(this, type);
                return new com.google.gson.TypeAdapter<T>()
                {
                    @Override
                    public void write(com.google.gson.stream.JsonWriter out, T value) throws java.io.IOException
                    {
                        locked.add(Thread.holdsLock(engine));
                        delegate.write(out, value);
                    }

                    @Override
                    public T read(com.google.gson.stream.JsonReader in) throws java.io.IOException
                    {
                        return delegate.read(in);
                    }
                };
            }
        }).create();
        SessionRepository repository = new SessionRepository(recording, FilepathTestSupport.root(root), true);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        Persistence coordinator = new Persistence(
            null, null, repository, writer, engine);
        try
        {
            assertTrue(coordinator.switchIdentity(new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID), true, true));
            engine.ensureSession(1_000L);
            locked.clear();
            assertTrue(coordinator.saveNow());
            assertEquals("one serialization per save, under the engine lock",
                Collections.singletonList(true), locked);
            String disk = SessionRepository.readText(repository.bound.state);
            SavedState reread = new Gson().fromJson(disk, SavedState.class);
            assertEquals("the file is exactly what the old detached copy wrote", new Gson().toJson(reread), disk);
        }
        finally
        {
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void successfulIdentitySwitchPrimesFreshBaseline() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        Engine engine = new Engine(
            deltas -> Collections.emptyList(),
            new TransactionClassifier(),
            new GpManagerConfig() {});
        Persistence coordinator = new Persistence(
            null, null, repository, writer, engine);
        try
        {
            TrackingIdentity alice = new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID);
            TrackingIdentity bob = new TrackingIdentity("rsprofile.bob", TrackingIdentity.ACCOUNT_HASH_INVALID);
            assertTrue(coordinator.switchIdentity(alice, true, true));
            engine.ensureSession(1_000L);
            assertTrue(coordinator.switchIdentity(bob, true, true));
            assertEquals(bob, coordinator.getActiveIdentity());
            assertTrue(EngineProbe.isBaselinePriming(engine));
        }
        finally
        {
            writer.shutdown(Duration.ofSeconds(5));
        }
    }

    @Test
    public void identityIsolationWorksWithoutPersistenceEnabled() throws Exception
    {
        Path root = temporary.newFolder().toPath();
        SessionRepository repository = new SessionRepository(new Gson(), FilepathTestSupport.root(root), true);
        OrderedPersistenceWriter writer = new OrderedPersistenceWriter(repository);
        Engine engine = new Engine(
            deltas -> Collections.emptyList(),
            new TransactionClassifier(),
            new GpManagerConfig() {});
        Persistence coordinator = new Persistence(
            null, null, repository, writer, engine);
        try
        {
            TrackingIdentity alice = new TrackingIdentity("rsprofile.alice", TrackingIdentity.ACCOUNT_HASH_INVALID);
            TrackingIdentity bob = new TrackingIdentity("rsprofile.bob", TrackingIdentity.ACCOUNT_HASH_INVALID);
            assertTrue(coordinator.switchIdentity(alice, false, true));
            engine.ensureSession(1_000L);
            engine.getActiveSession().rename("Alice ephemeral");
            assertTrue(coordinator.switchIdentity(bob, false, true));
            assertEquals(bob, coordinator.getActiveIdentity());
            // New account gets a fresh empty restore, not Alice's live session.
            assertTrue(engine.getActiveSession() == null
                || !"Alice ephemeral".equals(engine.getActiveSession().getName()));
        }
        finally
        {
            writer.shutdown(Duration.ofSeconds(5));
        }
    }
}

