/**
 * Character idle is presentation-only — must not pause the session or change GP/hr.
 */
public class CharacterIdleGpHrGuardrailTest
{
    @Test
    public void characterIdleDoesNotPauseSessionOrChangeRate()
    {
        Session session = new Session("Test", 0L, SessionMode.GENERAL);
        session.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.GAIN,
                Context.GENERIC,
                "",
                true,
                Collections.singletonList(new Flow(526, "Bones", 1, 100, 100L))),
            1, false);

        Metrics before = session.metrics(10_000L);
        CharacterIdleModel idle = new CharacterIdleModel();
        idle.delayMillis = 2_000L;
        assertFalse(idle.tick(false, false, 10_000L));
        assertTrue(idle.tick(false, false, 12_000L));
        assertTrue(idle.characterIdle);

        Metrics after = session.metrics(10_000L);
        assertEquals(before.elapsedMillis, after.elapsedMillis);
        assertEquals(before.profitPerHour, after.profitPerHour);
        assertEquals(before.net, after.net);
        assertFalse(session.paused);
    }

    /** Owner live 1.5.2: the NPC's name outlasts the gap between kills (Activity label timeout). */
    @Test
    public void theActivityNameWaitsTheLabelTimeout()
    {
        CharacterIdleModel idle = new CharacterIdleModel();
        idle.delayMillis = GpManagerPlugin.idleDelay(new GpManagerConfig() {});
        assertEquals(15_000L, idle.delayMillis);
        assertFalse(idle.tick(true, true, 0L));
        assertFalse("still named 6 s after the kill", idle.tick(false, false, 1_000L));
        assertFalse(idle.tick(false, false, 7_000L));
        assertTrue("dropped at the timeout", idle.tick(false, false, 16_000L));
    }

    @Test
    public void afkPauseStillFreezesRateAndLabelsAfk()
    {
        Session session = new Session("Test", 0L, SessionMode.GENERAL);
        session.addTransaction(
            Tx.of(
                1_000L,
                1_000L,
                TransactionType.GAIN,
                Context.GENERIC,
                "",
                true,
                Collections.singletonList(new Flow(526, "Bones", 1, 100, 100L))),
            1, false);

        session.pause(2_000L, PauseReason.IDLE);
        Metrics atPause = session.metrics(2_000L);
        Metrics later = session.metrics(62_000L);
        assertEquals(atPause.elapsedMillis, later.elapsedMillis);
        assertEquals(atPause.profitPerHour, later.profitPerHour);
        assertEquals(PauseReason.IDLE, session.getPauseReason());
    }
}

package com.gpmanager;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CharacterIdleModelTest
{
    @Test
    public void delayRequiredBeforeIdle()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 5_000L;
        assertFalse(model.tick(false, false, 1_000L));
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, false, 5_999L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 6_000L));
        assertTrue(model.characterIdle);
        assertFalse(model.tick(false, false, 7_000L));
        assertTrue(model.characterIdle);
    }

    @Test
    public void animationOrInteractClearsIdle()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        assertFalse(model.tick(false, false, 1_000L));
        assertTrue(model.tick(false, false, 3_000L));
        assertTrue(model.characterIdle);
        assertFalse(model.tick(true, false, 3_100L));
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, true, 4_000L));
        assertFalse(model.characterIdle);
    }

    @Test
    public void clearResetsState()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        assertFalse(model.tick(false, false, 1_000L));
        assertTrue(model.tick(false, false, 3_000L));
        model.clear();
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, false, 3_500L));
    }

    @Test
    public void busyAndXpPreventIdle()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        assertFalse(model.tick(true, false, 1_000L));
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, false, 3_000L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 5_000L));
        assertTrue(model.characterIdle);

        model.clear();
        model.noteSkillingXp(10_000L);
        assertFalse(model.tick(false, false, 11_000L));
        assertFalse(model.characterIdle);
        // XP soft-busy lasts for the idle delay after the drop — Idle fires then,
        // without stacking a second full delay.
        assertFalse(model.tick(false, false, 11_999L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 12_000L));
        assertTrue(model.characterIdle);
    }

    @Test
    public void hardBusyStillRequiresFullDelayAfterClear()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        model.noteSkillingXp(10_000L);
        assertFalse(model.tick(true, false, 10_500L));
        assertFalse(model.tick(false, false, 12_000L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 14_000L));
        assertTrue(model.characterIdle);
    }

}

package com.gpmanager;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;

/**
 * Development-only preview sprites (owner live 2026-10-13): real item images fetched by
 * {@code tools/fetch_preview_icons.py} into build/preview-icons/ (never committed and never part
 * of the published plugin). A missing file keeps the fixture's own dummy sprite, so previews run
 * anywhere; on a machine with the icons fetched, the screenshots read like real gameplay for the
 * README.
 */
public final class PreviewIcons
{
    private static final Map<Integer, BufferedImage> CACHE = new HashMap<>();

    private PreviewIcons()
    {
    }

    /** RuneLite's item box is 36 x 32; wiki renders are fitted inside it, never upscaled. */
    public static BufferedImage sprite(int itemId)
    {
        if (CACHE.containsKey(itemId))
        {
            return CACHE.get(itemId);
        }
        BufferedImage loaded = load(itemId);
        CACHE.put(itemId, loaded);
        return loaded;
    }

    private static BufferedImage load(int itemId)
    {
        try
        {
            File file = new File("build/preview-icons/" + itemId + ".png");
            if (!file.isFile())
            {
                return null;
            }
            BufferedImage source = ImageIO.read(file);
            if (source == null)
            {
                return null;
            }
            double scale = Math.min(1d, Math.min(36d / source.getWidth(), 32d / source.getHeight()));
            int width = Math.max(1, (int) Math.round(source.getWidth() * scale));
            int height = Math.max(1, (int) Math.round(source.getHeight() * scale));
            BufferedImage out = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = out.createGraphics();
            g.setRenderingHint(
                RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.drawImage(source, (36 - width) / 2, (32 - height) / 2, width, height, null);
            g.dispose();
            return out;
        }
        catch (Exception unavailable)
        {
            return null;
        }
    }
}

