        HudFrame freePlay = builder.update(LiveSnapshot.capture(free, NOW + 2L, null), f -> true, NOW + 2L);

        HudFrame grinding = builder.update(grind(0L, null), f -> true, NOW + 3L);
        assertTrue("a new Grind starts with a clean tray", grinding.rows.isEmpty());
        builder.tray().booked(receipt(NOW + 4L, TransactionType.LOOT, flow(1511, "Logs", 1L, 23)), NOW + 4L, false);
    }

    @Test
    public void anotherRunWithTheSameNameStartsWithACleanTrayAndMoments()
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", NOW);
        HudBuilder builder = new HudBuilder(config(true, 4), null);
        builder.update(LiveSnapshot.capture(engine, NOW, null), f -> true, NOW);
        engine.getActiveSession().addTransaction(receipt(NOW + 1L, TransactionType.LOOT,
            flow(536, "Dragon bones", 1L, 1_000_000)), 2_000, false);
        builder.tray().booked(receipt(NOW + 1L, TransactionType.LOOT, flow(536, "Dragon bones", 1L, 1_000_000)),
            NOW + 1L, false);
        HudFrame first = builder.update(LiveSnapshot.capture(engine, NOW + 2L, null), f -> true,
            NOW + 2L);
        assertEquals(1, first.rows.size());

        // The UI sees no intermediate Free play snapshot between the two same-name runs.
        engine.finishCustom(NOW + 3L);
        engine.startCustom("Vorkath", NOW + 4L);
        HudFrame next = builder.update(LiveSnapshot.capture(engine, NOW + 5L, null), f -> true,
            NOW + 5L);
        assertTrue("the old run's loot must not follow its name", next.rows.isEmpty());
        assertEquals("the old run's moment is gone", "", next.context);
    }
}

package com.gpmanager;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.ImageIO;
import net.runelite.api.Point;

import static com.gpmanager.HudTrayTest.flow;
import static com.gpmanager.HudTrayTest.receipt;

/** Paints HUD+ states over a game-coloured backdrop for `panelPreview` screenshots. */
public final class HudPreview
{
    private HudPreview()
    {
    }

    public static void write(File out) throws IOException
    {
        long now = SafeMath.now();
        emptyAndFiltered(out, now);
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
            @Override
            public boolean reducedMotion() { return true; }
        };
        Engine engine = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Item " + id, quantity, 50, quantity * 50)));
            return flows;
        }, new TransactionClassifier(), config);
        engine.startCustom("Vorkath", now - 2_400_000L);
        engine.getActiveSession().setProfitTargetGp(5_000_000L);

        HudBuilder builder = new HudBuilder(config, HudPreview::icon);
        HudTray tray = builder.tray();
        builder.update(LiveSnapshot.capture(engine, now - 3_000L, null), f -> true, now - 3_000L);
        add(engine, tray, now - 1_500L, flow(22124, "Superior dragon bones", 2L, 21_920));
        add(engine, tray, now - 1_000L, flow(11286, "Draconic visage", 1L, 3_425_000));
        add(engine, tray, now - 500L, flow(1319, "Rune 2h sword", 1L, 37_900));
        builder.update(LiveSnapshot.capture(engine, now, null), f -> true, now);
        canvas(out, "hud-grind.png", builder, config, 520, 260);

        // The same loot with no target: no bar, no label (owner live 2026-10-13).
        engine.getActiveSession().setProfitTargetGp(null);
        builder.update(LiveSnapshot.capture(engine, now + 1L, null), f -> true, now + 1L);
        canvas(out, "hud-loot.png", builder, config, 520, 260);

        // A looted Theatre of Blood: KC: 15, the scythe and rune loot (owner live 2026-10-13).
        Engine raid = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Item " + id, quantity, 50, quantity * 50)));
            return flows;
        }, new TransactionClassifier(), config);
        raid.startCustom("Theatre of Blood", now - 2_100_000L);
        HudBuilder raidBuilder = new HudBuilder(config, HudPreview::icon);
        HudTray raidTray = raidBuilder.tray();
        raidBuilder.update(LiveSnapshot.capture(raid, now - 1_200L, null), f -> true, now - 1_200L);
        for (int i = 0; i < 15; i++)
        {
            raidTray.kill("Verzik Vitur", now - 1_000L + i, false);
        }
        // An update inside the streak records its base at the pre-chest net, so the heading can
        // show the Net per kill.
        raidBuilder.update(LiveSnapshot.capture(raid, now - 900L, null), f -> true, now - 900L);
        raidBuilder.interaction("Verzik Vitur", true);
        add(raid, raidTray, now - 300L, flow(22486, "Scythe of vitur", 1L, 1_219_300_000));
        add(raid, raidTray, now - 200L, flow(565, "Blood rune", 56L, 339));
        raidBuilder.update(LiveSnapshot.capture(raid, now, null), f -> true, now);
        canvas(out, "hud-raid.png", raidBuilder, config, 520, 320);

        // Nothing new for a while: the tray folds and HUD+ rests at its narrow width.
        HudBuilder resting = new HudBuilder(config, HudPreview::icon);
        resting.update(LiveSnapshot.capture(engine, now + 60_000L, null), f -> true, now + 60_000L);
        BufferedImage rest = new BufferedImage(200, 80, BufferedImage.TYPE_INT_ARGB);
        Graphics2D r = rest.createGraphics();
        r.setColor(new Color(62, 74, 44));
        r.fillRect(0, 0, rest.getWidth(), rest.getHeight());
        r.translate(8, 8);
        new HudOverlay(resting, config).render(r);
        r.dispose();
        ImageIO.write(rest, "png", new File(out, "hud-rest.png"));

        // A time target in its final seconds: the countdown warns (owner live 2026-10-13).
        Engine timed = new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Item " + id, quantity, 50, quantity * 50)));
            return flows;
        }, new TransactionClassifier(), config);
        timed.startCustom("Vorkath", now - 61_000L);
        timed.getActiveSession().addTransaction(receipt(now - 500L, TransactionType.LOOT,
            flow(536, "Dragon bones", 2L, 3_930)), 2_000, false);
        timed.getActiveSession().setActiveTimeTargetMillis(60_000L, now);
        timed.getActiveSession().activeTimeTargetSetMillis = 9_000L;
        HudBuilder timedBuilder = new HudBuilder(config, HudPreview::icon);
        timedBuilder.update(LiveSnapshot.capture(timed, now, null), f -> true, now);
        canvas(out, "hud-time-warning.png", timedBuilder, config, 520, 160);
    }

    private static void emptyAndFiltered(File out, long now) throws IOException
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public boolean hudHideWhenIdle() { return false; }
            @Override
            public boolean reducedMotion() { return true; }
        };
        Engine engine = HudBuilderTest.engine();
        engine.ensureSession(now - 533_000L);
        HudBuilder builder = new HudBuilder(config, HudPreview::icon);
        builder.update(LiveSnapshot.capture(engine, now, null), f -> true, now);
        shot(out, "hud-empty.png", builder, config);
        builder.tray().booked(receipt(now, TransactionType.LOOT, flow(526, "Bones", 1L, 41)), now, false);
        engine.getActiveSession().addTransaction(receipt(now, TransactionType.LOOT, flow(526, "Bones", 1L, 41)), 2_000, false);
        builder.update(LiveSnapshot.capture(engine, now + 10L, null), f -> false, now + 10L);
        shot(out, "hud-filtered.png", builder, config);
        shot(out, "hud-narrow.png", builder, new GpManagerConfig()
        {
            @Override
            public int hudMaxWidth() { return 120; }
            @Override
            public boolean reducedMotion() { return true; }
        });
    }

    /** A full-size HUD+ canvas over the game-coloured backdrop. */
    private static void canvas(File out, String name, HudBuilder builder, GpManagerConfig config, int width, int height)
            throws IOException
    {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
        g.setColor(new Color(62, 74, 44));
        g.fillRect(0, 0, width, height);
        g.translate(8, 8);
        new HudOverlay(builder, config).render(g);
        g.dispose();
        ImageIO.write(image, "png", new File(out, name));
    }

    private static void shot(File out, String name, HudBuilder builder, GpManagerConfig config) throws IOException
    {        BufferedImage image = new BufferedImage(350, 240, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(62, 74, 44));
        g.fillRect(0, 0, image.getWidth(), image.getHeight());
        g.translate(8, 8);
        HudOverlay overlay = new HudOverlay(builder, config);
        Dimension size = overlay.render(g);
        g.dispose();
        ImageIO.write(image.getSubimage(0, 0, size.width + 16, size.height + 16), "png", new File(out, name));
    }

    private static void add(Engine engine, HudTray tray, long at, Flow item)
    {
        engine.getActiveSession().addTransaction(receipt(at, TransactionType.LOOT, item), 2_000, false);
        tray.booked(receipt(at, TransactionType.LOOT, item), at, false);
    }

    /** A stand-in sprite: RuneLite's item images are 36 x 32. */
    private static BufferedImage icon(int itemId, int quantity)
    {
        BufferedImage real = PreviewIcons.sprite(itemId);
        if (real != null)
        {
            return real;
        }
        BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(Color.getHSBColor((itemId % 97) / 97f, 0.5f, 0.8f));
        g.fillOval(6, 4, 24, 24);
        g.dispose();
        return image;
    }

}

package com.gpmanager;

import org.junit.Test;

import static com.gpmanager.HudBuilderTest.NOW;
import static com.gpmanager.HudBuilderTest.config;
import static com.gpmanager.HudBuilderTest.engine;
import static com.gpmanager.HudBuilderTest.grind;
import static com.gpmanager.HudTrayTest.flow;
import static com.gpmanager.HudTrayTest.receipt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** A factory reset leaves no HUD+ trace of the profile it replaced. */
public class HudResetPresentationTest
{
    @Test
    public void aFactoryResetStartsTheHudTripClean()
    {
        GpManagerConfig config = config(false, 4);
        HudBuilder builder = new HudBuilder(config, null);
        builder.update(grind(150_000L, null), f -> true, NOW);
        builder.tray().booked(receipt(NOW, TransactionType.LOOT, flow(11286, "Draconic visage", 1L, 2_500_000)),
            NOW, false);
        for (int k = 0; k < 3; k++)
        {
            builder.tray().kill("Vorkath", NOW + k, false);
        }
        builder.update(grind(50_000L, null), f -> true, NOW + 600_000L);
        assertTrue(!builder.tray().entries.isEmpty());

        builder.resetPresentation();

        Engine free = engine();
        free.ensureSession(NOW + 700_000L);
        HudFrame after = builder.update(LiveSnapshot.capture(free, NOW + 700_000L, null), f -> true,
            NOW + 700_000L);
        assertTrue("the reset tray is empty", after.rows.isEmpty());
        assertEquals("no trip chip survives", "", after.trip);
        assertEquals("no stale context line", "", after.context);
        assertFalse("no per-kill heading from before the reset", after.trayLabel.contains("/kill"));
        assertFalse(!builder.tray().entries.isEmpty());
    }

    @Test
    public void aFactoryResetHidesHudLikeANewInstallUntilPlay()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        Engine engine = engine();
        engine.ensureSession(NOW);
        builder.tray().booked(receipt(NOW, TransactionType.LOOT, flow(11286, "Draconic visage", 1L, 2_500_000)),
            NOW, false);
        assertTrue("the running profile shows",
            builder.update(LiveSnapshot.capture(engine, NOW + 10L, null), f -> true, NOW + 10L).visible);

        builder.resetPresentation();
        engine.resetData(NOW + 20L);
        assertFalse("after a reset HUD+ waits, as on a new install",
            builder.update(LiveSnapshot.capture(engine, NOW + 20L, null), f -> true, NOW + 20L).visible);

        engine.ensureSession(NOW + 30L);
        builder.tray().booked(receipt(NOW + 30L, TransactionType.LOOT, flow(536, "Dragon bones", 1L, 2_000)),
            NOW + 30L, false);
        HudFrame back = builder.update(LiveSnapshot.capture(engine, NOW + 30L, null), f -> true, NOW + 30L);
        assertTrue("play brings it back", back.visible);
        assertEquals("only the new loot", 1, back.rows.size());
    }
}

package com.gpmanager;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

import static com.gpmanager.HudBuilderTest.NOW;
import static com.gpmanager.HudBuilderTest.config;
import static com.gpmanager.HudBuilderTest.grind;
import static com.gpmanager.HudTrayTest.flow;
import static com.gpmanager.HudTrayTest.receipt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Auto width hugs content, stops at a ceiling, and shortens what does not fit. */
public class HudSizingTest
{
    private static final Graphics2D G = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();

    @Test
    public void fitShortensWithOneEllipsisAndLeavesShortTextAlone()
    {
        FontMetrics metrics = G.getFontMetrics(FontManager.getRunescapeFont());
        assertEquals("Logs ×4", HudOverlay.fit(metrics, "Logs ×4", 200));
        String cut = HudOverlay.fit(metrics, "Superior dragon bones ×2", 60);
        assertTrue(cut, cut.endsWith("…"));
        assertTrue(metrics.stringWidth(cut) <= 60);
    }

    /** Owner 1.2: a long name shortens before its count, and "(uncharged)" reads "(u)". */
    @Test
    public void aLongNameShortensButKeepsItsCount()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.tray().booked(receipt(NOW, TransactionType.LOOT, flow(21817, "Bracelet of ethereum (uncharged)", 2L, 90_000)), NOW, false);
        builder.tray().booked(receipt(NOW + 1L, TransactionType.LOOT, flow(1, "An extraordinarily long item name that "
            + "would never fit any sensible overlay", 3L, 10)), NOW + 1L, false);
        builder.update(grind(46L, null), f -> true, NOW + 10L);
        overlay.render(G);
        assertTrue(overlay.names[0], overlay.names[0].endsWith("… ×3"));
        assertTrue(overlay.names[1], overlay.names[1].startsWith("Bracelet of ethereum (u)"));
        assertTrue(overlay.names[1], overlay.names[1].endsWith(" ×2"));
    }

    @Test
    public void spritesCropToTheirVisiblePixels()
    {
        BufferedImage sprite = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        assertEquals("a sprite still loading keeps its whole canvas", new Rectangle(36, 32), Kit.visible(sprite));
        Graphics2D g = sprite.createGraphics();
        g.fillRect(10, 12, 4, 6);
        g.dispose();
        assertEquals(new Rectangle(10, 12, 4, 6), Kit.visible(sprite));
    }

    @Test
    public void autoWidthHugsContentAndStopsAtTheCeiling()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.update(grind(46L, null), f -> true, NOW);
        Dimension resting = overlay.render(G);
        assertTrue("short content leaves room below the ceiling", resting.width < config.hudMaxWidth());
        assertTrue(resting.width >= HudOverlay.MIN_WIDTH);

        builder.tray().booked(receipt(NOW, TransactionType.LOOT, flow(1, "An extraordinarily long item name that "
            + "would never fit any sensible overlay", 1L, 10)), NOW, false);
        builder.update(grind(46L, null), f -> true, NOW + 10L);
        assertEquals("long rows stop at Max width and shorten instead", config.hudMaxWidth(), overlay.render(G).width);
    }

    /** Owner 2026-09-28: GP/h sits beside "Net / target" whenever HUD+ has the room. */
    @Test
    public void theRateSharesTheNetLineWhenItFits()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.update(grind(-3_800L, 5_000_000L), f -> true, NOW);
        assertTrue("room to spare", overlay.render(G).width < config.hudMaxWidth());
        assertEquals("no line of its own", 0, overlay.moneyY[3]);
    }

    @Test
    public void tickingDigitsNeverWobbleTheWidth()
    {
        GpManagerConfig config = config(true, 4);
        HudBuilder builder = new HudBuilder(config, null);
        HudOverlay overlay = new HudOverlay(builder, config);
        builder.interaction("Ancient Wyvern of the Long Tail", true);
        Engine engine = HudBuilderTest.engine();
        engine.startCustom("Vorkath", NOW);
        builder.update(LiveSnapshot.capture(engine, NOW + 11_000L, null),
            f -> true, NOW + 11_000L);
        int narrowDigits = overlay.render(G).width;
        assertTrue("the title needs more than the minimum", narrowDigits > HudOverlay.MIN_WIDTH);
        builder.update(LiveSnapshot.capture(engine, NOW + 18_000L, null),
            f -> true, NOW + 18_000L);
        assertEquals(narrowDigits, overlay.render(G).width);
    }

    @Test
    public void emptyFreePlayFitsTimerAndRateOnOneLineAtEveryTextSize()
    {
        for (GpManagerConfig.TextSize textSize : GpManagerConfig.TextSize.values())
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public boolean hudHideWhenIdle() { return false; }
                @Override
                public TextSize hudTextSize() { return textSize; }
            };
            Engine engine = HudBuilderTest.engine();
            engine.ensureSession(NOW);
            HudBuilder builder = new HudBuilder(config, null);
            HudFrame snapshot = builder.update(LiveSnapshot.capture(engine, NOW + 533_000L, null),
                f -> true, NOW + 533_000L);
            assertEquals("8m53s", snapshot.timer);
            assertEquals("0/h", snapshot.rate);
            HudOverlay overlay = new HudOverlay(builder, config);
            Dimension rendered = overlay.render(G);
            assertTrue("empty " + textSize + " HUD fits below the old floor", rendered.width < 120);
            assertEquals("only one line remains", HudOverlay.PAD * 2 + G.getFontMetrics(overlay.bold()).getHeight(),
                rendered.height);
            FontMetrics metrics = G.getFontMetrics(overlay.body());
            assertTrue("timer and rate retain a gap", HudOverlay.PAD + 11 + HudOverlay.width(metrics, snapshot.timer) + 8
                <= rendered.width - HudOverlay.PAD - HudOverlay.width(metrics, snapshot.rate));
        }
    }

    /**
     * Owner live 2026-10-14: with the run's name off the HUD the rate rides the gem row, so the
     * old money-row wrap trigger is gone; the ceiling is the invariant that remains.
     */
    @Test
    public void aNarrowHudNeverDrawsWiderThanItsCeiling()
    {
        for (int ceiling : new int[] {320, 120})
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public int hudMaxWidth() { return ceiling; }
                @Override
                public boolean reducedMotion() { return true; }
            };
            HudBuilder builder = new HudBuilder(config, null);
            builder.tray().booked(receipt(NOW, TransactionType.LOOT,
                flow(1, "Whip", 1L, 1_500_000)), NOW, false);
            builder.update(grind(123_400_000L, null), f -> false, NOW + 10L);
            HudOverlay overlay = new HudOverlay(builder, config);
            Dimension rendered = overlay.render(G);
            assertTrue("the HUD never draws wider than its ceiling", rendered.width <= ceiling);
        }
    }

    /** Owner live 2026-10-14: the kill count survives even the narrowest HUD. */
    @Test
    public void theKillCountSurvivesNarrowCeilings()
    {
        for (int ceiling : new int[] {320, 100})
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override
                public int hudMaxWidth() { return ceiling; }
                @Override
                public boolean reducedMotion() { return true; }
            };
            HudBuilder builder = new HudBuilder(config, null);
            builder.update(grind(1_000L, null), f -> true, NOW - 1L);
            builder.interaction("Goblin", true);
            builder.tray().kill("Goblin", NOW - 1L, false);
            builder.update(grind(1_000L, null), f -> true, NOW);
            HudOverlay overlay = new HudOverlay(builder, config);
            overlay.render(G);
            if (ceiling == 320)
            {
                assertEquals("KC: 1", overlay.title);
            }
            else
            {
                assertTrue("the count survives narrow widths",
                    overlay.title.equals("KC: 1") || overlay.title.equals("1"));
                assertFalse("never an ellipsized count", overlay.title.contains("\u2026"));
            }
        }
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class HudTrayTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final long STAY = 5_000L;

    static Transaction receipt(long at, TransactionType type, Flow... flows)
    {
        return new Transaction(at, type, Context.LOOT, "", "Vorkath", true,
            Arrays.asList(flows), Confidence.CONFIRMED, "fixture", null);
    }

    static Flow flow(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    @Test
    public void eatingAndDrinkingNeverRideTheTray()
    {
        HudTray tray = new HudTray();
        tray.booked(receipt(T0, TransactionType.CONSUMPTION, flow(2434, "Prayer potion(4)", -1L, 9_800),
            flow(139, "Prayer potion(3)", 1L, 7_300)), T0, false);
        Transaction wine = receipt(T0 + 600L, TransactionType.CONSUMPTION, flow(1993, "Jug of wine", -1L, 5),
            flow(1935, "Jug", 1L, 1));
        wine.setActionKind(ActionKind.DRINK);
        tray.booked(wine, T0 + 600L, false);
        Transaction pie = receipt(T0 + 1_200L, TransactionType.CONSUMPTION, flow(2327, "Meat pie", -1L, 30),
            flow(2331, "Half a meat pie", 1L, 12));
        pie.setActionKind(ActionKind.EAT);
        tray.booked(pie, T0 + 1_200L, false);
        assertTrue("a sip, a drink or a bite is not a drop", tray.entries().isEmpty());
        assertFalse(tray.hasBooked());
    }

    /** Owner 2026-09-28: Greater Nechryael's death spawns never break its kill streak. */
    @Test
    public void spawnsNeverBreakTheKillStreak()
    {
        // The plugin never passes a spawn on: no header, engage or kill (owner: "Death spawn ×6").
        assertTrue(HudTray.minion("Death spawn"));
        assertTrue(HudTray.minion(" death SPAWN "));
        assertFalse(HudTray.minion("Greater Nechryael"));
        assertFalse(HudTray.minion(null));
        HudTray tray = new HudTray();
        tray.kill("Greater Nechryael", T0, false);
        tray.kill("Greater Nechryael", T0 + 20_000L, false);
        tray.kill("Greater Nechryael", T0 + 40_000L, false);
        assertEquals("G. Nechryael", tray.streak(T0 + 41_000L).getKey());
        assertEquals(3, (int) tray.streak(T0 + 41_000L).getValue());
        tray.kill("Abyssal demon", T0 + 60_000L, false);
        assertEquals("a kill of another NPC starts its own streak", 1, (int) tray.streak(T0 + 61_000L).getValue());
    }

    /** Owner 2026-09-28: a drop reads "Dropped", and a hidden item dropped stays off the tray. */
    @Test
