        g.fillRect(x, y, w, h);
        g.dispose();
        return image;
    }

    @Test
    public void aLargeSpriteIsCroppedScaledDownAndCentred()
    {
        BufferedImage fitted = Kit.fitIcon(sprite(2, 5, 30, 10), Kit.ICON_BOX);
        assertEquals(Kit.ICON_BOX, fitted.getWidth());
        assertEquals(Kit.ICON_BOX, fitted.getHeight());
        assertEquals("30 x 10 scales to 24 x 8, centred", new Rectangle(0, 8, 24, 8), Kit.visible(fitted));
    }

    @Test
    public void aSmallSpriteIsNeverBlownUp()
    {
        BufferedImage fitted = Kit.fitIcon(sprite(10, 12, 4, 6), Kit.ICON_BOX);
        assertEquals(new Rectangle(10, 9, 4, 6), Kit.visible(fitted));
    }

    @Test
    public void iconsOffLeavesTrayRowsWithoutSprites()
    {
        for (boolean show : new boolean[] {true, false})
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override public boolean hudHideWhenIdle() { return false; }
                @Override public boolean showItemIcons() { return show; }
            };
            HudBuilder builder = new HudBuilder(config, (id, quantity) -> sprite(2, 2, 20, 20));
            builder.update(HudBuilderTest.grind(1_000L, null), f -> true, NOW);
            builder.tray().booked(receipt(NOW + 1L, TransactionType.LOOT, flow(1420, "Iron mace", 1L, 42)), NOW + 1L, false);
            HudFrame s = builder.update(HudBuilderTest.grind(1_042L, null), f -> true, NOW + 2L);
            if (show) assertNotNull(s.rows.get(0).icon);
            else assertNull("item icons off", s.rows.get(0).icon);
        }
    }
}

package com.gpmanager;

import java.awt.BorderLayout;
import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.components.materialtabs.MaterialTab;

/** Test-side access to Shell state. */
public final class ShellProbe
{
    private ShellProbe()
    {
    }

    /** Tab labels in order. */
    public static String[] tabLabels(Shell shell)
    {
        String[] labels = new String[Shell.TABS.length];
        for (int i = 0; i < Shell.TABS.length; i++)
        {
            labels[i] = Shell.TABS[i][1];
        }
        return labels;
    }

    /** The selected tab's page id, as the tab strip shows it. */
    public static String selectedTab(Shell shell)
    {
        for (Map.Entry<String, MaterialTab> entry : shell.tabById.entrySet())
        {
            if (entry.getValue().isSelected())
            {
                return entry.getKey();
            }
        }
        return "";
    }

    public static void scrollCurrentToTop(Shell shell)
    {
        JScrollPane pane = shell.scrolls.get(shell.current);
        if (pane != null)
        {
            pane.getVerticalScrollBar().setValue(0);
            shell.scrollMemory.put(shell.current, 0);
        }
    }

    private static final String DEV_FOOTER = "gp-dev-footer";

    /** Dev builds only: a badge row under the notice line (null clears it). Production has no footer. */
    public static void setBadge(Shell shell, @Nullable JComponent badge)
    {
        JPanel footer = footer(shell);
        if (footer == null)
        {
            Component notice = ((BorderLayout) shell.getLayout()).getLayoutComponent(BorderLayout.SOUTH);
            JPanel bottom = new JPanel(new BorderLayout());
            bottom.setName(DEV_FOOTER);
            bottom.setOpaque(false);
            shell.remove(notice);
            bottom.add(notice, BorderLayout.NORTH);
            footer = new JPanel(new BorderLayout());
            footer.setOpaque(false);
            Kit.pad(footer, 2, Kit.GAP, 3, Kit.GAP);
            bottom.add(footer, BorderLayout.SOUTH);
            shell.add(bottom, BorderLayout.SOUTH);
        }
        footer.removeAll();
        if (badge != null)
        {
            footer.add(badge, BorderLayout.WEST);
        }
        footer.setVisible(badge != null);
        shell.revalidate();
    }

    @Nullable
    public static JComponent badge(Shell shell)
    {
        JPanel footer = footer(shell);
        return footer == null || footer.getComponentCount() == 0 ? null : (JComponent) footer.getComponent(0);
    }

    @Nullable
    private static JPanel footer(Shell shell)
    {
        Component south = ((BorderLayout) shell.getLayout()).getLayoutComponent(BorderLayout.SOUTH);
        return south != null && DEV_FOOTER.equals(south.getName())
            ? (JPanel) ((JPanel) south).getComponent(1) : null;
    }

    /** Presses the sheet button with this label, wherever it nests. */
    public static void pressSheet(Shell shell, String label)
    {
        for (JButton button : sheetButtons(shell))
        {
            if (label.equals(button.getText()))
            {
                button.doClick();
                return;
            }
        }
        throw new IllegalArgumentException("no sheet button " + label);
    }

    /** Types into the sheet's text field. */
    public static void typeSheet(Shell shell, String text)
    {
        javax.swing.JTextField field = firstField(shell.sheet);
        if (field == null) throw new IllegalArgumentException("no sheet field");
        field.setText(text);
    }

    /** The first text field in tree order, however deep its row nests it. */
    private static javax.swing.JTextField firstField(java.awt.Container parent)
    {
        for (java.awt.Component c : parent.getComponents())
        {
            if (c instanceof javax.swing.JTextField) return (javax.swing.JTextField) c;
            if (c instanceof java.awt.Container)
            {
                javax.swing.JTextField found = firstField((java.awt.Container) c);
                if (found != null) return found;
            }
        }
        return null;
    }

    /** The sheet's buttons, in tree order (rows, pager, choices). */
    public static List<JButton> sheetButtons(Shell shell)
    {
        List<JButton> out = new ArrayList<>();
        collectButtons(shell.sheet, out);
        return out;
    }

    /** The sheet's button texts, in tree order. */
    public static List<String> sheetButtonTexts(Shell shell)
    {
        List<String> out = new ArrayList<>();
        for (JButton button : sheetButtons(shell))
        {
            out.add(button.getText());
        }
        return out;
    }

    /** Presses the first enabled sheet button with this exact text, wherever it nests. */
    public static boolean pressSheetText(Shell shell, String text)
    {
        for (JButton button : sheetButtons(shell))
        {
            if (text.equals(button.getText()) && button.isEnabled())
            {
                button.doClick();
                return true;
            }
        }
        return false;
    }

    private static void collectButtons(Component root, List<JButton> out)
    {
        if (root instanceof JButton)
        {
            out.add((JButton) root);
        }
        if (root instanceof java.awt.Container)
        {
            for (Component child : ((java.awt.Container) root).getComponents())
            {
                collectButtons(child, out);
            }
        }
    }

    /** The sheet's checkbox whose label contains this text, or null. */
    @Nullable
    public static JCheckBox sheetCheckbox(Shell shell, String label)
    {
        for (java.awt.Component row : shell.sheet.getComponents())
        {
            if (row instanceof JPanel)
            {
                for (java.awt.Component c : ((JPanel) row).getComponents())
                {
                    if (c instanceof JCheckBox && ((JCheckBox) c).getText().contains(label))
                    {
                        return (JCheckBox) c;
                    }
                }
            }
        }
        return null;
    }

    public static String sheetTitle(Shell shell)
    {
        return shell.sheetTitle;
    }

    /** The notification text now showing, or "". */
    public static String noticeText(Shell shell)
    {
        return shell.notice.isVisible() ? shell.noticeText.getToolTipText() : "";
    }
}

package com.gpmanager;

import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

/** Test support: reads kit tables back as text, every page, without widening the plugin's API. */
public final class TableRows
{
    private TableRows()
    {
    }

    /** A plain row: key, name, quantity, value and tone (moved out of the plugin, 1.5.2 trim). */
    public static Table.Row row(String key, String name, String qty, String value, Kit.Tone tone)
    {
        return new Table.Row(key, null, name, qty, value, tone, "", "", false, null, java.util.Collections.emptyList());
    }

    /** Rows of every table under {@code root} whose title starts with {@code title}, as "name|qty|value|exact|tip". */
    public static List<String> of(Component root, String title)
    {
        List<String> texts = new ArrayList<>();
        for (Table table : tables(root, title))
        {
            for (Table.Row row : rows(table))
            {
                texts.add(row.name + "|" + row.qty + "|" + row.value + "|" + row.exact + "|" + row.tip);
            }
        }
        return texts;
    }

    /** Row keys of matching tables, every page. */
    public static List<String> keys(Component root, String title)
    {
        List<String> keys = new ArrayList<>();
        for (Table table : tables(root, title))
        {
            for (Table.Row row : rows(table))
            {
                keys.add(row.key);
            }
        }
        return keys;
    }

    /** Runs the open action of the first matching row whose key is {@code key}. */
    public static boolean open(Component root, String title, String key)
    {
        for (Table table : tables(root, title))
        {
            for (Table.Row row : rows(table))
            {
                if (row.key.equals(key) && row.open != null)
                {
                    row.open.run();
                    return true;
                }
            }
        }
        return false;
    }

    /** Row components actually built and visible in every table under {@code root}. */
    public static int visibleRows(Component root)
    {
        int count = 0;
        for (Table table : tables(root, ""))
        {
            if (table.body.isVisible())
            {
                for (Component child : table.body.getComponents())
                {
                    count += child instanceof javax.swing.JLabel ? 0 : 1;
                }
            }
        }
        return count;
    }

    public static List<Table> tables(Component root, String title)
    {
        List<Table> found = new ArrayList<>();
        collect(root, title, found);
        return found;
    }

    public static String title(Table table)
    {
        return ((javax.swing.JLabel) field(table, "title")).getText();
    }

    @SuppressWarnings("unchecked")
    private static List<Table.Row> rows(Table table)
    {
        return (List<Table.Row>) field(table, "rows");
    }

    private static void collect(Component component, String title, List<Table> found)
    {
        if (component instanceof Table && title((Table) component).startsWith(title))
        {
            found.add((Table) component);
        }
        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                collect(child, title, found);
            }
        }
    }

    private static Object field(Table table, String name)
    {
        try
        {
            Field field = Table.class.getDeclaredField(name);
            field.setAccessible(true);
            return field.get(table);
        }
        catch (ReflectiveOperationException e)
        {
            throw new AssertionError(e);
        }
    }
    /** Names of the rows on the page shown now. */
    public static List<String> names(Table table) {
        @SuppressWarnings("unchecked")
        List<Table.Row> drawn = (List<Table.Row>) field(table, "drawn");
        List<String> names = new ArrayList<>();
        for (Table.Row row : drawn == null ? java.util.Collections.<Table.Row>emptyList() : drawn) {
            names.add(row.name);
        }
        return names;
    }

    public static String pageText(Table table) {
        return (page(table) + 1) + "/" + table.pages();
    }

    public static int page(Table table) { return (Integer) field(table, "page"); }

}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TableTest
{
    private static List<Table.Row> rows(int count)
    {
        List<Table.Row> rows = new ArrayList<>();
        for (int i = 0; i < count; i++)
        {
            rows.add(TableRows.row("k" + i, "Item " + i, "×" + i, "+" + i, Kit.Tone.GAIN));
        }
        return rows;
    }

    @Test
    public void pagesClampAndReset()
    {
        Table table = new Table("GAINS").setRowsPerPage(10).setRows(rows(23));
        assertEquals(3, table.pages());
        assertEquals("1/3", table.pageLabel.getText());

        // Last page, then a shorter list: the page clamps instead of going blank.
        lastPage(table);
        assertEquals(2, TableRows.page(table));
        assertEquals(3, table.body.getComponentCount());
        table.setRows(rows(12));
        assertEquals(1, TableRows.page(table));
        assertEquals(2, table.body.getComponentCount());
        table.resetPage();
        assertEquals(0, TableRows.page(table));
        assertEquals(10, table.body.getComponentCount());
    }

    @Test
    public void aLongTitleEllipsizesInsteadOfWrappingOutOfTheHeader()
    {
        Table table = new Table("TRADE · 23 · long header title").setTotal("+168k", null).setRows(rows(3));
        table.setSize(232, 200);
        table.doLayout();
        table.header.doLayout();
        // A squeezed header (the pager joins the total): the title must not wrap below the line.
        table.left.setSize(60, Kit.HEADER);
        table.left.doLayout();
        assertTrue("the title stays on the header's single line",
            table.title.getY() + table.title.getHeight() <= Kit.HEADER);
    }

    @Test
    public void aPickerNeverReplacesTheTitle()
    {
        Table table =
            new Table("LOSSES · 11").setTotal("-33.3k", null).setRows(rows(3)).setPicker(new javax.swing.JButton("All"));
        table.setSize(232, 200);
        table.doLayout();
        table.header.doLayout();
        table.left.doLayout();
        assertTrue("the picker sits beside the title, not on top of it", table.title.getWidth() > 0);
    }

    private static void lastPage(Table table)
    {
        while (TableRows.page(table) < table.pages() - 1)
        {
            int before = TableRows.page(table);
            clickNext(table);
            assertTrue(TableRows.page(table) > before);
        }
    }

    private static void clickNext(Table table)
    {
        for (java.awt.Component c : table.pageLabel.getParent().getComponents())
        {
            if (c instanceof javax.swing.JButton && "›".equals(((javax.swing.JButton) c).getText()))
            {
                ((javax.swing.JButton) c).doClick();
                return;
            }
        }
        throw new AssertionError("no next button");
    }

    @Test
    public void rowsPerPageIsCappedAtFifteen()
    {
        Table table = new Table("RECENT").setRowsPerPage(40).setRows(rows(30));
        assertEquals(15, table.body.getComponentCount());
        assertEquals(2, table.pages());
    }

    @Test
    public void minRowsFixesBodyHeight()
    {
        Table table = new Table("COSTS").setRowsPerPage(5).setMinRows(5).setRows(rows(2));
        assertEquals(5 * Kit.ROW, table.body.getPreferredSize().height);
        table.setRows(rows(5));
        assertEquals(5 * Kit.ROW, table.body.getPreferredSize().height);
    }

    @Test
    public void emptyTableShowsItsText()
    {
        Table table = new Table("MARKET").setEmptyText("No settled sales").setRows(Collections.emptyList());
        assertEquals(1, table.body.getComponentCount());
        assertEquals("No settled sales", ((JLabel) table.body.getComponent(0)).getText());
        assertTrue(table.pageLabel.getParent() == null);
    }

    @Test
    public void foldHidesBodyOnlyWhenFoldable()
    {
        Table table = new Table("GAINS").setRows(rows(3));
        table.setFolded(true);
        assertFalse(table.isFolded());
        table.setFoldable(true).setFolded(true);
        assertTrue(table.isFolded());
        assertFalse(table.body.isVisible());
        table.setFolded(false);
        assertTrue(table.body.isVisible());
    }

    @Test
    public void rowCarriesTooltipsMenuAndFixedColumns()
    {
        int[] opened = {0};
        Table.Row row = new Table.Row("a", null, "Dragon bones", "×6", "+19.2k", Kit.Tone.GAIN,
            "Picked up", "+19,236 gp", true, () -> opened[0]++,
            Collections.singletonList(new Table.Menu("Correct…", () -> { })));
        Table table = new Table("GAINS").setRows(Collections.singletonList(row));
        JPanel line = (JPanel) table.body.getComponent(0);
        assertEquals("Picked up", line.getToolTipText());
        assertEquals(Kit.SELECTED, line.getBackground());
        assertNotNull(line.getComponentPopupMenu());
        JPanel numbers = (JPanel) line.getComponent(1);
        JLabel qty = (JLabel) numbers.getComponent(0);
        JLabel value = (JLabel) numbers.getComponent(1);
        int qtyWidth = qty.getPreferredSize().width;
        assertTrue("quantity column fits its text: " + qtyWidth, qtyWidth > 0 && qtyWidth <= 70);
        assertEquals(Kit.VALUE_WIDTH, value.getPreferredSize().width);
        assertEquals("+19,236 gp", value.getToolTipText());
        assertEquals(Kit.Tone.GAIN.color, value.getForeground());
    }

    @Test
    public void iconTablesUseIconHeightRowsAndKeepNamesAligned()
    {
        javax.swing.ImageIcon icon = new javax.swing.ImageIcon(
            new java.awt.image.BufferedImage(36, 32, java.awt.image.BufferedImage.TYPE_INT_ARGB));
        Table table = new Table("RECENT").setRows(java.util.Arrays.asList(
            new Table.Row("a", icon, "Oak plank", "", "+4.9k", Kit.Tone.GAIN, "", "", false, null, null),
            TableRows.row("b", "Coins", "", "+10", Kit.Tone.GAIN)));
        assertEquals(2 * Kit.ICON_ROW, table.body.getPreferredSize().height);
        for (java.awt.Component row : table.body.getComponents())
        {
            JPanel line = (JPanel) row;
            assertEquals(Kit.ICON_ROW, line.getPreferredSize().height);
            assertEquals("every row keeps the icon slot", Kit.ICON_WIDTH,
                line.getComponent(0).getPreferredSize().width);
            JPanel numbers = (JPanel) line.getComponent(2);
            assertEquals("no quantity column when no row has one", 1, numbers.getComponentCount());
        }
    }

    @Test
    public void fillFitsRowsToTheRoomLeft()
    {
        assertEquals(3, Table.fits(10, Kit.ICON_ROW));
        assertEquals(10, Table.fits(10 * Kit.ICON_ROW + 5, Kit.ICON_ROW));
        assertEquals(15, Table.fits(2_000, Kit.ROW));
    }

    @Test
    public void unchangedPageIsNotRebuilt()
    {
        Table table = new Table("GAINS").setRows(rows(3));
        java.awt.Component first = table.body.getComponent(0);
        table.setRows(rows(3));
        assertTrue(first == table.body.getComponent(0));
    }

    @Test
    public void toneFollowsCategory()
    {
        assertEquals(Kit.Tone.GAIN, Kit.Tone.of(Contribution.Category.GAIN));
        assertEquals(Kit.Tone.SUPPLY, Kit.Tone.of(Contribution.Category.SUPPLY));
        assertEquals(Kit.Tone.MARKET, Kit.Tone.of(Contribution.Category.MARKET));
        assertEquals(Kit.Tone.DIM, Kit.Tone.of(null));
    }

    @Test
    public void keyValueAddsFixedLines()
    {
        KeyValue kv = new KeyValue("WHY").put("How", "Charges used", Kit.Tone.PLAIN)
            .put("Net effect", "−24.2k", Kit.Tone.SUPPLY, "−24,190 gp");
        assertEquals(2, kv.lines());
        assertEquals(0, kv.clear().lines());
    }


    private static void collect(java.awt.Container root, List<String> texts)
    {
        for (java.awt.Component child : root.getComponents())
        {
            if (child instanceof JLabel)
            {
                texts.add(((JLabel) child).getText());
            }
            if (child instanceof java.awt.Container)
            {
                collect((java.awt.Container) child, texts);
            }
        }
    }
}

package com.gpmanager;

import com.gpmanager.Semantics.Receipt;
import java.awt.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.*;
import javax.swing.JPopupMenu;

/** Test-side access to LedgerPage state; moved out of production to keep the plugin small. */
public final class LedgerPageProbe
{

    /** The page's current read model. */
    public static LedgerData data(LedgerPage page)
    {
        return page.data;
    }
    private LedgerPageProbe()
    {
    }

    /** OVERVIEW, RECEIPTS (a group's list) or EXACT (a receipt selected under it). */
    public static String drill(LedgerPage p)
    {
        return p.data == null || p.data.detail == null || p.detail.getComponentCount() == 0 ? "OVERVIEW"
            : p.data.detail.exact != null ? "EXACT" : "RECEIPTS";
    }

    /** The selected receipt's Correct ▾ menu labels, in order. */
    public static List<String> correctMenu(LedgerPage p)
    {
        List<String> labels = new ArrayList<>();
        if (p.data != null && p.data.detail != null && p.data.detail.exact != null)
        {
            for (Component item : p.correctMenu(p.data.detail.exact).getComponents())
            {
                labels.add(((JMenuItem) item).getText());
            }
        }
        return labels;
    }

    /** Runs one entry of the selected receipt's Correct ▾ menu. */
    public static void chooseCorrection(LedgerPage p, String label)
    {
        for (Component item : p.correctMenu(p.data.detail.exact).getComponents())
        {
            if (((JMenuItem) item).getText().equals(label))
            {
                ((JMenuItem) item).doClick();
            }
        }
    }

    /**
     * The one effective Net contribution of a booked settlement, as the old proof worded it;
     * {@code corrected} is the receipt's own correction state, as the Ledger passes it.
     */
    public static String netContributionText(MarketRows.Row market, boolean corrected)
    {
        if (!market.realizedResultCorrectionAware)
        {
            return "0 · not counted";
        }
        if (corrected)
        {
            return Fmt.exactSigned(market.realizedResultGp) + " gp · corrected";
        }
        if (market.knownCostOnly)
        {
            return Fmt.exactSigned(market.realizedResultGp) + " gp · GE tax";
        }
        boolean knownResult = market.coverage != MarketRows.Coverage.FULLY_UNKNOWN
            || market.manualFinancialResult;
        return knownResult && market.settledQty > 0L
            ? Fmt.exactSigned(market.realizedResultGp) + " gp · Result"
            : "0 · not counted";
    }

    /** One rendered Market receipt row as "title|sub|value". */
    public static String marketReceiptRowText(Receipt receipt, long capturedAt)
    {
        boolean realized = MarketText.receiptRealized(receipt);
        return MarketText.receiptTitle(receipt) + "|" + MarketText.receiptSub(receipt, capturedAt) + "|"
            + (realized ? Fmt.exactSigned(MarketText.receiptPrimary(receipt)) + " gp"
                : MarketText.stateWord(receipt.marketSettlement));
    }


    public static List<String> overviewRows(LedgerPage p, LedgerPageProbe.FinancialTable table)
    {
        return p.data == null || p.data.detail != null ? Collections.emptyList() : TableRows.names(axd(p, table));
    }

    public static String overviewPageLabel(LedgerPage p, LedgerPageProbe.FinancialTable table)
    {
        return p.data == null || p.data.detail != null ? "" : TableRows.pageText(axd(p, table));
    }

    public static void toggleTable(LedgerPage p, LedgerPageProbe.FinancialTable table)
    {
        axd(p, table).setFolded(!axd(p, table).isFolded());
    }

    public static void toggleCorrected(LedgerPage p)
    {
        p.showCorrected = !p.showCorrected;
        if (p.data != null)
        {
            p.apply(p.data);
        }
    }

    public static void clickReceipt(LedgerPage p, String transactionId)
    {
        if (p.data == null || p.data.detail == null)
        {
            return;
        }
        if (p.data.detail.group.market)
        {
            for (Receipt receipt : p.data.detail.receipts)
            {
                if (receipt.transactionId.equals(transactionId))
                {
                    p.clickReceipt(receipt.transactionId, receipt.contributionId);
                    return;
                }
            }
            return;
        }
        for (LedgerData.Card card : LedgerData.cards(p.data.detail.group))
        {
            if (card.transactionId.equals(transactionId))
            {
                p.clickReceipt(card.transactionId, card.contributionId);
                return;
            }
        }
    }

    public static List<String> receiptCardTransactionIds(LedgerPage p)
    {
        List<String> ids = new ArrayList<>();
        if (!"OVERVIEW".equals(drill(p)))
        {
            if (p.data.detail.group.market)
            {
                for (Receipt receipt : p.data.detail.receipts)
                {
                    if (!ids.contains(receipt.transactionId))
                    {
                        ids.add(receipt.transactionId);
                    }
                }
            }
            else
            {
                for (LedgerData.Card card : LedgerData.cards(p.data.detail.group))
                {
                    ids.add(card.transactionId);
                }
            }
        }
        return ids;
    }

    public static List<String> detailReceiptRowTexts(LedgerPage p)
    {
        List<String> texts = new ArrayList<>();
        if ("OVERVIEW".equals(drill(p)))
        {
            return texts;
        }
        Semantics.Group group = p.data.detail.group;
        if (group.market)
        {
            for (Receipt receipt : p.data.detail.receipts)
            {
                texts.add(marketReceiptRowText(receipt, p.data.capturedAt));
            }
            return texts;
        }
        for (LedgerData.Card card : LedgerData.cards(group))
        {
            texts.add(group.primaryName + "|" + card.summaryText() + "|"
                + (card.incomplete ? "—" : Fmt.exactSigned(card.value) + " gp"));
        }
        return texts;
    }

    /** The detail's one Back: straight to the Ledger overview. */
    public static void back(LedgerPage p)
    {
        p.actions.selectionChanged(null, null, null);
    }

    public static void preview(LedgerPage p, LedgerData.CorrectionPreview preview, Correction correction)
    {
        p.pendingPreview = preview;
        p.pendingCorrection = correction;
        p.pendingTransaction = p.data == null || p.data.detail == null || p.data.detail.exact == null ? null
            : p.data.detail.exact.transactionId;
    }

    public static void select(LedgerPage p, String transactionId)
    {
        p.actions.selectionChanged(transactionId == null || transactionId.isEmpty() ? null : transactionId, null, null);
    }

    public static String marketRowSemantics(LedgerPage p, String groupId)
    {
        for (Semantics.Group group : p.data == null ? Collections.<Semantics.Group>emptyList()
            : p.data.market.groups)
        {
            if (group.semanticGroupId.equals(groupId))
            {
                return Fmt.signed(MarketText.marketPrimary(p.data, group)) + "|" + MarketText.marketLead(p.data, group);
            }
        }
        return "";
    }

    public static JPopupMenu reviewMenu(LedgerPage p, ReviewRow row)
    {
        JPopupMenu menu = new JPopupMenu();
        for (Decision decision : Decision.values())
        {
            if (row.validDecisions.contains(decision))
            {
                menu.add(Kit.item(LedgerPage.reviewLabel(decision), () -> p.actions.decide(row.transactionId, decision)));
            }
        }
        return menu;
    }

    public static List<String> detailTexts(LedgerPage p)
    {
        List<String> texts = new ArrayList<>();
        walk(p.detail, texts, false);
        return texts;
    }

    public static List<String> detailTooltips(LedgerPage p)
    {
        List<String> tips = new ArrayList<>();
        walk(p.detail, tips, true);
        return tips;
    }
    public enum FinancialTable { GAINS, COSTS, MARKET }
    private static Table axd(LedgerPage p, FinancialTable table) {
        return table == FinancialTable.GAINS ? p.gains : table == FinancialTable.MARKET ? p.market : p.costs;
    }

    static void walk(Component component, List<String> out, boolean tips) {
        String text = tips ? component instanceof JComponent ? ((JComponent) component).getToolTipText() : null
            : component instanceof JLabel ? ((JLabel) component).getText() : null;
        if (text != null && !text.isEmpty()) {
            out.add(text);
        }
        if (component instanceof Container) {
            for (Component child : ((Container) component).getComponents()) {
                walk(child, out, tips);
            }
        }
    }
}

