        assertNull("without a bond price there is no Bond pick", button(form, "Bond"));
        assertNotNull("10m keeps the rows aligned", button(form, "10m"));
    }

    @Test
    public void offClearsAndExistingTargetsReadBack()
    {
        JPanel form = GrindsController.grindForm(null, 5_000_000L, 3L * 3_600_000L);
        assertEquals("5m", net(form).getText());
        assertEquals("3h", ((JTextField) form.getClientProperty("timeField")).getText());
        Color lit = button(form, "5m").getForeground();
        assertEquals(Kit.ACCENT, lit);
        button(form, "Clear").doClick();
        assertEquals("", net(form).getText());
    }

    @Test
    public void readableTargetsParseBackExactly()
    {
        for (long gp : new long[] {750_000L, 1_000_000L, 9_120_000L, 10_000_000L, 9_120_345L, 1_234L,
            1_000_000_000L, 2_500_000_000L, 1_005_000_000L})
        {
            assertEquals(gp, GrindsData.parseNet(Fmt.targetNet(gp)));
        }
        assertEquals("the 1b pick lights", "1b", Fmt.targetNet(1_000_000_000L));
        for (long minutes : new long[] {30L, 60L, 90L, 180L, 1_590L})
        {
            assertEquals(minutes * 60_000L, GrindsData.parseTime(Fmt.targetTime(minutes * 60_000L)));
        }
    }

    private static JTextField net(JPanel form)
    {
        return (JTextField) form.getClientProperty("netField");
    }

    /** The first pick with this text; the picks sit in a row of their own. */
    private static JButton button(Container parent, String text)
    {
        for (Component c : parent.getComponents())
        {
            if (c instanceof JButton && text.equals(((JButton) c).getText())) return (JButton) c;
            if (c instanceof Container)
            {
                JButton found = button((Container) c, text);
                if (found != null) return found;
            }
        }
        return null;
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Owner 2026-10-01 (F28): a resume shows CALIBRATING for ~2.5s; bookings never wait. */
public class CalibratingCueTest
{
    private static final long NOW = 1_700_000_000_000L;

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
    }

    @Test
    public void aResumeArmsTheCueAndItExpires()
    {
        Engine engine = engine();
        engine.ensureSession(NOW);
        assertFalse("a plain start alone arms nothing", engine.calibrating(NOW + 100L));

        engine.getActiveSession().pause(NOW + 1_000L, PauseReason.IDLE);
        assertTrue(engine.resume(NOW + 2_000L, PauseReason.IDLE));
        assertTrue("the cue is up right after resume", engine.calibrating(NOW + 2_100L));
        assertFalse("the cue clears after 2.5s", engine.calibrating(NOW + 4_600L));
    }

    @Test
    public void autoStartAlsoArmsTheCue()
    {
        Engine engine = engine();
        assertTrue(engine.autoStart(NOW));
        assertTrue(engine.calibrating(NOW + 100L));
        assertFalse(engine.calibrating(NOW + 2_600L));
    }

    @Test
    public void liveShowsTheWordAndTheHudItsContextLineUntilItExpires()
    {
        Engine engine = engine();
        engine.startCustom("Vorkath", NOW);
        engine.getActiveSession().pause(NOW + 1_000L, PauseReason.IDLE);
        engine.resume(NOW + 2_000L, PauseReason.IDLE);

        LiveSnapshot during = LiveSnapshot.capture(engine, NOW + 2_500L, null);
        assertTrue(during.calibrating);
        assertEquals("CALIBRATING", LivePage.wordOf(during));
        HudBuilder builder = new HudBuilder(new GpManagerConfig() {}, null);
        assertEquals("Calibrating\u2026", builder.update(during, f -> true, NOW + 2_500L).context);

        LiveSnapshot after = LiveSnapshot.capture(engine, NOW + 5_000L, null);
        assertFalse(after.calibrating);
        assertEquals("plain running needs no status word", "", LivePage.wordOf(after));
        assertEquals("", builder.update(after, f -> true, NOW + 5_000L).context);
    }
}

package com.gpmanager;

import java.awt.Component;
import java.awt.Container;
import java.awt.Window;
import javax.annotation.Nullable;
import javax.swing.JLabel;
import javax.swing.Timer;

/**
 * The tiny DEV build footer, attached by the dev launcher and the panel preview only. It lives
 * under src/test so the plugin itself carries no build-identity code; release builds never show it.
 * Presentation only: never financial, never persisted and never owner-scoped.
 */
public final class DevBadge
{
    private DevBadge()
    {
    }

    /** Development builds show the DEV marker; release builds leave the footer collapsed. */
    public static void apply(SidebarPanel panel, @Nullable BuildInfo info)
    {
        BuildInfo resolved = info == null ? BuildInfo.fallback() : info;
        String badge = resolved.badgeText();
        JLabel label = null;
        if (!badge.isEmpty())
        {
            label = Kit.label(badge, Kit.small(), Kit.OFF);
            label.setToolTipText(resolved.tooltipText());
            label.getAccessibleContext().setAccessibleName("Build identity");
            label.getAccessibleContext().setAccessibleDescription(resolved.tooltipText());
        }
        ShellProbe.setBadge(panel.shell, label);
    }

    /**
     * Dev launcher: RuneLite adds the sidebar panel when it is first opened (and again after a
     * plugin restart), so look for unbadged GP Manager panels once a second.
     */
    public static void attachWhenShown(BuildInfo info)
    {
        if (info.badgeText().isEmpty())
        {
            return;
        }
        new Timer(1_000, e ->
        {
            for (Window window : Window.getWindows())
            {
                badgeAll(window, info);
            }
        }).start();
    }

    private static void badgeAll(Component component, BuildInfo info)
    {
        if (component instanceof SidebarPanel)
        {
            SidebarPanel panel = (SidebarPanel) component;
            if (ShellProbe.badge(panel.shell) == null)
            {
                apply(panel, info);
            }
        }
        else if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                badgeAll(child, info);
            }
        }
    }
}

package com.gpmanager;

import java.awt.FontMetrics;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The development-build footer is tiny, honest, width-safe and absent in release builds. */
public class DevMarkerPresentationTest
{
    @Test
    public void developmentBadgeShowsVersionAndBuildIdentityAtRealWidth() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        onEdt(() ->
        {
            DevBadge.apply(panel, BuildInfo.of("1.2.0", "1.2.0-dev", "105",
                "2026-09-23T01:24:37Z", "2929696", "1.12.39", true));
            return null;
        });

        JLabel badge = onEdt(() -> SidebarPanelProbe.buildBadge(panel));
        assertNotNull("development builds must identify themselves", badge);
        assertEquals("DEV \u00b7 1.2.0 \u00b7 01:24Z", badge.getText());
        assertNotNull(ShellProbe.badge(panel.shell()));
        assertTrue("full identity belongs in the tooltip",
            badge.getToolTipText().contains("Version: 1.2.0-dev"));
        assertTrue(badge.getToolTipText().contains("Schema: 105"));
        assertTrue(badge.getToolTipText().contains("Built: 2026-09-23 01:24:37 UTC"));
        assertNotNull(badge.getAccessibleContext().getAccessibleDescription());
        FontMetrics metrics = new JLabel().getFontMetrics(badge.getFont());
        assertTrue("the badge must fit the production sidebar width",
            metrics.stringWidth(badge.getText()) <= 225 - 24);
    }

    @Test
    public void releaseBuildLeavesTheFooterCollapsed() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        onEdt(() ->
        {
            DevBadge.apply(panel, BuildInfo.of("1.0.0", "1.0.0", "104",
                "2026-09-23T01:24:37Z", "", "1.12.39", false));
            return null;
        });

        assertNull("release builds must not claim to be development", SidebarPanelProbe.buildBadge(panel));
        assertNull(ShellProbe.badge(panel.shell()));
    }

    @Test
    public void missingMetadataDegradesToTheBareDevelopmentMarker() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        onEdt(() ->
        {
            DevBadge.apply(panel, null);
            return null;
        });

        JLabel badge = onEdt(() -> SidebarPanelProbe.buildBadge(panel));
        assertNotNull("a broken optional resource must never hide the build", badge);
        assertEquals("DEV BUILD", badge.getText());
        assertTrue(badge.getToolTipText().contains("GP Manager Development Build"));
    }

    @Test
    public void buildBadgeNeverTouchesSessionTruth() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(new Transaction(
            now + 1L, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true,
            java.util.Arrays.asList(new Flow(385, "Shark", -1L, 950, -950L)),
            Confidence.CONFIRMED, "Exact cost fixture", null), 2_000, false);
        long net = engine.getMetrics(now + 2L).net;
        int receipts = engine.getActiveSession().getTransactions().size();

        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null));
        onEdt(() ->
        {
            DevBadge.apply(panel, BuildInfo.of("1.2.0", "1.2.0-dev", "105",
                "2026-09-23T01:24:37Z", "2929696", "1.12.39", true));
            SidebarPanelProbe.refresh(panel);
            return null;
        });

        assertNotNull(SidebarPanelProbe.buildBadge(panel));
        assertEquals("the build marker is presentation only", net, engine.getMetrics(now + 2L).net);
        assertEquals(receipts, engine.getActiveSession().getTransactions().size());
    }

    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        if (SwingUtilities.isEventDispatchThread()) return callable.call();
        AtomicReference<T> value = new AtomicReference<>();
        AtomicReference<Throwable> failure = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() ->
        {
            try { value.set(callable.call()); }
            catch (Throwable ex) { failure.set(ex); }
        });
        if (failure.get() != null) throw new AssertionError(failure.get());
        return value.get();
    }
}

