            cardTexts.stream().noneMatch(text -> text.matches(".*[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}.*")));

        assertEquals("the linked receipt opens under the list", "EXACT", onEdt(() -> LedgerPageProbe.drill(page)));
