    /** Owner 1.1: Split shows Keep, Others and the Net it leaves before anything changes. */
    @Test
    public void theSplitPreviewsItsNetFirstAndTheResultMatches() throws Exception
    {
        Fixture fixture = new Fixture();
        Transaction transaction = fixture.book(new Flow(536, "Dragon bones", 4L, 2_000, 8_000L));
        long before = fixture.engine.getMetrics(NOW + 2_000L).net;
        fixture.confirm = false;

        fixture.split(transaction.getId());
        fixture.type("1");
        fixture.press("OK");

        assertEquals("keep one of four", Arrays.asList(536L, 1L, 4L),
            Arrays.asList(fixture.pending[0], fixture.pending[1], fixture.pending[2]));
        assertEquals("the preview changes nothing", 4L, transaction.quantity(536, true));
        assertEquals(before - 6_000L, fixture.previewed.afterNet);

        onEdt(() ->
        {
            fixture.controller.applySplit(transaction.getId(), fixture.pending, fixture.previewed.revision);
            return null;
        });
        assertEquals(1L, transaction.quantity(536, true));
        assertEquals("the result is what the preview said", fixture.previewed.afterNet,
            fixture.engine.getMetrics(NOW + 2_000L).net);
    }

    @Test
    public void aBookingAfterThePreviewSplitsNothing() throws Exception
    {
        Fixture fixture = new Fixture();
        Transaction transaction = fixture.book(new Flow(536, "Dragon bones", 4L, 2_000, 8_000L));
        fixture.confirm = false;
        fixture.split(transaction.getId());
        fixture.type("1");
        fixture.press("OK");
        fixture.book(new Flow(995, "Coins", 10L, 1, 10L));

        onEdt(() ->
        {
            fixture.controller.applySplit(transaction.getId(), fixture.pending, fixture.previewed.revision);
            return null;
        });
        assertTrue(ShellProbe.noticeText(fixture.shell()).startsWith("Not split"));
        assertEquals(4L, transaction.quantity(536, true));
    }

    private static final class Fixture
    {
        final Engine engine;
        final SidebarPanel panel;
        final LedgerController controller;

        Fixture() throws Exception
        {
            this(new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
                new GpManagerConfig() {}));
        }

        Fixture(Engine engine) throws Exception
        {
            this.engine = engine;
            JsonCodec.bind(new com.google.gson.Gson());
            panel = onEdt(() -> new SidebarPanel(engine, new GpManagerConfig() {}, null, null, null));
            controller = new LedgerController(panel);
            engine.startCustom("Vorkath", NOW);
        }

        Shell shell()
        {
            return panel.shell();
        }

        Transaction book(Flow... flows)
        {
            Transaction transaction = new Transaction(NOW + 1_000L, TransactionType.LOOT, Context.LOOT, "", "Vorkath", true,
                Arrays.asList(flows), Confidence.CONFIRMED, "fixture", null);
            engine.getActiveSession().addTransaction(transaction, 2_000, false);
            return transaction;
        }

        LedgerData.CorrectionPreview previewed;
        long[] pending;
        boolean confirm = true;

        void split(String transactionId) throws Exception
        {
            onEdt(() ->
            {
                // Owner 1.1: the split previews first; this harness confirms at once.
                controller.split(transactionId, (split, preview) ->
                {
                    previewed = preview;
                    pending = split;
                    if (confirm) controller.applySplit(transactionId, split, preview.revision);
                });
                return null;
            });
        }

        void type(String text) throws Exception
        {
            onEdt(() ->
            {
                ShellProbe.typeSheet(panel.shell(), text);
                return null;
            });
        }

        void press(String label) throws Exception
        {
            onEdt(() ->
            {
                ShellProbe.pressSheet(panel.shell(), label);
                return null;
            });
        }

        void closeAndStartAnotherRun()
        {
            engine.finishCustom(NOW + 2_000L);
            engine.startCustom("Other", NOW + 3_000L);
        }
    }

    /** Refuses every split, so the controller's refusal feedback can be pinned. */
    private static final class RefusingEngine extends Engine
    {
        RefusingEngine()
        {
            super(deltas -> Collections.emptyList(), new TransactionClassifier(),
                new GpManagerConfig() {});
        }

        @Override
        synchronized boolean splitItem(String transactionId, int itemId, long keepQuantity, long now,
            String optionalNote)
        {
            return false;
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        Object[] result = new Object[1];
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result[0] = callable.call();
            }
            catch (Exception ex)
            {
                throw new RuntimeException(ex);
            }
        });
        return (T) result[0];
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.awt.Component;
import java.util.Collections;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-01 (F01): undo mutates the live run only. Historical and Today scopes
 * disable it, and a menu opened while Current cannot mutate after a scope or owner switch.
 */
public class LedgerUndoScopeTest
{
    static
    {
        JsonCodec.bind(new Gson());
    }

    private static final long NOW = 1_700_000_000_000L;

    @Test
    public void historicalAndTodayDisableUndoWhileCurrentEnablesIt()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        JPopupMenu current = fixture.page().moreMenu();
        assertTrue(undo(current, "Undo latest correction").isEnabled());
        assertTrue(undo(current, "Undo last change").isEnabled());
        assertTrue(undo(current, "Restore last undo").isEnabled());

        fixture.apply(LedgerData.Entry.current().withScope(LedgerData.Scope.HISTORY, "past-run", "Past run"));
        JPopupMenu historical = fixture.page().moreMenu();
        assertFalse(undo(historical, "Undo latest correction").isEnabled());
        assertFalse(undo(historical, "Undo last change").isEnabled());
        assertFalse(undo(historical, "Restore last undo").isEnabled());

        fixture.apply(LedgerData.Entry.current().withScope(LedgerData.Scope.TODAY, null, null));
        assertFalse(undo(fixture.page().moreMenu(), "Undo last change").isEnabled());
    }

    @Test
    public void aStaleMenuCannotMutateAfterAScopeSwitch()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        JMenuItem undoLast = undo(fixture.page().moreMenu(), "Undo last change");
        assertTrue(undoLast.isEnabled());

        fixture.apply(LedgerData.Entry.current().withScope(LedgerData.Scope.HISTORY, "past-run", "Past run"));
        undoLast.doClick();

        assertEquals("an open menu must not undo across a scope switch", 0, fixture.engine.lastChanges);
    }

    @Test
    public void currentScopeStillUndoesAllThreeOperations()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        undo(fixture.page().moreMenu(), "Undo latest correction").doClick();
        undo(fixture.page().moreMenu(), "Undo last change").doClick();
        undo(fixture.page().moreMenu(), "Restore last undo").doClick();

        assertEquals(1, fixture.engine.corrections);
        assertEquals(1, fixture.engine.lastChanges);
        assertEquals(1, fixture.engine.restores);
    }

    @Test
    public void anOwnerSwitchLeavesAnOpenMenuInert()
    {
        Fixture fixture = new Fixture();
        fixture.apply(LedgerData.Entry.current());
        JMenuItem undoLast = undo(fixture.page().moreMenu(), "Undo last change");

        fixture.engine.restoreProfile("profile-b", new SavedState(), NOW + 1_000L);
        undoLast.doClick();

        assertEquals("an open menu must not undo another owner's run", 0, fixture.engine.lastChanges);
    }

    private static JMenuItem undo(JPopupMenu menu, String text)
    {
        for (Component component : menu.getComponents())
        {
            if (component instanceof JMenuItem && text.equals(((JMenuItem) component).getText()))
            {
                return (JMenuItem) component;
            }
        }
        throw new AssertionError("missing menu item: " + text);
    }

    private static final class Fixture
    {
        final UndoSpy engine = new UndoSpy();
        final SidebarPanel panel;

        Fixture()
        {
            try
            {
                SidebarPanel[] holder = new SidebarPanel[1];
                SwingUtilities.invokeAndWait(() -> holder[0] = new SidebarPanel(engine, new GpManagerConfig() {}, null, null, null));
                panel = holder[0];
            }
            catch (Exception ex)
            {
                throw new AssertionError(ex);
            }
            engine.ensureSession(NOW);
        }

        LedgerPage page()
        {
            return panel.ledger;
        }

        void apply(LedgerData.Entry entry)
        {
            panel.ledgerEntry = entry;
            panel.ledger.apply(LedgerData.capture(engine, NOW + 10L, entry));
        }
    }

    /** Counts the engine mutations the controller would perform. */
    private static final class UndoSpy extends Engine
    {
        int corrections;
        int lastChanges;
        int restores;

        UndoSpy()
        {
            super(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
        }

        @Override
        synchronized boolean undoCorrection(long now)
        {
            corrections++;
            return true;
        }

        @Override
        synchronized Transaction undoTransaction()
        {
            lastChanges++;
            return null;
        }

        @Override
        synchronized Transaction restoreUndo()
        {
            restores++;
            return null;
        }
    }
}

