import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Live Recent Activity is rebuilt from the shared semantic projection as living groups. */
public class LiveSemanticGroupsTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int DEATH = 560;
    private static final int CHAOS = 562;
    private static final int WATER = 555;
    private static final int BLOOD = 565;

    @Test
    public void repeatedExactSpellUpdatesOneLiveRowAndBubbles()
    {
        Engine engine = session("Vorkath");
        engine.getActiveSession().addTransaction(exactCast(T0 + 1_000L, "Ice Barrage", 1, 1, 1), 2_000, false);
        engine.getActiveSession().addTransaction(exactCast(T0 + 2_000L, "Ice Barrage", 1, 1, 1), 2_000, false);
        engine.getActiveSession().addTransaction(exactCast(T0 + 3_000L, "Ice Barrage", 1, 1, 1), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 4_000L, LiveContext.NONE);

        assertEquals("repeated exact spells are one updating row", 1, snapshot.recent.size());
        LiveSnapshot.Recent row = snapshot.recent.get(0);
        assertEquals("Ice Barrage", row.name);
        assertEquals("the row counts the receipts it speaks for", 3, row.receipts);
        assertEquals(-540L, row.value);
        assertEquals("Cast \u00b7 \u00d73", LivePage.metaOf(row));

        engine.getActiveSession().addTransaction(exactCast(T0 + 5_000L, "Blood Barrage", 1, 1, 1), 2_000, false);
        LiveSnapshot bubbled = LiveSnapshot.capture(engine, T0 + 6_000L, LiveContext.NONE);
        assertEquals(2, bubbled.recent.size());
        assertEquals("the newest group bubbles to the top", "Blood Barrage", bubbled.recent.get(0).name);
        assertEquals("Ice Barrage", bubbled.recent.get(1).name);
        assertEquals(3, bubbled.recent.get(1).receipts);
    }

    @Test
    public void genericCastCompositionsStaySeparateAndGeneric()
    {
        Engine engine = session("Vorkath");
        engine.getActiveSession().addTransaction(genericCast(T0 + 1_000L, 1, 1, 1), 2_000, false);
        // 2/2/2 would be Ice Rush's exact cost (named since 2026-09-28); 3/3/3 is no spell's.
        engine.getActiveSession().addTransaction(genericCast(T0 + 2_000L, 3, 3, 3), 2_000, false);
        engine.getActiveSession().addTransaction(bloodGenericCast(T0 + 3_000L), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 4_000L, LiveContext.NONE);
        assertEquals("same normalised composition groups, a different one splits", 2, snapshot.recent.size());
        for (LiveSnapshot.Recent row : snapshot.recent)
        {
            assertEquals("generic casts never receive an inferred spell name", "Cast", row.name);
        }
        LiveSnapshot.Recent grouped = snapshot.recent.stream()
            .filter(row -> row.receipts == 2).findFirst().orElseThrow(AssertionError::new);
        assertEquals(-720L, grouped.value);
        assertEquals("3 rune types \u00b7 \u00d72", LivePage.metaOf(grouped));
    }

    @Test
    public void liveRecentStaysBoundedToOnePageOfSemanticRows()
    {
        Engine engine = session("Vorkath");
        for (int i = 0; i < LiveSnapshot.RECENT_ROWS + 2; i++)
        {
            engine.getActiveSession().addTransaction(
                gain(T0 + 1_000L + i * 1_000L, "Item " + i, 2_000 + i, 1L, 100, 100L), 2_000, false);
        }
        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 20_000L, LiveContext.NONE);

        assertEquals("the Live preview is bounded", LiveSnapshot.RECENT_ROWS, snapshot.recent.size());
        assertEquals("the newest rows are kept", "Item 16", snapshot.recent.get(0).name);
        assertEquals("Item 2", snapshot.recent.get(LiveSnapshot.RECENT_ROWS - 1).name);
    }

    @Test
    public void unpricedFinancialRowsAreNotReviewButCanonicalReviewStillIs()
    {
        Engine engine = session("Vorkath");
        engine.getActiveSession().addTransaction(unpricedGain(T0 + 1_000L, "Unidentified mineral", 8), 2_000, false);
        engine.getActiveSession().addTransaction(review(T0 + 2_000L, "Unknown rune", 777), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 3_000L, LiveContext.NONE);

        assertEquals("only the canonical review transaction needs a decision", 1, snapshot.reviewCount);
        LiveSnapshot.Recent unpriced = rowNamed(snapshot.recent, "Unidentified mineral");
        assertNotNull(unpriced);
        assertTrue("the unpriced financial row keeps its incomplete marker", unpriced.unpriced);
        assertFalse("an unpriced financial row is not a review decision", "review".equals(unpriced.tag));
        assertNull("an unpriced gain opens Gains, not a Costs view", unpriced.ledgerCostView);
        LiveSnapshot.Recent review = rowNamed(snapshot.recent, "Unknown rune");
        assertNotNull(review);
        assertEquals("review", review.tag);
        assertTrue(review.ledgerReview);
    }

    @Test
    public void measuredResourceRowsShowInRecentAndStayInTheLedgerChargesChip()
    {
        Engine engine = session("Vorkath");
        engine.getActiveSession().addTransaction(gain(T0 + 500L, "Older gain", 999, 1L, 50, 50L), 2_000, false);
        engine.getActiveSession().addTransaction(blowpipeSpend(T0 + 1_000L), 2_000, false);
        engine.getActiveSession().addTransaction(blowpipeSpend(T0 + 2_000L), 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 3_000L, LiveContext.NONE);

        // Owner 1.3.4: charge use shows in Recent like any row; the Ledger's Charges chip still
        // holds it.
        LiveSnapshot.Recent scales = rowNamed(snapshot.recent, "Zulrah's scales");
        assertNotNull("the scales charge row is listed now", scales);
        assertEquals(LedgerData.CostView.CHARGES, scales.ledgerCostView);
        assertNotNull("owner 1.1: darts are Supplies like arrows", rowNamed(snapshot.recent, "Dragon dart"));
        assertEquals("the darts, the scales and the gain are in Recent", 3, snapshot.recent.size());
        assertNotNull(rowNamed(snapshot.recent, "Older gain"));

        LedgerData ledger = LedgerData.capture(engine, T0 + 3_000L,
            new LedgerData.Entry(LedgerData.Scope.CURRENT_GRIND, null, null,
                LedgerData.CostView.CHARGES, "", null, null, null, null));
        assertEquals("only the scales live in Charges",
            1, ledger.costCounts[LedgerData.CostView.CHARGES.ordinal()]);
        assertEquals("the darts are Supplies", 1, ledger.costCounts[LedgerData.CostView.SUPPLIES.ordinal()]);
    }

    @Test
    public void exactSpellRowCarriesStableDeepLinkIdentity()
    {
        Engine engine = session("Vorkath");
        Transaction newest = exactCast(T0 + 2_000L, "Ice Barrage", 1, 1, 1);
        engine.getActiveSession().addTransaction(exactCast(T0 + 1_000L, "Ice Barrage", 1, 1, 1), 2_000, false);
        engine.getActiveSession().addTransaction(newest, 2_000, false);

        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 3_000L, LiveContext.NONE);
        LiveSnapshot.Recent row = snapshot.recent.get(0);

        assertEquals("the representative receipt is the newest one", newest.getId(), row.receiptId);
        assertNotNull(row.contributionId);
        LedgerData.Entry entry = LivePage.entryFor(row);
        assertEquals("deep links never smuggle a search string", "", entry.search);
        assertEquals(newest.getId(), entry.highlightTransactionId);
        LedgerData linked = LedgerData.capture(engine, T0 + 3_000L, entry);
        assertNotNull("the stable identity resolves to its group detail", linked.detail);
        assertTrue(linked.detail.group.containsTransaction(newest.getId()));
    }

    // ── fixtures ───────────────────────────────────────────────────────────────────────────────

    private static Engine session(String name)
    {
        Engine engine = PresentationLifecycleTest.engine();
        engine.startCustom(name, T0);
        return engine;
    }

    private static LiveSnapshot.Recent rowNamed(List<LiveSnapshot.Recent> rows, String name)
    {
        for (LiveSnapshot.Recent row : rows)
        {
            if (name.equals(row.name))
            {
                return row;
            }
        }
        return null;
    }

    private static Transaction exactCast(long at, String name, int deathQty, int chaosQty, int waterQty)
    {
        Transaction transaction = genericCast(at, deathQty, chaosQty, waterQty);
        transaction.setActionLabel(ActionLabel.of(name));
        return transaction;
    }

    private static Transaction genericCast(long at, int deathQty, int chaosQty, int waterQty)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                rune(DEATH, "Death rune", -deathQty, 100),
                rune(CHAOS, "Chaos rune", -chaosQty, 50),
                rune(WATER, "Water rune", -waterQty, 30)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setActionKind(ActionKind.CAST);
        return transaction;
    }

    private static Transaction bloodGenericCast(long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "", "Vorkath", true, Arrays.asList(
                rune(DEATH, "Death rune", -1L, 100),
                rune(BLOOD, "Blood rune", -1L, 200),
                rune(WATER, "Water rune", -1L, 30)),
            Confidence.CONFIRMED, "Exact fixture", null);
        transaction.setActionKind(ActionKind.CAST);
        return transaction;
    }

    private static Flow rune(int id, String name, long quantity, int unit)
    {
        return new Flow(id, name, quantity, unit, quantity * unit, PriceSource.GRAND_EXCHANGE);
    }

    private static Transaction blowpipeSpend(long at)
    {
        Transaction transaction = new Transaction(at, TransactionType.CONSUMPTION,
            Context.GENERIC, "Measured charge spend \u00b7 Toxic blowpipe", "Vorkath", true,
            Arrays.asList(
                new Flow(11230, "Dragon dart", -2L, 100, -200L, PriceSource.GRAND_EXCHANGE),
                new Flow(12934, "Zulrah's scales", -1L, 110, -110L, PriceSource.GRAND_EXCHANGE)),
            Confidence.CONFIRMED, "Measured Check difference for Toxic blowpipe.", null);
        transaction.setActionKind(ActionKind.FIRE);
        return transaction;
    }

    private static Transaction gain(long at, String name, int itemId, long quantity, int unitPrice, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value,
                PriceSource.GRAND_EXCHANGE)),
            Confidence.LIKELY, "Test gain", null);
    }

    private static Transaction unpricedGain(long at, String name, int itemId)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, 8L, 0, 0L, PriceSource.UNPRICED)),
            Confidence.LIKELY, "Unpriced test gain", null);
    }

    private static Transaction review(long at, String name, int itemId)
    {
        return new Transaction(at, TransactionType.UNCERTAIN, Context.GENERIC, "", "Vorkath",
            true, Collections.singletonList(new Flow(itemId, name, -1L, 0, 0L)),
            Confidence.UNCERTAIN, "Awaiting a decision", null);
    }
}

package com.gpmanager;

import com.gpmanager.GpManagerConfig.LootFilter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.WorldType;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner report 2026-09-28: drops showed "?" values. Each Display loot filter mode shows the right
 * rows, every shown drop keeps its price, and no mode changes Net.
 */
public class LootDisplayModesTest
{
    private static final long T0 = 1_700_000_000_000L;

    @Test
    public void everyLootDisplayModeKeepsDropValuesAndShowsItsRows()
    {
        // The Ground Items lists: Iron mace highlighted, Bones hidden, Onion seed on neither.
        LootPresentationFilterService service = new LootPresentationFilterService(
            new GroundItemsPrefs(true, "Iron mace", "Bones", false));
        Engine engine = PresentationLifecycleTest.engine();
        engine.startCustom("Guard", T0);
        book(engine, T0 + 1_000L, new Flow(1420, "Iron mace", 1, 52, 52L));
        book(engine, T0 + 2_000L, new Flow(526, "Bones", 4, 90, 360L));
        book(engine, T0 + 3_000L, new Flow(5319, "Onion seed", 4, 3, 12L));
        long net = engine.getMetrics(T0 + 4_000L).net;

        assertEquals(List.of("Onion seed", "Bones", "Iron mace"),
            shown(engine, service, LootFilter.ALL_ITEMS));
        assertEquals("Follow Ground Items hides the hidden list", List.of("Onion seed", "Iron mace"),
            shown(engine, service, LootFilter.FOLLOW_GROUND_ITEMS));
        assertEquals("Highlighted list only shows the highlighted list", List.of("Iron mace"),
            shown(engine, service, LootFilter.HIGHLIGHTED_LIST_ONLY));
        assertEquals("no display mode changes Net", net, engine.getMetrics(T0 + 5_000L).net);
        assertEquals(52L + 360L + 12L, net);
    }

    /** Ordinary main-game worlds, PvP and LMS included, price drops; only separate economies do not. */
    @Test
    public void mainGameWorldsPriceDrops()
    {
        for (WorldType flag : EnumSet.complementOf(EnumSet.of(WorldType.DEADMAN, WorldType.SEASONAL,
            WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD, WorldType.TOURNAMENT_WORLD, WorldType.NOSAVE_MODE)))
        {
            Valuation valuation = new Valuation(new GpManagerConfig() {}, id -> null,
                (id, active) -> 52, id -> false,
                Valuation.economyFor(EnumSet.of(WorldType.MEMBERS, flag)));
            Flow drop = valuation.value(Collections.singletonMap(1420, 1L), T0).get(0);
            assertEquals(flag + " prices drops", PriceSource.GRAND_EXCHANGE, drop.getPriceSource());
            assertEquals(52L, drop.valueDelta);
        }
    }

    private static List<String> shown(Engine engine, LootPresentationFilterService service,
        LootFilter mode)
    {
        RecentFilter filter = flow -> service.isFlowIncluded(flow, mode);
        LiveSnapshot snapshot = LiveSnapshot.capture(engine, T0 + 4_000L,
            new LiveContext(false, filter, 0L, PvpState.NONE, "", false, "", false));
        List<String> names = new ArrayList<>();
        for (LiveSnapshot.Recent row : snapshot.recent)
        {
            assertFalse(mode + ": " + row.name + " keeps its price", row.unpriced);
            assertTrue(mode + ": " + row.name + " shows a value", row.value > 0L);
            names.add(row.name);
        }
        return names;
    }

    private static void book(Engine engine, long at, Flow flow)
    {
        engine.getActiveSession().addTransaction(Tx.of(at, TransactionType.LOOT, Context.LOOT,
            "Loot from Guard", true, Collections.singletonList(flow)), 2_000, false);
    }
}

package com.gpmanager;

import java.util.Collections;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The current loot visibility settings are presentation-only: they change which Live rows
 * appear, never what was booked, and they never hide costs or unpriced gains.
 */
public class LootVisibilityPresentationTest
{
    @Test
    public void minimumDisplayedLootValueHidesCheapPricedGainsOnly() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(
            transaction(now + 1_000L, "Cheap bones", 1, TransactionType.GAIN, 2, 100, 200L), 2_000, false);
        engine.getActiveSession().addTransaction(
            transaction(now + 2_000L, "Valuable hide", 2, TransactionType.GAIN, 1, 5_000, 5_000L), 2_000, false);
        long net = engine.getMetrics(now + 3_000L).net;

        LiveSnapshot unfiltered = LiveSnapshot.capture(engine, now + 3_000L, LiveContext.NONE);
        assertEquals("both gains are visible with no minimum", 2, unfiltered.recent.size());

        LiveContext minimum = new LiveContext(false, null, 1_000L, PvpState.NONE, "", false, "", false);
        LiveSnapshot filtered = LiveSnapshot.capture(engine, now + 3_000L, minimum);
        assertEquals("the cheap gain is hidden from presentation", 1, filtered.recent.size());
        assertEquals("Valuable hide", filtered.recent.get(0).name);
        assertEquals("canonical net is untouched by presentation filtering", net,
            engine.getMetrics(now + 3_000L).net);
        assertEquals("the hidden receipt is still canonical session truth",
            2, engine.getActiveSession().getTransactions().size());
    }

    @Test
    public void minimumDisplayedLootValueNeverHidesCostsOrUnpricedGains() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(
            transaction(now + 1_000L, "Prayer potion(4)", 3, TransactionType.CONSUMPTION, -2, 9_800, -19_600L), 2_000, false);
        // Unit price 0: the price is unknown, so the minimum cannot judge it.
        engine.getActiveSession().addTransaction(
            transaction(now + 2_000L, "Unidentified mineral", 8, TransactionType.GAIN, 8, 0, 0L), 2_000, false);

        LiveContext minimum = new LiveContext(false, null, 1_000_000L, PvpState.NONE, "", false, "", false);
        LiveSnapshot filtered = LiveSnapshot.capture(engine, now + 3_000L, minimum);
        assertEquals("costs stay discoverable and unpriced gains stay reviewable", 2, filtered.recent.size());
        LiveSnapshot.Recent mineral = null;
        for (LiveSnapshot.Recent row : filtered.recent)
        {
            if ("Unidentified mineral".equals(row.name))
            {
                mineral = row;
            }
        }
        assertNotNull("the unpriced gain stays visible", mineral);
        assertTrue("the unpriced row keeps its unknown marker", mineral.unpriced);
    }

    @Test
    public void itemFilterHidesOnlyPresentationAndKeepsCanonicalTruth() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(
            transaction(now + 1_000L, "Vial", 1, TransactionType.GAIN, 3, 1, 3L), 2_000, false);
        engine.getActiveSession().addTransaction(
            transaction(now + 2_000L, "Dragon bones", 1, TransactionType.GAIN, 2, 3_200, 6_400L), 2_000, false);
        long net = engine.getMetrics(now + 3_000L).net;

        SidebarPanel panel = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            created.bindFilter(flow -> !"Vial".equals(flow.itemName));
            SidebarPanelProbe.refresh(created);
            return created;
        });
        LiveSnapshot snapshot = SidebarPanelProbe.live(panel);
        assertNotNull(snapshot);
        assertEquals("the filtered item is not rendered", 1, snapshot.recent.size());
        assertEquals("Dragon bones", snapshot.recent.get(0).name);
        assertEquals("the booked net is unchanged by the presentation filter", net, snapshot.net);
        assertTrue("the hidden receipt stays canonical", engine.getActiveSession().getTransactions().size() == 2);
    }

    @Test
    public void minimumValueSettingParsesPlainAndSuffixedForms() throws Exception
    {
        assertEquals(0L, Fmt.parseGp(null));
        assertEquals(0L, Fmt.parseGp(""));
        assertEquals(0L, Fmt.parseGp("abc"));
        assertEquals(0L, Fmt.parseGp("0"));
        assertEquals(3_000L, Fmt.parseGp("3000"));
        assertEquals(200_000L, Fmt.parseGp("200k"));
        assertEquals(1_500_000L, Fmt.parseGp("1.5m"));
        assertEquals(2_500L, Fmt.parseGp("2,500"));
        assertEquals(0L, Fmt.parseGp("-5k"));
    }

    @Test
    public void panelReadsTheCurrentMinimumSettingOnEveryRefresh() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(
            transaction(now + 1_000L, "Cheap bones", 1, TransactionType.GAIN, 2, 100, 200L), 2_000, false);

        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine, minimumConfig("500"), null, null, null));
        onEdt(() ->
        {
            SidebarPanelProbe.refresh(panel);
            return null;
        });
        assertTrue("a 500 gp minimum hides a 100 gp unit-price gain", SidebarPanelProbe.live(panel).recent.isEmpty());

        SidebarPanel open = onEdt(() -> new SidebarPanel(engine, minimumConfig("0"), null, null, null));
        onEdt(() ->
        {
            SidebarPanelProbe.refresh(open);
            return null;
        });
        assertFalse("no minimum shows the same booked gain", SidebarPanelProbe.live(open).recent.isEmpty());
    }

    private static GpManagerConfig minimumConfig(String minimum)
    {
        return new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }

            @Override
            public String minimumDisplayedLootValue()
            {
                return minimum;
            }
        };
    }

    private static Transaction transaction(long at, String name, int itemId, TransactionType type,
        long quantity, int unitPrice, long value)
    {
        return new Transaction(at, type, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value)),
            Confidence.LIKELY, "Test sample.", null);
    }

    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        AtomicReference<T> result = new AtomicReference<>();
        AtomicReference<Exception> failure = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result.set(callable.call());
            }
            catch (Exception ex)
            {
                failure.set(ex);
            }
        });
        if (failure.get() != null)
        {
            throw failure.get();
        }
        return result.get();
    }
}

package com.gpmanager;

import static com.gpmanager.TargetFreshStartTest.HOUR;
import static com.gpmanager.TargetFreshStartTest.coins;
import static com.gpmanager.TargetFreshStartTest.live;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Owner 1.5.2: Free play's Net milestone counts all of Free play; a notice says when it is crossed. */
public class MilestoneTest
{
    static LivePage page()
    {
        LivePage.Actions actions = (LivePage.Actions) java.lang.reflect.Proxy.newProxyInstance(
            LivePage.Actions.class.getClassLoader(), new Class<?>[] {LivePage.Actions.class},
            (proxy, method, args) -> method.getReturnType() == boolean.class ? false : null);
        return new LivePage(actions, id -> null);
    }

    @Test
    public void itCountsAllOfFreePlayWhileATargetCountsFresh()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 400_000_000L);
        assertTrue(engine.setMilestone(1_000_000_000L));
        engine.setTargets(5_000_000L, null, HOUR);
        LiveSnapshot live = live(engine, HOUR);
        assertEquals("the target counts fresh", 0L, live.net);
        assertEquals("the milestone counts all of Free play", 400_000_000L, live.runNet);
        assertFalse(live.milestoneReached());

        coins(engine, HOUR + 5L, 600_000_000L);
        assertTrue(live(engine, HOUR + 10L).milestoneReached());
    }

    @Test
    public void aGrindLeavesItAloneAndCannotSetIt()
    {
        Engine engine = TargetFreshStartTest.engine();
        engine.setMilestone(1_000_000_000L);
        engine.startCustom("Vorkath", HOUR);
        assertNull(live(engine, HOUR).milestone);
        assertFalse(engine.setMilestone(5_000_000_000L));
        assertEquals(Long.valueOf(1_000_000_000L), engine.getGeneralSession().milestoneGp);
    }

    /** Owner 1.5.2: no bar and no HUD+ line; one small notice when it is crossed while playing. */
    @Test
    public void crossingItShowsOneNoticeButNotAtLogin() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.ensureSession(now - HOUR);
        engine.setMilestone(1_000L);
        coins(engine, now - 10_000L, 600L);
        SidebarPanel panel = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            SidebarPanelProbe.refresh(created);
            return created;
        });
        assertFalse(ShellProbe.noticeText(panel.shell()).contains("Milestone"));
        coins(engine, now - 5_000L, 600L);
        assertTrue(onEdt(() ->
        {
            SidebarPanelProbe.refresh(panel);
            return ShellProbe.noticeText(panel.shell());
        }).startsWith("Milestone reached"));

        SidebarPanel login = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            SidebarPanelProbe.refresh(created);
            return created;
        });
        assertFalse("already reached at login: no notice",
            ShellProbe.noticeText(login.shell()).contains("Milestone"));
    }

    /** The HUD+ kill-streak line measures the whole run, so a target start never moves it. */
    @Test
    public void aTargetStartLeavesTheHudNetBaseWhole()
    {
        Engine engine = TargetFreshStartTest.engine();
        coins(engine, 5L, 1_000L);
        HudBuilder builder = new HudBuilder(HudBuilderTest.config(false, 4), null);
        builder.update(live(engine, 10L), f -> true, 10L);
        engine.setTargets(5_000_000L, null, 20L);
