/** Owner fencing, thread ownership and the presentation-never-books contract. */
public class PanelLifecycleTest
{
    @Test
    public void ownerScopeChangeDropsThePreviousOwnersMarks() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        String sessionId = engine.getActiveSession().getId();
        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null));

        panel.suspend();

        panel.resume();
        assertNotNull(SidebarPanelProbe.live(panel));
    }

    @Test
    public void captureIsAReadAndNeverBooks() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(Tx.of(now + 1_000L, null, TransactionType.GAIN,
            Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(1, "Dragon bones", 2, 3_200, 6_400L))), 2_000, false);
        long bookedNet = engine.getMetrics(now + 2_000L).net;

        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null));
        onEdt(() ->
        {
            SidebarPanelProbe.refresh(panel);
            SidebarPanelProbe.refresh(panel);
            return null;
        });

        assertEquals("repeated presentation capture leaves canonical net untouched",
            bookedNet, engine.getMetrics(now + 2_000L).net);
        assertNotNull(SidebarPanelProbe.live(panel));
        assertEquals("the restored hierarchy shows the live owner", "Vorkath", SidebarPanelProbe.live(panel).ownerLabel);
    }

    @Test
    public void repeatedRefreshesStayCoalescedAndKeepExactlyOneShell() throws Exception
    {
        SidebarPanel panel = onEdt(() -> new SidebarPanel(PresentationLifecycleTest.engine(),
            PresentationLifecycleTest.config(), null, null, null));
        for (int i = 0; i < 50; i++)
        {
            panel.refresh();
        }
        Thread.sleep(120L);
        onEdt(() ->
        {
            SidebarPanelProbe.refresh(panel);
            return null;
        });
        assertNotNull("repeated refreshes keep exactly one live presentation", SidebarPanelProbe.live(panel));
        assertEquals(3, railTabs(panel));
    }

    @Test
    public void neutralTransfersNeverFabricateAValue() throws Exception
    {
        Transaction neutral = Tx.of(System.currentTimeMillis(), null,
            TransactionType.TRANSFER, Context.TRANSFER, "Bank transfer", "Vorkath", true,
            Collections.singletonList(new Flow(995, "Coins", -1_000, 1, -1_000L)));
        LiveSnapshot.Recent row = LiveProbe.toRecent(neutral);
        assertNotNull(row);
        assertTrue("a transfer row is neutral", row.neutral);
        assertEquals("neutral rows carry the booked zero", 0L, row.value);
        assertFalse("a transfer is never marked unpriced", row.unpriced);
    }

    private static int railTabs(SidebarPanel panel)
    {
        return ShellProbe.tabLabels(panel.shell()).length;
    }

    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        AtomicReference<T> result = new AtomicReference<>();
        AtomicReference<Exception> failure = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result.set(callable.call());
            }
            catch (Exception ex)
            {
                failure.set(ex);
            }
        });
        if (failure.get() != null)
        {
            throw failure.get();
        }
        return result.get();
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Owner 2026-10-09: a sale collected while still in progress (1,300 of 1,927 revenant ether, then
 * 500, then the last 127) books one settlement per collect. Live shows them as the offer's one
 * market row with the running total and Result, never as a separate "Traded" item cost.
 */
public class PartialSaleRecentTest
{
    private static final int COINS = 995;
    private static final int ETHER = 21820;

    private final OfferSlots ledger = new OfferSlots();
    private final Map<Integer, Long> inventory = new HashMap<>(Map.of(COINS, 1_000_000L, ETHER, 1_927L));
    private final Engine engine = new Engine(deltas ->
    {
        List<Flow> flows = new ArrayList<>();
        deltas.forEach((id, quantity) -> flows.add(new Flow(id, id == COINS ? "Coins" : "Revenant ether", quantity,
            id == COINS ? 1 : 174, quantity * (id == COINS ? 1 : 174), id == COINS ? PriceSource.FACE_VALUE : PriceSource.GRAND_EXCHANGE)));
        return flows;
    }, new TransactionClassifier(), new GpManagerConfig()
    {
        @Override
        public int stabilizationTicks()
        {
            return 0;
        }
    });
    private long now = System.currentTimeMillis() - 600_000L;

    @Test
    public void aSaleCollectedInPartsIsOneMarketRowWithTheRunningResult()
    {
        engine.startCustom("Trading", now);
        engine.setBaseline(new ContainerSnapshot(new HashMap<>(inventory)));
        offer(SELLING, 0, 0);
        move(ETHER, -1_927L);

        offer(SELLING, 1_300, 226_200);
        collect(222_300L);
        check("first collect", 1_300L, 222_300L, -3_900L);

        offer(SELLING, 1_800, 313_200);
        collect(85_500L);
        check("second collect", 1_800L, 307_800L, -5_400L);

        offer(SELLING, 1_927, 335_298);
        offer(SOLD, 1_927, 335_298);
        collect(21_717L);
        offer(EMPTY, 0, 0);
        check("last collect", 1_927L, 329_517L, -5_781L);
        assertEquals("three settlements, one per collect", 3, engine.getActiveSession().getTransactions().size());
        assertEquals("only the tax is lost", -5_781L, engine.getMetrics(now).net);
    }

    private void check(String step, long quantity, long received, long result)
    {
        Map<String, MarketRows.Row> rows = new HashMap<>();
        for (MarketRows.Row row : engine.marketRows())
        {
            rows.put(row.presentationId, row);
            assertEquals(step + ": the Result adds every settlement", result, row.realizedResultGp);
        }
        List<LiveSnapshot.Recent> recent = LiveSnapshot.recentRows(engine.summary().view(engine.summary().scope(
            Collections.singletonList(engine.getActiveSession())), LiveContext.NONE::flowVisible), rows, null);
        assertEquals(step + ": one row, no separate Traded item cost", 1, recent.size());
        LiveSnapshot.Recent row = recent.get(0);
        assertTrue(step, row.market);
        assertEquals(step, quantity, row.quantity);
        assertEquals(step + ": the received cash so far", received, row.value);
    }

    private void offer(GrandExchangeOfferState state, int traded, int spent)
    {
        now += 1_000L;
        boolean empty = state == EMPTY;
        OfferSlots.Transition transition = ledger.observe(new OfferSlots.Snapshot(0, state, empty ? 0 : ETHER,
            empty ? 0 : 1_927, traded, empty ? 0 : 174, spent)).orElse(null);
        if (transition != null)
        {
            engine.noteGeOffer(transition, "Revenant ether", now);
        }
    }

    private void collect(long coins)
    {
        now += 3_000L;
        engine.noteGeCollect(now);
        move(COINS, coins);
    }

    private void move(int item, long delta)
    {
        inventory.merge(item, delta, Long::sum);
        inventory.values().removeIf(quantity -> quantity == 0L);
        now += 600L;
        engine.markDirty();
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now, null);
        engine.processIfDirty(new ContainerSnapshot(new HashMap<>(inventory)), now + 1L, null);
    }
}

package com.gpmanager;

import java.util.Collections;
import javax.swing.JButton;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Owner 2026-10-01 (F06): a save failure stays visible until the backend actually recovers. */
public class PersistentSaveStatusTest
{
    @Test
    public void aStickyFailureIgnoresTheTimerAndTextClicks() throws Exception
    {
        Fixture fixture = new Fixture();
        onEdt(() ->
        {
            fixture.shell.notifySticky("Data not saved", "disk full", "Retry", () -> { });
            assertTrue(fixture.shell.notice.isVisible());
            assertFalse("a failure has no auto-dismiss timer", fixture.shell.noticeTimer.isRunning());
            fixture.shell.noticeClicked();
            assertTrue("a text click does not dismiss a failure", fixture.shell.notice.isVisible());
            fixture.shell.tell("Saved as My Grind", "future defaults only", false);
            assertTrue("routine news never replaces a failure",
                ShellProbe.noticeText(fixture.shell).startsWith("Data not saved"));
            fixture.shell.clearSticky();
            assertFalse("recovery takes the failure down", fixture.shell.notice.isVisible());
            fixture.shell.tell("Saved as My Grind", "future defaults only", false);
            assertTrue("routine news flows again",
                ShellProbe.noticeText(fixture.shell).startsWith("Saved as My Grind"));
            return null;
        });
    }

    @Test
    public void retryRunsAndAPersistingFailureComesBack() throws Exception
    {
        Fixture fixture = new Fixture();
        boolean[] retried = {false};
        onEdt(() ->
        {
            fixture.shell.notifySticky("Data not saved", "disk full", "Retry", () -> retried[0] = true);
            ((JButton) fixture.shell.noticeAction.getComponent(0)).doClick();
            assertTrue("the retry action runs", retried[0]);
            assertFalse("the attempt hides the failure", fixture.shell.notice.isVisible());
            fixture.shell.notifySticky("Data not saved", "disk full", "Retry", () -> { });
            assertTrue("still failing means still visible", fixture.shell.notice.isVisible());
            assertFalse("and still no timer", fixture.shell.noticeTimer.isRunning());
            return null;
        });
    }

    @Test
    public void theSidebarFollowsTheBackendStatusUntilRecovery() throws Exception
    {
        FakePersist persist = new FakePersist();
        SidebarPanel panel = onEdt(() -> new SidebarPanel(engine(), new GpManagerConfig() {}, null, null, persist));
        Shell shell = panel.shell();
        onEdt(() ->
        {
            persist.status = new SaveStatus(SaveStatus.State.FAILED, "disk full", false, "");
            panel.showPersistenceWarning();
            assertTrue(shell.notice.isVisible());
            assertTrue(ShellProbe.noticeText(shell).startsWith("Data not saved"));
            panel.showPersistenceWarning();
            assertTrue("a repeated failing status stays up", shell.notice.isVisible());

            persist.status = new SaveStatus(SaveStatus.State.OK, "", false, "backup-2026");
            panel.showPersistenceWarning();
            assertTrue("recovery replaces it with the recovery note",
                ShellProbe.noticeText(shell).startsWith("Recovered from backup"));
            assertTrue("routine recovery has a timer", shell.noticeTimer.isRunning());

            persist.status = new SaveStatus(SaveStatus.State.FAILED, "disk full", false, "");
            panel.showPersistenceWarning();
            assertTrue(shell.notice.isVisible());
            panel.suspend();
            assertFalse("a profile switch drops the old profile's failure", shell.notice.isVisible());
            return null;
        });
    }

    private static Engine engine()
    {
        return new Engine(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
    }

    private static final class Fixture
    {
        final SidebarPanel panel;
        final Shell shell;

        Fixture() throws Exception
        {
            panel = onEdt(() -> new SidebarPanel(engine(), new GpManagerConfig() {}, null, null, null));
            shell = panel.shell();
        }
    }

    /** Returns the status the test chooses; the real writer is never involved. */
    private static final class FakePersist extends Persistence
    {
        SaveStatus status = SaveStatus.neverSaved();

        FakePersist()
        {
            super(null, null, null, null, null);
        }

        @Override
        SaveStatus saveStatus()
        {
            return status;
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        Object[] result = new Object[1];
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result[0] = callable.call();
            }
            catch (Exception ex)
            {
                throw new RuntimeException(ex);
            }
        });
        return (T) result[0];
    }
}

package com.gpmanager;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.ui.NavigationButton;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** One NavigationButton owner: no duplicates across disable/enable, and never a silent missing icon. */
public class PresentationLifecycleTest
{
    private final RecordingNavigation navigation = new RecordingNavigation();
    private final SidebarPanel panel = new SidebarPanel(engine(), config(), null, null, null);
    private final BufferedImage icon = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

    @Test
    public void realSidebarIconLoadsAndIsCarriedByTheButton()
    {
        BufferedImage loaded = NavButton.loadIcon();
        assertNotNull(loaded);
        assertTrue("the real bundled icon must load, not the placeholder",
            loaded.getWidth() > 16 && loaded.getHeight() > 16);

        NavButton lifecycle = new NavButton();
        assertTrue(lifecycle.install(navigation, panel, loaded));
        NavigationButton button = lifecycle.button();
        assertNotNull(button);
        assertNotNull("the button must carry the icon", button.getIcon());
        assertNotNull("the button must carry the panel", button.getPanel());
        assertEquals("GP Manager", button.getTooltip());
        assertEquals(5, button.getPriority());
    }

    @Test
    public void installIsIdempotentWhileInstalled()
    {
        NavButton lifecycle = new NavButton();
        assertTrue(lifecycle.install(navigation, panel, icon));
        assertNotNull(lifecycle.button());
        assertFalse("second install must not register a duplicate",
            lifecycle.install(navigation, panel, icon));
        assertEquals(1, navigation.adds.size());
    }

    @Test
    public void disableAndReenableNeverDuplicatesTheButton()
    {
        NavButton lifecycle = new NavButton();
        assertTrue(lifecycle.install(navigation, panel, icon));
        NavigationButton first = lifecycle.button();

        lifecycle.uninstall(navigation);
        assertNull(lifecycle.button());
        assertEquals(first, navigation.removes.get(0));

        assertTrue("re-enable installs exactly one fresh button",
            lifecycle.install(navigation, panel, icon));
        assertNotNull(lifecycle.button());
        assertEquals(2, navigation.adds.size());
        assertEquals(1, navigation.removes.size());
        lifecycle.uninstall(navigation);
        assertEquals(2, navigation.removes.size());
        assertNull(lifecycle.button());
    }

    @Test
    public void missingHostPanelOrIconDegradeWithoutRegistering()
    {
        NavButton lifecycle = new NavButton();
        assertFalse(lifecycle.install(null, panel, icon));
        assertFalse(lifecycle.install(navigation, null, icon));
        assertFalse(lifecycle.install(navigation, panel, null));
        assertNull(lifecycle.button());
        assertEquals(0, navigation.adds.size());
    }

    @Test
    public void toolbarAdapterIsNullSafe()
    {
        assertNull(NavButton.toolbarHost(null));
    }

    static GpManagerConfig config()
    {
        return new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
    }

    static Engine engine()
    {
        return new Engine(deltas ->
        {
            List<Flow> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Flow(id, "Item " + id, quantity, 50, quantity * 50)));
            return flows;
        }, new TransactionClassifier(), config());
    }

    static final class RecordingNavigation implements NavButton.NavigationHost
    {
        final List<NavigationButton> adds = new ArrayList<>();
        final List<NavigationButton> removes = new ArrayList<>();

        @Override
        public void add(NavigationButton button)
        {
            adds.add(button);
        }

        @Override
        public void remove(NavigationButton button)
        {
            removes.add(button);
        }
    }

    static List<Flow> flow(int itemId, String name, long quantity, int unitPrice, long value)
    {
        return Collections.singletonList(new Flow(itemId, name, quantity, unitPrice, value));
    }
}

