import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

/** A tab fills at once when shown, and an unchanged page is not re-read or rebuilt on the way back. */
public class TabSwitchTest
{
    @Test
    public void aShownTabFillsAtOnceAndAnUnchangedPageKeepsItsRows() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(Tx.of(now, TransactionType.LOOT, Context.GENERIC, "", true,
            Collections.singletonList(new Flow(536, "Dragon bones", 1, 2_000, 2_000L))), 2_000, false);
        SidebarPanel[] holder = new SidebarPanel[1];
        SwingUtilities.invokeAndWait(() ->
        {
            holder[0] = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            holder[0].active = true;
        });
        SidebarPanel panel = holder[0];

        SwingUtilities.invokeAndWait(() -> panel.shell().show(Shell.LEDGER));
        SwingUtilities.invokeAndWait(() -> { });
        LedgerData first = panel.ledger.data;
        assertNotNull("the Ledger fills when shown, without waiting for a game tick", first);

        SwingUtilities.invokeAndWait(() -> panel.shell().show(Shell.LIVE));
        SwingUtilities.invokeAndWait(() -> panel.shell().show(Shell.LEDGER));
        SwingUtilities.invokeAndWait(() -> { });
        assertSame("nothing changed: the Ledger keeps its rows", first, panel.ledger.data);

        engine.getActiveSession().addTransaction(Tx.of(now + 1_000L, TransactionType.LOOT, Context.GENERIC,
            "", true, Collections.singletonList(new Flow(536, "Dragon bones", 1, 2_000, 2_000L))), 2_000, false);
        SwingUtilities.invokeAndWait(() -> panel.shell().show(Shell.LIVE));
        SwingUtilities.invokeAndWait(() -> panel.shell().show(Shell.LEDGER));
        SwingUtilities.invokeAndWait(() -> { });
        assertNotSame("a new booking re-reads the Ledger", first, panel.ledger.data);
    }
}

package com.gpmanager;

import java.awt.Component;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;

/**
 * The per-game-tick pulse must not rebuild the sidebar. Rebuilding every 0.6 s replaced the rows
 * a Swing menu was anchored to (the owner's disappearing dropdowns) and the labels a reader was
 * walking. Values still update in place, and a real data change still rebuilds.
 */
public class TickRefreshStabilityTest
{
    @Test
    public void liveRowsSurviveTicksAndRebuildOnlyWhenTheDataChanges() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(gain(now + 1_000L, "Dragon bones", 536, 3_200L), 2_000, false);
        SidebarPanel panel = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            SidebarPanelProbe.refresh(created);
            return created;
        });
        List<Component> before = onEdt(() -> children(SidebarPanelProbe.livePage(panel).body()));

        for (int tick = 0; tick < 3; tick++)
        {
            panel.tick();
            flushEdt();
        }
        List<Component> afterTicks = onEdt(() -> children(SidebarPanelProbe.livePage(panel).body()));
        assertEquals(before.size(), afterTicks.size());
        for (int index = 0; index < before.size(); index++)
        {
            assertSame("tick " + index + " kept the same component", before.get(index), afterTicks.get(index));
        }

        engine.getActiveSession().addTransaction(gain(now + 2_000L, "Rune platebody", 1127, 38_000L), 2_000, false);
        panel.tick();
        flushEdt();
        List<Component> afterBooking = onEdt(() -> children(SidebarPanelProbe.livePage(panel).body()));
        assertNotEquals("a new booking rebuilds the recent rows", before, afterBooking);
    }

    @Test
    public void openLedgerIsNotRebuiltByTicksButIsByANewBooking() throws Exception
    {
        Engine engine = PresentationLifecycleTest.engine();
        long now = System.currentTimeMillis();
        engine.startCustom("Vorkath", now);
        engine.getActiveSession().addTransaction(gain(now + 1_000L, "Dragon bones", 536, 3_200L), 2_000, false);
        SidebarPanel panel = onEdt(() ->
        {
            SidebarPanel created = new SidebarPanel(engine, PresentationLifecycleTest.config(), null, null, null);
            SidebarPanelProbe.refresh(created);
            SidebarPanelProbe.openLedger(created, LedgerData.Entry.current());
            return created;
        });
        flushEdt();
        List<Component> before = onEdt(() -> children(SidebarPanelProbe.ledgerPage(panel).body()));

        panel.tick();
        flushEdt();
        panel.tick();
        flushEdt();
        List<Component> afterTicks = onEdt(() -> children(SidebarPanelProbe.ledgerPage(panel).body()));
        assertEquals("ticks never rebuild the open Ledger", before, afterTicks);

        engine.getActiveSession().addTransaction(gain(now + 2_000L, "Rune platebody", 1127, 38_000L), 2_000, false);
        panel.tick();
        flushEdt();
        List<Component> afterBooking = onEdt(() -> children(SidebarPanelProbe.ledgerPage(panel).body()));
        assertNotEquals("a new booking re-reads the Ledger", before, afterBooking);
    }

    private static Transaction gain(long at, String name, int itemId, long value)
    {
        return new Transaction(at, TransactionType.GAIN, Context.GENERIC, "", "Vorkath", true,
            Collections.singletonList(new Flow(itemId, name, 1L, (int) value, value)),
            Confidence.LIKELY, "Test sample.", null);
    }

    /** Every component under the body, depth first; a rebuilt row shows up as a new instance. */
    private static List<Component> children(JComponent body)
    {
        List<Component> out = new java.util.ArrayList<>();
        java.util.Deque<Component> stack = new java.util.ArrayDeque<>(Arrays.asList(body.getComponents()));
        while (!stack.isEmpty())
        {
            Component component = stack.pop();
            out.add(component);
            if (component instanceof java.awt.Container)
            {
                stack.addAll(Arrays.asList(((java.awt.Container) component).getComponents()));
            }
        }
        return out;
    }

    /** Run everything already queued on the EDT, including a drain the last call scheduled. */
    private static void flushEdt() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> { });
        SwingUtilities.invokeAndWait(() -> { });
    }

    private static <T> T onEdt(Callable<T> callable) throws Exception
    {
        AtomicReference<T> result = new AtomicReference<>();
        AtomicReference<Exception> failure = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result.set(callable.call());
            }
            catch (Exception ex)
            {
                failure.set(ex);
            }
        });
        if (failure.get() != null)
        {
            throw failure.get();
        }
        return result.get();
    }
}

